[Lem finite-n-uniform-renewal of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] By enlarging $n_0$ if necessary,
\begin{align}
 \sup_{n\geqslant n_0}\sup_{x\geqslant0} \mathcal{R}_n([x,x+1]) < \infty.
\end{align}
Moreover, for every bounded step function $\phi$ with compact support and every sequence $b_n\to\infty$,
\begin{align}
 \sup_{v\geqslant b_n}
 \abs{
 \int_{[0,v]} e^{-\alpha_n(v-u)}\phi(v-u)\mathcal{R}_n(\mathrm d u)
 -
 \frac1{\theta_n} \int_0^\infty e^{-\alpha_na}\phi(a)\,\mathrm d a
 }
 \to 0.
\end{align}

[Prop bdsumblo of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Take $C_1, C_2>0$.
Assume that $|k_\ell-N^{2/3}\mathbf k_\ell|<C_1$ and $|N_\ell-N+\boldsymbol{\tau}_\ell N^{2/3}|<C_1$ for each $N$ and $\ell\in\llbracket 1, m\rrbracket$.
Then there exists $C_3=C_3(C_1, C_2)$ such that
\begin{multline}   
\Bigg| 2^{-m}N^m \sum_{\vec\mathfrak b\in \{0,1\}^m} \prod_{\ell=1}^m (2\sqrt{N_\ell N})^{-k_\ell-\mathfrak b_\ell} \sum_{\substack{(\vec p,\vec\upsilon,\mathcal H)\in \mathscr L_\epsilon[\vec \mathfrak b]:\\ p^0,\mathcal H<C_2 N^{1/3},\delta<C_2}} \sum_{\vec r \in \mathcal L^{-1}(\vec p, \vec\upsilon, \mathcal H)}  w(\vec r) \\ - \int_{\substack{(\vec\mathbf p,  \vec\boldsymbol{\upsilon},\mathbf H)\in\mathscr K_\epsilon[\vec\mathbf k]:  \\ \mathbf p^0, \mathbf H, \boldsymbol{\delta} < C_2 }} \exp\left(\sum_{\ell=1}^{m-1}
(\boldsymbol{\tau}_\ell-\boldsymbol{\tau}_{\ell+1}) \mathbf H(\mathbf Q_\ell)/2 \right)\mathbf I_{\beta,\vec\mathbf k}[\vec \mathbf p, \vec\boldsymbol{\upsilon},\mathbf H] \mathrm d(\vec\mathbf p,  \vec\boldsymbol{\upsilon},\mathbf H)\Bigg| <
C_3\epsilon^{-m/2}N^{-1/40}.
\end{multline}
The same bound holds in absolute values, i.e., if we simultaneously replace $w(r)$ with $|w(r)|$ and $\mathbf I_{\beta,\vec\mathbf k}[\vec\mathbf p,\vec\boldsymbol{\upsilon},\mathbf H]$ with $|\mathbf I_{\beta,\vec\mathbf k}[\vec\mathbf p,\vec\boldsymbol{\upsilon},\mathbf H]|$.

