body:
[Theorem 3 of arXiv:2605.03100, 'Berry-Esseen bounds for multivariate martingale difference sequences in the Kolmogorov dis'] Let $\{\bm{X}_k\}_{k \in [n]}$ denote a martingale difference process in $\mathbb{R}^d$ that satisfies Assumption \ref{as:fixed-variation}, and let $\bm{V}_k, \bm{\Sigma}_n$ be defined as in \eqref{eq:defn-Sigma-n}. Suppose that there exists a positive constant $M$ such that for all $k \in [n]$,
\begin{align}
\mathbb{E}[\|\bm{X}_k\|_{\infty}^3\mid\mathscr{F}_{k-1}] \leq M \lambda_{\min}(\bm{V}_k) \quad \text{almost surely.}
\end{align}

Then
\begin{align}
d_{\mathsf{K}}\left(\frac{1}{\sqrt{n}}\sum_{k=1}^n \bm{X}_k,\mathcal{N}(\bm{0},\bm{\Sigma}_n)\right) \lesssim \Delta \log_+d \log \frac{1+\Delta^2}{\Delta^2}
\end{align}
where 
\begin{align}
\Delta = \sqrt{M}\left(\frac{1}{\lambda_{\min}(\bm{\Sigma}_n)}\right)^{\frac{1}{4}} \left(\frac{d_{\max}(\bm{\Sigma}_n)}{d_{\min}(\bm{\Sigma}_n)}\right)^{\frac{1}{4}}\log_+^{\frac{3}{4}} d \cdot n^{-\frac{1}{4}}.
 \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm 11 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] For arbitrary $0 \leq t < T < \fz$, suppose the FBSDE \eqref{fbsde:equ:general} satisfies all the following conditions:
    \begin{itemize}
        \item[(1)] satisfies Assumption \ref{coefficient:assume:general} and Assumption \ref{fbsde:basic:assume:p:general} with some $p\in [2,\fz)$;
        \item[(2)] admits a regular decoupling field $w$ with the Lipschitz constant $L_w$;
        \item[(3)] \eqref{p-condition} holds with $L_g$ replaced by $L_w$. 
    \end{itemize}
    Then, the equation \eqref{fbsde:equ:general} admits a unique $\cL^p$-solution $\Tz = (X,Y,Z)$
    such that the a priori estimate \eqref{p-estimate} holds on $[t,T]$.

[Lemma 4 (When upward jumps are admissible) of arXiv:2608.30859, 'Conservation Laws with Discontinuous Flux:\\ A First Application to Traffic Flow'] Let $u^-<u^+$ and $\theta^-\ne\theta^+$. According to \eqref{eq:LaxCond}, upward jumps are Lax-admissible in the following two situations:
\begin{itemize}
\item $\theta^-=1$, $\theta^+=0$ and $u^* \leq u^+$, where $(u^*,g(u^*))$ denotes the unique point satisfying: 
\begin{equation}
u^*> u^- \quad\mbox{such that}\quad g^\prime(u^*) = \frac{f(u^-)-g(u^*)}{u^--u^*}.
\end{equation}
\item $\theta^-=0$, $\theta^+=1$ and $u^- \leq v^*$, where $(v^*,g(v^*))$ denotes the unique point satisfying:
\begin{equation}
v^* < u^+ \quad\mbox{such that}\quad g^\prime(v^*) = \frac{f(u^+)-g(v^*)}{u^+-v^*}.
\end{equation}
\end{itemize}

[Defi finite action of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $(\rho,j)\in \mathcal{M}((0,T)\times \mathbb{R}^n;[0,\infty)\times \mathbb{R}^n)$ be a finite Radon measure. We say that $(\rho,j)$ is a \emph{finite action curve} if
    \begin{enumerate}
    \item $(\rho,j)$ solve the continuity equation 
    \begin{align*}
\partial_t\rho+\dive j=0 \text{ in }\mathcal D'((0,T)\times \mathbb{R}^n).
\end{align*}
        \item $j\ll \rho$ and 
        \begin{align*}
            \int_{(0,T)\times \mathbb{R}^n}\left|\frac{dj}{d\rho}\right|^2\, d\rho<\infty;
        \end{align*}
    \end{enumerate}

[Corollary 2 (Failure of McKean's conjecture for grazing Boltzmann collisions) of arXiv:2609.03847, 'A counterexample to McKean's conjecture for the Landau-Coulomb equation'] Let $R>0$ be large enough and $f_R$ as in~\cref{thm:counter_example}, and $(Q_{B,\eps})$ be a grazing sequence of Boltzmann operators converging to the Landau--Coulomb operator. Then for $\eps>0$ small enough, the entropy dissipation increases at some positive time; there exists a sufficiently small $t^*_\eps$ such that 
    \begin{align*}
        D_{H,\eps}(F_{R,\eps}(t^*_\eps))> D_{H,\eps}(f_R). 
    \end{align*}

