[Corollary 152 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Assume that $a,b$ are smooth and bounded and let
$(\sft_{s},x_{s})$ be the corresponding Markov
diffusion process. Then for any $(t,x)\in\bR^{d+1}$,
 $\rho\leq1$, $C\in\bC_{\rho}$,  and Borel $f\geq0$
\begin{equation} 

I(t,x):=E_{t,x}\int_{0}^{\tau_{C}}f(t,x_{t})\,dt\leq N\rho^{2-\beta }\|I_{C }f\|_{E_{q,p,\beta }},
\end{equation}
where $\tau_{C}$ is the first exit time of 
$(\sft_{s},x_{s})$ from $C$. In particular,
for any $(t,x)\in\bR^{d+1}$,
 $\rho\leq1$, $C\in\bC_{\rho}$,  
\begin{equation} 

 E_{t,x}\int_{0}^{\tau_{C}}|b(t,x_{t})|\,dt\leq  N_{1} 
 \rho\hat b_{p\beta,q\beta,1} ,
\end{equation}
and in both estimates  $N$ and $N_{1}$ depend  only on $d,\delta,q ,p ,\beta ,\rho_{a} $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 3 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] Let $W$ defined as (\ref{Chatterjee-rank-correlation-coefficient}), we have
\begin{align}
    \left|\frac{\mathbb{P}(W>z)}{1-\Phi(z)}-1\right| = O(1)(1+z^3)/\sqrt{n},
\end{align}
for $0\leq z \leq n^{1/6}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor C2 of arXiv:2411.03712, '{\bf Probability Versions of Li-Yau Type Inequalities and Applications }\footnote{Supporte'] Assume that $\partial M$ is either convex or empty. Let $x\in M$ and $t>0$.    Then the following assertions hold.
 \begin{enumerate}
 \item [$(1)$]  For any $\varepsilon\in (0,1)$, $(equation G3 of the paper)$ holds for $\beta_{\varepsilon, f}$ replaced by
 \begin{equation} \beta_{\varepsilon,R}=2 K_{x,R} +\frac{\pi}{2R} \sqrt{K_{x,R}(n-1)} +\frac{\pi^2}{4R^2}\Big[4+   \big(\varepsilon^{-1}(1+\varepsilon)^2+2\big)n \Big].\end{equation}
  \item[$(2)$]
 For any $\alpha>1$, $(equation D4 of the paper)$ holds with  $\tilde\beta_{\alpha, f}$ replaced by
 \begin{equation} \tilde\beta_{\alpha,R}= \frac{\pi^2}{2 R^2}\Big(2+n+\frac{n\alpha^2}{2(\alpha-1)}\Big)+ \frac{\pi}{2R}\sqrt{K_{x,R}(n-1)}+\frac{2K_{x,R}}{\alpha-1}.\end{equation}

\end{enumerate}

[Definition def:Chernsingnabla of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] Let $L$ be a complex line bundle over a compact surface $\Sigma$ and $\nabla:=d+\alpha$ be a singular connection of $L$ with the singularity at $p\in \Sigma$, then the degree of $L$ can be defined as
\begin{equation}
\deg(L)=-\frac{i}{2\pi}\lim_{\varepsilon\rightarrow 0^+}\int_{\Sigma\setminus D_\varepsilon} d\alpha
\end{equation}
where $D_\varepsilon$ is a small disc of radius $\varepsilon>0$ around $p$.

From now on, we will refer to $\lim_{\varepsilon\rightarrow 0^+}\int_{\Sigma\setminus D_\varepsilon} -id\alpha \in 2\pi\mathbb{Z} $ as the \textbf{Chern number} $c(\nabla)$ of the singular connection $\nabla:= d+\alpha$.

[Lem 12 of arXiv:2604.00190, '2604.00190'] We have
\begin{align}
\lim_{n\to\infty}\cV^{\nu, (n)} {v_0}(x, y)= V^{\nu}(x, y),\qquad (x, y)\in\bR\times E. 

\end{align}
In addition, the function $V^{\nu}$ belongs to $\Gamma^\nu$.

