[Lemma lem:UV_int of arXiv:2605.21265, 'The non-Hermitian minor process'] Let the test functions $f_1,f_2$ satisfy the assumptions of Theorem~(theo:main of the paper) and let $K$ be defined as in (equation eq:def_K of the paper). For any $x_1,x_2\in (0,1]$ with $x_1<x_2$ it holds that
\begin{equation}
I_1= -8\int_{\mathbf{D}_{x_1}}\mathrm{d}^2 z_1\int_{\mathbf{D}_{x_2}}\mathrm{d}^2 z_2\overline{\partial_{z_1}f_1(z_1)}\partial_{z_2}f_2(z_2)\partial_{z_1}\partial_{\overline{z}_2}\log K +4x_1\!\!\int_{\partial\mathbf{D}_{x_1}\times \partial \mathbf{D}_{x_2}} \frac{\overline{f_1(z_1)}f_2(z_2)}{(x_1-z_1\overline{z}_2)^2}\mathrm{d} z_1\wedge \mathrm{d}\overline{z}_2,
\end{equation}
\begin{equation}
I_2=\frac{8}{x_1x_2}\left(\frac{1}{x_1}\int_{\mathbf{D}_{x_1}}\overline{f_1(z)}\mathrm{d}^2 z-\frac{1}{2}\int_0^{2\pi}\overline{f_1(\sqrt{x_1}\mathrm{e}^{\mathrm{i}\theta})}\mathrm{d}\theta\right)\!\!\left(\frac{1}{x_2}\int_{\mathbf{D}_{x_2}}f_2(z)\mathrm{d}^2 z-\frac{1}{2}\int_0^{2\pi}f_2(\sqrt{x_2}\mathrm{e}^{\mathrm{i}\theta})\mathrm{d}\theta\right)\!.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:variance of arXiv:2507.16188, 'The noisy voter model with general initial conditions'] For each $l=1,\ldots,n$ and $k=1,\ldots,q-1$, we have
\begin{equation}
\operatorname{Var}_{\mu_G}(\Psi_l^{(k)}) = \frac{1}{\gamma_l}\sum_{v\in V}\pi_G(v)^2| \psi_l(v)|^2 \big(1-(1-\theta)h_G(v)\big)\,,
\end{equation}
with $h_G(v) = \frac{1}{d_G(v)}\sum_{w\sim v}\mathbb{P}(v \leftrightsquigarrow w)$ and $\{v\leftrightsquigarrow w\}$ the event that two independent continuous-time random walks from $v$ and $w$, which move at rate $1-\theta$ and are killed at rate $\theta$, coalesce before dying. 
In particular,
\begin{equation}
\frac{\theta}{\gamma_l}\sum_{v\in V}
\pi_G(v)^2| \psi_l(v)|^2\leq \operatorname{Var}_{\mu_G}(\Psi_l^{(k)}) \leq \frac{1}{\gamma_l}\sum_{v\in V}\pi_G(v)^2| \psi_l(v)|^2
\end{equation}
Furthermore, if we let $M:= \max_v \mathrm{d}_G(v)/ \min_v \mathrm{d}_G(v) $, then we have
\begin{equation}
\frac{\theta}{2M}\leq \frac{\theta}{M\gamma_l}\leq  n \operatorname{Var}_{\mu_G}(\Psi_l^{(k)})  \leq \frac{M}{\gamma_l}\leq \frac{M}{\theta}\,.
\end{equation}

[Lem generalMin of arXiv:2411.08796, 'Optimal stopping for Markov processes \\ with positive jumps'] Let be given a Borel function $f\colon \mathds{R} \to \mathds{R}$ and a Borel set $B$
s.t. $\int_{B} |f(y)| G_{\alpha}(x,dy)<\infty$ for all $x\in\mathds{R}$.

Denote by $F_B \colon\mathds{R}\to \mathds{R}$ the function 
\begin{equation*}

F_B(x):=\int_{B} f(y) G_{\alpha}(x,dy).
\end{equation*}
Then
\begin{equation*}
F_B(x)=\Ex{x}{\ea{\mathpzc{h}_{B}}F_S(X_{\mathpzc{h}_{B}})}.
\end{equation*}

[Theorem 10 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the measure $\bnu$ admits the decomposition
        \begin{align}
                \bnu(\dd E) = \bnu(\{0\})\delta_0(\dd E) + \rho(E)\mb 1(E>0)\dd E, 
        \end{align}
        where $\rho$ is a nonnegative function on $(0,\infty)$ given by
        \begin{align}
                \rho(E) = \frac1\pi\lim_{\eta\downarrow0}\Im m(E+\ii\eta). \nonumber
        \end{align}
        Moreover, $\rho$ is locally $1/3$-H\"older continuous on $(0,\infty)$.
        Finally, $\rho$ is real analytic on the open set $\{E\in(0,\infty):\rho(E)>0\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:symm12 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable and symmetric functions $f$ 
\begin{equation}
\mathbb{E}^0_{{\mathcal V }^{(1)}_{1,2}} \left[f ({\mathcal H })\right]=\mathbb{E}^0_{{\mathcal V }^{(2)}_{2,1}} \left[f ({\mathcal H })\right]
\text{ and }
\mathbb{E}^0_{{\mathcal V }^{(2)}_{1,2}} \left[f({\mathcal H })\right] =\mathbb{E}^0_{{\mathcal V }^{(1)}_{2,1}} \left[f ({\mathcal H })\right].

\end{equation}

