[Prop PropConvergenceOnPathSpace of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $\theta\in \mathbb{R}$. Then, there exists a unique Feller diffusion process $(\mathbf{X}_{GL}^t)_{t\ge 0}$ on $\Upsilon_+$ such that whenever, 
\begin{equation*}
\left((N^{-1}\mathsf{x}_i^{(N)}(0))_{i\in \mathbb{N}},N^{-1}\sum_{i=1}^\infty \mathsf{x}_i^{(N)}(0)\right)  \overset{N \to \infty}{\longrightarrow} \boldsymbol{v}=((x_i)_{i\in \mathbb{N}},\gamma)\in \Upsilon_+,
\end{equation*}
we have, as $N \to \infty$,
\begin{equation*}
\left((N^{-1}\mathsf{x}_i^{(N)}(\bullet))_{i\in \mathbb{N}},N^{-1}\sum_{i=1}^\infty \mathsf{x}_i^{(N)}(\bullet)\right) \overset{\mathrm{d}}{\longrightarrow} \left((\mathsf{x}_i(\bullet))_{i\in \mathbb{N}},\boldsymbol{\gamma}(\bullet)\right)= \mathbf{X}_{GL}^\bullet
\end{equation*}
in $\mathrm{C}(\mathbb{R}_+;\Upsilon_+)$
with $\mathbf{X}_{GL}^0=\boldsymbol{v}$.

[Definition 18 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] We say that $v\in C_T\shc^{\beta} $ is a weak solution to \eqref{eq:FPlim}
  if for all $t \in [0,T]$ and  $\varphi\in\shs(\R^d)$ 
\begin{equation}
  \langle v(t), \varphi\rangle-\langle v_0,\varphi \rangle=\int_0^t \frac12 \langle v(s) , \Delta \varphi \rangle ds + \int_0^t  \langle  (v(s)F(K*v(s))) \cdot b(s) ,\nabla \varphi \rangle ds, 
\end{equation}
where the dual pairing is the one of $\shs,\shs'$ and $\cdot$ is the pointwise
product. Lemma
\ref{lm:WPdiv_arg} shows
that the right-hand side of \eqref{eq:WsolFP} is well-defined.

