[Proposition theorem for new prob space of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] There exists a filtered probability space $\left(\tilde{\Omega},\tilde{\mathcal{F}},(\tilde{\mathcal{F}}_t), \tilde{\mathbbm{P}}\right)$, a Cylindrical Brownian Motion $\tilde{\mathcal{W}}$ over $\mathfrak{U}$ with respect to $\left(\tilde{\Omega},\tilde{\mathcal{F}},(\tilde{\mathcal{F}}_t), \tilde{\mathbbm{P}}\right)$, a random variable $ \tilde{u}_0: \tilde{\Omega} \rightarrow L^2_{\sigma}$, and progressively measurable processes $(\tilde{u}^n), \tilde{u} :\tilde{\Omega} \times [0,T] \rightarrow \bar{W}^{1,2}_{\sigma}$ such that:
   \begin{enumerate}        
        \item $\tilde{u}_0$ has the same law as $u_0$;
        \item  $\tilde{u}^n$ is the unique weak solution of ((NSalphan of the paper)) on $\left(\tilde{\Omega},\tilde{\mathcal{F}},(\tilde{\mathcal{F}}_t), \tilde{\mathbbm{P}}, \tilde{\mathcal{W}}\right)$ with initial condition $\tilde{u}_0$;




    \item $\tilde{u}^n \rightarrow \tilde{u}$ in $C\left([0,T];W^{-\varepsilon,2}_{\sigma} \right) \cap L^2\left([0,T];L^2_{\sigma} \right)$ $\tilde{\mathbbm{P}}-a.s.$, and in\\ $L^2\left[ \tilde{\Omega};C\left([0,T];W^{-\varepsilon,2}_{\sigma}\right) \cap L^2\left([0,T];L^2_{\sigma} \right)  \right]$; 
    \item  $\tilde{u} \in L^\infty\left([0,T];L^2_{\sigma} \right) \cap L^2\left([0,T];\bar{W}^{1,2}_{\sigma}\right)$ $\tilde{\mathbbm{P}}-a.s.$ and in\\ $L^2\left[\tilde{\Omega};L^\infty\left([0,T];L^2_{\sigma} \right) \cap L^2\left([0,T];\bar{W}^{1,2}_{\sigma}\right)\right].$
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 24 of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Fix $T,\beta>0$ and $x\in\R^3\setminus\{0\}$. For every $L>0$ and
$m\in\mathbb N$ with $\beta\sqrt{T}\le L$, there exists a constant
$C=C(T,\beta,L,m)>0$ such that for all $0\le s<t\le T$,
\begin{align}
\int_{\R^3}p^{\,T,\beta}_{s,t}(x,y)\,|y-x|^{2m}\,dy
\;\le\;
\frac{C}{|x|}\,(t-s)^{m}.
\end{align}
Moreover, for every $\varepsilon>0$, there exists a constant
$C=C(T,\beta,L,m,\varepsilon)>0$ such that
\begin{align*}
\int_{\R^3}p^{\,T,\beta}_{s,t}(x,y)\,|y-x|^{2m}\,dy
\;\le\;
C\,(t-s)^{m}
\end{align*}
for all $0\le s<t\le T$ and all $x\in\R^3$ with $|x|\ge\varepsilon$.

