[Theorem 10 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] Let \(p\ge 2\) and \(\alpha\in(0,1/2)\) be such that \(1+\frac{1}{p}<\alpha+H\). There are exponents \(\eta>\frac{1}{2}\) and \(\bar \eta>1\) such that for \(h:\mathbb{R}^n\times \mathbb{R}^m\mapsto \mathbb{R}\) a bounded uniformly Lipschitz continuous function, one has the following:
\begin{itemize}
\item[1]. Suppose that \(\bar h(x)=\int_{\mathbb{R}^m}h(x,y)\mu(\dd y)=0\) for all \(x\in \mathbb{R}^n\). Then for any \(\beta<H\), there exists a constant \(\kappa>0\) such that 
\begin{equation}
\|\int_{s}^{t}h(x_r,y_r^\epsilon)\dd B_{r}^H\|_{p} \le C \epsilon^\kappa |h|_{BC^1}(|t-s|^\eta+\|x\|_{\alpha}^p(t-s)^{\bar \eta }).
\end{equation}
\item[2]. For general \(h\), one has the bound 
\begin{equation}
\|\int_{s}^{t}h(x_r,y_r^\epsilon)\dd B_{r}^H\|_{p} \le C |h|_{BC^1}(|t-s|^\eta+\|x\|_{\alpha}^p(t-s)^{\bar \eta }).
\end{equation}
where $C>0$ is a constant.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] In what follows, fix $L\in\mathbb{N}_+$, let $0\leq j\leq L$ and $\eta\in\Omega_N$ be arbitrary:
    \begin{itemize}
        \item Introduce the set $W_j^L:=\llbracket -j,-j+L+1\rrbracket\backslash\{0,1\}$; 



        \item Let $m_j^L(\eta)$ be the number of particles in $W_j^L$;

        \item Let ${\langle \eta\rangle}_{W_j^L}=\tfrac{1}{L}m_j^L(\eta)$ be the density of particles in the box $W_j^L$.
    \end{itemize}

[Definition 1 of arXiv:2609.00736, 'Modalities in non-classical variations of S4'] A \emph{(modal) logic} is a set of formulas closed under necessitation and \emph{modus ponens}:
        \[
            \ax{Nec}:=\frac{\varphi}{\Box\varphi} \text{ and } \ax{MP} :=\frac{\varphi \;\;\; \varphi\to\psi}{\psi}.
        \]
    We write $\Lambda\vdash\varphi$ for $\varphi\in\Lambda$.
    $\csf$ is the least logic containing all intuitionistic tautologies, and the axioms:
    \begin{itemize}
        \item ${\ax K} := (\Box(\varphi\to\psi) \to (\Box\varphi \to \Box \psi)) \land (\Box(\varphi\to\psi) \to (\Diamond\varphi \to \Diamond \psi))$;
        \item ${\ax 4} := (\Box\varphi \to \Box\Box\varphi) \land (\Diamond\Diamond\varphi \to \Diamond \varphi)$;
        \item ${\ax T} := (\Box\varphi \to \varphi) \land (\varphi \to \Diamond \varphi)$.
    \end{itemize}

[Proposition 7 (Leading Bell obstruction) of arXiv:2606.22066, 'A Bessel-zero obstruction to hyperbolic complete monotonicity of noncentral chi-square den'] Let \(a,b,\theta>0\), and let \(p=p_{a,b,\theta}\).  Define
\begin{equation}
H_u(w)=p(uv(w))p(u/v(w)),
\qquad w>2.
\end{equation}
Let
\begin{equation}
d_1=b\left(\frac{\theta}{a}-1\right),
\qquad
d_m=m!q_m(b\theta)^m
\quad(m\ge2),
\end{equation}
where the \(q_m\)'s are defined by \eqref{eq:log-Fa}.  Then, for each fixed \(n\ge1\),
\begin{equation}

\frac{1}{H_u(w)}
\frac{\dd^n}{\dd w^n}H_u(w)
=
u^n\mathcal B_n(d_1,\dots,d_n)
+
O(u^{n+1})
\qquad
(u\downarrow0),
\end{equation}
locally uniformly for \(w\) in compact subintervals of \((2,\infty)\).

Consequently, if \(p_{a,b,\theta}\) is HCM, then
\begin{equation}

(-1)^n\mathcal B_n(d_1,\dots,d_n)\ge0
\qquad(n\ge1).
\end{equation}

[Lemma 14 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Consider  a family $A(t)$ of    locally  bounded processes with  values in the class of square  matrices of  order $n$,

						\begin{enumerate}
							\item Suppose  that there  exist  a uniformly  bounded   and  elliptic  family $\K$,  and  a  constant number $k> 0$  such  that  $A$  is  $(\K, k)$-stable,  then $A$  is exponentially  stable and the  estimate \eqref{expstab} is  satisfied  with  $c=k/2$.
							\item Conversely,  if $A$ is  uniformly  bounded   and  exponentially   stable (so  that   estimate \eqref{expstab}  holds  for some $c> 0$)  then  for  any $k< 2c $,  there exists a  family of  uniformly bounded and  elliptic  processes $\K$ that   are  adapted  to  the  filtration  generated by $A$   and  are  such  that  $A$  is  $(\K, k)$-stable. More  generally, if  $q_0$ is a  family of  uniformly  positive numbers,  there  exists a family  of  uniformly  elliptic  processes $\K$   such  that $\K(0)= q_0 I,$   $A$  is  $(\K, k)$-stable  and for $t>0$ 
							\begin{equation}
								\trace(\K(t)) \leq C \left(1 + q_0 e^{ (-(2c -k)t) } \right).
							\end{equation}
						\end{enumerate}

