[Lemma pos_principle of arXiv:2507.06522, 'Balanced multi-species spin glasses'] Assume (equation converging_ratios of the paper) and (equation delta_decay of the paper).
There is a collection of random variables 
\eeq{ 
(\vc\delta_N)_{N\geqslant1} = (\delta_{s_1,\dots,s_p,N})_{s_1,\dots,s_p\in\mathscr{S},\, p\geqslant1,\, N\geqslant1}
}
such that the following statements hold with $\vc\Delta_N$ defined by $\Delta^2_{s_1,\dots,s_p,N} \coloneqq \Delta^2_{s_1,\dots,s_p} + \delta^2_{s_1,\dots,s_p,N}$.
\begin{enumerate}[label=\textup{(\alph*)}]

\item  For each $N$, the collection $\vc\delta_N$ is independent of the disorder $(g_{i_1,\dots,i_p})_{1\leqslant i_1,\dots,i_p\leqslant N,\,p\geqslant1}$.

\item  $\delta^2_{s_1,\dots,s_p,N} \leqslant \frac{1}{3\cdot 4^{p-1}}N^{-1/2}$ for all $s_1,\dots,s_p\in\mathscr{S}$, $p\geqslant1$, $N\geqslant1$.

\item  ${\vc\Delta}_N$ satisfies (equation delta_decay_finite of the paper) for all large $N$.

\item  $\sup_{{\boldsymbol x}\in[-1,1]^\mathscr{S}}|\xi_{N,\vc\Delta}({\boldsymbol x})-\xi_{N,{\vc\Delta}_N}({\boldsymbol x})|\to0$ as $N\to\infty$.

\item  For either ${\scaleobj{1.1}{\diamond}}\in\{\mathsf{Ising},\mathsf{spherical}\}$ and any $\varepsilon>0$, we have 
\eeq{ 
\lim_{N\to\infty}\sup_{H}\mathbb{E}_{\vc\delta} \mathbb{E}_g G_{N,H+H_{N,\vc\delta_N}}^{\otimes 2}\Big(\bigcup_{s\in\mathscr{S}}\{R_s(\sigma^1,\sigma^2)\leqslant -\varepsilon\}\Big)=0,
}
where $\mathbb{E}_{\vc\delta}$ denotes expectation over $\vc\delta_N$, $\mathbb{E}_g$ denotes expectation over the disorder, and the supremum is over
measurable functions $H\colon \Sigma_{N,{\scaleobj{1.1}{\diamond}}}\to\mathbb{R}$ satisfying
\eq{ 
\int_{\Sigma_{N,{\scaleobj{1.1}{\diamond}}}}\exp |H(\sigma)|\ \mu_N(\mathrm{d}\sigma) < \infty.
}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 25 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d=4$ and suppose that the assumptions of Theorem~\ref{thm:localWP_weakened} hold. Moreover, let $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$ and $T>0$. Let $(u,\sigma)$ be the unique maximal solution to \eqref{eq:SCHtorus}. Then we have
	\begin{equation}
	  \int_0^{\sigma\wedge T} \|u\|^2_{H^3} \dt < \infty  \qquad \mathbb{P}\text{-a.s.}
	\end{equation}

