body:
[Theorem of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The pmf of multivariate IGCP is given by
\begin{equation*}
\hat{p}_{\bar{\mathcal{M}}}(\bar{n},t)=\sum_{\substack{\Omega(k_i,n_i)\\i=1,2,\dots,q}}\Big(\prod_{i=1}^{q}\prod_{j_i=1}^{k_i}\frac{(\lambda_{ij_i})^{n_{ij_i}}}{n_{ij_i}!}\Big)\sum_{m=0}^{\infty}m^{\sum_{i=1}^{q}\sum_{j_i=1}^{k_i}n_{ij_i}}\sum_{\Omega(k_0,m)}\prod_{j_0=1}^{k_0}\frac{(\mu_{j_0}e^{-j_0\Lambda}t)^{x_{j_0}}}{x_{j_0}!}e^{-\mu_{j_0}t},\, \bar{n}\ge\bar{0},
\end{equation*}
where $\Omega(k_i,n_i)=\{(n_{i1},n_{i2},\dots,n_{ik_i}):\sum_{j_i=1}^{k_i}j_in_{ij_i}=n_i,\,n_{ij_i}\in\mathbb{N}_0\}$.

[Theorem 2 (Center-bias expansion) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Under \cref{ass:jet,eq:provisional-center}, uniformly on compact normalized query sets,
\begin{equation}
\cD^{c_\sigma}_{\sigma,\lambda}(z)
=G(z)-\frac{1}{\lambda}\nabla F_0(z)b+O(\sigma^\alpha),

\end{equation}
where $\nabla F_0$ is the $D\times D$ Jacobian of the tangent score. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma of unifrom estimation of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] There exists a constant $\mathfrak{C}_{\beta,\mathfrak{C}_A}>0$ independent of $n$ such that for all $\beta >0$
		\begin{equation*}
			\begin{split}
				&\sup_{n \geq 1}\left\lbrace  \mathbb{E}\left[ \esssup_{\tau \in \mathcal{T}_{[0,T]}} \mathcal{E}(\beta A)_{\tau} \left| Y^n_{\tau} \right|^2\right]+ \mathbb{E}\left[  \int_{0}^{T} \mathcal{E}(\beta A)_{s} \left| Y^n_{s-} \right|^2 dA_s\right] +\mathbb{E}\left[  \int_{0}^{T}\mathcal{E}(\beta A)_{s} d \left[M^n\right]_s \right]+\mathbb{E}\left[ \left| K^n_T \right|^2  \right]\right\rbrace \\
				& \leq \mathfrak{C}_{\beta,\mathfrak{C}_A} \left( \mathbb{E}\left[  \esssup_{\tau \in \mathcal{T}_{[0,T]}} \left| \mathcal{E}(\beta A)_{\tau} \xi_{\tau} \right|^2\right] +  \mathbb{E}\left[  \int_{0}^{T} \mathcal{E}(\beta A)_{s} \left| \mathfrak{f}(s) \right|^2 dA_s\right] 
				\right)  . 
			\end{split}
		\end{equation*}

