[Proposition HNNI-NEHU-MAIN of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $t \in \mathrm{supp}_t\ w_{q + 1,n + 1}^{(n)}$, the Newtonian pressure ${\mathfrak{p}_{q,n + 1}}\left( {t,x} \right)$ satisfies
\begin{equation*}
\left\| {{\mathfrak{p}_{q,{n+1}}}} \right\| _0 \leqslant C ,
\end{equation*}
\begin{equation*}
\left\| {{\mathfrak{p}_{q,{n+1}}}} \right\| _N \lesssim \delta _q^{\frac{1}{2}}\lambda _q^N , \ \ \forall \, N \in \left\{ {1, \cdots ,10} \right\} ,
\end{equation*}
and there exists a constant $\alpha \in \left( {\frac{\beta }{{b}},\beta } \right)$ such that the Newtonian stress ${\mathring{R}_{q,n + 1}}\left( {t,x} \right)$ satisfies
\begin{equation*}
{\left\| {{\mathring{R}_{q,{n+1}}}} \right\|_N} \lesssim {\delta _{q + 1,{n+1}}}\lambda _q^{N - \alpha }  , \ \ \forall \, N \in \left\{ {0,1, \cdots ,10} \right\}    ,
\end{equation*}
\begin{equation*}
{\left\| {{{\bar D}_{t,q}}{\mathring{R}_{q,{n+1}}}} \right\|_N} \lesssim {\delta _{q + 1,{n+1}}}\tau _q^{ - 1}\lambda _q^{N - \alpha } , \ \ \forall \, N \in \left\{ {0,1, \cdots ,10} \right\}   .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lmm Disjoint Sets of arXiv:2609.02682, 'LDP for tensor forms'] If $D_1,\dots,D_v\subseteq[n]$ are pairwise disjoint, then
\begin{equation}
\mathscr{E}(D_1,\dots,D_v)
=
\frac{1}{v!}\sum_{J\subseteq[v]} (-1)^{v-|J|}
\,\mathscr{M}\Big(\bigcup_{j\in J} D_j\Big).
\end{equation}
Consequently,
\begin{equation}
|\mathscr{E}(D_1,\dots,D_v)|\le \frac{2^v}{v!}\,\sup_{S\subseteq[n]} |\mathscr{M}(S)|.
\end{equation}

[Lemma lem:hankel_clt of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For
  a Hankel-profile random matrix  $X_N$ with an $\alpha$-stable profile $f$ as in Definition~(def:alpha_profile of the paper),  let $p_n(x,y)$ be the $n$-step transition probability on $\mathbb{T}_L^d$. Suppose that  $W \ll L$ and   $n (W/L)^\alpha \to \tau$ as $N \to \infty$, the following asymptotics hold.
\begin{enumerate}
    \item[(i)] \textbf{Even steps ($n=2k$):} The transition probability is concentrated around $y = x$,
    \begin{equation}
        p_{2k}(x, y) = \frac{1}{L^d} \theta_\alpha\Big( \frac{y-x}{L}, 2k \big(\frac{W}{L}\big)^\alpha \Big) + O(k e^{-c W^\alpha}).
    \end{equation}
    \item[(ii)] \textbf{Odd steps ($n=2k+1$):} The transition probability is concentrated around $y = x_0 - x$,
    \begin{equation}
        p_{2k+1}(x, y) = \frac{1}{L^d} \theta_\alpha\Big( \frac{y+x-x_0}{L}, (2k+1) \big(\frac{W}{L}\big)^\alpha \Big) + O(k e^{-c W^\alpha}).
    \end{equation}
\end{enumerate}

