[Thm eq:SigT2 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let ${\boldsymbol{\gamma}} \in {\mathbb R}^{d_1}$ with ${\gamma}_i  > -1$, $1\le i \le d_1$ and ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with ${\kappa}_i > -1$, $1 \le i \le d_2$. Then
the spectral operator can be written as 
\begin{align} 
  {\mathfrak D}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} u = \,  &
  \frac{1}{{\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y})} \left[  \sum_{i=1}^{d_1} 
     (\partial_{x_i}+ \partial_{y_{d_2}} )  x_i {\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y}) (\partial_{x_i}+ \partial_{y_{d_2}}) \right.  \\
       & \qquad\qquad\qquad \quad + \partial_{y_d} (|{\bm y}|- |{\bm x}|)  {\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} \partial_{y_d}\Big] \notag \\
  & + \frac{1}{{\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y})} \sum_{i=1}^{d_2} (\partial_{y_i} - \partial_{y_{d_2}}) 
       y_i  {\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y})  (\partial_{y_i} - \partial_{y_{d_2}}). \notag 
   \end{align}

