[Definition def-lacunary of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \begin{enumerate}
    \item A point process $\theta$ is called \textbf{lacunary} on $(0,\infty)$ if there exist constants $c,d \in (0, \infty)$, $c<d$, such that  
    \begin{equation} 
        \theta([cx, d x ]) \overset{\mathbb{P}}{\rightarrow} 0
    \end{equation} 
    as $x \rightarrow \infty $\footnote{The intuitive meaning of this definition is that atoms of the point process $\theta$ in $(0,\infty)$ are extremely spaced out and have large gaps, hence the choice of the word \textbf{lacunary}.}. 

    \item A point process $\theta$ is called \textbf{exponentially-lacunary} on $(0,\infty)$ if there exist constants $c,d \in (0, \infty)$, $c<d$, such that 
    \begin{equation}
         \theta([c \log x, d x ]) \overset{\mathbb{P}}{\rightarrow} 0
    \end{equation}
    as $x \rightarrow \infty $. 
\end{enumerate}

[Lemma of arXiv:2411.06838, 'Generalized Wasserstein Barycenters'] Let $
u_1, \ldots, 
u_n$ and $\Tilde{
u}_1, \ldots, \Tilde{
u}_n$ be probability measures in $\mathcal{P}_2(\mathbb{R})$; let $\lambda_1, \ldots, \lambda_n$ be weights such that $\sum_{i=1}^n \lambda_i =1$ and consider the barycenters $\mu$, $\Tilde{\mu}$ with respect to the measures $
u_1, \ldots, 
u_n$ and $\Tilde{
u}_1, \ldots, \Tilde{
u}_n$, with weights $\lambda_1, \ldots, \lambda_n$. Then
    \[
    W_2(\mu, \Tilde{\mu}) \leq \sum_{i=1}^n |\lambda_i|  W_2(
u_i,\Tilde{
u}_i).
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem MLSI DOWN UP of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Suppose that \(\Lambda\) is a nonnegative definite matrix with largest eigenvalue \(\lambda(\Lambda) < 1/2\). Then 
for all values of $L,M$, with $L+M$ even, for all $w\in{\ensuremath{\mathbb R}} ^L$,
\[
\mathcal{E}^{\rm du}(F, \log F)\ge (1 - 2\lambda(\Lambda))\, \mathrm{Ent}_{\nu_{L,M}}(F) \,,
\]
for every \(F : \Omega_{L,M} \to {\ensuremath{\mathbb R}} _+\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] For $A,B\in\mathcal K_{\X}^{\N^d}$, their multi-time convolution is the kernel sequence $A*B$ defined by

\begin{equation*}
(A*B)_{k}(x,C)=\sum_{r\leqd k}\int_{\X}A_r(x,\dd y)B_{k-r}(y,C),
\end{equation*}

for $k\in\N^d$, $x\in\X$ and $C\in\calX$.

[Theorem 2 (Low regularity wellposedness) of arXiv:2609.03558, 'Local well-posedness of the higher-order nonlinear Schr\"{o}dinger equation on the half-li'] Let $0\le s<\frac12$, $2\le \lambda\le \frac{7-2s}{1-2s}$, $
\mu=\frac{6\lambda}{(1-2s)(\lambda-1)}$, and $ r=\frac{2\lambda}{1+2(\lambda-1)s}
$. Let also $u_0\in H^s_x(\mathbb{R_+})$, $g_0\in H^{\frac{s+1}{3}}_{\text{loc},x}(\mathbb{R_+})$, $g_1\in H^{\frac{s}{3}}_{\text{loc},x}(\mathbb{R_+})$.  If $\lambda=\frac{7-2s}{1-2s}$, further assume that $u_0$ is small. Then,~\eqref{nonlinear} admits a unique solution in $u\in C([0,T];H^s_x(\mathbb{R}_+))\cap L^\mu_t(0,T;H^{s,r}_x(\mathbb{R}_+))$. Moreover, the data-to-solution map $(u_0,g_0,g_1)\mapsto u$ is locally Lipschitz continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm thm-L of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Suppose $d\ge 3$ and $q> 2 $ satisfies  the condition (equation q of the paper).
Let $ \lambda\in \Sigma_\theta$
and  $(u, \phi)\in W^{1, q} (E_{Nr}; \mathbb{C}^d) \times L^q(E_{Nr}; \mathbb{C})$ be a weak solution of
\begin{equation}
\left\{
\aligned
-\Delta u +\nabla \phi +\lambda u & = F &\quad & \text{ in } E_{Nr},\\
\text{\rm div} (u) & =0 & \quad & \text{ in } E_{Nr},\\
u& =0 & \quad & \text{ on } \Delta_{Nr},
\endaligned
\right.
\end{equation}
where $N\ge 4$ and $F\in L^\infty(E_{Nr}; \mathbb{C}^d)$. 
Then 
\begin{equation}
\aligned
&  |\lambda| \| u \|_{L^q(E_r)} 
+|\lambda|^{\frac12} \| \nabla u \|_{L^q(E_r)}\\
  & \le 
C \Bigg\{
\| F \|_{L^\infty(E_{Nr})}  (Nr)^{\frac{d}{q}}
+ \left(\fint_{E_{Nr}} |u|^q\right)^{1/q}
\left(
(Nr)^{\frac{d}{q}-2} + (Nr)^{\frac{d}{q}-1} |\lambda|^{\frac12} \right)\\
 & \quad + \left(\fint_{E_{Nr}} ( |\nabla u| + |\phi|)^q \right)^{1/q} (Nr)^{\frac{d}{q}-1}
+\left(\fint_{\Delta_{Nr}} ( |\nabla u| + |\phi|)^p \right)^{1/p}
(Nr)^{\frac{d-1}{p}-1}
\Bigg\},
\endaligned
\end{equation}
where  $p=\frac{q(d-1)}{ d}$ and $C$ depends only on $d$, $q$, $\theta$ and $M$ (not on $r$ or $N$).

