[Definition 82 of arXiv:2601.16377, '2601.16377'] For each $h \in [H]$, we define two holomorphic functions $\phi^+_h$ and $\phi_h^-$ in $\amsmathbb{M}_{h}$, which satisfy
\begin{equation}
 \forall x \in [\hat{a}'_{h},\hat{b}'_{h}]\qquad
\frac{\phi^{+}_{h}(x)}{\phi^{-}_{h}(x)} = e^{-\partial_x V_h(x)}.
\end{equation}
More specifically, we set:
\begin{equation}

\forall z \in \amsmathbb{M}_h\qquad \phi^+_h(z):= \big(\hat b'_h - z\big)^{\iota_h^+}\cdot e^{-\partial_zU_h(z)},\qquad
\phi^-_h(z):= \big(z-\hat a'_h\big)^{\iota_h^-}.
\end{equation}

[Dfn 227 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] In the symmetric spherical (resp.\ Ising) projection pursuit problem, we say that $\cA$ \textbf{$(\ioeps,\gamma)$-symmetrically attains} a target measure $\mu\in\cP_2(\bbR_{\ge 0})$ the output $\bx = \cA(\bG,\bg^{\aux})$ satisfies both of the following properties
    with probability at least $\gamma$:
    \begin{enumerate}[(i)]
         \item  
         $\bx \in S_N(\iota)$ (resp.\ $\Sigma_N(\iota)$);
         \item 
         $\bbW_2(\mu,\mu_{\bG,\sym}(\bx)) \le \ioeps$.
    \end{enumerate}
We say that $\cA$ is \textbf{$(\fq,\iotamsr,\iotasol,\gamma)$-symmetrically confined} to a subset $\cM\subseteq \cP_2(\bbR_{\ge 0})$ if the output $\bx$ satisfies both of the following properties with probability at most $1-\gamma$:
    \begin{enumerate}[(i)]
        \item  $\bx \in S_N(\iotasol)$ (resp.\ $\Sigma_N(\iotasol)$);
        \item  $\bbW_\fq(\mu_{\bG,\sym}(\bx),\cM) \ge \iotamsr$.
    \end{enumerate}

[Corollary cor cv Hausdorff ball boundary of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Jointly with~(equation eq cv subsequence of the paper) and~(equation eq cv ball of the paper), 
	\begin{equation}
		\left( \SCB^{\kappa_n, \partial}_{\ka_{\kappa_n}t}(\partial \BD)\right)_{t \in \BQ_{\ge 0}}
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( \SCB^\partial_t(\partial \BD) \right)_{t \in \BQ_{\ge 0}}
	\end{equation}
	for the product topology in $t \in \BQ_{\ge 0}$, where the space of compact sets is equipped with the Hausdorff topology, where $(\SCB_t^\partial(\partial \BD))_{t\ge 0}$ is as above the explored region in the uniform exploration of the $\CLE_4$.

