[Definition def:vector-energy-parameter of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] For \(q>0\), define the vector moment profile by
\begin{equation}
\rho(q)=\mathbb{E}[X_0^q+X_1^q]\in[0,\infty].
\end{equation}
The associated energy parameter is 
\begin{equation}
D_E(X)
=
\sup\left\{
s\in(0,1):
\inf_{0<q<2}2^{qs/2}\rho(q)<1
\right\},
\end{equation}
with the convention that the supremum of the empty set is \(0\).

[Lemma 27 (the continuous Poisson solution) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:poisson-cont}
  The function $g_\star$ of \eqref{eq:pois-rep} lies in $C([0,\infty))\cap C^1((0,\infty))$ with $g_\star'$ locally absolutely continuous, solves $\mathcal Lg_\star=-\hat\eta$ a.e.\ on $(0,\infty)$, and has the boundary flux
  \begin{equation}
    \frac{dg_\star}{ds_G}(0^+)=-\hat\eta(0)\,\frac{e^{-\beta G(0)}}{\mu}
    \qquad\bigl(\text{equivalently }\ \mathcal Lg_\star(0)=-\hat\eta(0)\bigr).
  \end{equation}
  For $0<x\le1$, with $c_F\coloneqq -\hat\eta(0)/\mu$, 
  \begin{equation}
  \begin{aligned}
    g_\star'(x)&=c_F\,x^{1-\delta}+O\bigl(\snorm{\eta}_\infty x^{2-\delta}\bigr),\\
    g_\star''(x)&=(1-\delta)\,c_F\,x^{-\delta}+E(x),
    \qquad |E(x)|\le C\snorm{\eta}_\infty\bigl(1+x^{1-\delta}\bigr).
  \end{aligned}
  \end{equation}
For $x\ge1$, $|g_\star'(x)|\le C\snorm{\eta}_\infty/x$ and $|g_\star''(x)|\le C\snorm{\eta}_\infty$ a.e.; and $|g_\star(x)|\le C\snorm{\eta}_\infty\bigl(1+\log(1+x)\bigr)$.

