body:
[Proposition 30 (One-row restriction) of arXiv:2608.29585, '2608.29585'] Fix an integer $n\ge2$. For every $d\ge1$ and $s\in\Z$, there is a unique continuous
$\widehat R_{\mathrm{ev}}^{\mathrm{BG}}$-algebra homomorphism
\begin{equation}
\operatorname{res}_{d,s}:\widehat\cZ_n^{\mathrm{BG}}
 \longrightarrow\mathscr A_{d,s}
\end{equation}
extending algebraic Harish--Chandra restriction along $\gamma_n$, where
$\mathscr A_{d,s}$ is regarded as an
$\widehat R_{\mathrm{ev}}^{\mathrm{BG}}$-algebra through the coefficient map
$\iota_d$.  The restriction is
given by
\begin{equation}
 \operatorname{res}_{d,s}(c)
 =\sum_{k\ge0}\iota_d(c_{(k)})\varepsilon_nU_k(z),
\end{equation}
and hence
\begin{equation}
 \operatorname{res}_{d,s}(\sigma_\lambda)=
 \begin{cases}
  \varepsilon_nU_k(z),&\lambda=(k),\\
  0,&\ell(\lambda)\ge2.
 \end{cases}
\end{equation}
For every zero-framed knot $K$, the interpolation-sector knot element
satisfies
\begin{equation}
 \operatorname{res}_{d,s}
 (J_K^{\mathrm{int}}(\mathfrak{gl}_n;q^2))=\mathscr J_{K,s}(z).
\end{equation}

[Lemma lemma-energy-ineq-on-C of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] Let $ \mathcal{C}_0\subset \mathbb{X}_{\alpha,\beta} $ be a weak-strong uniqueness class of (equation PDE-SQG of the paper) and let $\mathcal{C}=\overline{\mathcal{C}_0}^{\mathcal{I}}$. Suppose that $ \theta\in \mathcal{C} $ is  a weak solution of (equation PDE-SQG of the paper) for some $g \in L^2([0, T];H)$ in the sense of Definition (def-weak-solution-skeleton-equation of the paper). Then the $ H^{\alpha-2\beta} $-energy inequality holds:
	\begin{equation*}
		\frac{1}{2}\|\theta(T)\|_{H^{\alpha-2\beta}(\mathbb{T}^2)}^2+\int_0^T\|\theta(s)\|_{H^{2\alpha-2\beta}(\mathbb{T}^2)}^2\,\mathrm{d}s\leqslant\frac{1}{2}\|\theta(0)\|_{H^{\alpha-2\beta}(\mathbb{T}^2)}^2+\int_0^T\langle\Lambda^{2\alpha-2\beta}\theta, g\rangle\,\mathrm{d}s.
	\end{equation*}

[Lemma 20 of arXiv:2608.26288, 'Muon with Finite Newton--Schulz: The Smoothing Benefit in Nonsmooth Nonconvex Optimization'] Under~\cref{ass:general-spectral-link}, for every $C>0$, the Fenchel conjugate of $\widetilde\Phi_{h,C}$ is
\begin{equation}
  \widetilde\Phi_{h,C}^*(W)
  =C\sum_{i=1}^r\phi_h^*(\sigma_i(W)).
  \notag
\end{equation}

[Theorem Thm-(rho u) of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $d \geq 2$ and $p\ge 1$.  
		Assume (Hypo-W L of the paper), (Hypo-Qi of the paper), (Hypo-Pressure of the paper),  and (Hypo-h of the paper) with $\sigma> \frac{d}{2} + p$. Let $s > \frac{d}{2} + p + \max \{3\zeta,1\}$, where $\zeta=\zeta_{\mathcal Q_1,\mathcal Q_2}$ is given in (equation zeta-Q12 of the paper). Let $(\rho_0,u_0)\in\mathbb H^s_{\mathbf{r}}$ be an $\mathcal{F}_{0}$-measurable random variable.

		\begin{enumerate}[label={\bf (\arabic*)},leftmargin=0.79cm]\setlength\itemsep{0.2em}

			\item  
			If (Constant Sound of the paper) holds, then the Cauchy problem (equation SEuler-(rho u) of the paper) 
			admits a unique maximal $\mathbb H^s_{\mathbf{r}}$ classical solution $((\rho,u),\tau^{*})$ in the sense of Definition (solution definition (rho u) of the paper). Moreover, 
			\begin{equation}
				(\mathbf{r}(\rho), u)\in D([0,\tau^*);\mathbb H^{s'})\quad \forall s'<s\quad {\mathbb P}\text{-}{\rm a.s.},
			\end{equation}
			the lifetime $\tau^*$ is independent of $s$, and the following blow-up criterion holds:
			\begin{equation}
				\limsup_{t \rightarrow \tau^*} \|(\mathbf{r}(\rho), u)(t)\|_{{\mathbb W}^{p,\infty}} = \infty \quad \text{a.s. on } \{\tau^* < \infty\}.
			\end{equation}

			\item  If (General Sound of the paper) holds and we further assume that 
			$$\text{either}\quad \mathbb P\Big(0=\mathbf{r}_0<\underline{\mathbf{r}}\le \varrho_0\le \overline{\mathbf{r}}<\mathbf{r}_\infty=\infty\Big)=1\quad \text{or}
			\quad \mathbb P\Big(-\infty=\mathbf{r}_0<\underline{\mathbf{r}}\le\varrho_0\le\overline{\mathbf{r}}<\mathbf{r}_\infty=0\Big)=1.$$
			Then (equation SEuler-(rho u) of the paper) also admits a unique maximal $\mathbb H^s_{\mathbf{r}}$ classical solution $((\rho,u),\tau^{*})$ satisfying (equation X D(0,tau) of the paper) in the sense of Definition (solution definition (rho u) of the paper). Furthermore, the lifetime $\tau^*$ is independent of $s$ and the solution satisfies the blow-up criterion (equation Blow-up criterion (rho u) of the paper).
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

