[Proposition 32 (Boundedness and continuity of $\delta\Pi^-$, Steps 4.a) and 4.b)) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Assume that the hypothesis of Proposition~\ref{prop_2} is satisfied, and that additionally 
for all populated $\beta'\prec\beta$ and all~$\n$ 

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{q}} \left|
\partial^\n \delta \Pi_{x \beta'}(y)
\right|^{ q} \lesssim 
\ve^{\alpha-|\n|}
( \ve + |x-y|)^{| \beta' |- \alpha}\w \,.
\end{aligned}
\end{equation}

Then for every $\n$ and $l\geq0$ 

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{q}} \left| 
\partial^\n \delta\Pi^-_{x\beta}(y) 
\right|^{ q} 
\lesssim 
\ve^{\alpha-2-|\n|}
( \ve+ | x-y|)^{| \beta| - \alpha} \w \, ,
\end{aligned}
\end{equation}

and

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{q}} \left|
(\mathrm{id}-T_z^{\leq l}) \partial^\n \delta\Pi_{x \beta}^{-}(y) 
\right|^{ q} 
\lesssim 
\ve^{\alpha-2-|\n|-1-l}
|y-z|^{1+l}
( \ve+ | x-y| + |x-z|)^{| \beta| - \alpha} \w \,.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lmm equivalence of two cut norms of arXiv:2609.02682, 'LDP for tensor forms'] The Cut$^*$ norm is equivalent to the bad cut norm, i.e. there exists a constant $C_v>0$, depending only on $v$, such that
    \[C_v\|W\|_{\square}\le\|W\|_{\square^*}\le  \|W\|_{\square},\]
    for any $W\in \mathcal{W}_v$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 of arXiv:2608.28964, '2608.28964'] For the equation given by \eqref{eq NS},\eqref{eq xi} and for any $B_0,\gamma,\alpha>0$, there exists a constant $N\in\N^+$ such that if the sequence $\{b_j\}_{j\in\N^+}$ satisfies 
	\begin{equation*}
	\sum_{j\in\N^+}b_j^2\leq B_0\quad\text{and}\quad b_j\neq0\quad\text{for }1\leq j\leq N,
	\end{equation*}
    then there exists a constant $C>0$ such that, for any Fr\'echet differentiable function $\varphi\colon \mathcal X\to\R$, $U_0\in \mathcal X$ and $t\geq0$,
	\begin{align}
	\|\nabla P_t\varphi(U_0)\|_{\mathcal X}\leq C\exp\left(\gamma\|U_0\|_{\mathcal X}^2\right)\left(\sqrt{P_t(|\varphi|^2)(U_0)}+e^{-\alpha t}\sqrt{P_t(\|\nabla\varphi\|_{\mathcal X}^2)(U_0)}\right).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Iterative undirected graph process) of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the vertex set $V=\{v_1,\ldots,v_n\}$, consider a degree sequence $\d=(d_1,\ldots,d_n)$ of non-negative integers with $2m:=d_1+\ldots+d_n>0$ even, and consider a set $X$ of forbidden edges.
		\begin{itemize}
			\item Start with no edges $E_0=\emptyset$.
			\item For $r=0,\ldots,m-1$, let $d_{i,r}$ denote the degree of vertex $v_i$ in $(V,E_r)$, and consider those pairs of vertices $v_i,v_j\in V$ with $i\neq j$, $d_{i,r}<d_i$, $d_{j,r}<d_j$, and $\{v_i,v_j\}\not\in E_r\cup X$.
			\begin{itemize}
				\item If no such pairs exist, let $E_{r+1}=E_r$.
				\item Otherwise, choose such a pair $v_i,v_j$ at random with probability proportional to $(d_i-d_{i,r})(d_j-d_{j,r})(1-\tfrac{d_id_j}{4m})$, and let $E_{r+1}=E_r\cup\{\{v_i,v_j\}\}$.
			\end{itemize}
			\item Finally, apply rejection sampling to sample $E=E_m$ with $m$ edges.
		\end{itemize}
		This guarantees that $(V,E)$ is a simple undirected graph with degree sequence $\d$ and with no edges from $X$.

[Theorem 5 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $0<\mu\le1$. For any initial data $u_0\in \CD_\mu^1$, there exists energy solutions in $\CC(\IR,\CD_\mu^1)$ to \eqref{NLS} on $\IR^2$ for $m\ge1$. For any time interval $I$ containing $0$, we have the bound
\begin{equation}
\sup_{t\in I}\|u(t)\|_{\CD_\mu^1}\lesssim(1+|I|)\|u_0\|_{\CD_\mu^1}
\end{equation}
with a constant that depends only on the noise. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Define the function $G: [-1, 1] \to [0, \frac{1}{2}]$ by $G(r) = \Sigma_n\left(\frac{\pi - \arccos r}{2}\right)$.

For any measurable functions $f, g : \mathbb{S}^n \to \R_+$ and any measurable, non-increasing function $\Omega: (-1,1] \to (0, \infty)$ satisfying $$f(x)g(y) \leq \Omega^2(\langle x, y \rangle) \text{ for all }x, y \in \mathbb{S}^n,\, x\neq - y,$$ one has
\begin{equation}

    \left(\int_{\mathbb{S}^n} f(x) \,d\sigma_n(x)\right)^{\frac{1}{2}} \left(\int_{\mathbb{S}^n} g(y) \,d\sigma_n(y)\right)^{\frac{1}{2}} \leq 2\int_{-1}^1 \Omega(r) \,dG(r).
\end{equation}
In particular, if $f$ and $g$ satisfy the constraint $f(x)g(y) = 0$ for all $\langle x, y \rangle > 0$, we obtain
\begin{equation}

    \left(\int_{\mathbb{S}^n} f(x) \,d\sigma_n(x)\right)^{\frac{1}{2}} \left(\int_{\mathbb{S}^n} g(y) \,d\sigma_n(y)\right)^{\frac{1}{2}} \leq \int_{-1}^1 \Omega(r) \,dG(r).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn Def: simple polynomial process of arXiv:2605.16921, '${\ASL_n}(\mathbb Z)$ invariant random subsets of $\mathbb Z^n$'] Fix integers $k, m \geq 0$, let $\mu$ denote the Haar probability measure on the subspace of $\mathbb{T}^m_{\leq k+1}[X_1, \ldots, X_d]$ consisting of polynomials of degree exactly $k+1$, and let $f: \mathbb{T}^m \to [0, 1]$ be measurable. The associated \emph{simple polynomial point process} on $\mathbb{Z}^d$ is obtained as follows:
    \begin{itemize}
        \item draw a random polynomial $P$ according to $\mu$;
        \item independently across $t \in \mathbb{Z}^d$, keep $t$ with probability $f(P(t))$.
    \end{itemize}

[Lemma linearterm of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Recall that $ \besterrNuc{\mathbf{X}}{r} = \sum_{i=r+1}^{d} \sigma_i (\mathbf{X}) $. Assume that
\begin{equation*}
 \mathcal{A} \left(\mathbf{X}_\star \right) = \mathcal{A} \left(\mathbf{X} \right),
\end{equation*}
that the measurement operator $\mathcal{A}: \mathbb{R}^{d_1 \times d_2} \longrightarrow \R^m $ has the NSP of order $r$ for some $\eta_r<1$ and that $\varepsilon \le \frac{\besterrNuc{\mathbf{X}}{r}}{d}$.
Then it holds that
\begin{equation*}
\innerproduct{ \nabla \mathcal{J}_{\varepsilon}(\mathbf{X}) ,\mathbf{X}_\star- \mathbf{X}}  \le - \left( \frac{1-\eta_r}{1+\eta_r}    - 1/4  \right) \nucnorm{\mathbf{X} -\mathbf{X}_\star} + \frac{9}{4} \besterrNuc{\mathbf{X}_\star}{r}.
\end{equation*}

[Proposition prop:L2cycle of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] For every bounded Borel $\psi$ supported in $[r_0, r_1]$,
  \begin{equation}
    \Delta_n \in L^2, \quad M_n \in L^2.
  \end{equation}

[Lemma 26 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] For any \(3/4<H<1\) and \(u>v\) we have that 
\begin{equation}
\int_v^u (s-u)^{H-3/2}(s-v)^{2H-2}ds = (u-v)^{3H-5/2}\beta(H-1/2, 2H-1)
\end{equation}

[Proposition COR-WIEJDUHFJ-HUD of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Suppose that the exponents ${p_1}$ and ${p_2}$ obey $1 \leqslant {p_2} < {p_1} $. Then, the building block ${\mathbb{W}_\xi } \left( {t, x } \right)$ satisfies the intermittency
\begin{equation}
\frac{{{{\left\| {  {\sum\limits_{\xi  \in \Lambda } {{\mathbb{W}_\xi }} }  } \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| { {\sum\limits_{\xi  \in \Lambda } {{\mathbb{W}_\xi }} } } \right\|}_{{L^{{p_2}}}}}}} \sim {r^{\frac{2}{{{p_2}}} - \frac{2}{{{p_1}}}}} , \  \ \forall \, t \in \left[ 0,T \right] ,
\end{equation}
and the inertial-range intermittency
\begin{equation}
\frac{{{{\left\| {\sum\limits_{\xi  \in \Lambda } {\left( {{\mathbb{W}_\xi }\left( {x + l\mathbf{n}} \right) - {\mathbb{W}_\xi }\left( x \right)} \right)}}  \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| {\sum\limits_{\xi  \in \Lambda } {\left( {{\mathbb{W}_\xi }\left( {x + l\mathbf{n}} \right) - {\mathbb{W}_\xi }\left( x \right)} \right)}} \right\|}_{{L^{{p_2}}}}}}} \sim {r^{\frac{2}{{{p_2}}} - \frac{2}{{{p_1}}}}} , \ \ \forall \, t \in \left[ 0,T \right] .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main-intro of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] For every fixed integer $\ell\geq1$, as $N\to\infty$,
\begin{equation}
 C_\ell(N)=2^\ell N^\ell+\gamma_\ell N^{\ell-1}
 +\delta_\ell N^{\ell-2}+O_\ell(N^{\ell-3}),
\end{equation}
where
\begin{equation}
 \gamma_\ell=3\ell(\ell-1)2^{\ell-2}
 -\frac{\ell^2 2^{2\ell}}{2^\ell-1},
\end{equation}
and
\begin{align}
 \delta_\ell=2^\ell\bigg[&
 -\frac34\binom{\ell}{2}+\frac{15}{4}\binom{\ell}{4}
 +\frac{2^\ell\ell\bigl(\ell-6\binom{\ell}{3}\bigr)}{2^\ell-1}
 \nonumber\\
 &+\frac{2^\ell\ell^2\binom{\ell}{2}(5\cdot2^\ell-3)}
 {2(2^\ell-1)^2}
 +\frac{2^{2\ell}\ell^4}{(2^\ell-1)^3}
 \nonumber\\
 &-\frac{3^{\ell+1}}{2(3^\ell-1)}
 \left(\binom{\ell}{2}
 -\frac{2^\ell\ell^2}{2^\ell-1}\right)^2
 -\frac{2^{2\ell}\ell^2}{4(2^{2\ell}-1)}\bigg].

\end{align}
Equivalently, there are constants $N_0(\ell)$ and $A_\ell$ such that the
absolute value of the remainder in (equation eq:main-intro of the paper) is at most
$A_\ell N^{\ell-3}$ for every $N\geq N_0(\ell)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Under the assumptions of Theorem \ref{thm:main:blocks} there is $c>0$ such that for every $\eps >0$
	\begin{equation}
		\liminf _{t\to \8}  t^{\xi^*_1+\xi^*_2}(\log t)^{1\slash 2}	\P \left ( \text{There is $n \in \N$ such that } \Pi ^{(1)}_n>t, \Pi ^{(2)}_n> \eps t \right )\geq c \eps ^{-\xi^* _2}.
	\end{equation}
	In particular, there is $t_0$ such that 	
	\begin{equation}
		\P \left (\exists _n \ \Pi _n^{(1)}>t, \Pi _n ^{(2)}>t \right )\geq c  t^{-\xi^*_1-\xi^*_2}(\log t)^{-1\slash 2}\quad \mbox{for}\ t\geq t_0.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

