body:
[Lem 10 (Generalized pivot regeneration blocks) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let
$
    0<\rho_1<\rho_2<\rho_3<\cdots
$
be the generalized pivots, and let $\gk_n$ be as in~\eqref{eq:kappa-def}.  We use the interval edge set $\cE[x,y]$ and the interval environment $\Env[x,y]$ defined in~\eqref{eq:interval-env-notation}, and the block notation~\eqref{eq:block-variable-notation}. Then the following holds.

\begin{enumeratei}
\item \textbf{Generalized pivot renewal-block localization.}
If $\rho_i<\rho_j$ are two generalized pivots, then there
exists a minimum-hop geodesic from $\rho_i$ to $\rho_j$ using only
edges in $\cE[\rho_i,\rho_j]$.  Consequently,
$T(\rho_i,\rho_j)\text{ and }H(\rho_i,\rho_j)
$ are measurable with respect to $\Env[\rho_i,\rho_j]$.

\item \textbf{Renewal-block i.i.d.~structure.}
The block sequence
\begin{align}
    \left\{
        \left(
            \sfP_i,\,
            \Env[\rho_i,\rho_{i+1}]
        \right)
    \right\}_{i\ge1}
\end{align}
is i.i.d.~In particular,
$
    \{(\sfP_i,\sfT_i,\sfH_i)\}_{i\ge1}
$
is i.i.d.

\item \textbf{Geometric domination of the gaps.}
Generalized pivots occur infinitely often almost surely, and if
$
    \fs_{\ell,k}:=(k+1)\ell-1,
$
then
\begin{align}
    \sfP_i
    \preceq
    \fs_{\ell,k}\,\mathrm{Geom}(p_{\mathrm{gen},\ell}),
    \quad i\ge1.
\end{align}
In particular, $\sfP_1$ has finite moments of all orders.  Consequently,
\begin{align}
    \frac{\gk_n}{n}
    \to
    \frac{1}{\E\sfP_1}
    \quad\text{a.s.}
\end{align}

\item \textbf{Deterministic bounds for bounded weights.}
All moments of $\sfT_i$ and $\sfH_i$ are finite, and
\begin{align}
    \left\lceil\frac{\sfP_i}{\ell}\right\rceil
    \le
    \sfH_i
    \le
    \sfT_i
    \le
    2\left\lceil\frac{\sfP_i}{\ell}\right\rceil,
    \qquad
    \sfH_i\le \sfP_i,
    \quad i\ge1.
\end{align}
\end{enumeratei} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] For any $0\leq t\leq T$, it holds
  \begin{align}
    U_t^\epsilon Z_t^\epsilon
    =&Z_t^0 U_t^\epsilon\left( 1+\sum_{i=1}^{n-1}I_t^{i,\epsilon}+R_t^\epsilon \right),
  \end{align}
  where
  \begin{align}
    r_s^{1,\epsilon}=&H_s^\epsilon - c(s)X_s\nonumber\\
    \begin{split}
      I_t^{i,\epsilon}=&\int_0^t\int_0^{t_{i}}\cdots \int_{0}^{t_2} (r_{t_1}^{1,\epsilon})^\top (\sigma(t_1)\sigma(t_1)^\top)^{-1} (dY_{t_1}^\epsilon-c(t_1)X_{t_1}dt_1)\\
  &\times \cdots \times (r_{t_i}^{1,\epsilon})^\top (\sigma(t_i)\sigma(t_i)^\top)^{-1} (dY_{t_i}^\epsilon-c(t_i)X_{t_i}dt_i),
    \end{split}\\
    \begin{split}
      R_t^\epsilon=&\int_0^t\int_0^{t_{n}}\cdots \int_{0}^{t_2} K_{t_1}^\epsilon(r_{t_1}^{1,\epsilon})^\top (\sigma(t_1)\sigma(t_1)^\top)^{-1} (dY_{t_1}^\epsilon-c(t_1)X_{t_1}dt_1)\\
  &\times \cdots \times (r_{t_n}^{1,\epsilon})^\top (\sigma(t_n)\sigma(t_n)^\top)^{-1} (dY_{t_n}^\epsilon-c(t_n)X_{t_n}dt_n),
    \end{split} \\
    \begin{split}
      K_t^\epsilon=&\exp\left( \int_0^t(r_s^{1,\epsilon})^\top (\sigma(s)\sigma(s)^\top)^{-1} (dY_s^\epsilon-c(s)X_sds)\right.\\
  &\left.-\frac{1}{2}\int_0^t(r_s^{1,\epsilon})^\top(\sigma(s)\sigma(s)^\top)^{-1} r_s^{1,\epsilon} ds\right),
    \end{split}  
  \end{align}
  and
  \begin{align}
    \begin{split}
      Z_t^0=&\exp\left( \int_0^t(c(s)X_s)^\top (\sigma(s)\sigma(s)^\top)^{-1} dY_s^\epsilon\right.\\
  &\left.-\frac{1}{2}\int_0^t(c(s)X_s)^\top(\sigma(s)\sigma(s)^\top)^{-1} c(s)X_s ds\right).
    \end{split}    
