body:
[Theo 16 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Assume the FBSDE \eqref{fbsde:equ} satisfies one of the conditions:
    \begin{itemize}
        \item[(1)] all the conditions in Theorem \ref{thm:small:decoupling} with some $p\in [2,\fz)$ and sufficiently small $T - t$;
        \item[(2)] all the conditions in Theorem \ref{thm:large:decoupling} with some $p\in [2,\fz)$ and arbitrary $T\in (0,\fz)$.
    \end{itemize}
    Let $(X,Y,Z)$ be the solution of the FBSDE \eqref{fbsde:equ}.
    Then, for all $t\leq s < r\leq T$ and the coupling function $\vz = \1_{(s,r]}$, we have
    \begin{align}
        CV_p([t,T])
        &\leq c_{\eqref{equ:est:cv:p}} \left\{P_p([t,T]) + I_{p,\mu}([s,r]) \right.\notag\\
        &\quad\quad \left. + [(L_{\mu,1})^p + (L_{\mu,2})^p] I_{p,T} (r - s)^{p/2}\right\}.
    \end{align}
    Moreover,
    \begin{align}
        \E\left[ \left(\int^r_s |Z_u|^2\,\od u\right)^{p/2}\right] \leq CV_p([t,T]),
    \end{align}
    \begin{align}
        \E\left[|X_s - X_r|^p\right]
        &\leq c_{\eqref{equ:path:x}}\left\{ 
            I_{p,b}([s,r]) + I_{p,\mu}([s,r]) + (L_{\mu,3})^pCV_p([t,T])\right.\notag\\
            &\qquad\qquad + c_{\eqref{p-estimate}} [(L_{b,1})^p + (L_{b,2})^p] I_{p,T} (r - s)^p\notag\\
            &\qquad\qquad + c_{\eqref{p-estimate}}\left[(L_{\mu,1})^p + (L_{\mu,2})^p\right]I_{p,T} (r - s)^{p/2\notag}\\
            &\left. \qquad\qquad + (L_{b,3})^{p}(r - s)^{p/2}CV_p([t,T])\right\},
    \end{align}
    and
    \begin{align}
        \E\left[|Y_s - Y_r|^p\right]
        & \leq c_{\eqref{equ:path:y}}\left\{
            I_{p,f}([s,r]) + CV_p([t,T])\right.\notag\\
            &\qquad\qquad + c_{\eqref{p-estimate}}\left[(L_{f,1})^p + (L_{f,2})^p\right]I_{p,T} (r - s)^p\notag\\
            &\left. \qquad\qquad + (L_{f,3})^p (r - s)^{p/2} CV_p([t,T])\right\},
    \end{align}
    where 
    \begin{itemize}
        \item the constants $L_{b,i}$, $L_{\mu,i}$ and $L_{f,i}$ with $i\in\{1,2,3\}$ are the Lipschitz constants defined as in Assumption \ref{coefficient:assume:general};
        \item the positive constant $c_{\eqref{equ:est:cv:p}}$ only rely on $p$, $c_{\eqref{equ:small:decoupling}}$ (or $c_{\eqref{equ:large:decoupling}}$) and $c_{\eqref{p-estimate}}$;
        \item the positive constants $c_{\eqref{equ:path:x}}$ and $c_{\eqref{equ:path:y}}$ only rely on $p$.
    \end{itemize}

