[Lemma limit-A-N of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] \label[lemma]{lem-matrix-r} The following equalities    hold.
		\begin{align*}
			\dfrac{1}{2}	\operatorname{div}_x\left(\sum_{k\in K}(\sigma_k^N \otimes \sigma_k^N) \nabla_xf\right)&=
			\alpha_N	\Delta_xf
		\end{align*}
      where $\alpha_N:=\dfrac{1}{2}\sum_{k\in K_{++}}(\theta^{N,\tau}_k)^2$ and $\alpha_N \rightarrow 0$ as $N\rightarrow \infty$. Moreover, 
        \begin{align}
		A^N(r):=	\sum_{k\in K}\left((\nabla_x \sigma_k^Nr) \otimes (\nabla_x \sigma_k^Nr)\right) &= A(r)+\dfrac{1}{\tau}O(N^{-1})P^N(r),	\end{align}
		such that   $P^N$  is quadratic in $r$ and with coefficients uniformly bounded in $N$ and for $ r\in \mathbb{R}^2$
        \begin{align}
        A(r)
		=k_T (3 \left\vert r\right\vert^2I-2r\otimes r) , \qquad
		k_T=\dfrac{\lambda}{\tau}.      
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:fBm peturbed lattice of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] Let $\xi$ be a stationary point process with intensity $1$ and finite second moment, \textit{i.e.}
		\begin{equation*}
			\@ifnextchar[{\@withe}{\@withoute}{\xi(K)^{2}}<+\infty, \quad K \text{ compact }, 
		\end{equation*}
		and $\hat{\xi}$ be its Palm distribution. If $B$ is a $d$-fBf independent of $\hat{\xi}$, then 
		\begin{enumerate}[(i)]
			\item $\hat{\xi}_{B} = \{x + B_{x} : x \in \hat{\xi}\}$ is the Palm distribution of an ergodic point process $\xi_{B}$ with intensity $1$,
			\item the Bartlett's spectrum of $\xi_{B}$ is absolutely continuous with respect to Lebesgue measure and its density (also known as \emph{structure factor}) is given by
			\begin{equation}
				s_{\xi_{B}}(t) = \@ifnextchar[{\@withe}{\@withoute}{\int_{\mathbb{R}^{d}}e^{-\frac{1}{2}(\Sigma_{x}t,t)}e^{-i( t,x)} \, \hat{\xi}(\mathrm{d}x)}, \quad t\neq 0,
			\end{equation} 
			which converges absolutely on all compact subsets of $\mathbb{R}^{d}\backslash\{0\}$. Here, $\hat{\xi}$ is identified with a discrete measure.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Global1 of arXiv:2605.10309, 'Exponential Decay of $L^2$-Solutions to Stochastic Nonlinear Schr\"odinger Equations Drive'] Assume (H1),(H2) with $r_j=\infty$ for all $j$ and (H3).
