body:
[Lem 8 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For $K=O(\log N)$, let $Y_x$ denote the number of strings with prefix $x$ in $S_K$. Let $T_q$ be the set of all strings $x$ such that $\mathbb EY_x\geq N^q$.
		 Then there exist constants $C,c$ such that for all $a>0$,
	\begin{equation}
			\mathbb P(|Y_x-\mathbb EY_x|\leq CK(\mathbb EY_x)^{1/2+a})\geq 1- C\exp(-c(\mathbb EY_{x})^{2a}).
		\end{equation}
        Moreover,
        \begin{equation}
			\mathbb P(|Y_x-\mathbb EY_x|\leq CK(\mathbb EY_x)^{1/2+a}, \mbox{ for all }x \in T_q)\geq  1 - C\exp(-cN^{2qa}).
		\end{equation}

[Lemma 5 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, $D\subset \widetilde{\mathbb{Z}}^d$ and $v,w\in \widetilde{\mathbb{Z}}^d\setminus D$ with $|v-w|\ge d$, 
	\begin{equation}
		\mathbb{K}_{D\cup \{v,w\}}(v,w)\asymp \big[ \widetilde{G}_D(w,w)\big]^{-1}\cdot \widetilde{\mathbb{P}}_w\big( \tau_v<\tau_D \big). 
	\end{equation}

