body:
[Defn of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] A \textbf{generalized coarse slope} is an element of $\mathbb{R} \cup \{\pm \infty,\aleph\}$. A \textbf{generalized fine slope} is a coarse slope, plus a type in $\{\natural, \dagger, \sharp, \flat\}$. The meaning of $s^\heartsuit$ for $\heartsuit \in \{\natural, \dagger, \sharp, \flat\}$ remains the same as in \zcref{sec:T2foliations}, and we define the generalized fine slope of a $\Phi$-horizontal foliation $\mathcal{G}$ with a Reeb annulus as follows:

    \begin{enumerate}
        \item $\aleph^\natural$ if $\mathcal{G}$ has neither $+\infty^\sharp$ nor $-\infty^\flat$ annuli. This class was simply called $\aleph$ in the body of the article.
        \item $\aleph^\sharp$ if $\mathcal{G}$ has a $+\infty^\sharp$ annulus, but no $-\infty ^\flat$ annuli.

        \item $\aleph^\flat$ if $\mathcal{G}$ has a $-\infty^\flat$ annulus, but no $+\infty^\sharp$ annuli.

        \item $\aleph^\dagger$ if $\mathcal{G}$ has both $+\infty^\sharp$ and $-\infty^\flat$ annuli.
    \end{enumerate}
    We write $\mathscr{S}$ for the space of real fine slopes $\mathbb{R} \times \{\natural, \dagger, \sharp, \flat\}$, and $\widehat{\mathscr{S}}$ for the space of generalized fine slopes $(\mathbb{R} \cup \{-\infty, +\infty, \aleph\}) \times \{\natural, \dagger, \sharp, \flat\}$.\footnote{If preferred, $+\infty^{\sharp/\natural}$ and $-\infty^{\flat/\natural}$ may be excluded from $\widehat{\mathscr{S}}$ as they do not occur as fine slopes of $\Phi$-horizontal foliations.}

[Theorem th:path_localisation of arXiv:2608.06263, 'Almost sure path localisation for the derivative martingale of branching Brownian motion'] Let $a,b$ be functions $\mathbb{R}_{\ge0} \to \mathbb{R}_{\ge 0}$ satisfying $a \downarrow 0$ and $b \uparrow \infty$.
Then, almost surely,
\begin{equation}
\lim_{r \to \infty} \lim_{t \to \infty} \sum_{u \in \mathcal{N}_t} X_u(t) \mathrm{e}^{-X_u(t)} \1_{\{\forall s \in [r,t], X_u(s) \in [a(s)\sqrt{s},b(s)\sqrt{s}]\}} = \begin{cases}
    Z_\infty &\text{ if (equation eq:integrability_conditions of the paper) holds,} \\ 0 &\text{ otherwise.}
\end{cases} 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:abstract-active-response-multiplicity of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] The active response family satisfies
\begin{equation}
 \mathcal N_\mu(\Lambda)\text{ is a singleton}
 \quad\Longleftrightarrow\quad r=1.

\end{equation}

[Proposition prop:kernel of arXiv:2607.12564, 'Power-law and log-periodic degree tails for a family of probability generating function eq'] Let $\varphi(t)=\mathbb{E} e^{-tW}$ and $y(t)=1-\varphi(t)$, so the Laplace fixed point reads
\begin{equation}
  y(\lambda t)=\lambda\,y(t)-p\,y(t)^2=y(t)\bigl(\lambda-p\,y(t)\bigr).
\end{equation}
Then, for every $m\in\mathbb{Z}$, with $z_m:=\rho+i\chi m$ and $C(z):=1/\Gamma(-z)$,
\begin{equation}
  \mathbb{E}[W^{z_m}]=C(z_m)\int_0^\infty y(t)^2\,t^{-z_m-1}\,dt .
\end{equation}
Writing $t=\lambda^{v}$ and $H_p(v):=\lambda^{-\rho v}\,y(\lambda^{v})^{2}\ge0$, (equation eq:ysquare of the paper)
reads $\mathbb{E}[W^{z_m}]=C(z_m)\log\lambda\,\widehat H_p(m)$, $\widehat H_p(m)=\int_\mathbb{R} H_p(v)e^{-2\pi imv}dv$;
since $C(z_m)\ne0$, (cor:const of the paper) and (prop:reduce of the paper) show that, for $j\in\{1,2\}$, $\Psi_j$
is constant iff the periodization
$\mathcal P_p(u):=\sum_{n\in\mathbb{Z}}H_p(u+n)$ is constant. Moreover the unit-shift ratio of $H_p$,
\begin{equation}
  \frac{H_p(v+1)}{H_p(v)}=\lambda^{2-\rho}\Bigl(1-\tfrac{p}{\lambda}\,y(\lambda^{v})\Bigr)^{2}
\end{equation}
is strictly decreasing in $v$, from $\lambda^{2-\rho}>1$ (as $v\to-\infty$) to $\lambda^{-\rho}<1$
(as $v\to+\infty$).

[Theorem thm:correlation_kernel of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$\rho_k^{\operatorname{Int}}=\rho_{k,N}^{\operatorname{Int}}$ be the~$k$th correlation function associated to the point process~$\{u_s^t\}_{1\leq s\leq t\leq 2\ell N}$. For~$k$ black points~$(\ell x_p+i_p,2y_p+j_p)$,~$p=1,\dots,k$, where~$x_p=0\dots,2N-1$,~$i_p=0,\dots,\ell-1$,~$y_p=0,\dots,\ell N-1$, and~$j_p=0,1$, we have
\begin{multline}
\rho_k^{\operatorname{Int}}\left(\ell x_1+i_1,2y_1+j_1;\dots;\ell x_k+i_k,2y_k+j_k\right) \\
=\det\left(K_{\operatorname{Int}}\left(\ell x_p+i_p,2y_p+j_p;\ell x_{p'}+i_{p'},2y_{p'}+j_{p'}\right)\right)_{p,p'=1}^k,
\end{multline}
where
\begin{multline}
\left[K_{\operatorname{Int}}(\ell x+i,2y+j;\ell x'+i',2y'+j')\right]_{j',j=0}^1 \\
= -\frac{\one_{\ell x+i>\ell x'+i'}}{2\pi\mathrm{i}}\int_{\tilde \Gamma_l}\left(\prod_{m=1}^{2i'}\phi_m(z)\right)^{-1}Q(z,w)\prod_{m=1}^{2i}\phi_m(z)w^{x-x'}z^{y'-y}\frac{\,\mathrm{d} z}{z} \\
+\frac{1}{(2\pi\mathrm{i})^2}\int_{\tilde \Gamma_s}\int_{\tilde \Gamma_l}\left(\prod_{m=1}^{2i'}\phi_m(z_1)\right)^{-1}Q(z_1,w_1)Q(z_2,w_2)\prod_{m=1}^{2i}\phi_m(z_2) \\
\times \frac{(z_2-1)^{\ell N}}{(z_1-1)^{\ell N}}\frac{w_2^{x-N}}{w_1^{x'-N}}\frac{z_1^{y'}}{z_2^y}\frac{\,\mathrm{d} z_2\,\mathrm{d} z_1}{z_2(z_2-z_1)}.
\end{multline}
The contours~$\tilde \Gamma_l$ and~$\tilde \Gamma_s$ are simple closed positively oriented curves in~$\mathcal R$ containing~$p_0$ and~$q_\infty$ in their interior, and~$p_\infty$ and~$q_0$ in their exterior. Moreover,~$\tilde \Gamma_s$ is contained in the interior of~$\tilde \Gamma_l$.

