 \item[{\rm (i)}] $C_{\rm b}(m,p; F)$ satisfies {\rm ({\red SD})} for any $p\in (0,1)$ if and only id $F\in \mathcal{H}$.
 \item[{\rm (ii)}] $C_{\rm b}(n,p; F)$ satisfies {\rm ({\red ${\rm SD}^*$})} for any $p\in (0,1)$ if and only if $F\in \mathcal{H}^*$.
\end{itemize}

