[Proposition 60 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Lemma \ref{Lem.PrelimitKernelEdge}, where for each $s \in \mathcal{T}$, we set $\theta_s = \theta_0$, $R_s = R_0$ as in Lemma \ref{Lem.BigContour} for $\kappa = s$. If $x_N, y_N \in \mathbb{R}$ are sequences such that $\lim_{N \rightarrow \infty} x_N = x$, $\lim_{N \rightarrow \infty} y_N = y$, then for any $s,t \in \mathcal{T}$
\begin{equation}
\begin{split}
&\lim_{N \rightarrow \infty} K_{11}^N(s,x_N;t,y_N) = 0, \hspace{2mm} \lim_{N \rightarrow \infty} K_{22}^N(s,x_N;t,y_N) =  0,\\
& \lim_{N \rightarrow \infty} K^N_{12}(s,x_N; t,y_N) =  \kbm\left(\bar{\kappa} - s,  x  ; \bar{\kappa} - t, y  \right), 
\end{split}
\end{equation}
where 
\begin{equation}
\kbm\left(s,  x  ; t, y  \right) = \frac{e^{-x^2/2s}}{\sqrt{2\pi s}} - {\bf 1}\{s > t\} \cdot \frac{e^{-(x-y)^2/2(s-t)}}{\sqrt{2\pi (s-t)}}.
\end{equation}

[Lemma lem:admi_expo_exp of arXiv:2607.04514, 'Boundary-layer asymptotics for Gaussian-smoothed singular measures'] Assume (ass:standing of the paper)~(ass:standing:chart of the paper){} with \(r\geqslant 2\). Let \(A,\sigma_0>0\) and \(R_0\in(0,4R)\). Then there
  exists \(\mathscr R_\Psi\in \mathfrak P_{r-2}\) defined on \(\mathcal
  D_{R_0,A,\mathcal{K}_{\mathcal{S}},\sigma_0}\), such that, for \(x = \varphi(\theta)\),
  \begin{equation}
    \Psi_\sigma(\zeta;a,x) = \frac{\| y_\sigma(a,x)
    - M(\theta, \sigma\zeta)\|^2}{2\sigma^2} =\Psi(\zeta;a,x) +
    \frac{\sigma}{2}\,\Lambda_x (\zeta;a) + \sigma^2 \mathscr R_\Psi(\zeta;a,x,\sigma).
  \end{equation}
  Moreover, there exists a constant \(C_A>0\) such that, uniformly on \(\mathcal
  D_{R_0,A,\mathcal{K}_{\mathcal{S}},\sigma_0}\),
  \begin{equation}
    |\mathscr R_\Psi(\zeta;a,x,\sigma)| \le C_A(1+\|\zeta\|^6).
  \end{equation}

