[Corollary 19 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] We keep the assumptions and the notation of Proposition \ref{rwergo}. Let $F \! :\! \obbT^\bullet\! \to \bbR$ be 
a measurable function 
such that $\bE [|F(\bT, \boo)|] \leko \infty$ and such that $F(T, \boo) \eqo F(\mathtt{cent} (T, o))$ for all $(T, o)\ino   \obbT^\bullet\!$. Then 
\begin{equation}

\textrm{$\bP$-a.s.~} \quad \lim_{n\to \infty} \frac{1}{n} \sum_{0\leq k<n} F \big( \bT, X_k \big) = \bE \big[ F(\bT, \boo)\big] \; . 
\end{equation} 
Moreover, if  $F$ is nonnegative and if there is $\ttb\ino (1, \infty)$ such that $\bE [F(\bT, \boo)^\ttb] \leko \infty$, then 
\begin{equation}

\textrm{$\bP$-a.s.~} \quad  \sup_{n\in \bbN^*} \frac{1}{n} \sum_{0\leq k<n} E_{\bT, \boo} \big[ F \big( \bT, X_k \big) \big]  <\infty \; .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition defsDF of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For each diagram $\Gamma$, we define its associated diagram function as
\begin{equation}
F_{\Gamma}(\{n_j\}) := F_{\Gamma,\Sigma}(\{n_j\}) =
\sum_{\eta: V(\Gamma) \to [N]}
\sum_{\substack{
t_j \ge 0,\; w_e \ge 1 \\
2t_j + \sum\limits_{e \in \partial D_j} w_e = n_j
}}
\Bigg(
\prod_{(x, y) \in E_{\mathrm{int}}}
p_{w_e}\big(\eta(x), \eta(y)\big)
\prod_{(z, w) \in E_{\mathrm{b}}}
\big(A^{w_e}\big)_{\eta(z)\eta(w)}
\Bigg),
\end{equation}
where the second summation runs over all integers \( t_j \ge 0 \) and \( w_e \ge 1 \) satisfying the constraint \( 2t_j + \sum_{e \in \partial D_j} w_e = n_j \) for every $j$.
Analogously, the corresponding diagram function for the variance profile $\widetilde{\Sigma}$ is denoted by $\widetilde{F}_{\Gamma}(\{n_j\})= F_{\Gamma,\widetilde{\Sigma}}(\{n_j\})$.

[Proposition 29 (Deterministic bias, fully overdamped regime) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Under Assumptions~\ref{ass:diagonal-covariance} and~\ref{ass:power-law}, in the fully overdamped regime $\eta\lambda_1\le c_0(1-\rho)^2$ with a sufficiently small universal constant $c_0>0$, we have:
\begin{equation*}
    \cS_{\nesterov}(k)
    \eqsim
    \begin{cases}
    1,&\qquad k\lesssim \frac{1-\rho}{\eta},\\
    \left(\frac{1-\rho}{\eta k}\right)^s, &\qquad k\gtrsim\frac{1-\rho}{\eta}.\\
    \end{cases}
\end{equation*}

[Proposition prop:full-Jacobi-Gamma of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] In the coordinates (equation eq:Gamma-normal-cone of the paper),
\begin{equation}
 J_{F,\Gamma}
 =\frac{\sqrt2}{2}e^{-2t}
 \left[4\phi''(1)(\partial_t^2+\partial_t)+\Delta_\Lambda+2\right]
 +\mathcal R_\Gamma
\end{equation}
has $O(2)\times O(2)$ symmetry. Here $\mathcal R_\Gamma$ is a second-order operator whose coefficients, together with the derivatives needed below, are $O(e^{-(3+\mu)t})$.

[Lemma 9 of arXiv:2605.31374, 'Multi-point functions of a full-plane two-state\\ fuzzy $4$-Potts model'] For every $n\in 2\N$, $\xi\in\Xi_0$, distinct points $x_1,\dots,x_n\in\R^2$, and $0<\eps\leq \min_{i\neq j}\{|x_i-x_j|\}/2$, let $F_{x,\xi,\eps}$ be given as in~\eqref{e.F_xi,eps=} and we have
\begin{align*}
    \lim_{\delta\to0}\phi_{\delta\Z^2}\Ll[\mathcal{A}_{F_{x,\xi,\eps}}(\mcl L)\Rr] & =\exp\left( \frac{1}{2\pi^2}\iint F_{x,\xi,\eps}(\rz)F_{x,\xi,\eps}(\rz')\log|\rz-\rz'|\d\rz\d\rz'\right) \\
    &= \eps^\frac{n}{8}e^{nc_0}\prod_{1\leq i<j\leq n}\Ll(|x_i-x_j|^{\frac{\xi_i\xi_j}{4}}e^{2\xi_i\xi_jc_\eps(x_i-x_j)}\Rr)
\end{align*}
where the convergence is uniform over $(x_1,\dots,x_n)\in(\R^2)^n$ satisfying $\max_i|x_i|\leq 1/\dst$ for any $\dst\in(0,1)$; the constant $c_0$ is given as in Proposition~\ref{p}; and we have set
\begin{align*}
    c_\eps(v)  := \frac{1}{8\pi^2}\iint_{B_1(0)\times B_1(0)}\log\frac{|v+\eps(\rz-\rz')|}{|v|}\d\rz\d\rz',\qquad\text{for every $v\in\R^2\setminus\{0\}$ and $\eps>0$.}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2606.12381, 'Markov property and path regularity for the solutions to SPDEs driven by cylindrical-marti'] Let $0 \leq t_{0} \leq T$. For any two $G$-valued $\mathcal{F}_{t_{0}}$-measurable square integrable random variables $\xi$ and $\eta$, there exists $C_{T}>0$ such that 
\begin{equation*}
 \Exp \norm{ X(t,t_{0};\xi) -X(t,t_{0};\eta) }^{2}_{G}   \leq 
 C_{T} \Exp \norm{\xi-\eta}^{2}_{G}. 
\end{equation*}

