[Thm 14 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that hypotheses \ref{H0}, \ref{H1}, \ref{H2b}, \ref{H3} and \eqref{eq:cond-1} hold. For every $n\in\N$, $k\in\{1,\ldots,n\}$, $i\in\{-,+\}$ and $g:[0,T]\times H_n\rightarrow \R$ continuous such that 
\[
\sup_{t\in [0,T]}\norm{g(t,\cdot)}_{C^\theta_b(H_n)}<\infty,
\]
let $\mathfrak c>{\mathfrak c}_0$ and let $u_{n,k}^{(i)}$ be the unique solution to \eqref{Def:Unki} given by Theorem \ref{Thm: soluzione-kolmogorov}.\\
Then, there exists a sequence $\{f_{n,k,h}\}_{h\in\N}\subseteq C^{0,2}_b([0,T]\times H_n)$ such that:
\begin{enumerate}
\item 
$\displaystyle 
\sup_{h\in\N}\sup_{t\in[0,T]}\|f_{n,k,h}(t,\cdot)\|_{C_b^\theta(H_n)}<\infty$ and
\begin{align}
\lim_{h\rightarrow\infty}\norm{f_{n,k,h}(t,\cdot)-\scal{\mathcal{V}_n^*\nabla_x u^{(i)}_{n,k}(t,\cdot)}{C_n(t,\cdot)}_{U}-g(t,\cdot)}_{C_b(H_n)}=0, \qquad t\in[0,T];
\end{align}
\item  for every $h\in\N$, the parabolic equation 
\begin{equation}

\begin{cases}
\frac{\partial}{\partial t}v(t,x)+L_nv(t,x)=-f_{n,k,h}(t,x)-{\mathfrak c}\lambda_{k}^{(i)}v(t,x), & (t,x)\in[0,T)\times H_n, \\[1mm]
 v(T,x)=0, & x\in H_n,
\end{cases}
\end{equation}
has a unique strict solution $u^{(i)}_{n,k,h}\in C^{1,2}_b([0,T]\times H_n)$ given by
\begin{align}
u^{(i)}_{n,k,h}(t,x)=\int_{t}^Te^{{\mathfrak c}(s-t)\lambda_k^{(i)}}(R_n(s-t)f_{n,k,h}(s,\cdot))(x)ds, \qquad (t,x)\in[0,T] \times H_n;
\end{align}
\item for every $t\in [0,T]$ we have
\begin{align}
&\lim_{h\rightarrow \infty}\norm{u^{(i)}_{n,k,h}(t,\cdot)-u^{(i)}_{n,k}(t,\cdot)}_{C^1_{b,\mathcal{V}_n}(H_n)}=0,\\
&\lim_{h\rightarrow \infty}\norm{\mathcal{G}_n^*\nabla u^{(i)}_{n,k,h}(t,\cdot)-\mathcal{G}_n^*\nabla u^{(i)}_{n,k}(t,\cdot)}_{C_{b}(H_n;U)}=0.
\end{align}

\end{enumerate}

[Lemma 6 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] Fix $i\in[3]$. There exists $C<\infty$ such that, for every $p=(p^1,p^2,p^3)\in\mathbb T^3$ satisfying $\sin(p^i/2)\neq0$, every $\lambda>0$, and every $\kappa\ge1$, we have
\begin{equation*}
\sin^2(p^i)\left(\int_{\mathbb T_i^3}\frac{\rmd q}{\lambda+\kappa\theta(p+q)}\right)\left(\int_{\mathbb T_i^3}\frac{\rmd q}{\theta(p+q)}\right)\le\frac{C}{\kappa}.
\end{equation*}

