body:
[Lemma 17 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Let $B=B_r(0)$ and let $F:\ZZ^d\to\RR$ be a non-negative function.
    \begin{enumerate}[label=(\alph*),ref=\thelemma(\alph*)] 
        \item 
        If $r\ge2\rd(0)$, then
        \begin{equation}
                \fint_{\frac12 B}F\,\lesssim\, \fint_{x\in B}\fint_{B_\diamond(x)}F\,\lesssim\, \fint_{2B}F.
        \end{equation}
        \item 
         If $r\le 2\rd(0)$, then for any $p\in(0,1)$,
        \begin{equation}
            \sup_{x\in B}\Big(\fint_{B_{{\diamond}}(x)} F\Big)^p\,\lesssim \,\fint_{x\in 5B}\Big(\fint_{B_{{\diamond}}(x)} F\Big)^p.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 (Recentering of $\Pi^-$, Step 2.c) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $[\beta]\geq0$ and assume that $(\Gamma_{xy}\Pi_y)_{\beta'}=\Pi_{x\beta'}$ for all populated $\beta'\prec\beta$.
Then for every $c^{(k')}\in\RR[\![z_k]\!]$, we have

\begin{align}
(\Gamma_{xy}\Pi_y^-)_\beta 
&= \Pi_{x\beta}^- 
+ \Big( 
\sum_{k \geqslant \kk} \ve^{(\kk-k)\alpha} T_x^{<|\cdot|-2}\big(z_k W_{k, \varepsilon}(\Pi_x)\big)\Big)_\beta  \\
&\hphantom{= \Pi_{x\beta}^-\ }
- \Big(\Gamma_{xy} 
\sum_{ k \geqslant \kk} \ve^{(\kk-k)\alpha} T_y^{<|\cdot|-2}\big(z_k W_{k, \varepsilon}(\Pi_y)\big)\Big)_\beta \\ 
&=\Pi_{x\beta}^- 
+ \Big(
\sum_{ k \geqslant \kk} \ve^{(\kk-k)\alpha} (T_x^{<|\cdot|-2}-T_y^{<|\cdot|-2}) \big(z_k W_{k,
\varepsilon}(\Pi_x)\big)\Big)_\beta \\
&\hphantom{=\Pi_{x\beta}^-\ }
+ \Big( \Gamma_{xy} 
\sum_{ k \geqslant \kk} \ve^{(\kk-k)\alpha} (T_y^{<|\beta|-2}-T_y^{<|\cdot|-2})
\big(z_k W_{k, \varepsilon}(\Pi_y)\big) \Big)_\beta \, . 
\end{align}

In particular, $(\Gamma_{xy}\Pi^-_y-\Pi^-_x)_\beta$ is a (random) polynomial of degree $<|\beta|-2$.

[Lem 121 ({\cite{DLE}}) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] The following statements hold for any $(x, y) \in \overline{\mathfrak{L}}_{q;a,b,c}$.

		\begin{enumerate} 

			\item We have that  
			\begin{flalign}

				\arg f (x,y) = \pi (1 - \partial_y \mathcal{H}_{q;a,b,c} (x,y)); \qquad \arg (f (x,y)-1) = \pi (1 + \partial_x \mathcal{H}_{q;a,b,c} (x,y)).
			\end{flalign} 

			\item We have that $(x, y) \notin \mathfrak{L}_{q;a,b,c}$ if and only if $f(x, y) \in \mathbb{R}$. 

			\item We have that $(x,y) \in \mathfrak{L}_{q;a,b,c}$ if and only if both roots of \eqref{equationu} are not real. Moreover,  $(x, y) \in \mathfrak{A}_{q;a,b,c}$ if and only if \eqref{equationu} has a double (real) root for $u$.

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] {For each fixed $m\in \N$}, $\wtilde{M}_m(t)$ defined in \eqref{eqn-martingale} is a square integrable martingale with respect to the filtration $\wtilde{\Fb}_m=\{\wtilde{\Fn}_{m,t}\}_{t\in[0,T]}$, here $\wtilde{\Fn}_{m,t}=\sigma\{\wtilde{u}_m(s), s\leq t\}$ with the quadratic variation
				\begin{align}
					\llbracket \wtilde{M}_m \rrbracket_t = \sum_{i=1}^M \int_0^t  \|{S_{m-1}} \Nn_i(\wtilde{u}_m(s)) \|_{L^2(\bO)}^2 ds.
				\end{align}

