body:
[Lemma 20 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For any fixed $i\ge1$ and $\eps>0$,
there exist constants $C_{\cdot}$ and $c_{\cdot}$ (that may depend on $i$ and $\eps$)
such that for all $n\ge i$ and $k\ge0$,
\begin{align}
{\mathbb P}[M_{n,i}(\tau_n)-b_n>k]&
\leq  \CC e^{-(1-\varepsilon)k/e},
\\
{\mathbb P}[M_{n,i}(\tau_n)-b_n\le-k]&
\leq  \CC e^{-\cc e^{\ccname{\ccb} k}}
\leq  \CC e^{- k}
.\end{align}

[Lemma 96 of arXiv:2601.16377, '2601.16377'] Take two variational data satisfying Assumptions~\ref{Assumption_A} and \ref{Assumption_B} with $\iota_h^{-,\textnormal{I}}=\iota_h^{-,\textnormal{II}}=2$, differing by their segment endpoints $\hat{a}_{h}^{\prime\,\textnormal{I}}$ and $\hat{a}_{h}^{\prime\,\textnormal{II}}$ for a single $h \in [H]$, and by the potentials
\begin{equation*}
\begin{split}
V_h^{\textnormal{I}}(x) & = -2\, \mathrm{Llog}(x - \hat{a}_{h}^{\prime\,\textnormal{I}}) + V_h^0(x), \\
V_h^{\textnormal{II}}(x) & = -2 \,\mathrm{Llog}(x - \hat{a}_{h}^{\prime\,\textnormal{II}}) + V_{h}^{0}(x).
\end{split}
\end{equation*}
Assume furthermore that $\boldsymbol{\mu}^{\textnormal{I}}$ satisfies Assumption~\ref{Assumption_C} and $\hat{a}_{h}^{\prime\,\textnormal{I}}$ belongs to a saturation of $\boldsymbol{\mu}^{\textnormal{I}}$. Then, there exists $M > 0$ depending only on the constants in the assumptions, such that for $|\hat{a}_{h}^{\prime\,\textnormal{I}} - \hat{a}_{h}^{\prime\,\textnormal{II}}| < \frac{1}{M}$ and for any measurable function $f$ with finite $|\!|f|\!|_{\frac{1}{2}}$ we have
\begin{equation}

 \bigg| \int_{\amsmathbb R} f(x)\dd(\mu^{\textnormal{I}}-\mu^{\textnormal{II}})(x)\bigg| \leq M \cdot \big(|\!|f|\!|_{\frac{1}{2}} + |\!|f|\!|_{\infty}\big) \cdot |\hat{a}_{h}^{\prime\,\textnormal{I}} - \hat{a}_{h}^{\prime\,\textnormal{II}}|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop grad-B of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] Fixed $L\in\mathbb{N}$, shorten ${\langle \eta\rangle}_L=\tfrac{1}{L+1}\sum_{z\in \llbracket 0,L\rrbracket}\eta(z)$ for the density in the box $\llbracket 0,L\rrbracket$. For any $n\leq L$ it holds that
\begin{align}
    \mathbf{b}_{n,L}(\eta)
    (\mathbf{e}_{0,1}(\eta)-\mathbf{e}_{1,0}(\eta))
    =-\nabla\mathbf{H}_{n,L}(\eta)
\end{align}
with $\mathbf{H}_{n,L}=\mathbf{h}_{n,L}+\mathbf{g}_{n,L}$ and
\begin{align}
    \mathbf{h}_{n,L}(\eta)





















    &=
    \frac{1}{L+1}\mathbf{1}{
    \big\{
    {\langle \eta\rangle}_{L}\geq\tfrac{n+1}{L+1}
    \big\}
    }








    ,
    \\
    \mathbf{g}_{n,L}(\eta)
    &=\frac{1}{L+1}\sum_{j=1}^{L}
    \sum_{i=1}^{j}
    \mathbf{b}_{n,L}^j(\tau^{-i}\eta)
    (\mathbf{e}_{0,1}(\tau^{-i}\eta)
    -\mathbf{e}_{1,0}(\tau^{-i}\eta)
    )

    .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 74 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Take $x,y\in K$ and $x_n,y_n\in V_n$ satisfying $R(y,y_n),R(x,x_n)\lesssim R_H(K,V_n)\lesssim (3/5)^n$ 
and set
\begin{equation*}
  E_{\rm{sg},1}=\frac{\kappa^2}{\kappa+(2+\kappa)\log_{\frac{5}{3}}5},
\qquad
  E_{\rm{sg},2}=\frac{\kappa (2+\kappa)\log_{\frac{5}{3}}3}{\kappa+(2+\kappa)\log_{\frac{5}{3}}5},
\end{equation*}
\begin{equation*}
  E_{\rm{hk},1}=\frac{\kappa}{(2+\kappa)\log_{\frac{5}{3}}5+\frac{1}{2}\log_{\frac{5}{3}}3+1},
  \;\;\text{and}\;\; E_{\rm{hk},2}=(2+\kappa)\log_{\frac{5}{3}}5
\end{equation*}
Then, for any $f\in\BL^{\kappa}$, it holds that
\begin{align*}
  |P_tf(x)-P^n_tf(x_n)|\lesssim \|f\|_{\BL^{\kappa}} \left(\frac{3}{5}\right)^{nE_{\rm{sg},1}}n^{E_{\rm{sg},2}},\;\;\rm{and}\;\;
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim \left(\frac{3}{5}\right)^{nE_{\rm{hk},1}}n^{E_{\rm{hk},2}},
\end{align*}
for any $t>0$ and $\kappa\in [1/2,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 (Component sizes and susceptibility) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] For every $x\in V$,
\begin{equation}
  \Ee[\pi(C_q(x))]
  \leq
  \sum_{z\in V}h_q(x,z)
  \sum_{y\in V}\pi(y)h_q(y,z).
\end{equation}
Define $ \chi_q
  :=\sum_{x,y\in V}\pi(x)\pi(y)\Pp(x\leftrightarrow_q y).$
Then, it comes
\begin{equation}
  \chi_q
  \leq
  \sum_{z\in V}
  \left(\sum_{x\in V}\pi(x)h_q(x,z)\right)^2.
\end{equation}
If $M_q:=\max\{\pi(C) \mid C\text{ component of }F_q\}$
then, for every $a>0$, we get:
\begin{equation}
  \Pp(M_q\geq a)
  \leq\frac{\chi_q}{a^2}
  \leq
  \frac{1}{a^2}
  \sum_{z\in V}
  \left(\sum_{x\in V}\pi(x)h_q(x,z)\right)^2.
\end{equation}
Finally, for $U\subset V$, it results:

\begin{equation}
  \Pp(C_q(x)\cap U\neq\emptyset)
  \leq
  \sum_{y\in U}\sum_{z\in V}h_q(x,z)h_q(y,z).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 (Exact matrix-scale data) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Under W3, W4, W5, and the spike assumption, the array
\(M_N^{(4)}\) has the following properties for all sufficiently large \(N\):
\begin{enumerate}[label=(A\arabic*)]
\item its upper-triangular entries are independent and uniformly bounded after
      multiplication by \(\sqrt N\);
\item its deterministic mean matrix is exactly that of \(M_N^f\);
\item its centered variance profile is exactly that of \(M_N^f\);
\item its edgewise third and fourth cumulants are exactly those of the target;
\item
\begin{equation}
 \max_{i<j}
 \left|
 \cum_4(\widehat Y_{s_{ij}})-\kappa_4^{f,\nu}
 \right|\longrightarrow0;
\end{equation}
\item the fourth-moment Lindeberg condition is eventually identically zero.
\end{enumerate}

