[Theorem thm:near_critical of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] Let $d>8$
and $L \ge L_0$ with $L_0$ sufficiently large.
For both lattice trees and lattice animals,
there are constants $c \in (0,1)$ (independent of $L$)
and $C_L, \delta_L > 0$ such that
\begin{equation} 
    G_p(x) \le \frac{C_L}{|x|^{d-2}} e^{-cm(p)|x|}
\end{equation}
for all $p \in [p_c - \delta_L, p_c)$ and for all $x \in \mathbb{Z}^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.26565, 'A Horizon-Free Extrinsic Penrose Inequality'] If $0<s<t<t_0$, then
\begin{equation}
 G_t\subset G_s,
 \qquad E_s\subset E_t

\end{equation}
almost everywhere.  Moreover,
\begin{equation}
 \frac1{\cosh s}\sqrt{\frac{|\Sigma_s|}{\pi}}
 \leq
 \frac1{\cosh t}\sqrt{\frac{|\Sigma_t|}{\pi}}.

\end{equation}

[Proposition 10 (Pinching estimate) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Let $n=7,8$ and let $C(b)$, $\tilde C(b)$, $b_{max,2}$ and $\tilde b_{max,2}$ be as in
        Definitions \ref{def:pinchingCones1} and \ref{def:pinchingCones2}. Put
        $B_n:=b_{max,2}+\tilde b_{max,2}$ and define
        \begin{equation}
            \hat C(\beta):=
            \begin{cases}
                C(\beta),& 0<\beta\le b_{max,2},\\
                \tilde C(B_n-\beta),& b_{max,2}<\beta<B_n.
            \end{cases}
        \end{equation}
        Then $\{\hat C(\beta)\}_{0<\beta<B_n}$ is a continuous family of closed convex
        $O(n)$-invariant cones, each transversally invariant under $\dt R=Q(R)$, with the two
        properties
        \begin{enumerate}
            \item \emph{(Entry.)} For every $\theta>0$ and $N>0$ there exists $\beta_0>0$ such that
            \begin{equation*}
            \begin{split}
                \{R:R-\theta\Scal(R)\,\mathrm{id}\wedge\mathrm{id}\in\CPIC\}&\cap
                \{R:\Ric(R)_{11}+\Ric(R)_{22}-\theta\Scal(R)+N\ge0\}\\
                &\subset\{R:R+N\,\mathrm{id}\wedge\mathrm{id}\in\hat C(\beta_0)\}.
            \end{split}
            \end{equation*}
            \item \emph{(Pinching.)} If $\beta_j\nearrow B_n$, there are $\varepsilon_j\searrow0$ with
            \begin{equation*}
                \hat C(\beta_j)\subset
                \{R:R+\varepsilon_j\Scal(R)\,\mathrm{id}\wedge\mathrm{id}\in\CPICone\}.
            \end{equation*}
        \end{enumerate}
        Consequently, for every compact $K\subset\operatorname{int}\CPIC$ and every $T>0$ there exist
        $\theta>0$, $N>0$, an increasing concave function $f>0$ with $\lim_{s\to\infty}f(s)/s=0$, and a
        continuous family $\{F_t\}_{t\in[0,T]}$ of closed convex $O(n)$-invariant sets, invariant under
        $\dt R=Q(R)$, with $K\subset F_0$ and
        \begin{equation}
        \begin{split}
            F_t\subset{}&\{R:R-\theta\Scal(R)\,\mathrm{id}\wedge\mathrm{id}\in\CPIC\}\cap
            \{R:\Ric(R)_{11}+\Ric(R)_{22}-\theta\Scal(R)+N\ge0\}\\
            &\cap\{R:R+f(\Scal(R))\,\mathrm{id}\wedge\mathrm{id}\in\CPICtwo\}
        \end{split}
        \end{equation}
        for all $t\in[0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_apply_conc of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] There exists~$C_{\mathrm{dev}} \ge 1$ such that the following holds. Let~$x \in \R^d$ with~$\|x\| \ge 1$ and~$t \in [1,\|x\|]$. Then, 
	\begin{equation*}
		\E\left[\exp \left\{ \alpha \cdot | \E[Y_{t,x}]-Y_{t,x} |\right\}\right] \le   \exp \left\{C_{\mathrm{dev}} \alpha^2 t~\|x\| \right\} \quad \text{for any }\alpha \in \left(0,\tfrac{1}{4\K t}\right).
	\end{equation*}

[Lemma 24 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same setup as in Lemma~\ref{lem::reg_Dirichlet_annular}. 
The regularized Dirichlet energy and the partition function have the following asymptotics as $r\to\infty$: 
\begin{align} 
\begin{split}
	\| \varphiann{n} \|_{\nabla(\A_r),\mathrm{reg}}^2=& -n\pi r -2\pi \sum_{1\le i<j\le n} (-1)^{j-i} \left( \log \sin \left( \frac{\beta_{j}-\beta_i}{2} \right) + \log \sin \left( \frac{\alpha_{j}-\alpha_i}{2} \right) \right) \\
	& + 2\pi n\log 2 +\frac{\pi}{2r}\left(\sum_{j=1}^{n}(-1)^j (\alpha_j-\beta_j) \right)^2+ O(1)\ee^{-r};
\end{split}\\

\LZann{n}(r; \bs{\alpha}, \bs{\beta})=&\frac{\LZ_n(\bs{\alpha})\LZ_n(\bs{\beta})}{\sqrt{2}^n}\exp\left(\frac{nr}{4}-\frac{1}{8r}\left(\sum_{j=1}^{n}(-1)^j(\alpha_j-\beta_j)\right)^2+O(1)\ee^{-r}\right); 
\end{align}
where $\LZ_n$ is defined in~\eqref{eqn::LZunitdisc_def} and the $O(1)$ terms have upper bounds independent of $(\bs{\alpha}, \bs{\beta})$.

