[Lemma 4 ({\cite[Lemma~4.1) of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] {moench2026horizonProblem}}]

Let \(K\subset\mathbb R\setminus\{0\}\) be compact.  Then
\begin{equation}
  \PP(B_s>0\text{ for every }s\in K)>0.

\end{equation}
Fix \(t\neq0\), and let
\begin{equation}
  \xi_s^{(t)}
  :=B_s-\frac{K_H(s,t)}{|t|^{2H}}B_t

\end{equation}
be the centred fractional Brownian bridge obtained by conditioning at \(t\).
If in addition
\(t\notin K\), then
\begin{equation}
  \PP(\xi_s^{(t)}>0\text{ for every }s\in K)>0.

\end{equation}
The same assertions hold with all signs reversed. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same setup as in Lemma~\ref{lem::reg_Dirichlet_annular_cro}. The regularized Dirichlet energy and the partition function have the following asymptotic as $r\to\infty$: 
\begin{align} 
	\| \varphicro{n} \|_{\nabla(\A_r),\mathrm{reg}}^2=& \frac{n(n-2) \pi r}{2} -2\pi \sum_{1\le i<j\le n} \left( \log \sin \left( \frac{\beta_{j}-\beta_i}{2} \right) + \log \sin \left( \frac{\alpha_{j}-\alpha_i}{2} \right) \right) \notag\\
	& -2\pi n(n-1)\log 2 +\frac{\pi}{2r}\left(\sum_{j=1}^{n} (\alpha_j-\beta_j) \right)^2+ O(1)\ee^{-r};
\\
\LZcro{n}^{(\ell)}(r; \bs{\alpha}, \bs{\beta})=&\sqrt{2}^{n(n-1)}\LZradial{n}(\bs{\alpha})\LZradial{n}(\bs{\beta})\notag\\
&\times\exp\left(\frac{n(2-n)r}{8}-\frac{1}{8r}\left(\sum_{j=1}^{n}(\alpha_j-\beta_{j})-2n\pi\ell\right)^2+O(1)\ee^{-r}\right);
\end{align}
where $\LZradial{n}$ is defined in~\eqref{eqn::LZunitdisc_def} and the $O(1)$ terms have upper bounds independent of $(\bs{\alpha}, \bs{\beta})$.

