[Thm 3 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] There is a critical mass $M_c>0$ (defined in~\eqref{Mc} below) such that the following hold:
\begin{itemize}
\item [\textbf{(I)}] For any initial value $(u^0,w^0)\in \mathcal{I}_{M,\bar{M},rad}(\mathbb{B}_R)$ with $M\in (0,M_c)$ and \mbox{$\bar{M}\ge M$}, the global solution $(u,w)$ to~\eqref{E} is bounded.
\item [\textbf{(II)}] Let $M>M_c$. There is $\mu_{M}^s\in\mathbb{R}$ such that, for any $\bar{M}\ge M$, the set
\begin{equation*}
    \mathcal{F}_{M,\bar{M}} := \left\{ (u^0,w^0)\in \mathcal{I}_{M,\bar{M},rad}(\mathbb{B}_R)\ :\ \mathcal{L}(u^0,w^0)<\mu_{M}^s \right\}
\end{equation*}
is non-empty and, for any initial value $(u^0,w^0)\in \mathcal{F}_{M,\bar{M}}$, the global solution $(u,w)$ to~\eqref{E} blows up in infinite time.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] Let $\mathbf{X}$ and $\mathbf{Y}$ be as above. Then the signature kernel satisfies the linear PDE

\begin{equation*}
\frac{\partial^2 f}{\partial t \, \partial v}
= f \langle \boldsymbol{x}_t, \boldsymbol{y}_v \rangle
+  \phi[R^*_{\boldsymbol{x}_t}  \boldsymbol{y}_v] 
+  \psi[R^*_{\boldsymbol{y}_v} \boldsymbol{x}_t],
\end{equation*}

\begin{equation*}
\frac{\partial \phi}{\partial t}
= f \boldsymbol{x}_t
+ \phi \circ R^*_{\boldsymbol{x}_t}
+ L^*_{\psi}\boldsymbol{x}_t
- \varphi[\boldsymbol{x}_t] \mathbf{1} ,
\end{equation*}

\begin{equation*}
\frac{\partial \varphi}{\partial v}
= f \boldsymbol{y}_v
+ \psi \circ R^*_{\boldsymbol{y}_v}
+ L^*_{\phi}\boldsymbol{y}_v
- \psi[\boldsymbol{y}_v] \mathbf{1} .
\end{equation*}

\medskip

\noindent
with boundary conditions
\[
\begin{aligned}
f(a,v) &= 1, 
& \phi(a,v) &= \mathbf{0}, 
& \psi(a,v) &= \langle \mathbf{Y}_{c,v} - \mathbf{1}, \cdot \rangle, \\
f(t,c) &= 1, 
& \phi(t,c) &= \langle \mathbf{X}_{a,t} - \mathbf{1}, \cdot\rangle,
& \psi(t,c) &= \mathbf{0},
