[Corollary cor: DHX input for specific rare event in sle of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a constant $c_6>0$ such that 
    for any integers $1\le i\le n$ and $k\ge 1$, we have \begin{align*}
        {\mathbb{P}}\Big(\big|\sum_{I\subset \mathsf{B}_i^+,|I|=k}(\langle\sigma^I \rangle^+_{i-1}\prod_{x\in I}\tanh({\epsilon}\beta_c h_x)\big|\ge ({\epsilon} M^{\frac{7}{8}})^{k/2}\Big)&\le c_6^{-1}\exp\Big(-c_6\sqrt{{\epsilon}^{-1}M^{-\frac{7}{8}}}\times(k!)^{\frac{3}{8k}}\Big).
    \end{align*}Furthermore, if $\iota<0.1$, then for any integer $r\ge 1$, we have \begin{align*}
        {\mathbb{P}}\Big(\big|\sum_{k=r}^{\infty}\sum_{I\subset \mathsf{B}_i^+,|I|=k}(\langle\sigma^I \rangle^+_{i-1}\prod_{x\in I}\tanh({\epsilon}\beta_c h_x)\big|\ge 2({\epsilon} M^{\frac{7}{8}})^{r/2}\Big)&\le c_6^{-1}\exp\Big(-c_6\sqrt{{\epsilon}^{-1}M^{-\frac{7}{8}}}\times(r!)^{\frac{3}{8r}}\Big).
    \end{align*} The same results hold for $\mathsf{B}_i^-$ and $\mathsf{B}_i^+$.

[Lemma case_of_no_waterfall of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] Assume that $\mathsf{t}\notin(\mathsf{t}_l,\mathsf{t}_r)$ and $(\mathsf{t},\mathsf{x})\in \mathcal{W}^+\cup \mathcal{W}^-$.
	Then $C_{\mathsf{x}}=q^{N+T}$, and
	the limits as in the two previous lemmas
	take the form
	\begin{equation}

		\begin{split}
			&\lim_{L\to+\infty}
			q^{N+T}
			\bigl(
				q^{-N+1}(1-q^{N-1})(q^{-T-N}-1)
				-B(\tilde x)-D(\tilde x)
			\bigr)
			=-1,
			\\
			&\lim_{L\to+\infty}
			q^{N+T}\sqrt{\frac{w^{qR}(\tilde x-1)}{w^{qR}(\tilde  x)}}B(\tilde  x-1)
			=
			\lim_{L\to+\infty}
			q^{N+T}\sqrt{\frac{w^{qR}(\tilde x)}{w^{qR}(\tilde  x-1)}}D(\tilde  x)
			= 0.
		\end{split}
	\end{equation}

[Proposition 22 of arXiv:2609.02878, '2609.02878'] Let \((Z,d,\mathcal R,g)\) be the time-\((-1)\) model of a tangent
space at a fixed limiting point, and put
\(N=\dim_{\R}\mathcal R=2n\).  Then,
for every compact \(K\subset Z\) and every \(p\in(2,4)\),
\begin{equation}
 \int_{K\cap\mathcal R}r_{\rm Rm}^{-p}\,dV_g<\infty.
\end{equation}
Consequently \eqref{sp:eq:Minkowski} holds, and the zero extension of
\(r_{\rm Rm}\) is one-Lipschitz on \(Z\).

[Prop random cluster properties of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] The following properties hold.
\begin{enumerate}
\item[$\bullet$]\textup{(Domain Markov Property)} For every $\Lambda' \subset \Lambda$, every $\theta\in \{0,1\}^{\overline E(\Lambda[\mathsf{h}]) \setminus \overline E(\Lambda'[\mathsf{h}])}$, and every $\mathsf{s}\in (\mathbb R^+)^{\overline{\Lambda}\setminus\Lambda'}$ satisfying $\mathsf{s}_{|\partial^{\textup{ext}} \Lambda}=\mathsf{b}$,
\begin{equation}
\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf{h}}[(\omega,\mathsf{a}) \mid (\omega|_{\overline E(\Lambda[\mathsf{h}])\setminus \overline E(\Lambda'[\mathsf{h}])},\mathsf{a}|_{\overline{\Lambda}\setminus \Lambda'})=(\theta,\mathsf{s})]=\Psi^{(\xi^{\theta},\mathsf{s})}_{\Lambda',\beta,\mathsf{h}_{|\Lambda'}}[(\omega,\mathsf{a})],
\end{equation}
where $\xi^{\theta}$ is the partition of $(\partial^{\mathrm{ext}} \Lambda')^{\mathfrak{g}}$ where $x,y$ are in the same partition class if and only if they are in the same connected component in the graph obtained from  $((\overline{\Lambda}\setminus \Lambda')^{\mathfrak g}, \{ e \in \overline E(\Lambda[\mathsf h])\setminus \overline E(\Lambda'[\mathsf h]):\theta_e=1\})$ by identifying the vertices in the elements of the partition $\xi$.
\item[$\bullet$]\textup{(Absolute value FKG inequality)} For every  $A \subset \Lambda$, $\eta \in (\mathbb R^+)^A$, and all increasing and square integrable functions $F,G: (\mathbb{R}^+)^{\overline{\Lambda} \setminus A}\to\mathbb{R}$, 
\begin{equation} 
\mu_{\Lambda,\beta,\mathsf{h}}^{(\xi,\mathsf{b})}[F\cdot G \mid \mathsf a|_A=\eta]\geq \mu_{\Lambda,\beta,\mathsf{h}}^{(\xi,\mathsf{b})}[F \mid \mathsf a|_A=\eta]\mu_{\Lambda,\beta,\mathsf{h}}^{(\xi,\mathsf{b})}[G \mid \mathsf a|_A=\eta].
\end{equation}
\item[$\bullet$]\textup{(FKG inequality)} For every $A \subset \Lambda$, $\eta \in (\mathbb R^+)^A$, and every pair of increasing and square-integrable functions $F,G: \{0,1\}^{\overline E(\Lambda[\mathsf{h}])}\times (\mathbb R^+)^{\overline{\Lambda}}\to\mathbb{R}$,
we have
\begin{equation}
\Psi_{\Lambda,\beta,\mathsf{h}}^{(\xi,\mathsf{b})}[F\cdot G \mid \mathsf a|_A=\eta]
\geq
\Psi_{\Lambda,\beta,\mathsf{h}}^{(\xi,\mathsf{b})}[F \mid \mathsf a|_A=\eta] \Psi_{\Lambda,\beta,\mathsf{h}}^{(\xi,\mathsf{b})}[G \mid \mathsf a|_A=\eta].
\end{equation}
\item[$\bullet$]\textup{(Monotonicity in parameters)} Let $\Lambda\subset \mathbb{Z}^d$ be finite and $A\subset \Lambda$. For every boundary conditions $(\xi_1,\mathsf{b}_1) \leq (\xi_2,\mathsf{b}_2)$ on $\Lambda$, every $\eta_1,\eta_2\in (\mathbb{R}^+)^{A}$ such that $\eta_1\leq \eta_2$, every external magnetic fields $\mathsf{h}_1,\mathsf{h}_2\in (\mathbb R^+)^\Lambda$ with $\mathsf h_1\leq \mathsf h_2$, and every $0\leq\beta_1\leq \beta_2$ we have
\begin{equation} 
\Psi_{\Lambda,\beta_1,\mathsf h_1}^{(\xi_1,\mathsf{b}_1)}[\:\cdot \mid \mathsf{a}|_A=\eta_1] \preccurlyeq \Psi_{\Lambda,\beta_2,\mathsf h_2}^{(\xi_2,\mathsf{b}_2)}[\:\cdot \mid \mathsf{a}|_A=\eta_2].
\end{equation}
In particular, 
\begin{equation}
\Psi^0_{\Lambda,\beta,\mathsf h} \preccurlyeq \Psi_{\Lambda,\beta,\mathsf h}^{(\xi,\mathsf{b})},
\end{equation}
for every boundary condition $(\xi,\mathsf{b})$ on $\Lambda$ and every $\mathsf{h}\in(\mathbb R^+)^\Lambda$. 

\item[$\bullet$]\textup{(Monotonicity in domain)} 
Let $\Lambda_1\subset \Lambda_2\subset \mathbb{Z}^d$ be finite and $\mathsf h_1\in (\mathbb{R}^+)^{\Lambda_1},\mathsf h_2\in (\mathbb{R}^+)^{\Lambda_2}$ such that $\mathsf h_1(x)\leq \mathsf h_2(x)$ for all $x\in \Lambda_1$. For every $\beta\geq 0$, we have
\begin{equation}
\Psi_{\Lambda_1,\beta,\mathsf{h}_1}^{0} \preccurlyeq \Psi_{\Lambda_2,\beta,\mathsf{h}_2}^{0}.
\end{equation}    
\end{enumerate}

[Proposition pr1 of arXiv:2411.02362, 'Limit theorems for random Dirichlet series: boundary case'] Under the assumptions of Theorem (main of the paper),
\begin{equation}
\limsup_{s\to 0+}\Big(\frac{1}{\log 1/s\, \log^{(3)} 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k\leq(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation}
and
\begin{equation}
\liminf_{s\to 0+}\Big(\frac{1}{\log 1/s\, \log^{(3)}1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k\geq-(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:bounds of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] If the conditions of (t:hp of the paper) hold, then

    \begin{equation}
        (1-\epsilon)\delta_a + \epsilon \delta_{\bar{x}} \preceq_{\textrm{sd}} P_u(a, \cdot)
        \quad \text{and} \quad
        P_u(b, \cdot) \preceq_{\textrm{sd}} (1-\epsilon)\delta_b + \epsilon \delta_{\bar{x}}
    \end{equation}

[Mylem 2 of arXiv:2607.00495, 'Rank deficiency of Bernoulli random matrices for growing corank'] For any $R>0$,
\begin{align*}
    \left| \mathbb{Z}^{n} \cap RB_{2}^{n}\right| \le \left(2+\frac{C_{\ref{Integer size in ball}}R}{\sqrt{n}}\right)^{n},
\end{align*}
where $C_{\ref{Integer size in ball}}>0$ is an absolute constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop upper bound of arXiv:2412.04918, 'On one dimensional weighted Poincar\'e inequalities for Global Sensitivity Analysis'] Given $i \in \{ 1,\ldots, d \}$, assume that the distribution $\mu_i$ of the input variable $X_i$ belongs to $\mathcal{P}(a_i,b_i)$. Let $w_i \in \mathcal{W}(a_i,b_i)$ be a weight function and suppose that $\mu_i$ satisfies the following
weighted Poincar\'e inequality:  for all centered function $g\in H^1(\mu_i,w_i)$,
\begin{equation}

\mathbb{E}\left[g(X_i)^2\right] \leq C_P(\mu_i,w_i) \, \mathbb{E}\left[w_i(X_i)g'(X_i)^2\right] .
\end{equation}
We also assume that $\left( w_i(X_i) \right)^{1/2} \frac{\partial f}{\partial x_i}(X) \in L^2$ where $f(X) \in L^2 $. Then, 
\begin{equation}

      S_i^\mathrm{tot}\leq C_P(\mu_i,w_i) \, \frac{\nu_{i,w_i}}{\mathop{\rm Var}\nolimits(f(X))}.
  \end{equation}

[Theorem LR of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \noindent  Let $C_{1},C_{2}$ be copulas on $[0,1]^{2}$ with
associated joint distributions $P_{i}=F_{C_{i}}$ on $R^{2}$, having
densities $f_{i}$. Assume:

\begin{enumerate}
\item $0<E^{P_{i}}[X_{1}X_{2}]<\infty $ for $i=1,2$;

\item $P_{1}\leq _{\mathrm{lr}}P_{2}$, i.e.\ $\frac{f_{2}}{f_{1}}$ is
coordinatewise non-decreasing.
\end{enumerate}

Then for all $s_{1},s_{2}\in R$, 
\begin{equation}
\frac{E^{F_{C_{1}}}(X_{1}X_{2}1_{\{X_{1}\geq s_{1}\}}1_{\{X_{2}\geq s_{2}\}})
}{E^{F_{C_{1}}}(X_{1}X_{2})}\leq \frac{E^{F_{C_{2}}}(X_{1}X_{2}1_{\{X_{1}
\geq s_{1}\}}1_{\{X_{2}\geq s_{2}\}})}{E^{F_{C_{2}}}(X_{1}X_{2})}.

\end{equation}
Moreover, setting $s_{1}=0$ or $s_{2}=0$ yields the marginal forms
\begin{eqnarray}
\frac{E^{F_{C_{1}}}(X_{1}X_{2}1_{\{X_{1}\geq s\}})}{E^{F_{C_{1}}}(X_{1}X_{2})
} &\leq &\frac{E^{F_{C_{2}}}(X_{1}X_{2}1_{\{X_{1}\geq s\}})}{
E^{F_{C_{2}}}(X_{1}X_{2})}   \\
\frac{E^{F_{C_{1}}}(X_{1}X_{2}1_{\{X_{2}\geq s\}})}{E^{F_{C_{1}}}(X_{1}X_{2})
} &\leq &\frac{E^{F_{C_{2}}}(X_{1}X_{2}1_{\{X_{2}\geq s\}})}{
E^{F_{C_{2}}}(X_{1}X_{2})}.  
\end{eqnarray}

