body:
[Theorem 1 (Uniform logarithmic Sobolev inequality) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] For every fixed $\beta>0$, there exists $\rho_*(\beta)>0$ such that, for all $N\ge2$ and every real-valued $f\in\mathsf D_{N,\beta}$,
\begin{equation}
 \Ent_{\mathbb P_{N,\beta}}(f^2)
 \le \frac2{\rho_*(\beta)}\cE_{N,\beta}(f).
\end{equation}
Moreover, for every compact interval $I\Subset(0,\infty)$,
\begin{equation}
 \inf_{\beta\in I}\inf_{N\ge2}\rho_{N,\beta}>0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2510.25900, 'Dixie cup problem in an interlacing process'] Let the sequence $\alpha = \{a_{j}\}_{j=1}^{\infty }$ is formed as the \textit{interlacing} of two subsequences $\beta = \{b_{j}\}_{j=1}^{\infty }$ and $\delta = \{d_{j}\}_{j=1}^{\infty }$, as given in relation (\ref{sb1}).  Then,  as $N=2M \rightarrow \infty$ we have
\begin{equation}
E\left[T_{m}\left(N;\alpha\right)\right]\sim \left(D_M +B_M\right)\int_{0}^{\infty}\left[1-\prod_{j=1}^M
 \bigg(1-S_m(d_{j}u)e^{-d_{j}u}\bigg)\right]du 
\end{equation}
where, 
\begin{align*}
B_M:=\sum_{j=1}^M b_j\,\,\,\,\,\text{and}\,\,\,\,D_M:=\sum_{j=1}^M d_j,
\end{align*}
provided that the coupons from the sequence $\delta$ are far rarer than the ones from the sequence $\beta$ (see, (\ref{deca})--(\ref{cond3})). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Wendel's formula: Combinatorial version) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $n, d \ge 1$ be integers with $n \geq d+1$.
For every regular $X \in \R^{d\times n}$, the cardinality of the set $\mathcal M(X)$ is given by
\begin{align*}
    |\mathcal M(X)| = 2 \sum_{j=0}^{d-1} \binom{n-1}{j}.
\end{align*}
In particular, this cardinality is the same for all regular $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:convergence-convex of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] Let Assumption~(assump:data-convex of the paper) and the assumptions of
Lemma~(lemma:one-step-descent-convex of the paper) hold. Consider the update in
(equation eq:projected-gradient-guidance-relaxed of the paper). Then, with $\rho$, $B_1$,
$B_2$, $M_\eta$, and $C_\eta$ defined as in
Lemma~(lemma:one-step-descent-convex of the paper), we have
\begin{align*}
    \mathcal V_0
    &\textstyle \le
    \rho^T\mathcal V_T+
    \left(
        B_1\|n_T\|
        +
        \epsilon M_\eta C_{\mathcal X}\sigma_T
    \right)
    \frac{
        \rho^T-(1-\epsilon)^T
    }{
        \rho-(1-\epsilon)
    }+
    \left(
        B_2\|n_T\|^2
        +
        2\epsilon^2C_\eta C_{\mathcal X}^2\sigma_T^2
    \right)
    \frac{
        \rho^T-(1-\epsilon)^{2T}
    }{
        \rho-(1-\epsilon)^2
    }.
\end{align*}
Consequently,
\begin{align*}
     \|p_0\!-\!x^\star\|^2
    &\textstyle\!\le\!
    2\eta
    \Bigg[\!
        \rho^T\mathcal V_T\!+\!
        \left(
            B_1\|n_T\|
            \!+\!
            \epsilon M_\eta C_{\mathcal X}\sigma_T
        \right)
        \frac{
            \rho^T\!\!-\!(1\!-\!\epsilon)^T
        }{
            \rho-(1\!-\!\epsilon)
        }\!+\!
        \left(
            B_2\|n_T\|^2
           \! + \!
            2\epsilon^2C_\eta C_{\mathcal X}^2\sigma_T^2
        \right)
        \frac{
            \rho^T\!-\!(1\!-\!\epsilon)^{2T}
        }{
            \rho-(1-\epsilon)^2
        }
    \!\Bigg]\!.
\end{align*}
Moreover,~
    $\|n_0\|
    \le
    (1-\epsilon)^T\|n_T\|.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2609.03185, 'Uniqueness of tangent flows in free boundary flow'] Let $u$ be a solution to the linearized equation. There exist constants $0<\delta_1<\delta_2<1$ such that the following statements hold. \begin{enumerate} 
\item If $I(u,s+1)\geq e^{\delta_1}I(u,s),$ then $I(u,s+2)\geq e^{\delta_2}I(u,s+1).$ 
\item If, at some time $s$, the decomposition of $u$ into eigenfunctions of $L$ has no component in the zero eigenspace, then either $I(u,s+1)\geq e^{\delta_2}I(u,s)$ or $I(u,s-1)\geq e^{\delta_2}I(u,s).$ \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Recursive bound for the MGF) of arXiv:2604.13149, 'The Distributional Tail of Worst--Case Quickselect'] For every \(n\ge 0\) and every \(\theta> 0\),
\begin{equation}
\psi_{n+1}(\theta)\le G_\theta\!\bigl(\psi_n(\theta)\bigr).
\end{equation}

[Lemma lem.block-moment-bounds of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let
		\[
		R_k\coloneqq\max_{0\le s\le \Delta\tau_k}|X^\lambda(\tau_k+s)-X^\lambda(\tau_k)|\, .
		\]
		For every integer $r\ge1$, there exists $C=C(r,d,\Lambda,r_0)<\infty$ such that, for every $\lambda\in(0,1]$ and every $k\ge0$,
		\begin{equation}
			\widehat{\mathbb E}_0^\lambda[(\Delta\tau_k)^r]\le C \lambda^{-2r},\qquad \widehat{\mathbb E}_0^\lambda[R_k^r]\le C \lambda^{-r}\, .
		\end{equation}
		Consequently,
		\begin{equation}
			\widehat{\mathbb E}_0^\lambda|\Delta X_k^\lambda|^r\le C \lambda^{-r}\qquad\text{for }k\ge0\, ,
		\end{equation}
		and, for
		\[
		W_k=\Delta X_k^\lambda-\ell(\lambda)\Delta\tau_k\, ,
		\]
		\begin{equation}
			\widehat{\mathbb E}_0^\lambda|W_k|^r\le C \lambda^{-r}\qquad\text{for }k\ge0\, .
		\end{equation}

[Definition eq:T1-0 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Given that there is a handover at time $0$, the time to the next handover is defined as  

\begin{equation}
T:=\inf\left\{s>0: \forall t\in (0,s], {\mathcal H }\left(S_t \right)=0, \text{ but } {\mathcal H }\left(\overline{S_s}\right)= 2\right\},

\end{equation}

which is equivalent to $T_1(0)$ under the handover Palm probability distribution.

[Theorem Thm-(u P)-long-time of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let the conditions of Theorem (Thm-(u P)-local of the paper) hold and
		$$\theta\in\left(\frac{d}{2}+p,{s-\max \{3\zeta,1\}}\right).$$
		\begin{enumerate}[label={\bf{(\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item $($\textbf{Global regularity and continuous dependence on initial data}$)$  Under (Hypo-DNI-1 of the paper), the Cauchy problem (equation Target problem (u P) damp of the paper) admits a global $H_{\rm div}^s$ solution. For $V\in\mathscr{V}$  as specified in (Hypo-DNI-1 of the paper), we have
			\begin{equation}
				\mathbb{E} \left[V(\|u(t)\|_{H^s}^2)\Big|\mathcal{F}_0\right]  
				\leq \Big(V(\|u_0\|^2_{H^s})+\mathscr{G}_2t\Big) {\rm e}^{\mathscr{G}_1t},
				\quad t>0.
			\end{equation}
			Moreover, 
			if $\{u_{0,m}\}_{m\ge1}$ are $\mathcal{F}_0$-measurable $H_{\rm div}^s$-valued random variables such that 
			\begin{equation}
				\sup_{m\ge1}\|u_{0,m}\|_{H^s}\le R\quad \text{for some}\  R>0 \quad  \text{and}\quad  \lim_{m\to\infty}\|u_{0,m}-u_0\|_{H^{\theta}}=0 \quad{\mathbb P}\text{-}{\rm a.s.},
			\end{equation}
			then the corresponding sequence of solutions $\{u_{m}\}_{m\ge1}$ with $u_m|_{t=0}=u_{0,m}$ satisfies
			\begin{equation}
				\lim_{m\to\infty}
				\mathbb{E} \left[1\land \|u_{m}(t)-u(t)\|^2_{H^{\theta}}\Big|\mathcal{F}_0\right]=0, \qquad t>0.
			\end{equation}

			\item  $($\textbf{Uniform-in-time estimate and invariant probability measure}$)$ If (Hypo-DNI-1 of the paper) is strengthened to (Hypo-DNI-2 of the paper), then $u$ satisfies 
			\begin{equation}
				\mathbb{E}\left[V(\|u(t)\|_{H^s}^2) \Big| \mathcal{F}_0\right]  
				\leq V(\|u_0\|^2_{H^s}), \qquad t\ge0.
			\end{equation}
			Moreover, on $\mathbb T^d$, there exists an
			invariant 
			measure $\mu$ 
			in the sense of Definition (IM definition of the paper) with $E=H_{\rm div}^s$. 

			\item $($\textbf{Uniqueness of invariant probability measure}$)$ Let $M=M_{\theta,d}>0$ be a constant satisfying $\|\cdot\|_{W^{p,\infty}}\leq M \|\cdot\|_{H^\theta}$ for $\theta>d/2+p$. If (Hypo-DNI-3 of the paper) holds, then  
			\begin{equation}
				\int_0^t\mathbb{E}  \left[V\left(\frac{\|u(t')\|^2_{W^{p,\infty}}}{M^2}\right)\Bigg|\mathcal{F}_0\right]{\,\rm{d}} t'
				\leq  \frac{V(\| u_0\|^2_{H^\theta})}{\mathscr{G}_3}\left(1-{\rm e}^{-\mathscr{G}_3t}\right),
				\quad t>0,
			\end{equation}
			As a consequence of (equation u Wlip -> 0 of the paper) and $V(0)=0$, it follows that
			the Dirac measure centered at $0$ is the \textbf{unique invariant probability measure} on both $\mathbb T^d$ and $\mathbb R^d$ when $\widetilde h(0)=0$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: PageRankLowerBound of arXiv:2606.19583, 'Power-law hypothesis and (un)fairness of PageRank on undirected multi-type PAMs'] Assume that, for $k \in S$, there exist $\alpha>0$ and $p \in(0,1)$ such that, as $r\rightarrow \infty,$
\begin{equation}
\mathbb{P}_k^{\mathcal{T}}\left( d_\phi^{\scriptscriptstyle(-,\geq \alpha)} 
\geq pd^-_\phi \mid d_\phi^-=r\right) \stackrel{r \to \infty}{\rightarrow} 0.
\end{equation}

Then, with $\beta:=\frac{m_k+\alpha}{(1-p) c(1-c)}$, the random variable $R^{1,\textup{dirTr}}_\phi$ satisfies 
\begin{equation}
\mathbb{P}_k^{\mathcal{T}}(R^{1,\textup{dirTr}}_\phi>r) \geq (1+o(1))\mathbb{P}_k^{\mathcal{T}}(d_\phi^->\beta r) \quad \text{as } r \rightarrow \infty.   
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:mean of arXiv:2605.28106, 'Gaussian Processes with Sample Paths in Reproducing Kernel Banach Spaces'] Let \( \mu \) be a measure on \( (X,\mathcal{C}(X)) \) such that \( X^*\subseteq L^1(\mu) \).
    The \emph{mean} of \( \mu \) is the linear functional
    \begin{equation} 
        a_\mu:X^*\to\mathbb{R},\qquad f\mapsto\int_X f(x)\mu(dx).
    \end{equation}

