  =
  \frac12
  \mathbb E_{\mathbb Q}
  \left[
    \left|
      Z_t^{N,\alpha}
      -
      Z_t^{N,\beta}
    \right|
  \right]
 \le
  \frac12d_N.
\end{aligned}

\end{equation}

