[Lem 62 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $A,D$ satisfy \eqref{eq:costanti}; let $q \in (0, \varepsilon_0)$ and $k\in \mathbb N$ be such that $k \le \ell_0 (q)+5$; and set
	\begin{flalign} 
		q' \in [q - 2^k  N^{D \delta-1}, q]; \qquad \mathsf{t} = 2^k q^{-1} N^{1+6A\delta}.

	\end{flalign} 
	Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu\in\mathcal P^+$ (recall \Cref{def:P+}) and assume that, w.o.p. under $\mu$,
	\begin{flalign}

		H_0 (w) \le \mathcal{H}_q (w) + N^{\delta-1}, \quad \text{for each $w \in \mathcal C^q_k:=\mathcal{B}_{k+1}^q \cup \bigcup_{j=1}^k \mathcal{A}_j^q$}. 
	\end{flalign}

	\noindent Then we have w.o.p. that, for any $t \in [\mathsf{t}, N^{5}]$,   
	\begin{flalign} 
		H_t (z_0) \le \mathcal{H}_{q'} (z_0), \qquad \text{for each $z_0 \in \mathcal{A}_k^{q'}$}.
	\end{flalign}

[Prop geo-cle of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $d=d^{{\mathrm {geo}}}$. 
For every $V\in\mathfrak{C}$ and $x,y\in \mathcal{X}\cap\overline{V}$, we have
\begin{equation}
    \mathfrak{d}_V(x,y)=\inf_{\gamma\in P(x,y;\overline{V})}L_{d}(\gamma).
\end{equation}

