[Proposition 9 (GFT) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W^{(1)}=\big(w^{(1)}_{ab}\big)_{a,b=1}^N$ and $W^{(2)}=\big(w^{(2)}_{ab}\big)_{a,b=1}^N$ be two Wigner matrices satisfying Assumption~\ref{ass:momass}. Fix $\Gamma\in\N$ and assume that 
\begin{equation}
\E \big(w^{(1)}_{ab}\big)^{\gamma_1}\big(w^{(1)}_{ba}\big)^{\gamma_2} = \E \big(w^{(2)}_{ab}\big)^{\gamma_1}\big(w^{(2)}_{ba}\big)^{\gamma_2},\quad \gamma_1+\gamma_2\le \Gamma,\, \gamma_1,\gamma_2\in\N\cup\{0\},

\end{equation}
Let $\Delta^{(j)}$ be defined as in \eqref{eq:def_Delta} but with $W$ replaced by $W^{(j)}$, $j=1,2$. Then for any fixed $n_1,n_2\in\N\cup\{0\}$ and $\bm{k}\in\N^{n_1},\bm{l}\in\N^{n_2}$ it holds that
\begin{equation}
\E \left[\eta^{|\bm{k}|+|\bm{l}|}\Delta^{(1)} (\bm{k})\overline{\Delta^{(1)}(\bm{l})}\right]=\E \left[\eta^{|\bm{k}|+|\bm{l}|}\Delta^{(2)} (\bm{k})\overline{\Delta^{(2)}(\bm{l})}\right] + \mathcal{O}\left(N^{-(\Gamma-3)/2+\xi}\right),

\end{equation}
for any fixed $\xi>0$, uniformly in $z\in\mathcal{D}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $m\ge2$, let $1\le i<j\le m$, and let $a,b\in[1,2]$. Assume
\begin{equation}
 \frac{1}a+\frac{1}b\le\frac{3}{2}.
\end{equation}
Then
\begin{equation}
 C_{\mathbf q_{i,j}^{(m)}(a,b)}^{(m)}
 =2^{\frac{1}a+\frac{1}b-1+(m-2)\left(\frac{1}{\min\{a,b\}}-\frac{1}{2}\right)}.
\end{equation}

[Proposition 14 of arXiv:2608.18075, '2608.18075'] There is a lower semicontinuous inf-compact function
$\mathcal W:\mathsf X\to[1,\infty]$, and
constants $0<\rho<1$, $C<\infty$ such that
\begin{align}
 P_\tau\mathcal W&\le\rho\mathcal W+C,
 \\
 \mathbf{E}_z\left(L(z,Y)^p+\left|a_q(z, Y)\right|^p\right)&\le C\mathcal W(z)^{1/p},

\end{align}
where the constant $C$ in the second inequality may depend on $q$ through $a_q$. Moreover, 
\begin{align*}
      \sup _{\widehat{\mu} \in \mathfrak{I}} \int_{\mathsf X} \mathbf{E}_z\left[L(z, Y)^p+\left|a_q(z, Y)\right|^p\right] \widehat{\mu}(\dd z)<\infty.
\end{align*}

