[Mainthm 1 of arXiv:2609.03777, '2609.03777'] \begin{enumerate}[(i)]
\item The assignments
\begin{align}
WG_{k_1,\dots,k_r}
&=(k_1+\cdots+k_r)G_{k_1,\dots,k_r},\\
DG_{k_1,\dots,k_r}
&=2\pi i\frac{d}{d\tau}G_{k_1,\dots,k_r},\\
\delta G_{k_1,\dots,k_r}
&=
\begin{cases}
-\dfrac12G_{k_2,\dots,k_r},&k_1=2,\\
0,&k_1>2,
\end{cases}
\end{align}
on the generators of $\mes$ extend to well-defined derivations $W$, $D$ and $\delta$ on $\mes$.

\item The derivations $W$, $D$ and $\delta$ satisfy
\begin{align}
[W,D]=2D,\qquad [W,\delta]=-2\delta,\qquad [\delta,D]=W\,.
\end{align}
In particular, $\mes$ is an $\sltwo$-algebra.

\item Put
\begin{align}
\mesadm
&\coloneqq
\QQ\oplus
\Span_\QQ\{G_{k_1,\dots,k_r}\mid
r\geq1,\ k_1\geq3,\ k_2,\dots,k_r\geq2\}\,.
\end{align}
Then
\begin{align}
\mes=\mesadm[G_2]
\end{align}
is a free polynomial algebra over $\mesadm$, and
\begin{align}
\delta=-\frac12\frac{\partial}{\partial G_2}\,.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 28 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Fixed $\varepsilon>0$, let $\mathcal{G}$ and $\widetilde{\mathcal{G}}$ be two functionals as in Hypothesis \ref{hypothesis_B} also continuous over $\widehat{C}^{\alpha,p}_o$, and $\langle\ell,\cdot\rangle$ and $\langle\widetilde{\ell},\cdot\rangle$ be as in Theorem \ref{thm:CuchieroTeichmannGUAT} such that
    \begin{equation*}
        \sup_{t\in[0,T]}\sup_{\widehat{\mathbf{x}}\in \widehat{C}^{\alpha,p}_o} \frac{ \big|\mathcal{G}(\mathbf{x}^{(1)}_{\cdot\wedge t}) -\langle\ell,S(\widehat{\mathbf{x}})_t\rangle\big| }{ \psi(\widehat{\mathbf{x}}_{\cdot\wedge t}) } < \varepsilon;\qquad \sup_{t\in[0,T]}\sup_{\widehat{\mathbf{x}}\in \widehat{C}^{\alpha,p}_o} \frac{ \big|\widetilde{\mathcal{G}}(\mathbf{x}^{(1)}_{\cdot\wedge t}) -\langle\widetilde{\ell},S(\widehat{\mathbf{x}})_t\rangle\big| }{ \psi(\widehat{\mathbf{x}}_{\cdot\wedge t}) } < \widetilde{\varepsilon}.
    \end{equation*}

    Under the assumption of Hypothesis \ref{hypothesis_A}, let us consider the processes $(X,Y)$ being solutions to the equations
    \begin{equation*}
        \begin{aligned}
            &X_t = \eta + \int_0^t b\left(s,X_s,\Big\langle \ell,\mathbb{E}\left[S(\augpr{X})_s\right]\Big\rangle\right)ds
            + \int_0^t\sigma\left(s,X_s,\Big\langle \widetilde{\ell},\mathbb{E}\left[S(\augpr{X})_s\right]\Big\rangle\right)dW_s;\\
            &Y_t = \eta + \int_0^t b\left(s,Y_s,\mathbb{E}\left[\mathcal{G}(Y_{\cdot\wedge s})\right]\right)ds 
            + \int_0^t\sigma\left(s,Y_s,\mathbb{E}\left[\widetilde{\mathcal{G}}(Y_{\cdot\wedge s})\right]\right)dW_s,
        \end{aligned}
    \end{equation*}
    with $t\in[0,T]$. Then there exists $\delta=\delta(\varepsilon)>0$ such that
    \begin{equation*}
        \mathbb{E}\left[\big\lVert Y - X\big\rVert^2_{\infty,T}\right]\leq \delta,
    \end{equation*}
    where
    \begin{equation*}
        \delta=\delta(\varepsilon):= 2TLe^{4TL(1+2(L_\mathcal{G}\vee L_{\widetilde{\mathcal{G}}}))T}e^{2\beta(2T)^\gamma}\left(\varepsilon\vee\widetilde{\varepsilon}\right)^2
    \end{equation*}

