[Lemma Hardy-Poincare of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Let $d\geqslant 1$ and $\alpha_*=\frac{2-d}{2}$. For any $\alpha<0$,  and $\alpha \in (-\infty,0)\setminus \{ \alpha_*\}$ for $d\geqslant 3$, there is a positive constant $\Lambda_{\alpha,d}$ such that
\begin{equation}
\Lambda_{\alpha,d} \int_{\mathbb{R}^d} |f|^2(D+|x|^2)^{\alpha-1}\mathrm{d}x \leqslant \int_{\mathbb{R}^d} |\nabla f|^2 (D+|x|^2)^{\alpha}\mathrm{d}x
\end{equation}
holds for any function $f \in H^1\big((D+|x|^2)^{\alpha}\mathrm{d}x\big)$ and any $D \geqslant 0$, under the additional condition $\int_{\mathbb{R}^d} f (D+|x|^2)^{\alpha-1}\mathrm{d}x = 0$ and $D>0$ if $\alpha<\alpha_*$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:kl-dt-shifted-comp of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Under the same assumptions as Theorem~(thm:kl_local_error of the paper), the following bounds hold.
    \begin{enumerate}
        \item \textbf{Strongly convex, high friction:} 
        \begin{align*}
            \frac{1}{\gamma} \int_0^T \gamma_t^2 \eta_t^2 \mathtt{e}_t^2 \,\mathrm{d} t \lesssim \frac{1}{\alpha h^2}\,(\bar{\mathcal{E}}^{\rm w})^2 + \Bigl[\frac{1}{\beta^{1/2} h} \log\frac{1}{|\omega| h}\Bigr]\,(\bar{\mathcal{E}}^{\rm s})^2\,.
        \end{align*}

        \item \textbf{Weakly convex, high friction:}
        \begin{align*}
            \frac{1}{\gamma} \int_0^T \gamma_t^2 \eta_t^2 \mathtt{e}_t^2 \,\mathrm{d} t \lesssim \frac{T}{\beta^{1/2} h^2}\,(\bar{\mathcal{E}}^{\rm w})^2 + \Bigl[\frac{1}{\beta^{1/2} h} \log\frac{T}{h} + \beta^{1/2} T\Bigr]\,(\bar{\mathcal{E}}^{\rm s})^2\,.
        \end{align*}

        \item \textbf{Semi-convex, low friction:}
        \begin{align*}
            \frac{1}{\gamma} \int_0^T \gamma_t^2 \eta_t^2 \mathtt{e}_t^2 \,\mathrm{d} t \lesssim \frac{T}{\gamma h^2}\,(\bar{\mathcal{E}}^{\rm w})^2 + \frac{1}{\gamma h}\, \Bigl[\log\frac{\beta^{-1/2} \wedge T}{h} + \beta^{1/2} T\Bigr]\,(\bar{\mathcal{E}}^{\rm s})^2\,.
        \end{align*}


    \end{enumerate}

