[Theorem thm:bilinear of arXiv:2608.01253, 'The pseudo-quantum representation of \\finite reversible Markov chains'] The pseudo-wave and pseudo-density obey

\begin{equation}
\dot\Phi_z=K\Phi_z,\qquad \dot\rho_z=[K,\rho_z]=K\rho_z-\rho_zK.

\end{equation}

Moreover, for all $z$,

\begin{equation}
\rho_z^{T}=\rho_z,\qquad
\operatorname{Tr}\rho_z=\Phi_z^{T}\Phi_z=\Phi_0^{T}\Phi_0,
\qquad
\rho_z^{2}=(\operatorname{Tr}\rho_z)\,\rho_z.

\end{equation}

