[Lemma lemma_fin_deg_to_unim of arXiv:2607.04002, 'Collisions of random walks in unimodular random graphs: applications to the random geometr'] Fix~$d \ge 2$. For~$G \in \{ \mathcal{G}_\mathrm{SGil}, \mathcal{G}_\mathrm{Del}, \mathcal G_\mathrm{Gab}$\} we have that
\begin{equation}
\mathbb{E}_0 \big[ \exp \big( \theta \deg_G(0) \big) \cdot \mathds{1}\{0 \in V(G)\} \big] < \infty \quad \text{for all } \theta \in \mathbb{R}.
\end{equation}

[Theorem thm:BSSK_highlowtemp of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] Consider a BSSK model with species sizes $N_1,N_2$ such that $N_1+N_2=N$ and their ratio converges as $N_1/N_2=\lambda+O(N^{-1-\delta})$ for some $\lambda\in(0,1)$ and some $\delta>0$. Then the critical inverse temperature is $\beta_c:=\sqrt{1+\lambda}/\lambda^{1/4}$ and the free energy exhibits the following convergence in distribution as $N_1,N_2\to\infty$.
\begin{enumerate}[(i)]
\item In the high temperature regime, $\beta<\beta_c$,
 \begin{equation} 
N(F_{N_1,N_2}(\beta)-F(\beta))\to\mathcal{N}(-\frac12\sigma^2-\log2,\sigma^2),
 \end{equation} 
where $\sigma^2=-\frac12\log(1-(\beta/\beta_c)^4),$ with a slightly more complicated formula in the case of a general Wigner matrix rather than GOE.
\item In the low temperature regime, $\beta>\beta_c$,
 \begin{equation} 
\frac{N^{2/3}}{A(\beta,\lambda)}(F_{N_1,N_2}(\beta)-F(\beta))\to\TW_1,
 \end{equation} 
where the formula for $A(\beta,\lambda)$ is given in Theorem 2.3 of [BL20].
\end{enumerate}
The limiting free energy $F(\beta)$ is given in Theorem 2.1 of [BL20] (we omit the formula here but note that it depends on the ratio $\lambda$ 
and is continuous but non-differentiable at $\beta_c$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop two-pt classification of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\beta > 0$. Assume that for every pair of neighbours $x,y \in \mathbb Z^d$,
\begin{equation} 
\langle \tau_x \tau_y\rangle_\beta^+ = \langle \tau_x \tau_y \rangle_\beta. 
\end{equation}
Then,
\begin{equation}
\Psi^1_\beta = \Psi^0_\beta.
\end{equation}

[Corollary cor:pureweak-nonstrong of arXiv:2507.14676, 'On the critical parameters of branching random walks'] {cf:BZ17}}]
Let $(X,K)$ and $(X,K^*)$ two irreducible continuous-time BRWs such that $k_{xy}=k^*_{xy}$ for all $x \in X \setminus A$
where $A$ is a finite nonempty set. 

Then the following are equivalent:
\begin{enumerate}
\item $\lambda^*_w<\lambda_w$;
\item $\lambda^*_s<\lambda_w$;
\item $\lambda^*_w=\lambda^*_s<\lambda_w$.
\end{enumerate}
In particular, if $\min(\lambda_s , \lambda_s^*) \ge \max(\lambda_w, \lambda_w^*)$ (for instance, if $\lambda_s =\lambda_s^*$), then $\lambda_w=\lambda_w^*$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $1< p<\infty$ and $q=\max\{1,p-1\}$.
    Assume that $|F|\in L^{q}_{\loc}(\Omega_T)$ and that $u\in  L^q_{\loc}(0,T;W^{1,q}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$.
Then there exists a constant $c=c(n,p,L)$ such that 
\begin{equation}
    \frac{|u(x,t)-u(x,s)|}{|t-s|^\frac{1}{2}}
    \le c \bigl( g(x,t) + g(x,s) \bigr)
\end{equation}
for every parabolic cylinder $Q=Q_r=B\times I$ such that $2Q\Subset \Om_T$ and almost every $x\in B$ and $t,s\in I$, where $g$ is as in \eqref{p_time_grad}.

[Lemma 45 (Cubic stability inequality) of arXiv:2606.24887, '2606.24887'] For $0 < \eta_{\ast} < \eta^{\ast} < \infty$, let $\xi_1, \xi_2 : [\eta_{\ast}, \eta^{\ast}] \rightarrow \CC$ be complex-valued functions and $\tilde{\xi},\varphi: [\eta_{\ast},\eta^{\ast}] \rightarrow \RR_{+}$ be continuous. Suppose that some continuous function $\Delta : [\eta_{\ast}, \eta^{\ast}] \rightarrow \CC$ satisfies the cubic inequality 
		\begin{equation*}
			\big| \Delta^3 + \xi_2 \Delta^2 + \xi_1 \Delta \big| \le \varphi 
		\end{equation*}
		on $[\eta_{\ast}, \eta^{\ast}]$ as well as 
		\begin{equation*}
			\abs{\Delta} \lesssim \min \left\{ \varphi^{1/3}, \frac{\varphi^{1/2}}{\tilde{\xi}^{1/2}}, \frac{\varphi}{\tilde{\xi}}\right\}
		\end{equation*}
		at $\eta^{\ast}$. If the following holds
		\begin{enumerate}
			\item $\tilde{\xi}^3/\varphi^{2}$ is a monotonically increasing function,
			\item $|\xi_1| \asymp \tilde{\xi}$ and $|\xi_2| \lesssim \tilde{\xi}^{1/2}$,
		\end{enumerate}
		then, on $[\eta_{\ast}, \eta^{\ast}]$ we have 
		\begin{equation*}
			\abs{\Delta} \lesssim  \min\left\{ \varphi^{1/3}, \frac{\varphi^{1/2}}{\tilde{\xi}^{1/2}}, \frac{\varphi}{\tilde{\xi}}\right\}.
		\end{equation*}

[Definition def:cm of arXiv:2506.03999, 'Large deviations for scaled families of Schr\"odinger bridges with reflection'] A subset $\Gamma \subseteq \calX \times \calY$ is called \textit{$c$-cyclically monotone} if
    \begin{equation}
        \sum_{i=1}^k c(x_i, y_i) \leq \sum_{i=1}^k c(x_i, y_{i+1}),
    \end{equation}
    for all $k \in \bN$, $\{ (x_i, y_i ) \} _{i=1} ^k \subseteq \Gamma$, where $y_{k+1}$ is interpreted as $y_1$. 
    Correspondingly, a transport plan $\pi \in \Pi (\mu, \nu)$ is called cyclically monotone if $\pi(\Gamma) = 1$ for some cyclically monotone set $\Gamma$.

[Definition 15 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] We construct a sequence of random functions $v^{n}_M : \Omega \times \Pi \rightarrow \bR^{d'}\times \bR^{d' \times d}$, $n \in \bN$ such that $v^0_M=0$ and, for all $n \in \bN$, $z\in \Pi$,
\begin{equation}

 v^{n+1}_M(z)=T_{B,{{\rho}_r}}\left(\frac1{M} \sum_{j=1}^{M} R^{(\cdot)}_{n,j}(Pv^n_M)\right)(z) , 
\end{equation}
where $B\geqslant \norm{ v}_{{\rho}_r}$ and for any $\phi = (w^1, w^2) : \bR^d \rightarrow \bR^{d'}\times \bR^{d' \times d}$ and $x \in \Pi$,  $(R_{n,j}^{x}(\phi))_{n \in \bN, j \in \bN^*}$ are i.i.d. random variables with the same distribution as 
\begin{align}

R^{x}(\phi):=& \Bigg(\frac{1}{\theta } (f(\xxe, w^1(\xxe), w^2(\xxe)) + a w_1(\xxe))e^{-(a-\theta)E},\\
\nonumber
& \quad \sqrt{\frac{\pi}{{\ttheta} }}  \left(f(\Xx_\tE, w^1(\Xx_\tE), w^2(\Xx_\tE)) + \ta w^1(\Xx_\tE)\right)\sqrt{\tE}e^{-(\ta-\ttheta)\tE} \Ux_\tE\Bigg),
\end{align}
recalling that $\theta \in (0,a)$, $\ttheta \in (0,\ta)$, $E\sim\cE(\theta)$, $\tE \sim \Gamma(1/2,\ttheta)$ are independent and independent of $W$.

[Prop 41 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] The normalizing factor of a intertwining operator is at an unramified
place is given by
\begin{equation*}
	|\Delta_v|^{-\frac{\dim N_w}{2}}\times\text{ the usual factor}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Let \((\mathcal{T}, d) = (\mathcal{T}_g, d_g)\) be a random rooted ordered real tree encoded by a random \(g \in C_{\rm bridge}\).  
Consider a sequence \((\mathscr{T}^n : n \ge 1)\) of random ordered discrete trees with \(a_n := |V(\mathscr{T}^n)| \to \infty\), and suppose that the maximal edge length of \(\mathscr{T}^n\) converges to \(0\) in distribution.  
Then the following statements are equivalent:
\begin{enumerate}[label=(\roman*), ref=\roman*]
    \item The contour functions
    \[
        C_{\lfloor2(a_n-1)\,\cdot\,\rfloor}(\mathscr{T}^n)\ \overset{d}{\longrightarrow}\  g\quad\text{in \(D[0,1]\).}
    \] 
    \item  For each \(1 \le k \le a_n\), let \((V^n_1, \dots, V^n_{a_n})\) be a uniform random ordering of the vertices of \(\mathscr{T}^n\), and denote by \(\mathscr{T}^n_k\) the rooted ordered subtree spanned by the root \(\rho\) and \(\{V^n_1,\dots,V^n_k\}\). Then it holds that:
    \begin{itemize}
        \item \textit{Tightness}: 
        for any \(\delta > 0\),
        \[
            \lim_{k \to \infty} \limsup_{n \to \infty} \mathbb{P}(\Delta(n,k) > \delta) = 0,
        \]
        where
        \begin{align}
            \Delta(n,k) := \max_{v \in V(\mathscr{T}^n)} \min_{u \in V(\mathscr{T}^n_k)} d(v,u).
        \end{align}

        \item \textit{Finite-dimensional convergence}: for every fixed \(k \in \mathbb{N}_+\),
        \begin{equation}
            \big(\mathscr{T}^n_k, \{V^n_1,\dots,V^n_k\}\big) \overset{d}{\longrightarrow} \big(\mathcal{T}_{g,k}, \{p_g(U_1),\dots,p_g(U_k)\}\big)
        \end{equation}
        under the distance \eqref{fidis}, where \(\{V^n_1,\dots,V^n_k\}\) and \(\{p_g(U_1),\dots,p_g(U_k)\}\) are considered as multisets.
    \end{itemize}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

