[Prop 44 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Assume that there exists a sequence of  boundary  height functions $f^{(n)} : \partial \mathfrak{X} \rightarrow \mathbb{R}$, for each $n \ge 1$, such that $\Adm(\mX;f^{(n)})$ is not empty (recall \Cref{def:Adm}) and
  \begin{enumerate}
  \item [(A)] $\lim_{n\to\infty}\sup_{z\in \partial\mathfrak X
    }|f^{(n)}(z)-f(z)|=0$

  \item [(B)] the limit shape  $\mathcal H^{(n)}$ in $\mathfrak X$ with boundary condition $f^{(n)}$ {(cf. \Cref{th:limshapeD})}
    has the property that $\nabla \mathcal H^{(n)}\in \mathcal T$ and $\dist(\nabla \mathcal H^{(n)},\partial\mathcal T)\ge 1/(2n)$ hold almost everywhere in $\mathfrak{X}$, where $\mathcal T$ was defined in \eqref{e:cT}.
  \end{enumerate}
  Then, for the Glauber dynamic in $\mathfrak X$, for every $\delta,L,\omega>0$ there {exists $C<\infty$} such that, for every $N$,
  \begin{eqnarray}

    \max_{\eta\in \Omega^N}\mathbf P_\eta\Big(\exists t: C N^{2+\delta}\le t\le N^{L}, z\in \mathfrak X, |H_t(z)-\mathcal H(z)|\ge \omega\Big)\le CN^{-L}.
  \end{eqnarray}

[Definition The wave front set of a distribution of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Let $U\subset \mathbb{R}^n$ be some open subset of $\mathbb{R}^n$.
Given a distribution $T\in \mathcal{D}^\prime(U)$, the wave front set $WF(T)\subset T^*U\setminus \underline{0} $ is the closed conical subset with the following property:
an element $(x_0;\xi_0)\notin WF(T)$ if there exists a neighborhood $U_0$ of $x_0$, a closed conic neighborhood  $V_0\subset \mathbb{R}^{n*}$ of $\xi_0$ such that for all $\chi\in C^\infty_c(U_0)$, for all $N$~:
\begin{eqnarray*}
\vert \widehat{T\chi}(\xi) \vert \leqslant C_{\chi,N,V_0} \left(1+\vert \xi\vert \right)^{-N} 
 \end{eqnarray*}
 uniformly in $\xi\in V_0$.

[Lemma lem:CT-TASEP-dressing of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The kernel $K_{t,\mathbf{a},\mathbf{n}}$ is dual dressing
compatible (Definition~(def:sc-dual-dressing of the paper)) with
$(\Psi, \Phi)$ and $z = 1$ for every $t > 0$,
$\mathbf{a} \in \mathbb{Z}^m$, and
$1 \leq n_1 < \cdots < n_m$.
Explicitly:
\begin{align}
K_{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
- K_{t,\mathbf{a},\mathbf{n}}
&= \Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
   \Phi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}},
 \\
\partial_t K_{t,\mathbf{a},\mathbf{n}}
&= -\tfrac{1}{2}\Psi^{t,\mathbf{a},\mathbf{n}}
   \Phi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}},
 \\
K_{t,\mathbf{a},\mathbf{n}+\mathbf{1}}
- K_{t,\mathbf{a},\mathbf{n}}
&= 2\Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
   \Phi^{t,\mathbf{a},\mathbf{n}+\mathbf{1}}.

\end{align}

[Proposition p:trig poly avset of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $m\in\N_0$, and suppose that $p$ is a trigonometric polynomial of degree $m$. Then, for all $n\geq m+1$,
    \begin{equation}
        \frac{1}{2\pi}\int_0^{2\pi} p(x)\, dx = \frac{1}{n} \sum_{j=1}^n p(2\pi j/n+u),\quad u\in\R,
    \end{equation}
    but if $m\in\N$,
    \begin{equation}
        u\mapsto \frac{1}{m} \sum_{j=1}^m p(2\pi j/m+u), \quad u\in\R,
    \end{equation}
    is not constant.

\begin{proof}
    Let $m\in\N_0$, $n\in\N$, and $u\in\R$. We show that~(equation e:trig poly avset fit of the paper) holds for a trigonometric monomial $p(x)=e^{imx}$. The general case then follows from symmetry and linearity. Also, for $m=0$, both sides are equal to $1$, whereby the assertion holds. Hence, without loss of generality, we can assume $m\in\N$. In this case,
    \begin{equation*}
        \int_0^{2\pi} e^{imx}\, dx=0,
    \end{equation*}
    and what remains to show is that
    \begin{equation*}
        \sum_{j=1}^n e^{im(2\pi j/n+u)} = 0.
    \end{equation*}
    Further, as
    \begin{equation*}
        \sum_{j=1}^n e^{im(2\pi j/n+u)} = e^{imu} \sum_{j=1}^n e^{2\pi i jm/n},
    \end{equation*}
    it suffices to show that
    \begin{equation*}
        \sum_{j=1}^n e^{2\pi i jm/n} = 0.
    \end{equation*}
    Now let $l\in\N$ be the greatest common factor of $n$ and $m$. Then,
    \begin{equation*}
        \sum_{j=1}^n e^{2\pi i jm/n} = \sum_{k=0}^{l-1}\sum_{j=1}^{n/l} e^{2\pi i (kn/l+j)m/n} = \sum_{k=0}^{l-1} \underbrace{e^{2\pi ikm/l}}_{=1}\sum_{j=1}^{n/l} e^{2\pi ijm/n} = l\sum_{j=1}^{n/l} e^{2\pi ij(m/l)/(n/l)}.
    \end{equation*}
    Hence, it suffices to show the assertion for $n,m$ coprime, as dividing by a common factor keeps the property that $n\geq m+1\geq 2$. In that case, we can reorder the sum and perform an index shift to obtain
    \begin{equation*}
        \sum_{j=1}^n e^{2\pi i jm/n} = \sum_{j=1}^n e^{2\pi i j/n} = e^{2\pi i/n} \sum_{j=1}^n e^{2\pi i j/n}.
    \end{equation*}
    This relation concludes the first part of the proof, as $e^{2\pi i/n}\neq 1$, since $n\geq2$, whereby the right equation can only hold if both sides are $0$.

    For the second part, let $p$ be a general trigonometric polynomial with coefficients \linebreak $a_{-m},...,a_m\in\C$. Now, we can apply~(equation e:trig poly avset fit of the paper) to the different trigonometric monomials of $p$ to obtain
    \begin{equation*}
        \frac{1}{m} \sum_{j=1}^m p(2\pi j/m+u) = a_0 + \frac{a_{-m}}{m} \sum_{j=1}^m e^{-2\pi ij-imu} + \frac{a_m}{m} \sum_{j=1}^m e^{2\pi ij+imu} = a_0 + a_{-m} e^{-imu} + a_m e^{imu}.
    \end{equation*}
    This equation yields the second assertion, as $u\mapsto e^{-imu}$ and $u\mapsto e^{imu}$ are linearly independent and $a_{-m}\neq0$ or $a_m\neq0$.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:Arho6 of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] Let $\pi=\pi_{k:\infty}$ be a  nontrivial semi-infinite geodesic  in a fixed  environment $\omega\in\Omega_0$ and  $A_\pi(\omega)$   the recovering cocycle constructed in Theorem (thm:g400 of the paper). 
The geodesic $\pi$  is an $A_\pi$-geodesic. It lies  between $\phi_{}^{\pi_k,A_\pi,-}$ and $\phi_{}^{\pi_k,A_\pi,+}$, the two geodesics generated by $A_\pi$ that  resolve ties by taking $e_2$ and $e_1$ steps, respectively:
\begin{equation}
\phi_{}^{\pi_k,A_\pi,-}\preceq \pi \preceq \phi_{}^{\pi_k,A_\pi,+}.\qedhere\end{equation}

