[Lemma l.invar_cascade of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] For every $q\in \mathcal Q_\infty$, every Lipschitz $\mathbf{g}:\mathbb{R}^{D}\to\mathbb{R}$, and every bounded measurable $\rho:\mathbb{R}\to \mathbb{R}$, we have
\begin{align*}
    \mathbb{E} \left\langle \rho \left(\mathbf{h}\wedge\mathbf{h}'\right) \right\rangle_{\mathfrak{R}^\mathbf{g}} = \int_0^1 \rho(s) \mathrm{d} s.
\end{align*}

[Propo 5 (Size-biased and discounted Galton-Watson process with $k$ spines under $\Q^{(k),\bm \theta}_{T,r}$) of arXiv:2605.11264, 'Uniform sampling of multitype continuous-time Bienaym\'e-Galton-Watson trees'] Let $T\in \re_+$, $t\in (0,T)$, $k\in \na$, and $r\in [d]$.
Consider the process $\mathcal{N}=(\mathcal N_t)_{t\in [0,T]}$ with $k$ spines $\bm \varsigma_t=( \varsigma^{(1)}_t,\ldots,  \varsigma^{(k)}_t)$ at time $t$, under $\Q^{(k),\bm \theta}_{T,r}$. 
Then, $\mathcal N$ evolves as follows:
\begin{enumerate}
	\item The process starts at time 0 with one particle carrying all $k$ spines (i.e., $\mathcal{N}_0=\{\emptyset\} $, and $\bm\varsigma_0=(\emptyset,\ldots, \emptyset) $).
	\item A particle carrying $h\in [k]$ spines evolves a subtree forward in time independently of the rest of the process (branching Markov property).
	\item A particle type $i\in [d]$ carrying $h\in [k]$ spines at time $t\in (0,T)$, branches into $\bm \ell\in \z^d_+\setminus\{\bo 0\}$ offspring, and the $h$ spines split into $g_m\in \{0,1,\ldots,\ell_m\}$ different individuals (groups) of type $m\in [d]$, the $q$-th carrying $a_{m,q} \in [h]$ marks, with $\sum_{m\in[d]} \overline{a}_{m}=h$ and $q\in [g_m]$, at rate
	\begin{equation}
		\begin{split}
			& \alpha_i\E_i\left[\bo L^{\floor{\bo g}}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-g_m}\right]
			\\
			& \hspace{1cm} \times\frac{\bm \ell^{\floor{\bo g}}			\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{\ell_m-g_m}p_i(\bm{\ell})}{\E_i\left[\bo L^{\floor{\bo g}}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-g_m}\right]}
			\frac{\prod_{\substack{m\in [d]\\ g_m\neq 0}}\prod_{q=1}^{g_m}\E_m\left[N^{\floor{a_{m,q}}}_{T-t}e^{-\bm \theta \cdot \bo Z_{T-t}}\right]}{\E_i\left[N^{\floor{h}}_{T-t}e^{-\bm \theta\cdot \bo Z_{T-t}}\right]}.
		\end{split}
	\end{equation}In particular, a birth off the spine, that is, all marks follow the same vertex type $j\in [d]$, occurs at rate 
	\begin{equation}
		\begin{split}
			& \alpha_i\E_i\left[L^{(j)}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-\delta_{m,j}}\right]\\
			&\hspace{4cm}\times\frac{\ell_{j}p_i(\bm{\ell})
			\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{\ell_m}}{\E_i\left[L^{(j)}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}}\right]}
			\frac{\E_{j}\left[N^{\floor{h}}_{T-t}e^{-\bm \theta \cdot \bo Z_{T-t}}\right]}{\E_i\left[N^{\floor{h}}_{T-t}e^{-\bm \theta\cdot \bo Z_{T-t}}\right]}.
		\end{split}
	\end{equation}
	\item 
Given a particle carrying $h$ spines branches into $\bm \ell$ offspring, where the $h$ spines split into $g_m$ groups of type $m$, each of size $a_{m,q}$, the spines are assigned between the offspring as follows:
	\begin{itemize}
	\item Choose $\bo g$ of the $\bm \ell$ offspring to carry the spine groups uniformly amongst the $ \prod_{m=1}^d{\ell_m \choose g_m}$ distinct ways.
\item For each of the $g_m$ offspring chosen to carry the spine groups, assign group sizes $a_{m,1},\ldots, a_{m,g_m}$ amongst the $g_m$ offspring uniformly amongst the $g_m!/\prod_{n\geq 1}d_{m,n}!$ distinct allocations.
\item Partition the $h$ (labelled) spines between the $d$ types with their given group sizes $\overline a_{1},\ldots, \overline a_{d}$ uniformly amongst the $h!/\prod_{m=1}^{d} \overline a_m!$ distinct ways.
\item Partition the $\overline a_m$ (labelled) spines between the $g_m$  individuals carrying marks, using the block sizes $(a_{m,q})_{q\in [g_m]}$, uniformly amongst the $\overline a_m!/\prod_{q=1}^{g_m} a_{m,q}!$ distinct ways.
	\end{itemize}
	\item Finally, any particle $v$ type $i$, which is alive at time $t$ and carries no spines, behaves independently of the remainder of the process and undergoes branching into offspring that carry no spines at rate
\[
\alpha_i\frac{\E_i\left[\prod_{m=1}^d\E_m\left[e^{-\bm \theta\cdot \bo Z_{T-t} }\right]^{ L^{(m)}} \right]}{\E_i\left[e^{-\bm \theta\cdot \bo Z_{T-t} }\right]}{\rm d} t,
\]and given there is a branching event, there are $\bm \ell$ offspring with probability
\[
