[Lemma 11 of arXiv:2608.11071, 'Scaling Laws for Majority-based Opinion Dynamics in the Presence of Stubborn Agents'] Suppose that $N_0^n=N_1^n=\ceil{n\gamma}$ for some $\gamma\in(0,1/2)$. Let $X^n$ and $\bar X^n$ be two chains, each following the rates in~\eqref{eq:uprate}-\eqref{eq:downrate} and started at $x\in \mc S^n$ and $\bar x\in \mc S^n$, respectively. Assume without loss generality that $|x-1/2|\geq |\bar x -1/2|$. Then we have
    \begin{align}
        T_{\text{couple}}^{n}(X^n,\bar X^n) \leq_{st} T_{\text{enter}}^n(r)\nonumber,
    \end{align}
    where $T^n_{\text{couple}}(X^n,\bar X^n)=\inf\{t\geq 0: X^n(t)=\bar X^n(t)\}$ is the first time the two chains meet and
    $T_{\text{enter}}^n(r)=\inf\{t\geq 0: (r-x)(r-X^n(t))\leq 0\}$, as defined before, is the first time the chain $X^n$ crosses $r$.

[Lemma 15 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let 
\begin{equation}

p,q\in(1,\infty),\quad
\nu:=1-\frac{d}{p}-\frac{1}{q}\geq0.
\end{equation}
Suppose that Assumptions \ref{assumption 9.24.2}
and
\ref{assumption 6.2.1}  are satisfied and let   $u\in W^{1,2}_{(q,p)}
(\cO)\cap C(\bar \cO)$.  
Then on $Q$
\begin{equation}

u \leq \sup_{\partial'\cO}u_{+}+N(d,p_{0})C
\big\|c^{-\nu}r^{-1/q}(\det a)^{-1/p}(\cL u)_{-}
\big\|_{L_{(q,p)}(\cO )},
\end{equation}
where  
$$
C= \Big(R+ \|h\|_{L_{(q_{0},p_{0})}}
^{  p_{0}/(p_{0}-d)  } 
\Big)^{ d/p}  
 $$
if $p_{0}\ne d$ and $C= N(d,\|h\|_{L_{(\infty,d)}}) R$ if $p_{0}=d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:rieszcomp of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For any $0<\alpha,\beta,\alpha+\beta<d$ and $x\neq y$,
    \begin{align*}
      \int_{\mathbb R^d} \|x-z\|^{\alpha-d} \|z-y\|^{\beta -d}dz=k_{\alpha,\beta,d} \|x-y\|^{\alpha+\beta-d}, 
  \end{align*}
  with the coefficient \begin{align*}
    k_{\alpha,\beta,d} =\pi^{d/2}\frac{\Gamma(\frac{\alpha}{2})\Gamma(\frac{\beta}{2})\Gamma(\frac{d-\alpha-\beta}{2})}{\Gamma(\frac{d-\alpha}{2})\Gamma(\frac{d-\beta}{2})\Gamma(\frac{\alpha+\beta}{2})}.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Suppose that,
\begin{equation}

\gamma-\tau\leq \theta_{\tau}\tau'_{ R}(x_{\tau}),
\end{equation}
where $\theta_{\tau}\tau'_{ R}(x_{\tau})$ is  the first exit time of $x_{ \tau +s}$
from $B_{R}(x_{\tau})$, then $A\leq 2B^{2}+RB\leq 3B^{2}+R^{2}$,
so that $A$ in \eqref{4.24.1} can be replaced
with $R$. If, in addition, $B\leq KR$,
where $K$ is a constant, then
$$
E_{\cF_{\tau}}\int_{\tau}^{\gamma}e^{-\phi_{\tau,t}}(r_{t}\det a_{t})^{1/(d+1)}
f(\sft_{t},x_{t})\,dA_{t}
$$
$$
\leq N(d)(1+K)^{d/(d+1)}R^{d/(d+1)}
\|f\|_{L_{ d+1} }.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

