[Lemma l38 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] The sequence of measures ${\mathbb Q}^M_N = {\mathbb P}_{\nu^N} \circ (M^N)^{-1}$
on $D([0,T], {\mathscr D}'({\mathbb R} \times {\mathbb T}^{d-1}))$ converges, as
$N\to\infty$, to the centered Gaussian random field whose covariances
are given by
\begin{equation}

\begin{aligned}
{\mathbb Q}^M \big[\, M_t(F) \, M_s(G)\,\big]\; & =\;
2\, (s\wedge t)\,  \int_{{\mathbb R}} d\vartheta \; 
\chi (\phi  (\vartheta)) \, \int_{{\mathbb T}^{d-1}} d\theta \;
(\partial_\vartheta F)(\vartheta, \theta)\,
(\partial_\vartheta G)(\vartheta, \theta)\,
\\
& +\; (s\wedge t)\, \int_{{\mathbb R}} d\vartheta \;
\widehat c_0(\phi  (\vartheta)) \,
\int_{{\mathbb T}^{d-1}} d\theta \; F(\vartheta, \theta)\,
G (\vartheta, \theta)\,   \;
\end{aligned}
\end{equation}
for all $F$, $G$ in $C^\infty({\mathbb R} \times {\mathbb T}^{d-1})$ with compact
support. Here, ${\mathbb Q}^M$ stands also for the respective expectation.

[Lemma 21 of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume Assumption~\ref{ass:second-malliavin-uniform}. Let $\hat{\omega}$ be the constant defined via \eqref{eq:def-omega-second-malliavin}. Fix
$ 0 \le r \le s \le u $, $ i,j,k \in \left\{ 1,\dots,N \right\} $, and
$ \alpha,\beta \in \left\{ 1,\dots,m \right\} $. Define, for every $\rho \in [s,u]$,
\begin{equation*}
Y_\rho^{q,j,k,\alpha,\beta}
=
D_r^{k,\beta} D_s^{j,\alpha} X_\rho^{q,N}\quad\mbox{and}\quad
\bar v(\rho)
=
\frac1N \sum_{q=1}^N
\E\left(
\norm{Y_\rho^{q,j,k,\alpha,\beta}}^4
\right)^{1/4}.
\end{equation*}
Then, there exists a constant $ C > 0 $, depending only on the constants in
Assumption~\ref{ass:second-malliavin-uniform}, such that the following bounds hold.

\begin{enumerate}
\item[(i)] The initial condition in Lemma~\ref{lem:secondSDE} satisfies
\begin{align}

&\E\left(\norm{
\mathcal I_{r,s}^{i,j,k,\alpha,\beta}
}^4
\right)^{1/4}
\le
C e^{-\hat{\omega} (s-r)}
\left(
\mathbf{1}_{\left\{ i=j=k \right\}}
+
\frac1N
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\mathbf{1}_{\left\{ i=k \right\}}
\right)
+
\frac1{N^2}
\right).
\end{align}

\item[(ii)] For every $ \rho \in [s,u] $,
\begin{equation}

\E\left(
\abs{G_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
+
\norm{H_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
\right)^{1/4}
\le
2^{1/4}\gamma \bar v(\rho).
\end{equation}

\item[(iii)] For every $ \rho \in [s,u] $,
\begin{align}

&\E\left(
\norm{R_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
+
\norm{S_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
  \right)^{1/4}\nonumber \\
  &\qquad\qquad\qquad\qquad
\le
C e^{-\hat{\omega} (\rho-r)}
\left(
\mathbf{1}_{\left\{ i=j=k \right\}}
+
\frac1N
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\mathbf{1}_{\left\{ i=k \right\}}
+
\mathbf{1}_{\left\{ j=k \right\}}
\right)
+
\frac1{N^2}
\right).
\end{align}
\end{enumerate}

