body:
[Lemma 13 of arXiv:2607.22878, 'Clustering of large deviations in heavy-tailed moving averages: the catastrophe principle '] Let $(Z_i)$  be i.i.d.  zero mean one-dimensional random variables that are 
  regularly varying with index $\alpha>1$. Let $\{\lambda_n\}$ be a
  sequence of positive real numbers. For each $n=1,2,\ldots$ let 
  $\{\beta_{in}\}_{i =
    -\infty}^\infty $ be a sequence satisfying for all  
  $n$, $|\beta_{in}| \leq
  \lambda_n$  for all $i$, and $\sum_{i = -\infty}^\infty
  |\beta_{in}|^{\alpha - s} = o(\lambda_n^{\alpha -s})$ for all small
  enough $s > 0$. Then for any $\delta, \tau> 0$, $s>0$ small enough
  and all $n\geq
n_0(s,\tau/B)$ (that may also depend on the distribution of $Z$), we have 
   \begin{equation}
  \begin{aligned}
    &  P\left(|\sum_{i = -\infty}^\infty \beta_{in} Z_i\one(|\beta_{in} Z_i| \leq \lambda_n \tau)| > \delta\lambda_n\right) \\
      \leq & \begin{cases}
    \left(\frac{(1+s)\sum_{i = -\infty}^\infty |\beta_{in}|^{\alpha -
          s}}{ \delta \tau^{\alpha-s-1} \lambda_n^{\alpha -
          s}}\right)^{\delta/4\tau} & \text{ if } \ 1< \alpha \leq 2\\
    \left(\frac{E[Z^2] \sum_{i=-\infty}^\infty\beta_{in}^2}{\delta
        \tau\lambda_n^2} \right)^{\delta/4\tau} & \text{ if } \ \alpha > 2
      \end{cases}
  \end{aligned}  
\end{equation}
and 
  \begin{equation}
  \begin{aligned}
       & P\left(|\sum_{i = -\infty}^\infty \beta_{in} Z_i| > \delta\lambda_n\right) \\
       \leq & \begin{cases}
           (1+s) \lambda_n^{- \alpha + s}  \sum_{i = -\infty}^\infty
           \beta_{in}^{\alpha - s}  +   \left(\frac{(1+s)\sum_{i = -\infty}^\infty |\beta_{in}|^{\alpha - s}}{ \delta \tau^{\alpha-s-1} \lambda_n^{\alpha - s}}\right)^{\delta/4\tau}
 & \text{ if } \ 1 < \alpha \leq 2\\
            (1+s) \lambda_n^{- \alpha + s}  \sum_{i = -\infty}^\infty
            \beta_{in}^{\alpha - s}  +  \left(\frac{E[Z^2]
                \sum_{i=-\infty}^\infty\beta_{in}^2}{\delta
                \tau\lambda_n^2} \right)^{\delta/4\tau} 
& \text{ if }\ \alpha > 2
       \end{cases} 
  \end{aligned}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma multiesti of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $u,v,w\in L^2(\mathbb{R}^2)$ with $\|u\|_{L^2} = \|v\|_{L^2} = \|w\|_{L^2} = 1$. Assume $N_{\mathrm{min}}\geq 2$. Then
		\begin{itemize}
			\item[(a)] 
			\begin{align*}
				\left|\int_{\mathbb{R}^2}Q_{L_1}P_{N_1}uQ_{L_2}P_{N_2}v Q_{L_3}P_{N_3}w~dxdt\right| \lesssim L_{\mathrm{min}}^{1/2}N_{\mathrm{min}}^{1/2}.
			\end{align*}
			\item[(b)] If $N_{\mathrm{min}}\ll N_{\mathrm{max}}$, then
			\begin{align*}
				&\quad \left|\int_{\mathbb{R}^2}Q_{L_1}P_{N_1}uQ_{L_2}P_{N_2}v Q_{L_3}P_{N_3}w~dxdt\right|\\
				&\lesssim (L_1L_2L_3)^{1/2}N_{\mathrm{max}}^{-1/2}\left(\max_{1\leq j\leq 3}\{N_j L_j\}\right)^{-1/2}.
			\end{align*}
			\item[(c)] If $N_{\mathrm{min}}\sim N_{\mathrm{max}}$, then
			\begin{align*}
				\left|\int_{\mathbb{R}^2}Q_{L_1}P_{N_1}uQ_{L_2}P_{N_2}v Q_{L_3}P_{N_3}w~dxdt\right| \lesssim L_{\min}^{1/2}L_{\mathrm{med}}^{1/4}N_{\max}^{-1/4}.
			\end{align*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 ({\cite[Theorem 4.1) of arXiv:2608.26803, 'On bubbling of Fueter maps'] {HNS09}}]
  Suppose that the data $(M, X, \cI)$ is as in Definition \ref{Setup}. For a generic $H \in \cP^m$, the solution space
  \begin{equation*}
    \cM(H) \coloneq \{ f \in W^{k, p}(M, X) \,| \, \cF_H f = 0 \} 
  \end{equation*}
  is a smooth $0$--dimensional submanifold of $W^{k, p}(M, X)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Assume that the subordinator $S(t)$, $t\ge0$, is given by a general exponent $\phi$ as in \eqref{bernstein-eq} with $b>0$ or $\nu(0,+\infty)=+\infty$, and let $L(t)$, $t \geq 0$ be its inverse subordinator. Let $P_s$, $s \geq 0$, be a strongly continuous semigroup of operators on some Banach space $(\mathfrak{B}, \left\| \cdot \right\|)$, with the generator $(G,\DD(G))$, {such that}
		\begin{align}
			\left\| P_t u \right\| \, \leq \, M e^{\lambda_0 t} \left\| u \right\|, \quad {u \in \mathfrak{B},}
		\end{align}
		{where $M>0$ and $\lambda_0\ge0$}\footnote{{All strongly continuous semigroups are exponentially bounded in this way, see Appendix \ref{appendix_semigroups}.}}. Define
		\begin{align}
			\mathcal{P}_tu \, = \, \int_0^{+\infty} P_su \, l_t(ds),
		\end{align}
		as a Bochner integral on $\mathfrak{B}$, where $l_t(ds)$  denotes the distribution of $L$ under $\PP^{(x,0)}$ (which is independent of $x$).

		Then, whenever $u \in \mathfrak{B}$, the mapping $[0,+\infty)\ni t \mapsto q(t) \coloneqq \mathcal{P}_tu$ is strongly continuous on $\mathfrak{B}$ and {exponentially} bounded ({bounded by a constant if $\lambda_0=0$}). If, in addition, $u \in \mathcal{D}(G)$, then
		\begin{align}
			\phi(\partial_t) (q(t)-q(0)) \, = \, G q(t), \qquad q(0) = u,

		\end{align}
		in the sense that $q(t) \in \mathcal{D}(G)$ for all $t \geq 0$, $t \mapsto q(t)$ is strongly continuous (on $\mathfrak{B}$) and {exponentially} bounded {(bounded by a constant if $\lambda_0=0$)}, the generalized derivative on the left hand side of \eqref{eq_conv_theorem} exists for all $t > 0$ in the strong sense, and both $t \mapsto Gq(t)$ and $t \mapsto \phi(\partial_t) (q(t)-q(0))$ are strongly continuous and {exponentially} bounded {(bounded if $\lambda_0=0$)}.

		Finally, if $\mathpzc{q}(t)$ is another solution with the same properties as above, then $\mathpzc{q}(t) = q(t)$ for all $t \geq 0$.

