[Proposition pro.additive-renewal of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] For every $\lambda\in(0,1]$, the limit $\lim_{t\to\infty}t^{-1}A^\lambda(t)$ exists $\widehat{\mathbb P}_0^\lambda$-almost surely and in $L^1(\widehat{\mathbb P}_0^\lambda)$ and is the deterministic number
	\begin{equation}
	\eta(\lambda)=\frac{\widehat{\mathbb E}_0^\lambda\left[\int_{\tau_1}^{\tau_2}e^{-2V(X^\lambda(s))} ds\right]}{\widehat{\mathbb E}_0^\lambda[\Delta\tau_1]}\, .
	\end{equation}
	Moreover,
	\begin{equation}
		\Lambda^{-1}\le\eta(\lambda)\le\Lambda\, .
	\end{equation}
		For every integer $M\ge2$, there exists a finite constant $C=C(M,d,\Lambda,r_0)>0$ such that for all $\lambda\in(0,1]$ and all $t\ge\lambda^{-2}$,
		\begin{equation}
			\mathbb{E}_\mathbb{Q} \widehat E^{\lambda,\omega}_0\big|A^\lambda(t)-\eta(\lambda)t\big|^M
			\le C\lambda^{-M}t^{M/2}\, .
		\end{equation}

