[Lemma 19 of arXiv:2609.03098, 'Standing waves for Schr\"odinger equations with Kato class potentials and $L^\infty$-bound'] The mapping $G$ is continuous and there exist constants $M_G>0$ and $L_G>0$ such that
			\begin{equation}
				\| G(u,s)\|_{L^\infty}\leq M_G, \quad u\in H^1(\R^N), \ s\in [0,1],
			\end{equation}
			\begin{equation}
				\|G(u_1, s)-G(u_2, s)\|_{L^2} \leq L_G \|u_1-u_2\|_{H^1}, \quad u_1, u_2\in H^1(\R^N), \ s\in [0,1].
			\end{equation}
			Moreover, there exist constants $0 < L_\sigma < \gamma$ and $C_\sigma > 0$ such that
			\begin{equation}
				\|G(u,s)\|_{L^2} \leq L_\sigma ( \|Pu\|_{L^2} + \|Qu\|_{L^2} ) + C_\sigma, \quad u\in H^1(\R^N), \ s\in [0,1].
			\end{equation}

