body:
[Theorem thm:strongconvergence of arXiv:2608.21931, 'Interacting Urn Schemes on Finite Ancestral Directed Acyclic Graphs'] Suppose that the underlying graph $\overrightarrow{\mathbb{G}}$ is an FA-DAG and that
Assumption~(asm:strongconvergence of the paper) holds. Then all urn-proportions
$\{\U{n}{v}:n\geq0,\ v\in V\}$ converge almost surely. More precisely, for
each $v\in V$, there exists a $k$-dimensional random vector
$\U{\infty}{v}$ such that
\begin{equation}
    \U{n}{v}\xrightarrow{a.s.}\U{\infty}{v},
    \qquad\text{as }n\rightarrow\infty.
\end{equation}

For the sum-reinforcement scheme, the limiting proportions are
characterized recursively by
\begin{equation}
\U{\infty}{v}
=
\begin{cases}
\U{0}{v},
& \text{if }v\in S,\\[0.4cm]
\displaystyle
\frac{
\sum\limits_{\substack{u:u\rightsquigarrow v,u\in G}}
\N{\infty}{u}R^{(u,v)}
+
\sum\limits_{\substack{u:u\rightsquigarrow v,u\in V\setminus G}}
\U{\infty}{u}R^{(u,v)}
}{
\sum\limits_{\substack{u:u\rightsquigarrow v,u\in G}}
\N{\infty}{u}R^{(u,v)}\mathbbm{1}'
+
\sum\limits_{\substack{u:u\rightsquigarrow v,u\in V\setminus G}}
\U{\infty}{u}R^{(u,v)}\mathbbm{1}'
},
& \text{if }v\in V\setminus S.
\end{cases}
\end{equation}

For the average-reinforcement scheme, the limiting proportions are
characterized by the same recursion, with each reinforcement matrix
$R^{(u,v)}$ replaced by $R^{(u,v)}/d_v^{\mathrm{in}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:independent_cousins of arXiv:2606.11503, 'Percolation on hierarchical lattices'] Fix $0 \leq j < k$, $p \in [0,1]$, and a consistent set of labels $\mathcal{L} = (l^w)_{w \in \mathcal{E}_{1}^j}$.
  Then
  \begin{enumerate}[\quad a)]
  \item ``The families produced by individuals at generation $j$ are independent'':
    \begin{equation}

      \big( L^{we_1}, \dots, L^{we_{|\mathcal{E}_{1}|}} \big)_{w \in \mathcal{E}_{1}^{j}}
      \text{, are independent under }
      \mathbb{P}^{k}_{p} \big[ \cdot \big|
      L^w = l^w; \text{ for $w \in \mathcal{E}_{1}^{j}$} \big],
    \end{equation}
    see (r:cousins of the paper).
  \item ``The type of your father is the only relevant information about your previous generation'':\\
    Fixed $w_0 \in \mathcal{E}_{1}^{j}$ and some function $f: \{0, 1\}^{3 \times |\mathcal{E}_{1}|} \to \mathbb{R}$,
    \begin{equation}

      \begin{split}
        \mathbb{E}_{p}^{k} \Big[ f \big( L^{w_0e_1}, & \dots, L^{w_0e_{|\mathcal{E}_{1}|}} \big)
                                                 \Big| L^w = l^w; \text{ for all $w \in \mathcal{E}_{1}^{j}$}
                                                 \Big]\\
        = & \mathbb{E}_{p}^{k} \Big[
            f \big( L^{w_0e_1}, \dots, L^{w_0e_{|\mathcal{E}_{1}|}} \big)
            \Big| L^{w_0} = l^{w_0} \Big],
      \end{split}
    \end{equation}
    see again (r:cousins of the paper) for a discussion.
  \item ``The offspring distribution is homogeneous across generations at the critical point $p_{\star}$'':
    \begin{equation}

      \mathbb{E}_{p_{\star}}^{k} \Big[
      f \big( L^{w_0e_1}, \dots, L^{w_0e_{|\mathcal{E}_{1}|}} \big)
      \Big| L^{w_0} = l^{w_0} \Big]
      = \mathbb{E}_{p_{\star}}^{k - j} \Big[
      f \big( L^{e_1}, \dots, L^{e_{|\mathcal{E}_{1}|}} \big)
      \Big| L^{\varnothing} = l^{w_{0}} \Big].
    \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:second_moment of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $0\leq s<t \leq N$ and $x,y\in\mathbb{Z}^2$. Then
\begin{equation}
    {\mathbb E}[W_{s,t}(x)W_{s,t}(y)]=E_{x-y}\left[e^{\beta_N^2\sum_{n=s+1}^{t} h(S_{2n})}\right].
\end{equation}
Furthermore, with $\bar \sigma_N^2 := e^{\beta_N^2 } \beta_N^2$,
    \begin{equation} 
    E_{x}\left[\prod_{n=s+1}^{t} \{1+\beta_N^2 h(S_{2n})\}\right] \leq {\mathbb E}[W_{s,t}(x)W_{s,t}(0)] \leq E_{x}\left[\prod_{n=s+1}^{t} \{1+\bar \sigma_N^2  h(S_{2n})\}\right].
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2607.19549, 'The Generalized Friendship Paradox for Eigenvectors'] As $n \to \infty$, for \textbf{Model A} we have 
\begin{align*}
\max_{1 \le i \le n}\left|\frac{d_i}{n}-K\left(\frac{i}{n}\right)\right|\overset{p}{\to}0,    
\end{align*} while for \textbf{Model B} we have,
\begin{align*}
    \max_{1 \le i \le n}\left|\frac{d_i}{n\varepsilon_n}-K\left(\frac{i}{n}\right)\right|\overset{p}{\to}0.
\end{align*}

