[Theorem 10 (Truncation error) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under the same assumptions of \cref{thm:sequence-statistical}, the truncated posterior computed by  \cref{alg:spectral} satisfies
    \begin{equation}
    \E\sbr{\Wp^2(Q_t^{(m)},\Pi_t)}
    \lesssim m^{1-\zeta}+t^{-(\zeta-1)/\zeta}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:eta-entropy of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] For every \(T>0\),  it holds that
\begin{equation}
\begin{aligned}
  \frac1N
  \mathrm{Ent}\left(
    \mathbf P_{N,T}
    \mid
    \mathbf q_T^{\otimes N}
  \right)
  &\le
  \frac{\eta \Lambda_L}{1-\eta}
  \int_0^T
  \mathbb E_{\mathbb Q^{N,\mathrm{full}}}
  \left[
    \left\|
      R_t^{N:(1)}-X_t^1
    \right\|_1
  \right]\mathrm d t\le
  C_{\eta,T}N^{-1/4},
\end{aligned}

\end{equation}
for some $C_{\eta, T}>0$.

[Lemma lem:LGJ-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,r,n}$ and $\phi_{t,r,n}$ satisfy the linear
problem (equation eq:Linear-Psi-3 of the paper) and the adjoint
linear problem (equation eq:Linear-Phi-Prob of the paper) on
$\mathcal{V}$ with edge weights
$(c_k, \lambda_k)$.  Explicitly, for each fixed
$r \in \mathbb{Z}$:
\begin{align}
\psi_{t,r,n+1}
&= (1{-}\theta)^{-1} \psi_{t,r+1,n}
   - (1{-}\theta)^{-1}\theta \psi_{t,r,n},
 \\
\psi_{t-1,r,n}
&= -q(p\theta)^{-1} \psi_{t,r+1,n}
   + p^{-1} \psi_{t,r,n},

\end{align}
and
\begin{align}
\phi_{t,r+1,n}
&= (1{-}\theta)^{-1} \phi_{t,r,n+1}
   - (1{-}\theta)^{-1}\theta \phi_{t,r+1,n+1},
 \\
\phi_{t,r+1,n}
&= -q(p\theta)^{-1} \phi_{t-1,r,n}
   + p^{-1} \phi_{t-1,r+1,n}.

\end{align}

