[Proposition prop:CE-law of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Let $V\subset \mathbb Z^2$ be a connected domain, and consider the \ensuremath{\mathbb Z\textsc{gff}}\xspace model ${\widehat\pi}_V^\xi$ with boundary conditions $\xi$ that are $1$ on a $*$-connected path in $\partial_{\mathtt v} V$ and $0$ elsewhere so that they induce a unique disagreement polymer $(\gamma,\{D_i\},\{h_i\})$ in $V\cup \partial_{\mathtt v} V$ that contains boundary disagreements. Then for $\beta\geq \beta_0$, the law of this unique disagreement polymer is given by 
		\begin{equation}
			{\widehat\pi}^\xi_V(\gamma) =\frac1{Z} \exp\bigg(-{\ensuremath{\mathscr E}}_\beta(\gamma) + \sum_{\substack{{\ensuremath{\mathsf W}} \subset V \\ 
					{\ensuremath{\mathsf W}} \cap \Delta_\gamma \neq \emptyset}} \Phi({\ensuremath{\mathsf W}})\bigg)
		\end{equation}
		for a normalizer $Z = Z(\xi,V,\beta)$ and a decoration function $\Phi({\ensuremath{\mathsf W}})$ as per (def:disagree-polymer-len-energy-decor of the paper).

[Theorem 1 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] The following identities hold true for $\mu,\nu \in \mathcal{P}_2(\Rd)$ that share the barycentre $[\mu] = [\nu]$,
\begin{align*}
	Z_2(\mu,\nu) &= \min\left\{ \int_X \! \int_Y \!\frac{1}{2} \bigg( \Big| \frac{dq}{d\gamma}(x,y) - x \Big|^2\! \!\!+ \Big| \frac{dq}{d\gamma}(x,y) - y \Big|^2  \bigg)   \gamma(dxdy) \, : \, 	(\gamma,q) \in \Gamma Q(\mu,\nu)  \right\}, \\
	\mathcal{C}(\mu,\nu) &=  \min\left\{ \int_X \! \int_Y \Big| \frac{dq}{d\gamma}(x,y) \Big|^2   \gamma(dxdy) \, : \, 	(\gamma,q) \in \Gamma Q(\mu,\nu)  \right\},
\end{align*}
and both problems share a non-empty set of solutions.
Moreover, the following conditions are equivalent for any pair $(\gamma,q) = (\gamma,\zeta \gamma) \in \Gamma Q(\mu,\nu)$:
\begin{enumerate}[label={(\roman*)}]
	\item $(\gamma,\zeta\gamma)$ solves either of the two problems above;
	\item for any optimal potential $\ov{u}$ for the Zolotarev problem \eqref{eq:Z2} there holds $\zeta = \ov\zeta$ \ $\gamma$-a.e., where $\ov\zeta: \Rd \times \Rd \to \Rd$ is a Lipschitz continuous coupling map as below,
	\begin{equation}

		\ov\zeta(x,y) := \frac{x+y}{2} + \frac{\nabla \ov{u}(x) - \nabla \ov{u}(y)}{2};
	\end{equation}
		\item ${\rho} = {\zeta} \# {\gamma}$ is a convex dominant of the least second moment, namely $ {\zeta} \# {\gamma}$ solves   \eqref{eq:minDom};
		\item ${\rho} = {\zeta} \# {\gamma}$ is a Zolotarev projection of $\nu$ onto the cone $\{ \argu \succeq_c \mu\}$, namely $ {\zeta} \# {\gamma} \in \Pi_{\succeq_c \mu} (\nu)$;
		\item ${\rho} = {\zeta} \# {\gamma}$ is a Zolotarev projection of $\mu$ onto the cone $\{ \argu \succeq_c \nu\}$, namely $ {\zeta} \# {\gamma} \in \Pi_{\succeq_c \nu} (\mu)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2506.16260, 'Fractional Compound Poisson Random Fields on Plane'] Let $\{N(t),\ t\ge0\}$ be a Poisson process with transition rate $\lambda>0$ and $\{T_{2\alpha_i}(t_i),\ t_i\ge0\}$, $i=1,2$ be random processes as defined in Theorem \ref{thm5}. Also, it is assumed that all these processes are independent of each other. Then, the following holds true for TFPRF: 
\begin{equation}
	N_{\alpha_1,\alpha_2}(t_1,t_2)\overset{d}{=}N(T_{2\alpha_1}(t_1)T_{2\alpha_2}(t_2)),\ (t_1,t_2)\in\mathbb{R}^2_+.
\end{equation}

