[Lemma 14 (Truncated spacetime estimate) of arXiv:2608.25971, 'Positive \texorpdfstring{$\tau$}{tau}-bi-Ricci curvature and Mean curvature flow with surg'] Fix $\eta>0$ under \eqref{eq:normalized-space-form-setting}, and choose $ r>{(n+2)}/{2}$.  
There is $p_0=p_0(n,\alpha,\eta,r)$ such that the following holds.  If
$p\geq p_0$, $\sigma=p^{-1}$, $f=f_{\sigma,\eta}$, and
\begin{equation*}
 k\geq k_0:=1+\sup_{M_0}f_+,
 \qquad f_k=(f-k)_+,
\end{equation*}
then
\begin{align}
 &\sup_{0\leq s<T}\int_{M_s}f_k^p\,d\mu
 +\int_0^T\!\!\int_{M_s}
   \left(f_k^{p-2}|\nabla f|^2
   +f_k^{p-1}H^{\sigma-4}|\mathcal D|^2
   +H^2f_k^p\right)d\mu\,ds\notag\\
 &\hspace{35mm}\leq
 C\int_0^T\!\!\int_{\{f(\cdot,s)>k\}}
   \bigl(H^2f_+^p+1\bigr)d\mu\,ds,

\end{align}
where $C=C(n,\alpha,\eta,p)$.  Moreover,
\begin{equation}
 \int_0^T\!\!\int_{M_s}\bigl(H^2f_+^p+1\bigr)^r\,d\mu\,ds
 \leq C(n,\alpha,\eta,p,r).
\end{equation}

[Lemma lem:B.9_Chebyshev of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For any  fixed  number $t>0$, let $n = \lfloor tM\rfloor$, then for  $y\in\mathbb{R}$,
\begin{equation}
\lim_{M\to\infty}
\frac{1}{n+1}\,
U_n\!\Bigl(1 + \frac{y}{2M^2}\Bigr)
\;=\;
\frac{\sin\bigl(t\sqrt{-y}\bigr)}{t\sqrt{-y}},
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:UB-LD-any-point of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] There exists $c_0>0$ such that, for $\beta$ large and every $V \subset \mathbb Z^2$, $h \geq 2$, and $x \in V$,
		\begin{equation}
			{\widehat\pi}_V^0(\phi_x = h) \leq \exp\bigg(-2\pi\beta\frac{h^2}{\log h} + c_0 \frac{h^2}{\log^2 h}\bigg)\,.
		\end{equation}

