    $$\tau_n =  \inf \{t \in [0,T] : \|X(t)\| \geq n\} \wedge T,$$
    and consider the truncated process $X^n(t) = X(t \wedge \tau_n)$ for $t \in [0,T]$. Then $X^n$ satisfies the SDE
    \begin{equation*}
        X^n(t) = X(0) + \int_{0}^{t} b(s, X^n_{[0,s]}) \Ind_{\{s \leq \tau_n\}} \, ds + \int_{0}^{t} \sigma(s,X^n_{[0,s]}) \Ind_{\{s \leq \tau_n\}} \, dW(s), \quad t \in [0,T].
    \end{equation*}
    Applying Hölder's inequality, Doob's martingale inequality and the linear growth condition \eqref{LG-condition-existence}, yields
    \begin{equation*}
        E\left[\sup_{0 \leq s \leq t} \|X^n(s)\|^{2m}\right] \leq 3 ...","release_manifest_digest":"sha256:60ff49911744355acad156b3e63af3212d91891475a6d7ae2c1bfc28bd9a31a0","revision_digest":"sha256:5157cf12d5a4ccf69bc9a6ac6f4565ba6aff17373300fe8c1487d01053a89713","source_id":"arxiv:2606.23099","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

