[Lemma lem:strict-regularity-implies-common-noise of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] Suppose that $L^1,\ldots,L^K$ satisfy Assumption~(cond:uniqueness of the paper), with orthogonal matrices $\mathbf Q_t^k$ as therein.  Then, for every $t\in[T]$, the unique minimizer of $\Phi_t$ over $\mathscr{P}_+(K,d)$ is the matrix $\mathbf P_t^\star$ of (equation eq:unique-local-P-star of the paper), with blocks $(\mathbf P_t^\star)^{k,\ell}=\mathbf Q_t^k(\mathbf Q_t^\ell)^\intercal$, and $\rank(\mathbf P_t^\star)=d$.  In particular, Condition~(cond:common-noise.input of the paper) holds, and the unique barycenter $\mathbb{G}^{
\accentset{\overline{\hphantom{L}}}{L}
}$ of Theorem~(thm:uniqueness of the paper) is the  representative in $\mathcal{FG}(T, d)$ provided by Theorem~(thm:FG-common-noise-criterion of the paper).

[Lemma 14 of arXiv:2607.27082, '2607.27082'] Let $\eta\in(0,1)$. Then there exist constants $K_\eta<\infty$ and
$N_\eta\in\mathbb{N}$ such that
\begin{equation}
\E\bigl(u^{\tau_n^+}\bigr)\le K_\eta\,n^{-r}
\end{equation}
for all $n\ge N_\eta$ and all $u\in[0,1-\eta]$.

[Prop 39 ({cf.~\cite[Theorem A) of arXiv:2609.02561, 'NON-NEF LOCI IN MIXED CHARACTERISTIC'] {ELMNP}}]
With notation as above, let $S^0$ be an affine open neighborhood of $c_{X}(v)$ in $S$.
The function
\[ v(\|-/S\|)=v_{\num}(-/S): \Bigcone(X/S)_{\Q} \rightarrow \R_{\geq 0} \]
uniquely extends to the continuous function
\[ \Bigcone(X/S)_{\R} \rightarrow \R_{\geq 0}, \]
mapping an $f$-big $\R$-Cartier $\R$-divisor $D$ on $X$ to
\begin{equation*}
\inf \left\{ v(D') \middle|
\begin{gathered}
 \text{$D'$ is a $\R$-Cartier $\R$-divisor on $f^{-1}(S^0)$} \\
 \text{such that $D|_{f^{-1}(S^0)} \equiv_{S^0} D' \geq 0$.}
\end{gathered} 
\right\} 
\end{equation*}

[Theorem 12 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] For any $p\geq 1$,  suppose that assumptions of Lemma \ref{thm:opao1} are satisfied with $q:=(p+p_0)\vee 2$ for some positive constant $p_0$.
		 Then, there exist two positive constants $C$, $ \varrho$ and a unique invariant probability measure  $\mu\in \msr P_p(E)$ such that $\mu P_t=\mu$ for every $t\geq 0$, and 
		\begin{equation*}
			\mathbb{W}_p\left(\delta_{(\xi, i)} P_{t}, \mu\right) \leq C(1+\|\xi\|_r)\e^{-\varrho t},\quad \text{for any }(\xi, i)\in E.
		\end{equation*}

[Lem lem16 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Assume ((h of the paper)), ((f0 of the paper)) and ((f1 of the paper)) 
  with some $\lambda>1$ and $K_f>0$, and suppose that $p\ge 2$ and $r\ge \max\{p,2\lambda\}$ are such that $p>n$, and that
  ((15.1 of the paper)), ((15.01 of the paper)) and ((15.02 of the paper)) hold.
  Then there exist $\eta=\eta(p,r,a,h,f)>0$, $\beta=\beta(p,r,a,h,f)>0$
  and $\Gamma_{12}=\Gamma_{12}(p,r,a,h,f)>0$ such that if ((init of the paper)) is valid with
  \begin{equation} \label{16.1}
	\int_\Omega |\nabla u_0|^r \le \eta
	\qquad \mbox{and} \qquad
	\int_\Omega |\nabla u_{0t}|^p \le \eta,
  \end{equation}
  then
  \begin{equation} \label{16.2}
	|u| + |u_t| \le \delta_1
	\qquad \mbox{in } \Omega\times (0,T_{max})
  \end{equation}
  and
  \begin{equation} \label{16.3}
	\int_\Omega |\nabla u(\cdot,t)|^r
	+ \int_\Omega |\nabla u_t(\cdot,t)|^p
	\le \Gamma_{12} e^{-\beta t}
	\qquad \mbox{for all } t\in (0,T_{max}),
  \end{equation}
  where $\delta_1=\delta_1(h)$ is as in Lemma (lem11 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] For every $\mu\in\mathcal M_*$ the following hold.
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item The operator $G_\mu$ is positive, injective, self-adjoint and
Hilbert--Schmidt on $L^2(\mu)$, and
\begin{equation}
 G_\mu=A_\mu^{-1}.

\end{equation}
\item The form inclusion
\begin{equation}
 j_\mu:(V_\mu,\|\cdot\|_{\E,\mu})\longrightarrow L^2(\mu)

\end{equation}
is compact.  In particular, $A_\mu$ has compact resolvent, no zero mode, and
\begin{equation}
 0<\Lambda_1^\mu\le\Lambda_2^\mu\le\cdots\uparrow\infty.

\end{equation}
\item
\begin{equation}
 G_\mu:L^2(\mu)\longrightarrow C_b(D),

\end{equation}
so every eigenfunction of $A_\mu$ has a bounded continuous representative.
\end{enumerate}

[Theorem 18 (Homogeneous windows are locally equivalent) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Assume edge homogeneity near $\theta_0$ and \cref{ass:regularity}. Let $m,n\ge1$ be admissible depths. Assume moreover the following representation hypothesis: every admissible edge-extension pair $(e,a)$ arising near $\theta_0$ is represented at both depths, in the sense that for each such pair there exist states $y\in\cS_m$ and $\widetilde y\in\cS_n$ whose last edge is $e$ and for which appending $a$ yields $U_m(y,a)$ and $U_n(\widetilde y,a)$, respectively. Then there exist fixed linear maps
\begin{equation*}
G_{m\to n}:\RR^{|\cS_m|^2}\to\RR^{|\cS_n|^2}, \qquad G_{n\to m}:\RR^{|\cS_n|^2}\to\RR^{|\cS_m|^2},
\end{equation*}
such that
\begin{equation}
q_{\cQ}^{(n)}(\theta)=G_{m\to n}(q_{\cQ}^{(m)}(\theta)), \qquad q_{\cQ}^{(m)}(\theta)=G_{n\to
m}(q_{\cQ}^{(n)}(\theta))
\end{equation}
for all $\theta$ near $\theta_0$.
Consequently,
\begin{equation*}
\rank\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_T\bigr)=\rank\bigl(Dq_{\cQ}^{(n)}(\theta_0)|_T\bigr)
\end{equation*}
for every tangent block $T\subset T_{\theta_0}\Theta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] {\cite[Theorem 6.2.2 and Proposition 6.2.9]{Dap-Zab2002}}
Assume that Hypotheses \ref{H0}, \ref{H0.5} and \ref{H1} hold. Then, for every $n\in\N$, $\varphi\in B_b(H_n)$, $t>0$ and $x,h,k\in H_n$ we have
\begin{align}
&|\scal{\nabla(R_n(t)\varphi)(x)}{h}_{H_n}|\leq \|\Gamma_{t,n}h\|_{H_n}\|\varphi\|_{\infty},\\
&|D^2(R_n(t)\varphi)(x)(h,k)|\leq \sqrt{2}\|\Gamma_{t,n}h\|_{H_n}\|\Gamma_{t,n}k\|_{H_n}\|\varphi\|_{\infty}.
\end{align}
Further, for every $n\in\N$, $\varphi\in C_b^1(H_n)$, $t>0$ and $x,h,k\in H_n$ we have
\begin{align}
&|\scal{\nabla(R_n(t)\varphi)(x)}{h}_{H_n}|\leq \|e^{tA_n}h\|_{H_n}\|\varphi\|_{C^1_b({H_n})},\\
&|D^2(R_n(t)\varphi)(x)(h,k)|\leq \|e^{tA_n}k\|_{H_n}\|\Gamma_{t,n}h\|_{H_n}\|\varphi\|_{C^1_b({H_n})}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:support of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Assume $\theta:=\lambda v>0$. If $c<1$, there is a unique $s_*>0$ satisfying
\begin{equation}
  cs_*^2\mathbb{E}\frac{R^2}{(1+cRs_*)^2}=1.

\end{equation}
With
\begin{equation}
  x_-:=\mathbb{E}\frac{R}{1+cRs_*}-\frac1{s_*},

\end{equation}
one has $x_->0$ and
\begin{equation}
  \operatorname{supp}\mu_{c,\lambda,v}=[x_-,\infty).

\end{equation}
If $c\ge1$, then
\begin{equation}
  \operatorname{supp}\mu_{c,\lambda,v}=[0,\infty).

\end{equation}
In particular, the support is unbounded whenever $\lambda v>0$.

[Proposition Hypo_Conseq-U of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] Assume that Hypothesis (Hyp-f-U of the paper) holds. Then
	\begin{align}
		\int_{-\infty}^{\mathfrak{r}} e^{\delta\zeta}\|\boldsymbol{\mathfrak{K}}(\cdot,\zeta)\|^2_{2}\/\mathrm{d}\/ \zeta<\infty, \ \ \text{ for all } \mathfrak{r}\in\mathbb{R},
	\end{align}
	where $\delta$ is the same as in (equation forcing2-U of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 65 of arXiv:2607.18104, '2607.18104'] Fix $T'\geq 0$, and initial data $h_0^{\per,(i),\varepsilon}$ for all $i\in \lbr M \rbr$. Then under the same assumptions as in Lemma~\ref{lem:CoupleASEPperiodic}, we find for every $\varepsilon'>0$ some $\delta_0=\delta_0(\varepsilon',T')$ so that 
\begin{equation}
     \bigg\lVert \Big(\hApeps(\hfix_0^{\per,(i),\varepsilon};\cdot,t)\Big)_{t \in [0,T'],i \in \lbr M \rbr} -  \Big(\hfix^{\textup{patch},\delta,\varepsilon}(\hfix_0^{\per,(i),\varepsilon};\cdot,t)\Big)_{t \in [0,T'],i \in \lbr M \rbr}\bigg\rVert_{\textup{TV}}\leq \varepsilon^{\prime} 
\end{equation} for all $\delta \leq \delta_0$, and $\varepsilon=\varepsilon(\delta)>0$ small enough.

