[Proposition 5 of arXiv:2512.10686, 'Maximal rigidity of random measures and uniqueness pairs: stealthy processes, quasicrystal'] $ \M$ is perfectly interpolable from the orthant $ \e_{ -}^{ d}$ if  
\begin{align}

 \S\leqslant \S_{ 1}\times \dots \times \S_{ d}
\end{align} where each $ \S_{ i}$ is a symmetric non-negative    measure on $ \hat \e$  satisfying  \eqref{eq:integr-SF-general} and \eqref{eq:wiener}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary two-lobe of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Assume that $Q$ is continuous and strictly increasing on $
[0,1]$. Assume that $H_{F}$ has exactly one zero 
\begin{equation}
0<\xi <\frac{1}{2}  
\end{equation}
on $(0,\tfrac{1}{2})$. If 
\begin{equation}
\left\vert \int_{0}^{\xi }W_{F}(u)H_{F}(u)\,du\right\vert \geq \left\vert
\int_{\xi }^{1/2}W_{F}(u)H_{F}(u)\,du\right\vert ,  
\end{equation}
then $D_{0}$ has a constant sign on $[0,1]$.

A simpler sufficient condition is 
\begin{equation}
\int_{0}^{\xi }|H_{F}(u)|\,du\geq \int_{\xi }^{1/2}|H_{F}(u)|\,du,

\end{equation}
because $W_{F}$ is nonincreasing on $[0,\tfrac{1}{2}]$.

[Theorem 6 (Supermartingale decomposition) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Under Assumption $(L)$-a.e.,	let $(f_j)_{j\ge 0}$ be a sequence of
	non-anticipative real-valued functions. Then, the following assertions are equivalent:
	\begin{itemize}
		\item [(i)] $(f_j)_{j\ge 0}$ is a supermartingale.
		\vspace{.05in}
		\item [(ii)] For every sequence $(\delta_j)_{j\ge 0 }$ of positive real numbers there are sequences $(H_j)_{j\ge 0}$ and $(A_j)_{j\ge 0}$, of non-anticipative real-valued functions defined on 
		$\mathcal{S}$, such that $(A_j)_{j\ge 0}$ is nondecreasing, $A_0 = 0$, and
		\begin{equation} 
		f_i(S)=f_0+\sum_{j=0}^{i-1}H_j(S)\Delta_jS-A_i(S)+\sum_{j=0}^{i-1}\delta_j,
		\end{equation}
		for every $S \in \Se \setminus N_f$ and $i\ge 0$. Here $N_f$ is an $\overline{I}$-null set independent of  $(\delta_j)_{j\ge 0 }$.
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thrm 23 of arXiv:2608.31054, 'Revisiting Picard's proof of the Picard--Weber--Weck selection theorem'] Let $\Omega :=(0,1)^d$ and $  u\in H_0(\Rot;\Omega)\cap H(\div;\Omega)$. Then, there holds $  u\in H^1(\Omega)^d$ and
    \begin{align}
        \|\Grad   u\|_{L^2(\Omega)^{d\times d}}^2 = \|\Rotcirc   u\|_{L^2(\Omega)^{d\times d}}^2 + \|\div\,   u\|_{L^2(\Omega)}^2.
    \end{align}

