[Lemma 20 (Slope-measure representation) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] Let $u$ be a nonconstant increasing concave function on $[0,\overline x]$ with
$0<u'_+(0)<\infty$. There is a unique probability measure $\Pi_u$ on
$(0,\overline x]$ such that
\begin{equation}

u(x)=u(0)+u'_+(0)
\int_{(0,\overline x]}\min\{x,t\}\,\Pi_u(dt).
\end{equation}
For $x\in(0,\overline x]$,
\begin{equation}

\Pi_u([x,\overline x])=
\frac{u'_-(x)}{u'_+(0)}.
\end{equation}

[Defn ising of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] For a weighted graph $G=(\text{\boldmath $A$},\text{\boldmath $h$})$ on $[N]$, the \emph{Ising
    model} is the probability measure $\mu_G$ on $\{-1,1\}^N$
    assigning a mass of

    \begin{align}
    \mu_G(\text{\boldmath $\sigma$})=\frac1{Z(G)} \exp\left( \frac12\<\text{\boldmath $\sigma$},
    \text{\boldmath $A$}\text{\boldmath $\sigma$}\> + \<\text{\boldmath $h$}, \text{\boldmath $\sigma$}\> \right)
\end{align}

    to spin configurations $\text{\boldmath $\sigma$}\in\{-1,1\}^N$. Here,

    \begin{align}
    Z(G) = \sum_{\text{\boldmath $\sigma$}\in\{-1,1\}^N} \exp\left( \frac12\<\text{\boldmath $\sigma$},
    \text{\boldmath $A$}\text{\boldmath $\sigma$}\> + \<\text{\boldmath $h$}, \text{\boldmath $\sigma$}\>
    \right)
    \end{align}

    is the \emph{partition function} of the model. We furthermore
    define the \emph{normalized free energy} or \emph{free energy
    density} of the model as

    \begin{align*}
F(G) = \frac1N \log Z(G).
\end{align*}

[Lemma 8 of arXiv:2608.26501, 'Explicit Bounds on the Entropy of Piecewise H\"{o}lder Graphon Models'] Let $X\subset\rr^s$ be a $s$-cube of side length $\ell$. Divide $X$ into $m^s$ disjoint $s$-cubes of side length $\ell/m$, which we refer to as cells. If $A\subset X$ is a relative polytope, let $N$ be the number of cells which intersect the boundary of $A$. Then 
\begin{equation}
 N\leq 2s m^{s-1}
\end{equation}

[Lemma 3 of arXiv:2506.16484, 'Stochastic Heat Flow is a Black Noise'] The set 
\begin{align}
\begin{split}
    S = \Big\{ 
        h(Z_{s_1,t_1} &g_1\otimes g'_1, \ldots, Z_{s_N,t_N} g_N\otimes g'_N)
        \,:\,
        N\geq 1, h\in C_c^\infty(\R^N), 
\\
    &
        s_i<t_i \in\R, \ g_i,g'_i\in C_c(\R^2) 
        \text{ for all }i=1,\ldots,N
    \Big\}
\end{split}
\end{align}
is dense in $L^2(\Omega)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop_selfSimRiemann of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let $\kappa\in\mathbb{R}$, let $(X_H(\eta))_{\eta\in\mathcal{M}_\kappa}$ be the fractional L\'evy field on the model space $\mathcal{M}_\kappa$ and let $0<r< \inj_{\mathcal{M}_\kappa}(O)$. For any $a>0$ we have
    \begin{align*}
        \prob{\sup_{\eta\in\mathcal{B}^{\mathcal{M}_\kappa}_r(O)} X_H(\eta) < \varepsilon} = \prob{\sup_{\eta\in\mathcal{B}^{\mathcal{M}_{\kappa/a^2}}_{a r}(O)} \widehat{X}_H(\eta) < \varepsilon ~ a^{H}},
    \end{align*}
    where $(\widehat{X}_H(\eta))_{\eta\in\mathcal{M}_{\kappa/a^2}}$ is the fractional L\'evy field indexed by $\mathcal{M}_{\kappa/a^2}$.

