[Lemma 12 (Single-target order criterion) of arXiv:2608.16701, 'Order-Sensitive Fast-Synapse Limits in Sparse Excitatory--Inhibitory Threshold--Reset Netw'] The excitatory-first and inhibitory-first families produce different firing
counts on $[0,4\varepsilon]$ if and only if
\begin{equation}
 \boxed{x+a-b<\theta\le x+a.}

\end{equation}
In that case the excitatory-first target fires once and the
inhibitory-first target does not fire.

[Proposition 5 ({\cite[Lemma 3.11) of arXiv:2607.18104, '2607.18104'] {GZ:fractal}}]
There exist constants $c,C>0$, such that for all  $\phi>0$,
\begin{align*}
&\P\Bigg(\TF_{s+\theta^{-1}}(\pi) \geq \phi \theta^{-2/3}\log^{3}\big(1+\theta\lVert (x,s;y,t)\rVert_2\big),\,\,\,\forall(x,s;y,t)\in \R^{4}_{\uparrow},\pi\in \mathfrak{G}_{(x,s),(y,t)}, \theta\geq 2(t-s)^{-1}\Bigg)\\
&\leq C\exp\big({-c \phi^{9/4}}\big). 
\end{align*} By symmetry, the result holds with $s+\theta^{-1}$ replace by  $t-\theta^{-1}$. Hence,  
\begin{equation}
\begin{split}

&\P\Bigg(\TF(\pi) \geq \phi  |t-s|^{2/3}\log^{3}\bigg(1+\frac{\lVert (x,s;y,t)\rVert_2}{|t-s|}\bigg),\,\,\,\forall (x,s;y,t) \in \R^{4}_{\uparrow},\pi\in \mathfrak{G}_{(x,s),(y,t)}\Bigg)  \\
&\leq C\exp({-c \phi^{9/4}}).   
\end{split}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm see \cite{KM21} thm (\textcolor{red}{2.5}) of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Under the neutrality condition $\left(\mathrm{NC}_b\right)$, the value of the differential $C_{\mathbb{D}}\left[\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right]$ in the identity chart of $\mathbb{D}$ is given by
\begin{equation}
C_{\mathbb{D}}\left[\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right]=\prod_{j<k}\left(z_j-z_k\right)^{\sigma_j^{+} \sigma_k^{+}}\left(\bar{z}_j-\bar{z}_k\right)^{\sigma_j^{-} \sigma_k^{-}} \prod_{j, k}\left(1-z_j \bar{z}_k\right)^{\sigma_j^{+} \sigma_k^{-}},
\end{equation}
where the product is taken over finite $z_j$ and $z_k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 19 ({\cite{QAlg05}*{\S~3.2 Corollary 5.4}}) of arXiv:2609.03836, 'Koszul Orlik--Solomon Algebras from Non-supersolvable Arrangements'] \label[Thm]{thm:regularity_Koszul}
    Suppose $R$ and $S$ are  standard graded $\mathbb{K}$-algebras and we are given a surjective graded $\mathbb{K}$-algebra homomorphism $R \twoheadrightarrow S$. Assume that $S$ has a linear free resolution as a left $R$-module.
    Then $R$ is Koszul if and only if $S$ is Koszul. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] Retain the setting of Theorem \ref{thm:compact-manifold}. When $\mu = \nu$, it holds that
    \begin{align}
        \lim\limits_{T \to +\infty} \exp(\lambda_1 T)(H(Q^{T}|P^{T})+H(P^{T}|Q^{T})) &= \sum_{i \in \mathcal{I}_{1}}p_i^2,
    \end{align}
    where $p_i = \langle \rho, \psi_i \rangle_{L^2(\diffref)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 23 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] The number $\theta_{k}^{t}$ is determined by the
relation that 
\begin{equation}
\int_{0}^{\theta_{k}^{t}}\sin^{d-2}udu=\frac{\omega_{d-1}}{\omega_{d-2}}\times\frac{\int_{0}^{r}\sinh^{d-1}(\alpha(t)\rho)d\rho}{\int_{(k-1)r}^{kr}\sinh^{d-1}(\alpha(t)\rho)d\rho}.
\end{equation}
It admits the following estimate: 
\begin{equation}
C_{1,d}\times\frac{\sinh(\alpha(t)r/2)}{\sinh(k\alpha(t)r)}\leqslant\theta_{k}^{t}\leqslant C_{2,d}\times\frac{\sinh(\alpha(t)r)}{\sinh((k-1)\alpha(t)r)}\ \ \ \forall k,t.
\end{equation}
In addition, the total number $N_{r}^{t}$ of subdomains $P_{k}^{t}(i)$
are estimated as 
\begin{equation}
N_{r}^{t}\leqslant C_{3,d}\times\frac{\tilde{R}(t)}{r}\times\big(\frac{\sinh(\tilde{R}(t)\alpha(t))}{\sinh(\alpha(t)r/2)}\big)^{d-1}.
\end{equation}
Here $C_{i,d}$ ($i=1,2,3$) are universal constants that depend only
on $d.$

