[Proposition eq:AO-log-derivative of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:aggregate-product-mixture}
Under (equation eq:array-assumptions of the paper), uniformly in \(t\in[0,1]\) and
\(O\in\mathcal O_{N,L}\),
\begin{equation}
 \left\lvertA_O'(t)\right\rvert\le CNq_N^{m-1}A_O(t).
\end{equation}

[Lemma continuous-to-discrete of arXiv:2606.25135, 'Convergence Rates for Semistochastic Processes'] Let $\pi$ denote the stationary distribution for a continuous-time Markov process $\{X_t\}$  with Markov semigroup \, $\mathcal{U}^t$ and let $\Delta t > 0$ be a fixed time increment.  
If we set 
\begin{equation}  
Q= \mathcal{U}^{\Delta t} \ , 
\end{equation}
then for any initial distribution $\mu_0$ of~$X_0$, 
\begin{equation*}
d_{\mathrm{TV}}\left( \mu_0 \, \mathcal{U}^t  ,  \pi \right)   \leq  d_{\mathrm{TV}}\left( \mu_0 \, Q^n  , \pi \right) \ ,
\end{equation*}
where $n=\lfloor t / \Delta t \rfloor$ is the greatest integer less than or equal to $t / \Delta t$\ .

[Theorem of arXiv:2411.16651, 'On a problem of optimal mixing'] Let $X$, $Y$ be Polish spaces, let $\mu_1,\dots,\mu_n$ and $
u$ be atomless probability measures on the corresponding spaces, and let $c:X	imes Y 	o [0,\infty)$ be lower semi-continuous function, then
		$$ \inf\limits_{\pi\in	\Pi(\overrightarrow{\mu},{
u})} K_c(\pi):= \int\limits_{X	imes Y}c(x,y)\; d\pi = \sup\limits_{(\overrightarrow\phi,\psi)\in J(\overrightarrow{\mu},{
u})} \int_X\phi(x) d{\mu} +  \int_Y\psi(y) d{
u}, $$
		where 
		$$ J(\overrightarrow{\mu},{
u}) = \{\phi\in C(X), \overrightarrow\psi\in C^n(Y): \phi(x)+  rac{d\overrightarrow\mu}{d\mu}\cdot\overrightarrow\psi(y)\leq c(x,y) \}, \quad \psi(y):= \sum_i \psi_i(y).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2604.18427, 'Expected perimeter and area of the convex hull of planar Brownian motion stopped upon exit'] Define the almost surely unique random time at which the maximum horizontal displacement $M$ is attained by
\begin{equation}
    T = \argmax_{0 \le t \le \tau_\bbD} X_t.
\end{equation}
We show that
\begin{equation}
    \bbE[M^2 - Y_T^2] = 1 - \log 2 + \int_{\pi}^{2\pi} \frac{\cos u}{u} \D u \approx 0.210624.
\end{equation}
Consequently, the expected area of the convex hull of $\bfW$ when it first exits $\bbD$ is
	\begin{equation}
		\bbE[\sfA_{\tau_{\bbD}}] = \pi \,\bbE[M^2 - Y_T^2] \approx 0.661695.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 1. dfn: resistance forms associated with electrical networks of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{Resistance forms associated with electrical networks}]  

  Let $G$ be an electrical network.
  For functions $f,g: V_{G} \to \mathbb{R}$,
  we set 
  \begin{equation}
    \mathcal{E}_{G}(f, g) 
    \coloneqq 
    \frac{1}{2} 
    \sum_{x, y \in V_{G}} 
    \mu_{G}(x,y) (f(x) - f(y)) (g(x) - g(y))
  \end{equation}
  (if the right-hand side is well-defined).
  We then set $ \mathcal{F}_{G} \coloneqq \{ f \in \mathbb{R}^{V_{G}} \mid \mathcal{E}(f, f) < \infty \}$
  and, for each $x, y \in F$,
  \begin{equation}
    R_{G}(x,y) 
    \coloneqq 
    \sup 
    \{
      \mathcal{E}(f, f)^{-1} \mid f \in \mathcal{F},\, f(x)=1,\, f(y) = 0
    \},
  \end{equation}
  where we define $\sup \emptyset \coloneqq 0$.

[Lemma 24 of arXiv:2608.06523, 'On the Gardner Transition in the Ising Pure $p$-Spin Glass II'] The following inequalities hold on the full closed intervals:
\begin{align}
 &\frac{\mathcal J_{-m}(\tau)-\mathcal J_{2-m}(\tau)}
 {\tau\mathcal J_{4-m}(\tau)}<2,
 &&\tau=\frac{8/5-61m/200}{m^2},
 &&\frac{10}{13}\leq m\leq1,\\
 &\frac{\mathcal J_{-m}(\tau)-\mathcal J_{2-m}(\tau)}
 {\tau\mathcal J_{4-m}(\tau)}<2,
 &&\tau=\frac{9/5-101m/200}{m^2},
 &&\frac{1080}{1903}\leq m\leq\frac{10}{13}.

\end{align}

