[Lemma 1 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] \cite[Lemma 6.4.1]{Maostochatic}
		Let $p>1$, $\varepsilon>0$,  and $a,b\in\mathbb{R}$. Then
		\begin{equation}
			|a+b|^p\leq \left(1+\varepsilon^{\frac{1}{p-1}}\right)^{p-1}\left(|a|^p+\frac{|b|^p}{\varepsilon}\right).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\tau_t K^{\varepsilon}(x) = \varepsilon^{-1/2}g\left(\frac{t-x}{\varepsilon}\right)\) where \(g(s) = e^{-s}\int_0^se^vv^{H-3/2}dv\) be the kernel of the fastened fractional OU process for \(H>1/2\). Then as \(\varepsilon\to 0\) we have 
that \begin{itemize}
    \item If \(s<t\) then as \(\varepsilon\to 0\):
    \begin{equation}
    \int_{-\infty}^{t\wedge s}\tau_tK^{\varepsilon}(x)(s-x)^{H-3/2}dx \sim \varepsilon^{1-H}(t-s)^{2H-2}\beta(H-1/2,2-2H)
    \end{equation}
    \item If \(s>t\) then as \(\varepsilon\to 0\) we have the following decomposition \begin{equation}
\int_{-\infty}^{t\wedge s}\tau_tK^{\varepsilon}(x)(s-x)^{H-3/2}dx = A_t^{<} + A_t^{\varepsilon}
    \end{equation}
    where the first term behaves as \begin{equation}
A_t^{<} \sim \varepsilon^{1-H}(s-t)^{2H-2}\beta(H-1/2,2-2H)
    \end{equation}
and the second term is controlled by
\begin{equation}
A_t^{\varepsilon} \lesssim \varepsilon^{1/2}(s-t)^{H-3/2} 
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 75 of arXiv:2607.18104, '2607.18104'] There exist constants $C_3,c_3>0$ such that for all $N$ large enough 
\begin{equation}
\P\big(B^{\rho}_{\delta,N} \, \big| \, A^{\rho}_{\delta,N} \big) \geq 1- C_3\exp(-c_3 N^{1/5}) . 
\end{equation}

