[Proposition p:asymptotic variance test function of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] In the setting of Theorem~(t:asymptotic variance test function of the paper), assume $p>-d$. Also assume that either $d=1$, $f$ is isotropic, or $\Phi$ is isotropic. If further $\varepsilon^{-(d+p)}\hat\beta_\Phi(B_\varepsilon)$ converges as $\varepsilon\to0$, and $x\mapsto x_jf(x)$ is Fourier-smooth with exponent $p+2+\vartheta$ for every $j\in\{1,...,d\}$, then
\begin{equation}
    \frac{\BV[\Phi(f_r)]}{r^{d-p}} \xrightarrow{r\to\infty}\frac{d+p}{d\kappa_d(2\pi)^d} \int|\hat{f}(k)|^2\|k\|^p\,dk\lim_{\varepsilon\to0}\frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^{d+p}} .
\end{equation}

\begin{remark}
    These additional conditions from Proposition~(p:asymptotic variance test function of the paper) reduce to $p>-d$ if $f$ is assumed to be an isotropic Schwartz function. Further, the case $p=-d$ can be treated with the \linebreak $L^2$-ergodic theorem as in Proposition~(p:pseudo ergodic of the paper). Also note that if $p\in 2\N_0$ (or $p\in 4\N_0$ for the second equality), then
    \begin{equation}
        \frac{1}{(2\pi)^d}\int|\hat{f}(k)|^2\|k\|^p\,dk = \big\|f^{\big(\tfrac{p}{2}\big)}\big\|_2^2 = \big\| \Delta^{\tfrac{p}{4}}f\big\|_2^2,
    \end{equation}
    where $\Delta$ is the Laplace operator.
\end{remark}

\begin{proof}[Proof of Proposition~(p:asymptotic variance test function of the paper)] 
    Assume that $p>-d$ and that $\varepsilon^{-(d+p)}\hat\beta_\Phi(B_\varepsilon)$ converges as $\varepsilon\to0$. Then, similarly to~(equation e:linear statistic bound 1 of the paper), we can show
    \begin{equation*}
        \frac{\BV[\Phi(f_r)]}{r^{d-p}} = (2\pi)^{-d}r^{d+p} \int_{B_1} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) + o(1)
    \end{equation*}
    as $r\to\infty$. Now we define $g:[0,\infty)\to[0,\infty)$ and the measure $\mu$ on $[0,\infty)$ by
    \begin{align*}
        g(s)&:= \int_{\partial B_1} |\hat{f}(sk)|^2\,\sigma_d(dk), \quad s\in[0,\infty),\\
        \mu(B)&:= \hat\beta_\Phi\big(\{x\in\R^d:\|x\|\in B\}\big),\quad B\in\cB([0,\infty)),
    \end{align*}
    where $\sigma_d$ is the unique rotation invariant probability measure on $\partial B_1$. Since we assume that $x\mapsto x_jf(x)$ is Fourier-smooth with exponent $p+2+\vartheta$ for each $j\in\{1,...,d\}$, we can conclude that $g\in C^1$, and we do not only obtain that there is a $c_4>0$ such that $g(s)\leq c_4 (1+|s|)^{-(d+p+\vartheta)}$ but also such that $g'(s)\leq c_4 (1+|s|)^{-(d+p+1+\vartheta)}$. If we assume that either $f$ or $\Phi$ is isotropic, then $\hat{f}$ or $\hat\beta_\Phi$ is isotropic and
    \begin{align*}
        (2\pi)^{-d}r^{d+p} \int_{B_1} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) &= (2\pi)^{-d}r^{d+p} \int_0^1 g(rs) \, \mu(ds)\\
        &= (2\pi)^{-d}r^{d+p} \bigg(\mu([0,1))g(r)- \int_0^1 rg'(rs) \mu(B_s)\, ds\bigg)\\
        &= (2\pi)^{-d}\mu([0,1))r^{d+p}g(r)- (2\pi)^{-d}\int_0^r g'(s) s^{d+p}\frac{\mu(B_{\frac{s}{r}})}{(\frac{s}{r})^{d+p}}\, ds,
    \end{align*}
    where we used partial integration and that $\mu(\{0\})=0$ by Proposition~(p:pseudo ergodic of the paper).
    \begin{align*}
        (2\pi)^{-d}r^{d+p} \int_{B_1} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) &= (2\pi)^{-d}r^{d+p} \bigg(\mu([0,1))g(r)- \int_0^1 rg'(rs) \mu(B_s)\, ds\bigg)\\
        &\xrightarrow{r\to\infty} -(2\pi)^{-d}\int_0^\infty g'(s)s^{d+p}\, ds \lim_{\varepsilon\to0}\frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^{d+p}}\\
        &= \frac{d+p}{(2\pi)^d} \int_0^\infty g(s) s^{d+p-1}\, ds \lim_{\varepsilon\to0}\frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^{d+p}}\\
        &= \frac{d+p}{d\kappa_d(2\pi)^d} \int_0^\infty |\hat{f}(k)|^2 \|k\|^p\, ds \lim_{\varepsilon\to0}\frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^{d+p}},
    \end{align*}
    where we applied the theorem of dominated convergence and partial integration. Hence, all assertions have been shown.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm l:edge-resampling of arXiv:2607.18194, 'Temperature chaos in directed polymers'] The following holds for all sufficiently small $\varepsilon>0$ and all $n\geqslant 1$.
    Fix $k\in\{0,M\}$.
    For coupled white noises $(\xi,\eta_k)$ as defined below (equation e:def-boxes-Bk of the paper),
    it holds $\mathbb{P}_\mathrm{re}$-a.s. that
    \begin{align*}
        \left|
            \mathcal{H}^{\xi,(n)}_{{\,\mathrm{TF}_k}}
            -\mathcal{H}^{\eta_k,(n)}_{{\,\mathrm{TF}_k}}
        \right|\1_{\xi,\eta_k\in \mathsf{Good}_{\varepsilon,n}}
        \leqslant 
        2 \varepsilon^{\gamma/3} n^{1/3} \log^{4}(1/\varepsilon),
    \end{align*}
    where $\mathsf{Good}_{\varepsilon,n}$ was defined in (equation e:def-Good-event of the paper).
    In fact, of the four events in (equation e:def-Good-event of the paper), only $\mathsf{EnergyConc}_{\varepsilon,n}$ is relevant for the above bound.

