[Theorem thm:cltsmooth of arXiv:2411.08848, 'Stationary random measures: Covariance asymptotics, variance bounds and central limit theo'] (CLT for Sobolev statistics)

Let ${\mathcal X}$ be a simple stationary point process on $\mathbb{R}^d$ with truncated correlations satisfying Assumption (asmpt:integrationofrhokT of the paper).  Assume that for all $m \geq 2$, there exists $d_m \geq m$ such that for all $l_1,\ldots,l_{m-1} \in \mathbb{Z}_+$ with $\sum_i l_i \leq d_m$,

\begin{align}
    \int_{(\mathbb{R}^d)^{m-1}}  \prod\limits_{i=1}^{m-1} |z_{i}|^{l_i}\; |\kappa_{m-1}|(z_1,\ldots ,z_{m-1}) \, \mathrm{d} z_1\ldots \mathrm{d} z_{m-1} < \infty,
\end{align} 

and further that for all non-zero $\alpha^{(j)} \in \mathbb{Z}_+^d$, $1\le j\le m$, satisfying $\sum_{j=1}^m |\alpha^{(j)}| < d_m$, it holds that 

\begin{align}

 I_m(\tau; \alpha^{(1)},\ldots ,\alpha^{(m)}) = 0, \, \, \forall \tau : [m] \to [m-1].   
\end{align}

Let $f \in L^1(\mathbb{R}^d)\cap H^k$  for some $k\ge 1$ (with the convention that $H^0=L^2(\mathbb{R}^d)$). Let $\lambda_D + I(0) = 0$ and $I(\alpha)= 0$ for  $1\le |\alpha|< 2k$. If $2(d-d_m)< m(d-2k)$ for $m$ large, then 

\[
\frac{{\mathcal X}_L(f)-\mathbb {E} [{\mathcal X}_L(f)]}{L^{(d-2k)/2}}\stackrel{d}{\longrightarrow} N(0,Q_{2k}^{\kappa}(f,f))
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:neg_terme_biais of arXiv:2605.30999, 'Functional central limit theorems for $U$-statistics of $\beta$-mixing data'] Let $h\colon S^m\to\mathbb R$ be a canonical kernel. Suppose that $\sum_{k=1}^{+\infty} k\beta\left(k\right)$ is finite. 
Suppose that $\ens{h\pr{X_{\bm{i}}}^2,\bm{i}\in\operatorname{Inc}^m}$ is uniformly integrable.

Then 
\begin{equation}
    \lim_{n\to +\infty}\frac 1{n^{m-1/2  }}\sum_{\bm{i}\in\operatorname{Inc}^m_n}
    \abs{\E{h\pr{X_{\bm{i}}}}}=0.
\end{equation}
Let $\alpha\in\left(0,1/2\right)$. Suppose that 
\begin{equation*}
    \sup_{t>0}\sup_{\bm{i}\in\operatorname{Inc}^m}t^{p\left(\alpha\right)}
    \mathbb P\pr{\abs{h\pr{X_{\bm{i}}}}>t }<+\infty,
\end{equation*}
where $p\left(\alpha\right)=\left(1/2-\alpha\right)^{-1}$. Then
\begin{equation}
    \lim_{n\to +\infty}\frac 1{n^{m-1/2-\alpha }}\sum_{\bm{i}\in\operatorname{Inc}^m_n}
    \abs{\E{h\pr{X_{\bm{i}}}}}=0.
\end{equation}

