[Lemma 44 (Identities for $\gtorus$-gradients) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following identity holds for scalar functions $\phi$ and $\psi$: 
	\begin{align}
		\gtorus^{-1}(\angrmD \phi, \angrmD \psi) & = \Speed^2 \sum_{A=2,3} (\Yvf{A} \phi) \Yvf{A} \psi + \frac{\Speed^2}{(X^1)^2} (X^A \Yvf{A} \phi) X^B \Yvf{B} \psi. 
	\end{align}

[Theorem 3 of arXiv:2608.13631, 'The classical discrete laws near the mode:\\ complete local expansions for the negative bi'] Under the hypotheses of Theorem~\ref{thm:nb-main},
	\begin{equation}
	\begin{gathered}
		\log\Bigl[\sqrt{2\pi\,\frac{k(k+r)}{r}}\;P(k)\Bigr]
		\sim\sum_{n\ge1}\frac{\widehat A_n(t;p)}{r^{n}},\\
		\widehat A_n=\frac{(-1)^{n+1}}{n(n+1)}
		\Bigl[-B_{n+1}-\Bigl(\Bigl(\frac pq\Bigr)^{n}-p^{n}\Bigr)\Bh_{n+1}(t)\Bigr],
	\end{gathered}
	\end{equation}
	with $k=\mu+t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 21 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] \label[proposition]{thm:hard-full}
We have
\begin{equation}
\E\big[ u_x(t,X_t)^2\big] \le t \qquad \forall t\in[q,1].
\end{equation}

[Theorem thm:local_clt of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:sigmadef_local_intro of the paper), set
\begin{equation}

    \varsigma_n^2 = \mleft( 1 - p(1-p) \sum_{j=1}^K \beta_j p^{\mathsf{e}_j-2} \sum_{\rho \in \mathcal{V}_j} \mathsf{d}_\rho (\mathsf{d}_\rho-1) \mright)^{-1} \times p (1-p) (n-1).
\end{equation}
Then for any deterministic vertex $v \in [n]$ and any $\varepsilon > 0$, if $X$ is distributed as (equation eq:tilt of the paper)
with $Y \sim \mathcal{G}(n,p)$ and $\mathsf{g}$ given in (equation eq:smallgdef of the paper), under the ``phase-uniqueness or forest'' assumption, we have
\begin{equation}
    \mathbf{d} \mleft( \frac{\mathsf{deg}_v(X) - \mathbb{E}[\mathsf{deg}_v(X)]}{\varsigma_n}, Z \mright) \lesssim n^{-\frac{1}{4}+\varepsilon},
\end{equation}
for both $\mathbf{d} = \mathbf{d}_\mathrm{Was}$ and $\mathbf{d} = \mathbf{d}_\mathrm{Kol}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

