[Definition 5 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(f\colon\mcalY\to\mcalX\) be a morphism of stacks. By \citeSta{06NW}, the induced functor between the inherited fpqc sites gives a morphism of topoi. Moreover, the canonical morphism \(f^{-1}\mcalO_{\mcalX}\to\mcalO_{\mcalY}\) is an equivalence: on every object \(T\to\mcalY\), both sides are the ring \(\Gamma(T,\mcalO_T)\). We therefore obtain a morphism of ringed fpqc topoi. We denote the resulting derived adjunction by
  \begin{equation*}
    Lf_{\mathrm{sh}}^*\colon\mcalD(\mcalX_{\fpqc},\mcalO_{\mcalX})\rightleftarrows\mcalD(\mcalY_{\fpqc},\mcalO_{\mcalY})\colon Rf_*^{\mathrm{sh}};
  \end{equation*}
  see \citeSta{07A6}. Thus
  \begin{equation*}
    Lf_{\mathrm{sh}}^*(\mathord{-})\defeq\mcalO_{\mcalY}\otimes_{f^{-1}\mcalO_{\mcalX}}^Lf^{-1}(\mathord{-}).
  \end{equation*}
  We call \(Lf_{\mathrm{sh}}^*\) the \emph{site-theoretic derived pullback} and \(Rf_*^{\mathrm{sh}}\) the \emph{site-theoretic derived pushforward}.

[Lemma 221 (Estimates for the error integrals generated by the multiplier vectorfield) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Assume that $1 \leq N \leq \Ntop$,
$v \in \velocityarray = \{v^1,v^2,v^3\}$.
Let $\tander^N \in \mathfrak{P}^{(N)}$, where $\mathfrak{P}^{(N)}$
is the set of order $N$ $\nullhyparg{u}$-tangential commutator operators from
Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}. Let $\blowuprateofwaveWRTnumberofcommutations(N)$ denote the blowup rate of the wave variables defined in \eqref{E:BLOWUPRATEOFWAVEWRTNUMBEROFCOMMUTATORS}. Let $\varsigma_0$ be the constant featured in Lemma\,\ref{L:PRELIMINARYBELOWTOPORDERL2ESTIMATESFOREIKONALFUINCTIONQUANTITIES} (see also Remark\,\ref{R:SMALLNESSCONSTANTFORBELOWTOPORDERACOUSTICVARIABLES}).
Recall that the multiplier vectorfield $\multipliervectorfield$ is defined in \eqref{E:MULTIPLIERVECTORFIELD}
and that ${^{(\multipliervectorfield)}\mathfrak{B}}[\tander^N v]$ 
is the error term defined by 
\eqref{E:WAVEENERGYIDENTITYBULKERRORTERM} and \eqref{E:WAVEENERGYIDENTITYBULKERRORTERM1}--\eqref{E:WAVEENERGYIDENTITYBULKERRORTERM6}
and appearing on RHS\,\eqref{E:ENERGYNULLFLUXINTEGRALIDENTITIESWAVE}.
Then if $\varsigma_1 \in (0,1]$ is sufficiently small, the following estimates hold for 
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$, 
where the implicit constants are \textbf{independent} of $\varsigma_0,\varsigma_1$:
\begin{align}
	\begin{split} 
		\int_{\characteristicdiamondtwoarg{[\leftubar,\ubar]}{[\moreinterestingu_1,u]}} 	
			\left|
				{^{(\multipliervectorfield)}\mathfrak{B}}[\tander^N v] 
			\right| \weight^{\blowuprateofwaveWRTnumberofcommutations(N)} 
		\ReciprocalLunitAppliedtoTimeFunction \, \voldiamond & \lesssim (1 + \varsigma_1^{-1}) \int_{\ubar' = \leftubar}^{\ubar} \frac{1}{|\ubar'|^{1/2}} \totalfluxcontrolvelocity_{[1,N]}(\ubar',u) \, \mathrm{d} \ubar' \\
		& \ \  +  (1  +  \varsigma_1^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N]}(\ubar,u') \, \mathrm{d} u' \\
		& \ \ + \varsigma_1 \strongangularcontrolvelocity_{[1,N]}(\ubar,u).
	\end{split}
\end{align}

[Theorem cor:sources break detailed balance of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$ is a mass action chemical system with sources and sinks.  Let $\mathcal W_r $ be the set of the cycles associated with $(\Omega, \mathcal R , \emptyset ,  \mathcal K, \emptyset )$ and  $ \mathcal W$  the set of the cycles associated with $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$. 
  \begin {enumerate} 
 \item  Assume that
\begin{equation} 
\log \left( \frac{\alpha_k }{\beta_k }\right) =E(k), \quad \forall k \in \Omega_c^{\mathcal W} 
\end{equation}
where $E \in \mathbb R^M $ is the  solution to 
 \begin{equation} 
 S_\rho^T  E = \ln \left( \dfrac{ K_{ - \rho} }{ K_{  \rho } }  \right)  \ \forall \rho \in \{ 1, \dots, r \}
\end{equation} 
and where 
\begin{equation}
    \Omega_c^{\mathcal W }:= \{ k \in \Omega : \exists w \in \mathcal W  \quad (\mathbb S_r  \pi_R w ) ( k ) \neq 0   \}. 
\end{equation}
Then the chemical system  $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$ satisfies the property of detailed balance. 
 \item    Assume that the chemical system $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$ satisfies the detailed balance condition and 
 \begin{equation} 
 |\mathcal W| >  |\mathcal W_r |. 
 \end{equation}
Then either \begin{enumerate}
\item the chemical rates in the set $ \mathcal K_s =\{ \alpha_k , \beta_k \}_{ k \in  \Omega_c} $ satisfy (equation eq for the parameters of the paper)  
\item or the property of detailed balance is unstable, i.e. for every $\delta >0$ there exists a set $ \mathcal K^\delta =\{ K_\rho^\delta , K_{- \rho}^\delta \}_{\rho=1}^r $ such that 
\[ 
\max_{ k \in \Omega } \left( |K_\rho - K_\rho^\delta | +  | K_{-\rho} - K_{-\rho}^\delta | \right)  \leq \delta
\]
and such that the chemical system  $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K^\delta, \mathcal K_s )$ does not satisfy the detailed balance property. 
\end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def:nonlinear-m-s-stability of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] The point $x^\ast\in \mathbb R^d$ is said to be nonlinearly mean-square stable for the system (equation eq:main_d of the paper) if it is linearly mean-square  stable and 
    $$\lim_{t\to\infty} \mathbb{E}\left[\|Z(t)\|^2\right]=0,$$
    where $Z$ is the stochastic process defined pathwise by 
    \begin{equation}

    Z(t):=Y(t)-{\widetilde{Y}}(t),\quad t\geq 0.    
   \end{equation}

[Lemma 9 (\textsf{Quenched switching at the first meeting}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] Fix $\al\in\R$, $\be>0$, and $x,y\in\R$ with $x\neq y$.  Almost
  surely with respect to the Brownian environment,
  \begin{align}
      \int_{\DN^2}    \sum_{i=0}^{n-1}    \mathfrak D_i^{y,x}(\eta,\ga)\,   Q_y^{\al,\be}(d\eta)Q_x^{\al,\be}(d\ga)
  =   \sgn(y-x)   \bigl(Q_y^{\al,\be}\otimes Q_x^{\al,\be}\bigr)   \{\tau\leq n-1\},
  \end{align}
  and
  \begin{align}
      \int_{\DN^2}  \sgn\bigl(P_n(y,\eta)-P_n(x,\ga)\bigr)\,  Q_y^{\al,\be}(d\eta)Q_x^{\al,\be}(d\ga)
=   \sgn(y-x)        \bigl(Q_y^{\al,\be}\otimes Q_x^{\al,\be}\bigr)   \{\tau=\infty\}.
  \end{align}
  Consequently,
  \begin{align}
      \int_{\DN^2}
      \left[
        \sum_{i=0}^{n-1}\mathfrak D_i^{y,x}(\eta,\ga)
        +\sgn\bigl(P_n(y,\eta)-P_n(x,\ga)\bigr)
      \right]
      Q_y^{\al,\be}(d\eta)Q_x^{\al,\be}(d\ga) =\sgn(y-x).
   \end{align}

