[Theorem th:mainresulthyper of arXiv:2510.00748, '\bf On irreducible central limit theorems'] Fix $d\geq 2$ and let $\{Z_n\}$ be a sequence of homogeneous sum as in (equation eq:defpolchaos of the paper). Let ${\ensuremath{\mathcal G}} _n=(V_n,{\ensuremath{\mathcal E}} _n,w_n)$, $n\geq 1$, be the sequence of weighted hypergraphs associated to $\{Z_n\}$ via (equation e:can1 of the paper)--(equation e:can2 of the paper). If there exists $k \ge 2$ such that, as $n\to\infty$,
    \begin{equation}

        \liminf_{n} \mu_k^{(n)} > 0\,,
    \end{equation}
then $\{Z_n\}$ is irreducible in the sense of Definition (def:irreducibility of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] The following almost sure convergence results hold true:\\
\noindent{(i)} For $0\le p< (4a-1)/4a$, we have
\begin{equation*}
	\lim_{n\to\infty}\frac{G_n}{n}=0\ \ \text{a.s.},
\end{equation*}
\noindent{(ii)} for $p= (4a-1)/4a$, we have
\begin{equation*}
	\lim_{n\to\infty}\frac{G_n}{\sqrt{n}\log n}=0\ \ \text{a.s., and}
\end{equation*}
\noindent{(iii)} for $(4a-1)/4a<p\le 1$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{G_n}{n^{2a(p-1)+1}}=\frac{L}{(2a(p-1)+2)}\ \ \text{a.s.},
\end{equation*}
where $L$ is as given in \eqref{Lvariab}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:lil-rw2mc of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] {The rates of almost sure convergence of the fluctuations around the almost sure limit in the appropriate regimes are as follows.
\begin{enumerate}
\item[a)] For $p \in \left(0, \frac{11}{16}\right)$,
\begin{align}
    &\limsup_{n \to \infty} \sqrt{\frac{n}{2\log\log n}}\left(\frac{S_n}{{n}} - \Lambda_p\right) \\
    =-&\liminf_{n \to \infty} \sqrt{\frac{n}{2\log\log n}}\left(\frac{S_n}{{n}} - \Lambda_p\right) 
    {= \sqrt{\Sigma^{(1)}_p}}, \nonumber
\end{align}
where $\Sigma^{(1)}_p$ is given by (equation eq:sigma1 of the paper), and for $p \in \left(\frac{113+\sqrt{97}}{128}, 1\right)$, there exists a constant $C > 0$ such that
\begin{align}
    &\limsup_{n \to \infty} \sqrt{\frac{n}{2\log\log n}}\left|\frac{S_n}{{n}} - \Lambda_p\right| \leq C.
\end{align}
\item[b)] For $p \in \left\{\frac{11}{16}, \frac{113+\sqrt{97}}{128}\right\}$,
\begin{align}
    &\limsup_{n \to \infty} \left(\frac{n}{2\log n\log\log\log n}\right)^{1/2}\left(\frac{S_n}{{n}} - \Lambda_p\right) 
    \\ =-&\liminf_{n \to \infty} \left(\frac{n}{2\log n\log\log\log n}\right)^{1/2}\left(\frac{S_n}{{n}} - \Lambda_p\right) 
    {= \sqrt{\Sigma^{(2)}_p}}, \nonumber
\end{align}
where $\Sigma^{(2)}_p$ is given by (equation eq:sigma2 of the paper).
\end{enumerate}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Co ratio of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] Fix~$p_0\in(0,\frac12)$ and~$a\in(0,1)$. Then,
\begin{equation}
\lim_{n\to\infty}
\frac{\sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n^{\pi_a}(p)\bigr)}
      {\sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n(p)\bigr)}
=
\frac{1}{\sqrt a}
\ >\ 1
.
\end{equation}
In particular, the worst-case deficit of every sample-splitting rule~$\pi_a$, $a\in(0,1)$, over~$[p_0,1)$ is asymptotically larger than that of the plug-in rule, by the factor~$1/\sqrt a$. Equivalently, in view of Theorem~(thm:minimax_sharp of the paper), no~$\pi_a$ with~$a<1$ is asymptotically minimax optimal, its asymptotic minimax deficiency being~$1/\sqrt a$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:HB-BAOAB of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $(X_k,V_k)_{k\ge0}$ be the BAOAB chain, with $\xi_k$ the Gaussian variable used in the $k$th step. Let $\xi_0\sim\mathcal N(0,\mathrm{Id}_d)$ be independent of $(\xi_k)_{k\ge1}$, or alternatively let $\xi_0$ be the zero vector, and define the auxiliary variable $X_{-1}$ by
\begin{equation}
 V_0=\frac{2\beta}{(1+\beta)h}(X_0-X_{-1})
 +\frac{\varsigma}{1+\beta}\,\xi_0-\frac h2\nabla U(X_0).
\end{equation}
Then, for $k\ge0$,
\begin{equation}
 X_{k+1}=X_k+\beta(X_k-X_{k-1})-s\nabla U(X_k)+\widetilde\zeta_{k+1},
 \qquad
 s=\frac{h^2}{2}(1+\beta),
\end{equation}
where
\begin{equation}
 \widetilde\zeta_{k+1}=\frac h2\varsigma\,(\xi_k+\xi_{k+1}).
\end{equation}
If $\xi_0\sim\mathcal N(0,\mathrm{Id}_d)$, the sequence $(\widetilde\zeta_k)_{k\ge1}$ is a centered stationary $1$-dependent Gaussian sequence with
\begin{equation}
 \mathbb E[\widetilde\zeta_k\widetilde\zeta_k^\top]=\frac{h^2}{2}(1-\beta^2)\mathrm{Id}_d,
 \qquad
 \mathbb E[\widetilde\zeta_k\widetilde\zeta_{k+1}^\top]=\frac{h^2}{4}(1-\beta^2)\mathrm{Id}_d.
\end{equation}
If (equation eq:vpair-baoab of the paper) is imposed with $\xi_0=0$, then $\widetilde\zeta_1=\frac h2\varsigma\,\xi_1$ has the smaller covariance $\frac{h^2}{4}(1-\beta^2)\mathrm{Id}_d$, while (equation eq:zetacov-baoab of the paper) holds from the second update onward.

