[Proposition prop:tree of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] For all $k\geq1$, we have
\[
{c}_k(t,\boldsymbol{n})
=
\sum_{\gamma^{(k)}\in\Gamma^{(k)}}
\sum_{\substack{\spadesuit^{(k)}\in{\mathrm D}^{(k,\gamma^{(k)})}\\
\lambda(\spadesuit^{(k)})=\boldsymbol{n}}}
\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
\mathfrak I^{(k,\gamma^{(k)})}(t,\spadesuit^{(k)})
\mathfrak F^{(k,\gamma^{(k)})}(\spadesuit^{(k)}),
\]
where for $0\in\Gamma^{(k)}$,
\begin{align*}
\mathfrak C^{(k,0)}(\spadesuit^{(k)})
&={c}(\lambda(\spadesuit^{(k)}))g_{\lambda(\spadesuit^{(k)})},\\
\mathfrak I^{(k,0)}(t,\spadesuit^{(k)})
&=e^{-\mathrm{i} Q(\lambda(\spadesuit^{(k)})) t},\\
\mathfrak F^{(k,0)}(\spadesuit^{(k)})
&=1;
\end{align*}
for $1\in\Gamma^{(1)}$,
\begin{align*}
\mathfrak C^{(1,1)}(\spadesuit^{(1)})
&=\prod_{j=1}^3\{{c}(\boldsymbol{n}^j)g_{\boldsymbol{n}^j}\}^{\ast^{[j-1]}},\\
\mathfrak I^{(1,1)}(t,\spadesuit^{(1)})
&=\int_0^t e^{-\mathrm{i} Q(\lambda(\spadesuit^{(1)}))(t-s)}
\prod_{j=1}^{3}
\left\{e^{-\mathrm{i} Q(\boldsymbol{n}^j) s}\right\}^{\ast^{[j-1]}}
\,\mathrm{d}s,\\
\mathfrak F^{(1,1)}(\spadesuit^{(1)})
&=\mathrm{i}{\varepsilon^\alpha} ;
\end{align*}
and for $\gamma^{(k)}=(\gamma_j^{(k-1)})_{j=1}^3$,
\begin{align*}
\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
&=\prod_{j=1}^3
\left\{\mathfrak C^{(k-1,\gamma_j^{(k-1)})}(\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}},\\
\mathfrak I^{(k,\gamma^{(k)})}(t,\spadesuit^{(k)})
&=\int_0^t e^{-\mathrm{i} Q(\lambda(\spadesuit^{(k)}))(t-s)}
\prod_{j=1}^3
\left\{\mathfrak I^{(k-1,\gamma_j^{(k-1)})} (s,\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}}
\,\mathrm{d}s,\\
\mathfrak F^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
&=\mathrm{i}{\varepsilon^\alpha} \prod_{j=1}^3
\left\{\mathfrak F^{(k-1,\gamma_j^{(k-1)})}(\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}}.
\end{align*}

[Prop 69 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] The following holds if the constant $L$ entering \Cref{yy} is chosen to be sufficiently large. Let the constants $A,B,R$ satisfy
			\begin{eqnarray}

				B \ge 1000 R \ge 1000A \ge 30000. 
			\end{eqnarray}
			Let $q$ satisfy \eqref{eq:condizq}; let $\md,\omega > 0$ satisfy \eqref{condizd} and \eqref{domega}; and let the point $w_0$ around which the cell $\mathcal Y$ is centered satisfy the assumptions in \Cref{def:w0}. Also let $q'$ satisfy
			\begin{align}

				\begin{aligned} 
					&  q' \in [q - N^{R\delta-1} \omega, q].
				\end{aligned}
			\end{align}
			Further assume:
			\begin{enumerate}
				\item [(i)]   For all $w \in \mathcal Y$, we have 
				\begin{eqnarray}

					H_0 (w) \le \cH_\mq (w).
				\end{eqnarray}

				\item [(ii)]  For all $w \in \mathcal Y$ such that $(\mathtt{d}_w \mathtt{e}_{w;q'})^{1/2} \ge \omega^{-1}$ and $\mathtt{d}_w^{1/2} \mathtt{e}_{w;q'}^{3/2} \ge N^{A\delta-1}$, we have
				\begin{eqnarray} 

					H_0 (w) \le \cH_{\mq'} (w) .
				\end{eqnarray}
			\end{enumerate}

			\noindent Apply the Glauber dynamics restricted to  $\mathcal Y$ with {ceiling constraint $\cH_{q'}$ in the region  $\mathcal R:=\{w:(\mathtt{d}_w \mathtt{e}_{w;q'})^{1/2} \ge \omega^{-1}, \mathtt{d}_w^{1/2} \mathtt{e}_{w;q'}^{3/2} \ge N^{A\delta-1}\}$ and ceiling constraint  $\cH_q$ in $\mathcal{Y} \setminus \mathcal R$.} Then, w.o.p., it holds
			\begin{eqnarray}

                          H_t (z) \le \cH_{\mq'} (z) + N^{\delta-1}
			\end{eqnarray}
			 for each $t \in [\mq^{-1} N^{1+10B\delta} \omega,N^{5}]$  and $ z \in \mathcal Y^-$ such that $ \mathtt{d}_z \in (L^{-2} \mathfrak{d}, L^2 \mathfrak{d})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 6 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Assume that Assumption~\ref{ass:main} holds with \(b_0>\Xi(0)\) and \(K/\kappa\leq 2\). Then it holds that
\begin{multline}
\Vert \nabla_x p_t(x)\Vert_2
\lesssim 
\frac{c_0 \Xi(0)(1+\Vert x\Vert_2)}{\left(\Xi(0) e^{-4\Xi(0) t}+b_0(1-e^{-4\Xi(0) t})\right)^{(d+1)/2}}\\
\times \frac{1}{\sqrt{1-e^{-4\Xi(0) t}}}
\exp\left\{
-\frac{\Xi(0)b_0}{\Xi(0) e^{-4\Xi(0) t}+b_0(1-e^{-4\Xi(0) t})}\Vert x\Vert_2^2
\right\}\\
+ c_2(d,\kappa,K,b_0,c_0,\Xi(0),L_{\mathrm{Lip}}(\Xi))
(1+\Vert x\Vert_2)^3
\exp\{-\Xi(0)\Vert x\Vert_2^2\}
\end{multline}
for all \((t,x)\in(0,T)\times\R^d\), where \(c_2(d,\kappa,K,b_0,c_0,\Xi(0),L_{\mathrm{Lip}}(\Xi))>0\) is some constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop lm:Tube-Lemma of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] Fix an oriented rectangular loop $\ell$ with both dimensions at least $100$ strictly contained in the interior of the finite lattice $\Lambda_L$. Then for any plaquette count function $K: \mc{P}_{\Lambda_L}^+ \to \N$, we have
    \begin{equs}
        \int W_{\ell}(Q) \prod_{p \in \mc{P}_{\Lambda_L}^+} \mrm{Tr}(Q_p)^{K(p)}dQ = 0
    \end{equs}
    whenever $|K|:=\sum_p K(p)<4|\ell|-16$, and 
    \begin{equs}
        \sum_{K:|K|=4|\ell|-16}\int W_{\ell}(Q) \prod_{p \in \mc{P}_{\Lambda_L}^+} \mrm{Tr}(Q_p)^{K(p)}dQ >\bigg(\frac{1}{9}\bigg)^{|\ell|}.
    \end{equs} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:fixed f and stable laws of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $f\in\mathcal{LP}_{M}$ for some $M\geq 0$. \begin{enumerate}
		\item If $\sigma^2>0$ and $f_n(z)=f(n^{-1/2}z)$, then \begin{equation}
			\llbracket A_{n,f_n}\rrbracket\Rightarrow \mathsf{sc_{\sigma}},
		\end{equation} the semicircle law with variance $\sigma^2$. 

		\item If $\sigma^2=0$, $n_f$ is regularly varying with index $\alpha\in (0,2)$ and the limit\begin{equation}
			\lim\limits_{r\rightarrow\infty} \frac{n_{f,+}(r)}{n_{f}(r)}=\theta\in[0,1],
		\end{equation} exists,  then set $f_n(z)=e^{-a_nz}f\left(\frac{b_nz}{n}\right)$ to obtain
		\begin{equation}
		\llbracket A_{n,f_n}\rrbracket\Rightarrow\delta_{E}\boxplus\mu_{\alpha,\theta},
		\end{equation}  where $\mu_{\alpha,\theta}$ is the free $\alpha$-stable distribution with L\'evy pair $(0,\Sigma)$ as defined in (equation eq:stable_levy_measure of the paper).


	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma defect-inverse-sign of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $L:[0,1]\rightarrow \lbrack 0,1]$ be a
continuous strictly increasing map with inverse $T=L^{-1}$. Define the
symmetry defects 
\begin{equation}
D_{L}(x)=L(x)+L(1-x)-1,\qquad x\in \lbrack 0,1],  
\end{equation}
and 
\begin{equation}
D_{T}(u)=T(u)+T(1-u)-1,\qquad u\in \lbrack 0,1].  
\end{equation}
Then the following implications hold 
\begin{equation}
D_{L}(x)\leq 0\ \forall x\in \lbrack 0,1]\quad \Longrightarrow \quad
D_{T}(u)\geq 0\ \forall u\in \lbrack 0,1],  
\end{equation}
and 
\begin{equation}
D_{L}(x)\geq 0\ \forall x\in \lbrack 0,1]\quad \Longrightarrow \quad
D_{T}(u)\leq 0\ \forall u\in \lbrack 0,1].  
\end{equation}
In particular, whenever $D_{L}$ has a constant sign on $[0,1]$, $D_{T}$ has
the opposite constant sign on $[0,1]$.

