[Proposition of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $(\Omega,f)$ be a topological dynamical system. Then the following two statements are equivalent:
		\begin{enumerate}[(i)]
			\item $(\Omega,f)$ is minimal;
			\item $(\Omega,\mathcal{H},U_f,\hat{\mathbb{E}})$ is ergodic, where  $\mathcal{H}$ and $\hat{\mathbb{E}}$ are defined as in (equation 123 of the paper) and (equation eq:7.2621:37 of the paper), respectively.
		\end{enumerate}

[Theorem thm:crossedfields of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Let $(\mathscr{X}^{N,1})_{N\ge 1}$ and $(\mathscr{X}^{N,2})_{N\ge 1}$ be two sequences of random fields taking valued in the Skorokhod space $\mathcal{D}([0,T],\mathscr{S}'(\mathbb{R} ))$, and defined on a same probability space. For $i=1,2$, consider also sequences $(v_i^N)_{N\ge 1}$ of real numbers. Assume that
    \begin{enumerate}[label=(\alph*)]
        \item  For almost-every $(k_1,k_2)\in\mathbb{R}^2$, we have
            \begin{equation*}
                \lim_{N\to\infty} \frac{|k_1v_1^N+k_2v_2^N|}{N} = \infty .
            \end{equation*}
        \item  There exist $\alpha\in (0,1)$ and a constant $C>0$ such that for any $f_1,f_2\in\mathscr{S}(\mathbb{R} )$, the following bounds hold
        \begin{equation*}
            \sup_{t\in [0,T]} \mathbb{E}\left[ \big| \mathscr{X}_t^{N,1}(f_1)\mathscr{X}_t^{N,2}(f_2)\big|\right] \le C \prod_{i=1}^2 \|\Delta f_i\|_{L^2}\vee\|\nabla f_i\|_{L^2} ,
        \end{equation*}
        \begin{equation*}
            \mathbb{E} \left[\big| \mathscr{X}_t^{N,1}(f_1)\mathscr{X}_t^{N,2}(f_2) - \mathscr{X}_s^{N,1}(f_1)\mathscr{X}_s^{N,2}(f_2)\big|\right] \le C (t-s)^\alpha \prod_{i=1}^2 \|\Delta f_i\|_{L^2}\vee\|\nabla f_i\|_{L^2}
        \end{equation*}
        uniformly in $N\ge 1$, for any $0\le s\le t\le T$.
    \end{enumerate}
    Then, for any $t\in [0,T]$, any $\varphi\in\mathscr{S}(\mathbb{R} )$ and any~$f_1,f_2\in C_c^\infty (\mathbb{R} )$, we have
    \begin{equation*}
        \lim_{N\to\infty} \mathbb{E}\left[\left| \int_0^t \frac1N \sum_{x\in\mathbb{Z}} \nabla_N\varphi\left(\frac xN\right) \prod_{i=1}^2 \mathscr{X}_s^{N,i}\left( f_i\left(\cdot\, ; \frac{x+v_i^Ns}{N}\right)\right)\,\mathrm{d} s\right|\right] =0,
    \end{equation*}
    where we recall that for $u\in\mathbb{R}$, we denote by $f(\cdot\, ; u)$ the function $v\longmapsto f(v-u)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

