[Lemma of arXiv:2605.20471, 'Note on the Weak Convergence of Hyperplane $α$-Quantile Functionals and Their Continuity i'] \textcolor{black}{
	} Let $T>0,\alpha \in (0,1),\gamma \in \mathbb{R}^d,x \in \mathcal{D}_{\mathbb{R}^d}[0,\infty)$ and $\alpha \notin U(x,T)$ and $M_{T,\alpha}(x)\neq \gamma \cdot x_0$. Then
	\begin{equation}
	\lim_{\beta \to \alpha}\tau_{M_{T,\beta}}(x)=\tau_{M_{T,\alpha}}(x)\iff\begin{cases}
	\lim_{\beta \downarrow \alpha}\tau_{M_{T,\beta}}(x)=\tau_{M_{T,\alpha}}(x)&M_{T,\alpha}(x)>\gamma \cdot x_0\\
	\lim_{\beta \uparrow \alpha}\tau_{M_{T,\beta}}(x)=\tau_{M_{T,\alpha}}(x)&M_{T,\alpha}(x)<\gamma \cdot x_0\\
	\end{cases}
	\end{equation}

[Proposition 20 (Evaluation of $a\md{q}$-sum) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] Let $q=2^kr=2^kcq_1^2q_2^2$ where, $2^k||q$, $\mu^2(c)=1$, $q_1|c^\infty$, and $(c, q_2)=1$. The evaluation of $\mathcal{G}_q(m, n)$ is given by the following,
		\begin{equation}
			\begin{cases}
				\Delta_q(4m-n^2), &\text{$k=0$}.\\
				\sqrt{2}e\left(\frac{m}{2}\right)1_{n\equiv 1\md{2}}\Delta_q(4m-n^2), &\text{$k=1$}.\\
				\frac{1}{2}\Kl_2\left(\frac{4m-n^2}{2^{k}}; 2^2\right)1_{n\equiv 0\md{2}}1_{4m\equiv  n^2\md{2^k}}\Delta_q(4m-n^2)&\\
				\hspace{4cm}+\frac{1}{2^{k}}c\left(\frac{4m-n^2}{2^k}; 2^k\right)\Delta_q(4m-n^2), &\text{$k>1$; $2|k$}.\\
				\frac{1}{2}\Kl_2\left(\frac{4m-n^2}{2^{k-1}}; 2^3\right)1_{n\equiv0\md{2}}1_{4m\equiv n^2\md{2^{k-1}}}\Delta_q(4m-n^2),&\text{$k>1$; $2\nmid k$}.
			\end{cases}
		\end{equation}
		where, 
		\begin{equation}
			\Delta_q(4m-n^2)=q_1q_2^{-1}\eps_c^2\left(\frac{(4m-n^2)/q_1^2}{c}\right)1_{4m\equiv n^2\md{q_1^2}}c(4m-n^2; q_2^2).
		\end{equation}

