[Lemma 54 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Fix \(K<\infty\).  There is \(C_K<\infty\) with the following property.
Let \(\widehat Q_{h,u,L}\) be the underlying endpoint-tilted path law of a
component \(K_{h,u,L}\) from
Proposition~\ref{prop:uniform-entrance-component-compiler}, where
\begin{equation}
  h=2^{-m}\leq1,\quad m\in\mathbb Z_{\geq0},\qquad
  u,L\in h\mathbb Z_{\geq0},\qquad
  0\leq u\leq K.

\end{equation}
Thus, if \(Q_{h,u,L}\) denotes the unweighted law in
\eqref{eq:finite-entrance-component}, then
\begin{equation}
  \frac{\mathrm d\widehat Q_{h,u,L}}{\mathrm dQ_{h,u,L}}
  =\frac{e^{-G_{-u}}}{\EE_{Q_{h,u,L}}e^{-G_{-u}}}.

\end{equation}
Write \(G=-W\) on its right arm.  If \(r\geq2\) and
\begin{equation}
  S:=h\mathbb Z\cap[r,\min(2r,L)]

\end{equation}
is nonempty, then, for \(0<\varepsilon\leq1\),
\begin{equation}
  \widehat Q_{h,u,L}\left(
    \min_{s\in S}\frac{G_s}{s^H}\leq\varepsilon
  \right)
  \leq C_K\varepsilon.

\end{equation}

[Proposition prop:harmonic of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] Fix an input $x$ and a parameter $\theta$.
For every truncation order $T \ge 1$,
\begin{equation}
J^{(T)}_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{T} \frac{1}{k}\Big(\text{\emph{Best-of-}}k(\theta;x) - 1\Big),

\end{equation}
and if $J_{\mathrm{TailRL{}}}(\theta;x) > -\infty$, the same identity holds for the full series,
\begin{equation}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty} \frac{1}{k}\Big(\text{\emph{Best-of-}}k(\theta;x) - 1\Big).

\end{equation}

[Definition of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] A sublinear expectation $\hat{\mathbb{E}}$ on  $\mathcal{H}$ is a functional $\hat{\mathbb{E}}: \mathcal{H}\rightarrow \mathbb{R}$ satisfying the following properties: for all $X,Y\in \mathcal{H}$, we have
		\begin{description}
			\item[(a)] Monotonicity: $\hat{\mathbb{E}}[X]\leq \hat{\mathbb{E}}[Y]$ if $X\leq Y$.
			\item[(b)]Constant preserving: $\hat{\mathbb{E}}[c]=c$ for $c\in\mathbb{R}$.
			\item[(c)]Sub-additivity: $\hat{\mathbb{E}}[X+Y]\leq \hat{\mathbb{E}}[X]+\hat{\mathbb{E}}[Y]$.
			\item[(d)]Positive homogeneity: $\hat{\mathbb{E}}[\lambda X]=\lambda\hat{\mathbb{E}}[X]$ for
			$\lambda\geq 0$.
		\end{description}
  If (c) and (d) is replaced by the the following:
  	\begin{description}
			\item[(e)] Linearity:  $\hat{\mathbb{E}}[\lambda_1 X+\lambda_2 Y]= \lambda_1\hat{\mathbb{E}}[X]+\lambda_2\hat{\mathbb{E}}[Y]$ for $\lambda_1,\lambda_2\in\mathbb{R}$,
		\end{description}
  then $\hat{\mathbb{E}}$ is called a linear expectation.

[Proposition 6 of arXiv:2605.08345, '\vspace{-18mm}\textbf{Quantitative ergodicity for gene regulatory networks with transcript'] If the inequality
\begin{equation} 
\Vert X^{1}(t) - X^{2}(t) \Vert \le \CompL(t),
\end{equation}
is verified at time \( t = 0 \), then it is verified for all \( t \ge 0 \). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] For $n \ge 1$, $1 \le s < h(q_n)$, and $f \in M^{s}$ with $N_f=(N_1,\ldots,N_m)$ and $\#\mathrm{Dom}(f) :=\sum_{i=1}^m N_i$, we have
\begin{align}
    \p_n\big(\text{Coal}^{s}(f)\big)
    = \frac{1}{\big(q_n(s+1)\big)_{\#\mathrm{Dom}(f)}}\, \mathbb{E}_n\!\Bigg[\prod_{i=1}^{m}\big(\nu^s_{j_i}\big)_{N_i}\Bigg],
\end{align}
where $(l)_k := l(l-1)\cdots(l-k+1)$ denotes the falling factorial.

[Proposition 11 (Corrector bound on bounded domains) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Under Assumption~\textup{(U)}, let~$U \subset \Rd$ be a bounded Lipschitz domain and let~$\eps \in (0,1)$.
		For~$1 \le i \le d$, let~$\phi_i$ solve the corrector problem
		\begin{equation} 
			\begin{cases}
				\mathcal{L}^\eps(\ell_{e_i} + \phi_i) = 0 & \text{in } U^\eps\,,\\
				\phi_i = 0 & \text{on } \eps\Zd \setminus U^\eps\,.
			\end{cases}
		\end{equation}
		Then
		\begin{equation}

			\|\phi_i\|_{H^1_{\mathrm{crit}}(U^\eps)}^2 + \|\phi_i\|_{L^2(U^\eps)}^2
			\le \frac{C}{\kappa_\eps}
			+ \mathcal{O}_1\left(\frac{C\eps^d}{\kappa_\eps}\right)
			+ \mathcal{O}_2\left(C\eps^{d/2}\right),
		\end{equation}
		where~$C$ depends only on~$d$,~$\lambda$, and~$U$.

