[Theorem 33 (The range of ooSBM) of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu_{\rm d}$, $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ be such that $\mu_{\rm d} + \mu_{\rm a}$ is a non-zero measure and let $\gamma$, $c$, $\Tilde{c}>0$. Let $\mathcal{Y}=(\mathcal{Y}^{(\rm d)}, \mathcal{Y}^{(\rm a)})$ be an $\text{ooSBM}(\gamma, c, \Tilde{c})$ with initial measure $(\mu_{\rm d}, \mu_{\rm a})$ and let $\mathcal{X}$ be an $\text{SBM}(\gamma)$ with initial measure $\mu_{\rm d} + \mu_{\rm a}$. Then there exists a coupling for $\mathcal{Y}$ and $\mathcal{X}$ such that 
    \begin{equation*}
        \mathcal{R}(\mathcal{Y}^{(\rm d)}) \cup \mathcal{R}(\mathcal{Y}^{(\rm a)}) = \text{supp}(\mu_{\rm d}) \cup \text{supp}(\mu_{\rm a}) \cup \mathcal{R}(\mathcal{X}) \hspace{0.25cm} \text{a.s.} 
    \end{equation*}
    In particular, we have that $\mathcal{R}(\mathcal{Y}^{(\rm d)}) \cup \mathcal{R}(\mathcal{Y}^{(\rm a)})$ is a closed set a.s. and is equal in distribution to 
    \newline
    $\text{supp}(\mu_{\rm d}) \cup \text{supp}(\mu_{\rm a}) \cup \mathcal{R}(\mathcal{X})$. Therefore
    \begin{equation*}
        \text{dim}(\mathcal{R}(\mathcal{Y}^{(\rm d)}) \cup \mathcal{R}(\mathcal{Y}^{(\rm a)})) = \text{dim}(\text{supp}(\mu_{\rm d})) \vee \text{dim}(\text{supp}(\mu_{\rm a})) \vee (4 \wedge d) \text{   a.s.}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] The measure $m(\d\tau)$ in \eqref{eq: MA 01 defn intro} is given by
    \begin{equation}
        C_\gamma \ab[\vartheta_3(0,e^{-\theta\tau}) - \vartheta_3(\theta, e^{-\theta\tau})]\d\tau,
    \end{equation}
    where $C_\gamma$ normalizes $m$ to be a probability measure and $\vartheta_3$ is as defined in \eqref{eq: theta 3 definition}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 14 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $0<\mu\le 1$ and $m\ge1$. For $u_0\in e^X(H^1(\IR^2)\cap L_\mu^2(\IR^2))$, consider the unique solution $u_\eps$ to the regularized equation associated to \eqref{NLS}. Then there exists a unique function $u\in\CC(\IR,e^X(H^1(\IR^2)\cap L_\mu^2(\IR^2)))$ such that
\begin{equation}
\lim_{\eps\to0}\ \sup_{t\in[-T,T]}\|e^{-X_\eps}u_\eps(t)-e^{-X}u(t)\|_{H^1(\IR^2)\cap L_\mu^2(\IR^2)}=0
\end{equation}
for any $T>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

