[Proposition prop for tightness of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] For any $R > 1$,
    \begin{equation} 
    \lim_{\delta \rightarrow 0^+}\sup_{n \in \mathbb{N}}\mathbbm{E}\left(\int_0^{T-\delta}\norm{\hat{u}^{n}_{s + \delta} - \hat{u}^{n}_s}^2ds\right)= 0.
\end{equation} 
Moreover the sequence of the laws of $(u^n)$ is tight in the space of probability measures over\\ $L^2\left([0,T];L^2_{\sigma}\right)$.

[Lemma lem-properties-of-a_k of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Functions $a_k$ defined in (equation eqn-a_n of the paper) satisfy
\begin{enumerate}
\item[(i)] 
$a_k \searrow \1_A \mbox{  as } k \to \infty$.
\item[(ii)] The support of $a_k$ is contained in $S_{\frac{\alpha}{2}}$.
\item[(iii)] For future reference we also show  that
\begin{equation}
a_k(u) \leq \left(\frac{2}{\alpha} \@ifstar{\oldabs}{\oldabs*}{u}_{U^\prime}\right)^{\ell} \qquad \mbox{  for all } u \inU^\prime, k \geq 2, \ell\ge 1.
\end{equation}
\item[(iv)] For $u_1,u_2 \in U^\prime$
\begin{equation}
\vert a_k(u_2)-a_k(u_1) \vert
\leq  \frac{k^2}{a^2}\@ifstar{\oldnorm}{\oldnorm*}{f}_{\mathrm{Lip}} \@ifstar{\oldabs}{\oldabs*}{u_1-u_2}_{U^\prime} \bigl( \rho(u_1,A)+ \rho(u_2,A)\bigr),
\end{equation}
where  $\@ifstar{\oldnorm}{\oldnorm*}{f}_{\mathrm{Lip}}$ is the Lipschitz constant of the function $f$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lemma Ratio 1 of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $K>0$ and $E_t=E_t^1 \text{ or } E_t^2$. Then, there exists some $u \ge 0$ \textcolor{black}{(depending on $t$)} such that
    \begin{equation}
        \sup_{x \in E_t} \frac{e^t \mathbb P(|x+B_t-\lambda t|\le K)}{\mathbb P(|x+B_u-\lambda u|\le K)} \longrightarrow 0
    \end{equation}
    as $t \to \infty.$ 
    In particular, 
    \begin{equation}
        \sup_{x\in E_t} e^t \mathbb P(|x+B_t-\lambda t|\le K) \to 0
    \end{equation}
    as $t \to \infty$. (equation Eqn ratio 1 of the paper) and (equation Eqn implies by ratio 1 of the paper) hold for $\lambda =\sqrt{2}$ and $E_t = E_{t}^2 = \{|x| > bt \}$ for any $b>2\sqrt{2}$ as well.

