[Lemma lem:4.2 of arXiv:2608.27474, 'Nonlocality of Cover-Time Changes Under Edge Addition'] The target coefficients satisfy:

\begin{enumerate}
\def\arabic{enumi}.{\arabic{enumi}.}
\tightlist
\item
  If \(u,v\in S\), the response is identically zero.
\item
  If exactly one endpoint is outside \(S\), call it \(w\), then
\begin{equation}
  B_S=0,\qquad
  A_S=K_S(s,w)\bigl(1-H_w^0(S)\bigr)\le0.

  \end{equation}

\item
  If \(u,v\notin S\), then
\begin{equation}
  \boxed{
  B_S=
  2\!\left[
  K_S(s,u)\bigl(K_S(v,v)-K_S(u,v)\bigr)
  +K_S(s,v)\bigl(K_S(u,u)-K_S(u,v)\bigr)
  \right]\ge0.
  }

  \end{equation}
It is strictly positive precisely when \(s\) lies in the same
  component of \(G[B]\) as at least one of \(u,v\).
\end{enumerate}

[Definition Def:linear-m-s-stability of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Let ${\widetilde{Y}}$ be the solution of (equation eq:lin_gen of the paper) with initial data ${\widetilde{Y}}(0)\in\mathbb{R}^d$. 
    The point $x^\ast\in\mathbb{R}^d$ is said to be linearly mean-square  stable for the system (equation eq:main_d of the paper) if  there exist a constant $\alpha \geq 0$ and a time $t^\ast>0$ sufficiently large such that for all ${\widetilde{Y}}(0)\in\mathbb{R}^d$
$$\expect{\|{\widetilde{Y}}(t)\|^2} \leq \alpha^2 \quad \text{for all } t\geq t^\ast.$$
We then  define $\boldsymbol{\beta}>0$ as    \begin{equation}

    \boldsymbol{\beta}^2:=\lim_{t\to\infty} \expect{\|{\widetilde{Y}}(t)\|^2}<\infty.
    \end{equation}

[Proposition 29 of arXiv:2609.03736, '2609.03736'] For every $n\geq1$,
\begin{equation}
 A^{\mathrm K}_+(n)\leq A^{\mathrm K}_-(n).

\end{equation}

[Lemma 16 of arXiv:2506.18558, '2506.18558'] Suppose that Assumptions {\rm\ref{A1}}, {\rm\ref{A2}}, {\rm\ref{A3}} and {\rm\ref{A5}} hold.
For any $x\in\RR^{n}$, the SDE \eqref{e:ASDE2} has a unique strong solution $(X_t)_{t\ge0}$. Moreover, for any $T>0$, there exists a constant $C_{T}>0$ such that
\begin{align}
\mathbb{E}\left(\sup_{t\in [0, T]}|X_{t}|^{2}\right)\le  C_{T}(1+|x|^{2}).
\end{align}

