body:
[Theorem 2 of arXiv:2608.13631, 'The classical discrete laws near the mode:\\ complete local expansions for the negative bi'] As $r\to\infty$, uniformly for $p$ in compact subsets of $(0,1)$ and $t\in H$ with
	$\mu+t\in\Z_{\ge0}$,
	\begin{equation}
	\begin{gathered}
		\log\Bigl[\sqrt{2\pi\sigma^{2}}\;P(\mu+t)\Bigr]
		\sim\sum_{n\ge1}\frac{A_n(t;p)}{r^{n}},\\
		A_n=\frac{(-1)^{n+1}}{n(n+1)}
		\Bigl[p^{n}B_{n+1}(t)
		-\Bigl(\frac pq\Bigr)^{n}B_{n+1}(t+1)-B_{n+1}\Bigr].
	\end{gathered}
	\end{equation}
	In particular
	\begin{equation}
		A_1(t;p)=-\frac{p^{2}}{2q}\,B_2(t)-\frac pq\,t-\frac1{12},
		\qquad
		A_2(t;p)=-\frac16\Bigl[p^{2}B_3(t)-\frac{p^{2}}{q^{2}}\,B_3(t+1)\Bigr],
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Consider the model described in \S\ref{subsec:model_growing_sample_size}, and assume that the limit $\lim_{n\rightarrow\infty}(n+1)^{-1}k_{n}^{-1}s_{n+1}$ exists and equals $\eta$ for some $\eta\in(0,1)$. Assume that the first two criteria of \eqref{k_{n}_sequence_conditions} are satisfied, and that 
\begin{equation}_eta_conditions}
\sum_{n\geqslant N}\frac{k_{n}}{s_{n+1}}\left|\frac{s_{n+1}}{(n+1)k_{n}}-\eta\right| \text{ converges}.
\end{equation}
Assume, also, that one of \eqref{A1}, \eqref{A2} and \eqref{A3} is satisfied. Then the sequence $\{(n^{-1}A_{n},s_{n}^{-1}B_{n},s_{n}^{-1}C_{n})\}$ converges almost surely to a (possibly path dependent) compact, connected, internally chain transitive invariant set, contained in $\hat{\mathcal{S}}$, corresponding to the autonomous ODE 
\begin{equation}
\begin{bmatrix}
\dot{a}(t)\\
\dot{b}(t)\\
\dot{c}(t)
\end{bmatrix}=\begin{bmatrix}
\eta\hat{h}_{1}(a(t),b(t),c(t))\\
\hat{h}_{2}(a(t),b(t),c(t))\\
\hat{h}_{3}(a(t),b(t),c(t))
\end{bmatrix},\quad \text{with} \quad \begin{bmatrix}
a(0)\\
b(0)\\
c(0)
\end{bmatrix}=\begin{bmatrix}
A_{N}/N\\
0\\
0
\end{bmatrix},
\end{equation}
where $\hat{h}_{1}$, $\hat{h}_{2}$ and $\hat{h}_{3}$ are as defined via \eqref{hat{h}_defn_growing_size}, \eqref{hat{H}_{1}_defn}, \eqref{hat{H}_{2}_defn} and \eqref{hat{H}_{3}_defn}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LMMMNNNNS of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume $A$ and $\pi$ satisfy the same conditions as in Lemma (PII of the paper), and let  $C \in {L}(\mathbb{R}^n\times \mathbb{R}^n,L(\mathbb{R}^d,\mathbb{R}^n))$. Consider the following linear equation:
				\begin{align}
					\begin{split}
						\mathrm{d}y_t &= A\left( y_t, \int_{-r}^{0} y_{\theta+t} \pi(\mathrm{d}\theta) \right) \mathrm{d}t + \epsilon C(y_t, y_{t-r}) \mathrm{d}B_t(\omega), \\
						y_{\theta} &= \xi_{\theta} \quad \text{for} \quad \theta \in [-r, 0], \quad \xi \in C([-r, 0], \mathbb{R}^n).
					\end{split}
				\end{align}
				Let $y^{\xi,\epsilon}_{t}$ denote the solution and $\lambda_{1}<$, where $\lambda_{1}$ is  defined in (equation TRFVV of the paper). Then We can find $\epsilon_0>0$ such that for every  $0<\epsilon<\epsilon_0$ exusts $\lambda^\epsilon<0$ such that if $\xi\in C([-r,0],\mathbb{ R}^d)$, then 
				\begin{align*}
					\limsup_{t\rightarrow \infty}\frac{1}{t}\log\Vert y^{\xi,\epsilon}_t\Vert\leq \lambda^\epsilon, \ \  a.e.
				\end{align*}

