[Prop 83 (Tightness of all relevant processes) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] The following are true.
 \begin{enumerate}
		\item The fields $M^N$ from \eqref{mfield} may be realized as an element of $C([0,T],C^{\alpha,\tau}(\mathbb R^d))$ for any $\alpha<-5$ and $\tau>1$. Moreover, they are tight with respect to that topology.  \item The fields $\mathfrak F_N:=\mathscr B_N\cdot (\mathfrak H^N-\mathbb E[\mathfrak H^N])$ from \eqref{hn} may be realized as an element of as an element of $C([0,T],C^{\alpha,\tau}(\mathbb R^d))$ for any $\alpha<-d-p-2$ and $\tau>1$. Moreover, they are tight with respect to that topology.
        \item For any $f:I\to \mathbb R$ of exponential decay, the fields $Q_N^f$ from Definition \ref{qfield} may be realized as an element of $C([0,T],C^{\gamma,\tau}(\mathbb R))$ for any $\gamma<-1$ and $\tau>1$. Moreover, they are tight with respect to that topology.

        \item Let $\alpha,\gamma<0$ be as in the previous items. Let $(M^\infty,Q^{f,\infty}, H^\infty)$ be a joint limit point of $(M^N,\hat Q_N^{f},\mathfrak H^N)$ in the space $C\big([0,T],C^{\alpha,\tau}(\mathbb R^d)\times C^{\gamma,\tau}(\mathbb R^d)\times C^{\alpha,\tau}(\mathbb R^d)\big),$ where $f$ could be any specific function on $I$. For all $\phi\in C_c^\infty(\mathbb R)$, the process $(M_t^\infty(\phi))_{t\in[0,T]}$ is a continuous martingale with respect to the canonical filtration on that space, and moreover its quadratic variation is given by
  \begin{equation}

      \langle M^\infty(\phi)\rangle_t = \begin{cases} \sum_{\#(k_1)=p ,\#(k_2)=p} \frac{1}{k_1!k_2!} Q_t^{\boldsymbol\eta_{k_1,k_2},\infty}(\partial^{k_1} \phi\cdot \partial^{k_2}\phi), & N^{1/2} \varsigma_N\to 0 \\ Q_t^{\z_{  {\boldsymbol v}} ,\infty} (\phi^2) , & N^{-1}\psi_N(p,d)\gg |  \varsigma_N|\gg N^{-1/2} , \frac{   \varsigma_N}{|  \varsigma_N|}\to   {\boldsymbol v} \\ 
      Q_t^{\z_{  {\boldsymbol v}/|  {\boldsymbol v}|} ,\infty} (\phi^2) , & d=2 \text{ and } (\log N)^{1/2p}   \varsigma_N\to   {\boldsymbol v}\ne 0 \\ 
      |  {\boldsymbol v}|^{-2p} Q_t^{\boldsymbol\vartheta_{  {\boldsymbol v}} ,\infty} (\phi^2), & d\ge 3 \text{ and } \varsigma_N\to   {\boldsymbol v} \ne 0.
      \end{cases}
  \end{equation} Here $\boldsymbol\eta_{\alpha,\beta}$, $\z$, $\boldsymbol{\vartheta}_{   v}$ are the specific functions from Definitions \ref{etadef}, \ref{z}, and \ref{def:vartheta} respectively. Furthermore, the same joint limit holds if $f$ is replaced by $f_N$ in the prelimit, where $\sup_N f_N$ is dominated by some function of exponential decay and $f_N\to f$ uniformly.
  \end{enumerate}

[Lemma 51 of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Let $(t,x) \in L\cdot (\Z_{\leq 0} \times \Z^d)$ such that $(t,x)$ is $(L,\delta)$-mixed. 
Then, the following statements are true:
\begin{itemize}
\item For any $r \in [-L(t+1), -L t]$, the distributions of $R^{\Lambda_{2n_L}(v), -(t+1)n_L, -r}(\alpha^\pm)|_{\Lambda_{n_L}(x)}$ are given by the measure $\mu^{\SWM}_{\Lambda_{2n_L}}(\cdot|_{\Lambda_{n_L}(x)})$.
\item For any $r \in [-L(t+1), -L t]$, the random variables $R^{\Lambda_{2n_L}(x), -(t+1)n_L, -r}(\alpha^\pm)|_{\Lambda_{n_L}(x)}$ are independent of the Poisson process outside of the set $\Lambda_{2n_L}(x) \times [-(t+1)n_L, tL] $. 
\end{itemize}

[Lemma 12 of arXiv:2608.26834, 'Small-time annealed large deviations principle for one-dimensional diffusions in a random '] Let $I$ be a bounded interval and let $f\in H_0^1(I)$. Then
		\begin{equation}
			\|f\|_{L^\infty(I)}^2
			\le 2 e^{M(I)}\|f\|_{L^2(I,\mu_W)}\,\mathcal E_W(f,f)^{1/2}.
		\end{equation}
		Consequently,
		\begin{equation}
			\int_I|f|^6\,\dd \mu_W
			\le 16 e^{2M(I)}\left(\int_If^2\,\dd \mu_W\right)^2\mathcal E_W(f,f).
		\end{equation}

