	\end{align}

\medskip		

\noindent \underline{\textbf{$\upmu$ is large when $|u| \geq \frac{3}{4}\interestingu$}}.
	The following lower bound holds, where $\boringregionmupositive > 0$ is the constant appearing in 
	\eqref{E:DATAMUISLARGEINBORINGREGION}:
