        Let $P: \univcover\times \univcover\to \univcover$ be the product map sending $(\widetilde{A}, \widetilde{B})$ to $\widetilde{A}\widetilde{B}$, and let $s, s_1, s_2\in \{\pm 1\}$.
\begin{comment}
        \textcolor{Green}{For hyperbolic image under $P$, the following holds:}
        \begin{enumerate}[(1)] 


            \item \textcolor{Green}{$P(\Hyp_0\times \Hyp_0)\cap \big(\bigcup_{k\in \mathbb{Z}}\Hyp_k\big)
            = \Hyp_{-1}\cup  \Hyp_0\cup\Hyp_1$.}



            \item \textcolor{Green}{$P(\Hyp_0\times \Par_0^{sgn(s)})\cap \big(\bigcup_{k\in \mathbb{Z}}\Hyp_k\big) = \Hyp_0\cup \Hyp_{s}$.}

            \item \textcolor{Green}{$P\big(\Par_0^{sgn(s_1)}\times \Par_0^{sgn(s_2)}\big)\cap \big(\bigcup_{k\in \mathbb{Z}}\Hyp_k\big) = \Hyp_{\frac{s_1+s_2}{2}}$.}

        \end{enumerate}
\end{comment}
        Then the following holds:
        \begin{enumerate}[(1)] 





            \item $P\big(\Par_0\times\Ell_1 \big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big) = \Ell_1$.
            \item $P\big(\Par_0\times \Ell_{-1}\big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big)=\Ell_{-1} $
            \item $P\big(\Par^-_0\times\Par^-_0 \big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big) = \Ell_{-1}$.


            \item 
            $P\big(\Hyp_0 \times\Hyp_0\big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big) \subset \Ell_{-1}\cup \Ell_1$.

            \item $P\big(\Ell_{-1} \times\Ell_1\big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big) \subset \Ell_{-1}\cup \Ell_1$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Main_contribution in sec3 of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $(p_{i})_{i\in I}$ be the atoms of a Poisson point process $\mathcal P$ with intensity measure $e^{-\mu x}dx$. For any choice of $z\in \mathbb R$ and $\epsilon>0$, there exist $t_{0}>0, \delta >0$ such that for all $t > t_{0}$, 
  \begin{equation}
    \mathbb{P} \biggl(\exists i\in \mathbb N, k \le n^{i}(t):p_{i}+\chi_k^i(t)-\lambda t \ge z,p_i\notin[-(\mu - \lambda)t-\delta\sqrt{t},-(\mu -\lambda)t+\delta\sqrt{t}]\biggr)\le \epsilon. 
  \end{equation}

