[Proposition 22 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Let $\widetilde X^h$ be a strong solution of \eqref{eq:  h-regularized SDE}. Then $\widetilde X^h\in \mathbb L^{1,2}$, and in particular for every $i=1,\dots,n$ and every $t\leq T$
\begin{align*}
    \mathbb{E}[|D_r^i \widetilde X^h_T|^2]+\int_0^T \int_0^T \mathbb{E}[|D_s^i \widetilde X^h_t|^2]\,ds\,dt\leq C,
\end{align*}
where $C$ does not depend on $N$, or $h$. The constant is allowed to depend on $A$.

[Lemma quantitative CLT of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] For each exponent ${\delta> 0}$, there exist finite positive constants $C,s$ depending only on the parameters $d,\mathfrak{p}$ and $\delta$, such that for every $y\in\mathbb{Z}^d$, there exists a nonnegative random time $\mathcal{T}_{par,\delta}(y)$ satisfying
		\begin{equation}
			\forall T\geqslant 0,\qquad \mathbb{P}_\mathfrak{p}\left(\mathcal{T}_{par,\delta}(y)\geqslant T\right)\leqslant C\exp\left(-\frac{T^s}{C}\right). 
		\end{equation}
		On the event $\{y\in\mathscr{C}_\infty\}$, for every $x\in \mathscr{C} _\infty$ and every $t\geqslant \max\{\mathcal{T}_{par,\delta}(y),\vert x-y\vert\}$, we have
		\begin{align*}
			\vert p^\omega(t,x,y)-\theta(\mathfrak{p})^{-1}\bar{p}(t,x-y)\vert \leqslant C t^{-\frac{d}{2}-(\frac{1}{2}-\delta)} \exp\left(-\frac{\vert x-y\vert^2}{Ct}\right).
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2605.02226, 'Finitely Dependent Processes on Subshifts'] For $ m \in \mathbb{N}$, an element $x \in \{ 0,1\}^{G}$ is called an $ \mathbf{m}$-\textbf{net} (with respect to distance $d$ on $G$) if the set $ \{ g \in G: x_g =1\}$ is a maximal $m$-separated set. In other words, it is
\begin{enumerate}
    \item $m$-covering i.e. for every $ g \in G$ there exists $h\in G$ such that $ d(g,h) \leq m$ and $x_h= 1$, and
    \item $ m$-separated i.e. for every $ g $ with $x_g = 1 $ and $ h $ such that $ d(g, h) \leq m$ we have $ x_{h}=0$.
\end{enumerate}

