[Proposition 1 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] For any fixed $t>0$ and $p \ge 1$, the mapping $\epsilon \mapsto X^\epsilon$ is continuously differentiable in the Banach space of continuous processes endowed with the norm $\|\cdot\|_{p,t}$. 

  Moreover, the derivatives $X_t^{[k],\epsilon} := \partial_\epsilon^k X_t^\epsilon~(k\geq 1)$ satisfy the stochastic differential equation obtained by formal differentiation of \eqref{eq-eta}:
 \begin{align*}
  &dX_t^{[k],\epsilon}=\sum_{j=1}^k \sum_{(i_1,\cdots,i_j)\in \Lambda(k,j)}\nu(k,(i_1,\cdots,i_j))\partial^{j}\alpha(X_t^\epsilon)[X_t^{[i_1],\epsilon}\otimes \cdots \otimes X_t^{[i_j],\epsilon}]dt\\
  &+\epsilon\sum_{j=1}^k \sum_{(i_1,\cdots,i_j)\in \Lambda(k,j)}\nu(k,(i_1,\cdots,i_j))\partial^{j}\beta(X_t^\epsilon)[X_t^{[i_1],\epsilon}\otimes \cdots \otimes X_t^{[i_j],\epsilon}]dV_t\\
  &+k\sum_{j=1}^{k-1} \sum_{(i_1,\cdots,i_j)\in \Lambda(k-1,j)}\nu(k-1,(i_1,\cdots,i_j))\partial^{j}\beta(X_t^\epsilon)[X_t^{[i_1],\epsilon}\otimes \cdots \otimes X_t^{[i_j],\epsilon}]dV_t.
\end{align*}
with $X_0^{[k],\epsilon}=0$. Here,
\begin{align*}
  \Lambda(k,j)=\left\{ (i_1,\cdots,i_j)\in \mathbb{N}^j;i_1\leq \cdots \leq i_j,~i_1+\cdots+i_j=k  \right\},
\end{align*}
and $\nu(k,(i_1,\cdots,i_j))$ represents the number of partitions of the set $\{1,\cdots,k\}$ into $j$ subsets with $(i_1,\cdots,i_j)$ elements, and 
\begin{align*}
  &\partial^{j}\alpha(x_1,\cdots,x_{d_1})[\xi^1\otimes \cdots \otimes \xi^k]\\
  =&\sum_{i_1,\cdots,i_k=1}^{d_1}\frac{\partial}{\partial x_{i_1}} \cdots \frac{\partial}{\partial x_{i_k}} \alpha(x_1, \cdots, x_{d_1})\xi_{i_1}^1\cdots \xi_{i_k}^k
\end{align*}
for $\xi^{i}=(\xi_1^i,\cdots,\xi_{d_1}^i)~(i=1,\cdots,k)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.00449, 'First-order phase transitions in the hard-core model'] \label[theorem]{thm:regtree}
    For $\Delta\ge 3$, the value
    \[ \lambda_c(\Delta)=\frac{(\Delta-1)^{\Delta-1}}{(\Delta-2)^\Delta} \]
    is the Gibbs uniqueness threshold for the hard-core model on the infinite $\Delta$-regular tree $\TT_\Delta$ in the sense that
    \begin{enumerate}
        \item for $\lambda< \lambda_c(\Delta)$, $\TT_\Delta$ has uniqueness at $\lambda$, and
        \item for $\lambda> \lambda_c(\Delta)$, $\TT_\Delta$ has phase coexistence at $\lambda$.
    \end{enumerate}
    Further, the phase transition on $\TT_\Delta$ at $\lambda_c(\Delta)$ is second-order in the sense of \Cref{def:orders}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 of arXiv:2604.25769, 'The conformal dimension of the Brownian tree is one'] Let $x \in \SCT$ and $n \in \BN$. Then:
    \begin{itemize}
        \item We shall write $E(x, n)$ (resp.~$\widetilde E(x, n)$) for the event that there exists a subtree branching off $\llbracket x, \SR_{4\alpha^n}(x)\rrbracket$ (resp.~$\llbracket x, \SR_{32\alpha^n}(x)\rrbracket$) with diameter at least $\alpha^{n - 1}/4$. (Recall from \Cref{subsubsection:infinite-Brownian-tree} that $\SR_{4\alpha^n}(x)$ denotes the unique point on the geodesic ray $\llbracket x, \infty\rrparenthesis$ such that $d_\SCT(x, \SR_{4\alpha^n}(x)) = 4\alpha^n$ and that a subtree branching off $\llbracket x, \SR_{4\alpha^n}(x)\rrbracket$ is the closure of a bounded connected component of $\SCT \setminus \llbracket x, \SR_{4\alpha^n}(x)\rrbracket$.)
        \item We shall write $\sigma(x, n) \defeq 32\alpha \cdot \mathbf 1_{E(x, n)}$. 
    \end{itemize}

[Lem 156 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For parameters as in \eqref{eq:eta-delta-eps}, the state evolution limits of $\IAMP_{\chaos,N}(p,\sigma,b,w,\delta,\eta
  )$ satisfy:
  \begin{equation}

  \begin{aligned}
  \bbW_2\Big( |X^{\ubl}|, |\hat X^{\ubl,\eta}|\Big)
  &\le
  o_{\eta\to 0}(1), \\
  \quad 
  \bbW_2\Big(|Y^{\ubl}|,
    |\hat Y^{\ubl,\eta}|\Big)
  &\le
        o_{\eta\to 0}(1)\,,
  \end{aligned}
  \end{equation}
where $X^{\ubl}$ and $Y^{\ubl}$ are as in \eqref{e:state.evol.x.y.increments}
from 
\S\ref{subsec:IAMP-setup}.

[Lemma semiellipse_1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For any point $(s,u)\in \cup_{l=1,2}\cup_{i\in \mathbb{N}}C^l_i$, the following holds true: 
\begin{enumerate}[(i)]
\item  The point $(s,u) \in {\mathcal L }_e(v_1, v_2)$ if and only if $ {\mathcal H }^{l}(E^{s, v_l}_{u})= 0$, for $l=1,2$.
\item  The probability of such an event is
\begin{equation}
\mathbb{P}\left((s,u) \in {\mathcal L }_e(v_1, v_2)\right)= e^{-\lambda \pi u^2}. 
\end{equation}
\end{enumerate}

