  q\int_0^t e^{qs}ds\int_0^s e^{-qu}dA_u=e^{qt}\E_x\left[\int_0^\infty e^{-qs}dA_s\Big|\F_t\right]-u_q^A(X_t)-A_t.
\end{align*}
Thus, we have
\begin{align*}
u_q^A(X_t)=u_q^A(x)+M_t^{q,\nu}+q\int_0^t u_q^A(X_s)ds-A_t,
\end{align*}
where 
\begin{align*}
