[Prop trunbiliearestis of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $s\geq 0$, $3/8<b<1/2$, $\varepsilon<2b-3/4$, $R>0$, $0<T<1$. Then, we have
		\begin{equation*}
			\left\|\int_0^tU(t-t')(B_R(u))_x~dt'\right\|_{Z_T^{s,b}}\lesssim RT^\varepsilon\|u\|_{Z_T^{s,b}}
		\end{equation*}
		and
		\begin{equation*}
		\left\|\int_0^tU(t-t')(B_R(u)-B_R(v))_x~dt'\right\|_{Z_T^{0,b}}\lesssim RT^{\varepsilon}\|u-v\|_{Z_T^{0,b}}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary CorSingleBlock of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] For any choice of $r_0 \in (0, 1/2)$ and iteration number $N
    \geq 2 \ell_d$, applying the \textsf{PRD}\xspace sampler with the stepsize
    protocol~(equation EqnSingleBlockGrid of the paper) over the interval $[r_0, 1
      - r_0]$ returns output $\ensuremath{\widehat{Z}}$ such that
\begin{align}

  \ensuremath{D_{\scaleto{\operatorname{KL}}{4pt}}}(\ensuremath{\mathbb{P}}_Z \| \ensuremath{\mathbb{P}}_{\ensuremath{\widehat{Z}}}) & \leq \frac{8 \ell_d}{N}
  \mathsf{G}(r_0, 1 - r_0) +  \ensuremath{\mathsf{TC}}(\ensuremath{X}_{r_0}) + \ensuremath{\mathsf{TC}}(Z \mid
  X_{1 - r_0}) \qquad \mbox{where
    $\ell_d = \log\left( \frac{1 - r_0}{r_0} \right)$.}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm 5 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Let $\mu \in \mathcal{P}_2(\mathbb{R})$ and $F_{\mu}^{-1}$ be its representative in $\mathcal{U}^2(\mathbb{S})$ as defined in \eqref{inverse}. Then, the following holds for    any fixed {$h\in T/{\mathbb N}^*$}:
	\begin{itemize}
	\item[i.] The difference ${F}^{-1}_{\mu*\Gamma_h}-{F}^{-1}_{\mu}$ is monotone: \text{ if} $\phi \in \mathcal{U}^2(\mathbb{S})$, then $\langle \phi,{F}^{-1}_{\mu*\Gamma_h}-{F}^{-1}_{\mu}\rangle \geq 0$;
	\item[ii.] In addition, if $\phi$ is also in $\mathcal{C}^1(\mathbb{S})$, then the following identity holds:
	\begin{align*}
		\left\langle \phi,F^{-1}_{\mu\star\Gamma_h}-F^{-1}_{\mu}\right\rangle :=\frac{1}{4}\int_{\mathbb{R}}\int_{0}^h \phi'\bigg(\frac{(\tilde{F}_{\mu}\star\Gamma_t)(z)}{2}\bigg)\big[D_z (\tilde{F}_{\mu}\star\Gamma_t)(z)\big]^2\mathrm{d}t\mathrm{d}z.
	\end{align*}
	\end{itemize}

[Lemma 33 of arXiv:2607.18104, '2607.18104'] For $\delta>0$ and $N\in \N$, let $(u;v) = (u_1,u_2;v_1,v_2) \in D_{\delta^{1/4}}^N \cap \big(\mathbb{X}^{N}_{\delta^{1/4}} \times \mathbb{X}^{N}_{\delta^{1/4}}\big)$ be such that $v_2-u_2 \geq 3\delta^{1/2}N^{3/2}$.  There exist $c,C>0$, which do not depend on $\delta>0$ or $N\in \N$, such that 
the events
\begin{equation*}
    \hat{D}_{N,\delta}^{u,v} := \Big\{\gamma^{\per}_{u',v}(u_2+z) \in [u_1-5\delta^{3/5}N,u_1+5\delta^{3/5}N] \, \forall \, u' \in \bar{B}^N_{\delta}(u) , z\in [\delta N^{3/2},3\delta N^{3/2}] \Big\}
\end{equation*}
 satisfy for all $\delta>0$ and all $N$ large enough
 \begin{equation}
\mathbb{P}\big(\hat{D}_{N,\delta}^{u,v} \big) \geq 1 - C\exp(-c\delta^{-1/24}) .
\end{equation}  Similarly, we get that the events
\begin{equation*}
    \check{D}_{N,\delta}^{u,v} := \Big\{\gamma^{\per}_{u,v'}(v_2-z) \in [v_1-5\delta^{3/5}N,v_1+5\delta^{3/5}N] \, \forall \, v' \in \bar{B}^N_{\delta}(v) , z\in [\delta N^{3/2},3\delta N^{3/2}] \Big\}
\end{equation*}
satisfy for all $\delta>0$ and all $N$ large enough
 \begin{equation}
\mathbb{P}\big(\check{D}_{N,\delta}^{u,v} \big) \geq 1 - C\exp(-c\delta^{-1/24}) .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

