\begin{align*}
\mathbb{E}\bigl[(F - \mathbb{E}[F] - \delta_X(\Pi_X D_X F)) \cdot \delta_X(u)\bigr]
&= \mathbb{E}[F \cdot \delta_X(u)] - \mathbb{E}[\delta_X(\Pi_X D_X F) \cdot \delta_X(u)] \\
&= \langle D_X F, u \rangle_{\mathcal{H}_X} - \langle \Pi_X D_X F, u \rangle_{\mathcal{H}_X} \\
