body:
[Theorem 1 (Quantitative homogenization) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Under Assumption~\textup{(U)}, let $\sigma \in (0,1)$, let $\mu \ge 0$, let $U \subset \Rd$ be a bounded domain with $C^{2,\sigma}$ boundary, and let $f \in C^{0,\sigma}(\bar U)$.
		For $\eps \in (0,1)$, let $u^\eps_\mu \colon \eps\Zd \to \R$ and $\bar u_\mu \in H^1_0(U)$ be the solutions of
		\begin{equation}

			\left\{
			\begin{aligned}
				\mu u^\eps_\mu - \mathcal{L}^\eps u^\eps_\mu &= f && \text{in } U \cap \eps\Zd\,, \\
				u^\eps_\mu &= 0 && \text{on } \eps\Zd \setminus U\,,
			\end{aligned}
			\right.
			\qquad \text{and} \qquad
			\left\{
			\begin{aligned}
				\mu \bar u_\mu - \frac{\E[\a(0,e_1)]}{2d} \Delta \bar u_\mu &= f && \text{in } U\,, \\
				\bar u_\mu &= 0 && \text{on } \partial U\,.
			\end{aligned}
			\right.
		\end{equation}
		Then there exist constants $C < \infty$, $c > 0$ depending only on $\mu$, $d$, $\lambda$, $\sigma$, $U$, and $\|f\|_{C^{0,\sigma}}$, and a random variable $\mathcal{X}$ satisfying
		\begin{equation}

			\P\bigl[\mathcal{X} > s\bigr] \le C e^{-c s}
			\qquad \text{for every } s \ge 1\,,
		\end{equation}
		such that for every $\eps \in (0,1)$ with $\left| \ln\eps \right| \ge \mathcal{X}$,
		\begin{equation}

			\left\| u^\eps_\mu - \bar u_\mu \right\|_{L^2(U \cap \eps\Zd)} \le \frac{C}{\sqrt{\left| \ln\eps \right|}}\,.
		\end{equation}
		Here $\|g\|_{L^2(U \cap \eps\Zd)}^2 \coloneqq \eps^d \sum_{x \in U \cap \eps\Zd} g(x)^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm g=1_general of arXiv:2608.25362, 'Fluctuations of the free energy of the Sherrington--Kirkpatrick model with ferromagnetic i'] Let $\beta<1$ and $\gamma_N = 1 + \theta N^{-1/2}$ for some $\theta\in\mathds{R}$. Then
    \begin{align*}
        N F_N^{(J)}(\beta,\gamma_N)&- N\ln2 - \frac{N-1}{4}\beta^2 - \frac14\ln N \\
        &\overset{d}{\longrightarrow}
        \zeta_1 + \ln \int_{\mathds{R}} \exp\Big( \Big(\zeta_2 + \frac{\theta}{2}\Big)y^2 - \Big(\frac1{12} + \frac{v_2^2}{2}\Big)y^4 \Big)\,\frac{dy}{\sqrt{2\pi}},
    \end{align*}
    where
    \begin{align*}
        v_1 = \Big( -\frac12\ln(1-\beta^2) - \frac{\beta^2}{2} - \frac{\beta^4}{4} \Big)^{1/2},
        \qquad
        v_2 = \Big( \frac{\beta^2}{2(1-\beta^2)} \Big)^{1/2},
    \end{align*}
    and $\zeta_1 \sim \mathcal{N}\big( -\frac{\beta^4}{24}\,\E J^4 - \frac{v_1^2}{2},\; \frac{\beta^4}{8}(\E J^4 - 1) + v_1^2 \big)$ and $\zeta_2 \sim \mathcal{N}(0, v_2^2)$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

