[Lemma 44 (Regularity of the particle and mean-field drift) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumption~\ref{ass:core-target} and either kernel assumption, for
every \(T<\infty\),
\begin{equation}
    W_2(\mu_t,\mu_s)\le C_T|t-s|^{1/2},
    \qquad 0\le s,t\le T.
\end{equation}
Moreover,
\begin{align}
 &\|B(x,y)-B(x',y')\|
 +\|\nabla_1B(x,y)-\nabla_1B(x',y')\|
 \notag\\
 &\hspace{2cm}\le
 C_B(1+\min\{\|y\|,\|y'\|\})\left(\|x-x'\| + \|y-y'\|\right),

\end{align}
for all $x,x',y,y'\in\R^d$.

Consequently
\begin{equation}
 \sup_{x\in\R^d}
 \left\{
   \|v_{\mu_t}(x)-v_{\mu_s}(x)\|
   +\|\nabla_xv_{\mu_t}(x)-\nabla_xv_{\mu_s}(x)\|
 \right\}
 \le C_T|t-s|^{1/2}.
\end{equation}
For every fixed \(N\), the configuration-space drifts in
\eqref{eq:particle-FP-JN} and \eqref{eq:product-FP-JN} therefore belong to
\[
 C_{\mathrm{loc}}^{\alpha/2,\,1+\alpha}
 \bigl((0,T]\times(\R^d)^N;(\R^d)^N\bigr),
 \qquad 0<\alpha<1,
\]
and have at most linear growth.

[Theorem 3 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] Assume $\theta < 1/2$. Then, as $n \to \infty$, the following results hold:

\begin{itemize}
\item[(i)] (Almost sure convergence of empirical measures)  
\begin{equation}

\displaystyle\lim_{n\to\infty}\displaystyle\frac{1}{\log n}\sum_{j=1}^n\frac{1}{j}\left(\mathbb{I}\left\{\sqrt{j}\hat{N}_j \le x \right\},\mathbb{I}\left\{\sqrt{j}\hat{M}_j \le y \right\}  \right) = G (x,y) \quad \text{almost surely,}
\end{equation}
where $\mathbb{I}\{\cdot\}$ denotes the indicator function of events and $G(x,y)$ is the distribution function of a bivariate normal vector $(X, Y)$ with mean and covariance matrix
\begin{equation}

\mathbb{E}[(X,Y)] = (0,0), \qquad
\mathbb{V}[(X,Y)] = \sigma^2_{a,\theta} \begin{pmatrix}
1 & -1 \\
-1 & 1
\end{pmatrix},
\end{equation}
respectively.
\item[(ii)] (Almost sure convergence of moments)  
For all integers $m \geq 1$, we have
\begin{equation}

\frac{1}{\log n} \sum_{j=1}^n j^{m-1} \left( \hat{N}_j^{2m}, \hat{M}_j^{2m} \right) \longrightarrow \frac{\sigma_{a,\theta}^{2m}(2m)!}{2^m m!} (1,1) \quad \text{almost surely.}
\end{equation}

\item[(iii)] (Law of the iterated logarithm)  
\begin{equation}

\limsup_{n \to \infty} \pm \frac{ \sqrt{n} (\hat{N}_n, \hat{M}_n) }{ \sqrt{2 \log \log n} } = \sigma_{a,\theta} (1,1) \quad \text{almost surely.}
\end{equation}

\item[(iv)] (Asymptotic behavior of the average difference process)  
We have the almost sure convergence
\[
\lim_{n \to \infty} \frac{C_n}{n} = \frac{a}{1 - \theta} - \frac{1}{2},
\]
and the following central limit theorem:
\begin{equation}

\sqrt{n} \left( \frac{C_n}{n} - \left( \frac{a}{1 - \theta} - \frac{1}{2} \right) \right) \xrightarrow{d} \mathcal{N} \left( 0, \frac{8 \sigma^2_{a,\theta}}{3(2 - \theta)} \right).
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] We say an infinite-volume measure $\nu$ on $\mathbb{R}^{V}$ is \emph{regular} (with respect to $\rho$) if there exist $a, B > 0$ such that for any finite $\Lambda \subset V$ and any $\psi \in \mathbb{R}^{\Lambda}$,
    \begin{equation}

        \mathrm{d} \nu[\varphi|_{\Lambda} = \psi] \leq e^{B} \mathrm{d} \nu_{\Lambda, 0, \rho_{a}}^{0}[\psi].
