[Thm moment theorem 1 of arXiv:2505.11700, 'Distribution of the cokernels of determinantal row-sparse matrices'] Let $G$ be a finite abelian group. Assume that a sequence $(k_n)_{n=1}^{\infty}$ satisfies the following:
\begin{enumerate}
    \item $\gcd(|G|, k_n)=1$ for all sufficiently large $n$;
    \item for every $\epsilon>0$, $k_n < n^{\epsilon}$ for all sufficiently large $n$;
    \item if $|G|$ is even, then for every $\delta>0$, $\delta \log\log n < k_n$ for all sufficiently large $n$.
\end{enumerate}
Then 
\begin{equation}

\lim_{n \to \infty} \mathbb{E}(\#\mathrm{Sur}(\mathrm{cok}(A_n), G)) = 1.    
\end{equation}

[Defn def:HTD of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] Given $\sigma\in\mathbb{R}^{d}$ and $r_{\star}\le d$, define
\[
\sigma_{\mathrm{head}}\in\operatorname*{arg\,min}_{\normzero{\tilde{\sigma}}\ler_{\star}}\normone{\sigma-\tilde{\sigma}},\quad\sigma_{\mathrm{tail}}:=\sigma-\sigma_{\mathrm{head}},
\]
and set\begin{subequations}
\begin{align}
\mathsf{H} & :=\normtwo{\sigma_{\mathrm{head}}},\\
\mathsf{T} & :=\max\left\{ \frac{\normone{\sigma_{\mathrm{tail}}}}{\sqrt{r_{\star}}},\sqrt{r_{\star}}\norminf{\sigma_{\mathrm{tail}}}\right\} ,\\
\mathsf{D} & :=\frac{\bigl(\normone{\sigma_{\mathrm{tail}}}-\normone{\sigma_{\mathrm{head}}}\bigr)_{+}}{\sqrt{r_{\star}}}.
\end{align}
\end{subequations}

[Lemma 12 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3}, \ref{PEeqAssum-2.4} and \eqref{PETNs-3.01} hold. Then the family $\{p_{\tau,t}\}_{t\geq \tau}$ has the following properties: 

		$(i)$ $\{p_{\tau,t}\}_{t\geq \tau}$ satisfies the Feller property, i.e., for any $t\geq \tau$, if $\phi\in C_b({H})$, the map $p_{\tau,t}\phi$ is bounded and continuous on $\mathcal H$ endowed with the relative $H$-topology;

	$(ii)$ the family $\{v(t,\tau,\zeta): t\geq \tau, \zeta\in\mathcal H\}$ is Markov; in particular, $p_{\tau,t}=p_{\tau,r}p_{r,t}$ for any $\tau\leq  r \leq t$.

[Thm 3 of arXiv:2609.02040, '\Large Quantum Landau Damping with Coulomb Repulsion in the Whole Space'] Let $f_0(t,x,v)$ be the solution of the linearized Vlasov equation with initial data $f_0^{\init}$. Let $\rho_0(t,x)$ be the corresponding density. Let $f_0^\circ$ and $\rho_0^\circ$ be defined as in Theorem~\ref{thm:Green_functions}. Then 
		\begin{equation*} 
			\rho_0 = \Gosc_{0,+} \star_{t,x} \rho_0^\circ + \Gosc_{0,-} \star_{t,x} \rho_0^\circ + \Gr_0 \star_{t,x} \rho_0^\circ\, ,
		\end{equation*}
		where $\Gosc_{0,\pm}$ and $\Gr_0$ have the same structure as $\Gosc_{\h,\pm}$ and $\Gr_\h$ and satisfy the same bounds.
		Moreover,
		\begin{equation*}
			\n{\lambda_{\h,\pm}(k) - \lambda_{0,\pm}(k)} \lesssim \n{k}^4 h^2,
		\end{equation*}
		\begin{equation*}
			\n{a_{\h,\pm} - a_{0,\pm}} \lesssim \n{k}^4 h^2,
		\end{equation*}
		and 
		\begin{equation*}
			\n{\hatGr_\h(t,k) - \hatGr_0(t,k)} \lesssim \lt( {|k|^3 \over \langle k \rangle^4} \rt) e^{- \sigma \n{k} t} \min(1,h|k|)^2 .
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn type of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{G}$ be a foliation on $\mathbb{T}^2$. We define the \textbf{type} of $\mathcal{G}$ as follows:
\begin{enumerate}
    \item If $\mathcal{G}$ has no Reeb annuli,
        \begin{enumerate}
            \item If $\mathcal{G}$ has no $\sharp$ nor $\flat$ annuli, we say that it is of type $\natural$. Otherwise,
            \item If $\mathcal{G}$ has only $\sharp$ but no $\flat$ annuli, we say that it is of type $\sharp$,
            \item If $\mathcal{G}$ has only $\flat$ annuli but no $\sharp$ annuli, we say that it is of type $\flat$,
            \item Otherwise, $\mathcal{G}$ has both $\sharp$ and $\flat$ annuli, and we say that it is of type $\dagger$.
        \end{enumerate}
    \item If $\mathcal{G}$ has Reeb annuli,
        \begin{enumerate}
            \item If all leaves which spiral toward the right have the same slope, and all leaves which spiral toward the left have the same slope, then we say that it is of type $\aleph$.
            \item If the previous condition fails, we say that $\mathcal{G}$ is not of an admissible type.
        \end{enumerate}
\end{enumerate}
Besides the last case, we call these types \textbf{admissible}.

[Lemma 16 of arXiv:2609.03803, 'List-distance consistent vertices in trees are confined to a path'] Let $G=SP(w;1,\ell_2,\dots,\ell_k)$ with $k\ge4$ and $\ell_k\ge3$, suppose
$\ldc(G)=\lceil \ell_k/2\rceil+2$, let $c$ be an optimal labeling and adopt the
notation of \eqref{eq:B2}. Then
\begin{enumerate}
\item[\textup{(i)}] $\lceil \ell_{i_1}/2\rceil=\lceil \ell_k/2\rceil$ and
$m\in\{\ell_{i_1}+1,\ \ell_{i_1}+2\}$;
\item[\textup{(ii)}] $\Ntwo_t\le t+2$ for every $t$ with $1\le t\le \ell_{i_1}-1$.
\end{enumerate}

[Lem lemma:subordinadoNblack of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Fix $r\geq 0$. Under $\mathbf{N}_{x,r}$ and outside of a negligible set, the  convergence 
\begin{equation}
    A_t(\rho,\overline{W})= \lim_{k\to \infty} \frac{1}{\varepsilon'_k}  \int_0^t {\mathrm{d}} s \int_{r}^{\infty} {\mathrm{d}} z \,  \mathbbm{1}_{\{ \tau_z(\overline{W}_s ) < H(\rho_s) < \tau_z(\overline{W}_s) + \varepsilon_k^\prime \}}
\end{equation}
 holds  uniformly in compacts intervals. In particular, the process $(A_t)_{t \geq 0}$ is continuous and non-decreasing. Furthermore, the support of the measure ${\mathrm{d}} A$ coincides with the  complement of the constancy intervals of the process $\widehat{\Lambda}$.

[Thm 8 of arXiv:2506.18834, '\large\bf On the random-time and finite-time ruin probability for widely dependent claim s'] In a nonstandard renewal risk model, let $Y_i,i\ge1$ be ENUOD random variables with dominating coefficient $M_G$,
and let $Z_i,i\ge1$ be WLOD random variables with dominating coefficients $g_{L,H}(n),n\ge1$ satisfying
\begin{eqnarray}
g_{L,H}(n)=o(n^{b})\ \ \ \ \ \ \text{for some}\ b>0,\ \ \ \text{as}\ \ \ n\to\infty.
\end{eqnarray}
If $G\in\mathcal{C}$ and
\begin{eqnarray}
P(\tau>x)=o\big(\overline{G}(x)\big),
\end{eqnarray}
then $\max\{E\tau,EN(\tau)\}<\infty$ and (\ref{106}) holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_single_loop of arXiv:2605.06887, 'Law of large numbers for activated random walk on villages'] Given $n \in \mathbb{N}_+$ and an input jump odometer configuration $M = \left(M_x\right)_{x \in V} \in \mathbb{N}_0^{V}$ for $x \in V$, we define  $\Phi^{(n)}(M)$ as follows:

\begin{itemize} 

\item[(Inbound)] Calculate the number of particles that arrived to the airport of village $x \in V$:

\begin{equation}
I_x = \lfloor  \nu_x n  \rfloor + \sum_{y \in V} \sum_{j=1}^{M_y} \mathbb{1}\{\zeta_{j,y} = x\} 
\end{equation}

\item[(Active houses)] Distribute the particles arriving to the airport of village $x$ among the houses in village $x$ using the taxi tickets. Denote by $\mathcal{A}_x$ the set of houses in village $x$ in which at least one active particle arrived, and let $A_x$ denote the number of such houses:
\begin{equation}
   \mathcal{A}_x:= \left\{ i \in [n] \,: \; \exists \, j \in [I_x] \,: \, \gamma_{j, x} = i \, \right\}, \qquad A_x:= |\mathcal{A}_x|
\end{equation}
\item[(Quiet houses)] Let $\sigma_{x,i}=1$ if the house $(x,i)$ initially had a sleepy particle and $\sigma_{x,i}=0$ otherwise.
Denote by $Q_x$ the number of houses in village $x$ 
in which there was an initial sleepy particle, but no active particle arrived there:
\begin{equation}
   Q_x:= \sum_{i=1}^n \mathbb{1}\{ \,  \sigma_{x,i}=1, \; \forall \, j \in [I_x] \,: \, \gamma_{j, x} \neq i \, \} 
\end{equation}

\item[(Jump/Sleep)] If $i \in \mathcal{A}_x$, i.e., if $(x,i)$ is an active house of village $x$, let us define the $\mathbb{N}_+$-valued random variable
\begin{equation} T_{x,i}=\sigma_{x,i}+\sum_{j=1}^{I_x} \mathbb{1}\{\gamma_{j,x} =i \}. 
\end{equation}
Thus $ T_{x,i}$ is total number of active particles that ever entered this house (plus one in case they woke up a sleepy particle there).  Let
\begin{equation}
N_{x,i}=\min\left\{ \, K \in \mathbb{N}_0 \, : \, \sum_{j=1}^K \kappa_{j,(x,i)} = T_{x,i}-1 
\right\}
\end{equation} 
denote the number of landlord notices revealed until $T_{x,i}-1$ particles jumped away from house $(x,i)$.  Thus, if $ \kappa_{N_{x,i}+1,(x,i)}=1$ then the last active particle in house $(x,i)$ jumps, but if  $ \kappa_{N_{x,i}+1,(x,i)}=0$ then $(x,i)$ will have a sleepy particle
in the final stable configuration. Let 
\begin{equation}
J_x=\sum_{i \in \mathcal{A}_x} \kappa_{N_{x,i}+1,(x,i)}
\end{equation} denote the number of active houses in village $x$ from which all particles jumped away (these houses will be empty in the final stable configuration).

\item[(Outbound)] 
Now we are ready to define $\Phi^{(n)}(M) \in \mathbb{N}_0^V$ by writing a formula for the number $\Phi^{(n)}(M)_x$ of particles that jumped from village $x$: we just have to add the number $I_x$ of incomers to the number $\lfloor \sigma_x n  \rfloor$ of particles who were initially there and subtract from it the number $Q_x+A_x-J_x$ of particles who stayed:
\begin{equation}  \Phi^{(n)}(M)_x = \lfloor \sigma_x n \rfloor -Q_x +I_x - A_x + J_x. 
\end{equation}
\item[(Net income)] Let us define the $\mathbb{Z}^V$-valued random variable $S^{(n)}(M)$ by 
  \begin{equation}
      S^{(n)}(M)_x := - M_x + \lfloor \sigma_x n \rfloor + I_x, \qquad x \in V. 
  \end{equation}
\end{itemize} 
For any $m=(m_x)_{x \in V} \in \mathbb{R}_+^V$, let 
$\lfloor m \rfloor := (\lfloor m_x \rfloor)_{x \in V} \in \mathbb{N}_0^V$.
Let us define the scaled random functions
  $\phi^{(n)}: \mathbb{R}_+^{V} \to \mathbb{R}_+^V$ 
  and  $s^{(n)}: \mathbb{R}_+^{V} \to \mathbb{R}^V$
  by
\begin{equation} 
\phi^{(n)}(m):=\frac{1}{n}\Phi^{(n)}(\lfloor n m \rfloor), 
\qquad
s^{(n)}(m):=\frac{1}{n}S^{(n)}(\lfloor n m \rfloor). 
\end{equation}

