				&=\sum_{k=0}^{n-1}\Bigl(\hat{\mathbb{E}}\Bigl[v^Z_n(\frac{k}{n},S_{n,n-k})\Bigr]-\hat{\mathbb{E}}\Bigl[v^Z_n(\frac{k+1}{n},S_{n,n-k-1})\Bigr]\Bigr)\\
