[Theorem 23 (Corollary 20.5 in \cite{Bhattacharya2010}) of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Let $\bb Y_1,...,\bb Y_n$ be i.i.d random vectors with values in $\R ^2$ and law $Q$. Suppose that $\E [\bb Y_1]=0$, $\E [\|\bb Y_1\| ^4]<\8 $ and that the characteristic function $\hat{Q}$ of $Q$ satisfies  
	\begin{equation*}
		\limsup_{\|t \| \to \8}|\hat Q (t)|<1 .
	\end{equation*}	
	Let $\Sigma$ be the covariance matrix of $\bb Y_1$ and 
	\begin{equation}
		h(\bb x)= (2\pi )^{-1}(\det \Sigma)^{-1\slash 2}e^{-\langle \bb x,\Sigma^{-1} \bb x\rangle }.
	\end{equation}
	Let $Q_n$ be the law of $n ^{-1\slash 2}(\bb Y_1+...+\bb Y_n)$.
	Then
	\begin{equation}
		\sup _{C\in \mathcal{C}}\left | Q_n (C)-H (C)- H_2 (C)\right |=o(n^{-1}), 
	\end{equation}
	where $\mathcal{C}$

	is the family of convex sets $C \subset \R^2$;
	$H$ is the measure with density $h $, $H_2$ is the measure with density 
	$n^{-1\slash 2}P_1h +n^{-1}P_2h  $ and $P_1, P_2$ are polynomials depending only on $Q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn eq:gibbs_potts of arXiv:2609.02682, 'LDP for tensor forms'] With $N_n(Q_n,\phi,{{\bf X}})$ as in (equation hamiltoniandef of the paper) and $\beta \in \mathbb{R}$, define the Gibbs measure
\begin{align}
	\frac{d\mathbb{R}_{Q_n,{ \beta},\mu}}{d\mu^{\otimes n}}(\mathbf{X}):=\exp\Big(n\beta N_n(Q_n,\phi,{{\bf X}})-nZ_{Q_n}(\beta,\mu)\Big),
\end{align}
where \begin{align}
    Z_{Q_n}(\beta,\mu):=\frac{1}{n}\log \mathbb{E}_{\mu^{\otimes n}} \exp\Big(n \beta N_n(Q_n,\phi,{{\bf X}})\Big)
\end{align}
is the scaled log normalization constant.

[Lemma 24 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $A \xrightarrow{\alpha} D \xrightarrow{\beta} C \xrightarrow{h} A[1]$ be a distinguished triangle in the derived category $\mathcal{D}$ of an abelian category $\mathcal{A}$. Let $n \in \mathbb{Z}$ and suppose:
       	\begin{enumerate}
       		\item $\mathcal{H}^i(A) = 0$ for all $i \le n-1$ (hence $A \in \mathcal{D}^{\ge n}$);
       		\item The induced morphism on cohomology $h^{n-1} : \mathcal{H}^{n-1}(C) \longrightarrow \mathcal{H}^{n}(A)$ is zero, and the morphism $h^n:\mathcal{H}^{n}(C) \longrightarrow \mathcal{H}^{n+1}(A)$ is an isomorphism;
       		\item $\mathcal{H}^i(D) = 0$ for all $i > n$ (hence $D \in \mathcal{D}^{\le n}$).
       	\end{enumerate}
       	Then there is an isomorphism in the derived category
       	\begin{align*}
         D \simeq \tau_{\le n}A \;\oplus\; \tau_{\le n-1}C .
       \end{align*}
       	In particular $\tau_{\le n}A \simeq \mathcal{H}^n(A)[-n]$, so $D \simeq \mathcal{H}^n(A)[-n] \oplus \tau_{\le n-1}C.$

[Lem 5 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $p \in (0,1)$ and $\nu > 0$, and suppose that the two-point variable $Y$ with law $p\,\delta_{(1-p)\nu} + (1-p)\,\delta_{-p\nu}$ belongs to $\SE(\sigma^2,\alpha)$. Then
\begin{align}
    \nu \le \sigma\sqrt{\frac{2\beta_p}{1 - 2p}}\ \vee\ 2\alpha\,|\beta_p|,

\end{align}
where at $p = 1/2$ the first entry is interpreted as its limit $2\sigma$.

