[Definition 13 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] For $0<\delta<\eps$, define the {\em normalization factor} as
 \begin{equation*}
    \bc^\delta(\eps):=\phi_\delta\big[\mathcal A_{\frac1{2\eps^2}\one_{B_\eps(0)}}(\calL)\,\big|\,\calL_{\{0\},\eps}^{\rm odd}=\emptyset\big].
    \end{equation*}

[Lemma 16 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $p\in[1,\infty)$, $n\in\N$ and $\f\in\M_p$ be arbitrary. Then
\begin{equation*}
    2^{n(p-1)/p}\cdot\pnp{\f}\geq\sum_{u\in2^n}\pnp{\f\uhr_{u\appinf}}.
\end{equation*}

[Proposition 11 of arXiv:2604.19220, 'Split merge dynamics for expanding intervals and point processes on the real line.'] If  $\forall (n,k)\in I \; p_{n,k} = p \in (0,1), $ $ a_{n,0}= - \frac{n+1}{2},  $ and $ a_{n,n+1}=  \frac{n+1}{2} $ then $ \forall k \in \NN,$
\begin{equation}

\alpha_{n,k+1} = \alpha_{n,k} + \frac{1}{2p} + o \left ( \frac{1}{n+1} \right )
\end{equation}
and 
\begin{equation}

\alpha_{n,n -k +1 } = \alpha_{n,n-k} + \frac{1}{2(1-p)} + o \left ( \frac{1}{n+1} \right ).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:pLMagnusvectorfields of arXiv:2411.06827, 'The Exponential Lie Series and a Chen--Strichartz Formula for L{\'e}vy Processes'] The renormalised vector field $V_{i^{(n)}}$ is the $n$-th component of the pre-Lie Magnus expansion of {$V_i$}:
\begin{equation}

	{V_{i^{(n)}}=\Omega_n^{\triangleright  }(V_i).}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

