body:
[Prop GenDirFI-prop of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] For any $\zeta\in \mathcal{P}_{+}(\ensuremath{\mathbb{Z}})$, the generalised Dirichlet form~(equation def:genDirichlet of the paper) and the generalised Fisher information~(equation def:genFisher of the paper) with respect to $\zeta$  satisfy the following.
    \begin{enumerate}
        \item Continuity: The maps $(\zeta,f)\mapsto \mathscr{E}_\zeta(f)$ and $(\zeta,\varphi)\mapsto \mathscr{R}_\zeta(\varphi)$ are continuous on $\mathcal{P}_+(\ensuremath{\mathbb{Z}})\times \ensuremath{\mathbb{R}}^{|\ensuremath{\mathbb{Z}}|}$ and $\{(\zeta,\varphi) \,:\,\zeta\in \mathcal{P}_+(\ensuremath{\mathbb{Z}}), \varphi\in  \mathcal D_\zeta(\ensuremath{\mathbb{Z}})\}$ respectively. 

        \item Non-negativity: $\mathscr{E}_\zeta(f),\mathscr{R}_\zeta(\varphi)\geq 0$ with equality if and only if $f \in \left\langle {\mathbf 1} \right\rangle$ and $\varphi=\1$ respectively.
        \item Convexity: $\mathscr{E}_\zeta(\cdot)$ and $\mathscr{R}_\zeta(\cdot)$ are convex on their domains of definition.
        \item Connection: Let $f\in\ensuremath{\mathbb{R}}^{|\ensuremath{\mathbb{Z}}|}$ with $\mathbb{E}_\zeta[f]=0$. Then, for all $\delta \in \ensuremath{\mathbb{R}}$ with $|\delta| \leq \frac12 \|f\|_\infty^{-1}$, we have $\1+ \delta f \in \mathcal D_\zeta(\ensuremath{\mathbb{Z}})$ and
        \begin{equation}
            \mathscr{R}_\zeta(\1+ \delta f) = \delta^2 \bigl(\mathscr{E}_\zeta(f) + \delta R \bigr),
        \end{equation}
        where the remainder term satisfies $|R| \leq 3 \|M\|_\infty |\ensuremath{\mathbb{Z}}| \|f\|_\infty^3$.  
    \end{enumerate}

[Lemma lema_orig_teska of arXiv:2607.13302, 'Extending an Order-Statistic Characterization of the Exponential Distribution'] For $1 \leq j < k \leq n$ and any $r \geq 1$ it holds that
    \begin{align}
        &\frac{1}{(k-1)!}\sum_{i=0}^{r+1} (i+k-1)! \binom{n-k}{i} \genfrac{\{}{\}}{0pt}{}{k+r+1}{i+k} \nonumber \\
        & \qquad = \frac{1}{(k-j-1)!} \sum_{i=0}^{r+1} (k-j-1+i)! \binom{n-k+j}{i} \sum_{l=k-2}^{k+r-1} \genfrac{\{}{\}}{0pt}{}{l-j+2}{k-j+i} \nonumber \\
        & \qquad \qquad \qquad \qquad \qquad \times \sum_{s=0}^{k+r-l-1} \binom{n-k}{s} \frac{(s+j-1)!}{(j-1)!} \genfrac{\{}{\}}{0pt}{}{j+k+r-l-1}{s+j}
    \end{align}

[Definition 5 of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] The \textbf{$AB$-transition entrance distribution} in \(\bar{B} \cap (B + 1)\) is defined as:  
\begin{equation*}
    \eta^+_B(\d x) = \frac{1}{v_B^+}\rho(x)\overleftarrow{\mathcal{L}}\overleftarrow{q}(x)\d x, \quad x \in \bar{B} \cap (B + 1),
\end{equation*}
and analogously, the \textbf{$BA$-transition entrance distribution} on \(\bar{A} \cap (A + 1)\):  
\begin{equation}
    \eta^+_A(\d x) = \frac{1}{v_A^+}\rho(x)\overleftarrow{\mathcal{L}}\overleftarrow{q}(x)\d x,
\end{equation}
where \(v_A^+\) and \(v_B^+\) are normalizing constants such that these define probability measures.

[Lemma restr-right-Quillen of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\alpha\colon G\to G'$ be a homomorphism of compact Lie groups. Then
    \[
        \alpha_!\colon\cat{$\bm{G}$-$\textbf{\textup{L}}$-Top}\rightleftarrows\cat{$\bm{G'}$-$\textbf{\textup{L}}$-Top}
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 \alpha^*
    \]
    is a Quillen adjunction with homotopical right adjoint.
    \begin{proof}
        By [barrero2021]*{Lemma~3.7(vii)}, the functor $\alpha^*$ is homotopical. On the other hand, Example~(ex:graph-restr-rQ of the paper) shows that if $H$ is any compact Lie group, then $\alpha^*\colon\cat{$\bm{(H\times G')}$-Top}\to \cat{$\bm{(H\times G)}$-Top}$ is right Quillen for the $\mathcal G_{H,G}$- and $\mathcal G_{H,G'}$-model structures; applying this for $H={\textup{O}}(V)$, we see that $\alpha^*$ preserves \emph{level} fibrations. Similarly, if $f\colon X\to Y$ is even a $G'$-global fibration, then this shows that
        \[
            \begin{tikzcd}
                \alpha^*X(V)\arrow[r]\arrow[d,"\alpha^*f(V)"'] & \alpha^*X(V\oplus W)\arrow[d,"\alpha^*f(V\oplus W)"]\\
                \alpha^*Y(V)\arrow[r] & \alpha^*Y(V\oplus W)
            \end{tikzcd}
        \]
        is a homotopy pullback for all $H$-representations $V,W$ such that $V$ is faithful, i.e.\ $\alpha^*f$ is a $G'$-global fibration.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

