body:
[Theorem thm:smooth of arXiv:2608.30166, 'Square Functions and Rectifiability\\ under Monotone Transformations of the Density'] Let $\mu$ be an $n$-AD-regular measure in $\mathbb{R}^d$ with constant $c_0$ and
$\mu(\mathbb{R}^d)=\infty$, let $\phi$ be as above, and let $F\colon(0,\infty)\to\mathbb{R}$ be
a Borel function and bi-Lipschitz on $J_\phi$ with constant $\lambda_\phi$. The
following are equivalent:
\begin{itemize}
\item[(a)] $\mu$ is uniformly $n$-rectifiable.
\item[(b)] There exists a constant $c$ such that for any ball $B(x_0,R)$ centered at
$\operatorname{supp}(\mu)$,
\begin{equation}
\int_0^R\!\!\int_{x\in B(x_0,R)}|\Delta^F_{\mu,\phi}(x,t)|^2\,d\mu(x)\,\frac{dt}{t}
\;\le\;c\,R^n.
\end{equation}
\end{itemize}
If in addition $F\in C^1(0,\infty)$, then (a) and (b) are also equivalent to (c).
\begin{itemize}
\item[(c)] There exists a constant $c$ such that for any ball $B(x_0,R)$ centered at
$\operatorname{supp}(\mu)$,
\begin{equation}
\int_0^R\!\!\int_{x\in B(x_0,R)}|\widetilde\Delta^F_{\mu,\phi}(x,t)|^2\,d\mu(x)\,\frac{dt}{t}
\;\le\;c\,R^n.
\end{equation}
\end{itemize}
The Carleson constants in (b) and (c) differ from those of the corresponding conditions
for $\Delta_{\mu,\phi}$ and $\widetilde\Delta_{\mu,\phi}$ by at most a factor
$\lambda_\phi^2$. For $F=\log$ one can take $\lambda_\phi=\max\bigl(C_\phi
c_0,\,c_0/\phi(1)\bigr)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:poisson-collisions-proof of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] There is a universal constant $C<\infty$ such that, conditionally on
    $\mathbf P(t)$,
    \begin{equation}
            d_{\rm TV}\left(\mathcal L(C_n(t)\mid\mathbf P(t)),\operatorname{Poisson}(\mu_n(t))\right)
            \le Cn^3\left[S_2(t)^2+S_3(t)\right].
    \end{equation}

[Theorem thm:dist of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Assume the conditions of Theorem (thm:loc_lim of the paper).
\begin{itemize}
    \item[1.] If $\eta=1$, 
    \begin{align*}
        \limsup_{n\to \infty}\Prob{d_{G_n}(o_1,o_2)<\infty}=0.
    \end{align*}
    \item[2.] If $\eta<1$, then there is $j \in [k]$ and a constant $K^*>0$ such that
    \begin{align*}
        \liminf_{n \to \infty}\CProb{d_{G_n}(o_1,o_2)<K^* \log n}{o_1,o_2\in \mathcal N^{(j)}}>0.
    \end{align*}
    In particular, $\liminf_{n \to \infty}\Prob{d_{G_n}(o_1,o_2)<K^* \log n}>0$.
    \item[3.] If $\eta<1$, and additionally, $(i,j)$ is $\rm GOOD$ for all $i,j \in [k]$, then there is $j\in [k]$ and a constant $K_*$ such that
    \begin{align*}
        \liminf_{n \to \infty}\CProb{d_{G_n}(o_1,o_2)>K_* \log n}{o_1,o_2\in \mathcal N^{(j)}}>0.
    \end{align*}
    In particular, $\liminf_{n \to \infty}\Prob{d_{G_n}(o_1,o_2)>K_* \log n}>0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition GBSDE-propo1 of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] Let $(\xi_T,f,A)$ be a set of data satisfying assumption \textbf{(H)}. Let $(Y,M)$ be a solution of the GBSDE (equation GBSDE.Indp.y of the paper) associated with $(\xi_T,f,A)$. Then there exists a constant $\mathfrak{C}_{\beta}>0$ such that
	\begin{equation*}
		\begin{split}
			&\mathbb{E}\left[\sup_{0\leq t\leq T}\mathcal{E}(\beta A)_t |Y_t|^2\right]+\mathbb{E}\left[ \int_{0}^{T}\mathcal{E}(\beta A)_s |Y_{s-}|^2 dA_s\right] +\mathbb{E}\left[\int_{0}^{T}{\mathcal{E}(\beta A)_s}d[M]_s\right] \\ 
			& \leq \mathfrak{C}_{\beta} \left(  \mathbb{E}\left[\mathcal{E}(\beta A)_T |\xi_T|^2\right] +\mathbb{E}\left[\int_{0}^{T}\mathcal{E}(\beta A)_{s} |\mathfrak{f}(s)|^2 dA_s\right]\right).
