[Lemma 15 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $\tfrac{2n}{n+2}< p<\infty$.
    Assume that $|F|\in L^p_{\loc}(\Omega_T)$ and that $u\in  L^p_{\loc}(0,T;W^{1,p}_{\loc} (\Om;\mathbb{R}^N))$ is a weak solution to \eqref{p_eq}. 
    Moreover, assume that there exist a parabolic cylinder $Q_{2\rho}^\la=Q_{2\rho}^\la(z_0)=B_{2\rho}(x_0)\times I^\la_{2\rho}(t_0)\Subset\Om_T$ and an exponent $1<q\le p$ satisfying $2<\tfrac{q(n+2)}{n+p-q}$ such that
    \begin{equation}
    \biggl(\fiint_{Q_{2\rho}^\la} (|\na u|+|F|)^q \, dz\biggr)^\frac{1}{q} \le \lambda.
    \end{equation}
    Then $u\in L^\infty (I_{2\rho}(t_0);L^2(B_{2\rho}(x_0);\mathbb{R}^N))$.
    Moreover, there exists a constant $c=c(n,N,p,\nu,L)$ such that, for any $0<\rho<\rho_1<\rho_2< 2\rho$, we have
    \begin{equation}
	\begin{split}
			&\esssup_{t\in I^\la_{\rho_1}(t_0)}\la^{p-2}\fint_{B_{\rho_1}(x_0)}\frac{|u-u_{Q^\la_{\rho_1}(z_0)}|^2}{\rho_1^2}\,dx+\fiint_{ Q^\la_{\rho_1}(z_0)}|\na u|^p\,dz\\
			&\qquad\le c\fiint_{Q^\la_{\rho_2}(z_0)} \frac{|u-u_{Q^\la_{\rho_2}(z_0)}|^p}{(\rho_2-\rho_1)^p}\,dz + c\la^{p-2}\fiint_{Q^\la_{\rho_2}(z_0)} \frac{|u-u_{Q^\la_{\rho_2}(z_0)}|^2}{(\rho_2-\rho_1)^2}\,dz  \\
            &\qquad\qquad+c\fiint_{Q^\la_{\rho_2}(z_0)}  |F|^p  \,dz.
	\end{split}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

