[Definition def:Muckenhoupt of arXiv:2505.14012, 'Ergodicity for stochastic neural field equations'] The weight $\rho\in L^1_{\operatorname{loc}}(\mathbb{R}^d)$ is called an \emph{$A_2$-Muckenhoupt weight}, denoted $\rho\in A_2$, if
\begin{align*}
[\rho]_{A_2}:=\sup_{Q\subset\mathbb{R}^d,\;Q\;\textup{cube}}\left(\frac{1}{|Q|}\int_Q\rho(x)\, dx\right)\left(\frac{1}{|Q|}\int_Q   \rho(x)^{-1}\, dx\right)<\infty.
\end{align*}

[Theorem thm:results:LSI of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:LSI of the paper). Then the following properties are satisfied:
\begin{enumerate}
    \item The family of Gibbs measures $\{\theta^n\}_{n \geq 1}$ satisfies a uniform log-Sobolev inequality. That is, there exists $C_\theta \in (0, \infty)$ such that for all $n \in \ensuremath{\mathbb{N}}$, we have
    \begin{equation}

        \mathcal{H}(\Lambda | \theta^{n}) \leq 2 C_\theta \mathcal{I}(\Lambda | \theta^{n}), \quad \Lambda \in \mathcal{P}\big((\ensuremath{\mathbb{R}}^d)^{V_n}\big).
    \end{equation}
    \item  There exists $C_0  \in (0, \infty)$ such that for all $\nu \in \tilde{\mathcal{M}}_{2, d}$ satisfying \begin{equation}
    \int_{(\ensuremath{\mathbb{R}}^d)^{3}} \Big(|b(\mathbf{x})|^2 + \big|\nabla_{\mathbf{x}} \log \nu(\mathbf{x})\big|^2\Big) \nu(d\mathbf{x}) < \infty,

\end{equation}we have the following modified log-Sobolev inequality: \begin{equation}
        \mathbb{H}_2(\nu) - \mathbb H_2^* \leq C_0 \mathbb{I}_2(\nu),

    \end{equation}
   where $\mathbb H_\star$ is as defined in (equation eq:results:Hstar of the paper).
    \item If $\lambda \in \tilde{\mathcal{M}}_{2, d}$ and $(\mu, \gamma)$ is a linear growth solution to the $2$-MLFE on $[0, \infty)$, with initial condition $\lambda$, then there exists $c, C \in (0, \infty)$ such that the following inequality holds: 
        \begin{equation}

        \mathbb{H}_2(\mu_t) - \mathbb H_2^* \leq C \exp(-ct), \quad \text{for a.e. } t \geq 0.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

