[Lemma 19 (Dynamic master inequalities for cumulants) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ Wigner matrix satisfying Assumption~\ref{ass:momass}. For any fixed $p, n,S\in \N$ with $p\ge 3$ it holds that
\begin{equation}
\begin{split}
\Xi_t^{(p)}(n,S) \lesssim &\Xi_0^{(p)}(n,S) + \int_0^t \left(\Xi^{(p)}_s(n,S-1) +\frac{1}{N}\Xi^{(p)}_s(n+1,S+2)\right) \dif s\\
+&\int_0^s\left(\sum_{S'\le S} \frac{1}{N\eta^{S-S'+2}}\Xi^{(p)}_s(n-1,S') + \sum_{S'\le S-2} \frac{1}{\eta^{S-S'+1}}\Xi^{(p)}_s(n-2,S')\right)\dif s\\
+&\int_0^s\left(\sum_{S'\le S} \frac{1}{N\eta^{S-S'+2}}\Xi^{(p-1)}_s(n-1,S') + \sum_{S'\le S-2} \frac{1}{\eta^{S-S'+1}}\Xi^{(p-1)}_s(n-2,S')\right)\dif s,\\
\Theta_t^{(p)}(n,S) \lesssim &\Theta_0^{(p)}(n,S) + \int_0^t \left(\Theta^{(p)}_s(n,S-1) +\frac{1}{N}\Theta^{(p)}_s(n+1,S+2)\right) \dif s\\
+&\int_0^t \left(\frac{1}{N}\Theta_s^{(p-1)}(n-1,S) +\Theta_s^{(p-1)}(n-2,S-2)\right)\dif s,
\end{split}

\end{equation}
for any fixed $\xi>0$, uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$.

[Theorem Thm2 of arXiv:2411.18775, 'Limit Theorems for the Dynamical Foundation of the Fractional Brownian Motion and Related '] Fix any $t_0>0$. Under Assumptions~(asmp:hyp1 of the paper),~(asmp:coef new of the paper),~(asmp:m new of the paper),~(assmp:u0 new of the paper),~(assmp:coef2 of the paper), and Assumption~(assmp:m extra new of the paper)~(i) or  Assumption~(assmp:m extra new of the paper)~(ii) 
consider    a  process $(Z_t)_{t\in[0,t_0]}$,
\begin{align}
Z_t:=Z_t(A,H):=\sqrt{A}G^{(H)}_t, \qquad t\in[0,t_0],
\end{align}
where $G:\mathcal{H}\times [0,t_0]\times \Omega \rightarrow \mathbb{R}$ is assumed to be a measurable centered Gaussian field   independent of $A$ and $H$ and such that, for every $h\in \mathcal{H}$,   $(G^{(h)}_t)_{t\in[0,t_0]}$ has continuous paths and covariance function 
\begin{align*}
\mathop{\mathrm{Cov}}\nolimits(  G^{(h)}_t,G^{(h)}_s)=\left( \frac{2\sigma C^2_\beta C_\delta}{\gamma^2 }\right)\frac12\left(v_h(t)+v_h(s)-v_h(|t-s|)  \right).
\end{align*}
Then the processes $\left(X^N_t\right)_{t\in[0,t_0]}$ in   system~(equation final system of the paper), $N\in\mathbb{N}$, considered as $\left( \mathcal{X},\mathcal{B}(\mathcal{X}) \right)$-valued random elements,  converge as $N\to\infty$ to   $(Z_t)_{t\in[0,t_0]}$  in  distribution.

[Lemma 21 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] For every $\epsilon>0$, there exist $w>0$ and $K<\infty$ such that, for all
sufficiently large $s$,
\begin{equation*}
 \Pp\!\left(M_R(s)\ge w,\ H_s\le K\right)\ge1-\epsilon.
\end{equation*}

