\begin{align}
	 K \in \cK_{j} \quad \Leftrightarrow \quad \norm{K}_{\cW_j} \le C_{{\operatorname{RG}}} \tilde{\chi}_j^{3/2} \tilde{g}_j^3 r_j^{{\ka}}
\end{align}
and whenever $\norm{K_N}_{\cW_N} < \infty$,
\begin{align}
	| K_N (\Lambda, 0)  | & \le O_L (1) \norm{K_N}_{\cW_N}
	\\
	| K_N (\Lambda, \varphi) | & \le O_L (1) \tilde{g}_N^{-\frac{9}{4}} r_N^{ - {\ka} + {\kp}} \tilde{G}_N (\Lambda,  \varphi) e^{-\kappa L^{-dN} \norm{\varphi / h_{N,\varnothing}}_{\ell^2}^2 } \norm{K_N}_{\cW_N}  
\end{align}
where $\tilde{G}_N (\Lambda, \varphi)$ is as in [FSmap] and $\kappa >0$ is a constant (independent of any other parameter).

[Proposition prop:upper of arXiv:2607.06249, 'Extreme least singular values of Gaussian row submatrices and a phase retrieval stability '] Under the assumptions of Theorem (thm:general of the paper), for every fixed $\varepsilon>0$,
