[Theorem 2 of arXiv:2607.22438, 'A deterministic scalar reduction for the phase transition in two interacting urns'] For every \(\alpha>1\),
\begin{equation*}
 \widetilde p_\alpha=p_\alpha=p_{\mathrm{det}}(\alpha).
\end{equation*}
For polynomial reinforcements of integer degree \(m\ge 2\), the same conclusion holds with \(\alpha=m\), whenever the stochastic-approximation conclusions in Proposition~2.1 are available. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:limitL of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] For $m$ and $m_{*}$ defined by the equations (equation e91 of the paper) and (equation e127 of the paper) respectively, the following inequality holds
\begin{equation}
\limsup_{L \to \infty} \frac{1}{L^{2}} W_{H_{m}^{1}(\Lambda_{L})^{N} }(\mu_{m_{*},L }^{\otimes N}, \mu_{m,L}^{\otimes N} )^{2} \lesssim \lambda  |\ln m_{*}| \cdot \frac{1}{N}  . 
\end{equation}

[Prop 5 (Skorokhod representation theorem) of arXiv:2607.28078, '2607.28078'] \cite[Theorem 6.7]{CPM}
Let $E$ be a separable metric space, and let $\{\mu_n\}_{n \geq 1}$ be a sequence of probability measures on $E$ that converges weakly to a probability measure $\mu$. Then there exist a probability space $(\tilde{\Omega}, \tilde{\mathcal{F}}, \tilde{\mathbb{P}})$ and random variables $\tilde{X}_n, \tilde{X} : \tilde{\Omega} \to E$ such that
\begin{enumerate}
\item[$\rm(1)$] $\tilde{\mathcal{L}}_{\tilde{X}_n} = \mu_n$ and $\tilde{\mathcal{L}}_{\tilde{X}} = \mu$ under $\tilde{\mathbb{P}}$.
\item[$\rm(2)$] $\tilde{X}_n \to \tilde{X}$ $\tilde{\mathbb{P}}$-almost surely as $n \to \infty$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:tightness of arXiv:2411.18775, 'Limit Theorems for the Dynamical Foundation of the Fractional Brownian Motion and Related '] Fix $N_0$ sufficiently large such that  $\mathcal{A}_N\geq M$ for every $N\geq N_0$. Then, there is a constant $C>0$ such that for every $0\leq \epsilon\leq 1$, $N\geq N_0$ and $0\leq s\leq t\leq t_0$
\begin{align*}
&\mathbb{E}\left[|\widetilde X^N_t-	\widetilde X^N_s|^2\right] \\
&
\leq   C \Biggl(v(|t-s|) + \Bigl(\frac{1}{m^*_N}\int\limits_{(0,\infty)}\left[ \frac{\gamma}{y} {\1}_{\{0<y\leq 1\}}+\frac{\gamma^\epsilon}{y^{2-\epsilon}}  {\1}_{\{y> 1\}}\right] \mu_N(dy) \Bigr) \;|t-s|^{1+\epsilon} \Biggr)
\end{align*}

