[Proposition 9 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] For $\mu\in(0,1]$, the flow $S_t$ is continuous from $L_\mu^2(\IR^d)\cap\Gamma H^2(\IR^d)$ to itself. In particular, we have
\begin{equation}
\|S_tv_0\|_{L_{\mu}^2(\IR^d)\cap\Gamma H^\sigma(\IR^d)}\lesssim\|v_0\|_{L_{\mu}^2(\IR^d)\cap \Gamma H^\sigma(\IR^d)}
\end{equation}
for any $\sigma\in[1,2]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Risk stability of Polyak) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Let the Hessian be a positive trace-class operator and assume
\[
\bH=\diag(\lambda_1,\lambda_2,\ldots),
\qquad
\lambda_1=\lambda_{\max}\geq\lambda_2\geq\cdots>0,
\qquad
0\leq\rho<1,
\qquad
\sigma>0.
\]
Then Polyak momentum is risk stable if and only if
\begin{equation}

\eta
<
\frac{
2B(1-\rho^2)
}{
\lambda_{\max}\left[B(1-\rho)+(1+\rho)\right]
}
\end{equation}
and
\begin{equation}

\kappa_{\polyak}(\eta,\rho)
:=
\sum_{i\geq1}
\frac{
\eta\lambda_i(1+\rho)
}{
2B(1-\rho^2)
-
\eta\lambda_i\left[B(1-\rho)+(1+\rho)\right]
}
<1.
\end{equation}

[Conjecture conj:time of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] The chains $\mathbf{X}^{\textup{ord,lab}}$ and $\mathbf{X}^{\textup{ord,lab}}_{\textup{prod}}$ both exhibit cutoff around time
    \begin{equation}

        T \coloneqq n \log n \cdot \max\{1/q, 1/(2\gamma)\},
    \end{equation}
    where $\gamma$ is the spectral gap of the transition matrix $U$ of the single ball chain on $[d]$, and
    \begin{equation*}
        q \coloneqq \min \{1 - U(i,i) \colon i \in [d]\}.
    \end{equation*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma lem:upper-bound-c_L^d-regular of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Let $d \ge 3$. Then there exists a constant $\beta_d>0$, that depends only on~$d$, such that  

	\begin{equation}

		C_L^{ \text{\rm d-reg}}
		< \frac{\kappa_{L}^{\text{\rm d-reg}}}{M} ,
		\qquad \kappa_{L}^{\text{\rm d-reg}} := \frac{1}{2}(\beta_d)^L, 
		\qquad L=3, \dots, M.
	\end{equation}

[Lemma lem:disi of arXiv:2602.00853, 'Mixing times for the stochastic $p$-Laplace equation'] Let $r\geq 1$ be fixed.
Assume that there exists a unique invariant probability measure $\mu_\ast$ on $(H,\mathcal{B}(H))$ with finite absolute moment of order $r$ for the dual semigroup $(P^\ast_t)_{t\ge 0}$ on the space of probability measures on $(H,{\mathcal B}(H))$.
Then for any $x\in H$ and $0<s\leq t$
it follows that
\begin{equation}
\mathcal{W}_r(P^*_t\delta_x,P^*_t\mu_\ast)\leq \int_{H}
\int_{H}\mathcal{W}_r(P^*_s\delta_z,P^*_s\delta_y)P^*_{t-s}\delta_x(\mathrm{d} z)\mu_\ast(\mathrm{d} y).
\end{equation}
In particular, it follows that
\begin{equation}
\mathcal{W}_r(P^*_t\delta_x,\mu_\ast)=\mathcal{W}_r(P^*_t\delta_x,P^*_t\mu_\ast)
\leq \int_{H} \mathcal{W}_r(P^*_t\delta_x,P^*_t\delta_y)\mu_\ast(\mathrm{d} y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2603.28702, 'Distribution of the magnetization of the critical Ising model on sparse random graphs'] \begin{enumerate}
\item
The random variable $X_{\ell,n}$ has
\begin{align*}
&\E(X_{\ell,n})=(1+O(n^{-1}))\cdot\dfrac{1}{2}nd^\ell\ \ \text{and}\\ &\text{Var}(X_{\ell,n})=(1+O(n^{-1}))\cdot\dfrac{1}{2}nd^{2\ell}\dfrac{\ell^2}{d-1}\left(1+\gamma_\ell^{(2)}\right),
\end{align*}
where $\lim\limits_{\ell\to\infty}\gamma_\ell^{(2)}=0$.
\item 
Let $m$ be as in statement 4 of Proposition \ref{cyc-path-ER}. Then, under the planted measure $\PR_m^*$,
\begin{align*}
&\E_m^*(X_{\ell,n})=(1+O(n^{-1}))\cdot\dfrac{1}{2}nd^\ell\left(1+m^2n^{-2}\dfrac{\ell}{d-1}\left(1+\gamma_\ell^{(1)}\right)\right)\ \ \text{and}\\ &\text{Var}_m^*(X_{\ell,n})\sim\text{Var}(X_{\ell,n}),
\end{align*}
where $\lim\limits_{\ell\to\infty}\gamma_\ell^{(1)}=0$.
\end{enumerate}

[Lemma 14 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] For any $X_0\in M_F(\mathbb R)$ and $\lambda>0$,
	\begin{equation}
		\mathbb E_{X_0}(\exp(-\lambda L^x))=\exp\bigg(-\int V^\lambda(x-x_0)X_0(\d x_0) \bigg),
	\end{equation}
	where $V^\lambda$ is the unique bounded nonnegative distributional solution of
	\begin{equation}
		\frac{\Delta V^\lambda}{2}=(V^\lambda)^{1+\beta}-\lambda\delta_0
	\end{equation}
	such that $V^\lambda\in C(\mathbb R)\cap C^2(\mathbb R\setminus\{0\})$ and
	$V^\lambda(x)\to0$ as $|x|\to\infty$.

