[Proposition 19 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] If $X$ has bounded variation, then for every non-empty word $I = i_1\dots i_n$, $n\leq \kappa-1$:
    \[
K^{(I)}
=
\sum_{\pi \in NC(n)}
\left(
\prod_{(p,q) \in P(\pi)} (-1) \delta_{i_p,i_q}
\right)
K_{\,i_{U_1},\ldots,i_{U_r}},
\]
with the convention $K^{(\emptyset)} = K_\emptyset$ and for a non-empty word $J = j_1 \dots j_m$
\begin{equation}
K_{J}(s,t) =   (-1)^{m} \int_{s < u_1 < \dots < u_m <t} K(s, u_1)K(u_1, u_2) \dots K(u_{m-1}, u_{m})K(u_{m}, t) dX^{(j_1)}_{u_1}\dots dX^{(j_m)}_{u_m}.
\end{equation}

[Lemma 47 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta\in (0,1)$ and $b\geq v + 2\lambda + 2\log(2)\pi$.
Then
\begin{multline*}
\int_{D^{2}}
e^{-(b-v-2\lambda)^{2}/(2\log(2)/\pi + 2 G_{D}(z,w))}
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w
\\
\leq 
e^{-((2\pi\eta)\wedge 1)(b-v-2\lambda - 2\log(2)/\pi)}
(c_{\eta}\vert D\vert \diam(D)^{2\eta} +
\Vert 1_{D} \Vert_{H^{-\eta}(\C)}^{2}
),
\end{multline*}
where $\vert D\vert$ is the Lebesgue measure (area) of $D$,
and $c_{\eta}>0$ is a constant depending only on $\eta$.

