[Proposition 11 (Pathwise truncation identity) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Let $m<r$. Whenever both boundary words are defined on a sample path,
\begin{equation}
Z_t^{(m)}=\Pi_{r,m}(Z_t^{(r)}) \qquad (t\ge0),
\end{equation}
where $\Pi_{r,m}$ sends a length-$r$ word to its suffix of length $m$.

[Lemma lem.drift-bound of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] There exists $C<\infty$ such that, for $\mathbb{Q}$-a.e.\ $\omega$ and every $(m,h,\rho)$ in the admissible regime~(equation eq.admissible of the paper), the following holds. Suppose that $z=(z_1,\ldots,z_d)\in H^1_0(\square_M;\mathbb{R}^d)$ solves, componentwise in $\square_M$,
		\begin{equation}
			-\nabla\cdot(\mathbf{a}\nabla z_i)
			=2\lambda 3^{-m} e_1 \cdot(\mathbf{a}\nabla w_{i,M}-\bar{\mathbf{a}} e_i)-2\rho 3^{-3m}(w_{i,M}-x_i)+2\lambda(\mathbf{a} e_1) \cdot \nabla z_i-2\rho 3^{-2m}z_i\, .
		\end{equation}
		Then the drift integral satisfies
		\begin{equation}
			\begin{aligned}
			\left|\lambda\sum_{i=1}^d\Xint-_{\square_M} z_i\bigl((\mathbf{a}-\bar{\mathbf{a}})e_1\bigr)\cdot\nabla z_i\right|
			&\le \frac{1}{16}\left(\rho 3^{-2m}\|z\|_{\underline L^2(\square_M)}^2
			+\frac12\sum_{i=1}^d\Xint-_{\square_M}\nabla z_i\cdot\mathbf{a}\nabla z_i\right)\\
			&\quad+C \rho^2 3^{2h-2m} 3^{-2\beta_h M}\, .
			\end{aligned}
		\end{equation}

[Prop 12 of arXiv:2609.02576, 'Sharp estimates for the Jacobi and trigonometric Dunkl heat kernels'] The Opdam--Cherednik heat kernel satisfies the lower bound
	\begin{equation*}
		\hOC_t (x,y) \gtrsim H_t^0(x,y), 
	\end{equation*}
	uniformly in $t\geq 1$ and $x,y>0$.

