[Lemma lem:char. for ergodic of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},\mu,T)$ be a capacity preserving system. If $\mu$  is subadditive and continuous then the following three statements are equivalent:
	\begin{longlist}
		\item $\mu$ is ergodic;
		\item if $f\in B(\Omega,\mathcal{F})$  is $T$-invariant then $f$ is  constant $\mu$-a.s.;
		\item if $f:\Omega\to \mathbb{R}$ is  $\mathcal{F}$-measurable and  $T$-invariant $\mu$-a.s. then $f$ is  constant $\mu$-a.s.
	\end{longlist}
	Note that (iii) $\Rightarrow$ (ii) $\Rightarrow$ (i) does not need the continuity of $\mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] For any constant $\iota>0$
and any integer $k\ge \lfloor-\log_2\iota\rfloor$, let $\mathcal{H}^{\mathrm{aty}}_k(\iota)$ denote the collection of external fields such that \begin{align}
    \sum_{\gamma:\frac{S(\gamma)}{N^{7/4}}\in (2^{k-1},2^k]}\mu^{\pm}_{\Lambda_N,{\epsilon} h}(\gamma)\le e^{-2^{k}}.\nonumber
\end{align}

[Theorem 2 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$ with $\left\|f\right\|_{\Leb^\infty}\leq 1$, and $p\in [1,2]$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Poincare-type-Gaussian}}}(p)^k\Wop^{\geq k}(f),
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Poincare-type-Gaussian}}}(p) = C^{\text{\rm\ref{thm:high-order-Poincare-type-Boolean}}}(p) \gtrsim 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $(G^\bullet, G^\circ):  \Omega \times [0,1] \to V \times E$ and $(\mathbb{G}^{\bullet \bullet}, \mathbb{G}^{\circ \bullet}, \mathbb{G}^{\bullet \circ}) : \Omega \times [0, 1]^2 \to (V \otimes V ) \times (E \otimes V) \times (V \otimes E)$. Assume that for all $(s,u,t) \in [0,1]^3_\leq$, $(G^\bullet, \mathbb{G}^{\bullet \bullet})$ satisfies (equation eq:Chen_single_regularity of the paper) and $(G^\bullet, G^\circ, \mathbb{G}^{\bullet \circ}, \mathbb{G}^{\circ \bullet})$ satisfy (equation eq:chen_mixed of the paper). Let $p \geq 2$ and $\tilde{\gamma}_\bullet, \tilde{\gamma}_\circ \in (0,1)$ with $\tilde{\gamma}_\bullet, \tilde{\gamma}_\circ >1/p$. Assume further that  there exist constants $K_{ij}$, $i,j \in \{ \bullet, \circ\}$, such that for all $(s,t)$
    \begin{equs}
        \| G^i_{s,t}\|_{L_p}\leq  K_i |t-s|^{\tilde{\gamma}_i}, \qquad   
        \| \mathbb{G}^{i j }_{s,t}\|_{L_{p/2}}\leq  K_{ij} |t-s|^{\tilde{\gamma}_i+\tilde{\gamma}_j}
    \end{equs}
    for $i,j \in \{ \bullet, \circ\}$ with $(i,j) \neq (\circ, \circ)$. Then for any $\gamma_\bullet< \tilde{\gamma}_\bullet-1/p $, $\gamma_\circ< \tilde{\gamma}_\circ-1/p $, there exists a modification of ${\color{purp}G}:= (G^\bullet, G^\circ,\mathbb{G}^{\bullet \bullet}, \mathbb{G}^{\circ \bullet}, \mathbb{G}^{\bullet \circ} )$ such that with probability one, we have ${\color{purp}G} \in \mathcal{R}^{\gamma_\bullet, \gamma_\circ}$. Moreover, there is a constant $C=C(\gamma_\bullet, \tilde{\gamma}_\bullet, \gamma_\circ, \tilde{\gamma}_\circ, p)$ such that 
    \begin{equs}
        \| [G^i]_{\mathcal{C}^{\gamma_i}} \|_{L_p} \leq C K_i, \qquad \| [\mathbb{G}^{ij}]_{\mathcal{C}^{\gamma_i+\gamma_j}_2} \|_{L_p} \leq  C (K_{ij}+K_iK_j) . 
    \end{equs} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 32 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Fix a linear order $\alpha$.
    Let us define the deduction rules of $\sfu\RS_\alpha$ as follows, where every sequent is in the language $\calL^u_{\alpha+1,\alpha}$, so we identify $\ttOmega$ with $\alpha$ in $\alpha+1 = \alpha\cup\{\ttOmega\}$.
    \begin{center}
    \vspace{1em}
    \begin{mathprooftree}
        \AxiomC{}
        \RightLabel{$(\mathrm{Ax}) \quad (x\in y\in u)$}
        \UnaryInfC{$\Gamma,\ x\in y$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \AxiomC{}
        \RightLabel{$(\mathrm{Ax}) \quad (x\notin y\in u,\ y\in u)$}
        \UnaryInfC{$\Gamma,\ x\notin y$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \AxiomC{$\Gamma,\ A$}
        \AxiomC{$\Gamma,\ B$}
        \RightLabel{$(\land)$}
        \BinaryInfC{$\Gamma,\ A\land B$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \AxiomC{$\Gamma,\ A$}
        \RightLabel{$(\lor)$}
        \UnaryInfC{$\Gamma,\ A\lor B$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \AxiomC{$\Gamma,\ B$}
        \RightLabel{$(\lor)$}
        \UnaryInfC{$\Gamma,\ A\lor B$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \AxiomC{$\Gamma,\ s\dotin t\land r=s$}
        \RightLabel{$(\in)$ \hspace{2em} ($|s|<|t|$, $r\in t$ not basic.)}
        \UnaryInfC{$\Gamma,\ r\in t$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$\cdots \quad \Gamma,\ s\dotin t\to r\neq s \quad \cdots$ ($|s|<|t|$)}
        \RightLabel{$(\notin)$}
        \UnaryInfC{$\Gamma,\ r\notin t$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \AxiomC{$\Gamma,\ s\dotin t \land B(s)$}
        \RightLabel{$(\rmb\exists)$ \hspace{2em} ($|s|<|t|$)}
        \UnaryInfC{$\Gamma,\ \exists x\in t B(x)$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \AxiomC{$ \cdots \quad \Gamma,\ s\dotin t\to B(s) \quad \cdots$ ($|s|<|t|$)}
        \RightLabel{$(\rmb\forall)$}
        \UnaryInfC{$\Gamma,\ \forall x\in t B(x)$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \AxiomC{$\Gamma,\ A^{\ttL(u)_\ttOmega}$}
        \RightLabel{(Refl) \hspace{2em} ($A$ is a $\Sigma$-formula)}
        \UnaryInfC{$\Gamma,\ \exists z\in \ttL(u)_\ttOmega A^z$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$\Gamma,\ A$}
        \AxiomC{$\Gamma,\ \lnot A$}
        \RightLabel{(Cut)}
        \BinaryInfC{$\Gamma$}
    \end{mathprooftree}
    \vspace{1em}
    \end{center}
    Every tree formed by the given rule is an $\sfu\RS_\alpha$-preproof. We call a $\sfu\RS_\alpha$-preproof $\pi$ a \emph{proof} if $\pi$ has no infinite branch.

[Thm 4 of arXiv:2605.05430, 'Dirichlet problems and exit distributions for the telegraph process and its planar extensi'] For $x\in[a,b]$, it holds that

\begin{align}h_0(x)=\,&\frac{\lambda_0+\lambda_1}{\lambda_0c_1-\lambda_1c_0}\,(x-a)\nonumber\\
&\quad-\frac{(\lambda_0+\lambda_1)(b-a)}{\lambda_0c_1-\lambda_1c_0}\cdot\frac{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}\nonumber\\
&\quad+\frac{\lambda_0c_1(c_0+c_1)}{\lambda_0c_1-\lambda_1c_0}\cdot\frac{e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}}{\lambda_0c_1e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}
\end{align}
and
\begin{align}h_1(x)=\,&\frac{\lambda_0+\lambda_1}{\lambda_0c_1-\lambda_1c_0}\,(x-a)\nonumber\\
&\quad-\lambda_1c_0\,\frac{c_0+c_1+(\lambda_0+\lambda_1)(b-a)}{\lambda_0c_1-\lambda_1c_0}\cdot\frac{e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}-e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}{\lambda_0c_1e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}
\end{align}
Consequently, 
\begin{align}h(&x)=\frac{\lambda_0+\lambda_1}{\lambda_0c_1-\lambda_1c_0}\,(x-a)\nonumber\\
&-\frac{(\lambda_0+\lambda_1)(b-a)}{2(\lambda_0c_1-\lambda_1c_0)}\cdot\frac{(\lambda_0c_1+\lambda_1c_0)\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}-2\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}\nonumber\\
&+\frac{c_0+c_1}{2(\lambda_0c_1-\lambda_1c_0)}\cdot\frac{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-(\lambda_0c_1+\lambda_1c_0)e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}+\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}{\lambda_0c_1e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}
\end{align}

[Lemma 7 of arXiv:2608.04644, 'Khinchin's and Chung's Laws of the Iterated Logarithm at Time Zero for the Linear Stochast'] Recall that $H$ is defined in \eqref{def:H}. Suppose that  Condition \ref{hypo}  holds  and that $H<1$.  Then, for every fixed $x\in\mathbb{R}^d$, the following assertions hold.
\begin{itemize}
	\item[(1)] For every $t\ge0$,
	\begin{equation}
		\|u(t,x)\|_{L^2(\Omega)}^2
		=
		\textcolor{black}{\widetilde{\kappa}}^2 t^{2H},
	\end{equation}
	where $\textcolor{black}{\widetilde{\kappa}}$ is given by \eqref{def:tilde:kappa}.

	\item[(2)] The process $\{u(t,x)\}_{t\ge0}$ is a centered Gaussian self-similar process with Hurst index $H$.
\end{itemize}

