[Theorem stopping_quantile_continuity of arXiv:2605.20471, 'Note on the Weak Convergence of Hyperplane $α$-Quantile Functionals and Their Continuity i'] Let $T>0,\alpha \in (0,1),\gamma \in \mathbb{R}^d$. Let $x^n\to x$ in the Skorokhod topology and $x$ such that $ \alpha \notin U(x,T)$. Define:
	\begin{equation}
	x\mapsto \tau_{M_{T,\alpha}}(x):=\begin{cases}
	\inf\bigg\{t>0:\sup_{s\leq t}(\gamma \cdot x)_s\geq  M_{T,\alpha}(x)\bigg\}&\textrm{ if }\,M_{T,\alpha}(x)>\gamma \cdot x_0\\
	0&\textrm{ if }\,M_{T,\alpha}(x)= \gamma \cdot x_0\\
	\inf\bigg\{t>0:\inf_{s\leq t}(\gamma \cdot x)_s\leq  M_{T,\alpha}(x)\bigg\}&\textrm{ if }\,M_{T,\alpha}(x)< \gamma \cdot x_0\\
	\end{cases}
	\end{equation}
	Suppose that $M_{T,\alpha}(x)\neq \gamma \cdot x_0$. Then:
	\begin{enumerate}
		\item $\liminf_{n}\tau_{M_{T,\alpha}}(x^n)\geq \tau_{M_{T,\alpha}}(x)$;
		\item If, equivalently, $y\mapsto \frac{1}{T}\int_0^T\mathbf{1}_{\{z:\gamma \cdot z\leq y\}}(x_s)ds$ is continuous or $\beta \mapsto M_{T,\beta}(x)$ is strictly increasing and additionally $\alpha\in  \{\alpha:\lim_{\beta \to \alpha}\tau_{M_{T,\beta}}(x)=\tau_{M_{T,\alpha}}(x)\}$, then we have $\tau_{M_{T,\alpha}}(x^n)\to \tau_{M_{T,\alpha}}(x)$.
	\end{enumerate} 
	In fact, if the conditions of (2) are satisfied, then we also have $$(M_{T,\alpha}(x^n),\tau_{M_{T,\alpha}}(x^n))\to (M_{T,\alpha}(x),\tau_{M_{T,\alpha}}(x))$$
	in the usual sense.

