[Theorem theorem_spin_correlations of arXiv:2411.16452, 'Interface scaling limit for the critical planar Ising model perturbed by a magnetic field'] Let $\Omega \subset \mathbb{C}$ be a bounded and simply connected domain and $a, b \in \partial \Omega$ be two prime ends of $\partial \Omega$. Let $(\Omega_{\delta};a_{\delta}, b_{\delta})_{\delta}$ be discrete approximations of $(\Omega;a,b)$ satisfying the assumptions of Section (sec_assumptions_domain of the paper). Then, for any $\eta >0$ and any $k \geq 1$, we have that
\begin{align*}
    &\delta^{-\frac{k}{8}} {\mathbb{E}_{\delta}^{\pm}}[\sigma_{x_1}\dots \sigma_{x_{k}}] = C_{\sigma}^k f_{\Omega}^{(\pm, k)}(x_1,\dots ,x_k) + o(1) \\
    &\delta^{-\frac{k}{8}} {\mathbb{E}_{\delta}^{+}}[\sigma_{x_1}\dots \sigma_{x_{k}}] = C_{\sigma}^k f_{\Omega}^{(+,k)}(x_1,\dots ,x_k) + o(1) \\
    &\delta^{-\frac{k}{8}} {\mathbb{E}}_{\delta}^{-}[\sigma_{x_1}\dots \sigma_{x_{k}}] = C_{\sigma}^k f_{\Omega}^{(-,k)}(x_1,\dots ,x_k) + o(1)
\end{align*}
as $\delta \to 0$, uniformly over all $x_1, \dots, x_k \in \Omega$ at distance at least $\eta$ from $\partial \Omega$ and from each other. Here, $C_{\sigma}>0$ is a constant that corresponds to the fact that we are working on the square lattice. The functions $f_{\Omega}^{(\pm,k)}$, $f_{\Omega}^{(+,k)}$ and $f_{\Omega}^{(-,k)}$ are explicit and satisfy the following conformal covariance property. If $\psi: \Omega \to \tilde \Omega$ is a conformal map, then for any $k \geq 1$ and any $x_1, \dots , x_k \in \Omega$, with $\xi \in \{\pm,-,+\}$,
\begin{align*}
    &f_{\Omega}^{(\xi, k)}(x_1,\dots ,x_k) = \prod_{j=1}^{k} \vert \psi'(x_j) \vert^{1/8} f_{\tilde \Omega}^{(\xi,k)}(\psi(x_1),\dots ,\psi(x_k)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:gmc-singular-lebesgue of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] The two measures are almost surely mutually singular:
\begin{equation}
 \mathbb P\!\left(M_h\perp\mathcal L^2\right)=1.
\end{equation}

[Definition 8 (Orthonormal systems, Parseval frames, and standard bases in Hilbert $\mathcal{A}$-modules) of arXiv:2608.30589, 'Vector-Valued Wavelet Bases as Hilbert $\mathbb{M}_m(\mathbb{R})$-Module Bases: A Construc'] Let $\mathbb{H}$ be a Hilbert $\mathcal{A}$-module.
\begin{enumerate}
\item A family $S=\{h_i\}_{i\in I}\subset \mathbb{H}$ is an \emph{orthonormal system (ONS)} if
\begin{equation}
\langle h_i,h_j\rangle_{\mathcal{A}}=0 \ (i\neq j),\qquad
\langle h_i,h_i\rangle_{\mathcal{A}}=p_i,
\end{equation}
where each $p_i\in\mathcal{A}$ is a nonzero projection ($p_i^2=p_i=p_i^*$). If moreover $p_i=1_{\mathcal{A}}$ for all $i$, then $S$ is called an \emph{orthonormal system of unit vectors}.
\item A family $\{x_i\}_{i\in I}\subset \mathbb{H}$ is a \emph{Parseval $\mathcal{A}$-module frame} if for every $f\in\mathbb{H}$,
\[
f=\sum_{i\in I}\langle f,x_i\rangle_{\mathcal{A}}\,x_i
\]
with convergence in the Hilbert-module norm.
\item A family $S=\{h_i\}_{i\in I}\subset \mathbb{H}$ is an \emph{$\mathcal{A}$-orthonormal basis} (or \emph{standard basis}) if it is an orthonormal system of unit vectors and for every $f\in\mathbb{H}$ one has the reconstruction formula
\begin{equation}
f=\sum_{i\in I}\langle f,h_i\rangle_{\mathcal{A}}\,h_i,
\end{equation}
with convergence in the Hilbert-module norm. Equivalently, $S$ is an $\mathcal{A}$-Parseval frame and is orthonormal.
\end{enumerate}

[Lemma green_function_on_Z of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $d \ge 2$ and $Q \in \mathcal{H}_{\alpha, K}$ for some $\alpha, K > 0$. 
The Green's function on $\mathbb Z^d$ satisfies the following: \\
(i) if $\alpha > 2$ and $d = 2$, then
\begin{align*}
    G_n \asymp \log n,
\end{align*}
(ii) if $\alpha = 2$ and $d = 2$, then
\begin{align*}
    G_n \asymp \log \log n,
\end{align*}
(iii) if $\alpha < 2$ and $d = 2$ OR $d \ge 3$, then 
\begin{align*}
    G_n \asymp 1,
\end{align*}
where the implicit constants in $\asymp$ depend on $Q$.

[Proposition 21 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] For $x\in C$,

\begin{equation*}
P_Z^C=\widetilde H^C+q^C*P_Z^C,
\qquad
P_Z^C=\psi^C*\widetilde H^C.
\end{equation*}

Moreover,

\begin{equation*}
P_Z^C(k)(x,C)=R_D(k)(x).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 36 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Let $Z$ and $H$ be nonnegative, adapted processes with continuous paths and assume that $\psi$ is nonnegative and progressively measurable. Let $M$ be a continuous local martingale starting at $0$. If the following condition holds for all $t\geq 0$,
  \begin{equation*}
  Z(t)\leq\int_{0}^{t}\psi(s) \, Z(s)\,\mathrm{d}s+M(t)+H(t),
  \end{equation*}
  then for $p\in(0,1)$, $p_1 \in (1,1/p)$ and $p_2= \frac{p_1}{p_1-1}$, we have
  \begin{equation*}
  \E \sup_{0 \leq s \leq t} Z^{p}(s)\leq \Big( (c_{p} p_1 +1)\, \E\big[\sup_{0 \leq s \leq t} H(s) \big]^{p p_1}\Big)^{1/p_1} \left(\E \exp \Big\{p p_2 \int_{0}^{t}\psi(s)\,\d s \Big\}\right)^{1/p2} ,
  \end{equation*}
  where $c_p := (4 \wedge \frac{1}{p}) \frac{\pi p}{\sin(\pi p)}>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 6.3 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] For $d = \tfrac{1}{\sqrt{\alpha}}$, Assumption~(assumpt:2.7 of the paper) is consistent with  Assumption~(assumpt:2.9 of the paper), and (equation eq:lem_6.3_0 of the paper) remains valid for $[ \varkappa T^{2/3}]$ instead of $J_\varkappa$. This means that 
	\begin{equation}
	\lim_{\varkappa \to \infty} \lim_{T \to \infty} \mathbb{P}(x_{\alpha T-j}(T) > (1-2\sqrt{\alpha})T-x_{1+j}^f-ST^{1/3} \ \forall j \in [\alpha T-1] \setminus [\varkappa T^{2/3}]) = 1,
	\end{equation}
	as used in the proof of Theorem~(th:2.3 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:ordered of arXiv:2605.30017, 'Conditional Probability Spaces and the Structure of Agreement\footnote{We thank Emiliano C'] Fix $i = A, B$ and a set $G$ in $\mathcal G_i$.  Let $\mu_1, \dots, \mu_K$ be the distinct $\mathcal G_i$-atoms contained in $G$, ordered so that $\mu_r \subsetneq \mu_s$ implies $r < s$.  For each $j = 1, \dots, K$, let $ U_j = \bigcup_{k=1}^j \mu_k$.  Then:
\begin{enumerate}  [label=(\roman*)]
\item $G = \bigcup_{k=1}^K \mu_k$;
\item for every $j = 2, \dots, K$:
\begin{equation} 
U_{j-1} \cap \mu_j = \bigcup_{\{r < j : \mu_r \subsetneq \mu_j\}} \mu_r.
\end{equation}
\end{enumerate}

