[Lem 22 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $s\geq0$ and $p_0,p_1,p_2,p_1',p_2'>1$ such that $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{p_0}=\frac{1}{p_1'}+\frac{1}{p_2'}$. Then there exists a constant $C$ such that
    \begin{align*}
        \Vert (1+D^2)^\frac{s}{2}(fg)\Vert_{L^{p_0}}\leq C\Vert (1+D^2)^\frac{s}{2}f\Vert_{L^{p_1}}\Vert g\Vert_{L^{p_2}}+C\Vert (1+D^2)^\frac{s}{2}g\Vert_{L^{p_1'}}\Vert f\Vert_{L^{p_2'}}
    \end{align*}
    for all functions $f\in W^{s,p_1}\cap L^{p_2'}$ and $g\in W^{s,p_1'}\cap L^{p_2}$.

[Theorem 1 of arXiv:2609.02175, '2609.02175'] Let $V_1,V_2\in C_c^\infty(\mathbb R^n)$, $n\geq3$, and let
	$\lambda>0$ satisfy
	\begin{equation}
		\lambda>\sup_{\mathbb R^n}V_j,
		\qquad j=1,2.
	\end{equation}
Assume moreover the virial condition
\begin{equation}
	2(\lambda-V_j(x))-x\cdot\nabla V_j(x)>0,
	\qquad x\in\mathbb R^n,
	\qquad j=1,2.
\end{equation}
	If
	\begin{equation}
		\|S_1(\lambda,h)-S_2(\lambda,h)\|_
		{\mathcal B(L^2(\mathbb S^{n-1}))}
		=
		o(1),
		\qquad h\to0,
	\end{equation}
	then
	\begin{equation}
		V_1=V_2.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma range_estimates_main_text of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Consider a random walk on $\mathbb Z^d$ driven by $Q$. Let $D \subseteq H(r)$ with $|D|/|H(r)| \leq 3/4$. Define $\widetilde{\mathrm{R}}(k) := \mathrm{R}(k) \cap (H(r) \setminus D)$. Then, there exist positive constants $c_0, c_1$ depending on $Q$ such that for any $r \in \mathbb N^+$ and any $x \in H(r)$:
    \begin{align} 
        \mathbf P_x \left( \, \left|\widetilde{\mathrm{R}}\left(\ell(r)\right) \right| \geq c_1 f(r) \right) \geq c_0,
    \end{align}
    where $f(r)$ is defined as follows with $\ell(r)$ defined in (equation def: s(r) of the paper):
    \begin{align*}
        f(r) := \begin{cases}
            \ell(r) & \text{if } d \ge 3 \text{ or } (d = 2 \text{ and } \alpha < 2), \\
            \ell(r) / \log \log \ell(r) & \text{if } d = 2 \text{ and } \alpha = 2, \\
            \ell(r) / \log \ell(r) & \text{if } d = 2 \text{ and } \alpha > 2.
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop graph of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] For any $d \geq 2$, there exist constants $c_{\mathrm{reg}} , C_{\mathrm{reg}}, C_{\mathrm{S}_1}, C_{\mathrm{P}}\in (0, \infty)$ that depend at most on $d$,  
  such that for any $x \in \mathbb{Z}^d$, $n\in \mathbb{N}$ the following holds true:

  \begin{enumerate}[(i)]
  \item (Volume regularity) 

    \begin{align}
      c_{\mathrm{reg}}\, n^d \;\leq\; |B(x, n)| \;\leq\; C_{\mathrm{reg}}\, n^d.
    \end{align}

  \item (Sobolev inequality) 
  For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$ with $\supp{u} \subset B(x, n)$,

    \begin{align} 
      \Norm{u}{d/(d-1), B(x, n)}
      \;\leq\;
      C_{\mathrm{S_1}}\, \frac{n}{\abs{B(x, n)}}\, \sum_{\{y, y'\} \in E_d} |u(y) - u(y')|.
    \end{align}


  \item (Weak Poincar\'{e} inequality) 

    For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$

    \begin{align}
      \Norm{u - (u)_{B(x, n)}}{1, B(x, n)}

      \;\leq\;
      C_{\mathrm{P}}\, \frac{n}{\abs{B(x, n)})} 
      \sum_{\substack{y, y' \in B(x, n)\\ \{y, y'\} \in E_d}}
      \mspace{-24mu}|u(y) - u(y')|,
    \end{align}

    where $(u)_{B(x, n)} \ensuremath{\mathrel{\mathop:}=} \frac{1}{|B(x, n)|} \sum_{y \in B(x, n)} u(y)$.
  \end{enumerate}

