body:
[Lemma 21 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] Let $\nu > 0$. Then, for all
  $x_{1} \in \hcV_{\nu}^{(\rm h)}$,
  \begin{equation*}
    \sum_{\substack{x_{2}, x_{3} \in \hcV_{\nu}^{(\rm h)}\\x_{2} \succ x_{1}, x_{3}}} \left< \b 1_{\Sdu(x_{1})}, \b 1_{\Sdu(x_{2})} \right>\left< \b 1_{\Sdu(x_{2})\setminus \Sdu(x_{1})}, \b 1_{\Sdu(x_{3})} \right> \leq 2\nu \left( \frac{\log N}{\log\log N} \right)^{2}\,,
  \end{equation*}
  with $\nu$-high probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2609.02516, 'Power convexity of the torsion function on horo-convex domains in hyperbolic space'] Let $n\geq 2$, and let $\Omega\subset\mathbb{H}^n$ be contained in a geodesic ball $B_R$ of radius $R>0$. If $u_\Omega$ is the torsion function of $\Omega$ and $v_\Omega=-\sqrt{u_\Omega}$, then $$-\frac{R}{\sqrt{n}}<v_\Omega<0\quad\mathrm{in}\ \Omega.$$ In particular, if $R\leq 1/(2\sqrt{n})$, then
\begin{equation}
-\frac{1}{2n}<v_\Omega<0\quad\mathrm{in}\ \Omega.
\end{equation}

