[Corollary 35 (Explicit product-rule matrix criterion) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] In the setting of \cref{thm:selected-criterion}, let $L_I:T_0\to\RR^s$ be the linear map whose $j$th coordinate covector is
\begin{equation*}
\sum_{z\in F_{y_j}}\alpha_{j,z}(\theta_0)D\zeta_{j,z}(\theta_0)|_{T_0} + \sum_{z\in F_{y_j}}\zeta_{j,z}(\theta_0)D\alpha_{j,z}(\theta_0)|_{T_0},
\end{equation*}
where $\alpha_{j,z}$ and $\zeta_{j,z}$ are defined as in \cref{lem:coord-fiber} for the pair $(y_j,a_j)$.
Then
\begin{equation}
L_I=M_I.
\end{equation}
In particular, if
\begin{equation}
\Ker(L_I)\subset\Ker\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_{T_0}\bigr), \qquad \rank(L_I)<p, \qquad \rank\bigl(Dq_{\cQ}^{(r)}(\theta_0)|_{T_0}\bigr)=p,
\end{equation}
then the depth-$m$ window is not first-order locally sufficient relative to depth $r$ on $T_0$.

[Proposition 16 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Let Assumptions \ref{ass:K} and \ref{ass:F} hold. Let $\gamma\in(0,1)$. Then $ \phi$ maps $\shc^{\gamma}\cap L^1$ into itself.
  Moreover there exists a positive constant $C_{F,K}$,

  such that,
 for all $f,g\in \shc^{\gamma}\cap L^1$
   \begin{align}
    \|\phi f\|_{\shc^{\gamma}}\leq C_{F,K}\|f\|_{\shc^{\gamma}}\left(1+\|f\|_{L^1}\right),
   \end{align}
\begin{equation}
  \|\phi f\|_{L^1}\leq C_{F,K}\Vert f \Vert_{L^1},
 \end{equation}
  \begin{equation}

      \|\phi f-\phi g\|_{\shc^{\gamma}}\leq C_{F,K}(1+\|f\|_{\shc^{\gamma}}+\|g\|_{\shc^{\gamma}})(1+\|f+g\|_{L^1})\|f-g\|_{\shc^{\gamma}}.
    \end{equation}

