[Definition 27 of arXiv:2506.10511, '2506.10511'] For any $\alpha, b>0$ and  any connected set $\Lambda=\{{\bm k}_1,\cdots,{\bm k}_n\}\subset G$, we say that $\Lambda$ is $(\alpha,b)$-good if at least $n/(2\cdot 3^d)$ of its indices $j\in[1,n]_\mathds{Z}$ satisfy the following conditions:
	\begin{enumerate}
		\item[(1)] For each $P\in\mathcal{C}_{\delta,L}(\Lambda)$, if $({\bm u}_{{\bm k}_j,1}, {\bm v}_{{\bm k}_j,1},{\bm u}_{{\bm k}_j,2},{\bm v}_{{\bm k}_j,2})$ is a $V_{3\delta L}({\bm k}_j)$-special pair of edges such that $P$ first uses $\langle {\bm u}_{{\bm k}_j,1}, {\bm v}_{{\bm k}_j,1}\rangle$ to enter $V_{\delta L}({\bm k}_j)$ and then does not leave $V_{3\delta L}({\bm k}_j)$ until it uses $\langle {\bm u}_{{\bm k}_j,2}, {\bm v}_{{\bm k}_j,2}\rangle$, then it satisfies
		\begin{equation*}
			|{\bm v}_{{\bm k}_j,1}- {\bm u}_{{\bm k}_j,2}|\geq \alpha\delta L \quad \text{and}\quad  D({\bm v}_{{\bm k}_j,1}, {\bm u}_{{\bm k}_j,2}; V_{3\delta L}({\bm k}_j)) \geq (b\alpha \delta L)^\theta.	
		\end{equation*}

		\item[(2)] For any two distinct indices ${j}_1$ and ${ j}_2$, we have ${\bm k}_{{ j}_1} - {\bm k}_{{ j}_2} \in (3\delta L)\mathds{Z}^d$.
	\end{enumerate}
	If $\Lambda$ is not $(\alpha,b)$-good, then we say that $\Lambda$ is $(\alpha,b)$-bad.

[Lemma 11 of arXiv:2603.26936, 'Sharp Riemannian heat kernel estimates on the cut locus and the Parabolic Anderson model'] Suppose M has positive injectivity radius (meaning it is bounded from below by a positive constant) and sectional curvature bounded from above; note that this always holds if $M$ is compact. Then we can find constants $\zeta\in(0,1)$ and $D>0$ depending only on these two bounds (and with $D$ less than the injectivity radius of $M$) such that, for any $x,y\in M$ with $\bm{d}(x,y)< D$,
\begin{equation}
F_{a;x,y}(z) \geq \zeta \bm{d}^2(\gamma_{xy}(a),z)
\end{equation}
for any $a\in[0,1]$ and any $z\in M$.

[Lem 28 of arXiv:2608.26642, '2608.26642'] Assume that $\P_0[X_1^2]<\infty$. If a function $f\in L_{loc}^1(\R)$ satisfies
\begin{align}
   \mathscr{L}f=0,\qquad |f(x)|\le C(1+|x|),
 \end{align}
then there exist constants $a,b\in \R$ such that
 \begin{align}
   f(x)=ax+b\qquad \text{for a.e.}\ x\in \R.
 \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2608.10415, 'Continuous random variables'] The basic random matrices $Z\in M_N(L^\infty(X))$ are as follows:
\begin{enumerate}
\item In the case $N=1$ the random matrix is a usual random variable, $f\in L^\infty(X)$, automatically normal, and its law as defined above is the usual law.

\item In the case $X=\{.\}$ the random matrix is a usual scalar matrix, $A\in M_N(\mathbb C)$, and in the diagonalizable case, the law is $\mu=\frac{1}{N}\left(\delta_{\lambda_1}+\ldots+\delta_{\lambda_N}\right)$.
\end{enumerate}

