body:
[Lemma lem.tail-conversion of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let $\alpha\in(0,1)$ and $\sigma\in(0,1]$. Let $T\colon\Omega\to[0,\infty)$ and $\lambda_0\colon\Omega\to(0,1]$ be random variables. Suppose there exist deterministic $C_T<\infty$ and $c_T>0$ such that
		\begin{equation}
			\mathbb{Q}(T\ge M)\le C_T\exp(-c_T M^\sigma)\qquad\text{for every }M\ge 0\, ,
		\end{equation}
		and that for every $p>0$ there exists a deterministic $C_p<\infty$ such that
		\begin{equation}
			\mathbb{Q}(\lambda_0\le 2^{-k})\le C_p 2^{-pk}\qquad\text{for every }k\in\mathbb{N}\, .
		\end{equation}
		Let $\lambda_*(\omega)=3^{-(1-\alpha)T(\omega)}\wedge\lambda_0(\omega)\wedge 1$. Then there exist deterministic $C_*<\infty$ and $c_*>0$, depending only on $\alpha$, $\sigma$, $C_T$, $c_T$, and the family $(C_p)$, such that
		\begin{equation}
			\mathbb{Q}(\lambda_*\le\lambda)\le C_*\exp\bigl(-c_* (\log(1/\lambda))^\sigma\bigr)\qquad\text{for every }\lambda\in(0,1]\, .
		\end{equation}

[Lemma lem:cross-order-sec9 of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] There exists $\ell_0<\infty$ such that
\begin{equation}
\underline u_\ell<\overline u_\ell
\qquad\text{in }\mathbb R^4
\end{equation}
for every $\ell\ge\ell_0$.

[Conjecture conj: Discriminant of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Suppose that $\bM$ is chosen uniformly at random from all symmetric $n\times n$ matrices with $\{0,1 \}$-valued entries. 
    Then, for every prime $p$, 
    \begin{equation}
        \lim_{n\to \infty}\bbP\bigl(p \nmid \Delta_{\bM}\bigr) = \Bigl( 1 - \frac{1}{p}\Bigr) \prod_{k=1}^\infty\Bigl(1 - \frac{1}{p^{2k}}\Bigr). 
    \end{equation}
    Further, for every odd prime $p$, 
    \begin{equation}
        \lim_{n\to \infty}\bbP\bigl(p^2 \nmid \Delta_{\bM}\bigr) = \Bigl(1 - \frac{1}{p^2} \frac{3p-1}{p+1}\Bigr)\prod_{k=1}^\infty\Bigl(1 - \frac{1}{p^{2k}}\Bigr) 
    \end{equation}
    Moreover, the limiting probability for being odd and square-free factorizes over the constituent primes:
    \begin{align}
        \lim_{n\to \infty} \bbP\bigl(\Delta_{\bM} \textnormal{ is odd and square-free}\bigr) &= \frac{6}{7} \prod_{p \textnormal{ prime}}\Bigl(1 - \frac{1}{p^2} \frac{3p-1}{p+1}\Bigr)\prod_{k=1}^\infty\Bigl(1 - \frac{1}{p^{2k}}\Bigr) \\ 
        &= 0.1686\ldots \nonumber 
    \end{align} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 5 of arXiv:2604.13149, 'The Distributional Tail of Worst--Case Quickselect'] For all \(a>0\) and integers \(j\ge 1\), \(\ell\in\{0,\dots,j-1\}\) with \(r=j-\ell\ge 1\),
\begin{equation}
p_{j,\ell}(a)\le \binom{2r}{r}\,\frac{a^{\,j+r}}{(j+r)!}.
\end{equation}

[Corollary cor:Poisson_fringe of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume that $\mu$ is critical and belongs to the domain of attraction
of an $\alpha$-stable law for some $\alpha\in(1,2]$. Let $(k_n)_{n\geq 0}$ be
an integer sequence such that $k_n\to\infty$ and $k_n=o(n)$.
Suppose that, for every $k\ge1$ and every plane tree $\tau$, $
G_k(\tau)=1
\implies
|\tau|=k$.
Then:
\begin{enumerate}
\item[(i)] If $(n\pi_n)$ is bounded, then
\begin{equation}

d_{\mathrm{TV}} \left(
\# \{u \in \mathcal{T}^{n} : G_{k_{n}}( \mathcal{T}^{n}_{u})=1\},
\mathrm{Poisson}(n \pi_{n})
\right)
\quad \mathop{\longrightarrow}_{n \rightarrow \infty} \quad 0.
\end{equation}

\item[(ii)] If $n\pi_n\to\infty$, then
$$
\frac{
\#\{u\in\mathcal T^n: G_{k_n}(\mathcal T^n_u)=1\}
}{n\pi_n}
\quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad 1.
$$
In particular,
$$
\#\{u\in\mathcal T^n: G_{k_n}(\mathcal T^n_u)=1\}
\quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad \infty.
$$
\end{enumerate}

[Prop 15 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] For $\bbQ$-a.e.\ $\omega\in\Omega_{\lambda,\Lambda}$
    \begin{equation}
        \liminf_{N \to \infty} \inf_{x \in \bbZ^d} \Big[ \frac{\bbE^{\omega,+}_N[\varphi_x]}{\sqrt{4 \overline{g} \log N}} - h^\omega_{V_N}(x)   \Big] \geq 0 \,.
