body:
[Corollary 26 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let $S,T \in \SymHS(\Hcal)_{< I}$. Let
	$\mu = \Ncal(0,Q)$, $Q = C_0^{1/2}(I-S)C_0^{1/2}$, $\nu = \Ncal(0,R)$, $R = C_0^{1/2}(I-T)C_0^{1/2}$.
	Then 
	\begin{align}

		&\left\la \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}, \log\left\{{\frac{d\nu}{d\mu_0}(x)}\right\}\right\ra_{\Lcal^2(\Hcal,\mu_0)} =  \frac{1}{2}\la S(I-S)^{-1}, T(I-T)^{-1}\ra_{\HS}
		\nonumber
		\\
		& \quad \quad \quad \quad \quad \quad + \frac{1}{4}\log\dettwo[(I-S)^{-1}]\log\dettwo[(I-T)^{-1}].
		\\
		&\left\| \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_0)}=
		\frac{1}{2}||S(I-S)^{-1}||^2_{\HS}
		+ \frac{1}{4}(\log\dettwo[(I-S)^{-1}])^2.
		\\
		&\left\| \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_0}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_0)}=
		\frac{1}{2}||S(I-S)^{-1}-T(I-T)^{-1}||^2_{\HS}
		\nonumber
		\\
		& \quad \quad \quad \quad \quad \quad + \frac{1}{4}(\log\dettwo[(I-S)^{-1}] - \log\dettwo[(I-T)^{-1}])^2.

	\end{align}
	Furthermore,
	\begin{align}

		&\left\| \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_0}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_0)}

		\\
		&\leq \left(\frac{1}{2} + \frac{1}{4}[||S||_{\HS} + ||T||_{\HS} + ||ST||_{\HS}]^2\right)||(I-S)^{-1}||^2||(I-T)^{-1}||^2||S-T||^2_{\HS}.
		\nonumber
	\end{align}

[Lemma lem:W-tail of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] There exists $C<\infty$ such that
\begin{equation*}

   \mathbb{P}\bigl(W\ge C\sqrt\delta\,n(\log n)^{-3/2}\bigr)
   \le C\sqrt\delta+o_n(1).
\end{equation*}

[Theorem 5 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Suppose we are in Scenario~\eqref{Scenario_1}, and let $H_{0}$, defined in \eqref{H_{0}_defn}, satisfy the criterion:
\begin{equation}
(q_{1}+q_{2})\max\left\{\sup\left\{\left|\frac{\partial}{\partial x}H_{0}(x,y)\right|:(x,y)\in\mathcal{S}\right\},\sup\left\{\left|\frac{\partial}{\partial y}H_{0}(x,y)\right|:(x,y)\in\mathcal{S}\right\}\right\}<1.}
\end{equation}
Then there exists a unique root, say $(x^{*},y^{*})$, of the function $h$, defined in \eqref{h_H_defns}, in the set $\mathcal{S}$, and irrespective of whether the samples are drawn with replacement or without, the sequence $\{(n^{-1}A_{n},n^{-1}B_{n})\}$ converges almost surely to $(x^{*},y^{*})$. The same conclusion remains true if $g\in\mathcal{C}^{(1)}(\mathcal{S})$ and 
\begin{equation}
(q_{1}+q_{2})\max\left\{\sup\left\{\left|\frac{\partial}{\partial x}g(x,y)\right|:(x,y)\in\mathcal{S}\right\},\sup\left\{\left|\frac{\partial}{\partial y}g(x,y)\right|:(x,y)\in\mathcal{S}\right\}\right\}<1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] Let $ X_{ N}$ real random variables with $ X_{ N}  \xrightarrow[N \to \infty ]{w} X$. Assume $ \sup_{ N}\mathbf E\left[
 X_{ N}^{ 2}
\right]<\infty .$ Then 
\begin{align*}
  \textrm{Var}\left(X\right)\leqslant  \liminf_{ N}   \textrm{Var}\left(X_{ N}\right).
\end{align*}

