[Lemma logtildeGNbnd of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] For any $c \in \R^n$,  we have $\tilde{G}_N (\Lambda, \varphi + c\one) = \tilde{G}_N (\Lambda, \varphi) \le G_N (\Lambda, \varphi)$ and
\begin{align}
	\log G_N (\Lambda, \varphi)
		\lesssim L \norm{\varphi}^2_{\ell_N, \Phi_N}	
		 \lesssim L \ell_{N,\varnothing}^{-2} L^{-dN} \sum_{n \le d + p_{\Phi}} L^{2n N} \norm{\nabla^n \varphi}^2_{\ell^2 (\Lambda)} .

\end{align}

[Lemma 3 of arXiv:2606.22656, 'Fluctuations of Point Vortex Ensembles\\ at Small Negative Inverse Temperature'] For every $0\leq \beta_*<8\pi$ there exists $C_{\beta_*}<\infty$ such that, for all $0\leq \beta \leq \beta_*$, $N\ge2$, and $x\in\T$,
\begin{align}\notag
    |\log I_N|&\leq C_{\beta_*}\frac{\beta^2}{N^2}\\
    1+|K_N(x)|
    &\leq 
    \exp\left\{
        \frac{\beta}{N}|G(x)|
        +C_{\beta_*}\frac{\beta^2}{N^2}
    \right\},

    \\
    |K_N(x)|
    &\leq 
    \frac{C_{\beta_*}\beta}{N}
    \bigl(1+|G(x)|\bigr)
    \exp\left\{
        \frac{\beta}{N}|G(x)|
        +C_{\beta_*}\frac{\beta^2}{N^2}
    \right\}.
    \notag
\end{align}

