[Lemma lem:reduced-matrix-facts of arXiv:2608.29719, 'Persistence Pairing Graphs: Tracking Changes of Selected Homology Bases'] Let $U\in\Bbbk^{N\times N}$ be upper unitriangular.
\begin{enumerate}
\item If $c\in\Bbbk^N$ is nonzero, then $\operatorname{low}(Uc)=\operatorname{low}(c)$.
\item The nonzero columns of a reduced matrix are linearly independent.
\end{enumerate}

[Lemma 10 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Let $\gamma \in (0,1)$ and $K\in \shp(\R^d)$.  Let us suppose Assumption \ref{ass:F}. Then we have the following.
	\begin{itemize}
		\item[(i)] $K*f\in\shc^\gamma$ and
		\begin{equation}
			\|K*f\|_{\shc^\gamma}\leq \|f\|_{\shc^\gamma},  \forall f \in\shc^\gamma.  
		\end{equation}
		\item[(ii)] For all $\ell_1,\ell_2\in\shc^\gamma,  F(\ell_i)\in\shc^\gamma$ for $i=1,2$. Moreover we have
		\begin{equation}
			\|F(\ell_1)-F(\ell_2)\|_{\shc^\gamma}\leq C_F\|\ell_1-\ell_2\|_{\shc^\gamma}
		\end{equation}
		and
			\begin{equation}
			\|F(\ell_1)\|_{\shc^\gamma}\leq C_F(1+\|\ell_1\|_{\shc^\gamma}).
		\end{equation}
	\end{itemize}

