body:
[Proposition Proposition1 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and  let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C5 of the paper). Then, for any $\varepsilon>0$, as $n \rightarrow \infty$,
\begin{align} 
\sum_{i=1}^{m_{n}} \mathbb{E}[(e^{-\frac{\alpha}{2}t_{n}} \chi^{(\varphi, h)}_{u_{i}}(t_{n}-S(u_{i})))^{2} \mathbf{1}_{\{ |e^{-\frac{\alpha}{2}t_{n}} \chi^{(\varphi, h)}_{u_{i}}(t_{n}-S(u_{i}))|> \varepsilon \}} \mid \mathcal{G}_{i-1}^{(h)} ]  \xrightarrow[]{\rm p} 0. 
\end{align}

[Corollary 3 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] The expectation and variance of the generalized Euler characteristic $\chi_a(\Delta_W)$ are given by
\begin{align*}
\E{ \chi_a(\Delta_W) } \,&=\, \sum_{m=1}^{\alpha+1} a_{m-1} \frac{\beta^m}{m!} \z m m m (W), \\
\V{ \chi_a(\Delta_W) } \,&=\, \sum_{m,l=1}^{\alpha+1} \sum_{r=\max\{m,l\}}^{m+l-1} a_{m-1} a_{l-1} \frac{\beta^r}{(r-m)!(r-l)!(m+l-r)!} \, \z m l r (W).
\end{align*}

[Prp equivalent of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Let $\varphi$ be a characteristic function of an integer-valued random variable $X$ and let $0< \beta \leq 2$. The following assertions are equivalent.
\begin{enumerate}[(i)]
\item 
There exists $c > 0$ such that in an open neighborhood of $0$,
\begin{align*}
|1 - \varphi(x)| \geq c |x|^\beta.
\end{align*}

\item 
There exist $d \in \mathbb Z^+$ and $c' > 0$ such that for any $x \in \mathbb R$,
\begin{align*}
|1 - \varphi(2 \pi x)| \geq c' \| d x \|^\beta.
\end{align*}

\item 
There exist $d \in \mathbb Z^+$ and $c' > 0$ such that for any $x \in \mathbb R$,
\begin{align*}
|1 - \varphi(2 \pi x)| \geq c' |\varphi(2\pi x)| \| d x \|^\beta.
\end{align*}

\end{enumerate}

[Theorem 11 of arXiv:2609.02283, 'The game chromatic number of generalized Mycielski graphs of paths and cycles'] For $k\geq2$, the following statements hold for generalized Mycielski graphs of paths:

\begin{enumerate}[label={\upshape(\arabic*)},
                  nosep,
                  leftmargin=*]
\item $\chi_g(M_k(P_2))=3$;
\item $\chi_g(M_k(P_3))=3$;
\item $\chi_g(M_k(P_4))=3$;
\item $\chi_g(M_k(P_n))\geq4$ for $n\geq5$.
\end{enumerate}

