[Corollary 228 of arXiv:2601.16377, '2601.16377'] If $H = 2$ and $\theta_{g,h} = \theta > 0$ for all $g,h \in \{1,2\}$, we have
\begin{equation}

\mathcal{F}(z_1,z_2) = \frac{1}{4\theta \sigma(z_1)\sigma(z_2)}\left(\bigg(\frac{\sigma(z_1) - \sigma(z_2)}{z_1 - z_2}\bigg)^2 - (z_1 + z_2)(z_1 + z_2 - \mathsf{e}_1) + 4c_{0,0} - \mathsf{e}_2\right).
\end{equation}
where
\begin{equation}

c_{0,0} = \frac{1}{4}\left(\alpha_1\beta_2 + \alpha_2\beta_1 + (\beta_2 - \beta_1)(\alpha_2 - \alpha_1)\frac{E(\mathsf{k})}{K(\mathsf{k})}\right)
\end{equation}
in terms of the complete elliptic integrals
\begin{equation*}
\begin{split}
E(\mathsf{k}) = \int_{0}^{1} \sqrt{\frac{1 - \mathsf{k}^2t^2}{1 - t^2}},\qquad K(\mathsf{k}) = \int_{0}^{1} \frac{\dd t}{\sqrt{(1 - t^2)(1 - \mathsf{k}^2t^2)}}.
\end{split}
\end{equation*}
specialized to
\[
\mathsf{k} = \sqrt{\frac{(\beta_2 - \alpha_1)(\alpha_2 - \beta_1)}{(\beta_2 - \beta_1)(\alpha_2 - \alpha_1)}} < 1,
\]

[Cor 4 of arXiv:2603.28702, 'Distribution of the magnetization of the critical Ising model on sparse random graphs'] Consider the Ising model on $G(n,d/n)$ at the critical temperature and let
$$Z_n:=\SL{\sigma\in\{-1,1\}^n}\exp\left(\beta\SL{u\sim v}\sigma_u\sigma_v\right)$$
be its partition function. If we set
\begin{align*}
\Delta_n:=\log(Z_n)-n\log(2)-|E_n|\log\cosh(\beta)-\log\dfrac{\sqrt[4]{n}}{\sqrt{2\pi}}+\dfrac34,
\end{align*}
where $|E_n|$ is the number of edges of the graph, then
\begin{align*}
\Delta_n\xrightarrow[n\to\infty]{(d)}&\SL{i=3}^\infty\left(\tilde{C}_i\log(1+d^{-i})-\frac{d^i+1}{2i}\right)\\&+\log\int_\R\exp\left(\frac{y^2}{\sqrt{2(d-1)}}X-\left(\dfrac{1}{12}+\dfrac{1}{4(d-1)}\right)y^4\right)\ \text{d}y
\end{align*}
where the $\tilde{C}_i\sim\text{Pois}(\frac{d^i}{2i})$ are independent, and also independent of $X\sim N(0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 13 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $ \pi : E \longrightarrow B $ be a fiber bundle with fiber $S^{k}$ ($ k \geq 1 $), over a connected base $B$. 
        	Assume for simplicity that the bundle is oriented, so that the fibers carry a consistent orientation. In the Gysin sequence 
        	\begin{align*}
        	\cdots \longrightarrow H^{i}(B) \rightarrow H^{i}(E) \xrightarrow{ \ \delta_{i}  \ } H^{i-k}(B) \rightarrow H^{i+1}(B) \longrightarrow \cdots,
        	\end{align*}
        	we call $\delta_{i}:H^{i}(E) \longrightarrow H^{i-k}(B)$ \textbf{the connecting homomorphism in degree $i$}.

[Definition 2 of arXiv:2604.19220, 'Split merge dynamics for expanding intervals and point processes on the real line.'] Define a random process $(\tau_n)_{n\geq1}$ as
    \begin{equation}
        \tau_n=\begin{cases}
        0&\text{if } \ \forall k\leq n, \ \epsilon_k=0,\\
        \max\{k\leq n : \epsilon_k=1\}&\text{o/w }
    \end{cases}
    \end{equation}

[Cor one:step:error of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:derv:liningam of the paper)} hold, then  for $ 2\leq p_0\leq \min\{{\bar p}/((\eta+1)(\eta/8+1))\color{black},\bar p/2\}$
		\begin{align*}
			E|x_s^{i,N,n}-x_{\kappa_{n}(s)}^{i,N,n}|^{p_0}\leq Kn^{-1}
		\end{align*}
	  for any   $s\in[0,T]$ and $i\in\{1,\ldots,N\}$   where $K>0$ is independent of $N$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2604.05910, '\textbf{Well-posedness and Hurst parameter estimation for fluid equations driven by fracti'] Let $\omega\in V^T$ and $\xi\in \cB_\infty$. Then for every $\varphi\in \cB^*_{\alpha}$ we have 
    \begin{align*}
        \int\limits_0^t \langle \int_0^s S_{r-s}(\xi \cdot \nabla \omega_r)~\txtd W^H_r ,\varphi\rangle ~\txtd s = \int_0^t \int_r^t \langle S_{r-s} (\xi \cdot \nabla \omega_r),\varphi  \rangle~\txtd s ~\txtd W^H_r.
    \end{align*}

