[Lemma 12 of arXiv:2607.25986, 'Asymptotics of a two-species particle system associated to the doubly parabolic Keller-Seg'] We fix $c_0 \in L^\infty(\R^2)\cap L^1(\R^2)$ and $\theta>0$, $\lambda>0$.
There exists a constant $A$ such that for all $t> 0$, all $x\in\R^2$, all $\e\in [0,1]$,
\begin{equation}
|K^{\theta,\lambda}_t(x)|\leq A (t+|x|^2)^{-1} \quad \text{and} \quad 
|(\phi_\e \ast K^{\theta,\lambda}_t)(x)|\leq A \int_{\R^2} (t+|x-\sqrt \e y|^2)^{-1} \phi(y)\dd y.
\end{equation}
For any $\alpha>0$, any $t>0$, any $x\in \R^2$, any $\e\in [0,1]$,
\begin{align}
|\nabla K^{\theta,\lambda}_t(x)|\leq &
C_3(\theta,\alpha)(t+\alpha |x|^2)^{-\frac{3}{2}}, \quad \text{where} \quad C_3(\theta,\alpha)=\frac{\sqrt \theta C_0\big(\frac{4\alpha}{\theta}\big)}{4\pi}, \\
|\nabla (\phi_\e \ast K^{\theta,\lambda}_t)(x)|\leq& 
C_3(\theta,\alpha)\int_{\R^2}(t+\alpha |x-\sqrt\e y|^2)^{-\frac{3}{2}}\phi(y)\dd y.

\end{align}
There exists $A>0$ depending on $\theta$, $c_0$ and $\phi$ such that for any $t>0$, any $\e\in [0,1]$,
\begin{equation}
||\nabla (\phi_{\e}\ast b^{c_0,\theta,\lambda}_t) ||_{L^\infty(\R^2)}\leq  A (\e+t)^{-\frac 1 2}.
\end{equation}
For all $t\geq 0$, it holds that
\begin{equation}
\lim_{\e\to 0}\int_0^t ||\nabla \phi_{\e}\ast b^{c_0,\theta,\lambda}_{s} - \nabla b^{c_0,\theta,\lambda}_{s}||_{L^\infty(\R^2)} 
\dd s=0.
\end{equation}
For all $s>0$, if $x_n\to x$ and $\e_n\to 0$, then
\begin{equation}
(\nabla \phi_{\e_n}\ast b^{c_0,\theta,\lambda}_{s})(x_n)\to \nabla b^{c_0,\theta,\lambda}_{s}(x).
\end{equation}

[Theorem e: Psi_q limit var of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d, \infty)$, assume that $K$ and $\Phi$ fulfill the general assumptions in this subsection, and assume that Condition~(c:condition square-integrable general with p of the paper) or Condition~(c:condition square-integrable Markov with p of the paper) holds. Further, define\linebreak $N:=\max(\lceil\frac{d+p}{2}\rceil, 1)$, and assume that there are $\gamma_1,..., \gamma_N\in\R$ with $\gamma_n\neq\gamma_m$ for\linebreak $n,m\in\{1,...,N\},n\neq m$ such that $K^{(\gamma_n)}\Phi$ is $p$-uniform for every $n\in\{1,..,N\}$. Then $K^{(\gamma)}\Phi$ is $p$-uniform for every $\gamma\in\R$, and as $r\to \infty$,
    \begin{equation}
        \frac{\BV\big[\Psi_q(f^{(q)}(\frac{\cdot}{r}))\big]}{r^d} = O\big(r^{-(p-2q)}\big), \quad q\in\N_0, q<\max(\tfrac{d+p}{2}, 1),
    \end{equation}
    with $\Psi_q$ defined as in Theorem~(t:main theorem of the paper) and $f$ chosen as in the first part of Theorem~(t:main theorem formula of the paper). The same holds with respect to beyond $p$-uniformity, where $O$ gets replaced by $o$ in~(equation e: Psi_q limit var of the paper).

    Alternatively, let $\varepsilon>0$, and assume that Condition~(c:condition square-integrable stealthy of the paper) is fulfilled. Further, assume that there is a sequence $(\gamma_n)_{n\in\N}$ in $[-1, 1]\setminus\{0\}$ such that $\gamma_n\to 0$ as $n\to\infty$, and such that $K^{(\gamma_n)}\Phi$ is $\infty$-uniform with radius $\varepsilon$ for every $n\in\N$. Then $K^{(\gamma)}\Phi$ is $\infty$-uniform with radius $\varepsilon$ for every $\gamma\in\R$ such that Condition~(c:condition square-integrable stealthy of the paper) is fulfilled with respect to $\tilde\varepsilon:=|\gamma|\varepsilon$, in particular $\gamma\in[-1,1]$. Additionally, $\Psi_q(f^{(q)})$ is deterministic for every $q\in\N_0$ with $f$ chosen as in the second part of Theorem~(t:main theorem formula of the paper).
    \begin{proof}
        Let $p\in[-d, \infty)$, and assume that Condition~(c:condition square-integrable general with p of the paper) or Condition~(c:condition square-integrable Markov with p of the paper) holds. Then, by Theorem~(t:main theorem formula of the paper),~(equation e: K gamma conversion of the paper), and with convergence in $L^2$, we have that
        \begin{equation}
        K^{(\gamma)}\Phi(f_r) = \sum_{q=0}^{N-1}\frac{\gamma^q}{q!} \Psi_q\big(f_r^{(q)}\big) + o\Big(r^{\tfrac{d-p}{2}}\Big),\quad \gamma\in\R,
    \end{equation}
    as $r\to\infty$. The remainder term also fulfills some regularity with respect to $\gamma$, but we do not need it here. Hence, if $K^{(\gamma_n)}\Phi$ is $p$-uniform for every $n\in\{1,..,N\}$ for some $\gamma_n\in\R$, then
    \begin{equation}
        \begin{pmatrix}
            1 & \gamma_1 & \gamma_1^2 & \cdots & \gamma_1^{N-1}\\
            \vdots&\vdots&\vdots&&\vdots\\
            1 & \gamma_N & \gamma_N^2 & \cdots & \gamma_N^{N-1}
        \end{pmatrix}
        \begin{pmatrix}
            \Psi_0(f_r)\\
            \Psi_1(f_r')\\
            \vdots\\
            \frac{1}{(N-1)!}\Psi_{N-1}\big(f_r^{(N-1)}\big)
        \end{pmatrix}
        = O\Big(r^{\tfrac{d-p}{2}}\Big)
    \end{equation}
    as $r\to\infty$. Since the matrix is a Vandermonde matrix, and therefore invertible, as the $\gamma_n$ are assumed to be pairwise different for $n\in\{1,..., N\}$ (see, e.g.,~[Horn_Johnson_1985]), this relation also implies that
    \begin{equation}
        \Psi_{n}\big(f_r^{(n)}\big) = O\Big(r^{\tfrac{d-p}{2}}\Big), \quad n\in\{0,...,N-1\}.
    \end{equation}
    Together with~(equation e: K gamma f_r decomposition of the paper) and Theorem~(t:asymptotic variance test function of the paper), we therefore obtain that $K^{(\gamma)}\Phi$ is $p$-uniform for every $\gamma\in\R$. Moreover, Remark~(r: f_r formulas of the paper) yields~(equation e: Psi_q limit var of the paper). Under the assumption of beyond $p$-uniformity, the same proof yields beyond $p$-uniformity of $K^{(\gamma)}\Phi$ for $\gamma\in\R$, and $O$ simply gets replaced by $o$, which (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:pn-trajectory-tree-bijection of arXiv:2607.24018, 'Jeu de taquin forests \\ and the inverse infinite RSK correspondence'] For each tree $\tau$ in $\Phi(T)$, its
	lifetime $n(\tau)$ is the unique positive integer $k$ such
	that the path $\gamma_k$, after removing a finite
	initial segment, lies entirely within $\tau$.

	Moreover, the asymptotic directions exist and coincide:
	\begin{equation} 
	\alpha_\textnormal{asym}(\tau)  = \alpha_\textnormal{asym}(\gamma_{n(\tau)}) =
	z_{n(\tau)}
	\end{equation}
	for all trees $\tau$ in $\Phi(T)$.

[Lemma lem:SBPformula of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Fix $m >0, \varepsilon>0$. For some $T > 0$, suppose $F$ is an element of $C^{0,1}([0,T] \times \mathbb{R})$ such that for all $c \in (0,\infty)$ and $T' \in (0,T)$, 
$$
\sup_{(s,y) \in [0,T'] \times \mathbb{R}} e^{cy^+} |e^{-m\sigma\varepsilon^{-1/4}y}F(s,y)| < \infty.
$$ 
For $i \in \mathbb{Z}$ and $s \in [0,\infty)$, let $Y_i^\varepsilon(s) = X_i^\varepsilon(s) + \sigma\varepsilon^{-1/4}s$. The following equality holds, for all $s \in [0,T)$,
\begin{equation} 
\begin{split}
& (1 - e^{-m\sigma\varepsilon^{1/4}}) \sum_{i \in \mathbb{Z}} e^{m\sigma\varepsilon^{1/4}i - m\sigma\varepsilon^{-1/4}Y_i^\varepsilon(s) + \frac{1}{2}m\sigma^2\varepsilon^{-1/2}s} F(s,Y_i^\varepsilon(s)) \\
& \hspace{1.5in} = \int_{\mathbb{R}} \mathcal{G}^\varepsilon(s,z)^m \left[ m\sigma\varepsilon^{-1/4} F(s,z) - \partial_z F(s,z) \right]dz,
\end{split}
\end{equation}
where the sums and integrals appearing above converge uniformly on compact subsets of $[0,T)$ in $L^r(\mathbb{P})$ for all $r \in [1,\infty)$.

