[Mylem Lem_decoupling of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] Let $F$ be a convex function satisfying $F(x)=F(-x), \forall x\in \mathbb{R}$.  Assume $\xi=(\xi_{1}, \cdots, \xi_{n})^\top$ and $ \eta=(\eta_{1}, \cdots, \eta_{n})^\top$ are random vectors with independent centered entries. Let for any $t>0$ and $i\ge 1$, the independent random variables $\xi_{i}, \eta_{i}$ satisfy for  some $c\ge 1$
	\begin{align}
		\textsf{P}\{ \xi_{i}^{2}\ge t \}\le c\textsf{P}\{ c\vert \eta_{i}\tilde{\eta}_{i}\vert\ge t \},\nonumber
	\end{align}
	where $\tilde{\eta}_{i}$ is an independent copy of $\eta_{i}$. 
	Then, there exists a constant $C$ depending only on $c$ such that
	\begin{align}
		\textsf{E}\sup_{A\in \mathcal{A}}F\big(\xi^\top A\xi-\textsf{E}\xi^\top A\xi\big)\le \textsf{E}\sup_{A\in \mathcal{A}}F\big( C\eta^\top A\tilde{\eta}\big)\nonumber
	\end{align}
	where  $\mathcal{A}$ is a set of $n\times n$ fixed matrices. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:Jensen polynomial convergence of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $f\in\mathcal{LP}_{\infty}$. Then, $f\in\mathcal{LP}$ if and only if $A_{n,f}$ has only real roots for every $n\geq 0$. Moreover,  uniformly on compact subsets, \begin{equation}
	\lim\limits_{n\rightarrow\infty}J_{n,f}\left(\frac{z}{n}\right)=f(z).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor permutation of arXiv:2602.22342, 'Sum of Gaussian vectors and large sets'] There is a universal integer $q>0$ such that if $A$ is a permutation invariant, closed set in $\R^n$ with $\gamma_n(A)\geq \frac{2}{3}$, then there is a  permutation invariant convex body $K$ in $\R^n$ with 
$$\gamma_n(K)\geq\frac{1}{2}
\quad \text{and}\quad  K\subset  \underbrace{\vphantom{\Big|}A+\cdots+A}_{q\ \text{times}}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:R transform definition of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\mu$ be a probability measure on $\mathbb{R}$. The \emph{Cauchy transform} $G_{\mu}:\mathbb{C}_{+}\to\mathbb{C}_-$ of $\mu$ is the analytic function 
\begin{equation}
		G_{\mu}(z):=\int_{\mathbb{R}}\frac{1}{z-t}\mathrm{d}\mu(t).
	\end{equation} 
	 For $\alpha,\beta>0$, set $\Gamma_{\alpha,\beta}=\{z:\alpha\operatorname{Im}(z)>|\operatorname{Re}(z)|,\ \operatorname{Im}(z)>\beta \}$, and $\Delta_{\alpha,\beta}=\{z:z^{-1}\in\Gamma_{\alpha,\beta}\}$.
	 For every $\alpha>0$ there exists $\beta>0$ and the so-called $R$-\emph{transform} $R_{\mu}\colon\Delta_{\alpha,\beta}\rightarrow\mathbb{C}$ satisfying \begin{equation}
		G_\mu\left(R_{\mu}(z)+\frac{1}{z}\right)=z,\text{ for all }z\in\Delta_{\alpha,\beta},
	\end{equation}  and \begin{equation*}
		R_{\mu}\left(G_{\mu}(z)\right)+\frac{1}{G_{\mu}(z)}=z,\text{ for all }z\in\Gamma_{\alpha,\beta}.
	\end{equation*}

[Lemma lem_extra_path3 of arXiv:2506.06559, 'Bi-infinite incipient cluster in high dimensions'] Let $x\in\mathbb{Z}^d$, $W\subset \mathbb{Z}^d$, let {{$E \subset \mathcal{E}_D$}} and $z\in V(E)$. Then 

\begin{align*}
\{E\text{ is occupied}\}\cap \{W \leftrightarrow y\} 
\subset ( \{E\text{ is occupied}\}\circ \{y \longleftrightarrow E\} )
\cup (\{E\text{ is occupied}\}\circ \{W \leftrightarrow y\}).
\end{align*}

