[Theorem thm:gtp-quant-clt of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\mathcal{Y},\hat\mathcal{Z},n)$
  with $\mathcal{Y}\subseteq\mathbb{R}$ satisfy Condition~(cond:usa-minimax of the paper).
  Let $\overline V_n = \sum_{t=1}^n \overline{\textsf{\textbf{E}}}[Y_t^2 | Y_{1..t-1}]$ and
  $\underline V_n = \sum_{t=1}^n \underline{\textsf{\textbf{E}}}[Y_t^2 | Y_{1..t-1}]$ be real-valued, and let $X_n = \sum_{t=1}^n Y_t$.
  Suppose that for constants $M$, $C$, and $D$ we have

  \begin{equation}

    \max_{t\leq n} |Y_t| \leq n^{-1/2} M \quad \text{g.t.a.s.}~,
  \end{equation}
  and
  \begin{equation}

    \overline{\textsf{\textbf{P}}}\left[ \max(1- \underline V_n, \overline V_n - 1) > 9M^2 D n^{-1/2} (\log n)^2 \right] \leq C n^{-1/4} / (\log n)~.
  \end{equation}
  Then for $n \geq 2$,
  \begin{equation}

    \sup_{-\infty < x < \infty} \max\left( \overline{\textsf{\textbf{P}}}(X_n \leq x) - \Phi(x), \Phi(x) - \underline{\textsf{\textbf{P}}}(X_n \leq x)\right) \leq (2 + C + 7 M D^{1/2}) n^{-1/4} \log n~.
  \end{equation}

[Lemma lem:good-event of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] There are constants $c,C>0$ such that
\begin{equation}
 \mathbb P(\mathcal G_N^c)\le Ce^{-cN^{2\delta}}.
\end{equation}
In particular, $\mathcal G_N^c$ is superexponentially small at every speed
appearing in (thm:main of the paper).

[Prop 23 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $n^*$ be defined as in (\ref{smallestnsatisfy}) for every $n\geq 1$. For any $\mathbf{\lambda} = [\lambda_1,\lambda_2,...] \in \mathcal{Q}$, define $\T^{(1)}(\mathbf{\lambda})$ as follows:
\begin{equation}

\T^{(1)}_{n,j}(\lambda_n) =
\begin{cases}
\T^{(1)}_{n,j} & n < n^* \, ,\, 1 \leq j \leq n+1 \\ 
\notag\\
\T^{(1)}_{n,j} - \lambda_n\T^{(1)}_{n,1} & n \geq n^* \, ,\, 1 \leq j \leq n  \\
\notag \\
\T^{(1)}_{n,j} + n\lambda_n\T^{(1)}_{n,1} & n \geq n^* \, ,\, j = n+1  \\
\end{cases}
\end{equation}
for every $n\geq 0$ and $1\leq j \leq n+1$. Then $\T^{(1)}(\mathbf{\lambda}) \in \mathcal{M}^{\infty}$ for any $\lambda\in\mathcal{Q}$.

