[Proposition def:couplingmatrices of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Define the transformation matrix 
    \begin{equation*}
        R = \begin{pmatrix}
             \mathfrak{c}_1 & 1 \\
             \mathfrak{c}_2 & 1
        \end{pmatrix}\qquad \Longleftrightarrow\qquad R^{-1} = \frac{1}{\mathfrak{c}_1 - \mathfrak{c}_2}\begin{pmatrix}
            1 & -1 \\
            -\mathfrak{c}_2 & \mathfrak{c}_1
        \end{pmatrix}.
    \end{equation*}
    so that $R\mathbf{J}R^{-1}=\mathrm{diag}(\lambda_1,\lambda_2)$. Define also the coupling matrices 
    \begin{equation}
        \mathbf{G}^i = \frac12 (R^{-1})^\top (\mathfrak{c}_i\mathbf{H}^1+\mathbf{H}^2)R^{-1} 
    \end{equation}
    for $i\in\{1,2\}$. Then, for any $\varphi\in\mathscr{S}(\mathbb{R} )$, any $t\in [0,T]$ and any $\varepsilon >0$, the term $\mathscr{B}_t^{N,i,\varepsilon}(\varphi )$ rewrites as 
    \begin{align}
        \mathscr{B}_t^{N,i,\varepsilon}(\varphi ) & = N^{a-\gamma -\frac32} \mathbf{G}_{11}^i\int_0^t\frac1N \sum_{x\in\mathbb{Z}} \mathcal{Z}_s^{N,1}\left( \iota_\varepsilon \big( \cdot\, ;\tfrac{x-(v_1-v_i)N^as}{N} \big)\right)^2 \nabla_N\varphi\Big( \frac xN\Big)\,\mathrm{d} s \\
        & \quad +N^{a-\gamma-\frac32}(\mathbf{G}_{12}^i +\mathbf{G}_{21}^i)\int_0^t\frac1N\sum_{x\in\mathbb{Z}} \mathcal{Z}_s^{N,1}\left(\iota_\varepsilon \big( \cdot\, ; \tfrac{x-(v_1-v_i)N^as}{N}\big)\right) \notag \\
        & \hspace{6cm}\times \mathcal{Z}_s^{N,2}\left(\iota_\varepsilon \big(\cdot\, ; \tfrac{x-(v_2-v_i)N^as}{N}\big)\right) \nabla_N\varphi\Big( \frac xN\Big)\,\mathrm{d} s \\ 
        & \quad + N^{a-\gamma -\frac32} \mathbf{G}_{22}^i\int_0^t \frac1N\sum_{x\in\mathbb{Z}} \mathcal{Z}_s^{N,2}\left(\iota_\varepsilon \big(\cdot\, ; \tfrac{x-(v_2-v_i)N^as}{N} \big)\right)^2 \nabla_N\varphi\Big( \frac xN\Big)\,\mathrm{d} s 
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

