[Lemma l:Bessel_property of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Let $B$ be a ball of radius $\varrho\leq 1/2$. Then, for all $f\in L^2(B;{\mathbb R}^d)$ and $\delta\in (0,1]$, 
\begin{equation}

\sum_{k,\alpha} \Big|\int_{B} 
 \sigma^{\delta}_{k,\alpha} \cdot f   \Big|^2
\leq \delta^{-d} \|f\|_{L^2(B)}^2.
\end{equation}
In particular, there exists a constant $C$ such that, for all $N\geq1$, $\delta\in (0,1]$, balls $B$ of radius at most $1/2$, and $f\in L^2(B;{\mathbb R}^d)$, 
\begin{equation}

\sum_{k,\alpha}(\theta_k^N)^2 \Big|\int_{B} 
 \sigma^{\delta}_{k,\alpha} \cdot f  \Big|^2
\leq \frac{C}{(\delta N)^d }  \|f\|_{L^2(B)}^2.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] \begin{enumerate}
    \item For any permutation $\tau\in\Sigma_4$,
\[
\Delta_4(\alpha_{\tau(1)},\alpha_{\tau(2)},\alpha_{\tau(3)},\alpha_{\tau(4)})=(-1)^\tau\Delta_4(\alpha_1,\alpha_2,\alpha_3,\alpha_4);
\]
    \item $\Delta_4(-\alpha_1,\alpha_2,\alpha_3,\alpha_4)=-\Delta_4(\alpha_1,\alpha_2,\alpha_3,\alpha_4)$.
\end{enumerate}

