[Lemma of arXiv:2608.25065, 'Detection of first homology via random geometric graphs in the thermodynamic regime'] \label[lemma]{downward connection lower bound}
    If $\lambda_- > \lambda_c$, then for any $Q$ we have
    \[
        \mathbb{P}\left( 
        \begin{array}{c}
        z_0 + [-a/2,a/2] \mbox{ is connected to } \\
        B(z_0,Q\log R)^c 
        \mbox{ by a path in } \mathcal{H}
        \end{array}
        \right) \ge c_0
    \]
    where $c_0>0$ is as above.

[Proposition 14 (Lamperti representation and exact occupation threshold) of arXiv:2608.30178, '2608.30178'] Assume that
\begin{equation}
 r_{10}\ge1,
 \qquad b_{11}=0\ \text{or}\ r_{11}=r_{10}+1,
 \qquad b_{12}=0\ \text{or}\ r_{12}=\alpha_1+r_{10}-1,

\end{equation}
and \(b_{10}>0\).  Let \(G\) be the positive solution of
\begin{equation}
 \dd G_t=G_{t-}\left[-b_{10}\dd t+\sqrt{2b_{11}}\dd B_t
 +\int_0^\infty w\,\widetilde M(\dd t,\dd w)\right],
 \qquad G_0=x,

\end{equation}
where \(M\) has compensator \(b_{12}\dd t\,\mu_1(\dd w)\).  Let
\begin{equation}
 T(u):=\int_0^uG_v^{1-r_{10}}\dd v.

\end{equation}
Then \((G_{T^{-1}(t)})_{t\ge0}\) has the same law as \(\Xlow\), and the
equality can be realized pathwise on the canonical construction.  If
\(r_{10}>1\), then
\begin{equation}
 \lim_{t\to\infty}\frac{\log\Xlow_t}{\log t}=-\frac1{r_{10}-1}
 \qquad\text{almost surely},

\end{equation}
and, for every \(q>0\),
\begin{equation}
 \int_0^\infty\Xlow_t^q\dd t<\infty
 \quad\Longleftrightarrow\quad q>r_{10}-1.

\end{equation}
For \(r_{10}=1\), the time change is the identity.

