body:
[Thm thm_1 of arXiv:2503.22334, 'Probabilistic analysis of optimal multi-pivot QuickSort'] Let $K\in {\mathbb N}$ and $\lambda\in \mathbb{R}$. For the normalization $Y_n:=(X_n-{\mathbb E}\left[X_n\right])/n$ as $n\to\infty$ we have 
\begin{align*}
   Y_n&\stackrel{d}{\longrightarrow} Z_K,\\
   {\mathbb E}\left[\exp(\lambda Y_n)\right] &\longrightarrow {\mathbb E}\left[\exp(\lambda Z_K)\right]<\infty,
\end{align*}
where the distribution of $Z_K$ is determined as the unique centered, square integrable probability measure such that
\begin{align}
Z_K \overset{\text{d}}{=} \sum_{i=0}^{K} \kl*{D_i Z_K^{(i)}+\alpha_K D_i \ln\left(D_i\right)}+l_{\mathrm{opt}}(D),
\end{align}
where $D,Z_K^{(0)},\dots,Z_K^{(K)}$ are independent and $Z_K^{(i)}$ has the same distribution as $Z_K$ for all $i=0,\dots,K$.
Moreover, we have moments convergence, i.e., all moments of $Y_n$ converge to the moments of $Z_K$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 28 of arXiv:2609.01473, 'Keller sequences of exact $\infty$-categories'] Given a nullcomposite sequence
	\[\begin{tikzcd}
		\cal{A} \ar[r] \ar[d] & \cal{C} \ar[d] \\
		0 \ar[r] & \cal{B}
	\end{tikzcd}\]
	of exact categories, the following are equivalent:
	\begin{enumerate}[label=(\roman*)]
		\item $i$ is a Keller inclusion and $p\colon \cal{C} \to \cal{B}$ is the cofibre of $i$ in $\exact$;
		\item $p$ is a Keller projection and $i\colon\cal{A} \to \cal{C}$ is the kernel of $p$ in $\exact$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:Free convolution theorem of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\{f_n\}_{n=1}^{\infty}\subset\mathcal{LP}$ and satisfy Assumption (assump:main assumption of the paper). If $t\geq 0$ and $\{p_n\}_{n\geq 1}$ is a sequence of real-rooted polynomials indexed by their degree such that $\llbracket p_n\rrbracket\Rightarrow\mu$ weakly as $n\rightarrow\infty$, then \begin{equation}
		\llbracket f_{\lfloor tn\rfloor}\left(t\partial_{z}\right)p_n(z)\rrbracket\Rightarrow \mu\boxplus\mu_{c,\Sigma}^{\boxplus t},
	\end{equation} where $\boxplus$ is the free convolution of probability measures. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition useful-prop of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] Suppose $B\subseteq {\cal I}$ is an interval with $g(x)<f(x)$ for all $x\in B$.
\begin{enumerate}[(i)]

\item  Let  
\begin{align*}
A_t:= \int_0^t \frac{1}{f(X_s)-g(X_s)}\mathbb{I}_{\{X_s\in B\}}dC_s^{-}(g), \enskip t \geq 0. 
\end{align*}
Then $A_t<\infty, t < \tau^{\partial B}$ a.s. (while it may occur that $A_{\tau^{\partial B}}=\infty$) and with $\tau_{A}:=\inf\{t\geq 0: A_t\geq E_1\}$ it holds, for all $x \in B$ and $\tau_2 \in \mathbb{T}_2$, that
\begin{align*}
& g (x)\\
& \leq \E_x\left(e^{-r(\tau_A \wedge \tau_2)} \left(
f(X_{\tau_A})\mathbb{I}{\{\tau_A<\tau_2\}} + g(X_{\tau_2})\mathbb{I}{\{\tau_A>\tau_2\}} + h(X_{\tau_2})\mathbb{I}{\{\tau_2=\tau_{A}\}}\right)\mathbb{I}{\{\tau_2 \wedge \tau_A < \tau^{\partial B}\}}\right)\\
& + \E_x\left(e^{-r\tau^{\partial B}}  g(X_{\tau^{\partial B}}) \mathbb{I}{\{\tau_A \wedge \tau_2 \geq  \tau^{\partial B}\}}\right).
\end{align*}
Moreover, if $g$ is twice continuously differentiable except on a countable set of separated points $x_j \in {\cal I},j \in J$ (where $J$ is an index set), then
\begin{align*}
A_t = \int_0^t\left(\frac{(\mathbb{L}_X-r)g(X_s)}{g(X_s)-f(X_s)}\right)_+\mathbb{I}_{\{X_s \in B, X_s \neq x_j,\forall j\}}ds + \frac{1}{2}\sum_{j} \mathbb{I}_{\{x_j \in B\}}\left(\frac{g'(x_j+)-g'(x_j-)}{{g(x_j)-f(x_j)}}\right)_+l_t^{x_j}, \enskip t \geq 0.
\end{align*}

\item Let 
\begin{align}
A_t:= \int_0^t \frac{1}{f(X_s)-g(X_s)}\mathbb{I}_{\{X_s\in B\}}dC_s^{+}(f), \enskip t \geq 0. 
\end{align}
Then $A_t<\infty, t < \tau^{\partial B}$ a.s. (while it may occur that $A_{\tau^{\partial B}}=\infty$) and with $\tau_{A}:=\inf\{t\geq 0: A_t\geq E_2\}$ it holds, for all $x \in B$ and $\tau_1 \in \mathbb{T}_1$, that
\begin{align*}
\begin{split}
& f (x)\\
& \geq \E_x\left(e^{-r(\tau_1 \wedge \tau_{A})} \left(
f(X_{\tau_1})\mathbb{I}{\{\tau_1<\tau_{A}\}} + g(X_{\tau_{A}})\mathbb{I}{\{\tau_1>\tau_{A}\}} + h(X_{\tau_1})\mathbb{I}{\{\tau_1=\tau_{A}\}}
\right)\mathbb{I}{\{\tau_1 \wedge \tau_{A} < \tau^{ \partial B }\}}\right)\\
& + \E_x\left(e^{-r\tau^{\partial B}}  f(X_{\tau^{\partial B}}) \mathbb{I}{\{\tau_1 \wedge \tau_{A} \geq  \tau^{\partial B}\}}\right).
\end{split}
\end{align*}
Moreover, if $f$ is twice continuously differentiable except on a countable set of separated points $x_i \in {\cal I}, i \in I$ (where $I$ is an index set) then
\begin{align*}
A_t =  \int_0^t\left(\frac{(\mathbb{L}_X-r)f(X_s)}{f(X_s)-g(X_s)}\right)_+\mathbb{I}_{\{X_s \in B, X_s \neq x_i,\forall i\}}ds + 
\frac{1}{2}\sum_{i} \mathbb{I}_{\{x_i \in B\}} \left(\frac{f'(x_i+)-f'(x_i-)}{{f(x_i)-g(x_i)}}\right)_+l_t^{x_i}, \enskip t \geq 0.
\end{align*}



\end{enumerate}

