body:
[Proposition 29 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Fix any $\sigma \in(0,1/10)$ and let~$X_0,X_1,\dots$ be a random walk with step distribution~$\NN(0,1/2)$. For each~$\epsilon\in(0,1)$ and each $\delta\in(0,1)$ there exists~$a_0=a_0(\epsilon,\delta)\ge1$ 
such that for all $a\ge a_0$, all naturals $k\ge2$ and all reals~$r,u$ satisfying
\begin{equation}

r,u\ge a^{1/\sigma}\quad\text{\rm and}\quad ru\le k^{1-\delta}
\end{equation}
and all~$\gamma\colon\{0, \dots,k\}\to\R$ obeying
\begin{equation}

\bigl|\gamma(i)\bigr|\le a+\bigr(\min\{i,k-i\}\bigr)^{\sigma},\quad i=0,\dots,k, 
\end{equation}
we have
\begin{equation}

(1-\epsilon)\frac{4ru}k\le
E\biggl(\,\prod_{j=1}^{k-1}1_{\{X_j\ge\gamma(j)\}}\,\bigg|\, X_0=r,\,X_k=u\biggr)\le(1+\epsilon)\frac{4ru}k.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def1 definition:debut of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] A point $u \in \mathcal{T}_{H(\upvarrho)}$ is called an excursion debut for $(\widehat{\omega}_a)_{ a\in \mathcal{T}_{H(\upvarrho)}}$ if the following properties hold: 
    \begin{enumerate}
        \item[\emph{(i)}] We have  $\widehat{\omega}_u = x$;
        \item[\emph{(ii)}] We can find $v \succeq u$ such that $\widehat{\omega}_a\neq x$ for every $a$ in  $\rrbracket u,v \llbracket$. 
    \end{enumerate}
    We denote the collection of excursion  debuts by $\mathcal{D}(\upvarrho, \omega)$. For every $u \in \mathcal{D}(\upvarrho, \omega)$,  we write  $\mathcal{C}_u(\upvarrho, \omega)$ for the subset of points $v \in \mathcal{T}_{H(\upvarrho)}$ fulfilling that $v \succeq u$ with  $\widehat{\omega}_a \neq x$ for every $a \in \, \rrbracket u,v \llbracket$ and we set
\begin{equation*}
    \mathcal{C}^\circ_u(\upvarrho, \omega) := \mathcal{C}_u(\upvarrho, \omega) \cap \{ a \in \mathcal{T}_{ H(\upvarrho) } : \widehat{\omega}_a \neq x \}. 
\end{equation*}

[Proposition 9 (Stable convergence of \(Z^n\)) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[proposition]{prop:ll_forcing_stable_limit_new}
Assume that \(f\in C^3(\mathbb R^d;\mathbb R^d)\), and let \(Z\) be the
process defined in \eqref{eq:ll_Z_limit_reduction_section}.  Then
\begin{equation}
    Z^n
    \Rightarrow^{\mathrm{st}}
    Z
\end{equation}
in \(C([0,1],\mathbb R^d)\).

[Lemma 14 of arXiv:2605.17296, 'Zero correlations and averaged fields of orthonormal Gaussian Functions'] For $n, n' \in \N_0$ and $z,w \in \C$, 
\begin{equation}
\E \left[ f_{n}(z,\bar{z})\overline{f_{n^{\prime }}(w,\wbar)}
\right] =(-1)^{n^{\prime }+n}H_{n^{\prime
},n}(w-z,\wbar-\zbar) e^{z\wbar}. 

\end{equation}
In particular, $\{e^{-|z|^{2}/2}f_{k}(z,\bar{z})\}_{k=0}^{\infty }$ are
i.i.d. complex Gaussian random variables with zero mean and
unit variance.

