[Lem giant-is-unique of arXiv:2606.01627, 'The geometry of the giant component of random geometric graphs'] Let $\lambda_0 > \lambda_c$.  Then there are constants $C = C(\lambda_0,M) > 0, c = c(\lambda_0,M) > 0$ so that for all $\lambda \geq \lambda_0$ and $r\phi \leq  c$ we have \begin{equation*}
            \mathbb{P}\left(
        \begin{array}{c}
            \mbox{Exactly one component of } G_M^n(r) \\
            \mbox{ has }d_M\mbox{-diameter at least } r\phi
        \end{array}
        \right) \geq 1- C r^{-d}\exp(-c\phi)\,.
        \end{equation*}

[Definition Cumu of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] The joint cumulants of mixed Chebyshev  moments are defined recursively by
    \begin{equation}
        \begin{gathered}
            \kappa_X(n_1)=\mathbb{E}\!\Big[\mathrm{Tr}\big(U_{n_1}(\tfrac{X}{2})\big)\Big],\\
            \kappa_X(n_1,n_2)=\mathbb{E}\!\Big[\mathrm{Tr}\big(U_{n_1}(\tfrac{X}{2})\big)\mathrm{Tr}\big(U_{n_2}(\tfrac{X}{2})\big)\Big]-\kappa_X(n_1)\kappa_X(n_2),\\
            \cdots\\
            \kappa_X(n_1,\dots,n_s)=\mathbb{E}\!\Big[\mathrm{Tr}\big(U_{n_1}(\tfrac{X}{2})\big)\mathrm{Tr}\big(U_{n_2}(\tfrac{X}{2})\big)\cdots\mathrm{Tr}\big(U_{n_s}(\tfrac{X}{2})\big)\Big]-\sum_{\Pi}\prod_{P\in\Pi}\kappa_X\big(\{n_j\}_{j\in P}\big),
        \end{gathered}
    \end{equation}
    where the sum runs over all nontrivial partitions $\Pi$ of $[s]$, i.e., excluding the partition $[s]$ itself.

