u_{2k}$ to $
u_{2k+1}$ {$($}resp. $
u_{2k-1}${$)$} in Theorem (thm:local-convergence of the paper) (iii). Then there exists $t_k\in \mathbb R$ such that, for all $t\leq t_k$,
     egin{equation*}

u^{k,\uparrow}_{t}\leq_{\mathrm{st}} \omega ig(B(\delta_{a_{k+1}},r_{k+1}) ig), \  	ext{ {$ ig($}resp. $
u^{k,\downarrow}_{t}\geq_{\mathrm{st}} \omega ig(B(\delta_{a_k},r_k) ig)${$ ig)$}}. 
    \end{equation*}

[Lemma lem:green-kernel-regularity-package of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] There exists a constant
$C_D\ge1$ such that
\begin{equation}
 0\le G_D(z,w)
 \le C_D+\log^+\frac1{|z-w|},
 \qquad z,w\in D.
\end{equation}
Away from the diagonal, the Green kernel is locally uniformly continuous in
its first variable.  More precisely, for every compact $K\Subset D$ and every
$r_\ast>0$,
\begin{equation}
 \begin{aligned}
 \omega_{K,r_\ast}(\delta)
 &:=\sup_{\substack{z,z'\in K,\ |z-z'|\le\delta\\
                    w\in D,\ |z-w|\ge r_\ast,\ |z'-w|\ge r_\ast}}
    |G_D(z,w)-G_D(z',w)|,
    \qquad \delta>0,\\
 \omega_{K,r_\ast}(\delta)
 &\xrightarrow[\delta\downarrow0]{}0.
 \end{aligned}
\end{equation}

[Lemma 18 of arXiv:2608.18075, '2608.18075'] For $z\in\mathsf X$ and $h\in E_z$, define
\begin{align*}
 u_{z,h}(\omega)
 =-K_q(z,Y(\omega))h
 =-\sum_i\chi_i(z,Y(\omega))K_i(z)h.
\end{align*}
Then $(z,h,\omega)\mapsto u_{z,h}(\omega)$ is Borel and, for every fixed
$(z,h)$,
\begin{align*}
 u_{z,h}\in\mathbb D^{1,p}(\mathcal H)
 \qquad\text{for every finite }p.
\end{align*}
In addition,
\begin{align}
 \|u_{z,h}\|_{\mathcal H}
 +\|D_{\mathcal H}u_{z,h}\|_{\HS}
 &\le C_q\|h\|,
 \\
 \|D_{\mathcal H}u_{z,h}\|_{\rm op}
 &\le C_q\|h\|.

\end{align}
Furthermore, 
\begin{align}
 Y\bigl(\omega+\mathbf u_{z,h}(\omega)\bigr)
 =
 Y(\omega)-\Gamma K_q(z,Y(\omega))h,
\end{align}
and whenever $\|h\|\le(2C_q)^{-1}$,
\begin{align}
 (T_{z,h})_\#\mathbf P&\sim\mathbf P,\notag\\
 \operatorname{Ent}\bigl((T_{z,h})_\#\mathbf P\mid\mathbf P\bigr)
 &\le C_{\rm Ram}\|h\|^2,
\end{align}
where
\begin{align*}
 T_{z,h}(\omega)
 =\omega+\mathbf u_{z,h}(\omega).
\end{align*}

