[Definition def:freezing-ising of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] For any $B\in \R$, the ferromagnetic Ising measure on $T^\k$ with freezing temperature and 
         plus/minus boundary condition are defined as follows: 
    \begin{equation}
        \ising_\k^+(\infty,B)=\ising_\k^+(\infty)\coloneqq \delta_{T^{\k,+}},\quad \ising_\k^-(\infty,B)=\ising_\k^-(\infty)\coloneqq \delta_{T^{\k,-}}.
    \end{equation}

         In the antiferromagnetic regime, for any $B\in \R$, extend the definition of the unique $\TIS$ Ising measure $\ising_\k^\sharp$ to the following antiferromagnetic Ising measure on $T^\k$ with freezing temperature: 
    \begin{equation}
        \ising_\k^{\sharp}(-\infty,B)=\ising_\k^{\sharp}(-\infty)\coloneqq \frac{1}{2}\delta_{T^{\k,\pm}}+\frac{1}{2}\delta_{T^{k,\mp}}.
    \end{equation}

[Lem 52 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $x\in \Lambda_n$ and $y\sim x$. One has
\begin{equation}
	\mathbf P^{\emptyset}_{\beta_c}[y\connect{\mathcal M_n\:}\mathbb H_n]=\langle \sigma_y\sigma_{\mathcal R_n(y)}\rangle_{\beta_c},
\end{equation}
and
\begin{equation}
    \mathbf E^{\emptyset}_{\beta_c}\Big[\mathds{1}\{0,x\in \mathcal{S}_n,\: y \xleftrightarrow[]{\:\mathcal M_n\:} \mathbb H_n \}\langle\sigma_0\sigma_x\rangle_{\mathcal{S}_n,\beta}\Big]
    \leq
   \Big(\langle \sigma_0\sigma_x\rangle_{\beta_c}-\langle \sigma_0\sigma_{\mathcal{R}_n(x)}\rangle_{\beta_c}\Big)\langle \sigma_y \sigma_{\mathcal{R}_n(y)}\rangle_{\beta_c}.
\end{equation}

[Lemma lem:S6V-dressing of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The kernel $K_{t,x,m}$ satisfies the rank-one
difference identities
\begin{align}
K_{t,x,m-1} - K_{t,x,m}
&= \psi_{t,x,m-1}\phi_{t,x,m-1},
 \\
K_{t,x+1,m-1} - K_{t,x,m}
&= \psi_{t,x,m-1}\phi_{t,x+1,m-1},
 \\
K_{t-1,x,m-1} - K_{t,x,m}
&= \psi_{t,x,m-1}\phi_{t-1,x,m-1}.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def spin models of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\rho$ be an admissible measure on $\mathbb{R}$. The corresponding real-valued spin model on a finite subset $\Lambda\subset \mathbb Z^d$, with coupling constants $J=\{J_{xy}\}_{xy\in \overline E(\Lambda)}\in (\mathbb{R}^+)^{\overline E(\Lambda)}$, external magnetic field $\mathsf h=\{\mathsf h_x\}_{x\in \Lambda}\in \mathbb{R}^\Lambda$, boundary condition $\eta\in \mathbb{R}^{\partial^{\textup{ext}}\Lambda}$, and inverse temperature $\beta \geq 0$, is defined as the probability measure $\nu^\eta_{\Lambda,\beta,J,\mathsf h}$ on $\mathbb{R}^{\overline{\Lambda}}$ given by
\begin{multline}
\mathrm{d}\nu^\eta_{\Lambda,\beta,J,\mathsf h}(\tau) = \frac{1}{\mathbf{Z}^\eta_{\Lambda,\beta,J,\mathsf h}} \exp\Big(\beta \sum_{xy\in \overline{E}(\Lambda)} J_{xy} \tau_x \tau_y + \beta \sum_{x\in \Lambda} \mathsf h_x\tau_x  
\Big)\prod_{x\in \Lambda}\mathrm{d}\rho(\tau_x) \prod_{x \in \partial^{\textup{ext}} \Lambda} \delta_{\eta_x}(\tau_x),
\end{multline}
where $\mathbf{Z}^\eta_{\Lambda,\beta,J,\mathsf h}$ is a normalisation constant, and where $\delta_t$ is the Dirac measure at $t\in \mathbb R$. We will denote by $\langle f \rangle^\eta_{\Lambda,\beta,J,\mathsf h}$ the expectation of a function $f:\mathbb{R}^{\overline{\Lambda}}\rightarrow \mathbb R$ with respect to $\nu^\eta_{\Lambda,\beta,J,\mathsf h}$. When $J\equiv 1$, $\eta\equiv 0$ or $\mathsf{h}\equiv 0$, we may drop them from the notation.

[Prop 20 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] There is a one-to-one correspondence 
\begin{multline*}
\left\{ \begin{array}{c}
\text{strictly positive normalized}\\
\text{range martingales }X=\left\{ X_{w}\right\} _{w}\text{ for }E
\end{array}\right\} \\
\Longleftrightarrow\left\{ \begin{array}{c}
\text{POVMs }F\text{ on }\Omega_{m}\text{ such that}\\
aE\leq F\leq bE\text{ for some }0<a\leq b<\infty
\end{array}\right\} .
\end{multline*}
The correspondence is given on cylinders by 
\begin{equation}
F\left(\left[w\right]\right)=E^{1/2}_{w}X_{w}E^{1/2}_{w}.
\end{equation}

