[Lemma restr-inj-gl-sp-left-Quillen of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\alpha\colon G\to G'$ be an \emph{injective} homomorphism of compact Lie groups. Then
    \[
        \alpha^*\colon\cat{$\bm{G'}$-OrthSp}_\textup{$G'$-global}\rightleftarrows\cat{$\bm{G}$-OrthSp}_\textup{$G$-global}
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 \alpha_*
    \]
    is a Quillen adjunction.
    \begin{proof}
        Thanks to the previous lemma, it only remains to show that $\alpha^*$ preserves (level) cofibrations, or equivalently that $\alpha_*$ preserves level acyclic fibrations. This follows at once by applying Example~(ex:graph-restr-lQ of the paper) levelwise.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma RAND_MEASURE of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Suppose that $\varphi$ is an SDS with an invariant measure $\mu$.
	Then, there exists a set $\tilde{\mathcal{B}} \subseteq \mathcal{B}$ of full measure and a family of random measures $\{{\mu}_{\omega^-}\}_{\omega^- \in \mathcal{B}}$ such that, for every $A \times C \in \sigma(\mathcal{X}) \otimes \sigma(\mathcal{B})$, the following properties hold:
	\begin{enumerate}
		\item ${\mu}_{\omega^-}(\mathcal{X}) = 1$ for $\mathbf{P}$-almost every $\omega^- \in \mathcal{B}$.
		\item The map $\omega^- \mapsto {\mu}_{\omega^-}(A)$ is measurable.
		\item The measure $\mu$ admits the disintegration
		\[
		\mu(A \times C) = \int_{C} {\mu}_{\omega^-}(A)\, \mathbf{P}(\mathrm{d}\omega^-).
		\]
		\item For all $(\omega^-, \omega^+) \in \tilde{\mathcal{B}} \times \mathcal{B}$,
		\begin{align}
			\begin{split}
				&P_t(\omega^-, \omega^+) \in \tilde{\mathcal{B}},\\
				&\left(\varphi_{P_t(\omega^-, \omega^+)}^{t}\right)_{\ast} {\mu}_{\omega^-}
				= {\mu}_{P_t(\omega^-, \omega^+)}.
			\end{split}
		\end{align}
		\item  
		For every $t \geq 0$,
		\begin{align}
			\mathbb{P}(\tilde{\mathcal{B}} \times \mathcal{B}) = 1, 
			\qquad  
			\theta_{t}(\tilde{\mathcal{B}} \times \mathcal{B}) \subseteq \tilde{\mathcal{B}} \times \mathcal{B}.
		\end{align}
		Moreover, for every $(\omega^-, \omega^+) \in \tilde{\mathcal{B}} \times \mathcal{B}$ and every $t \geq 0$,
		\begin{align*}
			(\Phi^{t}_{(\omega^-, \omega^+)})_{\star} \mu_{\omega^-} 
			= \mu_{P_{t}(\omega^-, \omega^+)}.
		\end{align*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

