body:
[Lemma 29 of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] Let~$\pi=(\pi_0,\ldots,\pi_\ell)$ be a combinatorial path of length~$\ell$ with~$k$ distinct vertices; assume that~$\pi_\ell \notin\{\pi_0,\ldots,\pi_{\ell-1}\}$. Let~$T$ be the discovery tree of~$\pi$. Let~$\mathcal P(\pi)$ be the probability that there exists an infection path in~$\mathcal G$ started at the root and having an ordered trace~$\Gamma$ satisfying the following properties:
\begin{itemize}
\item the combinatorial path associated to~$\Gamma$ is~$\pi$;
\item all vertices of~$\Gamma$ are blue, except for the last one, which is red.
\end{itemize}
Then,
	\[
		\mathcal P(\pi) \le \begin{cases}
			(2\lambda^{a \wedge 1})^{(\ell-2k)\vee 0} \cdot F(T,\pi_0,\pi_\ell) \cdot \int_0^{\mathfrak{u}_1} u^{-\gamma_1}\;\mathrm{d}u &\text{if $\ell$ is even;}\\[.2cm]
			(2\lambda^{a \wedge 1})^{(\ell-2k)\vee 0} \cdot F(T,\pi_0,\pi_\ell) \cdot \int_0^{\mathfrak{u}_2} v^{-\gamma_2}\;\mathrm{d}v&\text{if $\ell$ is odd.}
		\end{cases}
	\]

[Lemma 36 (Mixed-word formula) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $\beta:[0,T_{\beta}]\to V$ be a continuous bounded-variation path with $\beta_0=0$ and $\beta_{T_{\beta}}=v\neq0$. Fix $\ell\in V^*$ with $\ell(v)=1$, put $W=\ker\ell$, and write
\[
\beta_t=x_tv+X_t,
\qquad x_t=\ell(\beta_t),
\qquad X_t\in W.
\]
Let $r\geq1$, let $n_0,\ldots,n_r\geq 0$, and let $\eta_1,\ldots,\eta_r\in W^*$, extended to $V^*$ by $\eta_j(v)=0$. Set $N=r+\sum_{j=0}^r n_j$. The canonical pairing of the covector word with the degree-$N$ signature level is
\begin{equation}
\begin{aligned}
&\left\langle
\ell^{\otimes n_0}\otimes\eta_1\otimes
\ell^{\otimes n_1}\otimes\cdots\otimes
\eta_r\otimes\ell^{\otimes n_r},
S_N(\beta)
\right\rangle\\
&\quad=\int_{\Delta_r(T_{\beta})}
\frac{x_{t_1}^{n_0}}{n_0!}
\prod_{j=1}^{r-1}
\frac{(x_{t_{j+1}}-x_{t_j})^{n_j}}{n_j!}
\frac{(1-x_{t_r})^{n_r}}{n_r!}
\prod_{j=1}^r\eta_j(\dd X_{t_j}).
\end{aligned}
\end{equation}

[Theorem Thm-singular-limit-main of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] (Singular limit)
    Assume that $f_{\tau, 0} \to f_0$ in $H_0$ as $\tau \downarrow 0.$ Then the following  holds.
    \begin{itemize}
        \item $ f_\tau$ converges to 
        $ \rho_0\otimes \mathbf{M}_0$ in $L^2(0,T;H_0)$, 
     where  $\rho_0(x)=\int_D f_0(x,r) dr$ and $f_\tau$ is the unique solution  to (equation limit-PDE-final-NOCUT-V1-main of the paper). Moreover, the following estimate (convergence rate) holds
              \begin{align}
 \int_0^T  \Vert f_{\tau}(t)-\rho_0\otimes \mathbf{M}_0\Vert_{H_0}^2 dt \leq C_P  \xi\tau (\Vert f_{\tau, 0}\Vert_{H_0}^2+\Vert \rho_0 \Vert^2_{L^2(\mathbb{T}^2)})+2T\Vert f_{\tau,0}-f_0\Vert_{H_0}^2.
          \end{align}
          \item Assume that $f_{\tau,0}$ converges to $ \rho_{0}\otimes\mathbf{M}_0$ in $H_0.$ Then,  $ f_\tau$ converges to 
        $ \rho_0\otimes \mathbf{M}_0$ in $C([0,T];H_0)$, 
     where  $\rho_0(x)=\int_D f_0(x,r) dr$. Moreover, the following estimate (convergence rate) holds
     \begin{align}
         \displaystyle\sup_{t\in [0,T]}\Vert f_{\tau}(t)-\rho_0\otimes \mathbf{M}_0\Vert_{H_0}^2 \leq   \Vert f_{\tau,0}- \rho_{0}\otimes\mathbf{M}_0\Vert_{H_0}^2.
     \end{align}
    \end{itemize}

[Definition def:threespinsystems of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] We fix an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \in \ensuremath{\mathbb{N}}^*$, three inverse temperatures $\beta, \beta_1, \beta_2 \geq 0$ and introduce three spin systems on the extended lattice:
\begin{itemize}
    \item The first one is the XY model on the extended lattice $\ensuremath{\mathbb{Z}^d}_n$ with inverse temperature $n \beta$, i.e.,
    \begin{equation} 
        \mu_{\Lambda_L^n, n,  \beta}^{\mathrm{XY}}(d \theta)  := \frac{1}{Z_{\Lambda_L^n, n,  \beta}^{\mathrm{XY}}} \exp \left( n \beta \sum_{x \sim_n y}  \cos ( \theta_x - \theta_y ) \right) \prod_{x \in \Lambda_L^n} d \theta_x.
    \end{equation}
    We denote by $\left\langle \cdot \right\rangle_{L, n  ,\beta}^{\mathrm{XY}}$ the expectation with respect to this measure.
    \item The second one is an XY model on the extended lattice $\ensuremath{\mathbb{Z}^d}_n$ with heterogenous temperatures defined as follows. For any $n \geq 2$ and any pair of inverse temperatures $\beta_1 , \beta_2 > 0$, we set
\begin{equation} 
        \mu_{\Lambda_L^n, n, \beta_1 , \beta_2}^{\mathrm{XY}}(d\theta) := \frac{1}{Z_{\Lambda_L^n, n, \beta_1,  \beta_2 }^{\mathrm{XY}}}\exp \left( \beta_1 \sum_{\substack{x \sim_n y \\ x \in \ensuremath{\mathbb{Z}^d} }} \cos (\theta_x - \theta_y) + n \beta_2 \sum_{\substack{x \sim_n y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} \cos (\theta_x - \theta_y) \right) \prod_{x \in \Lambda_L^n} d \theta_x.
\end{equation}
 We denote by $\left\langle \cdot \right\rangle_{L, n  ,\beta_1 , \beta_2}^{\mathrm{XY}}$ the expectation with respect to this measure.
    \item The third one is a spin system defined on the extended graph $\ensuremath{\mathbb{Z}^d}_{3}$ where the interaction on the edges connected to $\ensuremath{\mathbb{Z}^d}$ is the one of an XY model with inverse temperature $\beta_1$ and the interaction along the other edges is the one of a Villain model with inverse temperature $\beta_2$, i.e.,
    \begin{equation} 
        \mu_{\Lambda_L^3, \beta_1 , \beta_2}^{\mathrm{XY/Vil}}(d\theta) := \frac{1}{Z_{\Lambda_L^3, \beta_1 , \beta_2 }^{\mathrm{XY}}}\exp \left( \beta_1 \sum_{\substack{x \sim_3 y \\ \{ x , y \} \cap \ensuremath{\mathbb{Z}^d} \neq \emptyset}} \cos (\theta_x - \theta_y) \right) \prod_{\substack{x \sim_3 y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} v_{\beta_2}(\theta_x - \theta_y) \prod_{x \in \Lambda_L^3} d \theta_x.
    \end{equation}
    We refer to this model as \textbf{the XY/Villain model} and denote by $\left\langle \cdot \right\rangle_{L  ,\beta_1, \beta_2}^{\mathrm{XY/Vil}}$ the expectation with respect to this measure.
\end{itemize}

