body:
[Lemma 10 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $X$ be a stochastic process on $\mathcal{D}[0,T]$ such that $X(0) =0$ a.s.
	. Let $I(t) = \int_0^t X(s)\dif s,\ 0\le t\le T$, and $0\le t_1<t_2\le T, \ \gamma \in\mathbb{R}$.
	\begin{itemize}
		\item[($i$)] If $X$ has independent increments,
		\begin{equation}
			\mathbb{E}e^{i\gamma \big(I(t_2)-I(t_1)\big)} = \mathbb{E}e^{i\gamma (t_2-t_1)X(t_1)}\mathbb{E}e^{i\gamma \int_0^{t_2-t_1} \big(X(s+t_1)-X(t_1)\big)\dif s}.
		\end{equation}
		\item[($ii$)] If $X$ has independent and stationary increments,
		\begin{equation}
			\mathbb{E}e^{i\gamma \big(I(t_2)-I(t_1)\big)} = \mathbb{E}e^{i\gamma (t_2-t_1)X(t_1)}\mathbb{E}e^{i\gamma I(t_2-t_1)}.
		\end{equation}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma constantcomparison of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Fix a transitive directed graph $\vec{G}$ with outer degree $\Delta$. For any $\lambda, t > 0$, there exists a positive and finite constant $C(\Delta,\lambda,t)$ such that
    \begin{align}
        \widetilde{\phi}_{\lambda, t}(S)< C(\Delta,\lambda, t) \, \phi_{\lambda, t}(S) \, ,
    \end{align}
    holds for any finite, connected $S \subset V$ containing the origin. Moreover, $c(\Delta,\lambda,t) := 1/C(\Delta,\lambda,t)$ is continuous in $\lambda$ and $t$ on $[0, \infty) \times [0, \infty).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary crossings-half of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Assume the hypotheses of \textit{Claim~\ref
{An-vanishing}}. Assume moreover the earlier one-crossing framework: for
each $n$, $L_{n}$ has a unique crossing point $c_{n}\in (0,1)$ with the
diagonal, 
\begin{equation}
L_{n}(c_{n})=c_{n},  
\end{equation}
Then every cluster point of $(c_{n})$ is equal to $\tfrac{1}{2}$.
Consequently, 
\begin{equation}
c_{n}\longrightarrow \frac{1}{2}.  
\end{equation}

