[Theorem thm:F=tildeF of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Given  any fixed diagram $\Gamma$ with or without open edges, if all $n_j \gg t_N$ for $j=1,\ldots, s$,    and $\| A_N\|_{\mathrm{op}} \le 1+\tau n^{-1}$ with  $n=\sum_{j=1}^s n_j$,  for any fixed integer $s\geq 1$  and     constant   $\tau >0$,  then  
    \begin{equation}
     F_{\Gamma}(\{n_j\})=\widetilde{F}_{\Gamma}(\{n_j\}_{j=1}^s)+O\Big(\big(\frac{t_N}{n}+\delta\big)  n^{|E|}N^{|V_{\mathrm{int}}|-|E_{\mathrm{int}}|}\Big).
    \end{equation}

