    \begin{align}
        &\lim_{n \rightarrow \infty }\left[ \left( \sum_{J=1}^{N} \int_{t_2}^{t_1} \left \langle (\Lambda_{j}(v_{n}(\tau)))^{*}Q_{n}\phi_1, (\Lambda_{j}(v_{n}(\tau)))^{*}Q_{n}\phi_2 \right \rangle_{\mathbb{R}}d\tau \right) \cdot h_{v_{n|[0,t_2]}}\right]=\nonumber \\
        & \left[ \left( \sum_{J=1}^{N} \int_{t_2}^{t_1} \left \langle (\Lambda_{j}(v(\tau)))^{*}\phi_1, (\Lambda_{j}(v(\tau)))^{*}\phi_2 \right \rangle_{\mathbb{R}} d\tau \right) \cdot h_{v_{[0,t_2]}}\right]. \nonumber
    \end{align}

