[Definition D:Rho of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] A function $\rho:\mathbb{R}^d\mapsto \mathbb{R}$ is called an \textup{admissible weight
  function} if it is a strictly positive, bounded, continuous, and $L^1
  (\mathbb{R}^d)$-integrable function such that for all $T > 0$, there exists a constant
  $C_\rho(T)$ satisfying
  \begin{equation}
    \big(p(t,\cdot)*\rho(\cdot)\big)(x) \le C_\rho(T) \rho(x)
    \quad \text{for all $t\in[0,T]$ and $x\in\mathbb{R}^d$.}
  \end{equation}

[Lem 36 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] With all assumptions in Proposition \ref{prop:new-firstmoment}, we have
        \begin{equation}
            \mathbb E[|E(G,G')|] \leq N^{-\mathsf{C}/2}+N^{O(\delta)}\cdot\sum_{y \in \tal, z \in \tar}\sum_{x \in A_{y,z,i}^{\stable}} \sum_{i=1}^{N-1}\mathbb P\lt[(i,i+1)\in E(G_{B_x})\rt]^2].
        \end{equation}

