[Mainthm t:1.4i of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Assume $(r_N)_{N \geq 1}$ is as in~(equation e:1.11i of the paper). Then,
with the underlying space is as in~(equation e:1.10i of the paper),
\begin{equation}

\widehat{\eta}_{N,r_N}
\underset{N \to \infty} \Longrightarrow \ \widehat{\eta}_{\rm D} \,,
\quad ; \qquad
	\widehat{\eta}_{\rm D} \,\big|\, \widehat{\mathcal Z}_{\rm D} \sim\  \text{\rm PPP}\bigl(\widehat{\mathcal Z}_{\rm D}(\text{\rm d}\mkern0.5mu x)\otimes\text{\rm e}\mkern0.7mu^{-\alpha s}\text{\rm d}\mkern0.5mu s\otimes\nu({\rm d} \omega)\bigr) \,,
\end{equation}
where $\alpha$ and $\nu$ as in~(equation e:1.10i of the paper), and $\widehat{\mathcal Z}_{\rm D}$ is a random Radon measure on ${\rm D}$.
The law of $\widehat{\mathcal Z}_{\rm D}$ is uniquely defined via the relation:
\begin{equation}

	\widehat{\mathcal Z}_{\rm D} {\rm e}^{\alpha \psi_{\rm D} \overline{h}_{\rm D}} \overset{{\rm d}} = \mathcal Z_{\rm D} \,,
\end{equation}
where $\overline{h}_{\rm D}$ is as in~(equation e:1.7p of the paper) and independent of $\widehat{\mathcal Z}_{\rm D}$, $\psi_{\rm D}: {\rm D} \to \mathbb{R}$ is the deterministic field:
\begin{equation}

	\psi_{\rm D}(\cdot) : =  {\rm Leb}({\rm D}) \frac{\int_{\rm D} G_{\rm D}(\cdot,z)\, {\rm d} x}{\int_{{\rm D} \times {\rm D}} G_{\rm D}(x,y)\, {\rm d} x {\rm d} y} \,,
\end{equation}
and $\mathcal Z_{\rm D}$ is as in~(equation eq:deflqgm of the paper). The joint law of $\overline{h}_{\rm D}$ and $\mathcal Z_{\rm D}$ as determined by~(equation e:1104.14n of the paper) is the same as that in the coupling of Theorem~(t:1.2i of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:scalingreduction of arXiv:2606.11248, 'Persistent Homology of the Planar Wiener Sausage: Brownian Scaling and a Logarithmic Expec'] Suppose that there exist a normalization $a(T)$ and a nonnegative function $f$ on $(0,\infty)$ such that, for every fixed $r>0$,
\begin{equation}
\frac{\mathbb{E}[\beta_{1}^{T}(r)]}{a(T)}\to f(r)\qquad\text{as }T\to\infty,
\end{equation}
and suppose that
\[
a(T)=T\ell(T),
\]
where $\ell$ is slowly varying at infinity. Then there exists an absolute constant $\kappa\ge0$ such that
\begin{equation}
f(r)=\frac{\kappa}{r^{2}}.
\end{equation}

[Definition1 of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Let $T$ be a random infinite planar triangulation. We say that $T$ is weakly Markovian if there exist numbers $a_v^{p_1,\dots,p_k}$ for $k \ge 1$ and $p_1,\dots,p_k \ge 1$, $v \ge 0$, such that for any triangulation $t$ with $k$ holes of perimeters $p_1,\dots,p_k$ and $v$ internal vertices,
\begin{align*}
\mathbb{P}(t \subset T) = a_v^{p_1,\dots,p_k}.
\end{align*}

[Lem lm:bdry of arXiv:2604.12963, 'Shocks, instability, and the twenty networks\\ of infinite geodesics in the Directed Lands'] Let $\omega\in\Omega_0$, $\theta\in\Theta^\omega$, and  $(x,s)\in\mathbb{R}^2$. For $t\in\mathbb{R}$, let $\gamma(t)=(I^{\theta-}_{(x,s)}(t),t)$ and $\tau(t)=(I^{\theta+}_{(x,s)}(t),t)$. 
    \begin{enumerate}[label={\rm(\alph*)}, ref={\rm\alph*}] \itemsep=1pt
    \item $\gamma\preceq\tau$ and $(x,s)$ is weakly between the two paths. If $\gamma\ne\tau$, then the connected components of $\{(z,r):\gamma(r)<(z,r)<\tau(r)\}$ are all stability islands.
    \item Suppose $(x,s)$ is in the closure of some stability island. Let $t_1=\sup\{r\le s:\gamma(r)=\tau(r)\}$ and $t_2=\inf\{r\ge s:\gamma(r)=\tau(r)\}$. Then $-\infty<t_1<t_2<\infty$, $s\in[t_1,t_2]$, $\gamma(t_1) = \tau(t_1)$, $\gamma(t_2) = \tau(t_2)$, for any $r\in(t_1,t_2)$, $\gamma(r) < \tau(r)$, and the island is given by
    \begin{align}
    \{(z,r):\gamma(r)<(z,r)<\tau(r),\,t_1<r<t_2\}.
    \end{align}
    \end{enumerate}

