[Lemma 12 (Burn-in and occupancy of the good set) of arXiv:2605.27212, '2605.27212'] Let \(\varepsilon_0\) be as in Lemma~\ref{lem:tr-good-stationary}.  For every
fixed \(M<\infty\) there is a constant \(C_M<\infty\) such that the following
holds.  Assume \(1\le k\le\varepsilon_0 n\) and set
\begin{equation}
    t_*=C_M nk\log n.
\end{equation}
Then, uniformly in \(x\in\Stief{n}{k}\) and all integer times
\(t\ge t_*\),
\begin{equation}
    \Prob_x(X_t\notin\Good_{\mathrm{tr}})\le n^{-M}.
\end{equation}
Consequently, if \(L\le n^3\) and \(M=10\), then uniformly in \(x\) and
\(s\ge t_*\),
\begin{equation}
    \Prob_x(\exists\,u\in\{0,1,\ldots,L\}:X_{s+u}\notin\Good_{\mathrm{tr}})=o(1).
\end{equation}

[Mainthm 2 of arXiv:2609.03777, '2609.03777'] \begin{enumerate}[(i)]
\item The $\CC$-span of multiple Eisenstein series is graded by weight:
\begin{align}
\mes^\CC=\bigoplus_{k\geq0}\mes_k^\CC\,.
\end{align}
In particular, the $\QQ$-algebra of multiple Eisenstein series is graded by weight:
\begin{align}
\mes=\bigoplus_{k\geq0}\mes_k\,.
\end{align}
\item The assignment
\begin{align}
\Phi_k:\mes_k&\longrightarrow
\operatorname{gr}^W_k\mathsf{qMZV},\\
G_{k_1,\dots,k_r}
&\longmapsto
g_{k_1,\dots,k_r}
\bmod\operatorname{Fil}^W_{k-1}\mathsf{qMZV}
\end{align}
is a well-defined isomorphism of $\QQ$-vector spaces, where $\Phi_0(1)=1$.  These maps give an isomorphism of graded $\QQ$-algebras
\begin{align}
\Phi:\mes\xrightarrow{\,\sim\,}
\operatorname{gr}^W\mathsf{qMZV}\,.
\end{align}
Moreover, the map
\begin{align}
\mes\otimes_\QQ\CC\xrightarrow{\,\sim\,}\mes^\CC
\end{align}
is an isomorphism.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Lemma 3.5 of \cite{Chen2024} at $n=8$) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Let $n=8$ and $0<b\le b_{max}$. Then
    \begin{equation*}
        \rho'(b)\ge\rho'\Bigl(\frac1{18}\Bigr)=\frac{5625}{7921}>\frac49,\qquad
        0<\rho(b)<b,\qquad
        \rho\Bigl(\frac1{18}\Bigr)=\frac{31}{712}.
    \end{equation*}

