[Proposition 13 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $N\sim PP(\lambda)$. Let $t>0$, $\Lambda_{t,1},\dots$ i.i.d r.v.s distributed as in \eqref{distribuzioneVariabileAleatoriaLambda}. Then, for $n\in\mathbb{N}$ and $0\le s_1<s_2<\dots<s_n\le t$,
	\begin{equation}
		P\{S_1\in\dif s_1,\dots,S_n\in \dif s_n\,|\,N(t) = n\} = P\{\Lambda_{t,(1)}\in\dif s_1, \dots, \Lambda_{t, (n)}\in\dif s_n\},
	\end{equation}
	with $\Lambda_{t,(1)},\dots,\Lambda_{t,(n)}$ the (increasingly) ordered $\Lambda_{t,1},\dots,\Lambda_{t,n}$.

[Lemma lem:S-funnel-equality-d-regular of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] \begin{equation}

		[S^{ \text{\rm d-reg}}]  = \lim_{M \to \infty} \mathbb{E}_{{\cal G}_{M,d}^{\rm regular}} \left[ \frac{1}{M}\sum_{j =1}^M  \frac{\prod_{i=1}^d [S^{k_i,p_j}_j]}{([S^{p_j}_j])^{d-1}}  \right],
	\end{equation}
	where
	\begin{equation}

		[S^{p_j}_j]  \equiv  (1-I^0)e^{-pt}, \qquad 
		j\in {\cal M}.
	\end{equation}

