[Theorem ThmKL of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] Assume that the mixed partial derivatives appearing
in~(LemExactKL of the paper) are continuous on the compact log-odds region
associated with $\ensuremath{\mathcal{I}_{\scaleto{\operatorname{full}}{4pt}}}$, and that $\mathsf{q}$ is strictly positive on
$[-\ell_d, \ell_d]$.  Then we have the equivalence
\begin{subequations}
\begin{align}

  \mathsf{P}_{\scaleto{\mathrm{\textsf{IGC}\xspace}}{4pt}}(\ensuremath{\mathcal{I}_{\scaleto{\operatorname{full}}{4pt}}}) & = \left( \int_{-\ell_d}^{\ell_d}
  \sqrt{\mathsf{q}(\lambda)} \, d\lambda \right)^2 \equiv \mathsf{P}_{\scaleto{\mathrm{\textsf{IGC}\xspace}}{4pt}}.
\end{align}
Moreover, for the log-odds-uniform grid~(equation EqnSingleBlockGrid of the paper),
the sum of exact KL one-step errors satisfies
\begin{align}

  \sum_{j = 0}^{N - 1} \Gamma_{\scaleto{\operatorname{prod}}{5pt}}(r_j, r_{j + 1}) & = \frac{\mathsf{C}_{\scaleto{\operatorname{\textsf{IGC}\xspace}}{4pt}}}{2 N} +
  o(N^{-1}),
\end{align}
Finally, the optimal $N$-step discretization satisfies
\begin{align}

  \inf_{r_0 = r_0 < r_1 < \cdots < r_N = 1 - r_0} \sum_{j =
    0}^{N - 1} \Gamma_{\scaleto{\operatorname{prod}}{5pt}}(r_j, r_{j + 1}) & = \frac{\mathsf{P}_{\scaleto{\mathrm{\textsf{IGC}\xspace}}{4pt}}}{2 N} + o(N^{-1}).
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition CRP of arXiv:2411.06089, '{\Large \bf Averaging principle for semilinear slow-fast rough partial differential equati'] {\rm (Controlled Rough Path)}
Let $\mathbf X=(X,X^2) \in \mathscr{C}^\gamma ([0,T]; \mathbb R^d)$ for $\gamma \in (1/3,1/2]$.
We call a pair $(Y, Y')$ a controlled rough path,
if $(Y, Y') \in \hat{C}^\gamma ([0,T];\mathcal{H}_\alpha) \times \hat{C}^\gamma ([0,T]; \mathcal{H}_\alpha^d)$ for some $\alpha \in \mathbb R$
and the remainder term $R^Y$ defined by
	\begin{equation}
		R_{t,s}^Y=\hat \delta Y_{t,s}-S_{t-s}Y_s' \delta X_{t,s} ,
	\end{equation}
belongs to $C_2^{2\gamma} ([0,T];\mathcal{H}_\alpha)$,
where the component $Y'$ is the Gubinelli derivative of $Y$.
We denote by $\mathscr D_{S, \mathbf X}^{2\gamma} ([0,T]; \mathcal{H}_\alpha )$ the space of all controlled rough paths that are controlled by $\mathbf X$ according to the semigroup $S$.
Define a seminorm on this space by
\begin{equation*}
\|Y,Y'\|_{X, 2\gamma, \alpha}
	=\|Y'\|_{\gamma,\alpha}+|R^Y|_{2\gamma, \alpha},
\end{equation*}
and its norm is given by
\begin{equation*}
\|Y,Y'\|_{\mathscr D_{S, \mathbf X}^{2\gamma}}=
	\|Y_0\|_{ \mathcal{H}_\alpha}
	+ \|Y_0'\|_{\mathcal{H}_\alpha^d} +\|Y,Y'\|_{X, 2\gamma, \alpha}.
\end{equation*}

[Theorem 28 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] (see \cite{MR3029153,MR3404695}) With the convolution of coefficients as product, if $f\in\mathcal{H}_{p}$ and $g\in\mathcal{H}_{q}$
with $p-q\ge2$, then $f\star g\in\mathcal{H}_{-p}$ and there exists
a positive $A(p-q)$, depending only on $p$ and $q$, such that 
\begin{equation}

\|f\star g\|_{-p}\le A(p-q)\|f\|_{-p}\cdot\|g\|_{-q},
\end{equation}
where
\begin{equation}
A(p-q)=\left(\sum_{\alpha\in\ell}(2\mathbb N)^{(q-p)\alpha}\right)^{1/2}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

