[Proposition prop:p1:linearrate of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\mathbf{X}_\star \in \R^{d_1 \times d_2}$. Assume that the measurement operator $\mathcal{A}: \mathbb{R}^{d_1 \times d_2} \longrightarrow \R^m $ 
	satisfies the NSP (eq:NSP:definition of the paper) of order $r$ for some $0 < \eta_r<1$ 
	and that $ \mathbf{y} = \mathcal{A} \left(  \mathbf{X}_\star \right) $.
	Let the IRLS iterates  $\left\{   \mathbf{X}^{(k)} \right\}_k$ and $ \left\{ \varepsilon_{k} \right\}_k$ be defined by (eq:IRLS:step_1 of the paper) and (eq:IRLS:step_2 of the paper) of (alg:algo1 of the paper) with arbitrary positive definite initial weight operator $W^{(0)}$ and rank estimate $\widetilde{r} =r$, and assume that (alg:algo1 of the paper) does not return in iteration $k$, i.e., that $\varepsilon_k > 0$, so that the iterate $\mathbf{X}^{(k+1)}$ is defined.
	Assume that the weight operator $\W{\mathbf{X}^{(k)}}{\varepsilon_k}(\cdot)$ used in each iteration of (alg:algo1 of the paper) is defined as in (def:weightcore of the paper) 
	is admissible in the sense of (def:admissible:weightoperators of the paper), let $c_q$ be the weight operator-dependent constant (eq:c_q:def of the paper) of (lemma:normbound:hadamard of the paper).
	Set
	\begin{equation*}
	\gamma :=
	\begin{cases}
	3/4 \quad & \text{if } \besterrNuc{\mathbf{X}_\star}{r}=0, \\
	1/2 \quad & \text{otherwise}.
	\end{cases}
	\end{equation*}
	If 
	\begin{equation*}
		\besterrNuc{\mathbf{X}_\star}{r}  \le  \frac{1}{9} \nucnorm{\mathbf{X}_\star -\mathbf{X}^{(k)}}
	\quad \text{and} \quad
	\gamma > \frac{2\eta_r}{1+\eta_r},
	\end{equation*}
	then it holds that
	\begin{equation*} 
		\mathcal{J}_{\varepsilon_{k+1}}( \mathbf{X}^{(k+1)} ) -  \nucnorm{\mathbf{X}_\star} \le \left(  1-  \frac{ C_{\eta_r,\gamma}  }{ c_q \eta_1  d }\right) \left(     \mathcal{J}_{\varepsilon_{k}} \left( \mathbf{X}^{(k)}  \right) -  \nucnorm{ \mathbf{X}_\star } \right)
	\end{equation*} 
	where the constant $C_{\eta_r}$ is defined by 
	\begin{equation*}
	C_{\eta_r,\gamma}
	:=
	\frac{\left( \gamma - \frac{2\eta_r}{1+\eta_r}  \right)^2 }{\left( 3 + 2\eta_r \right)}.
	\end{equation*}

