[Cor 37 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta>0$. Then for every $N\geq 0$ and every deterministic functions or generalized functions
$f_{1},f_{2}\in H^{\eta}(\C)$ (in particular for every $f_{1},f_{2}$ smooth compactly supported in $\C$ test functions),
\begin{multline*}
\E\Big[\int_{\Ns_{\varepsilon}(A)} f_{1}(z)\,d^{2} z~\int_{\Ns_{\varepsilon}(A)} f_{2}(w)\,d^{2} w\Big]
=
\\
\sum_{n=1}^{N+1}
\Big(
\sum_{k=0}^{n-1}\dfrac{\E[(\psi_{2k+1, A},f_{1})\,(\psi_{2(n-k)-1, A},f_{2})]}{k!(n-1-k)! (k+1/2)(n-k-1/2)}
\Big)
\dfrac{(-1)^{n-1} \pi^{n-1}}{\vert\log \varepsilon\vert^{n}}
~+~ o(\vert\log \varepsilon\vert^{-(N+1)}).
\end{multline*}
If furthermore $f_{1}$ and $f_{2}$ are compactly supported in $D$, then
\begin{multline*}
\E\Big[\int_{\widetilde{\Ns}_{\varepsilon}(A)} f_{1}(z)\,d^{2} z~
\int_{\widetilde{\Ns}_{\varepsilon}(A)} f_{2}(w)\,d^{2} w\Big]
=
\\
\sum_{n=1}^{N+1}
\Big(
\sum_{k=0}^{n-1}\dfrac{\E[(\tilde{\psi}_{2k+1, A},f_{1})\,(\tilde{\psi}_{2(n-k)-1, A},f_{2})]}
{k!(n-1-k)! (k+1/2)(n-k-1/2)}
\Big)
\dfrac{(-1)^{n-1} \pi^{n-1}}{\vert\log \varepsilon\vert^{n}}
~+~ o(\vert\log \varepsilon\vert^{-(N+1)}).
\end{multline*}

