body:
[Theorem T:SLND of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume Hypothesis (H:para of the paper) and the Dalang condition~(equation E:main of the paper). Let $0<S<T<\infty$.
  \begin{enumerate}[\rm (i)]

    \item \emph{(SLND in time)}\index{strong local nondeterminism (SLND)!temporal}
          \begin{enumerate}[\rm (a)]

            \item If $\beta = 1$, $\gamma \ge 0$; or $\beta = 2$, $\gamma \in [0,
                      1]$, then there exist constants $C > 0$ and $\delta>0$ such that for
                  all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1, \dots, t_n
                    \in [S, T]$ with $\max_{1\le j \le n}|t-t_j| \le \delta$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} |t-t_j|^{2\rho}.
                  \end{align}

            \item If $\beta \in (0, 2)$, $\gamma \ge 0$, then there exists a constant $C>0$ such
                  that for all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1,
                    \dots, t_n \in [S, T]$ with $\max\{t_1, \dots, t_n \} \le t$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} (t-t_j)^{2\rho}.
                  \end{align}

          \end{enumerate}

    \item \emph{(SLND in space)}\index{strong local nondeterminism (SLND)!spatial} If $\beta \in (0, 2]$, $\gamma \ge 0$, then
          for any $M>0$, there exists a constant $C>0$ such that for all $t \in [S,
              T]$, for all $n \ge 1$, and for all $x, x_1, \dots, x_n \in B(0, M)$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t, x_1), \dots, u(t, x_n) \big) \ge C \min_{1 \le j \le n} |x-x_j|^{2\tilde\rho}.
          \end{align}

  \end{enumerate}

[Lemma firstlemma of arXiv:2607.01463, 'Two Multi--Draw Coupon Collector models with different retention rules'] Let $\phi(s)$ be analytic in a domain that contains the half--line $[n_{0},\infty)$. Then, the differences of the sequence $\left\{\phi(k)\right\}$ admit the integral representation
\begin{equation}
\sum_{k=n_{0}}^{N}\binom{N}{k}\left(-1\right)^{k+1}\phi(k)=\frac{\left(-1\right)^{N+1}}{2i \pi } \int_{\mathcal{C}} \phi(s)\frac{N!}{s\left(s-1\right)\cdots\left(s-N\right)}\,ds,
\end{equation}
where $\mathcal{C}$ is a positively oriented closed curve that lies in the domain of analyticity of $\phi(s)$, encircles $[n_{0}, N]$, and does not include any of the integers $0,1,\cdots,n_{0}-1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 20 of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $[S,T]\subseteq\Rsf$ be an interval and let $m,n\in\Nsf$. Let $p\in [1,3)$, let $\omega$ be a control function on interval $[S,T]$, and let $X$ be an $n$-dimensional branched rough path on interval $[S,T]$ with regularity $p$ and control $\omega$. Let $f: \Rsf^m\to R_n^2\Rsf^m$ be a compactly supported admissible rough velocity field and $(f^i_\tau)$ its global coordinate representation. Then for each $Y_0\in\Rsf^m$, there exists a function $Y: [S,T]\to \Rsf^m$ satisfying $Y(S)=Y_0$ for which there exists a constant $C\in (0,\infty)$ such that the inequality 
	\begin{equation}

		\left|
			Y^i(t) - Y^i(s) 
			- \sum_{\tau\in\Fcal_n^2} \frac{1}{\sigma(\tau)} f_{\tau}^i(Y(s)) X^\tau(s,t)
		\right|
		\leq C \omega(s,t)^\frac{3}{p}
	\end{equation}
holds for every $i\in \llbracket 1,m\rrbracket$ and $(s,t)\in \Delta[S,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm defective-t2 of arXiv:2411.14236, 'Size of chaos for Gibbs measures\\of mean field interacting diffusions'] Let $\mathcal X = \mathds R^d$.
Suppose that $W = W_+ - W_-$ where both $W_+$ and $W_-$
are $\mathcal C^2$ and of positive type
with $\lVert\nabla_{1,2}^2 W_+ \rVert_{L^\infty} \leqslant L^+_W$
and $\lVert\nabla_{1,2}^2 W_- \rVert_{L^\infty} \leqslant L^-_W$.
Suppose that there exist
$\varepsilon \in [0,1/2]$ and $\lambda \geqslant 0$ such that for all
$\nu \in \mathcal P_2(\mathds R^d)$,
\begin{equation}

\frac{\lambda}{2} W_2^2(\nu, m_*) \leqslant
- \frac {1+\varepsilon}2 \langle W_-, (\nu - m_*)^{\otimes 2}\rangle
+ H(\nu | m_*).
\end{equation}
Then for all $\nu^N \in \mathcal P_2(\mathds R^{Nd})$,
\begin{equation}

\frac{\lambda_N}{2}
W_2^2(\nu^N, m_*^{\otimes N}) \leqslant
H(\nu^N|m^N_*) + \delta_N,
\end{equation}
where $\lambda_N$, $\delta_N$ are defined by
\begin{align}
\lambda_N &= \begin{cases}
\makebox[0pt][l]
{$\lambda - 3(1/\sqrt{2\varepsilon}+3)L^-_WN^{-1},$}
\hphantom{
\bigl( 3(1/\sqrt{2\varepsilon}+3) L^-_W + L^+_W\bigr) \Var m_*,
}
& \varepsilon \in (0,1/2], \\
\lambda - 2(\log N+3)L^-_WN^{-1},
& \varepsilon = 0,
\end{cases} \\
\delta_N &= \begin{cases}
\bigl( 3(1/\sqrt{2\varepsilon}+3) L^-_W + L^+_W\bigr) \Var m_*,
& \varepsilon \in (0,1/2], \\
\bigl( 2(\log N + 3)L^-_W + L^+_W\bigr) \Var m_*,
& \varepsilon = 0.
\end{cases} 
\end{align}
Here $\Var m_*$ denotes the sum of the variances of the individual
components for a random variable with distribution $m_*$.
Consequently, in the case $\lambda_N > 0$,
for all $\nu^N \in \mathcal P_1(\mathds R^{Nd})$,
\begin{equation}

W_1^2(\nu^N, m^N_*) \leqslant \frac{64(1+\delta_N)^2}{\lambda_N}
H(\nu^N| m^N_*).
\end{equation}
Moreover, the $\textnormal{T}_{\`1}$ inequality (equation eq:ps-t1 of the paper) with the same constant
holds for any marginal distribution of $m^N_*$.

In particular, if $W$ consists solely of a positive part, i.e., $W = W_+$,
and if $m_*$ satisfies a $\textnormal{T}_{\`2}$ inequality
with constant $\lambda$, then (equation eq:ps-defective-t2 of the paper) holds
with $\lambda_N = \lambda$ and $\delta_N = L_W^+ \Var m_*$.
Consequently, (equation eq:ps-t1 of the paper) holds with the same constants. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 (Cole--Hopf differentiation) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $g : \R \to \R$ be a twice differentiable function with $g$ of at most linear growth and $g'$, $g''$ of at most exponential growth, and let $m \ge 0$. For every $t \ge 0$ and $x \in \R$, let $u(t,x)=T_{m,t}g(x)$.
We have
\begin{equation}

    \dr_x u=\mathcal L_{mg,t}g',
\end{equation}
\begin{equation}

    \dr_t u
    =\dr_x^2 u+m (\dr_x u)^2
    =\mathcal L_{mg,t}\bigl(g''+m(g')^2\bigr),
\end{equation}
and
\begin{equation}

    \left.
    \frac{d}{d\varepsilon}
    T_{m,t}(g+\varepsilon h)(x)
    \right|_{\varepsilon=0}
    =
    \mathcal L_{mg,t}h(x).
\end{equation}

