body:
[Theorem POC of arXiv:2412.01070, 'A note on Lévy-driven McKean-Vlasov SDEs under monotonicity'] Assume that Assumptions $({\bf A}_1')$, $({\bf A}_{2})$ and $({\bf A}_{3})$ hold, and suppose further  $X^i_0\in L^\beta(\Omega\to\mathbb R^d,\mathscr F_0,\mathbb{P})$ for any $1\le i\le n$.
Let $(\mu_t)_{t\ge0}$ be the common distribution of $(X_t^i)_{t\ge0}$ for all $1\le i\le n$, and $\bar{\mu}^n_t=\frac{1}{n}\sum_{i=1}^n\delta_{X^{i,n}_t}$, where $\{(X_t^{i,n})_{t\ge0}\}_{1\le i\le n}$ is the solution to the mean-filed interacting particle system
(equation MF of the paper)  with   $f(x,z)=f(x,\mu,z)$.
Then, for any fixed $T>0$, there is a constant $ C_T>0$ such that
\begin{equation}
\begin{split}
 \mathbb{E}{\mathbb W}_p^p(\bar{\mu}^n_t,\mu_t)
\le C_T\phi_{p,\beta,d}(n),\quad t\in[0,T],
\end{split}
\end{equation}
where the quantity $  \phi_{p,\beta,d}(n)$
is defined as below:
\begin{equation}
\phi_{p,\beta,d}(n):=
\begin{cases}
n^{-(1-\frac{p}{{\beta}})}, & d=1,2;  d=3 {\rm ~and~} \frac{3}{2}\le p<{\beta}; \\
                            &d=3, 1\le p<\frac{3}{2} {\rm ~and~} {\beta}<\frac{3p}{3-p}; d\ge4 {\rm ~and~} {\beta}<\frac{dp}{d-p}; \\
    n^{-\frac{p}{d}}, & d=3, 1\le p<\frac{3}{2} {\rm ~and~} {\beta}\ge\frac{3p}{3-p}; d\ge4 {\rm ~and~} {\beta}\ge\frac{dp}{d-p}.
\end{cases}
\end{equation}
Furthermore, for  any $0\le q_1<q_2<1,$
there exists a constant $\hat C_T>0$ such that
\begin{equation}
\begin{split}
\mathbb{E}\Big(\sup_{0\le t\le T}|X^{i,n}_t-X_t^i|^{pq_1}\Big)\le \frac{q_2}{q_2-q_1}\big(\hat C_T
\phi_{p,\beta,n}(n)\big)^{q_1}.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:4.5 of arXiv:2608.27474, 'Nonlocality of Cover-Time Changes Under Edge Addition'] For the graph (equation eq:4.15 of the paper), with path length measured in edges and the walk
started at \(s=x_0\),
\begin{equation}
\boxed{
f_s(\lambda)
=L^2+L+2+\frac{2L+3}{1+2\lambda},
}

\end{equation}
and hence
\begin{equation}
\boxed{
f_s(\lambda)-f_s(0)
=-\frac{2\lambda(2L+3)}{1+2\lambda}<0
\quad(\lambda>0).
}

\end{equation}

[Lemma 12 of arXiv:2608.04853, 'Minimal-Norm Extensions of Stationary Kernels on Subgroups of Locally Compact Abelian Grou'] Let $G$ be a locally compact abelian group and let $H\subseteq G$ be a closed subgroup. Let $k:G \times G \to \R$ be a stationary kernel with spectral density $\hat{k}:\hat{G} \to \R$.
Define
\begin{align*}
    \hat k_H(\xi_H)
:=
\int_{H^\perp}
\hat k(\xi_H+\xi^\perp) \d\xi^\perp,
\qquad
\xi_H\in \hat G/H^\perp\simeq \widehat H.
\end{align*}
Let $g\in\mathcal N(H)$. Then the unique solution of the minimal-norm extension problem
\begin{align*}
    \min
\left\{
\Vert f\Vert_{\mathcal N(G)}^2
=
\int_{\hat G}
\frac{|\hat f(\xi)|^2}{\hat k(\xi)} \d\xi
 \, \middle| \, 
f\in\mathcal N(G),\ f|_H=g \right\}
\end{align*}
is characterized on the Fourier side by
\begin{align*}
    \hat f(\xi_H+\xi^\perp)
=
\hat g(\xi_H)
\frac{\hat k(\xi_H+\xi^\perp)}
{\hat k_H(\xi_H)}
\end{align*}
for almost all $\xi_H\in \hat G/H^\perp$ and $\xi^\perp\in H^\perp$. On the set where $\hat k_H=0$, the quotient is interpreted as zero.

