[Theorem 17 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let~\eqref{co:3},~\eqref{co:5} and~\eqref{co:7}--\eqref{co:9} hold, and for each $\ell\in\N$ let $I^{(\ell)}$ denote the unique strong solution to~\eqref{eq:copy of the SIS epidemic model} with $I_{0}^{(\ell)} = \xi_{\ell}$ a.s. Then
\begin{equation*}
\max_{\ell=1,\dots,M_{n}}\E\big[|\hat{I}_{t}^{(n,\ell)} - I_{t}^{(\ell)}|^{p}\big] \leq e^{\int_{0}^{t}\hat{\lambda}_{p,j,n}(s)\,\mathrm{d}s}\int_{0}^{t}\hat{\delta}_{p,j,n}(s) + 2c_{p,q}\hat{\lambda}_{k+1}(s,N(s))N(s)^{p}M_{n}^{-\frac{1}{2}}\,\mathrm{d}s
\end{equation*}
for all $n\in\N$, $j\in \{0,\dots,k_{n}-1\}$, $t\in[t_{j,n}, t_{j+1,n}]$ and $q > 2p$. In particular, if~\eqref{eq:Hoelder condition on the function N} and $M_{n}\geq \hat{c}_{0}|\mathbb{T}_{n}|^{-2\alpha p}$ hold for all $n\in\N$ and some $\alpha\in ]0,\frac{1}{2}]$ and $\hat{c}_{0},\hat{c}_{\alpha} \geq 0$, then
\begin{equation*}
\sup_{t\in[0,T]}\max_{\ell=1,\dots,M_{n}}\E\big[|\hat{I}_{t}^{(n,\ell)} - I_{t}^{(\ell)}|^{p}\big]^{\frac{1}{p}} \leq \hat{c}_{p,q,\alpha}|\mathbb{T}_{n}|^{\alpha}
\end{equation*}
for all $n\in\N$ and $q > 2p$, where $\hat{c}_{p,q,\alpha} := \hat{c}_{p}(\hat{c}_{\alpha,0}T + 2c_{p,q}\hat{c}_{0}^{-1/2}\hat{c}_{p,0})^{1/p}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:radially of arXiv:2505.14012, 'Ergodicity for stochastic neural field equations'] If for $J\in L^1(\mathbb{R}^d)$ there exists a non-negative decreasing function $j_0:\mathbb{R}\to [0,\infty)$ that is continuous except at a finite number of points such that
\begin{align*}
|J(x)|\leq j_0(|x|) =:J_0(x),\quad x\in\mathbb{R}^d,
\end{align*}
then $J_0$ is called a {radially decreasing majorant} of $J$.

[Lemma 6 of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] Let $(W, W')$ be as described above. Then
    \begin{equation}
        \EE[W'-W|\sigma] = \frac{1}{Nn^{3/2}}\left(-\frac{N^{2}}{N+2}|W|^{2}W + R_{1}\right),
    \end{equation}
    where
    \begin{equation}
    \begin{split}
        R_{1} &= \frac{N}{n^{1/4}}\sum_{i=1}^{n}\left[m_{(i)}f_{N}(|m_{(i)}|) - mf_{N}(|m|)\right] \\
        & \quad + Nn^{3/4}\left(f_{N}(|m|) - 1 + \frac{N|m|^{2}}{(N+2)}\right)m.
    \end{split}
    \end{equation}
    and 
    \begin{equation}
    \begin{split}
        \EE[(W'-W)(W'-W)^{\transpose}|\sigma] &= 2\frac{1}{Nn^{3/2}}\left(\id + R_{2}\right),
    \end{split}
    \end{equation}
    where 
    \begin{equation}
        \begin{split}
            R_{2} &= \left[\frac{N}{2n}\sum_{i=1}^{n}\sigma_{i}\sigma_{i}^{\transpose} - \frac{1}{2}\id\right] -
            \frac{N}{\sqrt{n}}WW^{\transpose} + \frac{N}{n^{2}}\sum_{i=1}^{n}\sigma_{i}\sigma_{i}^{\transpose}\\ 
            &\quad + \frac{N}{2n}\sum_{i=1}^{n}\,g_{N}(|m_{(i)}|)\,|m_{(i)}|^2\,
            \left[\sigma_{i}m_{(i)}^{\transpose}+ m_{(i)} \sigma_{i}^{\transpose} - \frac{\id}{N}\right]
            + \frac{N}{2n}\sum_{i=1}^{n}g_{N}(|m_{(i)}|)m_{(i)}m_{(i)}^\transpose. 
        \end{split}
    \end{equation}

