[Lemma dir_E[deg-edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e^{\textnormal{tail}} = \delta^{\textnormal{tail}}\in O(1)$ and $\delta_e^{\textnormal{head}}=\delta^{\textnormal{head}}\in O(1)$ and
\begin{enumerate}
    \item $\mathds{E}[(d_U^{\textnormal{out}})^{\delta^{\textnormal{tail}}}], \mathds{E}[(d_U^{\textnormal{in}})^{\delta^{\textnormal{head}}}] \in o(n)$
    \item $\exists c>0: \lim_{n \rightarrow \infty} \mathds{P}(d_U^{\textnormal{out}}, d_U^{\textnormal{in}} \geq 1) \geq c$
\end{enumerate}
then 
\begin{align*}
    \mathds{E}[DH_n] = \Big(\frac{\delta^{\textnormal{tail}}-1}{\delta^{\textnormal{tail}}} \cdot \frac{\delta^{\textnormal{tail}} \mathds{E}[(d_U^{\textnormal{out}})^2] - 2 \mathds{E}[d_U^{\textnormal{out}}]}{2 \mathds{E}[d_U^{\textnormal{out}}]} + \frac{\delta^{\textnormal{head}}-1}{\delta^{\textnormal{head}}}  \cdot \frac{\delta^{\textnormal{head}} \mathds{E}[(d_U^{\textnormal{in}})^2] - 2 \mathds{E}[d_U^{\textnormal{in}}]}{2 \mathds{E}[d_U^{\textnormal{in}}]}\Big)(1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:lp of arXiv:2606.19763, 'Optimal Sparsification of Gaussian Processes'] Let $p\geq2$, let $0<\alpha<1$, and let $T\sse\R^n$ be bounded.  
	Then there exists a subset $S\sse T$ and non-negative shifts $\{c_s\}_{s\in S}$ such
	that
	\[
		|S|
		\leq
		\exp\pbra{
			O\pbra{
				\frac{p}{\alpha^2}
			}
		}
		\qquad\text{and}\qquad 
		\left\|
			\sup_{t\in T}\bg\cdot t-\max_{s\in S}\{\bg\cdot s+c_s\}
		\right\|_{L^p(\gamma_n)}
		\leq
		\alpha\cdot w(T)\,.
	\]
	Additionally, there exists an integer $m\geq n$ and a set $U \sse \R^m$ such that  
	\[
		|U|
		\leq
		\exp\pbra{
			O\pbra{
				\frac{p}{\alpha^2}
			}
		}
		\qquad\text{and}\qquad 
		\left\|
			\sup_{t\in T}\bg\cdot(t,0_{m-n})-\sup_{u\in U}\bg\cdot u 
		\right\|_{L^p(\gamma_m)}
		\leq
		\alpha\cdot w(T)\,.
	\]

[Definition 3 (Cannings tree) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Given a population profile $q = (q(s))_{s \in \mathbb{N}_+}$ and offspring vectors $\nu^s = (\nu_1^s, \ldots, \nu_{q(s)}^s)$, we define the associated Cannings tree $\mathscr{T}$ as a subset of $\mathcal{U}$ constructed recursively as follows:
\begin{itemize}
    \item $\emptyset\in \mathscr{T}$;
    \item Suppose all elements \( u \in \mathscr{T} \) with \( |u| = s \) have been defined. Label them in lexicographic order as \( u^1 \prec u^2 \prec \cdots  \prec u^{q(s)} \). Then the elements \( u \in \mathscr{T} \) with \( |u| = s + 1 \) are defined as
    \[
    \left\{ u^i j : 1 \le i \le q(s),\, 1 \le j \le \nu^s_i \right\},
    \]
    where we set \( q(0) := 1 \) and \( \nu^0_1 := q(1) \).
\end{itemize}
The resulting set $\mathscr{T}$ is a prefix-stable subset of $\mathcal{U}$ representing a random rooted ordered tree.

[Proposition prop_LSI_fluct_measure_nonquad of arXiv:2503.24372, 'A criterion on the free energy for log-Sobolev inequalities in mean-field particle systems'] Let $\psi=(\varphi,\zeta)\in\bbH=\R^d\times\bbH_0$ (recall~(equation eq_def_Hilbert_space of the paper)). 
There are $c,N_0>0$ independent of $N,\psi,T$ such that
the fluctuation measure $\mu^{N,\psi}_T$ satisfies a log-Sobolev inequality with the following constant. 

\begin{itemize}
	\item[(i)] (Theorem 1 in~[wang2024LSI]). For any $N\geq N_0 e^{c\|\zeta\|_{\bbH_0}/T}$, 

\begin{equation}
\big(\gamma^{N,\psi}_{T}\big)^{-1}
\leq 
c\exp\big ( c\|\zeta\|_{\bbH_0}/T\big)
.
\end{equation}

\item[(ii)] For any $N\geq 1$ (recall that $M^2\geq \|W^+\|_\infty, \|W^- -\alpha(x,y)\|_\infty$ by (equation eq: borne sup n of the paper)),

\begin{equation}
\big(\gamma^{N,\psi}_{T}\big)^{-1}
\leq 
c\exp\Big( \frac{2M}{T}(  MN+2\|\zeta\|_{\bbH_0})\Big)
.
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

