body:
[Lemma 17 of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $p\in(1,\infty)$ and $0<\alpha<\beta\le2$, with the convention
    $(-\triangle)^{\frac{2}{2}}:=-\triangle$. Then
    \begin{equation}
        \norm{(-\triangle)^{\frac{\alpha}{2}}f}_{L^p(\R^n)}
        \lesssim_{\alpha,\beta,p}
        \norm{f}_{L^p(\R^n)}^{1-\frac{\alpha}{\beta}}\,
        \norm{(-\triangle)^{\frac{\beta}{2}}f}_{L^p(\R^n)}^{\frac{\alpha}{\beta}},
        \qquad f\in\mathscr S(\R^n).
    \end{equation}
    In particular, for all $f\in\mathscr S(\R^n)$,
    \begin{align}
        \norm{(-\triangle)^{\frac{\sigma}{2}}f}_{L^p(\R^n)}
        &\lesssim\norm{f}_{L^p(\R^n)}^{1-\sigma}\,
          \norm{Df}_{L^p(\R^n)}^{\sigma},
        &&0<\sigma<1,\\
        \norm{\flap f}_{L^p(\R^n)}
        &\lesssim\norm{f}_{L^p(\R^n)}^{1-\frac{s}{2}}\,
          \norm{D^2f}_{L^p(\R^n)}^{\frac{s}{2}},
        &&0<s<2,\\
        \norm{Df}_{L^p(\R^n)}
        &\lesssim\norm{f}_{L^p(\R^n)}^{1-\frac{1}{s}}\,
          \norm{\flap f}_{L^p(\R^n)}^{\frac{1}{s}},
        &&1<s<2.
    \end{align}

[Prop checking-the-inequalities of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Assume that ${\mathbf{w}}$ is log-concave and that $r=r({\mathbf{w}})$ is finite.
	Then the following holds for all $n\geq 0$,
	\begin{equation}
	\frac{\PFtrees{{\mathbf{w}}}{n+1}}{\PFtrees{{\mathbf{w}}}{n}}
	=
	\frac{
		\PFComp{\shift{r-1}{\mathbf{w}},{\mathbf{b}}}{n+1}
	}{
		\PFComp{\shift{r-1}{\mathbf{w}},{\mathbf{b}}}{n}}
	\leq
	\frac{
		\PFComp{\shift{r-2}{\mathbf{w}},{\mathbf{b}}}{n+1}
	}{
		\PFComp{\shift{r-2}{\mathbf{w}},{\mathbf{b}}}{n}}
	\leq
	\dots
	\leq
	\frac{
		\PFComp{\shift{1}{\mathbf{w}},{\mathbf{b}}}{n+1}
	}{
		\PFComp{\shift{1}{\mathbf{w}},{\mathbf{b}}}{n}}
	\leq
	\frac{
		\PFComp{\shift{0}{\mathbf{w}},{\mathbf{b}}}{n+1}
	}{
		\PFComp{\shift{0}{\mathbf{w}},{\mathbf{b}}}{n}}
	=
	\frac{\PFtrees{{\mathbf{w}}}{n+2}}{\PFtrees{{\mathbf{w}}}{n+1}},
	\end{equation}
	where we omit the ill-defined equality on the left when $n=0$.

[Theorem 10 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] When \(t\rightarrow\infty\),
		\begin{align}
			\PR\left(\mathcal{D}_\alpha \geq t\right) = & \frac{2^{d^2+d(\alpha-2)-(\alpha-2)}\pi^{\frac{d(d-1)}{2}}}{(d-1)!} \left(\frac{\Gamma\left(\frac{d+\alpha}{2}\right)}{\Gamma\left(d+\frac{\alpha}{2}\right)}\right)^{d-1} t^{d^2+d(\alpha-1)-\alpha} e^{-K_{d,\alpha}t^{d+\alpha}} \nonumber
			\\
			& \hspace{8cm} + \mathcal{O}\left(t^{d^2+d(\alpha-2)-2\alpha} e^{-K_{d,\alpha}t^{d+\alpha}}\right)
		\end{align}
		where
		\begin{equation*}
			K_{d,\alpha} = \frac{\sigma_{d-1} 2^{d+\alpha-1}}{d+\alpha} B\left(\frac{d-1}{2},\frac{d+\alpha+1}{2}\right).
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Suppose that $\mu,\nu \in \cP_2(\R^d)$ satisfy~\eqref{theta}, and let $(\theta_t)_{t\ge 0}$ denote the corresponding constants for $\mu$.
    Then,
\begin{align}
    \frac{\dd}{\dd t} \, \|\KM^\mu_{t\gets} - \KM^\nu_{t\gets}\|_{L^2(\gamma)}\geq -\theta_t\,\|\KM^\mu_{t\gets} - \KM^\nu_{t\gets}\|_{L^2(\gamma)} - \sqrt{\FI(q^\nu_t\mmid q^\mu_t)}\,.
\end{align}

