[Definition def : Topology/RegPD/HW of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $L>0$ and $D\in \RegPD[\mu]^L$. Consider a sequence $\p{ \sigma_k : \intervalleff0{L} \rightarrow X }_{k\ge 1}$ of $D$-geodesics. We recursively define the sequence $\p{\HW{D}{ (\sigma_k)_{1\le k \le K} } }_{K\ge 0}$ of functions in $\mathcal F_{\mathrm b} $ as such : $\HW{D}{\emptyset}= \mu$ and for all $K\ge 0$ and $x,y\inX$,
	\begin{equation}

	\begin{split}
		\HW{D}{ (\sigma_k)_{1\le k \le K +1} }(x,y) \coloneqq &\HW{D}{ (\sigma_k)_{1\le k \le K} }(x,y) \wedge  \min_{0 \le s,t \le L } \Bigl( \HW{D}{ (\sigma_k)_{1\le k \le K} }(x,\sigma_{K+1}(s) )\\
		 &\quad + D(\sigma_{K+1}(s) , \sigma_{K+1}(t) ) + \HW{D}{ (\sigma_k)_{1\le k \le K} }( \sigma_{K+1}(t) , y) \Bigr). 
	\end{split}
	\end{equation}

[Defn Order on fine slopes of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] We define a partial relation $\prec$ on generalized fine slopes generated by the following inequalities. First, for $s,t\in \mathbb{R} \cup \{\pm\infty\}$ we impose
    \begin{equation}
        s^\heartsuit \prec t^\diamondsuit
    \end{equation}
   when $s < t$ and $\heartsuit, \diamondsuit \in \{\natural, \flat, \sharp, \dagger\}$, and
    \begin{equation}
        s^\flat \prec s^\dagger \prec s^\sharp, \quad \text{and} \quad s^\dagger \prec s^\dagger.
    \end{equation}
    Second, we have 
    \begin{equation}
        -\infty^\dagger \prec \aleph^\natural, \aleph^\sharp \quad \mathrm{and} \quad
        \aleph^\natural, \aleph^\flat \prec +\infty^\dagger.
    \end{equation}

