[Lemma 8 of arXiv:2605.07184, 'Convergence of Stochastic Gradient Descent with mini-batching and infinite variance'] Under the assumption of \Cref{th:averaging_stable_convergence}, the matrices $G_{N,i}$
  are uniformly bounded, \ie\
  \begin{align}

    \sup_{N\geq1}\sup_{1 \leq i \leq N} \vvvert G_{N,i} \vvvert < \infty \; .
  \end{align}
  Furthermore, for every $\epsilon>0$,
  \begin{itemize}
  \item there exists $T$ such that for $N$ large enough and  $i\leq N-T/\gamma_N$, 
    \begin{align}
      x
      (1-\epsilon) A^{-1} \preceq       G_{N,i} \; ; 
    \end{align}
  \item there exists $i_0$ such that for all $i\geq i_0$ and $N\geq i$,
    \begin{align}

      G_{N,i} \preceq (1+\epsilon) A^{-1} \; .
    \end{align}
  \end{itemize}

