[Lemma lem:order_of_RNx of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $0\leq \nu<\xi\leq 1$ and $M\in \mathbb{Z}_{+}$. Then, for all $N$ large enough (depending on $M,\nu,\xi$), 
for all integers $0\leq l<l'\leq \lceil \xi M \rceil$, $|l-l'|>1$, every $x\in A_l$ and $y\in A_{l'}$,
\begin{equation}
        R_{N^{\nu},N^{\xi}}(x-y)\leq \begin{cases}
            (\xi-\frac{l'}{M}+ \frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \nu<\frac{l'}{M}<\xi,\\
            (\xi-\nu + \frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \frac{l'}{M}<\nu,
        \end{cases}
    \end{equation}
    and
    \begin{equation}
        R_{N^{\nu},N^{\xi}}(x-y)\geq  \begin{cases}
            (\xi-\frac{l'}{M}-\frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \nu<\frac{l'}{M}<\xi,\\
            (\xi-\nu-\frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \frac{l'}{M}<\nu.
        \end{cases}
    \end{equation}
Furthermore, for all $x,y\in\mathbb{Z}_{\text{even}}^2$ such that $|x|\leq N^{\frac{l}{2M}}$ and $|y|\geq N^{\frac{l+1}{2M}}$,
\begin{equation}
    R_{N^\xi}(x-y)\leq 2 R_{N^\xi}(y)\leq 4 R_{N^\xi}(x),
\end{equation}
Finally, for some universal constant $c>0$, 
\begin{equation} 
    \sup_{|y| \leq N^{\xi/2}}\sum_{|x|\geq N^{(\xi+1/M)/2}} R_N(x-y) \leq e^{-cN^{1/M}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lacuna-small of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] There exists a constant $C(d) > 0$ such that for all $t \geq \hat{t}$ and $\lambda > 0$,
  \begin{equation}

    u(\hat{t}, b_{\hat{t}}, \h\theta; t, \lambda) \leq C(d) \lambda A^2 (\log \hat{t})^{d/2} \, \hat{t}^{-A^2}.
  \end{equation}

