[Lemma 9 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] We denote $F_1:=[\widetilde{B}(10d^2N)]^c$ and $F_{-1}:=\widetilde{B}(\frac{N}{10d^2} )$. For any $d\ge 3$ with $d\neq 6$, $D\subset \widetilde{\mathbb{Z}}^d$, $N\ge 1$, $i \in \{1,-1\}$, and $v\in (\widetilde{\mathbb{Z}}^d\setminus D)\cap  F_i$,
 	\begin{equation}
 	 \begin{split}
 	 	\mathbb{P}^D\big( v\xleftrightarrow{\ge 0} \partial B(N) \big) \lesssim & N^{-(\frac{d}{2}\boxdot 3)}\sum\nolimits_{x\in \partial \mathcal{B}(d^{i}N)} \mathbb{P}^D\big( v\xleftrightarrow{\ge 0}x  \big). 	 \end{split}
 	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:shortcut-to-LRP of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] Recall that $b=b_X$ is the constant in (equation Eq2 of the paper). 
Let $F$ be bounded and uniformly continuous.  For each fixed $\varepsilon\in(0,1)$,
\begin{equation*}

\lim_{\delta\downarrow0}\limsup_{n\to\infty}
\left|
\mathbb{E}\left[F\left(\frac{\sum_{i=1}^{N_\varepsilon}\hat{X}_i-X_n}{n(\log n)^{-3/2}}\right)\right]
-
