body:
[Proposition prop: osc of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Let $R$ be a $d \times k$ weak $\mathcal S$ matrix with respect to $S = \{x \in \mathbb{R}^d: n_i \cdot x \ge b_i \ \text{for all }1\le i \le m\}$ and a function $f:\{1,2,\dots, k\} \to \mathcal P(\{1,2,\dots, d\})$ such that \begin{itemize}
        \item [(1)] $f(j) \not = \emptyset$ for all $j \in \{1,2,\dots, k\}$,
        \item [(2)] for each $i \in \{1,2,\dots, d\}$, $f(j) = \{i\}$ if and only if $j = i$.
    \end{itemize}

    Suppose that $\delta > 0$, $0 \le t_1 < t_2<\infty$ and $w,x\in C([t_1,t_2], \mathbb{R}^d)$, $y \in C([t_1,t_2], \mathbb{R}^k)$ are such that 
    \begin{itemize}
        \item [(i)] $w(t) = x(t) + Ry(t)$ for all $t \in [t_1, t_2]$, 
        \item [(ii)] $w(t) \in S$ for all $t \in [t_1, t_2]$,
        \item [(iii)] for $j \in \{1,2,\dots, k\}$, 
        \begin{itemize}
            \item [(a)] $y_j(t_1) \ge 0$,
            \item [(b)] $y_j$ is non-decreasing, 
            \item [(c)] $\int^{t_2}_{t_1} \mathbf{1}_{F^{\delta}_{f(j)}}(w(s)) dy_j(s) = y_j(t_2)-y_j(t_1)$.
        \end{itemize}
    \end{itemize}
    Then, there exists a constant $C >0$ depending only on $R$, $S$, and $f$ such that 
    \begin{align}
        Osc(y,[t_1,t_2]) &\le C(Osc(x, [t_1, t_2])+\delta), \\
        Osc(w,[t_1,t_2]) &\le C(Osc(x, [t_1, t_2])+\delta),
    \end{align}
    where \begin{align*}
        Osc(g, [t_1,t_2]):=\sup\{\max_{1 \le \ell \le n}|g_\ell(t)-g_\ell(s)|: t_1 \le s < t \le t_2\}
    \end{align*}
    for any $g \in C([t_1, t_2], \mathbb{R}^n)$ and positive integer $n$.

