body:
[Proposition 22 of arXiv:2605.14206, 'The clumsy coupon collector's problem'] The following limit holds for all $t < 0$ as $m \to \infty$,
  \[
    m^{-t} \binom{m \, e^{-t/m}}{m}^{-1} 
    \longrightarrow \Gammaop(1-t).
  \]
  \begin{proof}
    Combine the facts $m\,e^{-t/m} = m - t + O(m^{-1})$
    and $\binom{-\nu}{m} = (-1)^m \binom{\nu+m-1}{m}$
    from
    \cite[pp.~49--56]{oldham2009atlas}
    to write
    \begin{align*}
      m^{-t} \binom{m\,e^{-t/m}}{m}^{-1}
      &= m^{-t} \binom{m-t+O(m^{-1})}{m}^{-1}
      = m^{-t} \binom{m+(1-t+O(m^{-1}))-1}{m}^{-1}\\
      &= m^{-t} \left(-1\right)^m \binom{t-1+O(m^{-1})}{m}^{-1}.
      \intertext{Next use the asymptotic expression
      $\binom{\nu}{m}^{-1} \sim (-1)^m \, m^{\nu+1} \Gammaop(-\nu)$,}
      &\sim m^{-t} \, m^{t+O(m^{-1})} \Gammaop(1-t+O(m^{-1}))
      \sim \Gammaop(1-t). \qedhere
    \end{align*}
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

