[Lemma Malianx of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] If $ A_t, B_t $ and $ C_t $ are measurable and essentially bounded deterministic functions in $ t $, then, Eq. ((mSDEline of the paper)) admits a unique solution. Moreover, let $X_t$ be the solution of ((mSDEline of the paper)), then
	\begin{equation}
	D^{\phi}_tX_t= X_t\int_{0}^{t}\phi(t,s)C_s\mathrm{d}s, \, \forall t\in[0,T], \, a.s.
	\end{equation}

[Lemma 28 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Suppose that $\rform{\cdot}{\cdot}{\Gamma}$ is a weak \clekp{} resistance form. Then almost surely the following holds. Let $V \in \metregions$ and $V_1,\ldots,V_n \in \metregions$, $n \in \N$, such that $V_i \cap V_j = \emptyset$ for $i \neq j$ and $\bigcup_i \ol{V_i} \cap \Upsilon_\Gamma = \ol{V} \cap \Upsilon_\Gamma$. Then
 \begin{align*}
  \rfdomainres{V}{\Gamma} &= \{ f : f|_{V_i} \in \rfdomainres{V_i}{\Gamma} \text{ for each } i \} ,\\
  \text{and}\quad
  \rformres{V}{f}{f}{\Gamma} &= \sum_i \rformres{V_i}{f}{f}{\Gamma} .
 \end{align*}

[Definition 45 (Property~\ref{prop:digits}: Matching digits) of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Consider fixed constants $\epsilon\in[0,1]$ and $k\in\Z_{\geq 0}$.
    We say that a Glauber dynamic $R$ \emph{matches digits up to $(\epsilon,k)$}
    if we may find an event $M\subset\Sigma$ of $\diff\iota$-probability at least $1-\epsilon$ such that:
    \begin{itemize}
        \item For any $u\in V$ and $\iota\in M$, we have
        \[
            \big\{
                \{R_{u,\iota}(\tau)_{1,u}\}_k=\{R_{u,\iota}(\tau')_{1,u}\}_k \text{ for all $\tau,\tau'\in \Pi_G$}
            \big\}
        \]
        \item For any $u\in V$ and $\tau\in\Pi_G$,
        the event $M$ and the random variable $\lfloor R_{u,\iota}(\tau)_{1,u}\rfloor_k$
        are $\diff\iota$-independent.
    \end{itemize}
    The event $M$ is called the \emph{matching event}.

[Proposition 30 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] For $k\ge n_1$ and for all $n$ large enough we have 
\begin{align*}
\left\{\frac{u_k}{u_{k-1}}\ge 1\right\}\cap \mathcal{A}_n \subset \left\{\frac{u_{k+1}}{u_k}>1+\frac13 \frac{a^2 }{(n-k+2a)^{3/2} \sqrt{n-k}}\right\}\cap \mathcal{A}_n.
\end{align*}

[Lemma 2-l22 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Fix a finite subset $D$ of ${\mathbb Z}^d$ with at least two elements. Then,
there exist a finite constant ${\mathfrak c}({\boldsymbol u}^N)$, uniformly bounded in
$N$ and depending only on ${\boldsymbol u}^N$ and $D$, such that
\begin{equation*}
{\mathbb E}_{\nu_N} \Big[ \,
\Big | \, \int_0^t {\mathscr Y}^{1,D,N}_{s}   \; ds \, \Big |^a \,
\Big]
\,\le\, {\mathfrak c}({\boldsymbol u}^N) \, T^a\,
\sup_{0\le r\le T} (1+\Vert F(r) \Vert^2_\infty)^a\,
\Big(\frac{1}{N^{d/2}}\Big)^{\theta/c} \, {\mathscr K}_N^{1/c}\;,
\end{equation*}
for all $N\ge 1$, $0\le t\le T$, $a>0$, $1\leq b\leq 2$,
and $0<\theta<1$ such that
\begin{equation}

\theta \,+\, (1-\theta) b \,>\, a\;.
\end{equation}
In this formula, $c = [\, \theta \,+\, (1-\theta) b\,]/ a >1$, and
\begin{equation*}
{\mathscr K}_N \,:=\, K^{[7 \theta + 3b(1-\theta)]/4}\, [\kappa_N(T)\,
(N/\ell_N)^d]^{\theta + (1/2) b (1-\theta)}\;.
\end{equation*}

