[Proposition prop:deformKLprop of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi \in \mathcal{P}(\mathcal{X})$ and $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ be an isometric involution transition matrix. For $P,L \in \mathcal{L}$, we have the following:
	\begin{enumerate}
		\item(Non-negativity) 
		\begin{align*}
			{}^Q D_{KL}(P \| L) \geq 0.
		\end{align*}
		Equality holds if and only if $QP = QL$ if and only if $P = L$. Similarly, 
		\begin{align*}
			D_{KL}^Q(P \| L) \geq 0.
		\end{align*}
		Equality holds if and only if $PQ = LQ$ if and only if $P = L$.

		\item(Duality) Let $P,L \in \mathcal{S}(\pi)$.
		\begin{align*}
			{}^Q D_{KL}(P \| L) = D_{KL}^Q(P^* \| L^*).
		\end{align*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2609.02019, '2609.02019'] Let $\sigma\in\mathscr S(\mathbb R;\mathbb R)$, and define
		\[
		\mathsf K_\sigma(z,y)
		\triangleq
		\frac{\sigma(z)-\sigma(y)}{(z-y)^2}
		-
		\frac{\sigma'(z)}{z-y}
		=
		\frac{
			\sigma(z)-\sigma(y)-\sigma'(z)(z-y)
		}{
			(z-y)^2
		},
		\qquad z\neq y.
		\]
		Then $\mathsf K_\sigma$ extends uniquely to a function in
		$C^\infty(\mathbb R^2)$, still denoted by $\mathsf K_\sigma$, and
		\[
		\mathsf K_\sigma(z,z)
		=
		-\frac12\sigma''(z),
		\qquad z\in\mathbb R.
		\]
		Moreover, the following estimates hold:
		\begin{equation}
			\sup_{z\in\mathbb R}
			\left\|
			\mathsf K_\sigma(z,\cdot)
			\right\|_{L_y^2}
			\le
			\frac43
			\left\|\sigma''\right\|_{L^2},
		\end{equation}
		\begin{equation}
			\sup_{z\in\mathbb R}
			\left\|
			\partial_z^a\partial_y^b
			\mathsf K_\sigma(z,\cdot)
			\right\|_{L_y^1}
			\le
			\left(
			\int_0^1
			(1-\vartheta)^{a+1}
			\vartheta^{b-1}
			\d \vartheta
			\right)
			\left\|
			\sigma^{(a+b+2)}
			\right\|_{L^1},\quad a\in\mathbb N_0,\ b\in\mathbb{N},
		\end{equation}
		and
		\begin{align}
			\sup_{z\in\mathbb R}
			\left\|
			\partial_y
			\left[
			\sigma(\cdot)
			\partial_y\mathsf K_\sigma(z,\cdot)
			\right]
			\right\|_{L_y^1} \le
			\frac12
			\|\sigma'\|_{L^\infty}
			\|\sigma^{(3)}\|_{L^1}
			+
			\frac16
			\|\sigma\|_{L^\infty}
			\|\sigma^{(4)}\|_{L^1}.

		\end{align}

[Corollary 16 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] For $B\in\cX_0$ we have
  \begin{equation}

    \BE \partial\eta(B)^{(2)}
    =\BE \lambda_{[\eta]^c}(B)^2
    -2 \,\BE \int_B \I\{x\notin[\eta]\}
    \lambda_B\big([\eta+\delta_x]\setminus[\eta]\big)\,\lambda(dx).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 6 of arXiv:2607.17576, 'How much randomness is needed to symmetrize a random variable?'] Let $0<p<1$ and write $q:=1-p$. Let $X\sim\text{Geom}(p)$ be a geometric random variable with the probability mass function $f_X(k)=pq^k$ for $k\in \mathbb{Z}_{\ge 0}$. Let $Y$ be an integer-valued independent symmetrizer of $X$. Then we have for all $\alpha>0$ that
\begin{equation}
H_\alpha (Y)\ge H_\alpha(X)
\end{equation}
and
\begin{equation}
T_\alpha (Y)\ge T_\alpha(X).
\end{equation}
Equality holds if and only if $Y$ is an independent copy of $-X$.

