[Lemma lem_flow_2 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under the assumptions of (lem_flow_1 of the paper), let $\left(z_1\right)_t,\left(z_2\right)_t,\left(z_3\right)_t \in$ $\left\{z_t, \overline{z}_t\right\}$ for $t\in \left[{t_0,t_c}\right]$. Then, we have that for all $t\in [t_0,t_m]$,
    \begin{equation}
        \begin{aligned}
            \left\|L_{(1,2,3), t}-K_{(1,2,3), t}\right\|_2 \prec \frac{\left(t_c-t_0\right)^3}{\left(t_c-t\right)^3}\left\|L_{(1,2,3), t_0}-K_{(1,2,3), t_0}\right\|_2+\frac{N^{\varepsilon_g}}{N\left(t_c-t\right)^3\left(\operatorname{Im} m_t\right)^3}.
        \end{aligned}
    \end{equation}
Combining this with (equation t_eta of the paper), (equation im_m_t_sim_through_evolution of the paper), (equation largG_3G_1 of the paper), and (equation largG_3G_2 of the paper), we obtain that for all $t\in\left[{t_0,t_m}\right]$,
    \begin{equation}
        \begin{aligned}
            \left\|L_{(1,2,3), t}-K_{(1,2,3), t}\right\|_2 \prec \frac{N^{\varepsilon_g}}{N\left(t_c-t\right)^3\left(\operatorname{Im} m_t\right)^3} \ .
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2607.12667, 'Phase Transition of Eigenvalues of Covariances from the Spiked Mixture Model in High-dimen'] Let $\X \in \mathbb{R}^{d\times n}$ have \ac{iid} Gaussian entries $\sim \mathcal{N}(0,1)$. Partition the columns as $\X = \begin{bmatrix}
    \X_1 & \X_2 & \ldots & \X_K
\end{bmatrix}$, with $\X_i \in \mathbb{R}^{d\times n_i}$, $(n_1,\ldots, n_K) \sim \text{Mult}(n,\pi_1, \ldots, \pi_K)$, an independent random vector sampled from the multinomial distribution. For $i,j \in [K]$, set:
\begin{align*}
    \Sb_n &:= \frac{\X\X^\mathsf{T}}{n}, &&\R_n(z):= (z\I- \Sb_n)^{-1}, \text{and }&&\Bb_n(z) := \frac{\X_i\X_i^\mathsf{T}}{n_i} \R_n(z)\frac{\X_j\X_j^\mathsf{T}}{n_j},
\end{align*}
where $z \in \mathbb{C}\setminus \{\lambda_1(\Sb_n), \ldots, \lambda_d(\Sb_n)\}$.

Assume $d,n \to \infty$ with $d/n \to \gamma \in (0, \infty)$. Then, 
\begin{align*}
    \frac{1}{d}\Tr(\Bb_n(z)) \xrightarrow[]{\text{a.s.}} T(z) \left(\frac{\gamma}{\pi_i} \ind_{i=j} + \frac{1}{1-\gamma G(z)}\right),
\end{align*}
where $T(z) = \int_t \frac{t}{z-t} d\mu_{\text{MP}(\gamma)}(t)$, $G(z) = \int_t \frac{1}{z-t} \mu_{\text{MP}(\gamma)}(t)$ are respectively the $T$- and the Cauchy transform of the \acl{MP} law of parameter $\gamma$.
Moreover, this convergence is uniform on $\mathcal{K}(\eta) = \{z\in \mathbb{C},\: d(z,[a,b])> \eta\}$ for all $\eta>0$.

