[Theorem 6 (Necessary Maximum Principle) of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] Assume $({\bf A4)}$-$({\bf A6})$ hold. Let $\hat{u} \in \mathcal{A}_{\mathcal{G}}$, and denote by $\hat{X}(t)$  the corresponding state process solving \eqref{ee1}. Let $(\hat{p}(t), \hat{q}(\cdot,t))$ be the adjoint processes associated with $\hat{u}$, solution of \eqref{p}. Then, the following statements are equivalent.
\begin{itemize}
\item[(i)] For every bounded $\beta\in \mathcal{A}_{\mathcal{G}}$, we have
\begin{eqnarray*}
\lim_{s \to 0}\frac{J(x_{0},\hat{u}+s\beta)-J(x_{0},\hat{u})}{ds} =\frac{dJ}{ds}(x_0,\hat{u}+s\beta)|_{s=0}= 0
\end{eqnarray*}
\item[(ii)] For all $t \in [0,T]$, we have
\begin{eqnarray*}
\mathbb{E} \left[ \left. \frac{\partial \mathcal{H}}{\partial u} \left(t,\hat{X}(t), \hat{u}(t), \hat{p}(t), \hat{q}(\cdot,t) \right) \, \right| \, \mathcal{G}_t \right]= 0 \quad \text{p.s.}		
\end{eqnarray*}
\end{itemize}

