[Lem lem3 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $p\ge 2$ and $q\in [p,\frac{(n+2)p}{n}]$. Then there exists $C(p,q)>0$ such that
  \begin{equation} \label{3.1}
	\int_\Omega |\nabla\varphi|^q
	\le C(p,q) \cdot \bigg\{ \int_\Omega |\nabla\varphi|^p \bigg\}^\frac{q-p}{p} \cdot \int_\Omega |\nabla\varphi|^{p-2} |D^2 \varphi|^2
	\qquad \mbox{for all $\varphi\in C^2(\overline{\Omega})$ fulfilling $\varphi=0$ on $\partial\Omega$.}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition diag:pb-regular-card of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] A regular cardinal $\kappa$ is \emph{$(S,T)$-regular} if for every pullback
    \begin{equation}
        \begin{tikzcd}
            X\arrow[r, "f'"]\arrow[dr,pullback]\arrow[d, "s'"'] & A\arrow[d,"s"]\\
            C\arrow[r,"f"'] & B
        \end{tikzcd}
    \end{equation}
    in $\PSh(T)$ such that $A,B,C$ are representable and $s$ is a map in $S$ (so that $X\in\PSh(S)$ by the definition of a cleft), $X$ can be written as a $\kappa$-small colimit in $\PSh(S)$ of representables.

[Lemma 21 (Six-move elimination) of arXiv:2608.08242, 'Bang--bang representation of $3\times 3$ embeddable stochastic matrices'] Suppose that $U\notin\V$.  Then $U\in R_6$ in each of the following
regions:
\begin{enumerate}[(1)]
\item $1<r\leq2$ and $\min(x,y)\leq r$;
\item $r\geq3$ and $\max(x,y)\geq r$;
\item $2\leq r\leq3$ and $\min(x,y)\geq r$.
\end{enumerate}

[Corollary 49 (Full Newton congruence filtration) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $n\ge2$, and $r>s\ge0$,
\begin{equation}
 J_r^{SU(n)}(K;q)-J_s^{SU(n)}(K;q)
 \in\{r-s\}\{r+s+n\}\Z[q^{\pm1}].
\end{equation}
More generally, for $0\le m<r$,
\begin{equation}
 J_r^{SU(n)}(K;q)\equiv
 \sum_{k=0}^{m}C_{r+1,k}^{(n)}H_k^{(n)}(K;q)
 \pmod{C_{r+1,m+1}^{(n)}\Z[q^{\pm1}]}.
\end{equation}

[Proposition 1 of arXiv:2604.00598, 'Allowing for Imprecision in the Game-theoretic Characterisation of the Poisson Process'] Suppose \(\gencapprocs\) contains all constant processes and is a cone---that is, closed under pointwise addition and multiplication with positive scalars.
Then for all \(\stopt\in\stopts\), \(f, g\in\stoptdom\)  and \(\mu\in\reals\),
\begin{enumerate}[label=\upshape{E\arabic*.}, ref=\upshape(E\arabic*), leftmargin=*, series=gencuprev]
\item \(\gencuprev{f}\leq\sup f\);
\item \(\gencuprev{f+g}\leq\gencuprev{f}+\gencuprev{g}\);
\item \(\gencuprev{\mu f}=\mu \gencuprev{f}\) whenever \(\mu>0\);
\item \(\gencuprev{f}\leq\gencuprev{g}\) whenever \(f\leq g\);
\item \(\gencuprev{f+\mu}=\gencuprev{f}+\mu\).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:rank-defect-frontier of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For $h\geq2$, $k\geq3$, and $0\leq r\leq k-2$,
\begin{equation}
 \min_{\substack{A\subset\mathbb Z,\ |A|=k\\r_h(A)=r}}
 \left(M_{h,k}-|hA|\right)=r.
\end{equation}
Equivalently,
\[
 \max_{\substack{A\subset\mathbb Z,\ |A|=k\\r_h(A)=r}}
 |hA|=M_{h,k}-r.
\]
Equality holds precisely when $\operatorname{cnul}_h(A)=0$.

[Lemma 25 of arXiv:2604.01978, 'Homogenized Transformers'] For $\bA=\frac{1}{d\sigma_{\bA}^{2}}\bW^{\sT}\bW'$, we have 
\begin{equation*}
\E\left\<\frac{\bA x}{\|\bA x\|},\frac{\bA y}{\|\bA y\|}\right\>= \langle x,y\rangle\,+\frac{\<x,y\>^{3}-\<x,y\>}{2d}+O(d^{-\frac32}).
\end{equation*}

