   where for any $\phi \in \mathcal{M}$
   \begin{equation}
   H_i(\phi) = 
   \begin{cases}
   -f_i(\phi) + \frac{1}{2}\sigma_{ii}g_i^2(\phi) & \textrm{if }  x_i = \phi_i(0) =0 \\        
   V_i'(x_i)x_if_i(\phi) + \frac{1}{2}\sigma_{ii}^2V_i''(x_i)x_i^2g_i^2(\phi) & \textrm{otherwise} \,,
       \end{cases}
