body:
[Lemma lem: CokMp_Trivial of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Let $q = p^{\operatorname{deg}(\beta)}$. Then, for every $n\geq 1$, 
    \begin{align}
        \biggl\lvert \, \bbP\biggl(\frac{\coker(\bM_{p,\beta})}{p\coker(\bM_{p,\beta})}  \cong 0   \biggr) - \prod_{i\geq 0}\Bigl(1 - \frac{1}{q^{2i+1}} \Bigr)     \, \biggr\rvert \leq \frac{3}{q^n}.
    \end{align}

[Proposition 22 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$ and $f:\cube^n\to \Rbb$,
\begin{equation}
    \Wop^{\geq k}(f) \leq \sum_{J\subseteq [n]:|J|=k} \Vop_J(f) \leq \Vop^k(f) \leq \left\|\left|\grad^k f\right|\right\|_{\Leb^2}^2.
\end{equation}

