body:
[Lemma root-mag-consensus-for-ising of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Let $\ising$ be a $\TIS$ Ising measure $\ising$ on $T^\k$ with temperature parameter $\beta$, external field $B$ and boundary law $\ell\in \P\cpr{\pr{1,-1}}$ corresponding to a fixed point $\theta\in \R$ of the Ising cavity map, as specified in Remark (\oldref{remark:BP-and-ising-cavity}) below. According to Remark (\oldref{rmk:external-field-p}), let $\nu\in \P(\{1,-1\})$ be such that $\nu(1)=p$ with $B=\log(p/(1-p))$ and define $\smref$ with respect to $\nu$ in each cases. 
 Then the following statements hold:  
 \begin{enumerate}
     \item In the ferromagnetic regime $(\beta>0)$:
     \begin{enumerate}
         \item If $B>0$, then $\ising^+_\k(\beta,B)$ is the unique $\TIS$ Ising measure that has a positive root magnetization. Moreover, the consensus under $\ising^+_\k(\beta,B)$ is greater than typical, that is, 
         \begin{equation}
             \bbE_{\ising^+_\k(\beta,B)}\sqpr{S_m}>\smref.
         \end{equation}
         \item If $B<0$, then $\ising^-_\k(\beta,B)$ is the unique $\TIS$ Ising measure that has negative root magnetization. Moreover, the consensus under $\ising^-_\k(\beta,B)$ is greater than typical,  that is, 
         \begin{equation}
             \bbE_{\ising^-_\k(\beta,B)}\sqpr{S_m}>\smref.
         \end{equation}
         \item If $B=0$, then in the uniqueness regime $\beta\leq \betacrit(\k,0)$, we have
         \begin{align}
             \bbE_{\ising_\k^*(\beta,0)}[\pmb\sigma_o]=0\quad \text{and}\quad\bbE_{\ising_\k^*(\beta,0)}[S_m]=\k\tanh(\beta)>\smref=0.
         \end{align}
         In the non-uniqueness regime $\beta> \betacrit(\k,0)$, we have
         \begin{align}
             \bbE_{\ising_\k^+(\beta,0)}[\pmb\sigma_o]>\bbE_{\ising_\k^\sharp(\beta,0)}[\pmb\sigma_o]=0>\bbE_{\ising_\k^-(\beta,0)}[\pmb\sigma_o]
         \end{align}
         and
    \begin{align}
    \bbE_{\ising_\k^+(\beta,0)}[S_m]=\bbE_{\ising_\k^-(\beta,0)}[S_m]>\bbE_{\ising_\k^\sharp(\beta,0)}[S_m]=\k\tanh(\beta)>\smref=0.
    \end{align}
     \end{enumerate}
     \item In the antiferromagnetic regime ($\beta<0$):
     \begin{enumerate}
         \item If $B>0$, then
         \begin{equation}
             \bbE_{\ising_\k^\sharp(\beta,B)}[\pmb\sigma_o]>0\quad \text{and}\quad \bbE_{\ising_\k^\sharp(\beta,B)}[S_m]<\smref.
         \end{equation}
         \item If $B<0$, then
         \begin{equation}
             \bbE_{\ising_\k^\sharp(\beta,B)}[\pmb\sigma_o]<0\quad \text{and}\quad \bbE_{\ising_\k^\sharp(\beta,B)}[S_m]<\smref.
         \end{equation}
         \item If $B=0$, then
         \begin{equation}
             \bbE_{\ising_\k^\sharp(\beta,0)}[\pmb\sigma_o]=0\quad \text{and}\quad \bbE_{\ising_\k^\sharp(\beta,0)}[S_m]=\k\tanh(\beta)<\smref=0.
         \end{equation}
     \end{enumerate}
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

