[Definition 10 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm (\cite[Definition 3.1]{DuanJTP2025}) A pair $(\bar{z},K)$ is called a solution to Eq.\,\eqref{deterministicparabolicobstacleEq} if it satisfies the following conditions}
\begin{itemize}
\item[(i)] {\rm $\bar{z}$ is continuous function on $[0,T]\times[0,1]$ satisfying $\bar{z}(t,x)\geq-v(t,x)$, $\bar{z}(t,0)=\bar{z}(t,1)=0  \text{ and } \bar{z}(0,x)=0$.}
\item[(ii)] {\rm $K$ \text{is a measure on} $(0,1)\times\mathbb R_+$ \text{such that}  $K\left((\e,1-\e)\times[0,T]\right)<\infty$ for every small $\e>0$ and $T>0$.}
\item[(iii)] {\rm $\bar{z}$ weakly solves the partial differential equation}
{\rm \begin{align}
\frac{\partial \bar{z}}{\partial t}=\frac{\partial^2 \bar{z}}{\partial x^2}+\dot{K}.
\end{align}
\text{That is, for every} $t\in [0,T]$ and every $\varphi\in  C_0^2 ([0,1])$,
$$
\int_0^1 \bar{z}(t,x)\varphi(x)\mathrm{d}x=\int_0^t \int_0^1 \bar{z}(s,x)\varphi''(x)\mathrm{d}s\mathrm{d}x+\int_0^t \int_0^1 \varphi(x)K(\mathrm{d}s,\mathrm{d}x).
$$}
\item[(iv)] {\rm
$$
\int_0^t \int_0^1 \left(\bar{z}(s,x)+v(s,x)\right)K(\mathrm{d}s,\mathrm{d}x)=0
$$}
\end{itemize}

[Proposition 14 of arXiv:2608.26974, 'Why not to use the Gaussian kernel'] If $k$ is a positive-semidefinite kernel on an open set $D \subset \R^d$ such that $k^{\alpha,\alpha}$ exists and is continuous for every $\alpha \in \N_0^d$ such that $\lvert \alpha \rvert \leq m$, then every $f \in H(k)$ is $m$ times continuously differentiable and
  \begin{equation}  
    \mathrm{D}^\alpha f(x) = \langle f, \mathrm{D}_x^\alpha k(\cdot, x) \rangle_{H(k)} 
  \end{equation}
  for any $\alpha \in \N_0^d$ such that $\lvert \alpha \rvert \leq m$ and $x \in D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

