body:
[Definition def:Bernoulli-split of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $\Omega = \{0, 1\}^{E \times \llbracket 1, M \rrbracket} \times \{0, 1\}^{\mathbb Z^d \times \llbracket 1, N \rrbracket}$. We define, for $e \in E$ and $l \in \llbracket 1, M \rrbracket$,
  \begin{equation}
    Y_{e, l}: (y, z) \in \Omega \mapsto y(e, l) \in \{0, 1\}
  \end{equation}
  and, for $x \in \mathbb Z^d$ and $k \in \llbracket 1, N \rrbracket$,
  \begin{equation}
    Z_{x, k}: (y, z) \in \Omega \mapsto z(x, k) \in \{0, 1\}.
  \end{equation}
  We call these Bernoulli variables base variables. We define for $l \in \llbracket 1, M \rrbracket$ the function
  \begin{equation}
    p_l: \beta \in \mathbb R_+^* \mapsto 1 - \frac {1 - h_l(\beta)} {1 - h_{l-1}(\beta)} \in [0, 1].
  \end{equation}
  Let $\mathbb P$ be the product probability measure on $\Omega$ such that
  \begin{equation}
    \mathbb P(Y_{e, l} = 1) = p_l(\beta) \text{ for all $e \in E$,$l \in \llbracket 1, M \rrbracket$} 
  \end{equation}
  and
  \begin{equation}
    \mathbb P(Z_{x, k} = 1) = \frac {q_\nu(\llbracket k, N \rrbracket)} {q_\nu(\llbracket k-1, N \rrbracket)}
    \text{ for all $x \in \mathbb Z^d$, $k \in \llbracket 1, N \rrbracket$.}
  \end{equation}
  We define
  \begin{equation}
    \nu_x = \min \{n \in \llbracket 0, N \rrbracket : \forall 1 \leqslant k \leqslant n, Z_{x, k} = 1 \}
  \end{equation}
  and we say that an edge $e = \{x, y\}$ is open if
  \begin{equation}
    \max\limits_{1 \leqslant l \leqslant \zeta(\nu_x, \nu_y)} Y_{e, l} = 1.
  \end{equation}

[Theorem 6 (Supercritical cutoff for $Z^{(N)}$) of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let $x_N\in[-1,1]^N$ be deterministic and suppose
  \begin{equation*}
    q_N:=N^{-1}\norm{x_N}_2^2
    \to
    q_0.
  \end{equation*}
  Then, for all sufficiently large $N$, $K_{A,N}$ has a
  unique nonzero invariant law $\nu_{A,N}$, and
  \begin{equation}
    \lim_{c\to\infty}\liminf_{N\to\infty}
    \norm{K_{A,N}^{n_N(-c)}(q_N,\cdot)-\nu_{A,N}}_{\TV}
    =1,
  \end{equation}
  while
  \begin{equation}
    \lim_{c\to\infty}\limsup_{N\to\infty}
    \norm{K_{A,N}^{n_N(c)}(q_N,\cdot)-\nu_{A,N}}_{\TV}
    =0.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Pro 12 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. Then
	\begin{align*}
		\reg(\phi)=\big\{x\in\Omega:\partial_P \phi(x)\neq\varnothing\big\},\qquad \cut(\phi)=\big\{x\in\Omega:\partial_P \phi(x)=\varnothing\big\}.
	\end{align*}
	Moreover, for any $x\in\reg(\phi)$, $\phi$ is differentiable at $x$ and $\partial_P \phi(x)=\{D\phi(x)\}$.

[Lemma lm:bulinsk of arXiv:2411.11429, 'Functional Central Limit Theorem for topological functionals of Gaussian critical points'] [Bulinskaya]

Let \( p'<p \) be integers, \( A \) a bounded Borel  set of \( \mathbb R^{p'} \). For $ 1\le i\le p,$ let \( g_i:A\to \mathbb R^{d_i} \) be a smooth centred Gaussian field  {such that\begin{itemize}
\item $ \|g_i(x)\|$ and $ \| \nabla g_i(x)\|$ are bounded  by $ \| (\partial _{ \alpha }F(x);\alpha \in I_i)\|$ for some finite $ I_i$,
\item   $G(x) := (g_i(x))\in \mathbb R^{p^{*}}
$ has a uniformly bounded density, where \( p^{*} = \sum_id_i.\)
\end{itemize} }
Let \( h_i:\mathbb R^{d_i}\to \mathbb R \)  smooth functions such that $ h_{ i}$ and its derivative are bounded by $c_{ l} \|x\|^{ l}$ for some $l>0$, and \( f_i(x): = h_i(g_i(x)),1\le i\le p. \) Assume also that each \( h_i(X) \) has a density bounded on \( [-\varepsilon, \varepsilon ] \) for some \( \varepsilon >0 \) on the input \( X\sim \mathcal N(0,I_{d_i}) \). Let
 \(a\in (0,1) \) and
\begin{align*}\psi (x) = (f_i(x))_{i = 1}^p\in \mathbb R^p.
\end{align*}  There is \( c_a ,\tau_a >0 \) such that for \( \tau \in (0,\tau_a ) \), 
\begin{align*}
\mathbf P(\inf_{x\in A}\|\psi (x)\|\le \tau )\le c_a  (1 +  \text{\rm{diam}}(A))^{2d} \tau ^{a }.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma untied-effective-bias of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under the conditions of Theorem (theo:untied-SGD of the paper), let \(J\) be a
stopping time satisfying (equation eq:stopping-time of the paper), and fix \(T>0\). Set $\tau_d:=\frac{\alpha_d}{d}$ and $N_T:=\left\lfloor\frac{Td}{\alpha_d}\right\rfloor$.
Then, 
\begin{align}
&\sup_{0\le\tau\le T}
\left|
\tau_d
\sum_{n=0}^{m_d(\tau)-1}
\mathbf 1_{\{n<J\}}
\sum_{\substack{i=1\\k_i\in\mathcal K}}^w
\left(
\sqrt d\,b_{k_i}^{(n)}
-
\beta_{k_i}^{(d,n)}
\right)
\mathcal T_i^{\mathrm{bias}}(\mu^{(n)})
\right|
\xrightarrow{\mathbb P}0,

\end{align}
where $m_d(\tau):=\left\lfloor\frac{\tau d}{\alpha_d}\right\rfloor$.

[Theorem thm:itolyons of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Fix $N<\infty$ and a bounded set of weakly geometric $p$-rough paths. The map
\begin{equation}
\mathbf x\longmapsto \mathrm{Sig}^{(N)}(\mathbf x)
\end{equation}
from the $p$-variation rough-path topology to $T^{(N)}(\mathbb{R}^d)$ is continuous.

[Lemma 53 (Persistence Lemma) of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] If $\gamma,\delta\in H(\ttX)$ and $\gamma<\delta\le\ttOmega$, then 
    \begin{equation*}
        H[\ttX]\sststile{\rho}{\alpha} \Gamma,\ \forall x\in \ttL(u)_\delta  B(x)
        \implies
        H[\ttX]\sststile{\rho}{\alpha} \Gamma,\ \forall x\in \ttL(u)_\gamma B(x).
    \end{equation*}

