[Definition def:indicators of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Let $G$ be a $ \{0,1\}$-valued function defined on the set of all finite plane trees. 
For every  sequence $\mathbf{x}=(x_1, \ldots, x_n) \in \mathbb{Z}_{\geq -1} ^{n}$ and for every $M \in \mathbb{N} \cup \{\infty\}$ we define $I_1^{(M)}$ as follows:
\begin{enumerate}
\item[--] if $\zeta(\mathbf{x})=\infty$ or $\zeta(\mathbf{x})>M$, set $I_1^{(M)}(\mathbf{x}) = 0$;
\item[--] if  $\zeta(\mathbf{x}) \leq M$ set $I_1^{(M)}(\mathbf{x})=G(T(\mathbf{x}_{1}, \ldots,\mathbf{x}_{\zeta(\mathbf{x})}))$.
\end{enumerate}
Then, for every $1 \leq i \leq  n$, define $I_i^{(M)}(\mathbf{x}) =I^{(M)}_{1}(x_i, x_{i+1}, \ldots, x_n, x_1, \ldots, x_{i-1})$.

[Proposition 8 of arXiv:2607.08129, '2607.08129'] For every $f\in C[0,1]$,
\begin{equation}
 I_\theta(f)
 =\sup_{\mu\in\cM_{\mathrm{at}}[0,1]}
 \bigg\{
 \int_{[0,1]}f(t)\mu(\dd t)-\mathfrak L_\theta(\mu)
 \bigg\}.
\end{equation}
Equivalently,
\begin{align}
 I_\theta(f)
 =\sup_{m,\boldsymbol t,\lambda}
 \bigg\{
 &\sum_{j=1}^m\lambda_jf(t_j)
 \nonumber\\
 &-\int_0^1\log\bigg[
 q^{m(x)}+
 \sum_{k=1}^{m(x)}\pi_k
 \exp\bigg\{\sum_{j=1}^m
 \lambda_j\1_{\{xk\le t_j\}}\bigg\}
 \bigg]\dd x
 \bigg\},

\end{align}
where the supremum is over $m\ge1$, $0\le t_1<\cdots<t_m\le1$, and $\lambda\in\R^m$.

For a fixed atomic measure $\mu$, the pointwise optimizer in the finite-state Gibbs variational formula used in \eqref{eq:finite-gibbs} is the reduced kernel
\begin{equation}
 a_k^\mu(x)
 =\frac{\pi_k e^{\mu([xk,1])}}{Z_\mu(x)},
 \quad 1\le k\le m(x),
 \qquad
 a_0^\mu(x)=\frac{q^{m(x)}}{Z_\mu(x)}.
\end{equation}

