[Lemma l:sharp_poincare of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] For all $\sigma\in [0,1/2)$ and balls $B\subseteq {\mathbb R}^d$, there exists a constant $C>0$ independent of the center of $B$ such that, for all $f\in L^2(B)$ and $\nabla f \in H^{-1-\sigma}(B)$, 
\begin{align}

\Big\|f-\fint_{B} f\Big\|_{H^{-\sigma}(B)}
\leq C \|\nabla f\|_{H^{-1-\sigma}(B)}.
\end{align}
In particular, $
\big\|f-\fint_{B} f\big\|_{H^{-1}(B)}
\leq C \|\nabla f\|_{H^{-1}(B)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 15 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W$ satisfy Assumption~\ref{ass:noise} and let $u \in L^q([0,1]; C^\alpha(\T^d))$ with $(q,\alpha)$ satisfying the condition~\eqref{eq:condition_SWP_time_integrable} from Remark~\ref{rem:regbynoise_time_integrability} (so that $X^\kappa$ is well-defined for any $\kappa>0$); let $\eps\in (0,1)$.
    We say that $u$ has the \emph{$(1-\eps)$-non-selection property} if there exists $ A \subset \T^d$ with $| A| \geq 1 - \eps $ and a constant $c_\eps >0$ such that:
\begin{itemize}
    \item  there exists a sequence $\{ \kappa_q \}_{q}$ such that
    \begin{equation*}
        \P\left(  \omega\in \Omega: \liminf_{q\to\infty} \dist ( X_1^{\kappa_{2q}}( x, \omega), X_1^{\kappa_{2q+1}}( x, \omega))\geq c_\eps> 0\,, \text{ for a.e. } x \in A\right) =1\,,
    \end{equation*}
    \item for any $x \in  A$, there exist a subsequence $\{\kappa_{q'}\}_{q'}$ and points $y, y' \in \T^d$ such that
    $$ X_1^{\kappa_{2q'}} ( x,  \omega) \rightarrow y \neq y' \leftarrow X_1^{\kappa_{2q'+1}} ( x, \omega).\quad \text{for $\P$-a.e. } \omega\in\Omega.$$
\end{itemize}

[Corollary 12 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Assume that $SOV(U) = 1$. Assume that $I$ has a connected component $\mc{G}$, with vertex set $V_\mc{G}$, such that there exist $\eps, \eta > 0$ such that, with high probability,

    \begin{equation} 
        \forall N \subseteq V_\mc{G} \text{ with } |N| \leq \eta n, \qquad |I[V_\mc{G} \setminus N]| \geq (1 + \eps )|V_\mc{G}|.
    \end{equation}
    Then, $\ds \operatorname*{pliminf}_{n \to +\infty} ov(\hat{\pi}, \pi^*) > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 (Finite exit from a uniformly supercritical band) of arXiv:2608.20638, 'Provable Edge-of-Stability for Adam on a One-Dimensional Quadratic'] Suppose that $x_Th_T>0$ and $w_T\ge2+\delta$ for some $\delta\in(0,1]$, and define
\begin{equation}
    \tau:=\min\{n\in\Npos:w_{T+n}<2+\delta\}.

\end{equation}
Then
\begin{equation}
\begin{aligned}
    \tau\le 1+\delta^{-1}\log\!\left(
        1+
        \frac{\delta(c\eta)^2}
        {(1-\beta_2)x_T^2}\right).
\end{aligned}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main Birk of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an  upper probability.  Then $V$ is ergodic with respect to $T$ if and only if there exists a unique $Q\in \mathcal{M}^e(T)\cap \operatorname{core}(V)$ such that for any  $f\in L^1(\Omega,\mathcal{F},Q)$,
	\begin{equation}
		\lim _{n \rightarrow \infty} \frac{1}{n} \sum_{i=0}^{n-1} f(T^{i} \omega)=\int f dQ \text{ for }V\text{-a.s. }\omega\in\Omega.
	\end{equation}

[Corollary cor:Push-TASEP-scalar of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] For $t > 0$ and $a < y_{n+1} - 1$, the one-point Fredholm
determinant
$F_{t, a, n} \vcentcolon= \det(I - K_{t, a, n})$ satisfies
\begin{equation}
F_{t,a,n}F_{t,a+1,n+1}
- F_{t,a+1,n}F_{t,a,n+1}
+ F_{t,a,n+1}\partial_t F_{t,a+1,n}
- F_{t,a+1,n}\partial_t F_{t,a,n+1} = 0.
\end{equation}

[Definition def:sol_gen_SDE of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$. A (general) solution to SDE$(b,\sigma;s)$ is a 
triple $( (\mathcal{F}_t)_{t},W, X)$, where: 
\begin{itemize}
\item[(i)] $(\mathcal{F}_t)_{t\in [s,T)}$ is a filtration on a probability space $(\Omega , \mathcal{F}, \mathbb{P})$, satisfying the usual assumptions of completeness and continuity from the right;
\item[(ii)] $W=(W_t)_{t\in [s,T)}$ is a $q$-dimensional (uncorrelated) Brownian motion (starting at $s$) with respect to $(\mathcal{F}_t)_{t\in [s,T)}$;
\item[(iii)] $X=(X_t)_{t\in [s,T)}$ is an $\mathbb{R}^d$-valued process, adapted to  $(\mathcal{F}_t)_{t\in [s,T)}$, such that: 
\begin{itemize}

\item the processes $(b(t,X_t))_{t\in [s,T)}$ and  $(\sigma(t,X_t))_{t\in [s,T)}$ are progressively measurable and such that 
\begin{equation}
\int_s^t |b(r,X_r)| dr + \int_s^t \big|\sigma\sigma^\top(r,X_r)\big| dr  <\infty, \qquad \mathbb{P}\text{-almost surely.}
\end{equation}

\item 
the following representation holds $\mathbb{P}$-almost surely:
\begin{equation}
X_t = X_s + \int_s^t b(r,X_r) dr + \int_s^t \sigma(r,X_r) dW_r ,\qquad t\in [s,T).
\end{equation}
\end{itemize} 
\end{itemize}

