[Theorem 4 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] Consider large $n,m\in\mN$ such that $\lim_{n\rightarrow\infty}\frac{m}{n}\rightarrow\alpha> 1$ and let $A_{ij}\sim \cN(0,1)$ be the independent elements of $A\in\mR^{m\times n}$. For a real scalar $c_3\geq 0$ set
  \begin{eqnarray}

 \hat{\gamma}_{1,l} & = &  \frac{-c_3 + \sqrt{c_3^2+4\alpha}}{4}
 \nonumber \\
 \phi_{1,l}(\gamma_{1}) & = &  -\gamma_{1}c_3 - \frac{\alpha}{2}\log \lp 1 + \frac{c_3}{2 \gamma_{1}}   \rp
 \nonumber \\
 \hat{\gamma}_{2} & = &  \frac{c_3 + \sqrt{c_3^2+4}}{4}
 \nonumber \\
 \phi_{2}(\gamma_2) & = &  \gamma_{2}c_3 - \frac{1}{2}\log \lp 1 - \frac{c_3}{2 \gamma_{2}}   \rp.
 \end{eqnarray}
 Let $\xi^-_{sph}$ be as in (\ref{eq:mininteq1ab0}) and for a real scalar $u\leq \mE \xi^-_{sph}$ set
  \begin{eqnarray}

 \nonumber \\
 \phi_l(u) & = & -\frac{c_3^2}{2} + \phi_{1,l}(\hat{\gamma}_1) + \phi_{2}(\hat{\gamma}_2) +c_3 u .
 \end{eqnarray}
One then has the following LDP with the indicator rate function $\zeta_l(u)$
\begin{eqnarray}

\lim_{n\rightarrow \infty} \frac{\log\lp \mP\lp \xi^-_{sph} \leq u  \rp \rp}{n} \leq \min_{c_3\geq 0}\phi_l(u)  \triangleq -\zeta_l(u).
\end{eqnarray}

