body:
[Theorem 11 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Assume that Assumptions \ref{LG-Condition} and \ref{ass:affine-coeff} hold.
    Let $\mu \in \ccM([0,T], \C^d)$
    and let $\psi \in L^2([0,T], (\C^d)^\ast)$
    solve the Riccati-type integral equation
    \begin{equation}
        \psi(t) = \mu([t,T]) +
        \int_t^T \psi(s) B(s, \Ind_{[t,s]}) + \frac{1}{2} A(s, \Ind_{[t,s]}, \psi(s))\, ds, \quad t\in[0,T]
    \end{equation}
    and define
    \begin{equation}
        \phi(t) = \int_t^T \psi(s) b^0(s) + \frac{1}{2}\psi(s)a^0(s)\psi(s)^\top \, ds, \quad t\in[0,T].
    \end{equation}
    Then the $\C$-valued process $Y$,

    defined by
    \begin{align}
        \begin{split}
            Y(t) & = \phi(t) + \psi(0)X(0) +\int_0^t \psi(s) dX(s)                                                                                                                       \\
                 & \quad -\int_0^t\sum_{i=1}^{d}\Bigl( \psi(s) ( b^i(s) \cdot X^i_{[0,s]}) + \frac{1}{2} \psi(s) ( a^i(s) \cdot X^i_{[0,s]}) \psi(s)^\top \Bigr)ds, \quad 0 \leq t \leq T,
        \end{split}
    \end{align}
    satisfies
    \begin{align}
        \begin{split}
            Y(t) & = \phi(t) + \psi(t)X(t)+ \mu \cdot X_{[0,t)}                                                                                                                            \\
                 & \quad + \int_t^T \sum_{i=1}^{d} \Bigl( \psi(s) ( b^i(s) \cdot X^i_{[0,t)}) + \frac{1}{2}\psi(s) (a^i(s) \cdot X^i_{[0,t)}) \psi(s)^\top \Bigr) ds, \quad 0 \leq t \leq T.
        \end{split}
    \end{align}
    Moreover, the process $\exp(Y)$ is a local martingale and if it is a true martingale, then 
    \begin{equation}
        E\left[e^{\mu \cdot X_{[0,T]}} |\, \ccF_t\right] = \exp\left(Y(t)\right), \quad 0 \leq t \leq T.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor final-convergence-metrics of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] There exist true metrics $d^{{\mathrm {geo}}}$ and $d^{{\mathrm {res}}}$ on all clusters $\mathcal{X}^{(m)}$ such that
\begin{equation}
    \begin{split}
        (\mathcal{X}^{(m)}_n,d^{{\mathrm {geo}}}_n,\pi_n)&\rightarrow(\mathcal{X}^{(m)},d^{{\mathrm {geo}}},\pi),\\
        (\mathcal{X}^{(m)}_n,d^{{\mathrm {res}}}_n,\pi_n)&\rightarrow(\mathcal{X}^{(m)},d^{{\mathrm {res}}},\pi)\\
    \end{split}
\end{equation}
weakly with respect to $\Delta_{\GHf}$ as $n\rightarrow\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\gamma \in \mathcal{P}_\mathcal{W}$, $\psi$ be its corresponding generator, $\varphi$ be its pseudo-inverse, $\vartheta \in \mathcal{P}_\mathcal{A}$, $A$ be the corresponding Pickands dependence function, $C_{\psi,A} \in \mathcal{C}_{am}$, $K_{\psi,A}$ be the Markov kernel of $C_{\psi,A}$ according to eq. \eqref{eq:markov-kernel} and $L$, $R$ be defined according to eq. \eqref{eq:definition_L_R} with $L<R$. 
Moreover, let $t \in (0,1)$ if $\psi$ is strict, $t \in [0,1)$ if $\psi$ is non-strict and let $\fg^t$ be defined according to eq. \eqref{eq:fct_g_t}. Then for all but at most countably many $x \in \left(t, \psi\left(\frac{L\varphi(t)}{1-L}\right)\right)$ the following equivalence holds:
\begin{equation*}
    K_{\psi,A}(x,\{\fg^t(x)\})>0 \text{ if, and only if } \frac{1}{\varphi(t)} \text{ is a point mass of } \gamma.
\end{equation*}

[Cor dexp of arXiv:2412.03415, 'Critical first passage percolation on random graphs'] Under the assumptions of Theorem (thm:main of the paper), consider the following special cases for the positive part of the edge distribution:
\begin{enumeratea}
\item Suppose  $(t_e|t_e>0)$ has cumulative distribution function $H_\gamma(t)=e \cdot \exp(-\exp(1/t^\gamma))$ for $0< t \leqslant 1$. Then as $n\to\infty$, 
\begin{enumeratei}
\item  For $\gamma < 1$, $ T_n(1,2) \stackrel{d}{\longrightarrow} \Xi $ where $\Xi = \Xi(\mathbf{p}, H_\gamma) < \infty$ a.s., 
\item  For $\gamma \geqslant 1$, $T_n(1,2)\stackrel{d}{\longrightarrow} \infty$.
\end{enumeratei}
\item Suppose $t_e\overset{d}{=}p_c \delta_0+(1-p_c)\delta_1$, namely the passage time distribution has mass at either zero or one. Then $T_n(1,2)\stackrel{d}{\longrightarrow} \infty$.

\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:isoflow of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small $n$--independent constants $\tau,\omega_*,\epsilon>0$, and for $i=1,2$ fix spectral parameters $\Lambda_{i,0}$ as in (equation eq:defincond of the paper). Fix an exponent $b\in [0,1]$.
	For $t\le T^*$ let $\Lambda_{i,t}$ be the solution of (equation eq:charflowmat of the paper) with initial condition $\Lambda_{i,0}$. Let $G_{i,t}:=(W_t-\Lambda_{i,t})^{-1}$, and let $M_{12,t}^A$, $M_{121,t}^{A_1,A_2}$ be defined in (equation eq:defm12 of the paper) and (equation eq:defm121 of the paper), respectively. Let $\ell_t, \gamma_t$ be from (equation eq:defcontrolparam of the paper), and assume that for some small $0<\xi\le \epsilon/10$, with very high probability, it holds
	\begin{equation}

		\begin{split}
			\big|\big\langle {\bm x}, \big(G_0^{z_{1,0}}(\mathrm{i}\eta_1)A_1G_0^{z_{2,0}}(\mathrm{i}\eta_2)-M_{12}^{A_1}(\eta_1,z_{1,0},\eta_2,z_{2,0})\big) {\bm y}\big\rangle\big|&\le 
			\frac{n^\xi (\rho^*)^{\frac{1-b}{2}} }{\sqrt{n} \eta_*^{\frac{3-b}{2}}\gamma_0^{\frac{b}{2}} }, \\
			\big|\big\langle {\bm x}, \big(G_0^{z_{1,0}}(\mathrm{i}\eta_1)A_1G_0^{z_{2,0}}(\mathrm{i}\eta_2)A_2G_0^{z_{1,0}}(\mathrm{i}\eta_1)-M_{121}^{A_1,A_2}(\eta_1,z_{1,0},\eta_2,z_{2,0})\big) {\bm y}\big\rangle\big|&\le \frac{n^\xi}{\eta_*^{2-b}\gamma_0^b},
		\end{split}
	\end{equation}
	where $\eta_*:=|\eta_1|\wedge|\eta_2|$,  uniformly in $\lVert A_i\rVert\le 1$, $\lVert {\bm x}\rVert+\lVert {\bm y}\rVert\lesssim 1$, and for any $|\eta_i|\in [|\eta_{i,0}|,n^{100}]$, where $\ell_0,\gamma_0$ are evaluated at $(\eta_1,z_{1,0},\eta_2,z_{2,0})$. Then,
	\begin{equation}

		\begin{split}
			\big|\big\langle {\bm x}, \big(G_{1,t}A_1G_{2,t}-M_{12,t}^{A_1}\big) {\bm y}\big\rangle\big|&\le
			\frac{n^{2\xi} (\rho^*_t)^{\frac{1-b}{2}} }{\sqrt{n} \eta_{*,t}^{\frac{3-b}{2}}\gamma_t^{\frac{b}{2}} },\\
			\big|\big\langle {\bm x}, \big(G_{1,t}A_1G_{2,t}A_2G_{1,t}-M_{121,t}^{A_1,A_2}\big) {\bm y}\big\rangle\big|&\le \frac{n^{2\xi}}{(\eta_{*,t})^{2-b}\gamma_t^b},
		\end{split}
	\end{equation}
	where $\eta_{*,t}:=|\eta_{1,t}|\wedge|\eta_{2,t}|$, with very high probability uniformly in $\lVert A_i\rVert\le 1$, $\lVert {\bm x}\rVert+\lVert {\bm y}\rVert\lesssim 1$, and all $t\le T^*$ such that $n\ell_t\ge n^\epsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 18 (Doob's optional stopping version III) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Let $\{f_j\}_{j \geq 0}$ be a given non-negative,  real-valued supermartingale on $\mathcal{S}$ we also set $f_{T+1} \equiv \liminf_{n \rightarrow T+1} f_n$. Consider two stopping times satisfying
$\rho\le \tau$ a.e. Under the assumption that both,  $(L)-a.e$ and property $(P)$ (see Definition \ref{def:Positivity}), then:
\begin{enumerate}
\item 
\begin{equation} 
\overline{\sigma}_{\rho}(f_{\tau}) \leq f_{\rho}~~\mbox{a.e. on}~~\mathcal{S},
\end{equation}
\item 
\begin{equation} 
\overline{\sigma}_{\rho}({\bf 1}_{\{\tau < T+1\}}~f_{\tau}) \leq {\bf 1}_{\{\rho < T+1\}} f_{\rho}~\mbox{~a.e. on}~~\mathcal{S}.
\end{equation}
\end{enumerate}

[Lemma Special case of Lemma~2.3, the least-action principle of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{lem:lap}
  Let $u$ be the true odometer stabilizing finite $V\subseteq\mathbb{Z}$ with given instructions and initial configuration
  with no sleeping particles.
  Let $u'$ be an odometer on $\mathbb{Z}$ that is stable on $V$ for the same instructions and 
  initial configuration.
  Then
  \begin{align*}
    u(v)\leq u'(v)
  \end{align*}
  for all $v\in V$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 34 of arXiv:2601.16377, '2601.16377'] Suppose that Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic} and \ref{Assumptions_offcrit}
 hold. If $[\mathfrak{a},\mathfrak{b}]$ is included in a void of the equilibrium measure, then for any $\eps>0$ there exists a real $C > 0$ independent of $\N$ such that the probability to have at least one particle $\ell_i$ inside $[\N(\mathfrak{a}+\eps),
 \N(\mathfrak{b}-\eps)]$ is at most $C^{-1}e^{-C\N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:noninvariant of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] Let $(\Omega,\mathcal{F},P)$ be a probability space and $T:\Omega\to \Omega$ be a measurable invertible transformation. If the limit (equation eq:20.19 of the paper) exits, then the following statements are equivalent:
	\begin{enumerate}
		\item [(i)] $\#(P(\mathcal{I}))<\infty$;
		\medskip
		\item [(ii)] $(\Omega,\mathcal{F},P,T)$ satisfies the finite irreducible invariant set partition assumption; 
		\medskip
		\item [(iii)]there exist $Q_1,\ldots,Q_n\in\mathcal{M}^e(T)$ and  a finite measurable partition $\alpha=\{A_1,\ldots,A_n\}$ with $P(A_i)>0$, $i=1,2,\ldots,n$, such that for any $f\in B(\Omega,\mathcal{F})$, 
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}f\circ T^i=\sum_{j=1}^{n}\left(\int fdQ_j\right)\cdot1_{A_j},  ~~P\text{-a.s.}
		\end{equation}
		\item [(iv)]there exist  $Q_1,\ldots,Q_n\in\mathcal{ M}^e(T)$  and  a finite  measurable partition $\alpha=\{A_1,\ldots,A_n\}
		$ with $P(A_i)>0$, $i=1,2,\ldots,n$ such that 
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}P(B\cap T^{-i}C)=\sum_{j=1}^nQ_j(C)P(A_j\cap B)\text{ for any }B,C\in\mathcal{F}.
		\end{equation}
	\end{enumerate}

