[Corollary 17 of arXiv:2607.04193, 'Onsager--Machlup Functionals for Generalized Newtonian Equations of Motion with Time-Varyi'] Consider the stochastic Hamiltonian system driven by fractional Brownian motion:
    \begin{equation*}
        \begin{cases}
            dq_t = \nabla_p H(q_t,p_t)dt, \\[4pt]
            dp_t = -\nabla_q H(q_t,p_t)dt + \sigma_t dB^H_t.
        \end{cases}
    \end{equation*}
    If the Hamiltonian function $H(q,p)$ satisfies
    \begin{equation*}
        \nabla_p \cdot \bigl(\nabla_q H(q,p)\bigr) = C,
    \end{equation*}
    for some constant $C$, then the stochastic Hamiltonian system possesses the path-preservation property. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem eqn:balanced-bound of arXiv:2604.09509, 'An Improved Bipartition Cover Bound for the Multispecies Coalescent Model'] If we have a species tree with $k$ species and a set $\cG$ of at least

\begin{equation}
    M_b(k, T_{\mathrm{min}}):=  \inf\left\{n \in \mathbb{N} : \sum_{\ell=2}^{k-2}\left[1-w_\ell\right]^n \leqslant 1-q\right\}

\end{equation}

\noindent gene trees sampled independently under the MSC model, where

\begin{equation}
    w_\ell := \mathbb{P}(W_{\ell} = 1)

\end{equation}

\noindent and where the distributions of $W_\ell := Z_{X_{\cB_\ell}}$ are defined recursively by $W_1 \equiv 1$ and

\begin{equation}
\mathbb{P}(W_\ell=j)
=
\sum_{a\geqslant 1}\sum_{b\geqslant 1}
\mathbb{P}\left(W_{\lfloor\ell/2\rfloor}=a\right)
\mathbb{P}\left(W_{\lceil\ell/2\rceil}=b\right)
g_{a+b,j}(T_{\mathrm{min}}),
\qquad \ell\geqslant 2.

\end{equation}

\noindent Then $\cG$ forms a bipartition cover with probability at least $q$. Here $T_{\mathrm{min}}$ is the minimum branch length (in coalescent units) in the species tree.

[Lemma le:regularity-small-ball of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ a \in (0,\infty) $, $ p \in (0,1] $, let $ \mathcal V \subseteq {\mathbb R}^d $,
and let $ ( X, U ) $ be an innovation which satisfies for every $ \theta \in \mathcal V $, $ i \in \{ 1, \dots, d \} $ that
\bas{
{\mathbb P}\bigl(|X^{(i)}(\theta,U)|\ge a\bigr)\ge p.
}
Then $(X,U)$ is $(c,q)$-regular on $\mathcal V$ with
\bas{
c=p(1-e^{-1})a^2
\qquad
  \text{and}
\qquad
q=p(1-e^{-1}).
}

