[Definition 2 of arXiv:2607.22416, 'A multi-player optimal stopping game based on a spider Brownian bridge'] We say that $(\tau^{*},\sigma^{*}) \in \sT \times \sT$ is a Nash equilibrium (for the game with expected payoffs $(\GG_i, \LL_i)_{i = 1,2}$) if 
    \begin{equation*}
        \begin{split}
            R_{1}(\tau^{*},\sigma^{*})=\sup_{\tau \in \sT} R_{1}(\tau,\sigma^{*}),  \\
            R_{2}(\tau^{*},\sigma^{*})=\sup_{\sigma \in \sT} R_{2}(\tau^{*},\sigma).
        \end{split}
    \end{equation*}

[Lemma 11 (Cai--Lu quadratic lower bound) of arXiv:2609.01436, '2609.01436'] Assume \cref{ass:CL}.  Let
$\varphi\in C_b^{1,1}([0,\infty))$ be nonnegative and convex.  Then
\begin{equation}
 \mathcal J[\varphi](y,z)
 \geq-\frac12(\varphi(y)\sqrt z+\varphi(z)\sqrt y),
 \qquad y,z\geq0.
\end{equation}
Consequently, if $F\in\mathcal B_1^+([0,\infty))$ has mass $N$ and energy
$E$, then
\begin{equation}
 \iint\mathcal J[\varphi]\,dF^{\otimes2}
 \geq-\sqrt{NE}\int\varphi\,dF.
\end{equation}

[Lemma 9 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $X$ be an $S$-valued affine process satisfying the support Condition~\ref{cond:full support_inhom}. Then the following holds:
    \begin{enumerate}[(i)]
        \item the function $\mu \mapsto \phi(t,T,\mu)$ maps $\cU(T)$ to $\C_{\leq 0}$ and $\mu \mapsto \Psi(t,T,\mu)$ maps $\cU(T)$ to $\cU(T)$,
        \item the functions $\phi$ and $\Psi$ satisfy the semi-flow property, i.e.,
              \begin{align}
                  \phi(s,T,\mu) & = \phi(t,T,\mu) + \phi(s,t, \Psi(t,T,\mu)), &  & \phi(T,T, \mu) = 0,  \\
                  \Psi(s,T,\mu) & = \Psi(s,t,\Psi(t,T,\mu)),                  &  & \Psi(T,T,\mu) = \mu,
              \end{align}
              for all $0 \leq s \leq t \leq T$.
    \end{enumerate}

