[Proposition 13 of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For fixed $\lambda$ in the support of the $\lambda$-marginal,
\begin{equation}
        \Prob_q(\mu\mid\lambda)
        =\frac{Q_\mu(qX)Q_{\lambda/\mu}(X)}{Q_\lambda[X+qX]},
        \qquad \mu\subseteq\lambda.
\end{equation}
Consequently,
\begin{equation}
        \EE[u^B\mid\lambda]
        =\frac{Q_\lambda[X+uqX]}{Q_\lambda[X+qX]}.
\end{equation}
In particular,
\begin{equation}
        \EE[B\mid\lambda]
        =q\frac{\partial}{\partial q}\log Q_\lambda[X+qX],
\end{equation}
and
\begin{equation}
        \Var(B\mid\lambda)
        =\left(q\frac{\partial}{\partial q}\right)^2
        \log Q_\lambda[X+qX].
\end{equation}

[Lemma lem:PTASEP-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,r,n}$ and $\phi_{t,r,n}$ defined in
\S(sec:PTASEP-kernel-reform of the paper) satisfy the linear
problem (equation eq:Linear-Psi-3 of the paper) and the adjoint
linear problem (equation eq:Linear-Phi-Prob of the paper) on
$\mathcal{V}$ with edge weights
$(c_k, \lambda_k)$.  Explicitly, for each fixed
$r \in \mathbb{Z}$:
\begin{align}
\psi_{t+1,r,n+1}
&= (q{+}p\theta)(1{-}\theta)^{-1}
   \psi_{t,r+1,n}
   - \theta(q{+}p\theta)(1{-}\theta)^{-1}
   \psi_{t,r,n},
 \\
\psi_{t+1,r+1,n}
&= q\psi_{t,r+1,n}
   + p\theta\psi_{t,r,n},

\end{align}
and
\begin{align}
\phi_{t,r+1,n}
&= (q{+}p\theta)(1{-}\theta)^{-1}
   \phi_{t+1,r,n+1}
   - \theta(q{+}p\theta)(1{-}\theta)^{-1}
   \phi_{t+1,r+1,n+1},
 \\
\phi_{t,r+1,n}
&= q\phi_{t+1,r+1,n}
   + p\theta\phi_{t+1,r+2,n}.

\end{align}

