[Lemma 24 of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] If $\beta$ is populated and $|\beta|=2$, then
\begin{enumerate}
	\item either $\beta$ is purely polynomial, 
i.e.~$\beta=\delta_\n$ for some $|\n|=2$,
	\item or $\beta=\delta_k+\kk\delta_{\0}$ for some $k\geq\kk$.		
\end{enumerate}

[Corollary 28 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $X$ have density $f$ with respect to $\pi_{T}.$ If $H(T_{a}(X) |\pi_{aT}) < \infty$ for some $a \in (0,1],$ then
    \begin{displaymath}
        a\E X = \E T_{a}(X) < \infty
    \end{displaymath}
    and
    \begin{displaymath}
         \E T_{a}(X) \log T_{a}(X) < \infty .
    \end{displaymath}

