body:
[Lemma 18 of arXiv:2605.31300, 'Cone-Additive Functions for Random Walks on Free Products of Graphs'] Assume that $f:\Pi\to\mathbb{R}$ is a cone-additive function such that there exist  constants $C\in(0,\infty)$ and $R\in(0,\mathcal{R})$ with 
\begin{equation*} 
 \bigl|f(\pi)\bigr| \leq C\cdot R^{\mathrm{length}(\pi)} \quad \textrm{ for all } \pi\in\Pi.
\end{equation*}
Then:
$$
\lim_{n\to\infty} \frac{f\bigl(\pi^\ast_n\bigr)}{n}=0 \quad \textrm{almost surely.}
$$

[Proposition prop:trace-comparison of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] There exist constants $c,C,c_*>0$ such that, whenever
\begin{equation}
 L\ge1,
 \qquad
 L^3\le c_*\log N,
\end{equation}
one has
\begin{equation}
 \sup_{\bm\xi\in\mathcal G_N}
 \left\|
 \mathbf 1_{(-L,\infty)}
 (\widetilde K_N-K_{\operatorname{Ai}})
 \mathbf 1_{(-L,\infty)}
 \right\|_1
 \le CN^{-c}e^{CL^{3/2}}.
\end{equation}
Moreover,
\begin{equation}
 \left\|
 \mathbf 1_{(-L,\infty)}K_{\operatorname{Ai}}\mathbf 1_{(-L,\infty)}
 \right\|_1
 \le C(1+L^{3/2}),
\end{equation}
and, after decreasing $c_*$ if necessary,
\begin{equation}
 \left\|
 \mathbf 1_{(-L,\infty)}\widetilde K_N\mathbf 1_{(-L,\infty)}
 \right\|_1
 \le C(1+L^{3/2}).
\end{equation}

