[Proposition prop.H1TwoScale of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] There exists a finite positive constant $C(c_{-},c_{+},\mathbf{r},\rho)$ such that for every $\lambda\in(0,\tfrac{1}{2})$, the following estimates about the expectation and variance of the carr\'e du champ of $\widetilde{G}_\lambda$ hold:
		\begin{multline}
			\left|\mathbb{E}_\rho\left[\sum_{b\in(\mathbb{Z}^2)^*}\left(c_b(\pi_b\widetilde{G}_\lambda)^2\right)\left(\eta\right)\right]-2\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}\right|\\
			\leqslant C\sqrt{\log (\lambda^{-1})}(3^{-\alpha m}\sqrt{\log(\lambda^{-1})}+3^m),
		\end{multline}
		\begin{equation}
			\mathbb{V}\!\mathrm{ar}_\rho\left[\sum_{b\in(\mathbb{Z}^2)^*}\left(c_b(\pi_b\widetilde{G}_\lambda)^2\right)(\eta)\right]\leqslant C 3^{18m}\log(\lambda^{-1}).
		\end{equation}

