[Prop 6 (Vitali's convergence theorem) of arXiv:2607.28078, '2607.28078'] \cite[Proposition 1.1]{ISI}
Let $(E,\|\cdot\|)$ be a separable Banach space and let $p\in[1,\infty)$. Let $\{X_n\}_{n\geq1}$ and $X$ be $E$-valued random variables in $L^p$ such that $X_n$ converges to $X$ in probability or almost surely. Then the following statements are equivalent.
\begin{enumerate}
\item[$\rm(1)$] $\{X_n\}$ converges to $X$ in $L^p$.
\item[$\rm(2)$] $\{\|X_n\|^p\}$ is uniformly integrable.
\item[$\rm(3)$] $\lim\limits_{n \to \infty} \mathbb{E}[\|X_n\|^p] = \mathbb{E}[\|X\|^p]$.
\end{enumerate}
Furthermore, if either of the following two conditions holds, then $\rm (1)$--$\rm (3)$ are satisfied.
\begin{enumerate}
\item[$\rm(4)$] $\sup\limits_{n} \mathbb{E}[\|X_n\|^q] < \infty$ for some $q \in (p, \infty)$.
\item[$\rm(5)$] There exists a random variable $Y \in L^p$ such that $\|X_n\| \le Y$ for all $n$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3}, \ref{PEeqAssum-2.4} and \eqref{PETNs-3.01} hold. Then $\{S_\epsilon(t,\tau):t\geq\tau\}$ is a continuous two-parameter evolution process on $\mathcal P_{4,z}(H)$. More precisely, for every $\tau\in\mathbb R$: 

	$(i)$  $S_{\epsilon}(\tau,\tau)=I_{\mathcal{P}_{4,z}({H})}$;

	$(ii)$ $S_{\epsilon}(t,\tau)=S_{\epsilon}(t,s)S_{\epsilon}(s,\tau)$ for any $t\geq s \geq \tau$;

	$(iii)$ $S_{\epsilon}(t,\tau): \mathcal{P}_{4,z}({H})\rightarrow \mathcal{P}_{4,z}({H})$ is continuous for any $t\geq \tau$.

[Proposition prop:higher of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For  any $0<\kappa<\frac{d-2}{2}$, we have \begin{align*}
       \lim_{R\to \infty} \frac{1}{ R^{2d-2}}\sum_{n=2}^{\infty}  \mathbb Var\left[I_1^{(n)}(\1_{B_R})\right] =0.
   \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:conv_int_onefold_moll of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] Let $h\in H_0^1\cap H^2$. Then it holds
	\begin{equation*}
		\int_{(0,1)} \bar{h}_x\gamma_{\varepsilon}(\beta_x) \, dx
		\xrightarrow{\varepsilon\downarrow 0}
		\int_{(0,1)} \bar{h}_x \delta_0(\beta_x) \, dx \;\,\text{in $(\mathcal{S})'$}.
	\end{equation*}

[Theorem 10 (Polynomial duality with dual process \eqref{generatory}) of arXiv:2606.00781, '2606.00781'] Let $\Lambda$ be a finite measure on $[0,1]$. Furthermore, let $r:=(r_n)_{n\in\nz_0}$ be a given sequence of real numbers. Then there exists a unique duality kernel $D=D_r:[0,1]\times\nz_0\to\rz$ (depending on the sequence $r$) satisfying the following three properties.
   \begin{enumerate}
      \item[(i)] The kernel $D$ is of polynomial form
         \begin{equation} 
            D(x,n)\ =\ \sum_{j=0}^n d_{n,j}x^j,\qquad x\in[0,1], n\in\nz_0,
         \end{equation}
         for some real coefficients $d_{n,j}$, $n\in\nz_0$, $j\in\{0,\ldots,n\}$.
      \item[(ii)] The diagonal coefficients are given by $d_{n,n}=r_n$ for all $n\in\nz_0$.
      \item[(iii)] $X$ is dual to $Y$ with respect to $D$, where $Y$ is the process with generator (\ref{generatory}).
   \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro_3 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $\hat{\tau}_c$ be the largest positive solution (if it exists) for $t$ in the equation 
\begin{eqnarray}

r(A)\ln\Big(1+\frac{t}{r(A)\|A\|}\Big)-\frac{t}{\|A\|}+2\kappa\min\Big\{\frac{t^2}{\|A\|_2^2},\frac{t}{\|A\|}\Big\}=0,
\end{eqnarray} 

where $\kappa$ is the constant in HWI given in Proposition~(prop_1 of the paper). If Conjecture~1 is true, then $\tau_c\leq \hat{\tau}_c$.

