\begin{align}
\abs{\mathcal{Q}^{n}(f)}
\leq 
s\mathcal{E}^{n}(f)+t\norm{f}^{2}_{L^{2}(V_n, \mu_{n})}, 
\quad f\in l(V_{n}).
\end{align}

