body:
[Theorem 1 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Let $Z$ be a one-dimensional symmetric $\alpha$-stable process with $\alpha \in (1,2)$. Consider two processes, $X$ and $\tilde{X}$, satisfying the SDEs
\begin{align*}
X_t = x_0 + \int_0^t b(X_s) \rd s + \int_0^t \sigma(X_{s-}) \rd Z_s \quad \text{and} \quad \tilde{X}_t = \tilde{x}_0 + \int_0^t \tilde{b}(s,\tilde{X}_s) \rd s +  \int_0^t \tilde{\sigma}(s,\tilde{X}_{s-}) \rd Z_s,
\end{align*}
for $t\in[0,T]$ with initial values $x_0, \tilde{x}_0\in\real$.

Suppose the coefficients satisfy the following conditions for some constants $K, k, K'>0$ and $\tilde{\eta} \in [1/\alpha,1]$:
\begin{itemize}
    \item[(i)] Drift coefficients:
    The coefficient $b$ of the baseline process $X$ is continuous and bounded: $|b(x)|\le K$ for all $x\in\real$.
    The coefficient $\tilde{b}$ of the perturbed process $\tilde{X}$ is spatially Lipschitz continuous with a time-dependent Lipschitz constant $f_{\tilde{b}}$ that is integrable over $[0,T]$:
    \begin{align*}
       \left|\tilde{b}(t,x)-\tilde{b}(t,y)\right|\le f_{\tilde{b}}(t) |x-y|, \quad \int_0^T f_{\tilde{b}}(s) \rd s<\infty. 
    \end{align*}
    \item[(ii)] Jump coefficients:
    The coefficient $\sigma$ of $X$ is strictly positive, bounded, and H\"older continuous:
    \begin{align*}
        k\le \sigma(x)\le K,\quad |\sigma^\alpha(x)-\sigma^\alpha(y)|\le K|x-y|^\eta.
    \end{align*}

    The coefficient $\tilde{\sigma}$ of the perturbed process $\tilde{X}$ satisfies the following conditions.
    It is bounded in magnitude by a function $g_{\tilde{\sigma}}$ that is square-integrable on $[0, T]$:
    \begin{align*}
        |\tilde{\sigma}(t,x)|\le g_{\tilde{\sigma}}(t), \quad
        \left(\int_0^T g_{\tilde{\sigma}}^2(s) \rd s\right)^{1/2}<\infty.
    \end{align*}
    Furthermore, it is spatially $\tilde{\eta}$-H\"older continuous with a time-dependent Lipschitz constant $f_{\tilde{\sigma}}$ that belongs to $L^\alpha[0,T]$: 

    \begin{align*}


       |\tilde{\sigma}(t,x)-\tilde{\sigma}(t,y)|\le f_{\tilde{\sigma}}(t)|x-y|^{\tilde{\eta}},\quad
       \left(\int_0^T f_{\tilde{\sigma}}^\alpha(s) \rd s\right)^{1/\alpha}<\infty
    \end{align*}
    \item[(iii)] The distances between the coefficients are small. 
    These distances are measured by the quantities $B$ and $S$, defined by integrals weighted by the transition probability density $p_t(x_0,\cdot)$ of the baseline process $X$ (as described in \eqref{SDE_density}):
    \begin{align*}
       B \coloneqq \int_0^T \int_\real \left|b(y)-\tilde{b}(s,y)\right| p_s\left(x_0,y\right) \rd s \rd y < 1, \quad S \coloneqq \left(\int_0^T \int_\real \left|\sigma(y)-\tilde{\sigma}(s,y)\right|^\alpha p_s\left(x_0,y\right) \rd s \rd y \right)^{1/\alpha} < 1. 
    \end{align*}
\end{itemize}
Then, there exists a positive constant $C = C\left(T, \alpha, K, k, \int_0^T f_{\tilde{b}}(s) \rd s, \int_0^T f_{\tilde{\sigma}}^\alpha(s) \rd s\right)$ such that
\begin{align*}
\sup_{t\in[0,T]}\mathbb{E}\left[|X_t-\tilde{X}_t|^{\alpha-1}\right] \le 
\begin{cases}
    C\left(|x_0-\tilde{x}_0|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\} & \text{if } \tilde{\eta} \in(1/\alpha,1], \\
	C\left(|x_0-\tilde{x}_0|^{\alpha-1}+ \left(\log\frac{1}{\max\{B, S\}}\right)^{-1}\right) & \text{if } \tilde{\eta} = 1/\alpha.
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 28 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] If \(X\sim Q\), then, for both \(\varepsilon\in\{-1,+1\}\),
\begin{equation}
  \delta^{-H}
  \{X(1+\varepsilon\delta t)-X(1)\}_{0\leq t\leq1}
  \Longrightarrow \{B_t\}_{0\leq t\leq1}
  \quad\text{in }C([0,1])

\end{equation}
as \(\delta\downarrow0\).

