    \begin{align*}
     |S(\alpha)|^{2^\kappa}
        \ll_n
        (L_1^n L_2^n)^{2^\kappa -1}
        (\prod_{i=1}^\kappa L_{s_i}^n)^{-1} \sum_{\substack{{\bf h}_1,...,{\bf h}_\kappa \\ {\bf h}_i\in [-\mathbf{L}_{s_i},\mathbf{L}_{s_i}]}}\sum_{\substack{{\bf x}_1,{\bf x}_2 \\ {\bf x}_i \in B^{\kappa}_{i}}}e(\Delta_{s_\kappa,{\bf h}_\kappa}\cdots \Delta_{s_1,{\bf h}_1}\Tilde{F}({\bf x}_1,{\bf x}_2;\alpha)),
    \end{align*}
    where $B^{\kappa}_{i}$ are boxes contained in $(\mathbf{M}_i,\mathbf{M}_i+\mathbf{L}_i]$.

