[Proposition 40 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definition \ref{Def.SchurProcess}, and let $\mathfrak{S}(\lambda)$ be as in (\ref{Eq.PointProcess}). Then $\mathfrak{S}(\lambda)$ is a Pfaffian point process on $\mathbb{R}^2$ with reference measure given by the counting measure on $\llbracket 1,m\rrbracket\times\mathbb{Z}$, and with correlation kernel 
$\kgeo:(\llbracket1,m\rrbracket\times\mathbb{Z})^2\rightarrow\operatorname{Mat}_2(\mathbb{C})$ given as follows. For each $u,v\in\llbracket1,m\rrbracket$ and $x,y \in \mathbb{Z}$,
\begin{equation*}
\begin{split}
\kgeo_{11}(u,x ; v,y) =& \frac{1}{(2\pi \im)^{2}}\oint_{C_{r_{1}}} dz \oint_{C_{r_{1}}} d w\frac{z-w}{(z^{2}-1)(w^{2}-1)(zw-1)} \cdot 
(1-c/z)(1-c/w) \cdot z^{-x }w^{-y }  \\
& \times (1-q/z)^{M_u+N} (1-q/w)^{M_v+N}  (1-q z)^{-N}(1-q w)^{-N}
\end{split}
\end{equation*}
where $r_{1} \in (1, q^{-1})$. In addition,
\begin{equation*}
\begin{split}
\kgeo_{12}(u,x ; v,y) = - \kgeo_{21}(v,y; u,x) =& \frac{1}{(2\pi \im)^{2}}\oint_{C_{r^z_{12}}} d  z \oint_{C_{r^w_{12}}}  dw  \frac{zw-1}{z(z-w)(z^{2}-1)} \cdot \frac{z-c}{w-c} \cdot  z^{-x } w^{y }  \\
&  \times     (1-q/z)^{M_u+N} (1-q/w)^{-M_v-N}(1-qz)^{-N}   (1-qw)^{N},
\end{split}
\end{equation*}
where $r^z_{12} \in (1, q^{-1})$, $r^w_{12} > \max(c, q)$, and $r^w_{12} < r^z_{12}$ when $u \geq v$, while $r^z_{12} < r^w_{12}$ when $u < v$. Finally,
\begin{equation*}
\begin{split}
\kgeo_{22}(u,x ;v,y) =& \frac{1}{(2\pi \im)^{2}}\oint_{C_{r_{2}}}  dz \oint_{C_{r_{2}}} dw \frac{z-w}{zw-1} \cdot \frac{1}{(z-c)(w-c)} \cdot z^{x }w^{y} \\
& 
\times  (1-q/z)^{-M_u-N}(1-q/w)^{-M_v-N} (1-qz)^N (1-qw)^N,
\end{split}
\end{equation*}
where $r_{2} > \max(c,q,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma tilt-lr of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $P_{1},P_{2}$ have densities $f_{1},f_{2}$ on $R^{2}$,
and suppose 
\begin{equation}
P_{1}\;\leq _{\mathrm{lr}}\;P_{2},  
\end{equation}
i.e.\ $\frac{f_{2}}{f_{1}}$ is coordinatewise non-decreasing. Define $\tilde{
P}_{i}$ as in Definition~(tilt of the paper). Then 
\begin{equation}
\tilde{P}_{1}\;\leq _{\mathrm{lr}}\;\tilde{P}_{2}.  
\end{equation}

