body:
[Defin 3 (Constrained model) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Define

\beq

\mathcal{M}_{1,\mathsf{c}}(\mathbb{R}) = \Big\{ \mu \in \mathcal{M}_1(\mathbb{R}) \, : \,

\Int{\mathbb{R}}{} |x| \, \mathrm{d}\mu(x) < +\infty \text{ and } \Int{\mathbb{R}}{} x \, \mathrm{d}\mu(x) = 0 \Big\}

\enq

equipped with the subspace topology.  In fact, this is a dense subset of $\mathcal{M}_1(\mathbb{R})$, though we shall not need this fact.
Given a Borel set $E \subset \mathcal{M}_{1,\mathsf{c}}(\mathbb{R})$ define the mass function by

\begin{align*}

&\Pi_{N,\mathsf{c}}: \mathfrak{B}(\mathcal{M}_{1,\mathsf{c}}(\mathbb{R})) \longrightarrow \intff{0}{1} \\

    &\Pi_{N,\mathsf{c}}[E] = \frac{1}{\mathcal{Z}_N^\mathsf{c} [V]} \Int{  \mathcal{A}_N }{} \delta\big(  \ov{\bs{\la}}_N^+\big)

\mc{I}(\bs{\la}^+_N ; \veps_N) \Delta(\boldsymbol{\lambda}_N^+) \pl{k=1}{N} \Big\{ \mathrm{e}^{- V(\lambda_k^+)} \Big\}

\, \mathbbm{1}_{E}(\op{L}_N^{(\boldsymbol{\lambda}_N^+)} )    \, \mathrm{d}\bs{\lambda}^+_N  \, .
\end{align*}

where $ \ov{\bs{\la}}_N^+ $ is as given in \eqref{definition contraction N vecteur}. Likewise we define the un-normalised mass function,

\begin{align*}

&\overline{\Pi}_{N,\mathsf{c}}: \mathfrak{B}(\mathcal{M}_{1,\mathsf{c}}(\mathbb{R})) \longrightarrow \intfo{0}{+\infty} \\

&\overline{\Pi}_{N,\mathsf{c}}[E] = \frac{ (N-1)! }{  |\ln(2\veps_N)|^{N-1} }\Int{  \mathcal{A}_N }{}

\delta\big(   \ov{\bs{\la}}_N^+ \big) \mc{I}(\bs{\la}^+_N ; \veps_N)

\Delta(\boldsymbol{\lambda}_N^+) \pl{k=1}{N} \Big\{ \mathrm{e}^{- V(\lambda_k^+)} \Big\}

\, \mathbbm{1}_{E}(\op{L}_N^{(\boldsymbol{\lambda}_N^+)} )    \, \mathrm{d}\bs{\lambda}^+_N \, .
\end{align*}

