    \begin{equation*}
		\mathcal{K}_c \coloneqq \bigg\{\mu\in{\mathcal P}({\mathcal C}): \mu(H_0^1)=1,\ \esssup_{t\in[0,1]} \int_{H_0^1} (\dot{\phi}(t))^2\,\mu(d\phi) \leq c\bigg\}.
	\end{equation*}
    is compact in ${\mathcal P}({\mathcal C})$.

