[Definition of arXiv:2411.16103, 'Non-commutative Stein's Method: Applications to Free Probability and Sums of Non-commutati'] The $1$-Kantorovich-Rubenstein metric is defined by 
\begin{align*}
d_{W}(\gamma_1, \gamma_2)
  &:= \inf_{\tau \in \Pi[\gamma_1, \gamma_2]} \tau[|Y - X|].
\end{align*}

[Lemma L:ZPL of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] For $F \in {{\mathcal F}_W}$ and $y \in {\mathcal Z}$, 
\begin{equation} 
 P_L( F \cap \{Z_S=y\}) 
  =  {\mathbb E} \Big(  \frac{ 1_F L_y}{X} \Big | X\ge 1 \Big), 
\end{equation}
and 
\begin{equation} 
  P_L( F | Z_S=y) 
  = \frac{ {\mathbb E}\big(  { 1_F L_y}{X^{-1}} \Big | X\ge 1 \big) }
      {  {\mathbb E}\big(  { L_y}{X^{-1}} \Big | X\ge 1  \big) }.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 23 of arXiv:2608.26803, 'On bubbling of Fueter maps'] Let $K$ be a compact smooth manifold of dimension $k$ and let $\cR \subset W$ be a codimension $n$ Fredholm $C^1$-rectifiable subset of a Banach space $W$. If $k < n$, then the exceptional locus
  \begin{equation*}
    \cE_K (\cR) \coloneq \{ f \in C^1(K, W) \, | \, f(K) \cap \cR \neq \emptyset \}
  \end{equation*}
  is Fredholm $C^1$ rectifiable of codimension $n-k$ in $C^1(K, W)$.

