[Corollary cor:LackerZhang of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfies Assumption (as:results:fixedPoint of the paper). Let $\nu_0$ be a solution to the Cayley fixed point{} in the sense of Definition (def:results:CBP of the paper). Then, $(F, 0)$
    solves the Lacker-Zhang fixed point problem with
    \begin{equation}
        F(x) = \frac{1}{\kappa}\Big(U(x) + \log \nu_0(x) \Big), \quad x \in \ensuremath{\mathbb{R}}^d.

    \end{equation} Conversely, if $(F, C)$ solves the Lacker-Zhang fixed point problem, then there is a solution $\nu$ to Cayley fixed point{} in the sense of Definition (def:results:CBP of the paper) characterized by its marginal $\nu_0$, which is given by
    \begin{equation}
        \nu_0(x) = \frac{1}{\mathcal{Z}_F} e^{-U(x) - \kappa F(x)}, \quad  \mathcal{Z}_F := \int_{\ensuremath{\mathbb{R}}^d}  e^{-U(y) - \kappa F(y)} dy, \quad x \in \ensuremath{\mathbb{R}}^d.

    \end{equation}

[Lemma 4 of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Fix $T,\beta,\varepsilon>0$ and $0\le s<t\le T$. For each partition $\pi$ of $[s,t]$, the map $\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[s,t]}$ defined in~\eqref{FirstTrans3dSub} is a sub-probability kernel on $E_\varepsilon$ and satisfies the following:
\begin{enumerate}[(i)]
\item The family $\{\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[s,t]}\}_\pi$ is monotone under refinement pointwise in $(x,A)$: if $\pi'$ refines $\pi$, then for every $x\in E_\varepsilon$ and $A\in\mathcal B(E_\varepsilon)$,
\begin{align}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi'}_{[s,t]}(x,A)
\;\le\;
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[s,t]}(x,A).
\end{align}

\item Fix $0\le r<s<t\le T$ and let $\pi$ be a partition of $[r,t]$ with $s\in\pi$. Then for every $x\in E_\varepsilon$ and $A\in\mathcal B(E_\varepsilon)$,
\begin{align}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[r,t]}(x,A)
\,=\,
\int_{E_\varepsilon}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi|_{[r,s]}}_{[r,s]}(x,dy)\,
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi|_{[s,t]}}_{[s,t]}(y,A).
\end{align}
Here $\pi|_{[r,s]}$ and $\pi|_{[s,t]}$ denote the restrictions of $\pi$ to $[r,s]$ and $[s,t]$, respectively.
\end{enumerate}

[Lem 42 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] We have
\begin{equation*}
	\int_{K_{n}}\M^\vee_v\left(\M\varphi_{\lambda_{\mathrm{E}}(\frac{1}{2}-s)}\cdot\M\bar{f}\right)\cdot f_{s}\\
	=\Delta^{-\frac{n-1}{2}}\xi(n-1)^{-1}\P\left(s,\lambda_{\mathrm{E}}(\tfrac{1}{2}-s);\varphi,f,\Phi\right)
\end{equation*}
for $s$ in general position.

