body:
[Lemma 7 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $(\hat{\xi},\hat{\Xi})=(\hat{\xi}_t,\hat{\Xi}_t)_{t\geq0}$ be the underlying MAP of $\hat{X}$ from (\ref{item_b}) with respect to the $L^1$ norm on $\mathbb{R}^d$, and $L$ be the first time of appearance of a jump of $(\hat{\xi},\hat{\Xi})$ due to the reflection. Let $\tau_D=\inf\{t>0: X_t\notin D\},$ the first exit from the orthant  $D:=(0,\infty)$ by the stable process $X$ in (a). The distribution of the ``corrective" jumps of the MAP $(\hat{\xi},\hat{\Xi})$ is determined by the first exit from the orthant $D$ as follows
\begin{equation}
\begin{split}
&{E}_{\theta}\left(G\left(\log\left(\frac{\|X_{\tau_D}\|_1}{\|X_{\tau_D-}\|_1}\right), \left(\frac{|X^{(i)}_{\tau_D}|}{\|X_{\tau_D}\|}, i\in\{1,\ldots, d\}\right)\right) \Bigg| X_{\tau_D-}\right)
\\
&\hspace{2cm}={\mathbb{E}_{0,\theta}\left(G\left(\Delta\hat{\xi}_{L}, \hat{\Xi}_L\right)\Big| \hat{\Xi}_{L-}=X_{\tau_D-}/\norm{X_{\tau_D-}}_1 \right),
\qquad \theta\in \mathcal{S}_{\|\cdot\|_1} }
\end{split}
\end{equation}
for any bounded measurable function $G:\mathbb{R}\times\mathcal{S}^{d,+}_{1}\to\mathbb{R}$ and any $\boldsymbol{\theta}\in\mathcal{S}^{d,+}_{1}.$ The latter can be computed further via 
\begin{equation}
	\mathbb{E}_{(0,\boldsymbol{\theta})}[G(\Delta \hat{\xi}_{L},\hat{\Xi}_{L})|\hat{\Xi}_{L-}]  = H(\hat{\Xi}_{L-})

\end{equation}
where, for $\Xi\in \mathcal{S}^{d,+}_{1}$
\begin{equation}
H(\Xi)=q(\Xi)^{-1}\cdot\sum_{j=1}^d \int_{\log(1- \Xi^{(j)})}^\infty G\Big(x,\frac{1}{{\rm e}^x}\big( \Xi +({\rm e}^x-1)\boldsymbol{e}_j\big)\Big)\cdot ({\rm e}^x+2 \Xi^{(j)}-1)^{-(1+\alpha)}\cdot {\rm e}^x dx,
\end{equation}
  and we are using the notation $\Xi^{(j)}$ for the the $j$-th coordinate of the position $\Xi$ and $q$ is the function given by \eqref{q}  taking $\rho_k=1/2$ for all $k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm jointr of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix an integer $r \ge 2$. Let $\bm H_n =(H_n^{(1)}, H_n^{(2)})$ be a sequence of 2-hypermultiplexes on the same vertex set $V_n$ with $|E(H_n^{(1)})| \to \infty$ and $|E(H_n^{(2)})| \to \infty$. Suppose $V_n$ is colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold:
    \begin{itemize}
      \item  There exists constants $\lambda_1, \lambda_2, \lambda_{1,2} \ge 0$ with $\lambda_1 \ge \lambda_{1,2}, \lambda_2 \ge \lambda_{1,2}$ such that 
            \begin{align}
            \frac{|E(H_n^{(1)})|}{c_n^{r-1}} \to \lambda_1,~\frac{|E(H_n^{(2)})|}{c_n^{r-1}} \to \lambda_2, \text{ and } \frac{|E(H_n^{(1, 2)})|}{c_n^{r-1}} \to \lambda_{1,2}. 
            \end{align}


      \item  For all $t \in [2, r - 1]$
      \begin{align}
      \frac{|\cK(t, H_n^{(1)})|}{c_n^{2r-t-1}} \to 0 \text{ and } \frac{|\cK(t, H_n^{(2)})|}{c_n^{2r-t-1}} \to 0 , 
      \end{align}
     where $\cK(t, \cdot)$ is defined in (equation defn:K of the paper). 
  \end{itemize} 
Then 
$$\begin{pmatrix}
    T(H_n^{(1)}\setminus H_n^{(2)})\\
    T(H_n^{(2)}\setminus H_n^{(1)})\\
    T(H_n^{(1, 2)})
\end{pmatrix} \dto \begin{pmatrix}
        Z_1 \\
        Z_2 \\
        Z_{1,2}
        \end{pmatrix} , $$
  where $Z_1 \sim \Pois(\lambda_1 - \lambda_{1,2})$, $Z_2 \sim \Pois(\lambda_2 - \lambda_{1,2})$, and $Z_{1,2} \sim \Pois(\lambda_{1,2})$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:q_toll_bound of arXiv:2609.02491, 'Generalised Random Parking for Trapeziums on a Strip'] There exists a finite constant $C>0$ such that, for all sufficiently large $x$,
\begin{equation}
\max_{s\in\{\mathcal{P},\mathcal{T}\}}|q_s(x)| \le C\mathcal R_2(x), \quad \text{where}\quad \mathcal R_2(x) \coloneqq
\begin{dcases}
    \mleft(\dfrac{4e}{x/a}\mright)^{x/a-4},
    &\text{if }a=b,\\
    \mleft(\dfrac{4e}{x/a}\mright)^{x/a-(5+(a+b)/(2a))},
    &\text{if }a>b.
\end{dcases}
\end{equation}

[Lemma 11 of arXiv:2608.29075, 'The 2-Monoidal Structure of Symmetric Sequences'] [\cite{Operads_2013_Hess}] 
Under the equivalence of Lemma \ref{equivalence},
\begin{enumerate}[1)]
    \item the left Kan extension of $\Phi \times \Psi$ along the fibered product functor 
    \begin{align*}
    \catname{Cospan} &\rightarrow \catname{A}^{\op} \\
    \left(T \xrightarrow{f} S, T' \xrightarrow{f'} S\right) &\mapsto \left(T \times_{S}T' \xrightarrow{f\times_{S} f'} S\right)
    \end{align*}
    corresponds to the matrix monoidal product of symmetric sequences,
    \item the left Kan extension of $\Phi \times \Psi$ along the composition functor \begin{align*}
    \catname{Comp} &\rightarrow \catname{A}^{\op} \\ \left(S\xrightarrow{f} R, T \xrightarrow{g} S\right) &\mapsto \left(T \xrightarrow{gf} R\right)
    \end{align*}
    corresponds to the composition product of symmetric sequences, and
    \item the unit for the external product of functors is $\Gamma: \catname{A}^{\op} \rightarrow \C$ specified by $\Gamma(f) = \textbf{1}$ if $f$ is a bijection and $\Gamma(f) = \varnothing$ otherwise.
\end{enumerate}

[Lemma 16 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Fix an arbitrary $\varepsilon>0$ and two times $(t,\tilde{t}) \in [0,T] \times [t,T]$. We consider a partition $\Pi^\ell \coloneqq (t^{{\ell}}_k)_{k\in\{0,\ldots,n^\smalltext{\ell}\}}$ of the interval $[t,\tilde{t}]$ with mesh size smaller than $\ell \in (0,\ell_\varepsilon)$, and such that $t^\ell_0 = t$ and $t^\ell_{n^\smalltext{\ell}} = \tilde{t}$. Then, it holds that
\begin{align}
\widetilde{V}_t &\geq \esssup_{\alpha \in \widetilde{\cA}} \E^{\Q^{\smalltext{\alpha} \smalltext{,} \smalltext{t}}_{\smalltext{\cdot}}} \Bigg[ \widetilde{V}_{\tilde{t}} + \int_{t}^{\tilde{t}} \widetilde{f}_s\big(X^1_{\cdot \land s}, {\alpha}_s\big) \d s + \sum_{k=0}^{n^\smalltext{\ell}-1} \bigg( G\Big(\E^{\Q^{\smalltext{\alpha}\smalltext{,}\smalltext{t}^\tinytext{\ell}_\tinytext{k}}_\smalltext{\cdot}}\Big[\M^{\star}_{t^\smalltext{\ell}_{\smalltext{k}\smalltext{+}\smalltext{1}}}\Big]\Big) - G\Big(\M^{\star}_{t^\smalltext{\ell}_{\smalltext{k}\smalltext{+}\smalltext{1}}}\Big) \bigg) \Bigg] - n^\ell \varepsilon \ell, \; \P\text{\rm--a.s.}
\end{align}

