[Lemma lemma_M of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] For any bounded deterministic matrices $A_1,A_2 \in {\mathbb C}^{2n \times 2n}$, we have
	\begin{align}
		\|M^{A_1}_{12}(\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2)\| \lesssim \frac{1}{\gamma},
	\end{align}
\begin{align}
	\big|\<\widehat M^{A_1}_{12} (\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2) A_2 \>\big| \lesssim \frac{\rho_1\rho_2}{\widehat \gamma},
\end{align}
\begin{align}
	\|M^{A_1,A_2}_{121}(\mathrm{i} \eta_1, A_1,\mathrm{i} \eta_2, A_2,\mathrm{i} \eta_1)\|  \lesssim \frac{1}{\eta_*\gamma},
\end{align}
uniformly for any $|z_i|<10$ and  $0<|\eta_i|<10$, where $\eta_*:=\min_{i=1,2}|\eta_i|$ and $\rho^*:=\max_{i=1,2}|\rho_i|$ with $\rho_i:=\pi^{-1}|\mathrm{Im}\, m^{z_i}(\mathrm{i}\eta_i)|$\normalcolor, and the following parameters:
\begin{align}
	\gamma=\gamma(\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2):=\frac{|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2}{|z_1-z_2|+\rho_1^2+\rho_2^2+\frac{\eta_1}{\rho_1}+\frac{\eta_2}{\rho_2}},
\end{align}
\begin{align}
	\widehat\gamma=\widehat\gamma(\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2):=|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The L\'evy measure of multivariate IGCP is given by
\begin{equation*}
\hat{\Pi}_{\bar{\mathcal{M}}}(A_1\times A_2\times \dots\times A_q)=\sum_{j_0=1}^{k_0}\mu_{j_0}\sum_{\bar{n}\succ\bar{0}}\sum_{\substack{\Omega(k_i,n_i)\\i=1,2,\dots,q}}\prod_{i=1}^{q}\Big(\prod_{j_i=1}^{k_i}\frac{(j_0\lambda_{ij_i})^{n_{ij_i}}}{n_{ij_i}!}e^{-j_0\lambda_{ij_i}}\Big)\mathbb{I}_{\{n_i\in A_i\}},
\end{equation*}
where $\Omega(k_i,n_i)=\{(n_{i1},n_{i2},\dots,n_{ik_i}):\sum_{j_i=1}^{k_i}j_in_{ij_i}=n_i,\,n_{ij_i}\in\mathbb{N}_0\}$.

