[Lemma lem:2 of arXiv:2602.00988, 'Wealth exchange under ceiling and flooring constraints: a modified Bennati–Dragulescu–Yako'] Let ${\bf p}(t) = \{p_n(t)\}_{n\geq 0}$ be a classical solution to the system of nonlinear ODEs (equation eq:law_limit of the paper)-(equation eq:two-classes of the paper) with ${\bf p}(0) \in V_\mu$, we have
\begin{equation}
\sup\limits_{t\geq 0} \sum\limits_{n\geq 0} K^n\,p_n(t) \leq \max\left\{\frac{K^{b+1}+K^a}{1-\mu/b},\sum_{n\geq 0} K^n\,p_n(0)\right\}
\end{equation}
for all $K > 1$, provided that $\sum_{n\geq 0} K^n\,p_n(0) < \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Let $\ma{s}=(s_{ij})$ be a continuous, symmetric, positive semi-definite $d\times d$ matrix-valued function on $\R^{d}$, $\ma{b}:\R^{d}\rightarrow \R^{d}$ a continuous function. Let $X(t)$ be an It\^{o} diffusion with generator
     $$Af=\frac{1}{2}\sum_{i,j}s_{ij}\partial_{i}\partial_{j}f+\sum_{i}b_{i}\partial_{i}f, \qquad f\in C_{c}^{\infty}(\R^{d}),$$
    and initial distribution $\nu$.

    Suppose $X_n(i), i\ge 0$ is a Markov chain in $\R^d$ with increments $Z_n(i+1)=X_n(i+1)-X_n(i)$ such that for each $r>0$
        \begin{equation}
        \begin{split}
            \sup_{|x|\le r}\left|m_n\ev[Z_n(i)|X_n(i-1)=x]-\ma{b}(x)\right| &\rightarrow 0,\\
            \sup_{|x|\le r}\left|m_n \ev[Z_n(i)Z_n(i)^{\top}|X_n(i-1)=x]-\ma{s}(x)\right|&\rightarrow 0,\\
            \sup_{|x|\le r}\left|m_n\ev[|Z_n(i)|^{4}|X_n(i-1)=x]\right|&\rightarrow 0,\\
        \end{split}
    \end{equation}
    uniformly for $i/m_n$ on compact subsets of $\R_+$ as $n\to\infty$, and $X_n(0)\Rightarrow \nu$ in law. Then 
    we have
     \begin{align}
       \left( X_n({\lfloor t m_n\rfloor}, t\ge 0) \right)\Rightarrow \left(X(t), t\ge 0\right)
     \end{align}
     in law, with respect to the Skorokhod topology on compact subsets of $\R_+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 11 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Let $\alpha,\beta>0.$ Then
\[
\begin{aligned}
&\mathbb{P}\!\left(
M_T^-<\alpha,\,
M_T^+<\beta,\,
H_I<H_S
\right)\\[1mm]
&=
\begin{cases}
\displaystyle
\int_0^\beta
\frac{
\left[
\gamma W^{(\gamma)}(r)
-
\bigl(Z^{(\gamma)}(r)-1\bigr)
\dfrac{W^{(\gamma)\prime}(r)}
{W^{(\gamma)}(r)}
\right]^2
}{
\gamma W^{(\gamma)}(r)
}\,dr,
& 0<\beta\leq\alpha,
\\[6mm]
\displaystyle
\int_0^\alpha
\frac{
\left[
\gamma W^{(\gamma)}(r)
-
\bigl(Z^{(\gamma)}(r)-1\bigr)
\dfrac{W^{(\gamma)\prime}(r)}
{W^{(\gamma)}(r)}
\right]^2
}{
\gamma W^{(\gamma)}(r)
}\,dr
\\[3mm]
\displaystyle\qquad
+
\frac{
\left[
\gamma W^{(\gamma)}(\alpha)
-
\bigl(Z^{(\gamma)}(\alpha)-1\bigr)
\dfrac{W^{(\gamma)\prime}(\alpha)}
{W^{(\gamma)}(\alpha)}
\right]^2
}{
\gamma W^{(\gamma)\prime}(\alpha)
}
\\[3mm]
\displaystyle\qquad\qquad\times
\left[
1-
\exp\!\left\{
-(\beta-\alpha)
\frac{W^{(\gamma)\prime}(\alpha)}
{W^{(\gamma)}(\alpha)}
\right\}
\right],
& \beta>\alpha.
\end{cases}
\end{aligned}
\]

[Lemma 1 (Per-step Descent for Smooth Losses) of arXiv:2608.27763, 'Fast Weight Attention for Continual Learning'] Let $f:\mathbb{R}^{d_x\times d_v}\to\mathbb{R}$ be $L$-smooth with respect to the Frobenius norm. For any step size $\eta\in(0,2/L)$, the gradient step $\Sbb^{+}=\Sbb-\eta\nabla f(\Sbb)$ satisfies
\begin{equation}
f(\Sbb^{+}) \le f(\Sbb) - \frac{\eta(2-\eta L)}{2}\,\|\nabla f(\Sbb)\|_F^2.
\end{equation}

