[Proposition pro: Moment Bounds on hat q for JSQ of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Moment Bounds on $\hat{q}_{\Sigma}$)}

    Under the assumption (ass:heavy_overload of the paper), with $\hat{q}_{\Sigma}:= \sum_i q_i - \frac{\lambda-\mu}{\gamma}$, we have the moment bounds for any $p\geq 1, p\in \mathbb{R}$:
    \begin{align*}
        \mathbb{E}[|\hat{q}_{\Sigma}|^p]^{1/p} &\leq \max\{C_{\lambda,\mu,n}'' \cdot\frac{\sqrt{p}}{\sqrt{\gamma}} + C_{\lambda,\mu,n}'\cdot p, \: n(A_{\lambda,\mu,n} +\frac{1}{n}) \frac{p}{\log(1+\frac{n\gamma}{\lambda}p)}\} \\
        \mathbb{E}[|\hat{q}_{\Sigma}|^p]^{1/p} &\geq  C_{4,\lambda,\mu} \exp(-8(15+A_{\lambda,\mu})\frac{\lambda}{\gamma p}) \frac{p}{\log(1+\frac{p\gamma}{\lambda})}
    \end{align*}
    Constants $C_{\lambda,\mu,n}'$, $C_{\lambda,\mu,n}''$ and $A_{\lambda,\mu,n}$ are defined in (equation eq: subexpo L-p norm JSQ of the paper) and (equation eq: MGF upper bound JSQ of the paper), respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:D12 of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$ and there are two large spokes, then
\begin{equation}
  D_1=|C(\zeta)-1|\le m-\frac34,
\end{equation}
\begin{equation}
  D_2=|C(\zeta^2)-1|\le m+\frac12.
\end{equation}

[Lemma 18 of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Let $G=(V,E)$ be a graph that contains the designated hierarchical-star 
\(
HS(v):=\mathrm{HStar}\!(v;\{u_i\}_{i\le \lceil n^{\varepsilon}\rceil};\{w_{i,j}\}_{i\le  \lceil n^{\varepsilon}\rceil,\,j\le \lceil n^{\varepsilon_1}\rceil })
\)
as in Definition~\ref{def:hierarchical-star}, for some $\varepsilon\ge \varepsilon_1>0$. Let $\varepsilon_2=\frac{1}{200}\min\{\rho,\lambda,1\}\varepsilon_1$. Fix any $i_0\le n^{\varepsilon}$. Suppose that $N\in \mathcal{G}(u_{i_0}, \{w_{{i_0},1},\dots, w_{{i_0},\lceil n^{\varepsilon_1}\rceil} \})$ is an event implying that there exist random times $T_\ell$ for $\ell =1,\dots,\lfloor n^{\varepsilon_2/2}\rfloor$ such that each $T_\ell$ is measurable with respect to $\mathcal{G}(u_{i_0}, \{w_{{i_0},1},\dots, w_{{i_0},\lceil n^{\varepsilon_1}\rceil} \})$, $T_{\ell +1}-T_\ell\ge 3$, and $u_{i_0}$ is infected at time $T_\ell$. Then, for any $x\in \{v\}\cup\{u_i\}_{i\le \lceil n^{\varepsilon}\rceil,\, i\ne i_0}$, there exists an event $A_x\in \mathcal{G}(HS(v))$ such that, for all sufficiently large $n$, the following hold:
\begin{enumerate}
    \item[\normalfont (i)] On $A_x\cap N$, there exists a random time $T\le T_{\lfloor n^{\varepsilon_2/2}\rfloor}+3$ such that $T$ is measurable with respect to $\mathcal{G}(HS(v))$, and the vertex $x$ is infected at time $T$;
    \item[\normalfont (ii)] $\mathbb{P}(A_x)\ \ge\ 1-\exp(-n^{\varepsilon_2/3})$.
\end{enumerate}

