		\begin{equation*}
			\Phi^{1,\bset{T}}_x:= \sum_{y}^{(Tx)}\bigg(|X_{xy}|^2 - \frac{1}{N}\bigg), \qquad \Psi^{1,\bset{T}}_x:=  \sum_{y}^{(Tx)}\bigg(|X_{xy}|^2 - \frac{1}{N}\bigg) G^{\bset{Tx}}_{\ubarr{y}\ubarr{y}},
