body:
[Theorem 2 of arXiv:2511.19308, 'Universal scaling limits at the spectral singularity of structured random matrices'] Let $H$ be a Hermitian $K \times K$-block random matrix with centred independent Gaussian entries as in \eqref{eq: matrix model definition}.
    Let $\zeta \in \C \setminus \R$ with $\Im(\zeta) > 0$.

    For $K = 2$ and
    \[
        S = \begin{pmatrix}
            s_{11} & s_{12} \\
            s_{12} & 0
        \end{pmatrix}, \qquad
        \text{with }\; s_{11}, s_{12} > 0,
    \]
    we have
    \begin{equation} 
        \begin{split}
        \lim_{N \to \infty} \frac{s_{12}}{\sqrt{s_{11}}} \frac{1}{N^{3/2}} \E\s*{\Tr\p*{\frac{1}{H - \frac{s_{12}}{\sqrt{s_{11}}} N^{-3/2} \zeta}}}
        & = \frac{\ii \sqrt{2}}{\sqrt{\pi}} \bigg[
            \frac{1}{2}
            \MeijerG{3, 0}{0, 3}{-}{0, \frac{1}{2}, \frac{1}{2}}{-\frac{\zeta^2}{8}}
            \HypergeometricPFQ{0}{2}{-}{\frac{1}{2}, 1}{-\frac{\zeta^2}{8}}
        \\
        & \hphantom{= \frac{\ii \sqrt{2}}{\sqrt{\pi}} \bigg[}
            + \MeijerG{3, 0}{0, 3}{-}{\frac{1}{2}, 1, \frac{3}{2}}{-\frac{\zeta^2}{8}}
            \HypergeometricPFQ{0}{2}{-}{\frac{3}{2}, 2}{-\frac{\zeta^2}{8}}
        \\
        & \hphantom{= \frac{\ii \sqrt{2}}{\sqrt{\pi}} \bigg[}
            + \MeijerG{3, 0}{0, 3}{-}{\frac{1}{2}, \frac{1}{2}, 1}{-\frac{\zeta^2}{8}}
            \HypergeometricPFQ{0}{2}{-}{1, \frac{3}{2}}{-\frac{\zeta^2}{8}}
        \bigg],
        \end{split}
    \end{equation}
    where $G_{p,q}^{m,n}$ is the Meijer $G$-function \cite[\DLMFsecref{16.17}]{NIST:DLMF} and ${}_p F_q$ is the generalized hypergeometric function \cite[\DLMFsecref{16.2}]{NIST:DLMF}.

    For $K = 3$ and
    \[
        S = \begin{pmatrix}
            s_{11} & s_{12} & s_{13} \\
            s_{12} & s_{22} & 0 \\
            s_{13} & 0 & 0
        \end{pmatrix}, \quad
        \text{with }\; s_{11} \geq 0 \;\text{ and }\; s_{12}, s_{13}, s_{22} > 0,
    \]
    we have
    \begin{eqsplit} 
        \lim_{N \to \infty} \frac{s_{13} \sqrt{s_{22}}}{s_{12}} \frac{1}{N^2} \E\s*{\Tr\p*{\frac{1}{H - \frac{s_{13} \sqrt{s_{22}}}{s_{12}} N^{-2} \zeta}}}
        & = 2 \ii \bigg[
            K_0\p*{2 \sqrt{-\ii \zeta}} I_0\p*{2 \sqrt{-\ii \zeta}}
        \\
        & \hphantom{= 2 \ii \bigg[}
            + K_1\p*{2 \sqrt{-\ii \zeta}} I_1\p*{2 \sqrt{-\ii \zeta}}
        \bigg],
    \end{eqsplit}
    where $K_{\nu}$ and $I_{\nu}$ are the modified Bessel functions \cite[\DLMFsecref{10.25}]{NIST:DLMF}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 9 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every $\beta\in\NN^n$ with $|\beta|=d-2$, the matrix
\begin{equation}
 H_\beta=(c_{\beta+e_i+e_j})_{i,j=1}^n
\end{equation}
has at most one positive eigenvalue.  If it is nonzero, it has exactly one
positive eigenvalue.  In particular, for every nonempty $I\subseteq[n]$,
\begin{equation}
 (-1)^{|I|-1}\det (H_\beta)_I\ge0.
\end{equation}

[Proposition of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Suppose that
\begin{align*}
    \sup_{(x,y)\in [0,1]^2}|w(x,y)|<1.
\end{align*}
Then, the free Fisher information of $\mu_{w}$ is finite. In particular, $\mu_{w}$ is absolutely continuous with respect to the Lebesgue measure, and its density is in $L^3(\mathbb{R})$.

