body:
[Definition eq:entropy of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] Define the \emph{entropy}\index{entropy} of $\mathsf{acc}$ as:
	\begin{align}
	\varphi_\mathsf{acc}(p):=\mathrm{Exp}_p\mathsf{acc}(p)=p\mathsf{acc}_1(p)+(1-p)\mathsf{acc}_0(p)
	\end{align}

[Lemma lem:cox of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $\lambda$ be a nonnegative progressively measurable process, and denote $\Lambda_t \coloneqq \int_0^t \lambda_s \,ds$. Suppose that $\Lambda_t < \infty$ for all $t \geq 0$ and $\Lambda_\infty = \infty$, $\mathbb{P}$-a.s. Moreover, suppose that $\Omega$ supports an $\operatorname{Exp}(1)$ random variable $E$ which is independent of $\mathcal{F}_\infty$. Define the random time
	\begin{equation*}
		\tau \coloneqq \inf\{t > 0: \Lambda_t \geq E\},
	\end{equation*}
	and define the filtration $\mathbb{A} = (\mathcal{A}_t)_{t \geq 0}$ by $\mathcal{A}_t \coloneqq \sigma(\{\tau \leq s\}; s \leq t)$. Let $\mathbb{G} \coloneqq \mathbb{F} \newtriangledown \mathbb{A}$. Then, the process $(\bm{1}_{\{\tau \leq t\}} - \Lambda_{\tau \land t})_{t \geq 0}$ is a $\mathbb{G}$-martingale, and we have $\mathbb{F} \hookrightarrow \mathbb{G}$.

[Theorem 15 of arXiv:2605.07184, 'Convergence of Stochastic Gradient Descent with mini-batching and infinite variance'] Let $\{X_{i,n},{1\leq i\leq m_n,n\geq 1}\}$ be a triangular array of rowwise independent
  random vectors such that $\esp[\|X_{i,n}\|]<\infty$. Define
  \begin{align*}
    S_n =\sum_{i=1}^{m_n}\left\{X_{i,n}-\esp[X_{i,n}]\right\}\;.
  \end{align*}
  Let $\nu$ be an $\alpha$-homogeneous Borel measure on $\Rset^d\setminus\{0\}$. Assume
  that
  \begin{align}

    \sum_{i=1}^{m_n} & \ \pr\!\left({X_{i,n}}\in \cdot \right) \convvague \nu \; , \\

    \lim_{\epsilon\to 0} \ \limsup_{n\to\infty}   & \ \esp\left[\|X_{i,n}\|^2
    \ind{\|X_{i,n}\|\le \epsilon}\right]  = 0 \; 
  \end{align}
  as $n\to\infty$ and for every $\epsilon>0$,
  \begin{align}

    \lim_{n\to\infty} \max_{1\le i\le m_n} & \pr(\|X_{i,n}\|>\epsilon )  = 0 \; .
  \end{align}
  Then $S_n$ converges weakly to a stable random vector $\Lambda$ with characteristic
  function given by
  \begin{align}

    \log\esp\left[e^{i u^\top \Lambda}\right]=\int_{\Rset^d\setminus\{0\}}
    \left\{e^{iu^\top x}-1-iu^\top x\right\}\,\nu(\rmd x) \; , \qquad u\in\Rset^d \; .
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 of arXiv:2511.06414, 'Non-uniform Edgeworth expansions for weakly dependent random variables and their applicati'] Under Assumption \ref{AssStat}
there are polynomials $\textbf{H}_j$ whose coefficients are polynomial functions of  $\al_j=q_{j+2}-\frac{q_2p_{j+2}}{p_2}$ and $\beta_j=\frac{p_{j+2}}{p_2}$ for $j\leq m-2$ so that
\begin{equation}
\Phi_{n,m}(x)=\Phi(x)-\varphi(x)\sum_{j=1}^{m-2}\sig_n^{-j}\textbf{H}_{j}(x)+e^{-x^2/2}R_n(x)\sig_n^{-(m-1)}
\end{equation}
where $R_n$ is a polynomials with bounded coefficients and degree depending only on $m$.
As a consequence, if Theorems  \ref{Edge2}, \ref{BE1} and \ref{Edge1} hold true with $A_n=0$, $B_n=\sig_n$  and $\Psi_{k,n}=\Phi_{k+2,n}$ given by \eqref{deff}, then the same results 
 hold true for every $m$ with the function $\mathbf{\Phi}_{m,n}$ given by 
\begin{equation}
\mathbf{\Phi}_{m,n}(x)=\Phi(x)-\varphi(x)\sum_{j=1}^{m-2}\sig_n^{-j}\textbf{H}_j(x)
\end{equation}
instead of the function $\Phi_{m,n}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2608.10415, 'Continuous random variables'] The integrals over the symmetric group $S_N$ are given by
$$\int_{S_N}u_{i_1j_1}\ldots u_{i_kj_k}=\begin{cases}
\frac{(N-|\ker i|)!}{N!}&{\rm if}\ \ker i=\ker j\\
0&{\rm otherwise}
\end{cases}$$
where $\ker i$ denotes as usual the partition of $\{1,\ldots,k\}$ whose blocks collect the equal indices of $i$, and where $|.|$ denotes the number of blocks.

[Lem surftype of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\lambda$ be a connected surface (i.e., $2$-manifold), possibly non-compact and possibly with boundary. Then at least one of the following holds:
    \begin{enumerate}
        \item $\pi_1(\lambda)$ remains nontrivial after capping off all the closed boundary components of $\lambda$.
        \item $\lambda$ is a compact genus 0 surface.
        \item $\lambda$ becomes homeomorphic to $\mathbb{R}^2$ after filling the closed boundary components with disks and deleting the open boundary components. In that case, $\pi_1(\lambda)$ is freely generated by its closed boundary components.
    \end{enumerate}

[Definition solution definition (u P) of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\tau^*$ be a stopping time with $\mathbb P(\tau^*>0)=1$, and let $(u,\tau^*) \triangleq (u(t))_{t\in [0,\tau^*)}$ be a progressively measurable process on $H_{\rm div}^s$.
		The pair $(u,\tau^*)$ is called a maximal $H_{\rm div}^s$ classical solution to (equation Target problem (u P) damp of the paper) if ${\mathbb P}\text{-}{\rm a.s.}$ the following conditions are satisfied:
		\begin{itemize}
			\item (equation Target problem (u P) damp of the paper) holds as an equality in $C(\mathbb K^d)$ for all $t\in[0,\tau^*)$;
			\item  $\sup_{[0,T]}\|u(t)\|_{H^s}<\infty$ for all $T<\tau^*$;
			\item $\limsup_{t\uparrow\tau^*}\|u(t)\|_{\mathbb H^s}=\infty$ a.s. on $\{\tau^*<\infty\}.$
		\end{itemize}
		In particular, if $\mathbb P(\tau^*=\infty)=1$, the solution is called global.

[Lemma 12 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $\mathbf q=(q_1,\ldots,q_m)$ be a Bohnenblust--Hille exponent, fix $i\in\{1,\ldots,m\}$, and put $\mathbf q^+=(q_1,\ldots,q_m,2)$. Then
\begin{equation}
C_{\mathbf q^+}^{(m+1)} \ge2^{1/q_i-1/2}C_{\mathbf q}^{(m)}.
\end{equation}

[Definition 10 (Finite directional coefficient module) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] The \emph{directional relation submodule} is
\[
U_{\Lambda,\bm{w}}^{\mathrm{dir}}
:=
U_{\Lambda}^{\mathrm{Eul}}
+
U_{\Lambda}^{\mathrm{tr}}
+
U_{\Lambda,\bm{w}}^{\mathrm{van}}
\subset
F_{\Lambda},
\]
and the \emph{finite directional coefficient module} is
\begin{equation}

M_{\Lambda,\bm{w}}^{\mathrm{dir}}
:=
F_{\Lambda}/U_{\Lambda,\bm{w}}^{\mathrm{dir}}.
\end{equation}

[Lemma 25 (Smooth conditional fiber weights) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Assume exact depth $r$ at $\theta_0$ together with \cref{ass:regularity}, and fix $m<r$. Let $y\in\cS_m$ and $z\in F_y$. Then, for $\theta$ near $\theta_0$, the stationary conditional weight
\begin{equation}
\alpha_z(\theta):=P_{\theta,\mathrm{stat}}(Z_t^{(r)}=z\mid Z_t^{(m)}=y)
\end{equation}
is well defined and $C^1$ in $\theta$.
More explicitly,
\begin{equation}
\alpha_z(\theta)=\frac{\pi_\theta(z)}{\sum_{w\in F_y}\pi_\theta(w)},
\end{equation}
where $\pi_\theta$ is the stationary law of the depth-$r$ chain.

[Lemma 9--lemma6.61 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Assume that $A_n$ satisfies the assumptions in Theorem (Theorem1.2 of the paper) and $X\sim\operatorname{Col}_n(\zeta)$. Fix any $\kappa>0$, $\Delta>0$ and some $\sigma\in(0,1)$. Then there exists an event $\mathcal{E}_\sigma(A_n)$ with $\mathbb{P}(A_n\in\mathcal{E}_\sigma(A_n))\geq 1-\exp(-\Omega(n^{\sigma/2}))$ such that for any $A_n\in\mathcal{E}_\sigma(A_n)$, the following holds:

   \begin{enumerate}
       \item Fix any given $(\theta_1,\theta_2)\in\mathbb{R}^2$ satisfying $|\theta_1\theta_2|=1$.   Then there exists some $J\in\{1,2\}$ depending on $A_n$ and $|\theta_1/\theta_2|$ such that, for any $1\leq k\leq {c_0}_{(9--lemma6.61 of the paper)}n^\sigma$ and for any \begin{equation}s\in\left(e^{-cn}, \frac{C_{(9--lemma6.61 of the paper)}\cdot \mu_k(\lambda_J)}{{\left(\prod_{i=1}^2\mu_1(\lambda_i)\right)^{1/2}}}\right),\end{equation} we have the estimate
    \begin{equation}
\mathbb{P}_{\widetilde{X}}\left(\left\|\sum_{i=1}^2 \frac{\theta_i}{\mu_1(\lambda_i)}(A_n-\lambda_i I_n)^{-1}\widetilde{X}\right\|_2\leq s
\right) \lesssim s e^{-ck},
    \end{equation} where ${c_0}_{(9--lemma6.61 of the paper)}>0$ and $C_{(9--lemma6.61 of the paper)}>0$ are two constants that depend only on $\kappa,\Delta$ and $B$. The constant $c>0$ depends only on $B$.
    \item  Fix any given $(\theta_1,\theta_2)\in\mathbb{R}^2$ satisfying $\max(|\theta_1|,|\theta_2|)=1$. Then there exist $I,J\in\{1,2\}$ depending on $A_n$ and $|\theta_1/\theta_2|$ such that, for any $1\leq k\leq {c_0}_{(9--lemma6.61 of the paper)}n^\sigma$ and any 
    \begin{equation}
s\in(e^{-cn},\frac{\mu_k(\lambda_J)}{\mu_1(\lambda_I)})
    \end{equation} we have the same estimate (equation 2122122121122 of the paper).
     \end{enumerate}

[Proposition prop:concentration3 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] There exists  $0<C_\star<C_2$ such that if $t\in [0,1)$  and $x\in \mathbb{R}^d$ satisfy \begin{equation}
1-t^2\leq C_\star^{-1}\log(\epsilon^{-1})^{-C_\star} \text{ and } \|tx\|^2\leq 1-C_2^{-1}\log(\epsilon^{-1}+1)^{-K},
\end{equation}
then for all $l\in \{1,...,\lfloor \beta \rfloor\}$ we have
    $$\int \|f^l(y)-f^l(tx)\|^2dp^{t,x}(y)\leq C\log(\epsilon^{-1})^{C_3}(1-t^2)^{\beta-\lfloor \beta \rfloor }\log((1-t^2)^{-1})^{-2\theta}.$$

