body:
[Proposition 2 of arXiv:2607.24533, 'Colored Markov-Modulated Brownian Motion for Preemptive Workload Stacks'] {Suppose that Assumptions~\ref{assump:intensity} and~\ref{assump:stability} hold.}
Then, using the active-time MMBM of Lemma~\ref{lem:active-censoring} and iterating from $c=C$ down to $c=2$, the depletion probability matrix defined in \eqref{eq:Phi-y} admits the representation
\begin{align*}
\vect{\Phi}_c(y)=e^{\vect{U}_c y},\qquad y>0,
\end{align*}
where $\vect U_c$ is the unique depletion exponent solving
\begin{equation}

\tfrac12(\vect{\Delta}_{\sigma}^{(c)})^2\vect U_c^2
+\vect{\Delta}_{\mu}^{(c)}\vect U_c
+\widetilde{\vect T}^{(c)}
=\vect0,
\end{equation}
for which $0$ is a simple eigenvalue with right eigenvector $\e$, and all nonzero eigenvalues lie in the open left half-plane.

{At color $1$, under the corresponding conditions in Assumption~\ref{assump:stability}:}
\begin{itemize}
\item \emph{Hold-and-jump model.} Color $1$ is depleting, and \eqref{eq:layer-qme} and {\eqref{eq:neg_drift}} again give a unique depletion exponent $\vect U_1$, with $\vect\Phi_1(y)=e^{\vect U_1 y}$, $y>0$.

\item \emph{Regulated-base model.} Color $1$ is regulated rather than depleted, and there is instead a unique stationary regulated-MMBM decay exponent $\vect K_{\mathrm{reg}}$ solving
\begin{equation}

\tfrac12 \vect{K}_{\mathrm{reg}}^{2}(\vect{\Delta}_{\sigma}^{(1)})^{2}-\vect{K}_{\mathrm{reg}}\vect{\Delta}_{\mu}^{(1)}+\widetilde{\vect{T}}^{(1)}=\vect{0},
\end{equation}
with eigenvalues in the open left half-plane, giving the anchor density
\begin{equation}

\vect{\nu}^{\mathrm R}(x)=\vect{g}_{\mathrm{reg}}e^{\vect{K}_{\mathrm{reg}}x},
\qquad x>0,
\end{equation}
where $\vect{g}_{\mathrm{reg}}$ satisfies the reflecting boundary condition
\begin{equation}

\vect{g}_{\mathrm{reg}}\left(\tfrac12\vect{K}_{\mathrm{reg}}(\vect{\Delta}_{\sigma}^{(1)})^{2}-\vect{\Delta}_{\mu}^{(1)}\right)=\vect{0},
\end{equation}
fixing its direction up to scale.
\end{itemize}

[Corollary anisotropic Lp Sobolev corollary of arXiv:2608.27248, 'Optimal Transport and the ABP Method in Higher Codimension'] Under the assumptions of Theorem (Polya Szego theorem of the paper), every
$u\in W_0^{1,p}(\Sigma)$, $1<p<n$, satisfies
\begin{equation}
 \left(\int_\Sigma |u|^{p^*}\,\mathrm d\mu\right)^{1/p^*}
 \leq A_{n,p}
 \left(\frac{\omega_n}{V_*(\mathcal E)}\right)^{1/n}
 \left(\int_\Sigma
  h_{\mathcal E}(\nabla^\Sigma u)^p\,\mathrm d\mu\right)^{1/p}.
\end{equation}
The constant is optimal uniformly over the stated class.  In particular,
$\mathcal E=\mathbb{B}^{n+m}$ gives the sharp inequality
\[
 \|u\|_{L^{p^*}(\Sigma)}
 \leq A_{n,p}\|\nabla^\Sigma u\|_{L^p(\Sigma)}
\]
for minimal submanifolds of codimension at most four.

[Theorem th:main of arXiv:2607.05345, 'The local product condition implies cutoff'] For any $0<\varepsilon\le 1/2$, we have
		\begin{eqnarray}

			\mathrm{w}_{\textsc{mix}}(\varepsilon) & \le & \frac{3}{2\gamma_\star}\log \frac{1}{\varepsilon}.
		\end{eqnarray}
		In particular, the cutoff phenomenon occurs as soon as, for some  (hence every) $\varepsilon\in(0,1)$,
		\begin{eqnarray}

			\gamma_\star \times \mathrm{t}_{\textsc{mix}}(\varepsilon) & \xrightarrow[n\to\infty]{} & \infty.
		\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:lm:aniso of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Fix $t_0 \in I$.
    Suppose either
    \begin{enumerate}[(1)]
        \item $\ell(x) = \log\log(x)$ and $h_n = e^{-\rho n^\gamma}$, where $\rho>0$ and $\gamma>0$; or
        \item $\ell(x) = \log(x)$ and $h_n = n^{-\gamma}$, where $\gamma>0$.
    \end{enumerate}
    Then, under Assumptions (a:sigma:aniso of the paper) and (a:psi:lil of the paper), we have
    \begin{align}
        \lim_{h\to0^+} \sup_{t\in I: 0<\phi(t-t_0) \le h} \frac{|X(t)-X(t_0)|}{\phi(t-t_0)\sqrt{\ell(1/ \psi(\phi(t-t_0)))}} = C \quad \text{a.s.}
    \end{align}
    for some non-random number $C=C(t_0)$ such that
    \begin{align}
        C \le \begin{cases}
        (\sqrt{2}+KC_4/2)C_2 & \text{in Case (1),}\\
        (\sqrt{2/\nu}+KC_4/2)C_2
        & \text{in Case (2),}
    \end{cases}
    \end{align}
    where $K$ is a universal constant and $\nu = \sum_{i=1}^N \theta_i^{-1}$, with $1/0=\infty$ and $1/\infty = 0$.
    If in addition Assumption (a:cv:lil of the paper) holds,
    then $C \ge C_1 [2\gamma^{-1}(1-\sqrt{1-C_0})]^{1/2} > 0$ in both Cases (1) and (2). (Proof in the paper; no proof environment follows the statement in the TeX.)

