[Lemma truncated_selection_sets_decouple_label_degree_whp of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $k\in\mathbb{N}$, $\alpha\in(0,m+1)$, and $D>m(m+1)$. Let the choice sequence $\mathbf x$ satisfy Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper) and~$\hyperref[ass:A]{\mathbf{x}}$(item:lb of the paper) with $I_{\hyperref[ass:A]{\mathbf{x}}}=\mathcal{O}((h_n^+)^{\gamma_0(1/2-\delta)})$ and let $(t_n)_{n\in\mathbb{N}}$ be a truncation sequence such that $  I_{\hyperref[ass:A]{\mathbf{x}}}\leq t_n\leq n$ for all $n\in\mathbb{N}$. Let $\beta\in(0,1)$, and $\gamma',\gamma''\in(1,2]$ such that  $\gamma'<\gamma''$ and $\beta>\gamma''(1/2-\delta)$. Then,
\begin{equation}
\mathbb{P}((\overline{\mathcal{S}^-_{n,1}},\overline{\mathcal{S}^+_{n,1}})\in\mathcal{B}_{\alpha,D}) = 1-o(1),\quad \mathbb{P}((\overline{\mathcal{S}^-_{n,1}},\overline{\mathcal{S}^+_{n,1}})\in \mathcal{G}_{\beta,\gamma',\gamma''}) = 1-o(1).
\end{equation}

