[Lem l:8.3n of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let ${\rm A}$, ${\mathbf A}$ be as in Lemma~(l:8.3 of the paper), $z \in {\mathbf A}$ and $x \in {\rm B}(z;r_n)$. Then,
	\begin{equation}
		\mathbb{P}_x \Big(\min_{y \in {\mathbf A} \setminus \{z\}}
		\tau_{\partial {\rm B}(y;r_n)} 
		\leq \tau_\partial 
		\Big)
		\leq \frac{2|{\mathbf A}| r_n}{n} \,,
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 22 of arXiv:2507.08909, 'Annealed almost periodic entropy'] If $n\ge k$, then any positive Borel function $f$ on $\bf{GL}(k,n)$ satisfies
	\begin{multline}
		\int_{\bf{GL}(k,n)} f(T)\,d\vol_{2kn}(T) \\ = v(k,n)\int_{\rmM^\circ_{k+}} (\det Q)^{n-k} \int_{\bf{U}(k,n)} f(VQ^{1/2})\ dm_{\bf{U}(k,n)}(V)\ d\vol_{k^2}(Q),
	\end{multline}
	where
	\begin{equation}
		v(k,n) := \frac{\pi^{nk}}{\pi^{k(k-1)/2}\prod_{j=1}^k(n-j)!}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:pos of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $M$ be a generator of an irreducible Markov chain on a finite state space $\ensuremath{\mathbb{Z}}$ and $\zeta\in \mathcal{P}_+(\ensuremath{\mathbb{Z}})$. Let $\zeta_*=\min_z\zeta(z)$ and  $M_*=\min \{M(z,z')\,:\,z,z'\in \ensuremath{\mathbb{Z}}, \, M(z,z')>0 \}$ be the smallest positive rate in $M$. 
    \begin{enumerate}[label=(\arabic*)]
        \item  We have the lower bound
        \begin{equation} 
            \alpha_{\gPI}(\zeta)
  \geq \frac{ \zeta_* M_* }{|\ensuremath{\mathbb{Z}}|}.
        \end{equation}
        \item Using $\lambda_{\zeta}$ for the spectral gap of $-M^\zeta$ and $\alpha_{\sLSI}(M^\zeta)$ for the standard LSI constant (defined in Lemma~(lem:symGen of the paper)) we have 
        \begin{equation}
            \alpha_{\gLSI}(\zeta)
            \geq 2\alpha_{\sLSI}(M^\zeta)
            \geq \dfrac{\lambda_{\zeta}}{1 + \dfrac12 \log\dfrac{1}{\zeta_*}}
            = \dfrac{ \alpha_{\gPI}(\zeta) }{1 + \dfrac12 \log\dfrac{1}{\zeta_*}}
  \geq \dfrac{ \zeta_* M_* |\ensuremath{\mathbb{Z}}|^{-1} }{1 + \dfrac12 \log\dfrac{1}{\zeta_*}}.
        \end{equation}
    \end{enumerate}

[Lem reversible and tilted MC of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] Let $X$ be a finite state space, $q\ge1$, and $f:X\to\mathbb R_+$.
    Write $\mu^f$ for the $(q,f)$-tilted measure on $X$, that is, $\mu^{q,f}(x) \propto q^{f(x)}$ for all $x\in X$.
    If $p : X^2 \to [0,1]$ is a transition kernel, denote by $\tilde p$ the transition kernel characterized by:
    \begin{align*}
        \forall (x,y)\in X^2,\quad
        \tilde p(x,y) = 
        \left\{
        \begin{array}{ll}
            p(x,y) & \text{if }x\ne y \text{ and }f(y)\ge f(x) \,;\\
            p(x,y)q^{f(y)-f(x)} & \text{if }x\ne y \text{ and }f(y)< f(x) \,;
        \end{array}
        \right.
    \end{align*}
    and $\tilde p(x,x)$ is adjusted so that this defines a transition kernel.
    If $p$ is reversible for the uniform measure on $X$, then $\tilde p$ is reversible for the measure $\mu^{q,f}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 4 of arXiv:2609.03777, '2609.03777'] The map $\bar\delta$ is a derivation of $\ha^{\geq2}_\ast$.  Under the isomorphism \eqref{eq:H-polynomial}, it is given by
\begin{align}
\bar\delta=-\frac12\frac{\partial}{\partial z_2}\,.
\end{align}
In particular, if $w$ has the decomposition \eqref{eq:canonical-decomposition}, then
\begin{align}
\bar\delta(w)
=-\frac12\sum_{j=1}^d
j\,a_j\ast z_2^{\ast(j-1)}\,.
\end{align}

