body:
[Lemma lem:system-rewrite-detailed of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] Let $h_t=e^{-f_t}g_t h_{\rm ref}$, where $g_t>0$ is
$h_{\rm ref}$-Hermitian and $\det g_t=1$.  Then
\begin{equation}
 \sqrt{-1}\Lambda_\omega R_{D_{h_t}}
 =\left(\frac{\beta}{r}+\Delta_\omega^{\mathbb C} f_t\right)\operatorname{Id}_E
  +\sqrt{-1}\Lambda_\omega R^0_{D_{g_t h_{\rm ref}}}.
\end{equation}
Consequently, the Higgs--Demailly system is equivalent to
\begin{equation}
 \left\{
 \begin{aligned}
  \det A_t&=e^{\lambda f_t}a_0,\\
  \sqrt{-1}\Lambda_\omega\left(
    R^0_{h_{\rm ref}}+\bar\partial(g_t^{-1}\partial^{h_{\rm ref}}g_t)
    +[\theta,g_t^{-1}\theta_{h_{\rm ref}}^*g_t]
  \right)&=-e^{f_t}\log g_t,
 \end{aligned}
 \right.
\end{equation}
where
\begin{equation}
 A_t:=\left(\frac{\beta}{r}+\Delta_\omega^{\mathbb C} f_t+(1-t)\alpha\right)\operatorname{Id}_E
      -e^{f_t}\log g_t.
\end{equation}
Under this reformulation, admissibility is equivalent to $A_t>0$.

[Proposition prpcgpart of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] Let $X_i$'s be iid random variables such that $\mathrm{Pr}\{X_1=i\}=\alpha_i$, $i=0$, $1$, $2$, $\dots$ and  $D(t)=\sum_{i=1}^{\hat{M}(t)}X_i$. Then, the pgf $\hat{G}_{D(t)}(u)=\mathbb{E}(u^{D(t)})$ is given by
\begin{equation*}
\hat{G}_{D(t)}(u)=\exp\Big(-t\sum_{j_0=1}^{k_0}\mu_{j_0}\Big(1-\exp\Big(-j_0\sum_{j=1}^{k}\lambda_j\sum_{i=1}^{\infty}\alpha_i^{*(j)}(1-u^i)\Big)\Big)\Big), \ \ |u|\le1,
\end{equation*}
where $\alpha_i^{*(j)}=\displaystyle\sum_{\substack{\sum_{m=1}^{j}r_m=i\\rangle_m\in\mathbb{N}_0}}\alpha_{r_1}\alpha_{r_2}\dots\alpha_{r_j}$.

[Cor 126 (limiting budget constraints) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Analogously  to \eqref{e:budget.constraint.Ising.plus.coarse} and the bounds from Lemmas \ref{l:sp.smooth.budget} and \ref{l:t.smooth.budget}, we have
almost surely 
	\begin{align*}
	&\breve{C}(t)
	- \frac{\bar{W}(t)^2}{\alpha} 
	\le
	\bigg(\frac{\trK L}{\sep}\bigg)^{O(1)}  
	\tep^{1/2}
	+ 3\epsilon^\circ
	\end{align*}
for all $t\in[q_*,1]$. Additionally, with $J\equiv J(p,2\tep,\lambda/2)$ as  defined by \eqref{e:bad.times.J}, we have
	\[
	\Big|\bar{C}(t)-\breve{C}(t)\Big|
	\le \bigg(\frac{\trK L}{\sep}\bigg)^{O(1)} \lambda^{1/2}
	\]
for all $t\in[q_*,1]\setminus J$. 

\begin{proof}
Recall $\TGam^N\equiv(\Tbbb,\Tvvv,\Tuuu)^N$
and $\tGam\equiv(\tbbb,\tvvv,\tuuu)$.
We showed in Lemma~\ref{l:limit.coefs} above that
the coefficients 
$(\Tbbb,\tB,\Tvvv,\tV,\Tuuu,\tU,\trrr,\twww)^N$
from Definition~\ref{d:t.smooth} 
converge pointwise to the coefficients
$(\Tbbb,\tB,\Tvvv,\tV,\Tuuu,\tU,\trrr,\twww)$
from Definition~\ref{d:cts.coeffs}.  Since the coefficients are defined on a compact domain and are uniformly Lipschitz by  Corollary~\ref{c:t.smooth.regularity.N}, the convergence in fact holds uniformly in $y$ for any fixed $t$. Let us abbreviate $\rho_{\vY,N,t} \equiv \rho_{N,t} \equiv \varrho_{N,t}\otimes \varsigma_{N,t}$ and $\rho_{Y,t} \equiv \rho_t \equiv \varrho_t\otimes \varsigma_t$. Then
	\begin{align*}
	\Big|\breve{C}^N(t)
	-\breve{C}(t)\Big|
	&\le \bigg|\int_{\R} \Cost_{2\bar{\lambda}}
	\Big(\TGam^N(t,y)\Big)
	\overline{\varrho_{N,t}*\sphi}(y)
	\,dy
	-\int_{\R} \Cost_{2\bar{\lambda}}
	\Big(\TGam(t,y)\Big)
	\overline{\varrho_{N,t}*\sphi}
	(y)\,dy\bigg| \\
	&\qquad+\bigg|\int_{\R} \Cost_{2\bar{\lambda}}
	\Big(\TGam(t,y)\Big)
	\overline{\varrho_{N,t}*\sphi}
	(y)\,dy
	-\int_{\R} \Cost_{2\bar{\lambda}}
	\Big(\TGam(t,y)\Big)
	\overline{\varrho_t*\sphi}(y)
	\,dy\bigg|\,.
	\end{align*}
On the right-hand side, the first term tends to zero by the convergence result from Lemma~\ref{l:limit.coefs}, making use of the above observation that the convergence holds uniformly over $y$.
For the second term, it follows from Corollary~\ref{c:reg.in.limit}\ref{c:reg.in.limit.a} that
$\TGam$ is a continuous function. It is compactly supported, from which we conclude that $\Cost_{2\bar{\lambda}}\circ\TGam$ is a bounded continuous function. The second term then tends to zero by the weak convergence result from Lemma~\ref{l:occ.wk.conv}. A similar analysis applies to the difference between $\bar{W}(t)^2$ and 
$\bar{W}^N(t)^2$. The first assertion then follows from the corresponding assertion from Lemma~\ref{l:t.smooth.budget}. The bound on the discrepancy between $\bar{C}(t)$ and $\breve{C}(t)$ follows from Corollary~\ref{c:limit.coefs.variants.of.temp.smoothing}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.27098, '\tit'] There exists $c>1$ such that,
  for all $\alpha$ and $\beta\le2^{2^{\alpha}}$,
  \begin{equation}
    \frac{\tau(\alpha)}{c}
    \le
    m(\NNN_{\alpha,\beta})
    \le
    c\tau(\alpha).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2608.13687, 'Multiplicative chaos from random multiplicative functions'] Given a block of primes $B$, enumerate $B = \{p_1< \dots < p_{|B|}\}$. Define  the quantities 
\begin{align*}
  M_B^\alpha &\coloneqq \max_{1 \leq k \leq |B|} \bigg\|\sum_{j=1}^k \phi_{p_j} \alpha_{p_j} p_j^{-ix} \bigg\|_\infty\,,  \qquad M^\alpha \coloneqq \sup_{n\in\N} \max_{B \subset I_n} M_B^\alpha\,,
\end{align*}
and similarly define $M_B^Z$ and $M^Z$ by replacing $\alpha_{p_j}$ with $Z_{p_j}$ above. Then, for all $\lambda >0$, 
\begin{align}
  \E\big[e^{\lambda M^\alpha}\big] < \infty\,, \qquad \E\big[e^{\lambda M^Z}\big] <\infty \,,
\end{align}
and 
\begin{align}
  \lim_{n\to\infty} \max_{B \subset I_n} M_B^\alpha = \lim_{n\to\infty} \max_{B \subset I_n} M_B^Z = 0\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Dn_limit of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] Let $w\in\{a,b\}^*$ be a word of exponent $d$ and let $g\geq 1$. Then for any tuple $\mathbf{z}=(z_0,\dots,z_{g-1})\in \mathbb{C}^g$, we have the convergence in distribution
\begin{align}
		\lim_{L\rightarrow \infty}
		\lim_{n\rightarrow \infty}
		\frac{D^w_n(L,g;\mathbf{z})}{\log L} 
=

		\frac{1}{\mathrm{lcm}(d,g)}\sum_{r=1}^{\mathrm{lcm}(d,g)}z_{(r\textnormal{ mod } g) }\bigl|\{c:c|d, \mathrm{gcd}(c,r))=1\}\bigr|.
	\end{align}

	Moreover, the convergence also holds for the expectation, and in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:middle-energy of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] Let $m=\left\lfloor n/2\right\rfloor$.
Then, for every realization of the first $m$ rows,
\begin{equation}
 S_m\geq\prod_{k=0}^{m-1}(n-2k)\geq m!.
\end{equation}

