[Corollary prop:affine_Levy of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Let $X=(X_t)_{t\in[0,T]}$ be an $S$-valued jump-diffusion with characteristics $(b,a,K)$ and extended generator $\mathcal A$. Assume that $b,a,\lambda\in\mathcal O(S)$ and $K(x,d\xi)=\lambda(x)F(d\xi)$. Let $G\in (0,\infty]^d$ satisfy (equation eqnG of the paper) and set
\begin{align*}
    \mathcal{V}&\subseteq\{h\in H(P_G^d(0)) \colon |h(z)|\leq  g_h(\Im(z)), 
   \text{ for $g_h:\mathbb R\rightarrow\mathbb R_+$ continuous, $z\in \mathbb C$}\},\nonumber \\
 \mathcal{V}^*&:=\{\mathbf{u}\in \mathcal{S}^* \colon h_\mathbf{u}=h|_{{P}^d_{R(S)}(0)},  \ h\in \mathcal{V}\}. \nonumber
\end{align*}
     Then $X$ is an $S$-valued $\mathcal{V}$-affine-holomorphic process and for all $\mathbf{u}\in\mathcal{V}^*$, $$\mathcal{A}\exp(h_\mathbf{u})=\exp(h_\mathbf{u})R(h_{\mathbf{u}})|_S,$$ where $R:\mathcal{V}^*\rightarrow \mathcal{S}^*$ is given by (equation eq:R1nice of the paper)
for $\mathbf{j}(\xi)=\xi\mathbf{1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let the assumptions in Theorem \ref{th-8} hold. Then, for each
$(A,p)\in \mathbb{S}_{d}\times \mathbb{R}^{d}$ and $N>0$, we have
\begin{equation}
\mathbb{\hat{E}}\left[  \frac{1}{2}\langle AS_{n,k}^{X},S_{n,k}^{X}
\rangle+\langle p,S_{n,k}^{Y}\rangle \right]  =k\mathbb{\hat{E}}\left[
\frac{1}{2}\langle AX_{n,1},X_{n,1}\rangle+\langle p,Y_{n,1}\rangle \right]  ,

\end{equation}
\begin{equation}
\mathbb{\tilde{E}}\left[  \frac{1}{2}\langle AS_{n,k}^{X},S_{n,k}^{X}
\rangle+\langle p,S_{n,k}^{Y}\rangle \right]  =k\mathbb{\tilde{E}}\left[
\frac{1}{2}\langle AX_{n,1},X_{n,1}\rangle+\langle p,Y_{n,1}\rangle \right]  ,

\end{equation}
\begin{equation}
\mathbb{\hat{E}}\left[  (|S_{n,k}^{X}|^{2}-N)^{+}+(|S_{n,k}^{Y}|-N)^{+}
\right]  \leq \mathbb{\hat{E}}\left[  \left(  k|X_{n,1}|^{2}-\frac{N}
{2}\right)  ^{+}+(k|Y_{n,1}|-N)^{+}\right]  +\frac{4\left(  k\mathbb{\hat{E}
}\left[  |X_{n,1}|^{2}\right]  \right)  ^{2}}{N}, 
\end{equation}
where $S_{n,k}^{X}=\sum_{i=1}^{k}X_{n,i}$ and $S_{n,k}^{Y}=\sum_{i=1}
^{k}Y_{n,i}$ for $k\leq n$.

