[Definition 23 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $\mathfrak{F}$ be a sub-family of $\mathcal{A}$.
    \begin{enumerate}[label=(\roman*)]
        \item $\Phi$ is said to be \emph{equicontinuous w.r.t $\mathfrak{F}$} at $x\in \X$ if 
		\begin{equation}
			\limsup\limits_{x'\rightarrow x}\sup\limits_{t\ge0}|P_tf(x')-P_tf(x)|=0,\quad \forall\,f\in \mathfrak{F}.
		\end{equation}
        \item $\Phi$ is said to be  \emph{uniformly equicontinuous w.r.t $\mathfrak{F}$} at $x\in \X$ if 
		\begin{equation*}
			\limsup\limits_{x'\rightarrow x}\sup\limits_{t\ge0}\sup_{f
            \in\mathfrak{F}}|P_tf(x')-P_tf(x)|=0.
		\end{equation*} 
    \end{enumerate}
    If $P_t$ is replaced by $Q_t$, then we refer to these properties as  \emph{Cesàro equicontinuous w.r.t.\ $\mathfrak{F}$} and \emph{uniformly Cesàro equicontinuous w.r.t.\ $\mathfrak{F}$} at $x \in \X$. If the property holds for all $x \in \X$, then we replace ``at $x \in \X$" by ``on $\X$" and sometimes omit this phrase for convenience.

[Thm main Thr  of arXiv:2411.01849, 'A tamed-adaptive Milstein scheme for stochastic differential equations with low regularity'] Assume conditions \textbf{A0-A2} hold. 
	   Then, for any $T>0$,  $ l_0 \geq \max\{2,  \frac{4l}{3(1+\alpha)}\},$ $p_0 \ge 4(l + \alpha + 1)$, there exists a positive constant $C_T$ depending on $x_0, \gamma, \eta, \alpha, l, l_0, \lambda, p_0$, and  $T$ such that
	\begin{equation} 
	\underset{0 \le t \le T}{\sup} \mathbb{E} \left[  |\widehat{X}_t - X_t| ^2\right] \le 
	C_T \Delta^{1+\alpha}.
	\end{equation}
	Moreover, assume that $\lambda<0$ and $\gamma <0$, then there exists a positive constant $C$, which depends on $x_0, \gamma, \eta, \alpha, l, l_0, \lambda, p_0$, but is independent of $T$,  such that
	\begin{equation} 
	\underset{t \ge 0}{\sup} \ \mathbb{E} \left[  |\widehat{X}_t - X_t| ^2\right] \le C\Delta^{1+\alpha}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Let $\Lambda>3$. There exist positive constants $c$ and $C_\Lambda$ such that, for all sufficiently large $K$, if $z \in Q_{0,\Lambda r}\setminus Q_{0,3r}$, $\varepsilon>0$, $i \in \{1, \cdots, \varepsilon^{-1}\}$, $\delta>0$ and $\alpha>0$ with $\alpha>2C(K)\delta$, where $C(K)=K^d/p_c^{2dK}$,
\begin{align*}
\mathbb {P}\left[X_{r,i}^{K-\mathrm{line-good}}\le \delta r^2| 0\leftrightarrow Q_{z,r}\right]\le C_{\Lambda}\left[r^{d+1}e^{-c(\log \alpha r^2)^4}+\frac{\alpha}{(i\varepsilon)^2}+ r^2\exp(-\delta r^2/2)\right].
\end{align*}

