body:
[Definition 25 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\alpha, \beta > 0$ be arbitrary. We denote by $\calc_2^{\alpha,\beta}([0,T],W)$ the space of all functions $\Xi : \Delta_T^2 \to W$ such that $\Xi_{t,t} = 0$ for all $t \in [0,T]$ and
\begin{align}
\| \Xi \|_{\alpha,\beta} := \| \Xi \|_{\alpha} + \| \delta \Xi \|_{\beta} < \infty.
\end{align}
Here $\| \Xi \|_{\alpha}$ denotes the H\"older norm
\begin{align}
\| \Xi \|_{\alpha} := \sup_{\genfrac{}{}{0pt}{}{(s,t) \in \Delta_T^2}{s < t}} \frac{|\Xi_{s,t}|}{|t-s|^{\alpha}}.
\end{align}
Furthermore, the function $\delta \Xi : \Delta_T^3 \to W$ is defined as
\begin{align}
\delta \Xi_{s,u,t} := \Xi_{s,t} - \Xi_{s,u} - \Xi_{u,t}, \quad (s,u,t) \in \Delta_T^3,
\end{align}
and its H\"older norm is defined as
\begin{align}
\| \delta \Xi \|_{\beta} := \sup_{\genfrac{}{}{0pt}{}{(s,u,t) \in \Delta_T^3}{s < u < t}} \frac{|\delta \Xi_{s,u,t}|}{|t-s|^{\beta}}.
\end{align}

[Theorem of arXiv:2608.10415, 'Continuous random variables'] The following happen, in relation with separability:
\begin{enumerate}
\item The Hilbert space $H=L^2[-1,1]$ is separable, with orthonormal basis coming by applying Gram-Schmidt to the basis $\{x^k\}_{k\in\mathbb N}$, coming from Weierstrass.

\item In fact, any $H=L^2(\mathbb R,\mu)$, with $d\mu(x)=f(x)dx$, is separable, and the same happens in higher dimensions, for $H=L^2(\mathbb R^N,\mu)$, with $d\mu(x)=f(x)dx$.

\item More generally, given a separable abstract measured space $X$, the associated Hilbert space of square-summable functions $H=L^2(X)$ is separable.
\end{enumerate}

[Theorem eq:fractionalbubbles of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $\gamma\in (0,n/2)$. Then for all $w \in \dot{H}^{\gamma} (\mathbb{R}^n )$ we have
    \begin{equation*}
        \|w \|_{L^{2^{*}}(\mathbb{R}^n )}^2 \leq S(n,\gamma) \|(-\Delta )^{\gamma/2}w \|_{L^{2} (\mathbb{R}^n )}^2 = S(n,\gamma) \int_{\mathbb{R}^n } w (-\Delta )^{\gamma}w  dx,
    \end{equation*}
    where
    \begin{align*}
        S(n,\gamma) = \frac{\Gamma ((n-2\gamma)/2)}{\Gamma ((n+2\gamma)/2)} |\operatorname{vol}(\mathbb{S}^n )|^{-\frac{2\gamma}{n}}.
    \end{align*}
    We have equality if and only if
    \begin{align}
        w(x) = c\left( \frac{\mu}{|x-x_0 |^2 + \mu^2 }  \right)^{\frac{n-2\gamma}{2}} \quad x\in \mathbb{R}^n,
    \end{align}
    for $c\in \mathbb{R}$, $\mu > 0$ and $x_0 \in \mathbb{R}^n$. We denote the set of these functions as $\mathcal{M}_{\mathbb{R}^n} $. (Proof in the paper; no proof environment follows the statement in the TeX.)

