[Proposition 7 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] The following results hold.
			\begin{itemize}
				\item[\upshape{(i)}] 	Let $q \geq 0$. Then, for $\lambda > 0$, $x,b \in [0,a]$ and $u \in [0,\infty)$,
				\begin{equation}
					\begin{aligned}
						&\mathbb{E}_x\Bigl(\int_0^{\infty} \ee^{-q t} 1_{\left\{U_t \in \dd u, \; t < T_{a,U}^{+,\lambda} \right\}} \mathrm{d} t\Bigr) \big/ \dd u \\
						&=  \frac{\lambda \int^\infty_0 \ee^{-\varphi_{q+\lambda}y} w^{(q)}(y+a;u) \dd y \1_{\{u \in [0,a]\}} + \ee^{-\varphi_{q+\lambda}(u-a)}\1_{\{u \in (a,\infty)\}}}{\lambda \int^\infty_0 \ee^{-\varphi_{q+\lambda}y} z^{(q)}(y+a) \dd y} z^{(q)}(x) -  w^{(q)}(x;u) .
					\end{aligned}  
				\end{equation}
				\item[\upshape{(ii)}] Let $q \geq 0$. Then, for $\lambda > 0$, $x,b \in [0,a]$ and $u \in [0,\infty)$,
				\begin{align}
					&\quad \mathbb{E}_x \Bigl(\int_0^{\infty} e^{-q t} 1_{\left\{U_t \in \dd u, t <  T_{a,U}^{-,\lambda} \right\}} \mathrm{d} t\Bigr) \big/ \dd u\notag \\
					&=  \frac{\overline{z}_b^{(q+\lambda,-\lambda)}(x)  + \lambda \int^x_b \W^{(q+\lambda)}(x-y)  \overline{z}_b^{(q+\lambda,-\lambda)}(y) \dd y }{\ee^{\varphi_{q} a} \alpha_2^{(q,q+\lambda)}(b) +  \lambda \int^a_b \Z^{(q+\lambda)}(a-y,\varphi_{q})\overline{z}_b^{(q+\lambda,-\lambda)}(y) \dd y}  \notag \\
					&\quad \times \Bigl( \Bigl[ \ee^{\varphi_{q} a} \alpha_1^{(q,q+\lambda)}(b;u) +  \lambda \int^a_b \Z^{(q+\lambda)}(a-y,\varphi_{q})\overline{w}_b^{(q+\lambda,-\lambda)}(y;u) \dd y  \Bigr] \1_{\{u \in [0,b)\}} \notag \\
					& \quad \quad + \Z^{(q+\lambda)}(a-u,\varphi_{q})\1_{\{u \in [b,\infty)\}} \Bigr) -  \Bigl(
					\overline{w}_b^{(q+\lambda,-\lambda)}(x;u) + \lambda \int^x_b \W^{(q+\lambda)}(x-y)  \overline{w}_b^{(q+\lambda,-\lambda)}(y;u) \dd y \Bigr). 
				\end{align}

				\item[\upshape{(iii)}] For $q, \gamma \geq 0$ and $x,b,u \in [0,a]$,
				\begin{equation}
					\mathbb{E}_x\Bigl(\int_0^{\infty} \ee^{-q t} 1_{\left\{U_t \in \dd u, t < T_{b,U}^{-,\gamma} \wedge \tau_{a,U}^+ \right\}} \mathrm{d} t\Bigr) \big/ \dd u =   \frac{\ovl{z}^{(q+\gamma,-\gamma)}_b(x)}{\ovl{z}^{(q+\gamma,-\gamma)}_b(a)} \ovl{w}_b^{(q+\gamma,-\gamma)}(a;u) -  \ovl{w}_b^{(q+\gamma,-\gamma)}(x;u). 
				\end{equation}


				\item[\upshape{(iv)}] For $q, \gamma \geq 0$ and $x,b,u \in [0,a]$,	\begin{equation}
					\mathbb{E}_x\Bigl(\int_0^{\infty} \ee^{-q t} 1_{\left\{U_t \in \dd u, t < T_{b,U}^{+,\gamma} \wedge \tau_{a,U}^+ \right\}} \mathrm{d} t\Bigr) \big/ \dd u =   \frac{\overline{z}^{(q,\gamma)}_b(x)}{\overline{z}^{(q,\gamma)}_b(a)} \overline{w}_b^{(q,\gamma)}(a;u) -  \overline{w}_b^{(q,\gamma)}(x;u). 
				\end{equation}


				\item[\upshape{(v)}] For  $q, \gamma \geq 0$, $x,b \in [0,a]$, and $u \geq 0$,
				\begin{equation}
					\mathbb{E}_x\Bigl(\int_0^{\infty} \ee^{-q t} 1_{\left\{U_t \in \dd u, t < T_{b,U}^{-,\gamma} \right\}} \mathrm{d} t\Bigr) \big/ \dd u = {\ovl{z}^{(q+\gamma,-\gamma)}_b(x)} \frac{\alpha_1^{(q,q+\gamma)}(b;u)}{\alpha_1^{(q,q+\gamma)}(b)} - \ovl{w}_b^{(q+\gamma,-\gamma)}(x;u), \; \notag 
				\end{equation}
				where $\alpha_1^{(\cdot,\cdot)}$ and $\alpha_2^{(\cdot,\cdot)}$ are defined in Eqs.~\eqref{eq:LimitOfWBar} and \eqref{eq:LimitOfZBar}, respectively. 




				\item[\upshape{(vi)}] For $q,\gamma \geq 0$, $x,b \in [0,a]$, and $u \geq 0$,
				\begin{equation}
					\mathbb{E}_x\Bigl(\int_0^{\infty} \ee^{-q t} 1_{\left\{U_t \in \dd u, t < T_{b,U}^{+,\gamma} \right\}} \mathrm{d} t\Bigr) \big/ \dd u =  {\ovl{z}^{(q,\gamma)}_b(x)}
					\frac{\gamma \int^\infty_0 \ee^{- \varphi_{q+\gamma} y}  w^{(q)}(y+b;u) \dd y}{\gamma \int^\infty_0 \ee^{- \varphi_{q+\gamma} y}  z^{(q)}(y+b) \dd y} - \ovl{w}_b^{(q,\gamma)}(x;u). \; \notag 
				\end{equation}

			\end{itemize}

