[Proposition 105 (Transport equation satisfied by $\partialmodquant{\tanderY^{N-1}}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following identity holds:
	\begin{equation} 
		\Lunit \partialmodquant{\tanderY^{N-1}} =  \frac{1}{2} \vec{G}_{\Lunit \Lunit}\diamond \angLap \tanderY^{N-1} \wavearray +\, ^{(\tanderY^{N-1})}\mathfrak{B},
	\end{equation}
	where:
	\begin{align}
		\begin{split} 
		^{(\tanderY^{N-1})}\mathfrak{B} & = - \tanderY^{N-1} \mathfrak{B} - \tanderY^{N-1} |\upchi|^2   \\
		& \ \ + \frac{1}{2} [\tanderY^{N-1},\vec{G}_{\Lunit \Lunit}] \diamond \angLap \wavearray + \frac{1}{2} \vec{G}_{\Lunit \Lunit} \diamond [ \tanderY^{N-1},\angLap]\wavearray  \\
		& \ \ + [\Lunit,\tanderY^{N-1}] \mytr_{\gtorus}\upchi + [\Lunit,\tanderY^{N-1}] \widetilde{\mathfrak{X}} + L \left\lbrace \partialmodquantinhom{\tanderY^{N-1}} - \tanderY^{N-1}\widetilde{\mathfrak{X}}\right\rbrace, 
		\end{split}
	\end{align}
	where $\mathfrak{B}$ is as in \eqref{E:BINHOMRIC} and $\tanderY^{N-1}$ is the same differential operator every time it appears in \eqref{E:TRANSPORTEQUATIONFORPARTIALMODIFIEDQUANTITY}.

