[Lem 6 of arXiv:2609.02327, 'On the counting function of square-full numbers'] {\cite{RS}}
			For $\frac{1}{2}\leqslant \sigma \leqslant 2$, $T$- sufficiently large, there exists a $T^{\ast}\in [T,T+T^{\frac{1}{3}}]$ such that  the bound
			\begin{equation}
				\log (\zeta(\sigma\pm it))\ll(\log \log (T^{\ast}))^2 \ll (\log \log (T))^2
			\end{equation}
			holds uniformly for $\frac{1}{2}\leqslant \sigma \leqslant 2$ and thus we have
			\begin{equation}
				|\zeta(\sigma\pm i T^{\ast})|^{\pm1}\,\,\ll\exp \left (c (\log \log T)^2 \right)
			\end{equation}
			on the horizondal line  $t=T^{\ast}$ uniformly for $\frac{1}{2}\leqslant \sigma \leqslant 2$. This implies
			\begin{equation}
				\frac{1}{|\zeta(\sigma\pm i T^{\ast})|}\ll \exp \left (c (\log \log T)^2 \right)
			\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 72 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that  $\rU$ is a topological vector space and $\rU^\prime$ its topological dual.
We denote by $\mathscr{L}^+(\rU,\rU^\prime)$ the space of symmetric non-negative definite linear maps $Q:\rU \to \rU^\prime $, i.e. 
for all $ f,\, g \in \rU$  the following two conditions hold, 
\begin{equation*}
\begin{aligned}
    \duality{f}{Q g}{\rU^\prime}{\rU}&= \duality{g}{Q f}{\rU^\prime}{\rU} \mbox{ and } 
    \duality{f}{Q f}{\rU^\prime}{\rU} \geq 0.
\end{aligned}
\end{equation*}

[Lemma Pro:Barlow of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] For every $y\in\mathbb{Z}^d$, there exist finite positive constants $C$ and $s$ depending on $d,\mathfrak{p}$ and a nonnegative $\omega$-measurable random variable $\mathcal{R}(y)$ satisfying 
		\begin{equation}
			\forall r>0,\quad \mathbb{P}_\mathfrak{p}(\mathcal{R}(y)\geqslant r)\leqslant C\exp\left(-\frac{r^s}{C}\right),
		\end{equation} 
		such that for almost every $\omega\in\Omega$ and every $y \in \mathscr{C}_\infty$, when $R>\mathcal{R}(y)$, we have
		\begin{equation}
			\forall T>0,\quad P^\omega_y\Big(\sup_{t\in[0,T]}\vert S_t-y\vert>R\Big)\leqslant C_1\Psi\left(C_2R,T\right),
		\end{equation}
		where $C_1,C_2$ are finite positive constants depending on $d,\mathfrak{p}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

