[Proposition eq:locality_upper_semi_continuity of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:upper_semi_continuity}
    Let $G$ be a transitive graph of polynomial growth with $d \in \mathbf{N}$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega(d_G(x,y)^{-d \alpha})$ for $\alpha \in (0, 2)$. 

    Let $(G_n,J_n)_{n \in \mathbf{N}}$ be a sequence of transitive graphs and kernels converging locally to $(G,J)$ with $\liminf_{n \to \infty} \dim(G_n) \geq 2$.

    Then

    \begin{equation}    

        \limsup_{n \to \infty} 
        \left(
            \beta_c(G_n,J_n)
        \right) \leq \beta_c(G,J). 
    \end{equation}

[Thm first main of arXiv:2412.05950, 'Quantitative particle approximation of nonlinear stochastic Fokker-Planck equations with s'] Assume $(\mathbf{A}^V)$, $(\mathbf{A}^c)$, $(\mathbf{A}^F)$,  and $(\mathbf{A}^K)$, let $T_{max}$ be the maximal existence time for ((SPDE_Ito of the paper)) and fix $T \in \left(0,T_{max}\right)$. In addition, let the dynamics of the particle system be given by ((particles of the paper)) with $\nu=Id$, $\sigma$ independent of the space  and  for any $m \ge 1$,
				\begin{align*}
					\sup_{N \in \mathbb{N}} \Big \| \left\| \rho^N_0 \right\|_{q} \Big \|_{{L^m(\Omega)}} < \infty
				\end{align*}
				with $ d \geq 1$, $q>d$ given by $(\mathbf{A}^K)$ and  $\beta \in \left(0,\frac{1}{2\big[1 + \frac{1}{d} - \frac{1}{q}\big]}\right) $.
				Then

				\begin{align*}
					\Big \| \left\|\rho - \rho^N \right\|_{T,q} \Big \|_{L^m(\Omega)}  &\le C \Big \| \left\|\rho_0 - \rho^N_0 \right\|_{q} \Big \|_{L^m(\Omega)} + C N^{-\varkappa} \, \nonumber 
				\end{align*}
				where
				\begin{align*}
					\varkappa = \min \left(\frac{\beta}{d}\gamma,\frac{1}{2}-\beta\Big(1 + \frac{1 }{d}-\frac{1}{q}\Big) \right)
				\end{align*}
				\noindent and $\rho$ is a  solution of SPDE (equation SPDE_Ito of the paper) with initial condition $\rho_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm potential-zero of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Let $X=(X_t)_{t\geq0}$ be a killed subordinator which is not identically zero. Assume that the Laplace exponent $\Phi(z)$ satisfies the following condition:
\begin{enumerate}[label={\upshape (\Alph*')}]
\item There exist constants $n\in\ensuremath{\mathbb{N}}\cup\{0\}$, $c_0\in(0,+\infty)$, $c_1,\dots,c_n\in\ensuremath{\mathbb{R}}\setminus\{0\}$ and $\beta_0<\beta_1<\dots<\beta_n<+\infty$ with $\beta_0\in(0,1]$, and a locally integrable function $R:(0,+\infty)\to(0,+\infty)$ such that $R(t)$ is non-increasing on $(r,+\infty)$ for some $r>0$, $R(t)=o(t^{-1-\beta_n})$, as $t\to+\infty$, and
\begin{align}
    \frac{d}{dz}
    \bigg(
    \frac{1}{\Phi(z)}
    -
    \sum_{k=0}^n
    \frac{1}{c_k z^{\beta_k}}
    \bigg)
    =
    O(R(|z|)),
    \quad
    \text{as $z\to\infty$ in $\{z\in\ensuremath{\mathbb{C}}\mid {\rm Re}\,z>0\}$}.	
\end{align}
\end{enumerate}
Then the potential measure $U|_{(0,+\infty)}$ restricted over $(0,+\infty)$ admits a continuous density $u(x)$ $(0<x<+\infty)$ which can be estimated as
\begin{align}
   u(x)
   =
   \sum_{k=0}^n
   \frac{x^{-1+\beta_k}}{c_k\Gamma(\beta_k)}+O(\varepsilon_1(x)),
   \quad\text{as $x\to0+$,}
\end{align}
where
\begin{align}
    \varepsilon_1(x)
    =
    x^{-2}R(x^{-1})+x^{-1}\int_{x^{-1}}^{+\infty} R(t)\,dt.	
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 7 (Supercritical cutoff for $X^{(N)}$) of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Under the assumptions of \cref{thm:gaussian-process-cutoff}, $X^{(N)}$ has
  a unique nonzero invariant law $\pi_{A,N}$ for all
  sufficiently large $N$, and
  \begin{equation}
    \lim_{c\to\infty}\liminf_{N\to\infty}
    \norm{P_{A,N}^{n_N(-c)}(x_N,\cdot)-\pi_{A,N}}_{\TV}
    =1,
  \end{equation}
  while
  \begin{equation}
    \lim_{c\to\infty}\limsup_{N\to\infty}
    \norm{P_{A,N}^{n_N(c)}(x_N,\cdot)-\pi_{A,N}}_{\TV}
    =0.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2609.02225, '\textbf{The direct moving plane method for weak solutions of the fractional $p$-Laplacian}'] Let $n\ge2$, $0<s<1$ and $1<p\le2$. Let $u\in\mathcal D^{s,p}(\mathbb R^n)\cap C(\mathbb R^n)$

be a nontrivial nonnegative weak solution of
\begin{equation}
        (-\Delta)^s_pu=u^{p_s^*-1}
        \quad\text{in }\mathbb R^n.
\end{equation}
Then $u$ is radially symmetric and radially nonincreasing about some point $x_0\in \mathbb R^n$. Moreover, there exists a constant \(A_\infty>0\) such that
\begin{equation}
  u(x) = A_\infty |x-x_0|^{-\frac{n-sp}{p-1}} \bigl(1+o(1)\bigr) \quad\text{as }|x|\to\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{G}$ denote the standard horizontal foliation on the neighborhood $N(\mathcal{W}) = [-1,2]^2_{x,z}$ of the square window $\mathcal{W} = [0,1]^2$, i.e., $\mathcal{G}$ is tangent to $\partial_x$. Let $\star \in \{ \sharp, \flat\}$. A \textbf{$\star$~modification of $\mathcal{G}$ in $N(\mathcal{W})$} is a smooth foliation $\mathcal{G}^\star$ on $N(\mathcal{W})$ satisfying
     \begin{itemize}
        \item $T\mathcal{G}^\star$ is either tangent or transverse to $T \mathcal{G}$; it is positively transverse if $\star = \sharp$ and negatively transverse if $\star = \flat$,
         \item $\mathcal{G}^\star$ coincides with $\mathcal{G}$ near $\partial N(\mathcal{W})$,
         \item $\mathcal{G}^\star$ is transverse to $\mathcal{G}$ in a neighborhood of $\mathcal{W}$.
     \end{itemize}

[Theorem theo:existence mixed of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] For all $L\in \mathbb{N}, d \in \mathbb{N}$, and $a>1$ there exists $q\in (0,1)$ and $N_0, N_1 \in \mathbb{N}$  such that site-bond percolation on the hierarchical lattice $\mathbb{H}_L^{d}$ with the kernel $J$ defined by 
	\begin{align*}
	J(e) = \begin{cases}
		 \frac{a L^d \log\log(|e|)}{|e|^{2d}} & \text{ for } |e| \geq N_1\\
		 N_0 & \text{ for } |e| < N_1
		 \end{cases}
	\end{align*}
	satisfies $\mathbb{P}_{q,J} \left( |K_0| = \infty \right)> 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 (\textsf{Convergence of the mollified sign kernels}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] Fix $\wt x\in\R$ and a compact set
  $K\Subset\R\setminus\{\wt x\}$.  For every
  $i,j\in\{0,\dots,n\}$,

  \noi
  \begin{align}

  \begin{aligned}
   & \sup_{u\in K}\bigg|
      \int_{\DN^2}
      \Psi^\eps(\wt x+\wt\ga_i-u-\ga_j)
      Q_{\wt x}^\eps(d\wt\ga)Q_u^\eps(d\ga) \\
     &\qquad\qquad\qquad  -\frac12    \int_{\DN^2}    \sgn(\wt x+\wt\ga_i-u-\ga_j)   Q_{\wt x}(d\wt\ga)Q_u(d\ga)
    \bigg|\xrightarrow{\eps\to 0} 0. 
  \end{aligned}
  \end{align}
  In addition, for every $j\in\{1,\dots,n\}$ and every compact
  $K\subset\R$,
  \begin{align}
    \sup_{u\in K}
    \bigg|    \int_{\DN}\Psi^\eps(u+\ga_j)Q_u^\eps(d\ga)     -\frac12\int_{\DN}\sgn(u+\ga_j)Q_u(d\ga)    \bigg|
    \xrightarrow{\eps\to 0} 0. 
  \end{align}

[Definition def:tridwn of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Under the setting of Definition~(def:vee of the paper), we define $\mathbb{F} 
ewtriangledown \mathbb{G}$, $
ewbigtriangledown_{i \in I} \mathbb{F}^i$ and $\mathbb{F} 
ewtriangledown \mathcal{G}$ as the right-continuous regularization of $\mathbb{F} \lor \mathbb{G}$, $ igvee_{i \in I} \mathbb{F}^i$ and $\mathbb{F} \vee \mathcal{G}$, respectively.

[Lem ratesofconv of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] There exists a linear functional $\nu_m$ on $\mathcal{P}$ for every $m\in\mathbb{Z}_+$ 
such that for every $q\in\mathbb{N}$ and $h\in \mathcal{P}_q$
\begin{equation}

	|\nu_m(h)| \le \frac{(Cqq_0)^{2m}}{m!} 
	\sobnorm{h}{0}{[-K, K]},
\end{equation}
and such that if in addition $q \leq \frac{N}{Cq_0}$, we have
\begin{equation}

	\left| \mathbf{E}[\mathop{\textnormal{tr}} h(X^N)]- \sum_{k=0}^{m-1} \frac{\nu_k(h)}{N^k} 
	\right| \leq \frac{(Cqq_0)^{2m}}{m! N^{m}} 
	\sobnorm{h}{0}{[-K, K]}.
\end{equation}
Here $C$ is a universal constant and $K:=(Cr)^{q_0}\|X_{\rm F}\|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Maintheorem 2 of arXiv:2608.28964, '2608.28964'] For the equation given by \eqref{eq NS},\eqref{eq xi} with $\xi=\eta$ given by \eqref{eq eta}, and any $B_0>0$, there exists an integer $N=N(B_0)\in\N^+$ such that the following holds. If $\{b_j\}_{j\in\N^+}$ satisfies
	\begin{equation*}
	\sum_{j\in\N^+}b_j^2\leq B_0\quad\text{and}\quad b_j\neq0\quad\text{for }1\leq j\leq N,
	\end{equation*}
    then the Markov process associated to the coupled system \eqref{eq NS},\eqref{eq eta} admits a unique invariant measure $\mu_*$ on $\mathcal X$.  Moreover, there exist constants $C,\alpha,\gamma>0$ such that
	\begin{equation}
	\left|\E\varphi(U(t,U_0))-\int_{\mathcal X}\varphi d\mu_*\right|\leq Ce^{-\alpha t}\exp\left(C\gamma\|U_0\|_{\mathcal X}^2\right)\|\varphi\|_{\mathcal X,\gamma}
	\end{equation}
    for any $\varphi\in\mathcal{O}_{\mathcal X,\gamma}$, $U_0\in \mathcal X$ and $t\geq0$, where
	\begin{equation*}
	\mathcal{O}_{\mathcal X,\gamma}=\left\{\varphi\in C^1(\mathcal X):\|\varphi\|_{\mathcal X,\gamma}<\infty\right\},\quad\|\varphi\|_{\mathcal X,\gamma}=\sup_{U_0\in \mathcal X}\left(e^{-\gamma\|U_0\|_{\mathcal X}^2}(|\varphi(U_0)|+\|\nabla\varphi(U_0)\|_{\mathcal X})\right).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn of arXiv:2605.04860, 'Branching Brownian motion with rank-based selection and reaction-diffusion equations'] Consider the PDE $U_t = \frac12 U_{xx} + G(U)$ with initial condition $U(x,0)=U_0(x)$ such that $U_0(x)\to 1$ as $x\to-\infty$ and $U_0(x)\to 0$ as $x\to\infty$. We say that the solution $U(x,t)$ \textit{spreads up to (the value) $u^\star$ at speed $c^\star$} if:
    \begin{enumerate}
        \item $\lim_{t\to\infty}\inf_{x\leq ct} U(x,t)\geq u^\star$ for all $c<c^\star$,
        \item $\lim_{t\to\infty}\sup_{x\geq ct} U(x,t)=0$ for all $c>c^\star$.
    \end{enumerate}
    More generally, we may say that the solution \textit{spreads up to (the value) $u^\star$ with speed at least $c^\star$} if just condition 1. holds.

[Lemma Eq:weakconvergence of arXiv:2606.03079, 'Mean Field Limits for Stochastic, Underdamped Reactive Langevin Dynamics Models'] (Weak Convergence). For any $\Phi \in \mathcal{S}$ and $0 \leq r_{1} \leq r_{2} \cdots \leq r_{W}=s<t<T$ and $\{\psi_{w}\}_{w=1}^{W} \subset$ $B\left(\otimes_{j=1}^{J} M_{F}(\mathbb{R}^{d}\times \mathbb{R}^{d})\right)$, we have that
\begin{equation}
\lim_{\zeta \rightarrow 0} \mathbb{E}\left[\left\{\Phi(\bm{\mu}_{t}^{\zeta})-\Phi(\bm{\mu}_{s}^{\zeta})-\int_{s}^{t}(\mathcal{A} \Phi)(\bm{\mu}_{r}^{\zeta}) d r\right\} \prod_{w=1}^{W} \psi_{w}\left(\bm{\mu}_{r_{w}}^{\zeta}\right)\right]=0.
\end{equation}

