[Prop 9 of arXiv:2605.31568, 'Lipschitz continuity of the time constant for continuum percolation'] \begin{align*}
    \E\left[ \sum_{q \in X_\lam \cap R(\widetilde{D})} \Delta_q f(X_\lam)\right]  
    &\le \E \left[\sum_{\substack{q \in \widetilde{\pi} 
    }} \1 \left\{\substack{G_\lam \setminus \{q\} \\ p(q) \leftrightarrow s(q)}\right\} d_{G_\lam \setminus \{q\}}(p(q),s(q)) \right]
    +\lam^2 o(\|x\|),
    \end{align*}
    where here $p(q)$ represents the vertex of $\widetilde{\pi}$
    preceding $q$ and $s(q)$ represents the vertex of $\widetilde{\pi}$
    following $q$.

[Lemma 4 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $z,w\in\C$ and $\varepsilon, \varepsilon'\in (0,1]$,
\begin{displaymath}
G_{D,\varepsilon,\varepsilon'}(z,w)
\leq\Big(\dfrac{1}{2\pi}\log (\varepsilon^{-1}) + c\Big)^{1/2}
\Big(\dfrac{1}{2\pi}\log (\varepsilon'^{-1}) + c\Big)^{1/2},
\end{displaymath}
where
\begin{displaymath}
c = \dfrac{1}{2\pi}
\int_{\C^{2}} 
\log (\vert y-x\vert^{-1})
\rho(x)\rho(y)
\,d^{2}x\,d^{2}y
+
\dfrac{1}{2\pi}
0\vee \log(\diam(D))
< +\infty.
\end{displaymath}
Moreover, for every $\varepsilon, \varepsilon'\in (0,1]$,
and $z,w\in\C$ such that $\vert w-z\vert\geq 2\,\varepsilon\vee\varepsilon'$,
\begin{displaymath}
G_{D,\varepsilon,\varepsilon'}(z,w)
\leq
\dfrac{1}{2\pi}
\Big(
0\vee\log \dfrac{2}{\vert w-z\vert}
+
0\vee\log(\diam(D))
\Big).
\end{displaymath}

