[Lemma xnuni of arXiv:2411.05204, '\Large\bf Sample Path Properties of the Fractional Wiener--Weierstrass Bridge'] If $H<K$ we define $ X ^{(n)}$ as in ((Xn of the paper)), and $ \varepsilon _n=\alpha^n,\ N_n=nH,\ \delta_n=b^{-nH}$.\footnote{Without loss of generality, we assume $N_n$ is always an integer, by using instead $\lfloor nH\rfloor$ or $\lceil nH\rceil$. } Then we have
\begin{align}
\sum_{n=1}^\infty{\mathbb P}\Bigg(\sup_{\substack{t,s\in[0,1]\\ |t-s|< \varepsilon _n/\delta_n}}\big|X^{(N_n)}(t)-X^{(N_n)}(s)\big|\leq \frac{1}{L}\left(\frac{ \varepsilon _n}{\delta_n}\right)^{H}\sqrt{-\log ( \varepsilon _n/\delta_n)}\Bigg)<\infty.\end{align}

[Definition def:IVGFFwithpotentialV of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an integer $L \in \ensuremath{\mathbb{N}}$ and an inverse temperature $\beta \geq 0$, we define the integer-valued height function with potential $V$ to be the probability distribution on the set $\Omega_{\Lambda_L}^\ensuremath{\mathbb{Z}}$ given by the identity

\begin{equation} 
    \mu_{\Lambda_L , \beta}^{\ensuremath{\mathbb{Z}}-V} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta}^{\ensuremath{\mathbb{Z}}-V}} \exp \left( - \sum_{x \sim y}  V \left( \frac{ \varphi(x) - \varphi(y)}{\sqrt{\beta}} \right)\right).
\end{equation}
We denote by $\mathrm{Var}_{L , \beta}^{\ensuremath{\mathbb{Z}}-V}$ the variance with respect to the measure $\mu_{L , \beta}^{\ensuremath{\mathbb{Z}}-V}$.

[Corollary cor: KR_crit of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Let  $\EuScript{V}\subset{\mathbb R}^m$  an open set.  Suppose that  $\Phi: \EuScript{V}\to {\mathbb R}$ a Gaussian random function that is $\mathrm{a.s.}$ $C^2$ and such that  the Gaussian vector $\nabla \Phi({\boldsymbol{v}})$ is nondegenerate  for any ${\boldsymbol{v}}\in \EuScript{V}$. We denote by $p_{\nabla \Phi(v)}$ is probability \emph{density}.  The following hold.

  \begin{enumerate}

  \item  The random function  $\Phi$ is $\mathrm{a.s.}$ Morse

  \item We set
  \begin{equation}
  \mathfrak{C}[-,\Phi]:=\sum_{\nabla F({\boldsymbol{v}})=0}\delta_v
  \end{equation}
  Then $\mathfrak{C}[-,\Phi]$ is a random locally finite measure on $\mathscr{V}$  in the sense of [DaVere2] or [Kalle_RM].   For any  nonnegative measurable function ${\varphi}:\mathscr{V}\to [0,\infty)$ we set
  \[
  \mathfrak{C}[{\varphi},\phi]=\int {\varphi}(v)\mathfrak{C}[dv,\Phi]=\sum_{\nabla \Phi(v)=0}{\varphi}(v).
  \]
  \item  For any box $B\subset \mathscr{V}$,   the function $\Phi$ $\mathrm{a.s.}$ has no critical points on $\partial B$ and
  \begin{equation}
  {\mathbb E}\big[\, \mathfrak{C}^\Phi[\boldsymbol{I}_B{\varphi}]\,\big]=\int_B{\mathbb E}\big[\, \vert\det \Hess_\Phi({\boldsymbol{v}})\vert \, \,\big\vert\,\nabla \Phi({\boldsymbol{v}})=0\,\big] p_{\nabla \Phi(v)}(0) {\varphi}({\boldsymbol{v}})d{\boldsymbol{v}}.
\end{equation}
\end{enumerate}
The quantity 
\begin{equation}
\rho_\Phi:={\mathbb E}\big[\, \vert\det \Hess_\Phi({\boldsymbol{v}})\vert \, \,\big\vert\,\nabla \Phi({\boldsymbol{v}})=0\,\big] p_{\nabla F(v)}(0)
\end{equation} 
is called the  Kac-Rice (or KR) density of $\Phi$.
 \nobreak\hfill\penalty250 \hbox{}\nobreak\hfill$\rlap{$\sqcap$}\sqcup$\vskip\aline (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem mom-est of arXiv:2411.06974, '{\bf Distribution dependent SDEs with multiplicative fractional noise}'] Let $\frac 1 {2}<\beta<H$. Assume that $\widetilde{b}$ is of linear growth:
$$|\widetilde{b}(r,x)|\leq K_{\widetilde{b}}+L_{\widetilde{b}}(1+|x|),\ \ r\in[S,T],\ \ x\in\mathbb R^d,$$
and $\widetilde{\sigma}$ is bounded  by a positive constant $M_{\widetilde{\sigma}}$ and
\begin{align*}
\|\widetilde{\sigma}(r,x)-\widetilde{\sigma}(s,y)\|\leq K_{\widetilde{\sigma}}|r-s|^{\gamma_0}+L_{\widetilde{\sigma}}|x-y|,\ \ r,s\in[S,T], \ \ x,y\in\mathbb R^d
\end{align*}
for some $\gamma_0 >1-\beta$, where $K_{\widetilde{b}},L_{\widetilde b},K_{\widetilde{\sigma}},L_{\widetilde{\sigma}}$ are all positive constants.
Then for the solution $\widetilde{X}$ of equation (equation Lemma 3.2-0 of the paper) and any $p\geq 1$, there holds
\begin{align*}
&\left[\mathbb E\left(\|\widetilde{X}\|_{S,T,\infty}+\|\widetilde{X}\|_{S,T,\beta}\right)^p\right]^{\frac 1 p}\cr
\leq& C_1(T-S,H,\beta,\gamma_0,p)\left(1+K_{\widetilde{b}}+K_{\widetilde{\sigma}} \right)+ C_2(T-S,H,\beta,\gamma_0,p)\left(\mathbb E|\widetilde{X}(S)|^p\right)^{\frac 1 p},
\end{align*}
where $C_i(T-S,H,\beta,\gamma_0,p),i=1,2$ are two positive constants which are independent of $S,T$, $K_{\widetilde b},K_{\widetilde \sigma}$, $\widetilde X(S)$ and decreasing as $T-S$ decreases, and satisfy
\begin{align*}
\lim_{T-S\rightarrow 0^+}C_1(T-S,H,\beta,\gamma_0,p)=0\ \ \ \mathrm{and}\ \ \ \lim_{T-S\rightarrow 0^+}C_2(T-S,H,\beta,\gamma_0,p)=1.
\end{align*}

