[Lem 11 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] Let $f\in C_{b}(\Sigma_{R})$ be given fixed.
Then one has 
\begin{equation}
\lim_{t\rightarrow\infty}\frac{1}{\beta(t)}\Lambda_{t}^{(\rho,\sigma)}(\beta(t)f)=\lambda_{0}^{{\rm eu};R}-\lambda_{0}^{{\rm eu};f,R}=:\Lambda(f),
\end{equation}
where the convergence holds uniformly for $\rho\leqslant R-\varepsilon$.

[Definition 5 of arXiv:2506.18558, '2506.18558'] A class of measures $\{\nu^x_t\}_{t\in\RR}$ is called an evolution system of measures for $\{P^x_{s,t}\}_{t\ge s}$, if
\begin{align}
\int_{\RR^m}P^x_{s,t} \varphi(y)\nu^x_s(dy)=\int_{\RR^m}\varphi(y)\nu^x_t(dy),\quad s\le  t,\varphi\in C_b(\RR^m).
\end{align}

[Definition def:wishart_mixing of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Given  a sequence of positive integers  \(t_N\),   the bipartite Markov chain with state space \(S=[M]\sqcup[N]\) and transition matrix  $P_S$ given in (equation equ:transition_matrix of the paper)
is said to be   \emph{Short-to-Long Mixing} at time \(t_N\),  if its \(n\)-step transition probabilities \(p_n(x,y)\) obey:

\begin{enumerate}[leftmargin=*,label=(D\arabic*)]
  \item  \textbf{(Short-time average mixing)}  
    There exists \(\gamma\ge1\) and \(N_0>0\) so that for all \(N\ge N_0\) and all \(x,y\in S\),
    \begin{equation}
      \frac1{t_N}\sum_{n=1}^{t_N}p_n(x,y)
      \;\le\;
      \begin{cases}
        \displaystyle \frac{\gamma}{N}, & y\in[N],\\[6pt]
        \displaystyle \frac{\gamma}{M}, & y\in[M].
      \end{cases}
    \end{equation}

  \item  \textbf{(Long-time uniform mixing)}  
    There exists \(\delta\in(0,0.1)\) such that for all \(n\ge t_N\) and all \(x,y\in S\),
    \begin{equation}
      \bigl|p_n(x,y)+p_{n+1}(x,y)-\tfrac1{N}\bigr|\;\le\;\frac{\delta}{N}
      \quad\text{if }y\in[N],
      \quad
      \bigl|p_n(x,y)+p_{n+1}(x,y)-\tfrac1{M}\bigr|\;\le\;\frac{\delta}{M}
      \quad\text{if }y\in[M].
    \end{equation}
\end{enumerate}
The additional assumption that  $\delta = \delta_N \to 0$  may be imposed   when necessary.

[Lemma 2603291635 of arXiv:2609.02626, 'Comparison principles and symmetry for subquadratic fractional $p$-Laplacian equations'] Assume that $N\ge 1$, $s\in (0, 1)$, $p>1$ and $\Omega\subset \mathbb{R}^N$ is an open set. Then 
\begin{equation}
\lambda_{1, s, p}(\Omega)\ge \frac{2\omega_{N-1}^{1+\frac{sp}{N}}}{spN^{\frac{sp}{N}}}|\Omega|^{-\frac{sp}{N}}.
\end{equation}

