[Cor 18 of arXiv:2507.08909, 'Annealed almost periodic entropy'] In the setting of Definition~\ref{dfn:cond-log-det-ent}, if $E,F,G$ are pairwise disjoint finite subsets of $S$, then
\begin{align}
\rmH_Q(E\cup F\mid G) &= \rmH_Q(E\mid G) + \rmH_Q(F\mid E\cup G) \\
&\le \rmH_Q(E\mid G) + \rmH_Q(F\mid G) 
\end{align}
(including the possibility that any of these expressions could be $-\infty$), and
\begin{equation}
\rmH_Q(E\mid G) - \rmI_Q(E\,;\,F\mid G) = \rmH_Q(E\mid F\cup G)
\end{equation}
(including the possibility of $-\infty$ on either side).

[Lemma propI of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] The following holds:
\begin{enumerate}[(i)]
    \item The function $I_e(\lambda)$ is finite for every $\lambda\in \mathbb{R}$, and $I_e$ is strictly convex and differentiable. Moreover, for every $\lambda\in \mathbb{R}$, there exists $\lambda^*\in \mathbb{R}$ such that
    \begin{equation*}
        I_e(\lambda)=\sup_{\eta \in \mathbb{R}} \{ \eta \lambda - [\gamma((\lambda_e+\eta)e)-\gamma(\zeta_e)]\}= \lambda \lambda^* - [\gamma((\lambda_e+\lambda^*)e)-\gamma(\zeta_e)]. 
    \end{equation*}
    \item For any $\lambda\in \mathbb{R}$, $I_e(\lambda)\geq 0$ and $I_e(\lambda)=0$ if and only if $\lambda=c^*(e)$, where $c^{*}(e)$ is defined in (equation eq:prelimCriticalSpeed of the paper). Furthermore, $I_e$ is strictly decreasing on the interval $(-\infty,c^*(e))$ and strictly increasing on the interval $(c^*(e),+\infty)$.
    \item For any constant $\beta>0$, there exists $\delta=\delta(\beta)\in (0,1)$ such that for any $\kappa\in (0,\delta)$, 
    \begin{equation*}
        I_e(c^*(e) - \kappa ) < \kappa \beta\quad\text{and}\quad I_e(c^*(e) + \kappa ) < \kappa \beta. 
    \end{equation*}
\end{enumerate}

[Cor Finite Dimensional Distributions of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For any fixed $j \in \mathbb{N}$ and times $t_1,\dots ,t_j \in [0,T]$, we have
\begin{equation*}
    \begin{split}
        (\Tilde{E}_n(t_1),\dots,\Tilde{E}_n(t_j)) \to (E(t_1),\dots ,E(t_j)),
    \end{split}
\end{equation*}
in distribution. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2511.19308, 'Universal scaling limits at the spectral singularity of structured random matrices'] Let $H$ be a $2N \times 2N$ block matrix as in \eqref{eq: matrix model definition} with
    \[
        S = \begin{pmatrix}
            N^{-1} \sigma_{11} & 1 \\
            1 & 0 \\
        \end{pmatrix}, \qquad
        \text{for }\; \sigma_{11} \in [0, \infty).
    \]
    Let $\zeta \in \C$ with $\Im(\zeta) > 0$, then
    \begin{eqsplit}
        \lim_{N \to \infty} \frac{1}{N} \E\s*{\Tr\p*{\frac{1}{H - N^{-1} \zeta}}}
        & = \frac{\ii}{2} \sum_{n, r \in \Z} c_{n, r} \int_0^{\infty} \dd v \, \ee^{-\p*{\frac{1}{2} \sigma_{11} v^2 - \ii \zeta (v + \frac{1}{v})}} v^n
        \\
        & \qquad
            \times \sum_{k, l = 0}^{\infty} \frac{(\sigma_{11} / 2)^k (-\ii \zeta)^{2k + 2l + 1 + r}}{k! \, l! \, (2 k + l + 1 + r)!},
    \end{eqsplit}
    where the only non-zero coefficients $c_{n, r}$ are
    \begin{align*}
        & c_{-3, -1} = c_{-2, -2} = c_{-2, 0} = c_{0, -2} = c_{0, 0} = -\ii \zeta, \qquad
        c_{-1, -1} = -1 - 2 \ii \zeta, \qquad
        c_{1, -1} = -1 - \ii \zeta, \\
        & c_{-2, 1} = c_{0, -1} = c_{0, 1} = c_{2, -1} = \sigma_{11}, \qquad
        c_{-1, 0} = c_{1, 0} = 2 \sigma_{11}.
    \end{align*}

    For the $K = 3$ case, let $H$ be a $3N \times 3N$ block matrix as in \eqref{eq: matrix model definition} with
    \[
        S = \begin{pmatrix}
            0 & N^{-1} \sigma_{12} & 1 \\
            N^{-1} \sigma_{12} & 1 & 0 \\
            1 & 0 & 0
        \end{pmatrix}, \qquad
        \text{for }\; \sigma_{12} \in [0, \infty).
    \]
    Let $\zeta \in \C$ with $\Im(\zeta) > 0$, then
    \begin{equation}
    \begin{split}
        \lim_{N \to \infty} \frac{1}{N} \E\s*{\Tr\p*{\frac{1}{H - N^{-1} \zeta}}}
        & = 2 \ii \Big[ (\sigma_{12} - 2 \ii \zeta) \p1{K_0(x) I_0(x) + K_1(x) I_1(x)}
        \\
        & \hphantom{= 2 \ii \Big[}
            + \sqrt{-\ii \zeta (\sigma_{12} - \ii \zeta)} \p1{K_1(x) I_0(x) + K_0(x) I_1(x)} \Big],
    \end{split}
    \end{equation}
    where $x := 2 \sqrt{-\ii \zeta (\sigma_{12} - \ii \zeta)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

