body:
[Lemma eq:biskup_iterative_renormalisation of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:second_iterative_renormalisation}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$ and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega (d_G(x,y)^{-d \alpha})$ with $\alpha \in (0,2)$.

    Let $\beta > \beta_c$, and let $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ be the renormalisation scheme in \thref{def:renorm_scheme_2}.

    For $\delta \in (\max(0, 1-\alpha),2-\alpha)$ and $c > 0$, for  $r_0$ sufficiently large it holds for any tile $\Tile{i}{j}$ that 

    \begin{equation}

        \mathbf{P}_{\beta}
        (
            \Tile{i}{j} \text{ is bad}
        )
        \leq 
        \exp
        (
            -
            c
            (r_i/r_0)^{d(2 - \alpha - \delta)}
        ).
    \end{equation}

[Lemma 7 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] For any vertices $u$ and $v$, the Green function $G^\kappa(u,v)$ is finite if and only if $\kappa \geq \kappa_c$. Furthermore, for $\kappa\geq \kappa_c$, 
\begin{equation} 
G^\kappa(u,v) = \frac{\tau_\kappa^{d(u,v)}}{1-\tau_\kappa (1+ \kappa)^{-1}}.
\end{equation}

[Proposition 26 of arXiv:2609.01485, 'On the Ramification of Quadratic Fields where the Torsion of a Rational Elliptic Curve Gro'] Let $E/\mathbb{Q}$ be a rational elliptic curve such that there exists $P\in E(K)[7]\setminus E(\mathbb{Q})$, where $K/\mathbb{Q}$ is a quadratic field. Suppose that $E$ has additive reduction at $7$. Then the following are equivalent:
    \begin{itemize}
        \item $7 \mid d_K$, where $d_K$ is the discriminant of $K$.
        \item The Kodaira symbol of $E$ at $7$ is not $II$.
    \end{itemize}
    Moreover, if $7 \mid d_K$, then $E$ has Kodaira symbol $IV^*$.

[Lem setup1 of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Let $0 \leq \alpha,\beta \leq 1-\eps$ be real parameters and let $k$ be a nonnegative integer. Then $\abs{\sete[e^{if}]} = n^{-\omega_{\lambda,\ell,\eps}(1)}$, provided that
\begin{cond}
	\item  For all $H$ with $k+2$ vertices, $n^{k+2}\Delta_H^2 \leq n^{2+k\beta-\eps}$;
    \item  There is some connected $H$ with $k + 2$ vertices such that $n^{2\alpha+k\beta+\eps} \leq n^{k+2}\Delta_H^2$;
    \item  For every $H$ with greater than $k+2$ vertices 
    we have $n^{v(H)}\Delta_H^2 \leq n^{2\alpha+k\beta - \eps}$.
\end{cond}

[Proposition lem:CLE-shrink of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] Suppose $x_1<x_2<x_3<x_4$, and $\Gamma$ is a $\CLE_\kappa$ configuration on $\mathbbm{H}$. We have
\begin{itemize}
    \item Let $E$ be the event that there exists a loop $\ell\in\Gamma$ such that $\ell\cap I(x_1,r_1)\neq\emptyset$, $\ell\cap B(x_i,r_i)\neq\emptyset$ for $i=2,3$, and $\ell\cap I(x_4,r_4)\neq\emptyset$. Then $\prod_{i=1}^4 r_i^{-h}\mathbbm{P}[E]$ converges to $CG^{(1234)}(x_1,x_2,x_3,x_4)$ as taking first $r_1\to0$, then $r_2,r_3\to0$, finally $r_4\to0$.
    \item Let $F$ be the event that there exist two loops $\ell,\ell'\in\Gamma$ such that $\ell$ intersects $I(x_1,r_1)$ and $B(x_2,r_2)$, while $\ell'$ intersects $I(x_4,r_4)$ and $B(x_3,r_3)$. Then $\prod_{i=1}^4 r_i^{-h}\mathbbm{P}[F]$ converges to $C'G^{(12)(34)}(x_1,x_2,x_3,x_4)$ as taking first $r_1\to0$, then $r_2\to0$, then $r_3\to0$, finally $r_4\to0$.
\end{itemize}
Here $C$ and $C'$ are two constants in $(0,\infty)$.

[Definition def:poly_growth of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] We say that $G$ has \emph{polynomial growth}\footnote{Note that, since the graph is connected, the definition of polynomial growth is independent of the choice of the center vertex: if there is some constant $C = C_{\boldsymbol{0}}$ such that $g_{\boldsymbol{0}}(n) \le C n^d$, then, for any vertex $x$, there exist $C_x$ such that $g_x(n) \le C_x n^d$.} if there exist $C$ and $d$ such that for all $n$
\begin{align*}
g(n) \le C n^d.
\end{align*}

[Definition 2 (Model) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] A (random) \emph{model} is a triple $(\Pi,\Pi^-,\Gamma)$, 
where $\Pi_x,\Pi^-_x\colon\mathcal{S}(\RR^{1+d})\to\RR[\![z_k,z_\n]\!]$ are a family of (random) linear maps indexed by $x\in\RR^{1+d}$ 
and $\Gamma_{xy}\in\mathrm{End}(\RR[\![z_k,z_\n]\!])$ is a family of (random) endomorphisms indexed by $x,y\in\RR^{1+d}$ such that the following holds (almost surely).

For all $\beta$ and all $\kappa>0$ 

\begin{align}
\|\Pi\|_\beta &\coloneqq 
\sup_{x\in\RR^{1+d}} \sup_{0<t<1} (\sqrt[4]{t})^{-|\beta|+\kappa} (1+|x|)^{-2\kappa}
|\Pi_{x\beta t}(x)| < \infty \, , \\
\|\Pi^-\|_\beta &\coloneqq 
\sup_{x\in\RR^{1+d}} \sup_{0<t<1} (\sqrt[4]{t})^{-|\beta|+2+\kappa} (1+|x|)^{-2\kappa}
|\Pi^-_{x\beta t}(x)| < \infty \, , \\
\|\Gamma\|_\beta &\coloneqq
\sup_\gamma \sup_{x\in\RR^{1+d}} \sup_{x'\neq y'\in B_1(x)} |x'-y'|^{-|\beta|+|\gamma|+\kappa} (1+|x|)^{-2\kappa} |(\Gamma_{x'y'})_\beta^\gamma| < \infty \, ,
\end{align}

where $(\Gamma_{xy})_\beta^\gamma\coloneqq(\Gamma_{xy}z^\gamma)_\beta$.
The map $\Gamma$ is related to $\Pi$ and $\Pi^-$ by

\begin{equation}
\Gamma_{xy}\Pi_y = \Pi_x \, , \quad
(\Gamma_{xy}\Pi^-_y)_\beta = \Pi^-_{x\beta} + \textnormal{ polynomial of degree }\leq|\beta|-2 \, , 
\end{equation}

it is transitive and triangular with respect to the homogeneity in the sense of
\begin{equation}
\Gamma_{xy}\Gamma_{yz} = \Gamma_{xz} \, , \quad
(\Gamma_{xy}-\mathrm{id})_\beta^\gamma \neq 0 \implies |\gamma|<|\beta| \, ,
\end{equation}

and satisfies\footnote{with the understanding that $\binom{\n}{\m}$ vanishes if the componentwise $\m\leq\n$ is violated}

\begin{equation}
\Gamma_{xy}(\pi_1\pi_2) = (\Gamma_{xy}\pi_1)(\Gamma_{xy}\pi_2) \, , \quad
\Gamma_{xy} z_k = z_k \, , \quad
(\Gamma_{xy})_{\delta_\n}^\gamma = \sum_\m \tbinom{\n}{\m} (y-x)^{\n-\m} 1_{\gamma=\delta_\m} \, .
\end{equation}

For purely polynomial multiindices $\delta_\n$ and for multiindices of the form
$\beta=\delta_{\kk}+\delta_{\n_1}+\dots+\delta_{\n_{\kk}}$ it holds

\begin{equation}
\Pi_{x\delta_\n}=(\cdot-x)^\n \, , \quad
\Pi^-_{x\delta_\n} = 0 \, , \quad
\Pi_{x\beta}=0 \, , \quad
\Pi^-_{x\beta} = \tfrac{\kk!}{\prod_\n \beta(\n)!} (\cdot-x)^{\n_1+\dots+\n_{\kk}} \, .
\end{equation}

Finally, for $\beta$ not populated and $\gamma$ populated, 

\begin{equation}
\Pi_{x\beta} = 0 \, , \quad
\Pi^-_{x\beta} = 0 \, , \quad
(\Gamma_{xy})_\beta^\gamma = 0 \, .
\end{equation}

[Prop Prop_ThickenedSpaceOfZ2ZHarmonicSpinors_Submanifold+Submersion of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $({\mathbf{p}}_0,[{\mathfrak l}_0];\Phi_0) \in \mathbf{Harm}^*$
  there are
  an open subset $\mathscr{U} \subseteq {\mathbf{E}}_{00}^*$ with $({\mathbf{p}}_0,[{\mathfrak l}_0];\Phi_0) \in \mathscr{U}$ and
  a finite rank subbundle $\mathrm{Ob} \subseteq f^*{\mathbf{F}}_{00}|_\mathscr{U}$
  such that:
  \begin{enumerate}
  \item

    $\mathscr{V} \coloneq \mathrm{pr}_{\mathbf{Dir}}(\mathscr{U}) \subseteq \mathbf{Dir}$ is open,
  \item

    the local thickening
    \begin{equation*}
      \mathbf{Harm}^{\mathbf{t}}
      \coloneq
      \set[\big]{
        ({\mathbf{p}},[{\mathfrak l}];\Phi) \in \mathscr{U}
        :
        D_{\mathbf{p}}^{\mathfrak l} \Phi \in \mathrm{Ob}
      }
      \subseteq \mathscr{U}
    \end{equation*}
    is a tame Fréchet manifold, and
  \item

    the projection map $\mathrm{pr}_\mathscr{V} \mskip0.5mu\colon\thinspace \mathbf{Harm}^{\mathbf{t}} \to \mathscr{V}$ is a uniform submersion.
  \end{enumerate}

