[Corollary 7 (Simplex cap) of arXiv:2607.23980, 'Sharp small-deviation inequalities for sums of independent\\nonnegative random variables'] Let $y=(y_1,\ldots,y_n)\in[0,\infty)^n$, and write $s(y)=\sum_i y_i$. If $s(y)>0$ and $0\le t\le s(y)/(n+1)$, then
\begin{equation}
 \Pp_D\left(\sum_{i=1}^n y_iD_i\ge t\right)
 \ge\left(1-\frac{t}{s(y)}\right)^n.
\end{equation}
Moreover, for every $\delta>0$, if $s(y)\ge n+\delta$, then
\begin{equation}
 \Pp_D\left(\sum_{i=1}^n y_iD_i>1\right)\ge b_{n,\delta},
 \qquad
 K_n(y)\le1-b_{n,\delta}.
\end{equation}

[Theorem 24 (Uniform-in-time empirical $W_2$ propagation of chaos) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target}, \ref{ass:W2}, and \ref{ass:concentration},
\begin{equation}
    \sup_{t\ge0}\E W_2^2(\mu_t^N,\mu_t)
    \le C\left\{
       N^{-2\varepsilon\alpha/
          (L_\mathrm{cpl}+2\varepsilon\alpha)}
       +r_{N,d}\right\}
    \le C\left\{
       r_{N,d}^{\,2\varepsilon\alpha/
          (L_\mathrm{cpl}+2\varepsilon\alpha)}
       +r_{N,d}\right\}.
\end{equation}

[Lemma 17 ($L^2$-energy estimate) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d\in\{3,4\}$, $u_0\in L^0_{\F_0}(\Omega; H^1(\sO))$  and let Assumption~\ref{assumption_weakened_setting} hold. Let $(u,\sigma)$ be the unique 			maximal solution to \eqref{eq:SCHtorus}. Let $T>0$ and let $(\sigma_m)_{m\geq 1}$ be a localising sequence for $(u,\sigma)$. Then, almost surely, for all $t\geq 0$
        \begin{align}
         \|u(t\wedge\sigma_m)\|_{L^2}^2 &+ \inttm \|\Delta u\|^2_{L^2}\ds + 6  \inttm \|u \grad u\|_{L^2}^2 \ds \nonumber\\
         &\le \|u_0\|_{L^2}^2 + C_{\psi} \inttm \|u\|_{L^2}^2\ds +C_\psi|\sO|t
        +M_{t \land \sigma_m}
        \end{align}
        for some continuous local martingale $(M_t)_{t\geq 0}$ with $M_0=0$. Furthermore, 
        \begin{equation}

         \sup_{t\in[0,T]\cap[0,\sigma)} \|u(t)\|_{L^2}^2  +  \int_0^{T\wedge \sigma} \|\Delta u\|_{L^2}^2\ds +  \int_0^{T\wedge \sigma}  \|u\grad u\|_{L^2}^2\ds  < \infty  \qquad \mathbb{P}\text{-a.s.}
    \end{equation}
    If, in addition, $u_0 \in L_{\F_0}^2(\Omega; L^2(\sO))$, then there exists a constant $C_T>0$, depending only on $T$, $d$ and the constants in Assumption~\ref{assumption_weakened_setting}, such that for all $m \geq 1$, we have
    \begin{align}

        \E\Big[ \|u(T\wedge\sigma_m)\|^2_{L^2} + \int_0^{T\wedge\sigma_m} \|\Delta u\|_{L^2}^2 \ds+ \int_0^{T\wedge\sigma_m} \|u\grad u\|_{L^2}^2\ds\Big]
        \leq C_T\big(\E\big[\|u_0\|_{L^2}^2\big]+1\big).
    \end{align}

[Theorem 1 of arXiv:2606.22656, 'Fluctuations of Point Vortex Ensembles\\ at Small Negative Inverse Temperature'] There exists $0<\beta_0<8\pi$ such that, for every $0<\beta<\beta_0$,
\begin{equation*}
    \lim_{N\to\infty} Z_N(\beta)=\dettwo(I-\beta G)^{-1/2}.
\end{equation*}
As a consequence, the law of $\omega_N$ on $\D'(\T)$ under the positions' distribution $\nu_{N,\beta}(dx^N)$ weakly converges to $\mu_\beta$ for $\beta<\beta_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:differentiated-linear-estimate of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $\alpha\geq0$ and assume Assumptions~(ass:reference-diffusion of the paper) and
(ass:drift-multiplier of the paper).  For
\begin{equation*}
 F\in H_{x,\alpha}^1,\qquad
 \psi\in H^1(\mu_T),\qquad u=\mathcal U(F,\psi),
\end{equation*}
one has $\mathfrak g[u,F]\in L_\alpha^2(\mathbb R^d)$ and
$D_xu\in H_{x,\alpha}^1(\mathbb R^d)$, with
\begin{equation}
 D_xu
 =\mathcal P_1^{-1}(D_xF,D_x\psi)
 =\mathcal U(\mathfrak g[u,F],D_x\psi).

\end{equation}
If, in addition, $w$ is a regular weight of order $\alpha$,
$C_w(X)<\infty$, and $\psi\in H^2(\mu_T)$, then
$\mathsf G u\in H_{x,\alpha}^1(\mathsf{S}^d)$.  For every $\kappa\geq1$, the following
estimate holds with
$C=C\bigl(T,\lambda,\Lambda,M_1(a),\operatorname{osc}_\alpha(w),C_w(X),
\Lambda_b\bigr)>0$:
\begin{equation}
 \left\lVert D_x\mathsf G u\right\rVert_{w_\kappa}
 \leq C_{w_\kappa}(X)\left\lVert D_xF\right\rVert_{w_\kappa}
 +C\left(\left\lVert F\right\rVert_{w_\kappa}
          +T^{\alpha/2}\norm\psi_{H^2(\mu_T)}\right).

\end{equation}

