[Lemma 7 (Action of $L^{X^{(N)}}$ on $h_m^{(N)}$) of arXiv:2606.00781, '2606.00781'] The generator $L^{X^{(N)}}$ acts on $h_m^{(N)}$ via
   \begin{equation} 
      L^{X^{(N)}}h_m^{(N)}
      \ =\ \sum_{k=1}^m \varphi(k,m)h_{m-k}^{(N)} - 2\varphi(m)h_m^{(N)},
      \qquad m\in\{0,\ldots,N\},
   \end{equation}
   where $\varphi(.,.)$ and $\varphi(.)$ are defined via (\ref{lambda_rep}) and
   (\ref{totalrate}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 179 (The coercivity of the velocity $L^2$-controlling quantities) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\totalfluxcontrolvelocity_N(\ubar,u), \dots, \weakspacetimetransvelocitycontrol_N(\ubar,u)$ be the velocity $L^2$-controlling quantities from Def.\,\eqref{E:UNIFIEDCOMMUTATORVELOCITYNULLFLUXL2CONTROLLINGQUANTITY}--\eqref{E:UNIFIEDCOMMUTATORVELOCITYSPACETIMEL2TRANSCONTROLLINGQUANTITY},
let $(\ubar,u) \in [\leftubar,\ubarboot)\times [\moreinterestingu_1,\moreinterestingu_2]$,
and let $(\ubar',u') \in [\leftubar,\ubar] \times [\moreinterestingu_1,u]$.
Then for $1 \leq N \leq \Ntop$,
the following lower bounds hold,
where $\mathfrak{P}^{(N)}$ is the set of order $N$ commutator operators from
Def.\,\ref{D:NOTATIONFORPOWERSOFWEIGHT}, $L^2_q$ are the weighted norms from Def.\,\ref{D:GEOMETRICL2NORMS}, and $\blowuprateofwaveWRTnumberofcommutations(N)$ is as in Def.\,\ref{D:NOTATIONFORPOWERSOFWEIGHT}:
\begin{subequations}
	\begin{align}
		\begin{split} 
			\totalfluxcontrolvelocity_N(\ubar,u)  & \geq \max_{\tander^N \in \mathfrak{P}^{(N)}} \left\{ \sum_{i=1}^3 \frac{1}{2} \left\|  
			\sqrt{\upmu} \left| \nullangrmD \tander^N v^i \right|_{\gnulltori} 
			\right\|^2_{L_{\blowuprateofwaveWRTnumberofcommutations(N)}^2\left(\ingoingcharacteristicsurfacetwoarg{\ubar'}{[\moreinterestingu,u']}\right)}, 
			 \sum_{i=1}^3	
			\left\| 
			\newuL \tander^N v 
			\right\|_{L_{\blowuprateofwaveWRTnumberofcommutations(N)}^2\left(\ingoingcharacteristicsurfacetwoarg{\ubar'}{[\moreinterestingu,u']}\right)}^2, \right.
			\\
			& \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 
			\left. 
			 \sum_{i=1}^3 \left\| 
			\frac{1}{\sqrt{\Lunit \ubar}} \Lunit \tander^N v^i
			\right\|_{L_{\blowuprateofwaveWRTnumberofcommutations(N)}^2\left(\outgoingcharacteristicsurfacetwoarg{u'}{[\leftubar,\ubar')}\right)}^2, 
			\,  \sum_{i=1}^3
			\left\| 
			\frac{\upmu}{\sqrt{\Lunit \ubar}}  
			\left| \angrmd \tander^N v^i \right|_{\gtorus} 
			\right\|_{L_{\blowuprateofwaveWRTnumberofcommutations(N)}^2\left(\outgoingcharacteristicsurfacetwoarg{u'}{[\leftubar,\ubar')}\right)}^2
			\right\rbrace,
		\end{split}	\\
		\begin{split}  
			\strongangularcontrolvelocity_N(\ubar,u) & \ge  \max_{\tander^N \in \mathfrak{P}^{(N)}}  \sum_{i=1}^3  0.92 \left\| \angrmD  \tander^N v^i \right\|^2_{L^2_{\blowuprateofwaveWRTnumberofcommutations(N)}\left( \characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]} \cap \smallneighborhoodofcreasearg{[\leftubar,\ubarboot]}\right)} 
		\end{split} \\ 
		\begin{split}  
			\weakspacetimeangularvelocitycontrol_N(\ubar,u) & \ge  \max_{\tander^N \in \mathfrak{P}^{(N)}}  \sum_{i=1}^3   \left\| \sqrt{\upmu} \left| \nullangrmD   \tander^N v^i \right|_{\gnulltori} \right\|^2_{L^2_{\blowuprateofwaveWRTnumberofcommutations(N)-1}\left(  \characteristicdiamondtwoarg{[\leftubar,\ubar')}{[\moreinterestingu_1,u']}\right)} 
		\end{split}	\\
		\begin{split}  
		\weakspacetimetransvelocitycontrol_N(\ubar,u)  & \ge \max_{\tander^N \in \mathfrak{P}^{(N)}}   \sum_{i=1}^3 \left\|  \newuL \tander^N v^i \right\|^2_{L^2_{\blowuprateofwaveWRTnumberofcommutations(N)-1}\left(  \characteristicdiamondtwoarg{[\leftubar,\ubar')}{[\moreinterestingu_1,u']}\right)} 
		\end{split}		
	\end{align}
\end{subequations}

[Corollary 14 of arXiv:2608.30138, 'High-frequency wave propagation for the viscoelastic wave equation with singular memory'] Let $k\ge 1$. Define
\[
\|u\|_{Y_k(T)} := \sum_{j=0}^{k+1}
\|\partial_t^j u\|_{C([0,T];\,H^{k+1-j}(\Omega))}.
\]
Then, under the assumptions of Theorem~\ref{thm_well_posed}, for $0\le \varepsilon\le\varepsilon_0$, the solution satisfies
\[
\begin{aligned}
\|u\|_{Y_k(T)}
&\le
C_{k,T}
\bigg(
\|u_0\|_{H^{k+1}(\Omega)}
+
\|v_0\|_{H^k(\Omega)}
\\
&\qquad
+
\sum_{\ell=0}^{k}
\|\partial_t^\ell u_-\|_{C_{\mathrm b}((-\infty,0];\,H^{k+1-\ell}(\Omega))}
+
\sum_{\ell=0}^{k}
\|\partial_t^\ell f\|_{C([0,T];\,H^{k-\ell}(\Omega))}
\bigg).
\end{aligned}
\]
Here $C_{k,T}$ depends on $k,T,\varepsilon_0$, the elliptic constants, and the kernel bounds, but not on the particular data or on
$\varepsilon\in[0,\varepsilon_0]$.

