\begin{align*}
	1+\frac{\theta}{kZ_{\alpha,\beta}(k)}
	&=1+\frac{\theta}{k+(\alpha+\beta)(k-1)} \\
	&=\frac{(\alpha+\beta+1)k-(\alpha+\beta)+\theta}{(\alpha+\beta+1)k-(\alpha+\beta)} \\
	&=\left(1+\frac{\theta-(\alpha+\beta)}{(\alpha+\beta+1)k}\right)\left(1-\frac{\alpha+\beta}{(\alpha+\beta+1)k}\right)^{-1}.
\end{align*}
Substituting this into \eqref{eq:cn_product} yields
\[
c_n=\prod_{k=1}^{n-1}\left(1+\frac{\theta-(\alpha+\beta)}{(\alpha+\beta+1)k}\right)^{-1}\; \prod_{k=1}^{n-1}\left(1-\frac{\alpha+\beta}{(\alpha+\beta+1)k}\right).
\]
