[Lem 50 of arXiv:2605.27974, 'Discrete approximation of semi-Dirichlet forms with non-symmetric perturbations of resista'] For any $\alpha > \lambda$ and $f \in C(X)$, we have the following: 
\begin{equation}
\limtoinfty{n}\norm{
\tilde{G}^{n}_{\alpha}f\lvert_{V_{n}}
-(\tilde{G}_{\alpha}f)\lvert_{V_{n}}
}_{\infty}=0.
\end{equation}
\begin{proof}
For the sake of simplicity, let $\mathscr{H}_{n}$ (resp.\ $\mathscr{H}$) denote $L^2(V_{n},\mu_{n})$ (resp.\ $L^2(X,\mu)$). 
For any $n \in \N$, by Proposition~\ref{prp5}, we have 
\begin{align}
\mathcal{E}^{n}_{1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
\leq
\mathcal{E}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
\leq
(1-s)^{-1}\mathcal{A}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}]).
\end{align}
Thus we obtain $\supover{n}\mathcal{E}^{n}_{1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}]) < \infty$
since the following holds:
\begin{align}
\mathcal{A}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
&=([f\lvert_{V_{n}}],{G}^{n}_{\alpha}[f\lvert_{V_{n}}])_{\mathscr{H}_{n}}
+(\lambda+1-\alpha)\norm{{G}^{n}_{\alpha}[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}} \\
&\leq
\norm{{G}^{n}_{\alpha}}_{\mathrm{op}}
\norm{[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}}
+\abs{\lambda+1-\alpha}
\norm{{G}^{n}_{\alpha}}^{2}_{\mathrm{op}}
\norm{[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}} \\
&\leq
\left\{(\alpha-\lambda)^{-1}+\abs{\lambda+1-\alpha}(\alpha-\lambda)^{-2}\right\}
\norm{f}^{2}_{\infty} < \infty.
\end{align}
On the other hand, since $[f\lvert_{V_{n}}] \in \mathscr{H}_{n}$ strongly K-S converges 
to $[f] \in \mathscr{H}$ and ${G}^{n}_{\alpha}$ strongly K-S converges to ${G}_{\alpha}$ 
by Proposition~\ref{main1}, ${G}^{n}_{\alpha}[f\lvert_{V_{n}}] \in \mathscr{H}_{n}$ 
strongly K-S converges to ${G}_{\alpha}[f] \in \mathscr{H}$. Therefore, we obtain the conclusion 
from Corollary~\ref{cor2} and Proposition~\ref{cptop}, noticing that 
$[\tilde{G}_{\alpha}f]=G_{\alpha}[f]$ 
(resp.\ $[\tilde{G}^{n}_{\alpha}f\lvert_{V_{n}}]=G_{\alpha}^{n}[f\lvert_{V_{n}}]$)
holds by Proposition~\ref{resolvdouitu}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

