body:
[Proposition eq:boundZ of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] There exists a constant $C_{21}=C_{21}(\kappa ,\rho ,\mathcal{E})>0$ such that for any $i\in \{1,2\}$, any $\varphi \in \mathscr{S}(\mathbb{R} )$ and any $0\le s<t\le T$, we have 
    \begin{align}
        & \mathbb{E}_{\rho ,\mathcal{E}} \left[\sup_{0\le t\le T} \big|\mathcal{Z}_t^{N,i}(\varphi )\big|^2\right] \le C_{21}  \|\Delta\varphi\|_{L^2}^2 \vee \|\nabla\varphi\|_{L^2}^2 , \\ 
        & \mathbb{E}_{\rho ,\mathcal{E}}\left[ \big| \mathcal{Z}_t^{N,i}(\varphi ) - \mathcal{Z}_s^{N,i}(\varphi )\big|^2\right] \le C_{21} (t-s) \|\Delta\varphi\|_{L^2}^2\vee \|\nabla\varphi\|_{L^2}^2.
    \end{align}

[Lemma 15 (ODE tracking error) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] On the event
$\sup_{k\ge n}\norm{\hat c_k-c}\le c_\wedge/4$, for every $T>0$,
\[\max_{m\in\cW_{\mrm N}(n,T)}
\norm{\theta_m^{\mrm N}
-\vartheta_{\mrm N}(\tau_{\mrm N}(n,m);\theta_n^{\mrm N})}\le
        e^{5T/2}
        \sqbk{
        \max_{m\in\cW_{\mrm N}(n,T)}
        \norm{\sum_{k=n}^{m-1}\alpha_{k+1}^{\mrm N}\xi_{k+1}^{\mrm N}}
        +
        \frac{25T\alpha_{n+1}^{\mrm N}}{8(1-\gamma)}}.
\]

[Lemma lem:finiteTAL of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] Let $\mu^M=\mathcal{N}(0,\Sigma_M)\in\mathcal{P}(\mathbb{R}^M)$ a Gaussian measure with zero mean and covariance operator $\Sigma_M\in \mathbb{R}^{M\times M}$, then for any $\nu^M\in\mathcal{P}(\mathbb{R}^M)$ we have the inequality:
    \begin{equation}
        W^2_{\Sigma^{-1}_M}(\nu^M,\mu^M)\le 2\mathcal{H}(\nu^M|\mu^M).
    \end{equation}

[Proposition 1 of arXiv:2609.01237, ''] For any given function $f \in H^{\half}(\Gamma_1)$,  the  problem
    \begin{equation}     

	\begin{split}
-\Delta u +\beta u &= 0, \quad     \text{in } U, 
    \\
u &= f, \quad \text{on } \Gamma_1, 
    \\
\boldsymbol{n}  \cdot   \nabla u  &= 0, \quad \text{on } \Gamma_2,
    \end{split}
    \end{equation} 
has a unique weak solution $u_f \in H^1(U)$.  Moreover, there exists a constant $C_0 > 0$, depending only on the domain $U$  and $\beta$, such that
    \begin{align*}
\|u_f\|_{H^1(U)} \leq C_0\|f\|_{H^{\half}(\Gamma_1)}.
    \end{align*}

