[Theorem 5 (Frank--Seiringer \cite{FS08}) of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $n\ge1$, $s\in(0,1)$, and $sp>n$. Then
    \begin{equation}
        \Norm{\frac{u}{|\cdot|^{s}}}_{L^p(\R^n)}
        \le C_{n,s,p}\,[u]_{s,p},
        \qquad\forall\,u\in C_{\mathrm{c}}^\infty(\R^n\setminus\{0\}).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:IBJ-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,a,n}$ and $\phi_{t,a,n}$ defined in
\S(sec:IBJ-kernel-reform of the paper) satisfy the linear
problem (equation eq:Linear-Psi-3 of the paper) and the adjoint
linear problem (equation eq:Linear-Phi-Prob of the paper) on
$\mathcal{V}$ with edge weights
$(c_k, \lambda_k)$.  Explicitly:
\begin{align}
\psi_{t,a,n+1}
&= q_{n+1}\psi_{t,a+1,n}
   - \psi_{t,a,n},
 \\
\psi_{t+1,a+1,n}
&= \psi_{t,a+1,n}
   + p_{t+1}\psi_{t,a,n},

\end{align}
and
\begin{align}
\phi_{t,a+1,n}
&= q_{n+1}\phi_{t,a,n+1}
   - \phi_{t,a+1,n+1},
 \\
\phi_{t,a+1,n}
&= \phi_{t+1,a+1,n}
   + p_{t+1}\phi_{t+1,a+2,n}.

\end{align}

