body:
[Corollary 10 (Effect of a frequency cutoff) of arXiv:2609.01403, '2609.01403'] Let \(\chi\in C_c^\infty(\mathbb R^n)\) be radial and equal to \(1\)
near the origin, and set \(\eta=1-\chi\).

\begin{enumerate}

\item If \(\alpha>0\) and
\(\alpha\notin\{n,n+2,n+4,\ldots\}\), then
\begin{equation}
    \mathcal F^{-1}(\eta|\xi|^{-\alpha})(x)
    =\kappa_{n,\alpha}|x|^{\alpha-n}+H_\alpha(x),

\end{equation}
where \(H_\alpha\) is smooth and radial near the origin. At
\(\alpha=n\),
\begin{equation}
    \mathcal F^{-1}
    \bigl(\eta\operatorname{Fp}|\xi|^{-n}\bigr)(x)
    =c_n\log\frac1{|x|}+H_n(x),

\end{equation}
where \(H_n\) is smooth and radial near the origin.

\item If \(\alpha<n\) and
\(\alpha\notin\{0,-2,-4,\ldots\}\), then, for every \(N>0\),
\begin{equation}
    \mathcal F^{-1}(\chi|\xi|^{-\alpha})(x)
    =\kappa_{n,\alpha}|x|^{\alpha-n}
    +O(|x|^{-N}),
    \qquad |x|\to\infty.

\end{equation}
If \(\alpha\in\{0,-2,-4,\ldots\}\), then
\(\mathcal F^{-1}(\chi|\xi|^{-\alpha})\) is a Schwartz function.

\end{enumerate}

[Lemma 27 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Suppose that $n \in \N \cup \{\infty\}$ and $V_i \in \metregions$, $0 \le i < n$, are such that for each $i,j > 0$, $i \neq j$, we have $\dpathY(V_i,V_j) > 0$ and $\ol{V_i} \cap \ol{V_0}$ consists of a single point. Let $V = \bigcup_{i=0}^n V_i$. Then
\begin{align*}
 \rfdomainres{V}{\Gamma} &= \left\{ f : f|_{V_i} \in \rfdomainres{V_i}{\Gamma} \text{ for each } 0 \le i < n ,\ \sum_{i=0}^n \rformres{V_i}{f}{f}{\Gamma} < \infty \right\} \\
 \text{and}\quad
 \rformres{V}{f}{f}{\Gamma} &= \sum_{i=0}^n \rformres{V_i}{f}{f}{\Gamma} .
\end{align*}

[Lemma 17 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For $\eps\le r\le r_0$, we have
\begin{equation}
  \Vol_{\omega_\eps}\{r<d<2r\}\le Cr^4,
  \qquad
  \Vol_{\omega_\eps}\{d<2\eps\}\le C\eps^4.
\end{equation}
Moreover, for every fixed $\chi\in C^\infty(X)$, pulled back to $\widetilde X$, we have
\begin{equation}
  |\mathcal P_\eps^*\chi|\le C_\chi\tau^{-3}.
\end{equation}

