[Definition 6 of arXiv:2606.02036, 'Self-intersection local times for Volterra Gaussian processes in stochastic flows with int'] If the kernel $k$ of a Volterra Gaussian process $u$ satisfies 
   \begin{align}

 \inf_{t\in[0,1]}\inf_{s\in[0,t]}\frac{1}{(t-s)^{\zeta}}\int^t_sk^2(t,r)\differential{r}>0
  \end{align}
  for some $\zeta>0,$ then the process $u$ is said to be $(2,\zeta)$-locally nondeterministic.

[Theorem HMbsde of arXiv:2606.24304, 'Quantitative Homogenization of PDEs with Neumann boundary conditions: a probabilistic appr'] Suppose that the  conditions of Theorem (HM_RSDE_W of the paper) and  \textbf{(H.3)} hold.
Then for every $0\leqslant t<T$, 
as $\varepsilon \to 0$, $U^{\varepsilon,t, x,y}$ converges  in distribution 
to $\bar{U}^{t, x}$  in the  $S$-topology in the space $\mathbb{D}([t,T];{\mathbb R})$ 
of right continuous functions with left limits. In addition,  for any $(t,x,y)\in[0,T]\times\bar D_1\times
 \bar{D}_2$, 
 $$
 \lim_{\varepsilon \to 0} u^{\varepsilon}(t,x,y) = \bar{u}(t,x), 
 $$
 where  $\bar{u}(t,x):=\bar{U}_t^{t, x}$  is the unique viscosity solution of the following averaged  Neumann type PDE:
\begin{eqnarray} 
\left\{
  \begin{array}{lllll}
    \frac{\partial  }{\partial t} \bar{u} + \bar{{\mathcal L}}\bar{u}+\bar{f}(x,\bar{u}) =0 
       \quad  \hbox{for }  (t,x)\in[0,T]\times {D_1},  \medskip \\
     \frac{\partial }{\partial \mathbf{n}} \bar{u} = g(x,\bar{u}) \quad  \hbox{for }  (t,x)\in[0,T]\times\partial D_1,  \medskip
    \\
    \bar{u}(T,x)={h}(x) \quad \hbox{for }   x\in \bar{D}_1,
  \end{array}
\right.
\end{eqnarray}
Here $\bar{{\mathcal L}} :=\sum_{i,j=1}^n\bar{a}^{ij}(x)\frac{\partial ^2}{\partial x^i\partial x^j}
+ \sum_{i=1}^n  \bar{b}^i(x)\frac{\partial}{\partial x^i}$. 
\end{theorem}

\subsection{Quantitative homogenization of PDEs with nonlinear Neumann boundary conditions  on smooth bounded domains} 

 Theorem (HMbsde of the paper) gives 
  the homogenization result for $u^{\varepsilon}(t,x,y)$. A natural but important question  is that if we can obtain the convergence rate.  
  In this section, we will address  this question by utilizing 
   the strong convergence rate established { in [C-W22], as stated in} Theorem (HM4 of the paper). 
Suppose $D_1$ and $D_2$ are $n$-dimensional  non-empty open bounded convex domains satisfying $D_i:=\{x\in\mathbb{R}^n; l_i(x) > 0\}$
  for some convex functions
 $l_i\in{\mathcal C}_b^2(\mathbb{R}^n)$ with $|\nabla l_i(x)|=1$ on $\partial D_i$ with $i=1, 2.$
Consider the following PDE 
with nonlinear Neumann boundary condition: 
\begin{eqnarray}
\left\{
  \begin{array}{lllll}
    \frac{\partial  }{\partial t}  u^{\varepsilon} + ({\mathcal L}_1+ \varepsilon^{-1} {\mathcal L}_2)u^{\varepsilon}+f(x,y,u^{\varepsilon}) = 0
     \quad \hbox{for } (t,x,y)\in [0,T]\times \bar D_1\times\bar{D}_2, \medskip\\
        \frac{\partial_x }{\partial \mathbf{n}}  u^{\varepsilon} =g(x,u)     \quad  \hbox{for }   (t,x,y)\in [0,T]\times \partial D_1 \times\bar{D}_2,\medskip\\ 
       \frac{\partial_y }{\partial \mathbf{n}^{(2)}} u^{\varepsilon} =0. \quad   \hbox{for }  (t,x,y)\in [0,T]\times \bar{D}_1 \times\partial {D}_2,  \medskip\\
       u^{\varepsilon}(T,x,y)=h(x) \quad  \hbox{for }  ( x, y) \in \bar{D}_1 \times \bar D_2,
  \end{array}
\right.
\end{eqnarray}
where ${\mathcal L}_1, ~{\mathcal L}_2$ are   the operators  given in (equation LL2 of the paper) with $a(x,y)=a(x)=\frac12\sigma\sigma^*(x)$.
Consider the following generalized backward SDE:  for $s\in [t, T],$
\begin{eqnarray}
U_s^{\varepsilon,t, x, y} &=& h(X_T^{\varepsilon,t, x, y}) + \int_s^T f(X_r^{\varepsilon,t, x, y}, Y_r^{\varepsilon,t, x, y}, U_r^{\varepsilon,t, x, y}) \, dr + \int_s^T g(X_r^{\varepsilon,t, x, y},  U_r^{\varepsilon,t, x, y}) \, d\phi^{\varepsilon, t, x, y}_r \nonumber\\
&&  - \int_s^T Z_r^{\varepsilon,t, x, y} \, dW_r,  
\end{eqnarray}
which is  decoupled with slow-fast reflected SDE system on convex domains 
  $D_1$ and $D_2$:
\begin{eqnarray} 
\begin{cases}
dX_s^{\varepsilon, t, x, y} = b(X_s^{\varepsilon, t, x, y}, Y_s^{\varepsilon, t, x, y}) \, ds + \sigma(X_s^{\varepsilon, t, x, y}) \, dW_s 
+\mathbf{n}(X_s^{\varepsilon, t, x, y} )d\phi^{\varepsilon, t, x, y}_s,  \\
dY_s^{\varepsilon, t, x, y} = \varepsilon^{-1}b^{(2)}(X_s^{\varepsilon, t, x, y}, Y_s^{\varepsilon, t, x, y} ) \, ds 
+ \varepsilon^{-1/2} \sigma^{(2)}(X_s^{\varepsilon, t, x, y}, Y_s^{\varepsilon, t, x, y}) \, dB_s  
+ \mathbf{n}^{(2)}(Y_s^{\varepsilon, t, x, y}) d \phi_s^{(2), \varepsilon, t, x, y},  \end{cases}
\end{eqnarray}
