[Theorem 1 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] (Gonz\'alez-Navarrete \& Lambert, 2019 \cite{GL2})
Consider the random-trend diffusion model. If $0 \le a+b \le 1$ and $b\le a$ we get

\begin{equation}

\lim_{n \to \infty}\left(\frac{N_n}{N_n+M_n},\frac{M_n}{N_n+M_n}\right) = \left(\frac{a}{1-\theta},1-\frac{a}{1-\theta}\right)  \ \ \mbox{a.s.},
\end{equation}
where $\theta=b(\alpha-\beta)$. In addition,
\begin{itemize}
\item[(i)]  If $\theta <  \frac{1}{2}$ then, for $n \to \infty$, in $D[0, \infty)$

\begin{equation}

\frac{1}{\sqrt{n}}\left[(N_{\floor*{tn}},M_{\floor*{tn}}) - tn\left(\frac{a}{1-\theta},1-\frac{a}{1-\theta}\right) \right] \xrightarrow{d} W_t,
\end{equation}
where $W_t$ is a continuous bivariate Gaussian process with $W_0=(0,0)$, $\E(W_t)=(0,0)$ and, for $0 < s \le t$,

\begin{equation*}
\E(W_s W_t^T) = s\left(\frac{t}{s}\right)^{\theta} \dfrac{a(1-a-\theta)}{(1-\theta)^2(1-2\theta)} \left( 
\begin{array}{cc}
1
& 
-1
\\
-1
& 
1
\end{array}
\right) \ .
\end{equation*}

\item[(ii)]  If $\theta =  \frac{1}{2}$ then, for $n \to \infty$, in $D[0, \infty)$

\begin{equation}

\frac{1}{\sqrt{n^t\log(n)}}\left[(N_{\floor*{n^t}},M_{\floor*{n^t}}) - n^t\left(2a, 1-2a\right) \right] \xrightarrow{d} W_t,
\end{equation}
where $W_t$ is a continuous bivariate Gaussian process with $W_0=(0,0)$, $\E(W_t)=(0,0)$ and, \break for $0 < s \le t$,

\begin{equation*}
\E(W_s W_t^T) = 2sa(1-2a)\left(\begin{array}{cc}
1 & -1 \\
-1 & 1 
\end{array}
\right) \ .
\end{equation*}

\item[(iii)]
Suppose that $ \frac{1}{2}< \theta < 1$. Then we have tightness for the sequence of two-dimensional random variables $\{V_n\}_{n\geq2}$ given by $
V_n := \frac{1}{n^{b(\alpha - \beta)}}\left[{(N_n, M_n) - n\left(\frac{a}{1-\theta},1-\frac{a}{1-\theta}\right)}\right]$. Furthermore, there exists {a} random vector $W = ({W_1}, \ {W_2})$ such that, as $n$ diverges
\begin{equation}

V_n  \longrightarrow W \ \ \  \mbox{a.s.}
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:back_BESQ of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Let $\mathcal W^*$ be the image of $\mathcal W$ under $(a,r)\mapsto(a,-r)$.
\vspace{-0.5em}
\begin{enumerate}[label=(\roman*)]
    \item For each $(a,r)\in {\mathbb H}$, $(\mathcal S^*_{-r,-x}(a),\, x\ge r)$ is the almost sure unique strong solution to
    \begin{align*}
        \mathcal S^*_{-r,-x}(a)=a-2\int_r^x \mathcal W^*([0,\mathcal S^*_{-r,-u}(a)], \ensuremath{\mathrm{d}} u) + (2-\delta)(x-r), \quad x\ge r.
    \end{align*}
    Let $\mathscr{S}^*_{r,x}(a):=\mathcal S^*_{-r,-x}(a)$ for $x\ge r$. Then ${\mathscr S}^*$ is a general ${\rm BESQ}^{2-\delta}$ flow driven by $-\mathcal W^*$. Moreover, ${\mathscr S}^*$ is killed if $\mathcal S$ is not killed, and it is not killed if $\mathcal S$ is killed. 

    \vspace{-0.5em}
    \item For each $(a,r)\in (0,1)\times {\mathbb R}$, $(\mathcal Y^*_{-r,-x}(a),\, x\ge r)$ is the almost sure unique strong solution to
    \begin{align*}
    \mathcal Y^*_{-r,-x}(a)= a 
    &- 2 \int_r^x\!\! \int_0^1 
    \bigl(\mathbbm{1}_{\{s \le \mathcal Y^*_{-r,-u}(a)\}} 
          - \mathcal Y^*_{-r,-u}(a)\bigr)
    \mathcal W^*(\ensuremath{\mathrm{d}} s, \ensuremath{\mathrm{d}} u) \nonumber\\
    &+ \int_r^x 
    \Bigl[(2-\delta)\bigl(1-\mathcal Y^*_{-r,-u}(a)\bigr)
          - (2-\delta')\,\mathcal Y^*_{-r,-u}(a)\Bigr]
    \ensuremath{\mathrm{d}} u, \quad x\ge r.
    \end{align*}
    Let $\mathscr{Y}^*_{r,x}(a):=\mathcal Y^*_{-r,-x}(a)$ for $x\ge r$. Then ${\mathscr Y}^*$ is a general ${\rm Jacobi}(2-\delta,2-\delta')$ flow driven by $-\mathcal W^*$. Moreover, $\mathcal Y^*$ is killed at a boundary $0$ or $1$ if and only if $\mathcal Y$ is not. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn DefAvoidingBridges of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $[a,b]\subset \mathbb{R}_+$, $k\in \mathbb{N}$ and $\mathbf{x}=(x_i)_{i=1}^k$, $\mathbf{y}=(y_i)_{i=1}^k\in \mathbf{W}_{k}^\circ$. Let $u, l \in \mathrm{C}([a,b])$ be such that: $u(t)>l(t)$ for all $t\in [a,b]$ and $u(a)>x_1, u(b)>y_1, l(a)<x_k, l(b)<y_k$. We define $\mathbf{P}_{\mathrm{avoid}}^{a,b;\mathbf{x},\mathbf{y};u,l}$ to be the law of the process $(\mathsf{A}(t;i))_{i\in \llbracket 1, k \rrbracket,t\in [a,b]}$ distributed according to $\mathbf{P}^{a,b;\mathbf{x},\mathbf{y}}$ and conditioned on the non-zero probability event
\begin{equation*}
\left\{u(r)>\mathsf{A}(r;1)>\mathsf{A}(r;2)>\cdots >\mathsf{A}(r;k)>l(r), \ \ \forall r\in [a,b]\right\}.
\end{equation*}
Write $\mathbf{E}_{\mathrm{avoid}}^{a,b;\mathbf{x},\mathbf{y};u,l}$ for the corresponding expectation.

[Lemma 24 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Let $ M>0$, $\epsilon_0>0$ and $v \in \mathcal{A}_M$. Assume that the conditions {\rm [A1-A5]} hold for any $0 \leq \epsilon < \epsilon_0$, then there exists a unique solution $X^{\epsilon,v}_{t;t_0,\xi}$ to Eq. \eqref{eq: controlled equation truncated}. It satisfies
\begin{align}
 \sup_{v\in \mathcal{A}_M}  &   \E \Big[ \exp \Big\{  \delta \sup_{t \geq t_0} \Big( \| X^{\epsilon,v}_{t;t_0,\xi}\|_{H}^{2+\beta} + \frac{\gamma_0}{2} \int_{t_0}^t \| X^{\epsilon,v}_{s;t_0,\xi} \|_{H}^{\beta} \| X^{\epsilon,v}_{s;t_0,\xi} \|_{V}^{2} \, \d s \nonumber \\
      & \quad  \quad - (1+\frac{\beta}{2}) \big( \big( C_{A,\rho,\epsilon}+ \beta C_B \epsilon \big) \,  (t-t_0)  \big) \Big) \Big\} \Big]  \leq  2 e^{\delta ( \| \xi \|_{H}^{2+\beta} + (2+\beta) \frac{2 C_B}{\lambda_1 \gamma_0} M )  };  \\
 \sup_{v\in \mathcal{A}_M}  &   \E \Big[ \exp \Big\{  \delta \sup_{t \geq t_0} \big( \| X^{\epsilon,v}_{t;t_0,\xi}\|_{H}^{2} +  \frac{\gamma_0}{2} \int_{t_0}^t  \| X^{\epsilon,v}_{s;t_0,\xi} \|_{V}^{2} \, \d s  -  C_{A,\rho,\epsilon} \,  (t-t_0)   \big) \Big\} \Big]  \leq  2 e^{\delta ( \| \xi \|_{H}^{2} + \frac{4 C_B}{\lambda_1 \gamma_0} M )  }. 
\end{align}
for any $0<\delta \leq \frac{ (1+\beta)\lambda_1 \gamma_{0}}{4 (2+\beta)^2 C_{B} \epsilon}$ and for any $0<\epsilon \leq \epsilon_0$. Furthermore, we have
\begin{align}
 \sup_{v\in \mathcal{A}_M}  &   \E \exp \Big\{ \delta \| X^{\epsilon,v}_{t_1;t_0,\xi}\|_{H}^{2+\beta}  \Big\} \leq 2 e^{\delta ( \| \xi \|_{H}^{2+\beta} + (2+\beta) \frac{C_{A,\rho,\epsilon}+ 2 C_B M+ \beta C_B \epsilon }{\lambda_1 \gamma_0} )},  \\
\sup_{v\in \mathcal{A}_M}  &     \E \Big[ \exp \Big\{  \frac{\delta}{2} \sup_{t \geq t_1} \big( \frac{\gamma_0}{2} \int_{t_1}^t \| X^{\epsilon,v}_{s;t_0,\xi} \|_{H}^{\beta} \| X^{\epsilon,v}_{s;t_0,\xi} \|_{V}^{2} \, \d s- (1+\frac{\beta}{2}) \big( C_{A,\rho,\epsilon}+ \beta C_B \epsilon \big) (t-t_1) \big) \Big\} \Big] \nonumber \\
 &  \leq 2 \, e^{\delta  \big( \frac{\| \xi \|_{H}^{2+\beta}}{2} + (1+\frac{\beta}{2}) \frac{ C_{A,\rho,\epsilon} + 2C_B M+  \beta C_{B} \epsilon  }{\lambda_1 \gamma_0} \big)}. 
\end{align}
The ``$\beta=0$'' version of the above estimates also hold. Taking the supremum over $\epsilon \in (0,\epsilon_0]$ of the above inequalities yields the uniform estimate respect to $\epsilon$ on a finite time interval.

