body:
[Theorem 15 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] The BPHZ model $(\tilde\Pi^{\eps, \delta}, \tilde \Gamma^{\eps, \delta})$ on $\tilde{\mfT}$ associated to the noise assignment 
	given in Definition~\ref{def:tcT_noise_ass}
	is bounded in $L^p(d\mathbb{P}; \mathcal{M})$ uniformly in $0 < \delta < \eps < 1$ for all $p \in [1, \infty)$ where $\mathcal{M}$ is the space of models on $\tilde{\mfT}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:lbstrthm1 of arXiv:2607.26551, 'An RDT based confirmation of Lehner's formula for Kronecker-Gaussian matrices'] For large $n\in{\mathbb N}$ and fixed $k,l\in{\mathbb N}$, let $G_{i}\in{\mathbb R}^{n\times n}$, $G_{i}^{(1,1)},G_{i}^{(1,2)},G_{i}^{(1)}\in{\mathbb R}^{k\times n},i=1,\dots,l$ be independent  standard normal matrices. Let $R$, $A_i$,  and $F_i$ be as in  Theorem (thm:thm1 of the paper). Also, let $U_iD_iU_i^T=F_i$ be the eigen-decomposition of $F_i$ ($U_i$ is unitary and $D$ is diagonal). For  $t\in(0,1)$ and $Q\in{\mathcal Q}$, let $D^{(2)}(t)$   be as in ((eq:lbstr3a1 of the paper)) and  ((eq:lbstr3 of the paper)). Set $G_i^{(1,3)} = Q G_i^{(1,1)} + \sqrt{I-Q^TQ}G_i^{(1,2)}$, 
 \begin{eqnarray}

 \bar{\zeta}_i^{(1,1)}(X^{(1)}) & = & \mbox{Tr}(G_i^{(1,1)}  X^{(1)} F_i) 
 \nonumber \\
 \bar{\zeta}_i^{(1,3)}(X^{(2)}) & = & \mbox{Tr}(G_i^{(1,3)}  X^{(2)} F_i) , 
 \end{eqnarray} 
and
\begin{equation}

{\mathcal G}_{D_u} (X^{(1)},X^{(2)}) =    
\sqrt{2} \left (
\sqrt{t} \sum_{i=1}^{l}    \bar{\zeta}_i^{(1,1)}(X^{(1)})
+\sqrt{t} \sum_{i=1}^{l}    \bar{\zeta}_i^{(1,3)}(X^{(2)})
+\sqrt{1-t} \sum_{j=1}^{2}  \sum_{i=1}^{l}   \zeta_i^{(2)}(X^{(j)})
\right ) .
\end{equation} 
Let
\begin{equation}

L^{(2)}(t)=  \max_{(X^{(1)},X^{(2)})\in\bar{{\mathcal X}}}  
 {\mathcal G}_{D_u} (X^{(1)},X^{(2)}) .
\end{equation} 
 One then has  
\begin{eqnarray}

\lim_{n\rightarrow \infty} \frac{1}{\sqrt{n}} {\mathbb E} D^{(2)}(t) 
\leq 
\lim_{n\rightarrow \infty} \frac{1}{\sqrt{n}} {\mathbb E} L^{(2)}(t) .
\end{eqnarray}

[Proposition 4 (Uniform one-sided endpoint and maximum estimates) of arXiv:2609.02257, 'Aperiodic random walks: uniform estimates, local limits and invariance principles'] There are constants \(C,c>0\) such that, for all sufficiently large
\(N\) and all \(L,H,R\in\Z_{\ge0}\),
\begin{align}
 q_{N,L}(0,H)
 &\le C\frac{H+1}{(L+1)^{3/2}}
 \exp\left\{-c\frac{H^2}{L+H+1}\right\},         \\
 q_{N,L}\bigl(0,H;\max_{j\le L}S_N(j)-H\ge R\bigr)
 &\le C\frac{H+1}{(L+1)^{3/2}}
 \exp\left\{
   -c\frac{H^2}{L+H+1}
   -c\frac{R^2}{L+R+1}
 \right\}.                   
\end{align}
Consequently,
\begin{align}
 \sum_{H\ge0}
 q_{N,L}\bigl(0,H;\max_{j\le L}S_N(j)\ge R\bigr)
 &\le \frac{C}{\sqrt{L+1}}
 \exp\left\{-c\frac{R^2}{L+R+1}\right\},
 \\
 q_{N,L}\bigl(0,0;\max_{j\le L}S_N(j)\ge R\bigr)
 &\le \frac{C}{(L+1)^{3/2}}
 \exp\left\{-c\frac{R^2}{L+R+1}\right\}.

\end{align}
The same statements hold for the dual array. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] Let $z\in\mathbb R^d$, then for all $i\in I$, $x_i\in E_i$ and $T>0$, if assumptions \eqref{hyp:Lip} and \eqref{hyp:ErgoF} are satisfied and $F_i(z,\,\cdot\,)\in\mathcal A_i$, we have
\begin{align*}
\mathbf E_{x_i}\big[\varphi(\mathbf Z_T^{n,z})\,\mathbf 1_{\{T\leq\tau_1^n\}}\big]\underset{n\to\infty}{\longrightarrow}\mathbf E_{x_i}\big[\varphi(\bar{\mathbf Z}_T^z)\,\mathbf 1_{\{T\leq\tau_1\}}\big],\quad\forall\varphi\in C_b^1(Z).
\end{align*}

[Tm item:characterization of arXiv:2411.05441, 'Sticky diffusions on star graphs : characterization and It\^o formula'] Let $X(t) = (i(t), x(t))$ be a sticky diffusion on a star graph $\Gamma$ with stickiness parameter $\eta > 0$. Then,
	\begin{enumerate}[label={\rm(\roman*)}]
	 \item  there exists a nonsticky diffusion $Y$ on $\Gamma$ and a strictly increasing continuous function $V^{-1}$ such that $X$ and $Y(V^{-1}(\cdot))$ are indistinguishable. Moreover, there exists an increasing process $\ell_X$, adapted to the completion of the natural filtration of $X$ with respect to the collection of probability measures $\left ( \mathbf P_\mathsf{x} \right)_{\mathsf{x} \in \Gamma}$, such that $\ell_X$ almost surely increases only when $X = \mathsf{v}$ and $V^{-1}(t) = t - \eta \ell_X(t)$;

	 \item  up to an extension of the filtered probability space, there exists a one-dimensional Brownian motion $W$ such that, almost surely, we have
	 \begin{equation} 
		\begin{cases}
		dx(t) = \sigma_{i(t)}(x(t)) \mathbf{1}_{\{x(t) \ne 0\}}\, d W(t) + b_{i(t)}(x(t)) \mathbf{1}_{\{x(t) \ne 0\}}\, dt + d\ell_X(t), \\
		\eta \ell_X(t) = \int_0^t \mathbf 1_{\{X(s) = \mathsf{v} \}} ds;
		\end{cases}
	\end{equation}

	\item  for every $f \in C_b^{1,2}(\mathbb{R}_+ \times \Gamma)$, almost surely, we have the It\^o formula
	\begin{equation}
	\begin{split}
	& f(t,X(t)) = f(0,X(0)) + \int_0^t \left ( \partial_s f(s,X(s)) +  Lf(s,X(s)) \right ) \mathbf 1_{\{ X(s) \neq \mathsf{v} \}}  ds \\
	& \quad + \int_0^t \sigma(X(s)) \partial_x f(s,X(s)) \mathbf{1}_{\{X(s) \neq \mathsf{v} \}} d  W(s)
	 + \int_0^t \left ( \eta\, \partial_s f(s,\mathsf{v}) +  \sum_{i=1}^N \rho_i \partial_x f_i(s,0) \right ) d \ell_X(s).
	\end{split}
	\end{equation}
	\end{enumerate}

