[Prop 18 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] The term $I_2^{\mathrm{C}}(s)$, initially defined for large $\Re(s)$ in Proposition \ref{prop:before-meromorphic-continuation} admits a meromorphic continuation to the whole complex plane and, in a neighbourhood of $\Re(s)=0$, it is given by
		\begin{multline*}
			M_{01}(s)+M_{11}(s)+\frac{\V}{2}\sum_{\chi\in\Pi(G_1)}\sum_{\varphi\in\B(\1_{n-2}\boxplus\chi\boxplus\chi^{-1})}
			\intop_{i\mathbb{R}}\left\langle \phi,\Eis(\varphi,\overline{\lambda_{\mathrm{C}}(s,z)})\right\rangle_{[G_n]^1 }\\
			\frac{\prod_{\pm}L^S\left(\tfrac{n-1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm\right)
				L^S\left(\tfrac{1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm\right)}{L^S(1+2z,\chi^2)}
			\optionA{\P_S(-\lambda_{\mathrm{C}}(s,z);\varphi,f,f_s)}
			\optionB{\P_S(s,-\lambda_{\mathrm{C}}(s,z);\varphi,\Phi)}
			\, dz
		\end{multline*}
		where $M_{01}$ and $M_{11}$ are given in \eqref{eq:M01-before-magic} and \eqref{eq:M11-before-magic}, respectively. Moreover, the third summand above is analytic on $\Re(s)=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Question of arXiv:2609.00436, 'A counterexample to the stable forking conjecture'] \begin{itemize}
            \item Do supersimple theories of finite $\mathrm{SU}$-rank satisfy the conclusion of the stable forking conjecture?

            \begin{itemize}
                \item Is the conclusion of the stable forking conjecture satisfied for $a, b  \subset \mathbb{M} \models T$, for a supersimple theory $T$ and $a\mathop{\mathpalette\setbox0=\hbox{$x$}\kern\wd0\hbox to 0pt{\mathchardef \nn=12854\hss$\nn$\kern1.4\wd0\hss}\hbox to 0pt{\hss$\mid$\hss}\lower.9\ht0 \hbox to 0pt{\hss$\smile$\hss}\kern\wd0{}} b$, where $\mathrm{SU}(a)=\mathrm{SU}(b) = 3$?\footnote{As stated in the introduction, Brower proves the case where $\mathrm{SU}(a) = 2$ and $\mathrm{SU}(b) < \omega$, improving on work of Peretz, so this is the least-rank case that remains open.}
            \end{itemize}
            \item Do countably categorical simple theories satisfy the conclusion of the stable forking conjecture?
        \end{itemize} (Stated as a question by the paper; open unless the paper says otherwise.)

[Lemma lem:fourthcumu1 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (lemma_G_large_2 of the paper), we have that     
 \begin{align}
&- D\mathbb{E}\langle \underline{G_1E_aM_2HG_2E_b}\rangle=\opr{N^{-3/2}\eta^{-2} +N^{-2}\eta^{-2}\big\|\big({1-\widehat M}\big)^{-1}\big\|} \nonumber\\ &+\frac{D\kappa^{(2, 2)}}{N}\sum_{x=1}^D \left[  { \langle \mathrm{diag}(M_2)^2E_x\rangle }\widetilde K_{ba}(M_2\mathrm{diag}(M_2)E_x) +\langle M_1 \mathrm{diag}(M_2)E_x\rangle  \widetilde K_{bx}(\mathrm{diag}(M_1E_aM_2))\right]\nonumber\\
&+\frac{D\kappa^{(2, 2)}}{N}\sum_{x=1}^D   \left[\langle M_1E_aM_2 \mathrm{diag}(M_1)E_x\rangle  \widetilde K_{bx}(\mathrm{diag}(M_1))+\langle M_1E_aM_2 \mathrm{diag}(M_2)E_x\rangle  \widetilde K_{bx}(\mathrm{diag}(M_2))\right]  ,
    \end{align}
where $\kappa^{(2, 2)}$ is the normalized $(2,2)$-cumulant of $h_{12}$, defined as $\kappa^{(2, 2)}:=N^2\mathcal C_{12}^{(2,2)}$, and $\mathrm{diag}(B)$ is the diagonal matrix consisting of the diagonal entries of the given matrix $B$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:kesten-visit-before-exit of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds. Fix  $0 \le y <1$ and $c>0$.  
 \begin{thmenumi}[label=(\roman*)]
\item Suppose that $\Exp ( X^2 ) < \infty$ and $\Exp X =0$. 
 Then there exists the limit
 \begin{equation}

 \lim_{N \to \infty}q_{2, N}(y; c) = q_{2} (y; c)  :=     1-y.
 \end{equation}
\item Suppose that~(equation ass:stable-alpha of the paper) holds with $\alpha \in (1,2)$. Then there exists the limit
 \begin{align}

 \lim_{N \to \infty}q_{\alpha, N}(y; c) & = q_{\alpha} (y; c), \end{align}
 where
  \begin{align}

 {q_{\alpha} (y ; c)} & :=
 \left(\alpha -1\right) c^{1-\frac{\alpha}{2}}\left(1+c\right)^{\alpha -1 }\left(y+c  \right)^{\frac{\alpha}{2}}y^{\alpha -1}
  \int_y^1  \left(y+cv\right)^ {-\alpha}  \left(1-v\right)^{\frac{\alpha}{2} -1}{\mathrm d} v.
 \end{align}
  \end{thmenumi} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop quantunique of arXiv:2507.09120, 'Chemical distance in graphs of polynomial growth'] Let $p_0 > p_c$. Then there exists $R_0 < \infty$ such that for all $R \ge R_0$, we have
   \[
      \mathbb{P}_p( A_v) \ge 1 - e^{- \sqrt{R}}
   \]
   for all $p \in [p_0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:scaling of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] For any $\rho > 0$, we have
\begin{equation}
    \mathbf{X} \sim \mathcal{L}^{\mathbf{x},\mathbf{y},\bm{\lambda}}_{n,\ell,r,\mathbf{f},\mathbf{g}}
    \qquad \text{if and only if} \qquad
    \mathbf{X}^{(\rho)} \sim \mathcal{L}^{\rho \mathbf{x}, \rho \mathbf{y}, \rho^{-3} \bm{\lambda}^{(\rho)}}_{n, \rho^2 \ell, \rho^2 r, \mathbf{f}^{(\rho)}, \mathbf{g}^{(\rho)}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

