[Prop 14 of arXiv:2608.26698, 'Mapping class groups of simply connected closed spin 5-manifolds with no 2- and 3-torsion '] Let $M$ be a simply connected closed spin 5-manifold.
      	\begin{itemize}
      		\item[(1)] Suppose $H_2(M)$ has no 2- and 3-torsion, in other words, suppose $p_1 \geq 5$. Then there is an isomorphism \[\Omega^{\mathrm{Spin}}_6(K(H_2(M), 2)) \xrightarrow{\cong} \mathbb{Z}^g \oplus H_2(K({(\mathbb{Z}/{{p_1}^{r_1}})}^2, 2)) \oplus \cdots \oplus H_2(K({(\mathbb{Z}/{{p_s}^{r_s}})}^2, 2)) \oplus H_M\] given by  \begin{align*}
      			[N, \nu] \mapsto ( & \hat{A}_1([N, \nu]), \cdots, \hat{A}_g([N, \nu]), \\
      			& a_{p_1, r_1}{\pi_{p_1, r_1}}_*{\nu}_*(p_1(N) \cap [N]), \cdots, a_{p_s, r_s}{\pi_{p_s, r_s}}_*{\nu}_*(p_1(N) \cap [N]), {\nu}_*([N])).
      		\end{align*}

      		\item[(2)] Suppose $H_2(M)$ has no 2-torsion. Then there is a short exact sequence \[0 \rightarrow \mathbb{Z}^g \oplus (T/{\mathrm{im} d^4_{7,0}}) \rightarrow \Omega^{\mathrm{Spin}}_6(K(H_2(M), 2)) \xrightarrow{h} H_M \rightarrow 0.\]
      	\end{itemize}

