[Theorem thm:Maruyama_stationary_increments_1 of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] Let $B$ be a real-valued Gaussian process with stationary increments.
		\begin{itemize}
			\item $B$ is ergodic (and weakly-mixing) if and only if $\mu$ is non-atomic,
			\item $B$ is mixing if and only if
			\begin{equation*}
				V_{a,b}(t) \underset{\|t\|\to +\infty}{\longrightarrow}  0, \quad a,b \in \mathbb{R}^{d},
			\end{equation*}
			where 
			\begin{align*}
				V_{a,b}(t)&=\cov{B_{-a}}{ B_{t+b}-B_{t}}\\
				&=v(t+a)+v(t+b)-v(t+a+b)-v(t).
			\end{align*}
		\end{itemize}
		In particular, if $\mu$ is absolutely continuous, then $B$ is mixing. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 (Averaged diagonal self-averaging) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $A_n=(1-\alpha)I_n+\alpha W_r^{(n)}$. For every fixed
$L<\infty$,
\begin{equation}
\begin{aligned}
  \max_{0\leq k,\ell\leq L}
  \frac{1}{n}\sum_{i=1}^n
  \Bigl|
  \bigl[A_n^k(A_n^\ell)^\top\bigr]_{ii}
  -\tau_{k,\ell}
  \Bigr|^2
  \xrightarrow{\mathbb{P}}0.
\end{aligned}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:boundary-representation-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Almost surely,
\begin{equation}
\mu=\pi_\#\mu_\partial.
\end{equation}

[Proposition prop: BernPerc_internal_1 of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $d \geq 2$, $\lambda > 0$, and $\alpha > 0$. Let $Q \in \mathcal{H}_{\alpha, K}$ (see (equation def: H_alpha of the paper)). Then, there exist an absolute constant $C > 0$, positive constants $c = c(K, \alpha, d)$ and $R_0 = R_0(\lambda, K, \alpha, d)$ such that for any positive integers $r$ with $r \ge R_0$ and any subset $A \subseteq H(r)$, we have
\begin{align}
    \mathbb P \left( \mathrm{Good}_{H(r)}^{\lambda, \ell(r)} \cap A = \emptyset \right) &\leq C \exp(-c \lambda |A|), 
\end{align}
where $\ell(r)$ is defined in (equation def: s(r) of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Explicit Construction of $\nu_t$ (Theorem 2, \cite{alaoui:montanari2022})}


    Let $X_0 \sim \nu_0$, $C \in \R^n, C \succ 0$, $W_t$ be a standard Brownian motion and define  $y_t = tX_0 + C\inv W_t$. Then, there exists a standard Brownian motion $B_t$ adapted to the Filtration generated by $y_t$ \st{} the following Radon-Nikodym derivative is a solution $F_t(x)$ for the SDE Definition \ref{def:stoclocproc}: 
    \begin{align*}
        \frac{d\nu_t(x)}{d\nu}
        \propto \exp\Parent{-\frac{t}{2} x\T C^2 x + y_t \T C^2 x}. 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 21 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $(4a-1)/4a<p\le 1$. Then,
\begin{equation}
\lim_{n\to\infty}\frac{S_n}{n^{2a(p-1)+1}}=L \ \ \text{a.s.,}
\end{equation}
where $L$ is some non-degenerate random variable. Also, we have the following mean square convergence:
\begin{equation}
\lim_{n\to\infty}\mathbb{E}\Big(\Big|\frac{S_n}{n^{2a(p-1)+1}}-L\Big|^2\Big)=0.
\end{equation}

