[Lemma 7 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $(\cF_t)_{t\in [S,T]}$ be a given filtration, $W^H$ be a $\R^d$-valued $(\cF_t)_t$-fBm of parameter $H\in (0,+\infty)$ and let $f\in L^\infty([S,T];C^1_x)$. Let $Z$ be a $\R^d$-valued $\cF_S$-measurable random variable and $\psi$ be a $\R^d$-valued, $(\cF_t)_t$-progressive process such that $\llbracket \psi\rrbracket_\varsigma<+\infty$ for some $\varsigma>0$ (for $\llbracket \psi\rrbracket_\varsigma$ defined by~\eqref{eq:slowly_varying_process}). Then:
\begin{enumerate}
    \item If $H\in (0,1/2)$ and $\varsigma=1$, there exists a constant $C_1=C_1(H,d)>0$ such that, uniformly over $\kappa\in (0,1]$, for every $(s,t)\in [S,T]^2_\leq$ one has
    \begin{equation}
	   \bigg\|\int_s^t f(r, Z+ \kappa W^H_r + \kappa\psi_r) \dd r \bigg\|_{L^2(\Omega)} \leq C_1 \kappa^{-1} |t-s|^{1-H} (1+\llbracket \psi\rrbracket_1)\| f\|_{L^\infty([S,T];C^{-1}_x)}.
    \end{equation}
    \item If $H\in [1/2,+\infty)\setminus \N$ and $\varsigma>H$, then for any $\theta>0$ such that
    \begin{equation}
        \theta<\frac{1}{2H}, \quad \theta<\frac{\varsigma}{H}-1
    \end{equation}
    there exists a constant $C_2=C_2(H,d,\theta,\varsigma)>0$ such that, uniformly over $\kappa\in (0,1]$, for every $(s,t)\in [S,T]^2_\leq$ one has
    \begin{equation}
	   \bigg\| \int_s^t f(r, Z+ \kappa W^H_r + \kappa \psi_r) \dd r\bigg\|_{L^2(\Omega)} \leq C_2 \kappa^{-\theta} |t-s|^{1-\theta H} (1+\llbracket \psi\rrbracket_\varsigma)\| f\|_{L^\infty([S,T];C^{-\theta}_x)}.
    \end{equation}
\end{enumerate}
Similarly, if $f$, $Z$, $\psi$ are as above and $W^\beta$ is a $\beta$-stable Lévy process with $\beta\in (0,2]$ and $\varsigma>1/\beta$, then for any $\theta>0$ such that
\begin{equation}
        \theta<\frac{\beta}{2}, \quad \theta<\varsigma\beta-1
    \end{equation}
there exists a constant $C_3=C_3(\beta,d,\theta,\varsigma)>0$ such that, uniformly over $\kappa\in (0,1]$, for every $(s,t)\in [S,T]^2_\leq$
    \begin{equation}
	   \bigg\| \int_s^t f(r, Z+ \kappa W^\beta_r + \kappa \psi_r) \dd r\bigg\|_{L^2(\Omega)}
       \leq C_3 \kappa^{-\theta} |t-s|^{1-\theta H} (1+\llbracket \psi\rrbracket_\varsigma)\| f\|_{L^\infty([S,T];C^{-\theta}_x)}.
    \end{equation}

