[Lemma lma:beta of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $T$ be a tangle with Conway holes $m_1$ connected to $m_2$ and $m_3$ connected to $m_4$. Let $\rho: \pi_1(T) \to SL_2(\mathbb{R})$ satisfy $\rho(m_1) = \rho(m_2) = I$, and $\rho(m_3) = \rho(m_4) = P$, with $P$ noncentral parabolic. Suppose $m_2 = \tau m_1\tau^{-1}$, and let $P^\tau = \rho(\tau)^{-1}P\rho(\tau)$, and suppose that for every tangent cocycle $u$ on the chosen character germ, one has $\mathrm{tr}(u(m_1)(P^\tau - P)) = 0$. Then we have 
\begin{equation*}
	d\mathrm{tr}(m_1m_3) = d\mathrm{tr}(m_2m_3) = d\mathrm{tr}(m_1m_4) = d\mathrm{tr}(m_2m_4)
\end{equation*}

[Proposition 1 (Gibbs regret bound) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[proposition]{prop:gibbs-benchmark}

Define
\begin{equation}
\BT
:= \inf_{\rho\ll\Pi_0}
\left[
\sum_{t=1}^T
\int\E[\ell_t(\theta; (X_t, Y_t))-\ell_t(\theta^\star; (X_t, Y_t))]\rho(\d\theta)
+\frac1\eta\KL(\rho\|\Pi_0)
\right].
\end{equation}
Then $\fR\del[1]{(\Pi_t)_{t=0}^{T-1}}\le\BT$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 43 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble as in Section~\ref{Section_general_model}. Fix $h \in [H]$ and suppose that there exist two holomorphic functions $\Phi^{+}_h(z)$ and $\Phi^{-}_h(z)$
 defined for $z$ in an open set $\amsmathbb{M}_h\subset \amsmathbb C$ which contains $\big[\hat{a}_h-\tfrac{1}{2\N},\hat{b}_h+\tfrac{1}{2\N}\big]$ but not $\big[\hat{a}_{g}-\tfrac{1}{2\N},\hat{b}_{g}+\tfrac{1}{2\N}\big]$ for $g \neq h$, and such that
 \begin{equation}

\forall x \in [\hat a_h, \hat b_h]\qquad \frac{w_h\big(\N x+\frac{1}{2}\big)}{w_h\big(\N
x-\frac{1}{2}\big)}= \frac{\Phi^+_{h}(x)}{\Phi^-_{h}(x)}.
 \end{equation}
For any integer $n \geq 2$, segment indices $h,h_2,\ldots,h_n \in [H]$ and variables $z_j\in \amsmathbb{C}\setminus [\hat a_{h_j}, \hat b_{h_j}]$ indexed by $j \in \llbracket 2,n\rrbracket$, the following expression
\begin{equation}

\begin{split}
& \quad R_{h;h_2,\ldots,h_n}(z;z_2,\ldots,z_n) \\
& = \sum_{J \subseteq \llbracket 2,n\rrbracket} \sum_{\tau \in \{\pm 1\}} \bigg(\prod_{j \in J} \frac{\delta_{h,h_j}}{z_j - z - \frac{\tau}{2\N}}\bigg) \cdot
 \Phi_h^{\tau}(z) \cdot \E^{(\textnormal{c})}\Bigg[\prod_{i = 1}^N\bigg(1 + \frac{\tau}{\N}\,\frac{\theta_{h,h(i)}}{z - \frac{\ell_i}{\N} - \frac{\tau}{2\N}}\bigg)\,,\,\big(G_{h_j}(z_j)\big)_{j \notin J}\Bigg]
\end{split}
\end{equation}
is a meromorphic function of the variable $z\in \amsmathbb M_h$. The only possible poles are located
\begin{itemize}
\item at $z=z_j \pm \frac{1}{2\N}$ for some $j \in \llbracket 2,n\rrbracket$ --- these poles are simple if all points $z_j \pm \frac{1}{2\N}$ are pairwise distinct, but multiplicities add up if some pairs coincide;
\item at $z = \hat{a}_h - \frac{1}{2\N}$. This pole is at most simple, and it is absent if $\Phi_h^-\big(\hat{a}_h-\tfrac{1}{2\N}\big) = 0$;
\item at $z = \hat{b}_h + \frac{1}{2\N}$. This pole is at most simple, and it is absent if $\Phi_h^+\big(\hat{b}_h+\tfrac{1}{2\N}\big) = 0$.
\end{itemize}
In addition, \eqref{eq_Nekrasov_higher} is a meromorphic function of the variables $z_j\in \amsmathbb{C}\setminus [\hat a_{h_j}, \hat b_{h_j}]$ for $j \in \llbracket 2,n\rrbracket$, with only possible poles $z_j=z \pm \frac{1}{2\N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

