body:
[Corollary 17 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $(\mathcal{X}_y)_{y \geq 0}$ be the $\text{SBM}(4)$ defined in Theorem \ref{theorem sbm snake} and let $(\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s)_{s \geq 0}$ be the $\text{ooSBM}(4, c, \Tilde{c})$ (defined in Corollary \ref{corollary continuous modifications}) which is the continuous modification of the process $(\mathcal{Z}^{(\rm d)}_s, \mathcal{Z}^{(\rm a)}_s)_{s \geq 0}$ (defined in Theorem \ref{theorem ooSBM ffd convergence}). Note that both $(\mathcal{X}_y)_{y \geq 0}$ and $(\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s)_{s \geq 0}$ are constructed on the same probability space $(\Omega, \mathcal{F}, \mathbb{P}_{(\mu_{\rm d},\mu_{\rm a})})$. As above let $\mathcal{Y}_s = \mathcal{Y}^{(\rm d)}_s \cup \mathcal{Y}^{(\rm a)}_s$ for $s \geq 0$. Let $\delta > 0$. Then we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. that
    \begin{equation}
        \overline{\bigcup_{y \geq \delta}\text{supp}(\mathcal{X}_y)} =  \overline{\bigcup_{i \in I} \{\hat{w}^i_t: f^i_t > \delta\}} \subseteq \overline{\bigcup_{i \in I} \{ \hat{w}^i_t: f^i_t > H^i_t(\delta)\}} = \overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)}.
    \end{equation}
    Secondly we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. that 
    \begin{equation*}
        \mathcal{R}(\mathcal{X}) \subseteq \mathcal{R}(\mathcal{Y}^{(\rm d)}) \cup \mathcal{R}(\mathcal{Y}^{(\rm a)}).
    \end{equation*}
    \begin{proof}
        The first equality in \eqref{equation coupled domination} follows from the snake representation in Theorem \ref{theorem sbm snake} and the result in Proposition \ref{proposition closure of range of continuous process} means we can exclude the case where $f^i_t = \delta$. The second equality follows by Lemma \ref{lemma support sbm interval}. The subset relation follows by the fact that for $z \geq 0$, $i \in I$, $r \in [0,\sigma(f^i)]$ we have $H^i_r(z) \leq z$. 
        \par
        The second result follows from the fact that the range can be written as a countable union, e.g.
        \newline
        $\mathcal{R}(\mathcal{X}) = \bigcup_{\delta>0, \delta \in \mathbb{Q}}\overline{\bigcup_{y \geq \delta}\text{supp}(\mathcal{X}_y)}$ and similarly for $\mathcal{Y}$ and so we can apply the first result countably many times to obtain the second result here.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:sharp-subg of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:sharp-subg}
A centered, variance-one law is sharp sub-Gaussian if
\begin{equation}
 \mathbb E e^{t\xi}\le e^{t^2/2},
 \qquad t\in\mathbb R.
\end{equation}

[Lemma 8 (Quantitative logarithmic-slope estimate) of arXiv:2608.24616, '2608.24616'] If $\limsup_{q\downarrow0}e(q)=1$, there are $t_k\to\infty$ and
$\delta_k\downarrow0$ such that, for every $0<\varepsilon<M<\infty$
and all sufficiently large $k$,
\begin{equation}
  \sup_{\varepsilon\leq v\leq M}
  \left[1-e\bigl(\Phi^{-1}(v/t_k)\bigr)\right]
  \leq \frac{\sqrt{\delta_k}}{\varepsilon}.

\end{equation}
Consequently, $m_{t_k}(2)\to0$.

