[Proposition prop:S of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] Let $d>2$,
$\eta >0$,
$L \ge L_2$,
and $z\in [\frac{1}{2},1)$.
Then
\begin{align} 
m_S(z)^2 \sim \frac{2d}{\sigma_L^2} (1-z)
	\qquad \text{as $z\to 1$,}
\end{align}
and there are constants $K_S > 0$, $a_S \in (0,1)$ (independent of $L$)
and $\delta_2 = \delta_2(L) > 0$ such that
\begin{equation} 
S_z(x) \le \delta_{0,x} +
	\frac {K_S}{ L^{1-\eta} \nnnorm x^{d-2} } e^{- a_S m_S(z) \norm x_\infty }
	\qquad (x\in \mathbb Z^d)
\end{equation}
uniformly in $z \in [1 - \delta_2, 1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 93 of arXiv:2601.16377, '2601.16377'] Take two variational data satisfying Assumptions~\ref{Assumption_A} and \ref{Assumption_B}, differing only by their potentials $V^{\textnormal{I}}_h$ and $V^{\textnormal{II}}_h$ on the $h$-th segment for a single $h \in [H]$. Assume furthermore that $\boldsymbol{\mu}^{\textnormal{I}}$ satisfies Assumption~\ref{Assumption_C}. Then, there exists $M > 0$ depending only on the constants in the assumptions, such that for any measurable function $f$ with finite $|\!|f|\!|_{\frac{1}{2}}$, we have \begin{equation}

\bigg| \int_{\amsmathbb{R}} f(x)\dd(\mu^{\textnormal{I}} - \mu^{\textnormal{II}})(x) \bigg| \leq M \cdot |\!|f|\!|_{\frac{1}{2}} \cdot \Big(|\!|V^{\textnormal{I}}_{h} - V^{\textnormal{II}}_{h}|\!|_{\infty} + \sup_{[\hat{a}_h' + \frac{1}{M},\hat{b}_h' - \frac{1}{M}]} \big|(V_h^{\textnormal{I}} - V_{h}^{\textnormal{II}})'\big|\Big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem complete-flooding of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Let the complete graph $K_m$ have i.i.d.~edge weights with law $\mathrm{Exp}(1)^{1/\theta}$. For distinct vertices $u,v$, let $T(u,v)$ be their first-passage time, and let
\begin{align*}
 Y^{(m)} := \max_{w\in V(K_m)}T(u,w)
\end{align*}
be the flooding time from $u$. For every fixed $p\geqslant1$, there is $C_p<\infty$ such that, for all $m\geqslant2$,
\begin{align}
 \sup_{u\ne v} \left\VertT(u,v)\right\Vert_p \leqslant C_p\frac{\log m}{m^{1/\theta}},
 \text{ and }
 \norm{Y^{(m)}}_p \leqslant C_p\frac{(\log m)^{\gth}}{m^{1/\theta}},
 \text{ where } \gth=\max\{{1,\theta^{-1}}\}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] [Harrem\"oes, Johnson and Kontoyiannis \cite{HJK1}] 
If $T=\E X$ and $H(X|\pi_{T}) < \infty,$ then 
\begin{displaymath}

    H \Big( \sum_{i=1}^{n} T_{1/n}(X_{i}) \big| \pi_{T} \Big) \longrightarrow 0 
\end{displaymath}
as $n\rightarrow \infty,$ where $(X_{i})_{i \ge 1}$ iid copies of $X.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition lr of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $X,Y$ be $R^{2}$-valued random vectors with densities $
f_{X},f_{Y}$ with respect to a common dominating measure. We say that $X$ is
smaller than $Y$ in \textit{likelihood ratio order}, and write $X\leq _{
\mathrm{lr}}Y$, if the density ratio $\frac{f_{Y}}{f_{X}}$ is coordinatewise
non-decreasing; that is, 
\begin{equation}
\frac{f_{Y}(x_{1},x_{2})}{f_{X}(x_{1},x_{2})}\quad \text{is non-decreasing
in each coordinate $x_{i}$, $i=1,2.$}  
\end{equation}

[Lemma Lemma-F-difference of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $s>\frac{d}{2}+2$ and $\theta\in(\frac{d}{2}+1,s-1)$.
		Let $J_n$ and $F$ be defined in (equation Define Jn of the paper) and (equation F-Euler of the paper), respectively. 
		\begin{itemize}[leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item If (Constant Sound of the paper) holds and $X,Y\in\mathbb H^s$, then 
			\begin{align}
				\left\langleJ_n F(J_nX)-J_m F(J_mY),X-Y\right\rangle _{\mathbb H^\theta} 
				\lesssim  \Big(1+\|X\|^4_{\mathbb H^s}+\|Y\|^4_{\mathbb H^s}\Big)
				\left((n\wedge m)^{-2(s-1-\theta)}+\|X-Y\|^2_{\mathbb H^\theta}\right).
			\end{align}




			\item If (General Sound of the paper) holds and $X,Y\in\mathbb H^s$, then 
			\begin{align*}
				&\left\langleJ_n F(J_nX)-J_m F(J_mY),X-Y\right\rangle _{\mathbb H^\theta}\notag\\
				\lesssim\ &  \Big(1+ \Phi^2_{\Lambda}\big(\|X\|_{\mathbb H^{s}}+\|Y\|_{\mathbb H^{s}}\big)+\|X\|^4_{\mathbb H^s}+\|Y\|^4_{\mathbb H^s}\Big)
				\left((n\wedge m)^{-2(s-1-\theta)}+\|X-Y\|^2_{\mathbb H^\theta}\right).
			\end{align*}
		\end{itemize}

