    \[
        \begin{aligned}
            \left\| \mathfrak P^{-1}_n (\mathbf u_n)^\mu \right\|_{H^\theta_0} \leq C \left\| \mathfrak P^{-1}_n (\mathbf u_n^\mu) \right\|_{H^\theta_0}.
        \end{aligned}
    \]

[Prop Prop_UniversalZeroLocus_Eigen of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] The \defined{universal zero locus} of non-degenerate $\mathbb{Z}/2\mathbb{Z}$ eigenspinors
  \begin{equation*}
    {\mathbf{Z}}_{{\mathbf{P}}\mathbf{Eig}^*}
    \coloneq
    \set[\big]{
      ({\mathbf{p}},[{\mathfrak l}];[\Phi],\lambda,x) \in {\mathbf{P}}\mathbf{Eig}^* \times X
      :
      x \notin \mathrm{Br}({\mathfrak l}),
      \Phi(x) = 0      
    }
  \end{equation*}
  is a tame Fréchet submanifold of ${\mathbf{P}}\mathbf{Eig}^* \times X$ and $\mathrm{pr}_{{\mathbf{P}}\mathbf{Eig}^*} \mskip0.5mu\colon\thinspace {\mathbf{Z}}_{{\mathbf{P}}\mathbf{Eig}^*} \to {\mathbf{P}}\mathbf{Eig}^*$ has index $-1$.
  \qed (Proof in the paper; no proof environment follows the statement in the TeX.)

