body:
[Definition def:kernel of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] For $t, u \in \mathbb{R}$ and parameters satisfying
Assumption~(ass:params of the paper), the \emph{regularized kernel of $n$-MFSM}
is
\begin{equation}

f_n(t,u;H,\alpha)
:= \frac{1}{\Gamma(\gamma(t)+1)}
\left[
(t-u)_+^{\gamma(t)}
- \sum_{k=0}^{n-1}\frac{t^k}{k!}\,(-u)_+^{\gamma(t)-k}
\prod_{j=0}^{k-1}\bigl(\gamma(t)-j\bigr)
\right],
\end{equation}
where $x_+ := \max\{x,0\}$ with $0_+^0 := 1$, and the empty product
(for $k=0$) equals $1$.

[Lemma our_B5 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] There exists a finite constant $C_0$ that depends on $R^{\pm}$ and $l$ such that 
    \begin{equation}
    \begin{split}
    &\int_0^t\int_0^1\frac{(\nabla\rho_s)^2}{\sigma(\rho_s)}dx\;ds+\int_0^t\Big|F_{-}(\rho_s(0))\log\Big(\frac{\rho_s(0)}{1-\rho_s(0)}\Big)\Big|\;ds\\
    &+\int_0^t\Big|F_{+}(\rho_s(1))\log\Big(\frac{\rho_s(1)}{1-\rho_s(1)}\Big)\Big|\;ds\leq C_0 t+\int_0^1 V_0(\gamma)\;dx-\int_0^1 V_0(\rho_t)\;dx,
    \end{split}
    \end{equation}
    where $V_0(x)=x\log(x)+(1-x)\log(1-x).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:FP-propagator of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The propagator satisfies:
\begin{enumerate}[label=\textup{(\roman*)},
leftmargin=*]
\item \textup{(Splitting)}
For $i < p < j$,
\begin{equation}
\partial_{a_p} [B_{\mathbf{x},\mathbf{a}}]_{ij}(z, w)
= -[B_{\mathbf{x},\mathbf{a}}]_{ip}(z, a_p)
[B_{\mathbf{x},\mathbf{a}}]_{pj}(a_p, w).
\end{equation}

\item \textup{(Flux conservation)}
For $i < j$,
\begin{equation}
\Bigl(\partial_z + \partial_w
+ \sum_{i < p < j} \partial_{a_p}\Bigr)
[B_{\mathbf{x},\mathbf{a}}]_{ij}(z, w) = 0.
\end{equation}

\item \textup{($x$-independence)}
\begin{equation}
\sum_{p=1}^m \partial_{x_p}
[B_{\mathbf{x},\mathbf{a}}]_{ij}(z, w) = 0.
\end{equation}
\end{enumerate}

[Lem HT comp of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For each $a > 0$ and $t > 0$, set 
  \begin{equation}
    F(a,t)
    \coloneqq 
    \left\{ s \in \supp \mathcal{C}_t \,\middle |\,
    \varlimsup_{\delta \downarrow 0}
    \frac{\mathcal{C}_t([s-\delta,s+\delta])}{\Psi_{\mathrm{ct}}(\delta)}
    < a\right\}.
  \end{equation}
  Then, for all sufficiently small $a > 0$, $\mathcal{H}_{\Psi_{\mathrm{ct}}}(F(a,t)) = 0$ for all $t > 0$,
  $\hat{P}_{\bm{\rho}}$-a.s.

[Thm eq:diff-SL0 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let  ${\kappa}_1,\ldots, k_{d_2-1} > -1$ and ${\kappa}_{d_2} = -1$. For $(\bm x,\bm y) \in {\mathbb S}^{d_1-1} \!\rtimes {\mathbb R}_\Sigma^{d_2}$, 
let ${\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma}$ be the differential operator defined by 
\begin{align}
  {\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma}:= &  \sum_{i=1}^{d_2} \left( y_i \partial_{y_i}^2 + (\kappa_i +1) \partial_{y_i} \right) 
      - 2 {\langle} \bm y, \nabla_{\bm y} {\rangle} \partial_{y_{d_2}}  + 2 |{\bm y}|  \partial_{y_{d_2}}^2   \\
       & +(d_1-2) \partial_{y_{d_2}} - (|{\boldsymbol{\kappa}}| - d_1+d_2+1) \partial_{y_d} + \frac{1}{|\bm y|} \Delta_0^{(\bm x)}, \notag
\end{align}
where $\Delta_0^{(\bm x)}$ is the Laplace-Beltrami operator on the unit sphere in $\bm x$ variable. 
Then 
\begin{align}
  {\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma} u = - n u, \qquad
       \forall u \in {\mathcal V}_n\big({\mathbb S}^{d_1-1} \!\rtimes {\mathbb R}_\Sigma^{d_2}, {\mathsf W}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma} \big).
\end{align}

[Prop 66 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $w\in\C$, $x>0$ and $y\in\R$ such that $\vert y\vert <x$,
the following holds:
\begin{equation}

\sum_{n=1}^{+\infty}
\dfrac{1}{n!}
\Big(\sum_{k=1}^{n}\dfrac{n! (n-1)!}{(n-k)! k! (k-1)! }
\,\vert y\vert^{n-k}\,\vert w\vert^{k}
\Big)
\dfrac{1}{x^{n}}
<+\infty,
\end{equation}
and
\begin{eqnarray}

\sum_{n=1}^{+\infty} (-1)^{n-1}
\dfrac{1}{n!}
\dfrac{w^{n}}{(x-y)^{n}}
&=&
\sum_{n=1}^{+\infty} (-1)^{n-1}
\dfrac{1}{n!}
\Big(\sum_{k=1}^{n}(-1)^{n-k}\dfrac{n! (n-1)!}{(n-k)! k! (k-1)! }
\,y^{n-k}\,w^{n}
\Big)
\dfrac{1}{x^{n}}
\\ 
\nonumber
&=&
\sum_{n=1}^{+\infty} (-1)^{n-1}
\dfrac{1}{n!}
\Lambda_{n}(w,y)
\dfrac{1}{x^{n}}.
\end{eqnarray}

