[Theorem thm:combined-early-late-numerical-time of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $\rho,c,q,C_X,L_f,C_{\mathrm{Loj}},C_{\mathrm{dec}}
\in(0,\infty)$. Set
\bas{
\textcolor{magenta}{
  \eta
  =
  [
    2 C_{ \mathrm{Loj} } ( C_X + 1 )
  ]^{ - 1 }
}
  .
}
Then there exist $ C_0, C_1 \in (0,\infty) $ such that the following is true.

Let $ \beta \in [ \nicefrac{ 1 }{ 2 }, 1 ) $,
$ \varepsilon \in [ 0, 1 ] $ satisfy
\bas{
\textcolor{magenta}{
  q+3\ln\beta\ge\rho
}
  .
}
Let $V\subseteq{\mathbb R}^d$ be measurable, let $(X,U)$ be $(c,q)$-regular on
$V$ in the sense of (def:regular of the paper) and assume for every
$\theta\in V$, $i\in\{1,\dots,d\}$ that
\bas{
\textcolor{magenta}{
  \| X^{ (i) }( \theta, U ) \|_{ L^{ \infty } } \le C_X
}
  .
}
Let $ F \colon {\mathbb R}^d \to [0,\infty) $ have a globally $ L_f $-Lipschitz continuous
derivative and assume for every $\theta\in V$ that
\bas{
\textcolor{magenta}{
  f_X(\theta)=-\nabla F(\theta)
}
\qquad
\text{and}
\qquad
\textcolor{magenta}{
  F(\theta)\le C_{\mathrm{Loj}}|f_X(\theta)|^2
}
  .
}
Let $ ( \gamma_n )_{ n \in {\mathbb N} } $ be decreasing and $ (0, C_{ \mathrm{Loj} } (C_X + \varepsilon) ] $-valued and

assume for every $ j, n \in {\mathbb N} $ with $ 1 < j \le n $ that
\bas{
\textcolor{magenta}{
  \gamma_j
  \le
  \gamma_n
  C_{\mathrm{dec}}
  \exp\bigl(
  \textstyle
    \frac{ \eta }{ 2 } \sum_{ k = j + 1 }^n \gamma_k
  \bigr)
}
  .
}
Let $ \theta_0 \in {\mathbb R}^d $ and let $(\theta_n)_{n\in{\mathbb N}_0}$ be the \RMSprop\
algorithm driven by $(X,U)$ with parameter tuple
$(\beta,\varepsilon,(\gamma_n)_{n\in{\mathbb N}},\theta_0)$ defined above.
Define
$
  \tau = \inf\{ n \in {\mathbb N}_0 \colon \theta_n \notin V \}
$.
Then one has for every $ n \in {\mathbb N} $ that
\bas{

\textcolor{magenta}{
  {\mathbb E}\bigl[
    F(\theta_n)
    \1_{ \{ \tau \ge n \} }
  \bigr]
\le
  \exp\bigl(
  \textstyle
    - \eta \sum_{ k = 2 }^n \gamma_k
  \bigr)
  \,
  \bigl[
    F( \theta_0 )^{ 1 / 2 }
    +
    \gamma_1
    ( 2^{ - 1 } L_f d )^{ 1 / 2 }
  \bigr]^2
  + C_0 \gamma_n
  + C_1 ( 1 - \beta)^2
}
  .
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 7 of arXiv:2609.02173, 'Bounding Selmer Groups of Superelliptic Jacobians via Class Groups'] For a finite place $v\in \Sigma$, the following conditions are equivalent:
	\begin{enumerate}
		\item The polynomial \(f_0\) satisfies \((\dagger)_v\).
		\item For maximal ideal $\mathfrak p_v\subset \mathcal O_{\overline {K_v}}$, every pair \(i\neq j\), every root \(\alpha\) of \(f_{v,i}\), and
		every root \(\beta\) of \(f_{v,j}\), one has $ \fp_v\nmid \alpha-\beta $
	\end{enumerate}

[Proposition 22 (Six descriptions of the singular mass) of arXiv:2608.03353, '\bfseries A Direct Route to Markov Chain Convergence\\[2mm] \Large via Asymptotic Equivale'] Assume \hyp{A1}{A1} and let $\alpha, \beta : \XXA \to [0,\infty)$ be finite measures,
with Lebesgue decomposition $\alpha = \alpha_{\acp{\beta}} + \alpha_{\sgp{\beta}}$ of
$\alpha$ with respect to $\beta$ as in Theorem \ref{thm:lebesgue}, and let
$S \in \XXA$ be a set with $\beta(S) = 0$ carrying $\alpha_{\sgp{\beta}}$. Then the
following six numbers coincide, and their common value is $\sing(\alpha\mid\beta)$.
\begin{enumerate}[label=\textup{(\roman*)},nosep,topsep=3pt,leftmargin=2.4em,itemsep=4pt]
  \item \emph{The variational form}, which is Definition \ref{def:singmass}:
        \begin{equation}
          \alpha(\XX) \;-\; \max\,\bigl\{\, \gamma(\XX) \ :\ \gamma \le \alpha,\ \gamma \ll \beta \,\bigr\} ,

        \end{equation}
        the maximum being attained at $\gamma := \alpha_{\acp{\beta}}$.
  \item \emph{The mass of the singular part}:
        \begin{equation}
          \alpha_{\sgp{\beta}}(\XX) .

        \end{equation}
  \item \emph{The mass the absolutely continuous part leaves over}:
        \begin{equation}
          \alpha(\XX) \;-\; \alpha_{\acp{\beta}}(\XX) .

        \end{equation}
  \item \emph{The largest mass hidden on a $\beta$-null set}:
        \begin{equation}
          \max\,\bigl\{\, \alpha(A) \ :\ A \in \XXA,\ \beta(A) = 0 \,\bigr\} ,

        \end{equation}
        the maximum being attained at $A := S$.
  \item \emph{The null set of the reversed density}:
        \begin{equation}
          \alpha\bigl( \{ g = 0 \} \bigr) ,
          \qquad\text{$g$ any density of $\beta_{\acp{\alpha}}$ with respect to $\alpha$.}

        \end{equation}
  \item \emph{The distance to the measures that have a density}:
        \begin{equation}
          \min\,\bigl\{\, \tv{\alpha - \gamma} \ :\ \gamma : \XXA \to [0,\infty)
          \text{ a finite measure},\ \gamma \ll \beta \,\bigr\} ,

        \end{equation}
        the minimum being attained at $\gamma := \alpha_{\acp{\beta}}$; and if
        $\alpha,\beta \in \Prob$ the same minimum is attained over the smaller set of
        competitors $\gamma \in \Prob$ with $\gamma \ll \beta$.
\end{enumerate}
Moreover $\alpha_{\acp{\beta}}(S) = 0$, so that the carrier $S$ splits the mass of
$\alpha$ as
\begin{equation}
  \alpha(S) = \sing(\alpha\mid\beta)
  \qquad\text{and}\qquad
  \alpha(\XX\setminus S) = \alpha(\XX) - \sing(\alpha\mid\beta) .

\end{equation}
In particular $\sing(\alpha\mid\beta) = 0$ if and only if $\alpha \ll \beta$, and
$\sing(\alpha\mid\beta) = \alpha(\XX)$ if and only if $\alpha \perp \beta$, that is
if and only if $\alpha$ is carried by a $\beta$-null set.

