[Proposition prop_characterization of arXiv:2411.16452, 'Interface scaling limit for the critical planar Ising model perturbed by a magnetic field'] There exists a unique law ${\mathbb{P}}_{h}^{(\Omega,a,b)}$ such that the following holds.
    The Radon-Nikodym derivative of ${\mathbb{P}}_{h}^{(\Omega,a,b)}$ with respect to ${\mathbb{P}}_{\operatorname{SLE}_3}^{(\Omega,a,b)}$ is given by
    \begin{equation} 
        \frac{{\operatorname{d}} {\mathbb{P}}_{h}^{(\Omega,a,b)}}{{\operatorname{d}} {\mathbb{P}}_{\operatorname{SLE}_3}^{(\Omega,a,b)}}(\gamma)= \frac{1}{\mathcal{Z}_h(\Omega)}\bigg(\sum_{k \geq 0}\frac{h^k}{k!}\int_{\Omega_L^k} f_{L}^{(+,k)}(z_1, \dots, z_k) \prod_{j=1}^k dz_j\bigg)\bigg(\sum_{k \geq 0}\frac{h^k}{k!}\int_{\Omega_{R}^k} f_{R}^{(-,k)}(z_1,\dots,z_k)\prod_{j=1}^{k}dz_j\bigg)
    \end{equation}
    and, for any sequence $(\delta_n)_n$ such that $({\mathbb{P}}_{n,h}^{\pm})_n$ converges weakly in the topology (topo_4 of the paper), there exists a further subsequence $(\delta_{n_k})_k$ such that ${\mathbb{P}}_{n_k,h}^{\pm} \to {\mathbb{P}}_h^{(\Omega,a,b)}$ weakly as $k \to \infty$ in the topology (topo_4 of the paper). Above, $\Omega_R$, respectively $\Omega_L$, denotes the connected component of $\Omega \setminus \gamma$ on the right, respectively left, of $\gamma$ and the functions $f_{L}^{(+,k)}:= f_{\Omega_L}^{(+,k)}$ and $f_{R}^{(-,k)}:= f_{\Omega_R}^{(-,k)}$ are as in Theorem (theorem_spin_correlations of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.13358, 'Extreme points of sets of probability measures and $\phi$-divergences'] Let $\Omega$ be finite and $\cF$ be the power set.\
    \begin{enumerate}
    \item[a)] There exists a measure $q\in \cM$ with $p'\ll q$ for all $p'\in \cM$.
    \item[b)] Let $q\in \cM$ with $p'\ll q$ for all $p'\in \cM$ and $\varphi\colon[0,\infty)\to\R$ be a convex function with $\varphi(1)=0$ and $\varphi_+'(0)=-\infty$.\ Then, for $p\in \cM$, the following statements are equivalent.
    \begin{enumerate}
        \item$p$ is an extreme point of $\cM$.
        \item For every $p'\in \cM\setminus\{p\}$, it holds
    \begin{equation}
            \lim_{\lambda\uparrow 1}\frac{\Div{\varphi}{\lambda p+(1-\lambda)p'}{q}-\Div{\varphi}{p}{q}}{1-\lambda}=-\infty.
    \end{equation} 
    \item $p$ is a strict local maximizer of the function
        \[
         \cM\to \R,\quad p'\mapsto \Div{\varphi}{p'}{q}.
        \]
    \end{enumerate}
    \end{enumerate}

