[Theorem thm:hall-heyde-quantitative-clt of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $X_t = \sum_{j=1}^t Y_j$, with $\mathcal{F}_t$ the $\sigma$-field generated by $Y_1, Y_2, \dots, Y_t$. Let 
  \(
  V_t = \sum_{j=1}^t \mathbb{E}[Y_j^2 \mid \mathcal{F}_{j-1}], 1 \leq t \leq n,
  \)
  and suppose that for constants $M$, $C$, and $D$ we have

  \begin{equation}

    \max_{t \leq n} |Y_t| \leq n^{-1/2} M \quad \text{a.s.},
  \end{equation}
  and
  \begin{equation}

    \mathbb{P}\left( \left| V_n - 1 \right| > 9M^2 D n^{-1/2} (\log n)^2 \right) \leq C n^{-1/4} / \log n~.
  \end{equation}
  Then for $n \geq 2$,
  \begin{equation}

    \sup_{-\infty < x < \infty} \left| \mathbb{P}(X_n \leq x) - \Phi(x) \right| \leq (2 + C + 7 M D^{1/2}) n^{-1/4} \log n~.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RBM-WF-recurrences of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The product-graph wave functions satisfy the linear
problem
(equation eq:dc-clean-linear-d1 of the paper)--(equation eq:dc-clean-linear-S3 of the paper)
and its adjoint
(equation eq:dc-clean-adjoint-d1 of the paper)--(equation eq:dc-clean-adjoint-S3 of the paper)
with the shifts and edge weights above.
Explicitly:
\begin{align}
\partial_t \Psi^{\mathbf{n}}
&= \tfrac{1}{2}\partial_{\mathbf{a}}^2 \Psi^{\mathbf{n}}
   + \partial_{\mathbf{a}} \Psi^{\mathbf{n}}
   + \tfrac{1}{2}\Psi^{\mathbf{n}},
 \\
\Psi^{\mathbf{n}+\mathbf{1}}
&= \partial_{\mathbf{a}} \Psi^{\mathbf{n}} + \Psi^{\mathbf{n}},

\end{align}
and
\begin{align}
\partial_t \Phi^{\mathbf{n}}
&= -\tfrac{1}{2}\partial_{\mathbf{a}}^2 \Phi^{\mathbf{n}}
   + \partial_{\mathbf{a}} \Phi^{\mathbf{n}}
   - \tfrac{1}{2}\Phi^{\mathbf{n}},
 \\
\Phi^{\mathbf{n}}
&= -\partial_{\mathbf{a}} \Phi^{\mathbf{n}+\mathbf{1}}
   + \Phi^{\mathbf{n}+\mathbf{1}}.

\end{align}

