[Lemma lem:continuity0-bd of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Let $\theta \in (0,1)$, and for $\varepsilon \in (0,1]$, choose $\delta = \varepsilon^{1/2\theta}$, so that $\tilde{\mathcal{E}}_\theta^\varepsilon(t,x) = \tilde{\mathcal{E}}^{t,x,\delta,\varepsilon}(t)$. Fix $T > 0$ and $r \in [1,\infty)$. 
\begin{enumerate}[label = (\roman*)]
\item There exist constants $b_1 = b_1(r,T)$ and $b_2 = b_2(\theta,r,T)$ in $(0,\infty)$ such that, for all $\varepsilon \in (0,1]$, $t \in [0,T]$ and $x,x' \in \mathbb{R}$, 
\begin{equation} 
\| \tilde{\mathcal{E}}^{t,x,\delta,\varepsilon}(0) - \tilde{\mathcal{E}}^{t,x',\delta,\varepsilon}(0) \|_r \leq b_1 e^{b_2(|x| + |x'|)}|x' - x|^{\theta/2}.
\end{equation}
\item There exist constants $b_3 = b_3(r,T)$ and $b_4 = b_4(\theta, r,T)$ in $(0,\infty)$ such that, for all $\varepsilon \in (0,1]$, $t,t' \in [0,T]$ and $x \in \mathbb{R}$, 
\begin{equation} 
\| \tilde{\mathcal{E}}^{t,x,\delta,\varepsilon}(0) - \tilde{\mathcal{E}}^{t',x,\delta,\varepsilon}(0) \|_r \leq b_3 e^{b_4|x|}|t' - t|^{\theta/4}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Quantitative Approximation Probability  of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For any fixed $k$, there exist constants $C(T,k), C'(T,k)$ such that
    \begin{equation*}
        \mathbb{P}\bigg(\sup_{t \in [0,T]}|a_j^{(n)}(t)-\tilde{a}_j^{(n)}(t)|>C(T,k)\frac{\log(n)^j}{\sqrt{n}} \text{ for some } j\leq k\bigg) < C'(T,k)n^{-2},
    \end{equation*}
    and
    \begin{equation*}
        \mathbb{P}\bigg(\sup_{t \in [0,T]} \frac{1}{\sqrt{n}}|b_j^{(n)}(t)^2-\tilde{b}_j^{(n)}(t)^2|>C(T,k)\frac{\log(n)^{2j}}{\sqrt{n}} \text{ for some } j \leq k\bigg) < C'(T,k)n^{-2}.
    \end{equation*}

