body:
[Theorem Wegnerlimits of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For any fixed  diagram   $\Gamma\in \mathcal{T}_s$,
        the  diagram function associated with   the Wegner model in Definition (wegner of the paper),  denoted by $F^{(\mathrm{Wegner})}_{\Gamma}(\{n_i\};\lambda)$,  admits the following asymptotics      as $M\rightarrow\infty$.
        \begin{enumerate}
        \item[(i)] \textbf{Frozen regime: $M^{\frac{1}{3}}\lambda \ll 1$}. Given   any  fixed integer $D\geq 2$,  if all $n_i\le CM$ for any fixed $C>0$,  then
        \begin{equation}
            \frac{1}{n_1\cdots n_s}F^{(\mathrm{Wegner})}_{\Gamma}(\{n_i\};\lambda)=\frac{1+o(1)}{n_1\cdots n_s}F^{(\mathrm{Wegner})}_{\Gamma}(\{n_i\};0)=\frac{1+o(1)}{n_1\cdots n_s}D^dF^{(\mathrm{G\beta E})}_{\Gamma}(\{n_i\},M),
        \end{equation} where   $F^{(\mathrm{G\beta E})}_{\Gamma}(\{n_i\},M)$ denotes  the diagram function of G$\beta$E  matrix of size $M$.
        \item[(ii)] \textbf{Skellam regime: $M^{\frac{1}{3}}\lambda \to \mu \in (0,\infty)$}. Given   any  fixed integer $D\geq 2$,  if all $n_i\lambda\rightarrow t_i>0$,
        \begin{equation} 
            \frac{1}{n_1\cdots n_s}F^{(\mathrm{Wegner})}_{\Gamma}(\{n_i\})=\frac{(1+o(1))C_\Gamma}{\,t_1\cdots t_s\,}\,\mu^{-|E|+s}\sum_{\alpha_v\in \mathbb{T}_D^d}\int_{\lambda_e:\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}p^{\mathrm{(Skellam)}}(\alpha_{u}-\alpha_{v},\lambda_e) \prod_{e\in E(\Gamma)}d\lambda_e.
        \end{equation}

        \item[(iii)] \textbf{Diffusive regime: $M^{\frac{1}{3}}\lambda \gg 1$}: When   $d=1$,  with the same notations, assumptions and scalings on $n_i$ as in Theorem (thm:limit_cumulant of the paper) where    $\alpha=2$, $N=DM$ and the effective bandwidth  $W_{\mathrm{eff}}=\sqrt{\lambda}M$, then
\begin{equation}
    \frac{1}{n_1\cdots n_s}F^{(\mathrm{Wegner})}_{\Gamma}(\{n_i\};\lambda)=(1+o(1))\frac{1}{n_1\cdots n_s}\mathcal{L}_\Gamma (\{t_i\}; (W_{\mathrm{eff}},N)).
\end{equation}
\end{enumerate}

