[Lemm l:cond-reg of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Define the event 
    \begin{align*}
        \mathsf{PolymerCondTF}_{\varepsilon,n}
        &\coloneqq  
        \bigcap_{k = 1}^{M-1}
        \left\{
            \xi \in \Xi :
            \mathbb{P}^{\xi,(n)}\left(
                \mathrm{TF}_k \,\middle|\,
                |X^{(n)}(r_k)|,
                |X^{(n)}(r_{k+1})| \leqslant \varepsilon
            \right)
            \geqslant 1-e^{-\log^{3/2}(1/\varepsilon)}
        \right\}.
    \end{align*}
    For all sufficiently small $\varepsilon>0$,
    \begin{align*}
        \limsup_{n\to\infty}\mathbb{P}\left(\neg\mathsf{PolymerCondTF}_{\varepsilon,n}\right) \leqslant e^{-\log^2(1/\varepsilon)}.
    \end{align*}

[Lemma delay_rough of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let $\mathbf{X}$ be a \emph{$\pi$-delayed $\gamma$-rough path with delay $r > 0$}. Suppose $\frac{1}{3}<\beta\leq\gamma$ , $r_1\leq r$ $(\zeta,\zeta^\prime)\in\mathscr{D}_{\mathbf{X}}^{\beta}([-r,0],\mathbb{R}^d) $, $(\xi_1,\xi_{1}^{\prime})\in\mathscr{D}_{\mathbf{X}}^{\beta}([-r,0],\mathbb{R}^d)$ and $(\xi_2,\xi_{2}^{\prime}),(\eta,\eta^{\prime})\in \mathscr{D}_{\mathbf{X}}^{\beta}([0,r_1],\mathbb{R}^d) $. Assume $F:\mathbb{R}^{d}\times\mathbb{R}^d\times\mathbb{R}^d\rightarrow \mathcal{L}(\mathbb{R}^m,\mathbb{R}^n)\in C^{2}_{b}$. Let $\xi: [-r,r_1]\rightarrow \mathbb{R}^d$ is defined by
			\begin{align}
				\xi_{t}:=\begin{cases}
					\xi_{1}(t), & \text{for } -r\leq t<0\\
					\xi_{2}(t), & \text{for } 0\leq t\leq r_1
				\end{cases} \ \ 
			\end{align}
			and
			\begin{align}
				\xi_{t}^{\prime}:=\begin{cases}
					\xi_{1}^{\prime}(t), & \text{for } -r\leq t<0\\
					\xi_{2}^{\prime}(t), & \text{for } 0\leq t\leq r_1
				\end{cases} \ \ 
			\end{align}
			Then for every  $s,t\in [0,r_1]$ and $A_{s}:=\big(\eta_{s},\zeta_{s-r},\int_{-r}^{0}\xi_{\theta+s}\pi(\mathrm{d}\theta)\big)$, following statement is well defined
			\begin{align}
				\begin{split}
					&\int_{s}^{t}F\big(\eta_{\tau},\zeta_{\tau-r},\int_{-r}^{0}\xi_{\theta+\tau}\pi(\mathrm{d}\theta)\big)\circ\mathrm{d}\mathbf{X}_{\tau}:=\quad\lim_{\vert\Pi\vert\rightarrow 0}\bigg[\sum_{t_j\in\Pi}F(A_{t_j})\circ X_{t_{j},t_{j+1}}\\&\quad+\sum_{t_j\in\Pi} \frac{\partial F}{\partial Y_{1}}|_{A_{t_j}}\circ (\eta^{\prime}_{t_j}\circ\mathbb{X}_{t_j,t_{j+1}})+\sum_{t_j\in\Pi}\frac{\partial F}{\partial Y_{2}}|_{A_{t_j}}\circ(\zeta^{\prime}_{t_j-r}\circ \mathbb{X}_{t_j,t_{j+1}}(-r))\\ &\qquad+\sum_{t_j\in\Pi} \frac{\partial F}{\partial Y_{3}}|_{A_{t_j}}\circ \big(\int_{-r}^{0}\xi_{\theta+t_j}^{\prime}\circ \mathbb{X}_{t_j,t_{j+1}}(\theta)\pi(\mathrm{d}\theta)\big)\bigg{]}.
				\end{split}
			\end{align}
			Where by $\frac{\partial F}{\partial Y_{1}}|_{A_{\tau}}, \frac{\partial F}{\partial Y_{2}}|_{A_\tau}$ and $ \frac{\partial F}{\partial Y_{3}}|_{A_\tau}$, we mean the derivative of $F$ respect to first, second and the third arguments at $A_\tau$.

