body:
[Prop First-Prop-Res of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] \begin{enumerate}
\item[\rm(1)] The family $(\check{R}_\alpha)_{\alpha\geq 0}$ satisfies the resolvent equation: $\check{R}_\alpha - \check{R}_\beta = (\beta- \alpha)\check{R}_\alpha\check{R}_\beta, \alpha,\beta\geq 0$. Moreover $\alpha\|\check{R}_\alpha\|\leq 1, \alpha\geq 0$.
\item[\rm(2)] For all $\alpha\geq 0, \ran(\check{R}_\alpha)$ and $\ker(\check{R}_\alpha)$ are $\alpha$-independent.
\item[\rm(3)]   For all $\alpha\geq 0, \check{R}_\alpha$ is injective on $\ran(\check{R}_\beta)$ for all $\beta\geq 0$.
\end{enumerate}

[Lem 56 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] We have for each $j \in [0, \mathfrak{j}]$ and $i \in [0, a_j-1]$ that 
\begin{flalign} 

	\begin{aligned} 
		& (1 - N^{-M\delta}) q_{i} \le q_{i+1} \le  q_{i}; \qquad \quad q_{a_j} \ge 2^{j-1} N^{5000K\delta-1}; \\
		& a_j \le a_0 \le N^{2/3+2M\delta}; \qquad \qquad \qquad \quad \mathsf{T}_{a_j, j} \le N^{2+2M^2 \delta}. 
	\end{aligned}
\end{flalign}

[Lemma lem:var of arXiv:2510.09818, 'On the Fourier dimension of fractional Brownian graphs'] [LL25]
Let $H \in (0,1)$ and consider a fractional Brownian motion $B$ with Hurst parameter $H$. There exists a constant $C_H>0$ depending only on $H$ such that for all integers $n \ge 1$, for all $0<t_1<\cdots<t_n$, and for all $a_1, \dots, a_n \in \mathbb R$
\begin{align*}
	\mathrm{Var}\left( \sum_{j=1}^n a_j B_{t_j}\right) \ge \frac{C_H^{n-1}}{n} \sum_{j=1}^n (a_j+\cdots+a_n)^2 (t_j-t_{j-1})^{2H},
\end{align*}
where we have used the convention $t_0=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

