[Lem 24 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1},\A{2}\leq 1$ be such that $N^{-1}\ll  \pr{\A{1}\A{2}}^{1/2}$. Let $0< 1/C\leq \widehat{q}\in S(1,\A{1},\A{2})$ such that $\widehat{q}\sim \widehat{q}_0+\Tilde{h}\widehat{q}_1+...$ in $S(1,\A{1},\A{2})$. Then, 
    \begin{equation}
        \begin{split}
            \log\det&\pr{\widehat{q}_{N,\A{1},\A{2}}}\\
            &= \pr{N\A{1}^{1/2}\A{2}^{1/2}}^{d}\int_{\mc{T}_{\A{1},\A{2}}}\log\pr{\widehat{q}_0(\rho)}d\rho+\mc{O}\pr{N^d\pr{N\A{1}^{1/2}\A{2}^{1/2}}^{-1}}.
        \end{split}
    \end{equation}

