[Thm 1 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] \begin{equation}
\mu_h( \mathrm{d} z) = \lim_{\eps\to 0} \eps^{\gamma^2/2} \exp \left( \gamma h_\eps( \dd z)  \right) v_g (\dd z)
\end{equation}
exists in probability.  Furthermore the resulting measure is nonzero precisely when $\gamma \in [0,2)$, and is independent of the choice of regularisation kernel $\theta$ subject to very mild conditions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] A convex function $u_1: [0,1) \times \Delta \to \mathbb R$ is said to be a viscosity sub-solution to (equation eq:gHJB of the paper) if 
\begin{enumerate}
    \item[(i)] For any $x_0 \in \Delta$, $\limsup_{(t,x) \to (1,x_0)} u_1(t,x) \leq 0$. 
    \item[(ii)] For any convex test function $\phi \in C^2([0,1) \times \Delta; \mathbb R)$, and any local maximum $(t_0,x_0) $ of $u_1 - \phi$, we have 
    \begin{align*}
        -\partial_t \phi(t_0,x_0) \leq H(t_0, u_1(t_0,x_0), \det \nabla^2 \phi(t_0,x_0)).
    \end{align*}
\end{enumerate}
A convex function $u_2: [0,1) \times \Delta \to \mathbb R$ is said to be a viscosity super-solution to (equation eq:gHJB of the paper) if 
\begin{enumerate}
    \item[(i)] For any $x_0 \in \bar{\Delta}$, $\liminf_{(t,x) \to (1,x_0)} u_2(t,x) \geq 0$. 
    \item[(ii)] For any $(t_0,x_0) \in [0,1) \times \partial \Delta$, $\liminf_{(t,x) \to (t_0,x_0)} u_2(t,x)=+\infty$
    \item[(iii)] For any convex test function $\phi \in C^2([0,1) \times \Delta; \mathbb R)$, and any local minimum $(t_0,x_0)$ of $u_2 - \phi$, we have 
    \begin{align*}
        -\partial_t \phi(t_0,x_0) \geq H(t_0, u_2(t_0,x_0), \det \nabla^2 \phi(t_0,x_0)).
    \end{align*}
\end{enumerate}
A continuous function $u: [0,1) \times \Delta \to \mathbb R$ is said to be a viscosity solution to (equation eq:gHJB of the paper) if it is a sub-solution and super-solution.

[Definition 20 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let us define the axioms and deduction rules of $\LK_{\rmbeta}$ as follows: We assume the typical rules for first-order logic, and add the following rules for ordinals:
    \begin{center}
        \vspace{1em}
        \begin{mathprooftree}
            \def\fCenter{\vdash}
            \AxiomC{}
            \RightLabel{$(<_\ord)$ ($\ttX \vDash x<y$)}
            \UnaryInfC{$[\ttX]\fCenter \tilde{x}<_\ord\tilde{y}$}
        \end{mathprooftree} 
        \hspace{3em}
        \begin{mathprooftree}
            \def\fCenter{\vdash}
            \AxiomC{}
            \RightLabel{$(\le_\ord)$ ($\ttX \vDash x\le y$)}
            \UnaryInfC{$[\ttX]\fCenter \tilde{x}\le_\ord\tilde{y}$}
        \end{mathprooftree}

        \vspace{1em}
        \begin{mathprooftree}
            \def\fCenter{\vdash}
            \AxiomC{$\cdots\ [\ttX']\fCenter \Gamma, A(\tilde{n}) \quad (n\notin \ttX)\ \cdots $}
            \AxiomC{$\cdots\ [\ttX]\fCenter \Gamma, A(\tilde{n}) \quad (n\in \ttX)\ \cdots$}
            \RightLabel{$(\forall^\ord)$}
            \BinaryInfC{$[\ttX]\fCenter \Gamma,\forall^\ord x A(x)$}
        \end{mathprooftree}

        \vspace{1em}
        \begin{mathprooftree}
            \def\fCenter{\vdash}
            \AxiomC{$[\ttX]\fCenter \Gamma,A(\tilde{n})$}
            \RightLabel{$(\exists^\ord)$}
            \UnaryInfC{$[\ttX]\fCenter \Gamma,\exists^\ord x A(x)$}
        \end{mathprooftree}
    \end{center}
    In $\forall^\ord$, the first form of the hypotheses is enumerated for every possible $\ttX'$ for an extension of $\ttX$ of the form $\ttX\cup \{n\}$, where $n$ is the least number not in $\field \ttX$. (The order of $n$ in $\ttX'$ can be arbitrary).

    We form a $\rmbeta$-preproof from a given set of rules. We say a $\rmbeta$-preproof $\pi$ is a \emph{$\rmbeta$-proof} if for every infinite branch $B$ of $\pi$, the union of all template orders occurring in $B$ is ill-founded.

