[Definition 1 of arXiv:2604.27485, 'On large deviation principles for general random processes \footnote{Research supported by'] {\rm
We will say that a statement~$\mathcal S$  whose formulation involves a function $\varepsilon=\varepsilon_T >0$ {\em is satisfied for $\ept $ that tends  to zero slowly enough  as\/} $T\to\infty $ (and will denote this property of the function~$\ep$ by writing  ``$\varepsilon =\oo (1)$ as $T\to\infty $'') if
\begin{enumerate}
\item[(i)] there exists a positive function  $\widetilde\varepsilon = \widetilde\varepsilon_T \to 0$ as $T\to\infty  $ such that   $\mathcal S$ holds true with $\varepsilon=\widetilde\varepsilon,$ and
\item[(ii)] the statement~$\mathcal S$ holds true for all functions
$\varepsilon_T \to 0 $ such that
$\varepsilon_T\ge   c \widetilde\ep_T $ for some constant  $c>0.$
\end{enumerate}
}

[Corollary eq:cantelli_nonMarkov of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let two canonical insurance models $(\alpha, \Lambda, \Phi, B, b)$ and $(\bar \alpha, \bar \Lambda, \Phi, \bar B, \bar b)$  be given. Let   $\Lambda$ and $\bar \Lambda$ have  identical reset points. Suppose that the state-wise prospective reserves $(V^i)$ of the first model satisfy
	\begin{align}
	\begin{split}
			&\mathds{1}_{\{  \bar \Lambda^{i\raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(t-)<\infty \}} I^i(t-)  \bigg(  B^i(\mathrm{d} t)+ \sum_{j : j\neq i}(b^{ij}(t) + V^j(t)-V^i(t)) \Lambda^{ij}(\mathrm{d} t)\bigg)\\
			& =\mathds{1}_{\{  \bar \Lambda^{i\raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(t-)<\infty \}} I^i(t-)  \bigg(  \bar B^i(\mathrm{d} t)+ \sum_{j : j\neq i}(\bar b^{ij}(t) + V^j(t)-V^i(t)) \bar \Lambda^{ij}(\mathrm{d} t)\bigg).
			\end{split}
	\end{align}
	Then the two models have  identical state-wise prospective reserves:
	 $$(V^i)_{i \in \mathcal{Z}}=(\bar V^i)_{i \in \mathcal{Z}}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2609.03840, 'Haglund--Haiman--Loehr formula via Carlsson--Mellit algebra'] \cite[Lemma~4.2,~Example~4.3]{CGM20} 
  We have
  \begin{align} 
    d_+ I_{\lambda, w}
    &= {-q^k}\sum_{x \in \Add(\lambda)} x d_{\lambda, x}
      \left( \prod_{i=1}^k\frac{x-tw_i}{x-qtw_i} \right) I_{\lambda + x, \{x\} \cup w},
       \\
    d_- I_{\lambda, w \cup \{x\}}
    &= I_{\lambda, w},  \\
    I_{\lambda, \emptyset}
    &=  \frac{(-1)^{|\lambda|}}{T_\lambda} \widetilde{H}_\lambda(X; q, t). 
  \end{align}
  Here, for a sequence \( w = (w_1 ,\dots, w_k) \),
  \( \{x\} \cup w \) denotes \( (x, w_1 ,\dots, w_k) \) and
  \( w \cup \{x\} \) denotes \( (w_1 ,\dots, w_k, x) \). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Suppose that $\xi$, $f$, $g$ satisfy (H1)-(H3) and $L$, $U$ satisfy Assumption \ref{assLU}. Then the doubly reflected $G$-BSDE with data $(\xi,f,g,L,U)$ has a unique solution $(Y,Z,A)\in S^\infty_G(0,T)\times BMO_G\times \cap_{\alpha\geq 2} S^\alpha_G(0,T)$. Moreover, for any $\alpha\ge 2$, we have
	\begin{align*}
		\lim_{n\rightarrow \infty}\hat{\mathbb{E}}\left[\sup_{t\in[0,T]}|Y_t-\bar{Y}^n_t|^\alpha\right]=0, 
	\end{align*}
	where for each $n\in\mathbb{N}$, $(\bar{Y}^n,\bar{Z}^n,\bar{A}^n)\in S^\infty_G(0,T)\times BMO_G\times \cap_{\alpha\geq 2} S^\alpha_G(0,T)$ is the solution to the following reflected $G$-BSDE:
	\begin{equation}
		\begin{cases}

			\bar{Y}^n_t=\xi+\int_t^T f(s,\bar{Y}^n_s,\bar{Z}^n_s)ds+\int_t^T g(s,\bar{Y}^n_s,\bar{Z}^n_s)d\langle B\rangle_s\\
			\ \ \ \ \ \ \ \ -n\int_t^T(\bar{Y}^n_s-U_s)^+ds-\int_t^T \bar{Z}^n_sdB_s+(\bar{A}^n_T-\bar{A}^n_t), \\
			\bar{Y}^n_t\geq L_t, \forall t\in[0,T], \{-\int_0^t (\bar{Y}^n_s-L_s)d\bar{A}^n_s\}_{t\in[0,T]} \textrm{ is a non-increasing $G$-martingale}.
		\end{cases}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:strong_LLN of arXiv:2411.04690, 'Asymptotic distribution of the derivative of the taut string accompanying Wiener process'] Let a function $\varphi$ be continuous almost everywhere, locally bounded and satisfy the condition of power growth (equation eq:power_bound of the paper). 
Then for every $r>0$ it is true that 
  \begin{equation*}
			R_{r}(\varphi)
			\stackrel{\text{a.s.}}{=}
			\int\limits_{\mathbb R} \varphi(u) p_{\infty,r}(u)\,du.
	\end{equation*}

