[Definition def:BG of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] A line ensemble $\mathbf{X} : \mathbb{R} \to \mathbb{A}_+^\infty$ satisfies the $\lambda$-BG property if
for any $n \in \mathbb{N}$, any $\ell < r$, and any
bounded measurable function $F$ on the space of paths $[\ell,r] \to \mathbb{A}_+^\infty$, we have
\begin{equation}

    \mathbb{E}_\mathbf{X} \mleft[ F(\mathbf{X}) \middle| \mathcal{E}^n_{\ell,r}(\mathbf{X}) \mright]
    = \mathbb{E}_{\mathbf{Y} \sim \mathcal{L}^{\mathbf{X}^{\leqslant n}(\ell), \mathbf{X}^{\leqslant n}(r),\lambda}_{n,\ell,r,X^{n+1}|_{[\ell,r]}}}
    \mleft[F(\mathbf{Y} \mathbf{X}^{> n}) \mright]
\end{equation}
almost surely as $\mathcal{E}^n_{\ell,r}(\mathbf{X})$-measurable random variables.

[Proposition 29 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] Let $
u > 0$. There exists $C_{
u} > 0$ such that with $
u$-high probability,
   egin{equation*}
      \|\hat{A} - A^{\pp}\| \leq C_{
u} \sqrt{ rac{\log N}{\log \log N}} \quad 	ext{ and } \quad \|\hat{A} - A\| \leq C_{
u}\sqrt{ rac{\log N}{\log \log N}}\,.
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:Woodbury of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $K$ be dressing compatible with $(\Psi, \Phi)$,
and suppose that $\dim E < \infty$ and that
$F(u) \vcentcolon= \det_H(I - zK(u))$
is well-defined for every $u \in \mathcal{V}$.  Then
\begin{equation}
F(u) = F(Tu)\det_E\bigl(\mathcal{M}(Tu)\bigr).
\end{equation}
In particular, for each $i \in \mathbb{N}$,
\begin{equation}
\det_E(\mathcal{M}_i(u))F(u)F(S_i u)
= \det_E(C_i(u))F(Tu)F(T^{-1}S_i u).
\end{equation}

[Theorem eq:cluster-lower-bound-alt of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{thm:cluster_size_lower_bound}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Theta(d_G(x,y)^{-d \alpha})$ with $\alpha \in (1,2)$.

    Let $\beta > \beta_c$.



    Then there exists $A = A(G,J) > 0$ such that for all $k \in \mathbf{N}$

    \begin{equation}

        \exp
        (
            -  
            A 
            \beta k^{
                \max(2-\alpha, (d-1)/d)
            }(\log k)^{
                \mathbf{1}
                \left(
                    \alpha=1+1/d
                \right)}
        )
        \leq 
        \mathbf{P}_{\beta}
        \left(
            k 
            < 
            \# K 
            < 
            \infty
        \right).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem maintheorem of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $f \colon \mathbb N^s \to \mathbb C$ be a function that satisfies (mainassumption of the paper) and that is furthermore real and non-negative or satisfies (upperboundassp of the paper). Assume that the polytope $\cal P$ is bounded, that $\cal F$ is of dimension $d$ and not contained in a coordinate hyperplane, and that $\vec\ell$ is of convergent type for the face $\cal F$.

Then there exist $\varepsilon > 0$ and a constant $c_{\cal P}$, which only depends on $\vec \ell$ and the polytope $\cal P$, such that
    \begin{align*}
\Upsilon(B; \vec 1)
		= \frac{c_f c_{\cal P}}
		{\prod_{i=1}^s \alpha_i^{\ell_i}} B^a (\log B)^{d+\ell}
			+ O_{\vec \varpi, \vec \alpha, \vec \ell}(C_f B^a (\log B)^{d + \ell - \varepsilon}).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2609.03455, '2609.03455'] Put
\(
 x={\u\Delta}/({\u-1})\),
\(
 y={\psi}/{\u}
\).
Then, we have
\[
 \A_0(\Gtwo\cap\G(7))
 =\C(\psi,\u,\Delta)
 =\C(x,y).
\]
Moreover, $x$ and $y$ satisfy
\begin{multline}
64y^{28}
-x^6y^{21}
-52x^4y^{21}
-1520x^2y^{21}
-18496y^{21} \\
-84x^4y^{14}
+5264x^2y^{14}
-3648y^{14} 
-1072x^2y^7
+64y^7
+16x^2=0.
\end{multline}
The normalization of the plane curve
\eqref{eq:genus17-xy} has genus $17$.

[Definition 64 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same parameters as in Definition \ref{Def.ParametersEdge} and fix $T \in (0, \bar{\kappa})$. Let $\mathbb{P}_N$ be the Pfaffian Schur process from Definition \ref{Def.SchurProcess} with $M \geq \bar{\kappa} N$. If $(\lambda^0, \dots, \lambda^N)$ is distributed according to $\mathbb{P}_N$, we define $\mathfrak{L}^N = (L^N_1, L^N_2)$ on $\llbracket 0, M \rrbracket$ through
\begin{equation}
L^{N}_i(s)  =  \lambda^{s}_{i}. 
\end{equation}
By linearly interpolating the points $(s, L^N_i(s))$, we may think of $L_1^N, L_2^N$ as random elements in $C([0,M])$, see Figure \ref{Fig.DiscreteLE}. We also define the rescaled curves
\begin{equation}
\begin{split}
&\mathcal{L}^{N}_i(t) = \sigmap^{-1} N^{-1/2} \cdot \left(L^{N}_i(tN) -  h_2(t)N\right) \mbox{ for } i = 1,2, t\in [0,T].
\end{split}
\end{equation}

