[Definition eq:multi-agent-macroscopic-intermediate-solved-weights of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] For every \(N\in \mathbb{N}\), we define the piecewise-constant extensions of the state processes
	and the initial weight laws as
	\begin{equation*}
		\begin{aligned}
		\bar X^N(t,\xi) &:= \sum_{i=1}^N \bar X_i^N(t)\,\mathds{1}_{I_i^N}(\xi), \quad t\in [0,T],\,\xi\in [0,1],\\
		q^{N,\xi,\xi'}_0 &:= \sum_{i,j=1}^N q^N_{ij,0}\,\mathds{1}_{I_i^N\times I_j^N}(\xi,\xi'), \quad \xi,\xi'\in [0,1].
		\end{aligned}
	\end{equation*}
	With this notation, the independent projection system (equation eq:multi-agent-discrete-independent-projection-solved-weights of the paper)
	can be equivalently rewritten as the following system of path-dependent McKean-Vlasov SDEs parameterized by \(\xi \in [0,1]\):
	\begin{align}
		d\bar X^N(t,\xi) &= \int_0^1\int_{\mathcal{C}^d_t} \int_{\mathbb{R}} \Phi_t(\bar{X}^N(\cdot,\xi)_{[0,t]},\gamma,w) K(\bar X^N(t,\xi),\gamma(t)) \, dq^{N,\xi,\xi'}_0(w)\,d\bar \mu_{[0,t]}^{N,\xi'}(\gamma)\,d\xi' dt + \sqrt{2\nu}\,dW^N(t,\xi),\nonumber\\
		\bar X^N(0,\xi) &= X^N_{0}(\xi), \quad \bar \mu^{N,\xi}_{[0,t]} := \mathrm{Law}(\bar X^N(\cdot,\xi)_{[0,t]}) \in \mathcal{P}(\mathcal{C}^d_t).
	\end{align}
	The initial states are analogously set as
	\begin{equation*}
		X_0^N(\xi) := \sum_{i=1}^N X_{i,0}^N\,\mathds{1}_{I_i^N}(\xi), \quad \xi\in [0,1],
	\end{equation*}
	and the driving noise \(W^N(t,\xi)\) is defined piecewise by
	\[
		W^N(t,\xi) := \sum_{i=1}^N W_i^N(t)\, \mathds{1}_{I_i^N}(\xi),\quad t \in [0,T],\,\xi\in [0,1].
	\]

[Lemma lem:Xdev of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Suppose $\mathbf{x} \in \mathrm{Meso}(N)$. Then, for all $t \geqslant 0$ and $\Delta>0$, we have
    \begin{equation*}
        \P{\abs{X_t(i, j) - \mathbb{E}\!\left[X_t(i, j)\right]} \geqslant \Delta \text{ for some } i, j} \leqslant d^2m \frac{N}{\Delta^2} + \frac{24d^3}{m} \frac{N^2}{n^2\Delta^2} t + 2dm \Exp{-\frac{\Delta^2}{32d^2m^2n}}.
    \end{equation*}

