[Lemma 47 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] Let $\ccG\! \subset \! \ccF$ be a $\sigma$-field and let $(Z_s)_{s\in \bbR_+}$ be a $\bbR$-valued continuous process. Let $s_0, \ttb \ino (1, \infty)$ and $\ttc \ino (0, \infty)$. We assume that there is 
a $\ccG$-measurable and a.s.~finite r.v. $C$ such that for all $s, s'\ino [0,s_0]$,
\begin{equation}

\textrm{$\bP$-a.s.~} \quad \bE \Big[ \big| Z_s \! -\! Z_{s'}\big|^\ttb \Big| \, \ccG \Big] \leq C |s\! -\!s'|^{1+ \ttc}. 
\end{equation}
Then, for all $\gamma \ino (0, \frac{\ttc}{\ttb} )$, we get 
\begin{equation}

\textrm{$\bP$-a.s.~} \quad  \bE \big[  \big( \mathtt{Hol}_{\gamma, s_0} (Z) \big)^\ttb  \big| \ccG\big] \leq c_{\ttb, \ttc, \gamma, s_0} C, 
\end{equation}
where $c_{\ttb, \ttc, \gamma, s_0}\eqo 2^{2\ttb} (2s_0)^{1+c-\gamma b} \big(1 \! -\! 2^{-(\frac{\ttc}{\ttb}) +\gamma} \big)^{-\ttb} $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm-representation of arXiv:2411.12623, 'Random signed measures'] A random signed measure $\xi$ on $S$ has independent increments iff a.s.
	\begin{equation}
		\xi (B)=\sum_{j=1}^p X_j\delta_{s_j}(B)+\alpha(B)+\int_{\mathbb{R}\setminus\{0\}}x\Psi(B\times dx),\quad B\in\hat{\mathcal{S}}
	\end{equation}
	where $p\in\mathbb{N}\cup\{\infty\}$, $X_1,...,X_p$ are independent real-valued random variables, $s_1,...s_p$ are fixed points in $S$, $\alpha$ is given by the difference of two deterministic atomless measures in $\mathcal{M}_S$ and $\Psi$ is a Poisson process on $S\times (\mathbb{R}\setminus\{0\})$ independent of $X_1,...,X_p$. The intensity measure of $\Psi$, which we denote by $F$, satisfies 
	\begin{equation}
		\int_{\mathbb{R}\setminus\{0\}}1\wedge|x| F(B\times dx)<\infty,\quad\textnormal{for every $B\in\hat{\mathcal{S}}$.}
	\end{equation}
	and $F(\{s\}\times (\mathbb{R}\setminus\{0\}))=0$ for every $s\in S$. Moreover, the representation ((eq-representation of the paper)) is almost surely unique. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm(\cite[Lemma 3.1]{KS2019})}
{\rm There exists an adapted  random field $g=\left\{g(s,x)\right\}_{(s,x)\in[0,T]\times[0,1]}$ such that $\mathbb{Q}$-a.s. for all $t\in[0,T]$,}
\begin{align*}
\int^{t}_0\int_0^1 g^2(s,x)\mathrm{d}s\mathrm{d}x<\infty,
\end{align*}
{\rm and $\widetilde{W}:[0,T]\times[0,1]\rightarrow\RR$ defined by}
\begin{equation}
\begin{split}
\widetilde{W}(t,x):=W(t,x)-\int^t_0\int_0^xg(s,y)\mathrm{d}s\mathrm{d}y,
\end{split}
\end{equation}
{\rm is a Brownian sheet under the measure $\mathbb{Q}$.
Moreover,}
\begin{align*}
M_t=\exp\left(\int^t_0\int^1_0g(s,x){W}(\mathrm{d}s,\mathrm{d}x)-\frac{1}{2}\int^{{t}}_0\int^1_0 g^2(s,x)\mathrm{d}s\mathrm{d}x\right),\,\,\mathbb{Q}\text{-a.s.},
\end{align*}
\begin{align}
H(\nu|\mu)=\frac{1}{2}\mathbb{E}^{\mathbb{Q}}\left[\int^T_0\int^1_0 g^2(s,x)\mathrm{d}s\mathrm{d}x\right],
\end{align}
{\rm where $\mathbb{E}^{\mathbb{Q}}$ stands for the expectation under the measure $\mathbb{Q}$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] Let $x \leq b$ and $q \geq 0$. Then
			\begin{align}
				\E_x\left[e^{-q\tau_b^+-A_{\tau_b^+}};\,\tau_b^+<\infty\right]
				= \frac{u^{(q)}_{{\mathbf{T}}(\nu_A)}(x)}{u^{(q)}_{{\mathbf{T}}(\nu_A)}(b)}.
			\end{align}
			Moreover, for any bounded, non-negative measurable function $f:\R\to\R$,
			\begin{align}
				\E_x\left[\int_0^{\tau_b^+} e^{-qt-A_t} f(X_t)\,dt\right]
				= \int_{-\infty}^b f(y)\left(
				\frac{u_{{\mathbf{T}}(\nu_A)}^{(q)}(x)}{u_{{\mathbf{T}}(\nu_A)}^{(q)}(b)}
				W_{{\mathbf{T}}(\nu_A)}^{(q)}(b,y)
				- W_{{\mathbf{T}}(\nu_A)}^{(q)}(x,y)
				\right)dy,
			\end{align}
			where $W_{{\mathbf{T}}(\nu_A)}^{(q)}$ and $u^{(q)}_{{\mathbf{T}}(\nu_A)}$ are the unique solutions to \eqref{volterra_sf_w} and \eqref{fun_u}, respectively.

