body:
[Proposition 25 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $B, C \in \widehat{\Bcal}(S)$ be disjoint such that $\pbb(\nu(B) = 0) < 1$ and $\pbb(\nu(C) = 0) < 1$, and let $A^{B \cup C}$ be a jointly exchangeable matrix associated with $\xi$ on $B \cup C$. Then there exist a random partition of $\nbb$ into subsequences $(b_i)$ and $(c_i)$ such that a.s.\
    \begin{align*}
        A^B_{ij} &\coloneqq A^{B \cup C}_{b_ib_j}, \\
        A^C_{ij} &\coloneqq A^{B \cup C}_{c_ic_j}
    \end{align*}
    are jointly exchangeable matrices associated with $\xi$ on $B$ and $C$, respectively. Moreover, the matrix $A^{BC}_{ij} \coloneqq A^{B \cup C}_{b_ic_j}$ is separately exchangeable.

[Proposition 48 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every partition $\lambda$ and every $w\in S_n$,
\begin{equation}
 \Nrm_{x,z}\bigl(H_{w,\lambda}(x,z)\bigr)\in\RV.
\end{equation}
If $\operatorname{char}(\kk)=0$ and the polynomial is nonzero, it has a
smooth integral projective realization.

[Lemma lemme compl. of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Let $\eta, \lambda_0>0$ fixed small enough. Let $\lambda \in \mathbb{C}$ such that $|\lambda|\leqslant \lambda_0$. Then, for all $\psi, F \in \mathcal{H}_\eta$ such that $|a(\psi,\psi)| \leqslant C \| F \|_{\mathcal{H}_\eta} \| \psi \|_{\mathcal{H}_\eta}$, the following inequality holds
\begin{equation}
\| \psi \|_{\mathcal{H}_\eta} \leqslant \tilde C \| F \|_{\mathcal{H}_\eta} ,
\end{equation}
where $C$ and $\tilde C$ are two positive constants that do not depend on $\lambda$ and $\eta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 191 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $f^{m}\to f$ weakly in $L_{2}(\Gamma_{i}(t_{0}))$ 
as $m\to \infty$ and $k_{1},...,k_{i}\in\{1,...,d_{1}\}$. Then
$$
 \int_{\Gamma_{i}(t_{0})}
f^{m}  (t_{1},...,t_{i})
\,dw^{ k_{i}}_{t_{i}}\cdot...\cdot dw^{ k_{1}}_{t_{1}}
\to \int_{\Gamma_{i}(t_{0})}
f  (t_{1},...,t_{i})
\,dw^{ k_{i}}_{t_{i}}\cdot...\cdot dw^{ k_{1}}_{t_{1}}
$$
weakly in $L_{2}(\Omega)$ as $n\to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn d:connective-constant-pp of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] For a graph $\Psi = \Psi(\cdot)$ on the input process $\mathcal{P}$, the  
 {\em averaged connective constant} $\bar{\Delta} \in [0,\infty]$
is defined as 
\begin{equation}
\bar{\Delta} := \inf\Bigl\{\delta\ge 0: \forall\, p \in \mathbb{N} \;  \exists \, m_p \in \mathbb{N} \text{\ such that for all $m\ge m_p$}, \,
\mathfrak{n}_{p}(m)\le \delta^m\Bigr\},
\end{equation}
where \begin{equation}
\mathfrak{n}_p(m):=\sup_{B\in\mathcal{B}_b(r_0,n_0)}\sup_{x_1,\ldots, x_p\in B}
  \mathbb {E} _{\bk x1p}[N(x_1, m; \Psi(\mathcal{P}\cap B))],
\end{equation}
 with \(N(x_1, m;\Psi(\mathcal{P}\cap B))\) being the number of  self-avoiding paths of length \(m\) starting from \(x_1 \in \mathcal{P} \cap B\) in  $\Psi(\mathcal{P}\cap B)$, where $\mathcal{B}_b(r_0,n_0)$, defined in~(equation e.particular-sets of the paper), are the sets of the form large windows
$W_n$, possibly intersected with finite unions of balls of sufficiently large
radius.

[Proposition prop:cp-upper of arXiv:2607.00731, 'Sharp Asymptotics for the Largest Component in the Subcritical Regime of Preferential Atta'] Let $(d_n)_{n\ge 1}$ be deterministic degree sequences, and write
\(\ell_n = \ell(\mathbf d_n)\), \(D_n = D_{\mathbf d_n}\),
\(\Delta_n = \Delta(\mathbf d_n)\), and \(\phi_n = \phi_{\mathbf d_n}\).

Assume that:
\begin{enumerate}
\item $D_n \Rightarrow D$ for some random variable \(D\) taking values in \(\mathbb Z_{\ge0}\);
\item $Q(d_n)\to 0$;
\item $\mathbb P(D=0)>0$ and $\mathbb P(D=1)>0$;
\item $\mathbb P(D_n=0)>0$ and $\mathbb P(D_n=1)>0$ for all large $n$;
\item $\mu_4(d_n)\le \Delta_n^{1/2}$ and $\Delta_n\le n^{1/6}$ for all large $n$.
\end{enumerate}
Assume further that, for all large $n$, the equation $\phi_n'(\theta)=0$ has a smallest positive solution $\theta_n\in(0,1)$, and define
\begin{equation}
T_n:=\frac{1}{-\log\phi_n(\theta_n)}
\left[
\log n+\frac{3}{2}\log\bigl(-\log\phi_n(\theta_n)\bigr)
-\frac12\log\phi_n''(\theta_n)
+\log\mathbb E\!\left(D_n e^{\theta_n D_n}\right)
\right].
\end{equation}
If $\theta_n\ell_n/T_n\to\infty$, then for every fixed $\delta>0$,
\begin{equation}
\mathbb P\bigl(L_1(\mathrm{CM}(d_n))\le (1+\delta)T_n\bigr)\to 1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] Define the finite measure
\[
\mu_2(A)=\E\bigl[S^2\mathbf 1_{\{S\in A\}}\bigr].
\]
Then $\mu_2\ll \nu$, and the density ratio is
\begin{equation}
r(s)=\frac{d\mu_2}{d\nu}(s)
=\frac{s}{\sigma\sqrt{2\pi}}
\left(
 e^{-\frac{(y(s)-h)^2}{2\sigma^2}}+e^{-\frac{(y(s)+h)^2}{2\sigma^2}}
\right).
\end{equation}
If $h\le \sigma^2$, then $r$ is increasing on $(0,1)$.

[Lemma 30 of arXiv:2608.15805, 'Spectral duality structures and the Fisher--Rao geometry of reset distributions'] $\widetilde P$ is the symmetric tridiagonal matrix with constant
off-diagonal $\sqrt{pq}$; it commutes with $S$. Its eigenpairs are
\begin{equation}
v_k(z)=\sin(\pi k z/a),\qquad
\lambda_k = 2\sqrt{pq}\,\cos(\pi k/a),\qquad k=1,\dots,a-1,

\end{equation}
and each eigenvector has definite parity under the reflection,
\begin{equation}
S v_k = (-1)^{k+1} v_k,

\end{equation}
so $v_k$ is odd for $k$ even and even for $k$ odd.

