[Corollary 20 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $(\mathbf{x}_t)_{t\geq 0}$ be a solution to \eqref{eq:fast system simplified} in the setting \nameref{S2} with non-null $\Sigma$. Then, for almost every $\tau\ge0$, it holds that
\begin{align*}
    &\left| AC_\infty(\tau)\left[\mathbf{v}\right]
    - \left( c_1(\lambda^*) e^{-i B(\lambda)\tau}
    + c_2(\lambda^*) e^{i B(\lambda)\tau} \right)
    \right|\\
    =& \cO\left(-A(\lambda)\right) + \cO\left(\left|\left| \mathbf{e}_1^*(\lambda) - \mathbf{e}_1^*(\lambda^*) \right|\right| \right) + \cO\left(\left|\left| \mathbf{e}_2^*(\lambda) - \mathbf{e}_2^*(\lambda^*) \right|\right| \right)
\end{align*}
for any $\mathbf{v}$ in a dense subset of $\R^2$ and in the limit $\lambda\to\lambda^*$. The complex parameters $c_j(\lambda)$ are defined for any $j\in\{1,2\}$ and $\lambda\leq \lambda^*$ by
\begin{align*}
    c_j(\lambda):= \frac{ \left|\left\langle \mathbf{v}, \mathbf{e}_j(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_j^*(\lambda) \right|\right|^2}{ \left|\left\langle \mathbf{v}, \mathbf{e}_1(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_1^*(\lambda) \right|\right|^2 + \left|\left\langle \mathbf{v}, \mathbf{e}_2(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_2^*(\lambda) \right|\right|^2},
\end{align*}
for $\mathbf{v}$ in the dense subset mentioned above. Moreover, we have that
\begin{align*}
    AC_\infty(\tau)\left[\mathbf{v}\right] =& c_1(\lambda^*) e^{-i B(\lambda^*)\tau}
    + c_2(\lambda^*) e^{i B(\lambda^*)\tau} + \cO\left(-A(\lambda)\right) \\
    &+ \cO\left(\left|\left| \mathbf{e}_1^*(\lambda) - \mathbf{e}_1^*(\lambda^*) \right|\right| \right) + \cO\left(\left|\left| \mathbf{e}_2^*(\lambda) - \mathbf{e}_2^*(\lambda^*) \right|\right| \right) + \cO\left( |B(\lambda)-B(\lambda^*)| \right) .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

