body:
[Lemma 12 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] There exist $C=C_d>1$ and a stationary $\frac 1{8}$-Lipschitz random field $\rd\ge 2$ such that:
    \begin{itemize}
        \item For all $x\in\ZZ^d$ and $R\ge r_\diamond(x)$,
            \begin{gather}
                \Big(\fint_{\BB_R(x)}a_e^{d+1}\Big)^{\frac1{d+1}} \le C\expec{a^{d+1}}^{\frac1{d+1}};\quad
\Big(\fint_{\BB_R(x)}a_e^{-(d+1)}\Big)^{\frac1{d+1}}\le C\expec{a^{-(d+1)}}^{\frac1{d+1}}.
            \end{gather}
            \item   $\rd$ satisfies the following moment bound: there exists $c_0>0$ such that
            \begin{equation}
		\expec{r_\di^{c_0\gamma}}^{\frac1\gamma}\lesssim  \gamma^{\frac1{d+1}}\Gamma^{2}.
            \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj local curve GW vs M2 of arXiv:2609.02409, 'Membranes and Maps'] ((conj:GW:vertex of the paper), $n=1$) For every Calabi--Yau local curve over $\bP^1$ equipped with a Calabi--Yau $\mathsf{T}$-action, we have
    \begin{equation}

        \GWargs{Z}{\mathsf{T}}{[\bP^1]}
        =
        \hat{\mathsf{A}}_{\mathsf{T}}\Big( \overline{M}_{0}\big(Z,[\bP^1]\big) \Big) \,.
    \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem 3 (Sufficient conditions of  \cref{ass:predictive-stability}) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Let $\Theta\subset\R^d$ be convex and compact. Suppose that, for every $t$, almost surely, the map $\ell_t(\cdot;(x,y))$ is continuously differentiable on a neighborhood of $\Theta$ for almost every conditional realization $(x,y)$ of $(X_t,Y_t)$, and there are nonnegative $\cG_t$-measurable envelopes $H_t,G_t,D_t$ such that
     \begin{align}
     \|\nabla\ell_t(\theta;(X_t,Y_t))-\nabla\ell_t(u;(X_t,Y_t))\|
     &\le H_t\|\theta-u\|,\qquad \theta,u\in\Theta, \\
     \sup_{\theta\in\Theta}\|\nabla\ell_t(\theta;(X_t,Y_t))\|
     &\le G_t,\\
     \sup_{\theta,u\in\Theta}|\ell_t(\theta;(X_t,Y_t))-\ell_t(u;(X_t,Y_t))|
     &\le D_t.
    \end{align}
Assume that there exists an absolute constant $C_{\rm env}>0$ such that
    \begin{equation}
    \E\sbr{\e^{\eta D_t}(H_t+\eta G_t^2)\mid\cG_{t-1}}
    \le C_{\rm env}\qquad
    \text{a.s. for every }t\in\bN.
    \end{equation}
Moreover, assume that there exists $\theta^\star\in\operatorname{int}(\Theta) $ such that
    \begin{equation}
    \E[\nabla\ell_t(\theta^\star;(X_t, Y_t))\mid\cG_{t-1}]=0
    \qquad\text{a.s.}
    \end{equation}
Then \cref{ass:predictive-stability} holds for all probability measures supported on $\Theta$, with a deterministic constant depending only on $C_{\rm env}$, $\eta$, and $\operatorname{diam}(\Theta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:W as a sum of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ be such that $(\log^{3/2}n)/\sqrt{n}\ll\mu\ll n$ and {recall $t_{\mu/n}=\argmin_{t \in (0,2)}\lambda_{\mu/n}(t)$.}
    Then, for any $\epsilon_n\ll1$ such that $(\mu^2n)^{1/3}\epsilon_n^2\gg\log n$ and $\epsilon\gg(\mu/n)^{1/3}$ (which are both possible thanks to the assumption on $\mu$) the sum $W_n$ defined in~(equation eq:def W of the paper) satisfies
    \begin{align*}
        W_n=\big(1+o(1)\big)\frac{\mu}{2n}e^{-n\lambda_{\mu/n}(t_{\mu/n})}\sum_{|m-t_{\mu/n}|<\epsilon_nt_{\mu/n}}\exp\left(-\left(\frac{3}{2}+o(1)\right)\left(\frac{\mu^4}{2\pi^2n}\right)^{1/3}\big(m-t_{\mu/n}\big)^2\right)\,,
    \end{align*}
    where the $o(\cdot)$ in the exponential are uniform over all terms of the sum.

