[Corollary cor:realbranches of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $\mathcal C\subset X(M)$ be the irreducible algebraic curve obtained from Theorem (thm:main of the paper), and let $x\in\widetilde{\mathcal C}\setminus\mathcal C$ be the corresponding ideal point. Then $x$ is a real point of $\widetilde{\mathcal C}$, and there is a holomorphic local coordinate at $x$, defined over $\mathbb R$, whose restriction gives a signed real analytic coordinate
\begin{equation*}
	t:(\widetilde{\mathcal C}(\mathbb R),x)\longrightarrow(\mathbb R,0)
\end{equation*}
such that, after shrinking the parameter interval, the following hold for every $t\neq0$:
\begin{enumerate}
	\item the corresponding character $\chi_t\in X(M)$ is real-valued and irreducible;
	\item if $\mu$ is a knot meridian, then $I_\mu(t) = \chi_t(\mu) = 2+Qt^2+O(t^3)$ for some $Q>0$;
	\item $\chi_t$ is the character of an irreducible representation $\rho_t:\pi_1(M)\longrightarrow SL_2(\mathbb R)$
\end{enumerate}

[Defn 6 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] We define $\mathscr{S}'_p(\R^{d})$ as the set of tempered distributions that are $\Z^d$ periodic in frequency, that is, the set of $u\in \mathscr{S}'(\R^d)$ such that,
\begin{equation*}
    \forall n\in \Z^d, \m\m\m\tau_{n}\mc{F}_{h}(u)=\mc{F}_{h}(u).
\end{equation*}

[Lem rarity-of-disagreement-regions of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $M_0(d)$ such that for all $M\ge M_0$ the following holds. Suppose that $\mathbb P(\widetilde{D}_{k-1}(B') =1)\le q_{k-1}$ for all $B' \in \mathscr{B}_{k-1}$. Then for every $B \in \mathscr{B}_k$, one has 
    \begin{align*}
        \mathbb P(|\mathsf{Dis}_{k-1}(B)|>s_k ) \le q_k/10\,.
    \end{align*}

[Prop 25 of arXiv:2607.27535, 'Universal topological statistics on \\ triangulated singular spaces'] The set $k \cdot \ordsimp{d}$ triangulates into FK-simplices as follows:
    \begin{align} 
        k \cdot \ordsimp{d} = \bigcup_{I \subseteq \indexset{d-1}} \bigcup_{\substack{\vecbf n \in \vecbf N_{d, k} [I] \\ \permelt \in \permgrp_d [I]}} (\vecbf n + \permelt \ordsimp{d})
    \end{align}
    where $\vecbf N_{d, k} [I] \subset \ZZ^d$ and $\permgrp_d [I] \subseteq \permgrp_d$ are defined as:
    \begin{align*}
        \vecbf N_{d, k} [I] =& \bigg\{(n_1, \ldots n_d) \in \ZZ^d \>\bigg|\> k-1 \ge n_1 \ge \cdots \ge n_d \ge 0 \text{, and } (i \in I \iff n_i = n_{i+1}) \bigg\} \\
        \permgrp_d [I] =& \bigg\{ \permelt \in \permgrp_d \>\bigg|\> i \in I \implies \permelt^{-1}(i) < \permelt^{-1}(i+1) \bigg\}
    \end{align*}

