[Theorem existencUnicit of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let $\mathcal{L}$ be a regular Lagrangian. 
Then a smooth curve $\gamma = (x_1, \ldots, x_n)$ is an $\mathcal{L}$-geodesic if and only if it satisfies
\begin{equation}
\frac{d^2 x_i}{dt^2} 
+ \sum_j g^{ij}(v) 
\left(
  \frac{\partial^2 \mathcal{L}}{\partial v_j \partial x_i} \frac{d x_i}{dt} 
  - \frac{\partial \mathcal{L}}{\partial x_j}
\right) = 0,
\end{equation}
where $g^{ij}(v)$ denotes the inverse matrix of 
$g_{ij}(v) = g_v^{\mathcal{L}}\!\left(\frac{\partial}{\partial x_i}, \frac{\partial}{\partial x_j}\right)$.
In particular, for each $v \in \mathcal{U}$ there exists a unique maximal $\mathcal{L}$-geodesic $\gamma_v : I_v \to M$ such that $\gamma_v'(0) = v$ and $0 \in I_v$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thmISPHyper of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ h \in L^{2}_{\mathbb{F}}(0,T; H^{1}(G')) $, $ g \in L^{2}_{\mathbb{F}}(0,T; H^{1}(G)) $ and $ R \in C^{3}(\overline{Q}) $ satisfy 
\begin{align}

    |R(t, x)| \neq 0 \quad \text { for all }(t, x) \in  [0,T] \times \overline{G}.
\end{align}
If $ z \in \mathbb{H}_{T} $ satisfies (systemHyper of the paper) and 
\begin{align*}
    & \frac{\partial z}{\partial \nu} = \frac{\partial z_{x_{1}}}{\partial \nu} = 0 \quad \text { on }(0, T) \times \partial G, ~ \text{${\mathbb{P}}$-a.s.},  \\
    & z(T) = z_{t}(T) =0  \text { in } G, ~ \text{${\mathbb{P}}$-a.s.},  \\
    &
\end{align*}
then 
\begin{align*}
    h (t, x^{\prime} )=0 & \text { for all } (t, x^{\prime} ) \in(0, T) \times G^{\prime},~ \text{${\mathbb{P}}$-a.s.}  \\
    g(t, x)=0 & \text { for all }(t, x) \in(0, T) \times G, ~ \text{${\mathbb{P}}$-a.s.} 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] For any deviation vector $\eta_\tau$ such that $\tau\neq \emptyset$, 	we define $
	\mathsf{Proper} \mathcal{L}^*(w_\tau)$ to be the weighted linear combination of the following terms in the $3$-way concatenation in $\frac{1}{1-\gamma}\cdot  \mathcal{L}^*(w_\tau)$:
	\begin{enumerate}
		\item Proper concatenations such that each non-trivial gadget in $A^{-1}$-path is an $\alpha$-gadget;
		\item Linearization of well-behaved intersections such that each non-trivial gadget in $A^{-1}$-path is an $\alpha$-gadget.
	\end{enumerate}
	It is important to distinguish between $\mathsf{Proper}(\eta_\tau)$ and $\mathsf{Proper}\mathcal{L}^*(w_\tau)$.

[Corollary 40 (Alternative entropy-based uniform-in-time $W_2$ bounds) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target},
\ref{ass:W2}, \ref{ass:concentration}, and \ref{ass:initial-T2},
\begin{equation}
    \sup_{t\ge0}\E W_2^2(\mu_t^N,\mu_t)
    \le C\left\{
       N^{-2\varepsilon\alpha/
          (L_{\mathrm{ent}}+2\varepsilon\alpha)}
       +r_{N,d}\right\}
    \le C\left\{
       r_{N,d}^{\,2\varepsilon\alpha/
          (L_{\mathrm{ent}}+2\varepsilon\alpha)}
       +r_{N,d}\right\}.
\end{equation}
Moreover, for fixed $k$ and $N\ge2k$,
\begin{equation}
    \sup_{t\ge0}W_2^2(P_{N,t}^{(k)},\mu_t^{\otimes k})
    \le C_k\left\{
       N^{-2\varepsilon\alpha/
          (L_{\mathrm{ent}}+2\varepsilon\alpha)}
       +N^{-1}\right\}.
\end{equation}

