[Theorem thm:lattice2 of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] Assume that $\mathbf E|X|^{r+3}$ is finite for some integer $r \ge 1$.
Assume also that $S_n$ is integer valued with maximal span $1$. Then there exist polynomials $\overline{P}_1$, $\overline{P}_2$,\ldots, $\overline{P}_{r+1}$ such that
\begin{align*}
    \mathbf P(S_n=x,\overline{\tau}>n) 
=
    e^{-\frac{x^2}{2\sigma^2n}}
    \sum_{\nu = 2}^{r+1}
        \frac{\overline{P}_\nu(x/\sigma\sqrt{n})}{n^{\nu/2}} 
+
    O\left( \frac{1}{\min (n^{(r+2)/2}, x^{r+2})} \right).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2609.03418, 'Sampling and Density Theorems for the Fractional Opdam--Cherednik Transform'] Let $\alpha \geq \beta \geq -\frac{1}{2}$ with $\alpha > -\frac{1}{2}$. The Opdam--Cherednik transform $\mathcal{H}_{\alpha, \beta} (f)$ of a function $f \in C_c(\R)$ is defined by
\begin{equation} \H_{\alpha, \beta} (f) (\lambda)=\dint_{\R} f(x)\; G^{\alpha, \beta}_\lambda(-x)\; A_{\alpha, \beta} (x) dx \quad \text{for all } \lambda \in \C. \end{equation}
The inverse Opdam--Cherednik transform for a suitable function $g$ on $\R$ is given by
\begin{equation} \H_{\alpha, \beta}^{-1} (g) (x)= \dint_{\R} g(\lambda)\; G^{\alpha, \beta}_\lambda(x)\; d\sigma_{\alpha, \beta}(\lambda) \quad \text{for all } x \in \R, \end{equation}
where $$d\sigma_{\alpha, \beta}(\lambda)= \left(1- \dfrac{\rho}{i \lambda} \right) \dfrac{d \lambda}{8 \pi |C_{\alpha, \beta}(\lambda)|^2}$$ and
$$C_{\alpha, \beta}(\lambda)= \dfrac{2^{\rho - i \lambda} \Gamma(\alpha+1) \Gamma(i \lambda)}{\Gamma \left(\frac{\rho + i \lambda}{2}\right)\; \Gamma\left(\frac{\alpha - \beta+1+i \lambda}{2}\right)}, \quad \lambda \in \C \setminus i \mathbb{N}.$$

[Lemma 56 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] At the $t$th stage inside row $B_a$, whose global stage is
$e=b_a+t-1$ and whose colour is $i_e=a+t-1$, one has
\begin{equation}
 R_{i_e+1}^{(e-1)}
 =p_{e-1,b_a-1}^*R_{a+t}^{\langle a\rangle},
\end{equation}
where $p_{e-1,b_a-1}:X_{e-1}\to X_{b_a-1}$ is the tower projection.

[Lem 39 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma \geq 2$ and $0 \leq s \leq t \leq T$. For every $n \in \mathbb{N}_+$, it holds 
	\begin{align} 
		\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{n \sqrt{n} } \int_s^t \dd r  \sum_{x} \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n})     \bar{\xi} _x^{\alpha}( \eta_r^n )  \bar{\xi} _{x+1}^{\beta}( \eta_r^n )   \Bigg\}^{2} \Bigg] \leq \widetilde{C} \| \nabla H \|^{2}_{2,n} (t-s)^{3/2} [ K_n \sqrt{n} \;]^{2}.
	\end{align}

