[Lemma 38 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] The following facts hold for all $p \in (0,1)$.
\begin{enumerate}[(a)]
    \item For each $v$ in $\cH$ and each $k \geq 0$, we have
    \begin{align}
        \E[\phi_v^k] &= \left(1 - \frac{2^k-1}{2^k} p\right)^d, \\
        \Var(\phi_v^k) &= \E[\phi_v^{2k}](1 - o(1)).
    \end{align}

    \item For each $k \geq 0$, we have
    \begin{align}
        \E[\Phi_k] &= \mu_1^k, \\
        \Var(\Phi_k) &= \mu_1^{2k} (1-o(1)).
    \end{align}
\end{enumerate}

