    \begin{align*}
        L_{\rm w,\mathsf{x}}^2 \lesssim \beta^6 h^{10}\,, \qquad
        L_{\rm w, \mathsf{p}}^2 \lesssim \beta^4 h^8\,, \qquad L_{\rm s,\mathsf{x}}^2 \lesssim \beta^4 h^6\,, \qquad L_{\rm s, \mathsf{p}}^2 \lesssim \beta^2 h^4\,.
