[Lem 10 (Analytical properties of $M_n$ and $M^*_n$) of arXiv:2604.06122, 'REM universality for linear random energy'] Fix $h\in \mathbb{R}^n\setminus \{0\}$. Then $\MGF$ $M_{n}(h,\cdot)$ is continuous, infinitely differentiable, and verifies the following properties
 \begin{enumerate}
 \item $M_{n}(h,0)=M'_{n}(h,0)=0$;
 \item $M''_n(h,\lambda)>0$ for any $\lambda\in \R$;
 \item $\{M'_n(h,\lambda):\, \lambda \in \R_{> 0}\}= (0,\Sigma_n(h))$;
 \item there exists a continuous increasing function $\Lambda_n(h,\cdot ):[0,\Sigma_n(h))\to \R_{\geq 0}$ such that
\begin{equation}

M'_{n}(h,\Lambda_n(h,a))=a;
 \end{equation}
Moreover $\Lambda_n(h,0)=0$ and $\Lambda_n(h,(0,\Sigma_n(h)))=\R_{> 0}$.
\end{enumerate}
The $\FLT$ $M^*_n(h,\cdot)$ satisfies
 \begin{enumerate}
 \setcounter{enumi}{4}
 \item for any $a\in (0,\Sigma_{n}(h))$
 \begin{equation}

M^*_{n}(h,a)=\Lambda_n(h,a) a-M_{n}(h,\Lambda_n(h,a)),\qquad \dot M^*_n(h,a)=\Lambda_n(h,a),
 \end{equation}
 and
 \begin{equation}

 \ddot M^*_n(h,a)=\dot \Lambda_n(h,a)=\frac{1}{M''_n(h,\Lambda_n(h,a))};
 \end{equation}
 \item $M^*_n(h,\cdot)$ is strictly increasing in $[0,\Sigma_{n}(h))$;
 \item $M^*_n(h,(0,\Sigma_{n}(h))\,)=(0,\Gamma_{n}(h))$ and $M^*_n(h,\Sigma_{n}(h)\,)=\Gamma_{n}(h)$;
 \item there exists a continuous increasing function $A_n(h,\cdot):(0,\Gamma_n(h))\to (0,\Sigma_n(h))$ such that
 \been{

 M^*_n(h,A_n(h,c))=c,\quad \forall c\in (0,\Gamma_n(h)).
 }
 \end{enumerate}

