[Lemma only_one_vertex_connection_set_lower_bound_technical_calculation of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Let $\mathbf x$ be a choice sequence that satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper)  and let $d=d(n),k=k(n)\in\mathbb{N}$.  Then,
\begin{equation}
\mathbb{P}(u_n(v)-\widetilde{u}_n(v)> k,\deg_n(v)\geq d)\leq\theta^{-d} \mathbb{P}(u_n(v)-\widetilde{u}_n(v)> k).
\end{equation}

[Proposition prop:moment-identities of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $A=(a_i)$ and $B=(b_i)$ be the spoke and rim labels of a geodesic Leech labeling. Then
\begin{equation}
  (m-2)\sum_i a_i+3\sum_i b_i=\frac{N(N+1)}2,
\end{equation}
\begin{equation}
  \sum_{t\in T(A)}t=3\sum_i b_i,
\end{equation}
and
\begin{equation}
\begin{aligned}
  \frac{N(N+1)(2N+1)}6
  ={}&\left(\sum_i a_i\right)^2
  +(m-3)\sum_i a_i^2
  -2\sum_i a_i a_{i+1}\\
  &+3\sum_i b_i^2
  +2\sum_i b_i b_{i+1}
\end{aligned}
\end{equation}
hold. In particular,
\[
  \sum_{t\in T(A)}t\equiv0\pmod3.
\]

[Theorem 74 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] We have
\begin{equation}

 \|\Psi^{-1}_{\lambda} g_{\cA}\|_{L_{d/(d-1)}(\bR^{d}) } 
\le N(d,\delta)\lambda^{-1/2}P(\cA ),
\end{equation}
where   $\Psi _{\lambda}( x)=\exp(- \sqrt{\lambda}
  |x| \sfp_{0}/16)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: old bsbt of arXiv:2507.04505, 'Heights of butterfly trees'] If $\boldsymbol{\pi}_n \sim \operatorname{Unif}(\operatorname{B}_n)$, then $\operatorname{LIS}(\boldsymbol{\pi}_n) \sim X_n$ follows a distributional recurrence defined by $X_0=1$ and $X_{n+1} \sim (X_n + X_n')\eta_n + \max(X_n,X_n')(1 - \eta_n)$ for iid $X_n \sim X_n'$ independent of $\eta_n \sim \operatorname{Bern}(\frac12)$ for $n \ge 0$. Additionally, there exist constants $\alpha = \log_2(3/2) \approx 0.58496$ and $\beta \approx 0.83255$ such that $N^\alpha \le \mathbb{E} \operatorname{LIS}(\boldsymbol{\pi}_n) \le N^\beta$. Furthermore, $C(\boldsymbol{\pi}_n) \sim Y_n$ follows a distributional recurrence defined by $Y_0 = 1$ and $Y_{n+1} \sim Y_n + \eta_n Y_n'$ for iid $Y_n \sim Y_n'$ independent of $\eta_n \sim \operatorname{Bern}(\frac12)$ for $n\geq 0$. Lastly, $C(\boldsymbol{\pi}_n)/N^\alpha \to_d W$, where $W$ takes values in $[0,\infty)$ and is uniquely determined by its positive integer moments $m_k = \mathbb{E} W^k$: these moments satisfy $m_1 = 1$ and
    $$m_{k} = \frac{\lambda - 1}{\lambda^k - 1} \sum_{j=1}^{k-1} \binom{k}j m_j m_{k-j}$$
    for $k\geq 2$, where $\lambda = 2^\alpha = 3/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

