[Lemma 30 (Integral Asymptotics 2) of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] If $\rho=0$ (which also implies $H_0>1/2$),
there exists a continuous and bounded function $\msf b:(0,\infty)\to\mbb R$ such that
\begin{align}

\msf J(\th)=
\begin{cases}
4\Ga(H_0)\Ga(1-H_0)\ell(\th)+\msf b(\th)&1/2<H_0<1,\\
4\big((1+\th)\log(1+1/\th)-1\big)& H_0=1,
\end{cases}
\end{align}
where we recall the definition of $\ell$ in \eqref{Equation: ell function}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma1 of arXiv:2411.18775, 'Limit Theorems for the Dynamical Foundation of the Fractional Brownian Motion and Related '] Fix any $t_0>0$. Let $(X^N_t)_{t\in[0,t_0]}$ be the solution of  system~(equation final system of the paper) and $(\widetilde{X}^N_t)_{t\in[0,t_0]}$ be the process given in formula~(equation eq:MyX of the paper). Under Assumptions~(asmp:coef of the paper),~(asmp:m of the paper),~(assmp:u0 of the paper),~(assmp:coef2 of the paper), we have with a suitable constant $C>0$
		\begin{align}
			\mathbb{E}\left[\sup\limits_{t\in[0,t_0]} \left| X^N_t -  \widetilde{X}^N_t  \right|^2   \right]\leq C v(t_0)t_0^2N^{-2(b-d)}\exp\left( C N^{-2(b-d) t_0^2} \right)\longrightarrow 0,
		\end{align} 
         as $N\to\infty$.

[Lemma eq:nondesc of arXiv:2606.30475, 'Ancestries in random $d$-DAGs'] As $n\to\infty$, the expected number of non-descendants of $n$ in $G_n$ among the first $m$ vertices satisfies
 \begin{equation}
  \mathbb{E} \big|[m]\setminus D_n\big| \to \frac{1}{d+1}\alpha^{d+1}
 \end{equation}
 for $m\sim \alpha n^{\frac{d-1}{d+1}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] For the sequence of stopping times
			\begin{align}
				\tau^k_m:=\inf\left\{t\in[0,T]:\|u_m(t)\|_{H_0^1(\bO)} + \|u_m(t)\|_{L^p(\bO)}\geq k\right\},
			\end{align}
			where $k\in\N$, the solution of the SDE \eqref{eqn-Faedo-Galerkin} lie on manifold $\bM$, i.e., $u_m(t\wedge\tau^k_m)\in\bM$ for all $t\in[0,T]$.

[Lem sparse-giant-nearby of arXiv:2606.01627, 'The geometry of the giant component of random geometric graphs'] Fix $\beta,\varepsilon >0, \lambda_0 > \lambda_c$ and $x \in M$.      There are constants $c = c(\lambda_0,d,\varepsilon,\beta,M) > 0$ and $n_0 = n_0(\lambda_0,d,\varepsilon,\beta,M), L' = L'(\lambda_0,d,\varepsilon)$ so that if $r \leq n^{-\beta}$ and $\lambda \geq \lambda_0$ then the following holds. 
    The event
    \[
    \mathcal{C}:=
    \left\{
        \begin{array}{c}
        \text{there exists a connected component }
        \kappa \text{ of } G^-(r) \\
        \text{such that }
        \forall p \in \mathring{G}^{n}_M(r) \cap B_M(x,\delta/L'),
        \exists p' \in \kappa  \\ 
        \mbox{ such that }
        d^\lambda_r(p,u^{-1}(p')) \le \log^2 n
        \end{array}
    \right\}
    \]
    satisfies
    $\mathbb{P}(\mathcal{C}^c) \leq \exp(- c \log ^2n)$ for all $n \geq n_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:double-edge-integration of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] For any matrices $A,B \in \R^3$, if $Q \sim \mrm{Haar}(\mrm{SO}(3))$, then
    \begin{equs}
        \E[\mrm{Tr}(AQ)\mrm{Tr}(Q^*B)]=\frac{1}{3}\mrm{Tr}(AB)
    \end{equs}

