[Proposition 20 of arXiv:2609.02444, 'The Hasse norm principle for $A_4$-quartic extensions of global function fields'] \begin{enumerate}
  \item There exists $\lambda\in\mathbb{Z}_{>0}$ such that for all \(a,b,n_2,n \in \ZZ_{\geq 0}\) with $a+b+n_2=n$, 
    \[ |V(a,b,n_2)/{\mathbb{B}_n}| \leq \lambda.\]
   \item There exists $M\in\mathbb{Z}_{>0}$ such that for all \(a,b,n_2, n \in \ZZ_{\geq 0}\) with \(a,b,n_2 \geq M\) and $a+b+n_2=n$,
    \[ |V(a,b,n_2)/{\mathbb{B}_n}| = \begin{cases} 1 & \text{ if } a \equiv b \pmod 3 \\
    0 &\text{ otherwise.}
  \end{cases}\]
  \end{enumerate}

[Proposition 10 of arXiv:2609.03339, 'Exterior Serrin Rigidity for the Homogeneous \texorpdfstring{$k$}{k}-Hessian Equation\\'] Let $\Omega\subset\R^n$ be smooth,
		bounded, strictly star-shaped, and strictly $(k-1)$-convex.
Then the normalized exterior problem has a unique \(k\)-admissible solution \[ u\in C^{1,1}_{\mathrm{loc}}(\overline E), \qquad E=\mathbb R^n\setminus\overline\Omega, \]   
in each of the following classes: 
\begin{equation}
 \text{When}~q>1,
			\begin{cases}
				\sigma_k(D^2u)=0&\text{in }~\R^n\setminus\overline\Omega,\\
				u=-1& \text{on}~\partial\Omega,\\
				u(x)\to 0&\text{as}~|x|\to\infty.
			\end{cases}
		\end{equation}	
\begin{equation}
\text{When}~q=1,
			\begin{cases}
				\sigma_k(D^2u)=0&\text{in }~\R^n\setminus\overline\Omega,\\
				u=0& \text{on}~\partial\Omega,\\
				u(x)-\log|x|=O(1)&\text{as }|x|\to\infty.
			\end{cases}
		\end{equation}	
        \begin{equation}
    \text{When}~0<q<1,
			\begin{cases}
				\sigma_k(D^2u)=0&\text{in }~\R^n\setminus\overline\Omega,\\
				u=1& \text{on}~\partial\Omega,\\
				u(x)-|x|^\alpha=O(1)&\text{as }|x|\to\infty.
			\end{cases}
		\end{equation}	

        The solution is the local \(C^1\)-limit on \(\overline E\) of smooth strictly admissible solutions $u_{\varepsilon
        }$ of the nondegenerate equations 
        \begin{equation}
        \text{When}~q>1,
			\begin{cases}
				\sigma_k(D^2u_{\varepsilon})=F_{\varepsilon}&\text{in }~\R^n\setminus\overline\Omega,\\
				u_{\varepsilon}=-1& \text{on}~\partial\Omega,\\
				u_{\varepsilon}(x)\to 0&\text{as}~|x|\to\infty.
			\end{cases}
		\end{equation}	

\begin{equation}
 \text{When}~q=1,			\begin{cases}
				\sigma_k(D^2u_{\varepsilon})=F_{\varepsilon}&\text{in }~\R^n\setminus\overline\Omega,\\
				u_{\varepsilon}=0& \text{on}~\partial\Omega,\\
				u_{\varepsilon}(x)-\log|x|=O(1)&\text{as }|x|\to\infty
			\end{cases}
		\end{equation}	
        \begin{equation}
\text{When}~0<q<1,		\begin{cases}
				\sigma_k(D^2u_{\varepsilon})=F_{\varepsilon}&\text{in }~\R^n\setminus\overline\Omega,\\
				u_{\varepsilon}=1& \text{on}~\partial\Omega,\\
				u_{\varepsilon}(x)-|x|^\alpha=O(1)&\text{as }|x|\to\infty
			\end{cases}
		\end{equation}	
with right-hand side \[ F_\varepsilon(x) =c_{n,k,q}\varepsilon^2 \bigl(|x|^2+\varepsilon^2\bigr)^{-n/2-1}. \] 
There exists \(C\ge1\), independent of
\(0<\varepsilon\le\varepsilon_0\) and of the truncation radius \(R\),
such that
\begin{equation}
\begin{gathered}
\begin{cases}
 C^{-1}|x|^{1-q}\le -u_\varepsilon(x)\le C|x|^{1-q},
     &q>1,\\
 |u_\varepsilon(x)-\log |x||\le C,
     &q=1,\\
 |u_\varepsilon(x)-|x|^{1-q}|\le C,
     &0<q<1,
\end{cases}\\
 C^{-1}|x|^{-q}\le |Du_\varepsilon(x)|\le C|x|^{-q},
 \qquad
 |D^2u_\varepsilon(x)|\le C|x|^{-q-1}.
\end{gathered}
\end{equation}

Finally, all integrations by parts below are valid for the approximants and pass to the limit by the uniform estimates and asymptotics.
After translating a strict star center to the origin, there exists a positive constant $c_0$ independent of $\varepsilon$ such that
\begin{equation} x\cdot Du_{\varepsilon}(x)\geq \begin{cases} c_0,&q=1,\\ c_0|x|^{1-q},&q\ne 1. \end{cases} \end{equation} 
The corresponding transformed approximants satisfy \begin{equation} \sup_E \left| v_\varepsilon^{n+1} Dv_\varepsilon\cdot Da_\varepsilon \right| \longrightarrow0. \end{equation} 
If \(|Du|=c>0\) on \(\partial\Omega\), then
\[
\|\,|Du_\varepsilon|-c\,\|_{L^\infty(\partial\Omega)}
\longrightarrow0.
\]
In particular,
\[
\max_{\partial\Omega}|Du_\varepsilon|\longrightarrow c.
\]
The corresponding statements with an arbitrary positive logarithmic or power-growth coefficient follow by a positive affine rescaling.

