body:
[Corollary 24 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu \in \mathcal{M}_F(\mathbb{R}^d)$ and $\gamma > 0$. Let $(\mathcal{X}_r)_{r \geq 0}$ be an $\text{SBM}(\gamma)$ started from $\mu$ on a probability space $(\Omega, \mathcal{F}, \mathbb{P}_\mu)$. Then $\mathbb{P}_{\mu}$-a.s. there exists $N<\infty$ such that for any $s$, $t \geq 0$ with $0 \leq t-s<1$ we have that
    \begin{equation*}
        \overline{\bigcup_{s \leq u \leq t} \text{supp}(\mathcal{X}_u)} \subseteq \text{supp}(\mathcal{X}_s)^{NH(t-s)}.
    \end{equation*}
    \begin{proof}
        If we take $a=3$ in Lemma \ref{lemma support of SBM thickening} and then for the random positive constant $\delta$ and for $0 < t-s<\delta$ we have that
        \begin{equation*}
            \bigcup_{s \leq u \leq t}\text{supp}(\mathcal{X}_u) \subseteq \bigcup_{s \leq u \leq t}\text{supp}(\mathcal{X}_s)^{aH(u-s)} = \text{supp}(\mathcal{X}_s)^{3H(t-s)}.
        \end{equation*}
        Now let $N = 4/\delta$ where $\delta$ is the (random) positive constant given in Lemma \ref{lemma support of SBM thickening} and let $s$, $t \geq 0$ with $0 < t-s < 1$. Then there exists $s_1, \dots, s_K$ be such that $s<s_1< \dots < s_K<t$ and $s_1-s<\delta$, $t-s_K<\delta$, $s_{i+1}-s_i<\delta$ for all $1, \dots, K-1$, and $K \leq 1/\delta$. Therefore, by applying Lemma \ref{lemma support of SBM thickening} we have 
        \begin{equation*}
            \bigcup_{s \leq u \leq s_1}\text{supp}(\mathcal{X}_u) \subseteq \text{supp}(\mathcal{X}_s)^{3H(s_1-s)} \subseteq \text{supp}(\mathcal{X}_s)^{3H(t-s)},
        \end{equation*}
        for $1 \leq i \leq K$ we have
        \begin{equation*}
            \bigcup_{s_i \leq u \leq s_{i+1}}\text{supp}(\mathcal{X}_u) \subseteq \text{supp}(\mathcal{X}_{s_i})^{3H(s_{i+1}-s_i)} \subseteq \text{supp}(\mathcal{X}_{s_i})^{3H(t-s)},
        \end{equation*}
        and finally
        \begin{equation*}
            \bigcup_{s_K \leq u \leq t}\text{supp}(\mathcal{X}_u) \subseteq \text{supp}(\mathcal{X}_{s_K})^{3H(t-s_K)} \subseteq \text{supp}(\mathcal{X}_{s_K})^{3H(t-s)}.
        \end{equation*}
        With the above we have
        \begin{equation*}
            \bigcup_{s_i \leq u \leq s_{i+1}}\text{supp}(\mathcal{X}_u) \subseteq \text{supp}(\mathcal{X}_{s_i})^{3H(t-s)} \subseteq \text{supp}(\mathcal{X}_{s_{i-1}})^{6H(t-s)} \subseteq \dots \subseteq \text{supp}(\mathcal{X}_s)^{3iH(t-s)},
        \end{equation*}
        since $\text{supp} (\mathcal{X}_{s_i}) \subseteq \cup_{s_{i-1} \leq u \leq s_i} \text{supp}(\mathcal{X}_u)$, and similarly $\bigcup_{s_K \leq u \leq t}\text{supp}(\mathcal{X}_u) \subseteq \text{supp}(\mathcal{X}_s)^{3KH(t-s)}$. Therefore we have
        \begin{equation*}
            \bigcup_{s \leq u \leq t}\text{supp}(\mathcal{X}_u) \subseteq \text{supp}(\mathcal{X}_s)^{3H(t-s)/\delta}
        \end{equation*}
        and increasing the $3$ to $4$ to define $N$ is simply so that we can ensure the closure of $\bigcup_{s \leq u \leq t}\text{supp}(\mathcal{X}_u)$ is contained in $\text{supp}(\mathcal{X}_s)^{NH(t-s)}$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm eq:gauge_PDE_intro of arXiv:2506.12171, 'The multinomial dimer model'] Fix $R\subset \mathbb{R}^d$ and a suitable boundary function $H_b$ on $\partial R$. If $H$ is a weak solution to the differential equation 
    \begin{align}
         \text{div} (\nabla F(\nabla H)) = 0
    \end{align}
    with $H\mid_{\partial R} = H_b$, the limiting gauge flow is $\alpha = \nabla H$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:matchlaw of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Fix $n\geq 2$. Let $\zeta$ be a probability measure on $[0,1]$ with
		$(n+1)$-atom prefix $\{0,q_1,\ldots,q_n\}$ as in Definition~(def:nprefix of the paper);
		the tail $\mathrm{supp}(\zeta)\cap(q_n,1]$ may be nonempty.
		Let $(X_t)_{t\in[0,1]}$ be the Auffinger--Chen process~(equation eq:AuffingerChen of the paper),
		and write $U:=\partial_x\Phi_\zeta(q_{n-1},X_{q_{n-1}})$.
		Define $\mathrm{Test}:=\{\chi_1,\ldots,\chi_5\}$, where each $\chi_i:[-1,1]\to\mathbb{R}$ is given by
		\begin{align}
			\chi_1(m) &:= \mathbb{E}\!\left[(\partial_x\Phi_\zeta(q_n,X_{q_n}))^2 \;\middle|\; U=m\right], \\
			\chi_2(m) &:= \mathbb{E}\!\left[\partial_x\Phi_\zeta(q_n,X_{q_n})\,X_{q_n} \;\middle|\; U=m\right], \\
			\chi_3(m) &:=\mathbb{E}[\partial_x\Phi_\zeta(q_n,X_{q_n})\mid U=m]=m, \\
			\chi_4(m) &:= \mathbb{E}\!\left[X_{q_n} \;\middle|\; U=m\right], \\
			\chi_5(m) &:= \mathbb{E}\!\left[\Phi_\zeta(q_n,X_{q_n}) \;\middle|\; U=m\right]. 
		\end{align}
		For $\varepsilon\in(0,1)$, let $\delta_\varepsilon=\varepsilon^{\frac{1}{2}}$ and define $\mathrm{LawMatch}_{n-1}(\zeta,\varepsilon)$ as the set of
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)})\in([-1+\delta_\varepsilon,1-\delta_\varepsilon]^N)^{n-1}$ such that, for every
		$\chi\in\mathrm{Test}$ and $k\in[n-1]$,
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N\chi(m_i^{(n-1)})\,m_i^{(k)}
			-\mathbb{E}\!\left[\chi(U)\,\partial_x\Phi_\zeta(q_k,X_{q_k})\right]\right|\leq\varepsilon,
		\end{equation}
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N\chi(m_i^{(n-1)})\,\partial_m h_\zeta(q_k,m_i^{(k)})
			-\mathbb{E}\!\left[\chi(U)\,X_{q_k}\right]\right|\leq\varepsilon,
		\end{equation}
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N\chi(m_i^{(n-1)})
			-\mathbb{E}\!\left[\chi(U)\right]\right|\leq\varepsilon
		\end{equation}
		and, for every $k\in[n-1]$,
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N \Phi_\zeta\!\Bigl(q_k,\partial_m h_\zeta(q_k,m_i^{(k)})\Bigr)
			-\mathbb{E}\!\left[\Phi_\zeta(q_k,X_{q_k})\right]\right|\leq\varepsilon.
		\end{equation}

[Lemma 12 of arXiv:2604.03548, 'Degree-preserving conservative processes and a unified approach for their hydrodynamics'] Assume that there exists some constant $C_0>0$ such that 
\begin{equation}

\sup_{N\in\mathbb N} 
\max_{i=0,\ldots,\lfloor N/2\rfloor}|\phi(0,i)| < C_0. 
\end{equation}
Then, there exists a constant $ C=C(T)$ such that 
\begin{equation*}
\sup_{N\in\mathbb N}\sup_{0\le t\le T} \max_{i=0,\ldots,\lfloor N/2\rfloor}|\phi(N^2t,i)| < C. 
\end{equation*}
In particular, we have the second moment estimate 
\begin{equation}

\sup_{N\in\mathbb N} \sup_{0\le t\le T}
\frac{1}{N} 
\mathbb E_N\bigg[\sum_{x\in\mathbb T_N} \eta_x^2(N^2t)\bigg]
<C. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

