[Theorem 9 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=\left(V,E\right)$ be a locally finite weighted graph satisfying the $CD\psi\left(n,-K\right)$ condition with $K\geq0$, where $\psi\in C^{1}\left(0,+\infty\right)$ is a concave function. Let $b>\frac{1}{2}$ be a constant. Then for any $0<f\in \ell^{\infty}\left(V\right)$, 
    \begin{equation*}
        \Gamma ^\psi\left(P_t f\right)\leq \psi^\prime \left(1\right)\left(1+\frac{2Kt}{2b+1}\right)  \frac{\Delta P_t f}{P_t f}+\frac{n}{2} \left(\frac{b^2}{\left(2b-1\right)t}+\frac{K^2 t}{2b+1}+K\right).
    \end{equation*}

