body:
[Lemma id-g-fixed-points-vs-ev of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\Phi\colon\ul{{\mathfrak S\kern-.4pt}}_\textup{gl}\xrightarrow{\;\smash{\raisebox{-0.25ex}{\ensuremath{\scriptstyle\sim}}}\;}\ul\Spc_\textup{gl}$ be the unique equivalence, and fix any homomorphism $\varphi\colon H\to G$ of compact Lie groups. Then the composite
    \[
        {{\mathfrak S\kern-.4pt}}_\textup{$G$-gl}\xrightarrow[\raise2pt\hbox{$\scriptstyle\smash{\sim}$}]{\;\Phi_G\;} \PSh(\textup{Glo}_{/\mathbb B{G}})\xrightarrow{\;\ev_\varphi\;}\Spc
    \]
    is equivalent to
    \begin{equation}
        {{\mathfrak S\kern-.4pt}}_\textup{$G$-gl}\xrightarrow{\;\smash{\raisebox{-0.25ex}{\ensuremath{\scriptstyle\sim}}}\;}{{\mathfrak S\kern-.4pt}}_\textup{$G$-gl}^\textup{closed}\xrightarrow{\;(-)^\varphi\circ\ev_{{\mathcal{U}}_H}\;}\Spc
    \end{equation}
    for any complete $H$-universe ${\mathcal{U}}_H$.
    \begin{proof}
        Using that $\Phi$ is a global functor, and comparing the functoriality on both sides, it suffices to consider the case where $H=G$ and $\varphi=\textup{id}_H$. In this case, combining Lemmas~(lemma:fixed-point-corep of the paper) and~(lemma:resolve-pt of the paper) shows that $((eq:phixed-points of the paper))$ is corepresented by the terminal object. On the other hand, the terminal object of $\PSh(\textup{Glo}_{/\mathbb B{H}})$ is represented by $\textup{id}_H$, so it corepresents evaluation at $\textup{id}_H$ by the Yoneda lemma. Adjoining over, it will therefore suffice that the left adjoint of $\Phi_H\colon{{\mathfrak S\kern-.4pt}}_\text{$H$-gl}\to\PSh(\textup{Glo}_{/\mathbb B{H}})$ preserves the terminal object; but as this left adjoint is again an equivalence, this is clear.
    \end{proof}

[Theorem t:proba of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Let the family $\widetilde{\xi}_{a;n}$ satisfy the assumptions~((a:center of the paper))--((a:growth of the paper)). Then there exist constants $C_1,C_{2}$ and a number $n_0$ such that for every $n>n_0$
\begin{equation}
\forall a \quad C_1^2\, n \le \mathop{\rm Var}\nolimits \widetilde{\xi}_{a;n} \le C_{2}^2 \, n,
\end{equation}
and random variables
\begin{equation}
\frac{\widetilde{\xi}_{0;n}}{\sqrt{\mathop{\rm Var}\nolimits \widetilde{\xi}_{0;n}}}
\end{equation}
converge to $\mathcal{N}(0,1)$ in distribution as $n\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm clt-from-var-lb of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Here $n$ denotes the length of the segment; the statement will be applied with $n$ replaced by other lengths $m$ with $m\asymp n$.
Assume $1\ll\ell\ll n$ and
$\go_e\stackrel{\mathrm{d}}{=}\mathrm{Exp}(1)^{1/\theta}$. Suppose that,
for some constants $c>0$, $\ga\geqslant0$, and $A\in\mathds{R}$,
\begin{align}
 \var(T_{[n]})\geqslant c\frac{n}{\ell^\ga(\log\ell)^A}

\end{align}
for all sufficiently large $n$. Suppose further that there exists an integer sequence $b=b_{n,\ell}$
such that $b>2\ell$, $b=o(n)$, and
\begin{align}
 \frac{\ell^{\ga-2/\theta}(\log\ell)^{A+2\gth}}{b}\to0,
 \qquad
 \frac{b\ell^{2\ga-2-4/\theta}(\log\ell)^{2A+4\gth}}{n}\to0.

\end{align}
Then
\begin{align*}
 \frac{T_{[n]}-\E T_{[n]}}{\sqrt{\var(T_{[n]})}}
 \Rightarrow\N(0,1).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 (Infinitesimal range evolution) of arXiv:2608.10992, '2608.10992'] At level $t$, conditionally on $X_t=x<\infty$, the update rate is
$x+1$, with update kernel
\begin{equation}

        x\longmapsto\max\{x,U_x+X_t'\},
\end{equation}
where $U_x$ is uniform on $\{0,\ldots,x\}$ and $X_t'$ is independent of $U_x$ with the law of $X_t$. Null changes are allowed. The process is increasing and is sent to $\infty$ when its graphical range becomes infinite.

[Corollary 3 of arXiv:2511.19308, 'Universal scaling limits at the spectral singularity of structured random matrices'] As $\abs{\xi} \to 0$ we have
    \begin{equation} 
        \lim_{N \to \infty} K N \eta_N \rho_N(\eta_N \xi) = \begin{cases}
            1, & K = 1, \\
            \frac{4 \pi}{3^{9/4}} + O(\abs{\xi}), & K = 2, \\
            -\frac{\pi}{4} \log(\abs{\xi}) + \frac{\pi}{2} \p*{\log\p*{\frac{2}{\pi}} - \gamma + \frac{1}{2}} + O(\abs{\xi}), & K = 3,
        \end{cases}
    \end{equation}
    where $\gamma \approx 0.5772$ is the Euler–Mascheroni constant and the local spacing scale $\eta_N$ is
    \begin{align}
        K & = 1: \quad \eta_N = \pi N^{-1}, \\
        K & = 2: \quad \eta_N = \frac{2 s_{12}}{\sqrt{s_{11}}} \p*{\frac{2 \pi}{3\sqrt{3}}}^{3/2} N^{-3/2}, \\
        K & = 3: \quad \eta_N = \frac{s_{13} \sqrt{s_{22}}}{s_{12}} \frac{\pi^2}{4} N^{-2}.
    \end{align}
    As $\abs{\xi} \to \infty$ we have the asymptotic
    \begin{equation} 
        \lim_{N \to \infty} K N \eta_N \rho_N(\eta_N \xi) = \begin{cases}
            1, & K = 1, \\
            \frac{2^{2/3}}{3} \abs{\xi}^{-1/3} + O(\abs{\xi}^{-1}), & K = 2, \\
            \frac{1}{2 \sqrt{2}} \abs{\xi}^{-1/2} + O(\abs{\xi}^{-1}), & K = 3.
        \end{cases}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

