[Proposition 6 (Center-of-mass factorization) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] Let
\begin{equation}
 c_N=N^{-1/2}\sum_{i=1}^Nz_i,
 \qquad
 r_k:=\frac{z_1+\cdots+z_k-kz_{k+1}}{\sqrt{k(k+1)}},
 \quad 1\le k\le N-1,
\end{equation}
and set $Z^{\rm rel}:=(r_1,\ldots,r_{N-1})$.  The map $Z\mapsto(c_N,Z^{\rm rel})$ is unitary and, in these coordinates,

\begin{equation}
 \mathbb P_{N,\beta}=\gamma_\beta^{(2)}\otimes \mathbb P_{N,\beta}^{\rm rel},
\end{equation}
where $\gamma_\beta^{(2)}(dc)=(\beta/2\pi)e^{-\beta|c|^2/2}\D c$ and $\mathbb P_{N,\beta}^{\rm rel}$ is the law of $Z^{\rm rel}$.  Consequently,
\begin{equation}
 \rho(\mathbb P_{N,\beta})=\min\{\beta,\rho(\mathbb P_{N,\beta}^{\rm rel})\}.
\end{equation}

