[Lemma 31 (Changing path for directions $0 \leq \alpha < \alpha_b$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose that $x_{max}^+ < x_{max}^-$ (i.e., $\alpha_b \in (0,\pi)$). Let $\delta > 0$ and let $z_0 \in \R^2$, $a \in \R$, and $b > 0$ such that $(a,b) \neq z_0$. Then, for $0 \leq \alpha < \alpha_b$,
\begin{equation}
I_1^{z_0}(a,b) = \frac{1}{2i\pi}\int_{R^-_{\delta}\cup \Omega_{-,\M + \delta} \cup \Omega_{+,\M + \delta}\cup R^-_{\delta}}\phi^{z_0}(x)\frac{\gamma(x,Y^+(x),Z^+(x))}{\partial_y\gamma_+(x,Y^+(x))}e^{-ax-bY^+(x)}
 dx.
\end{equation}
Furthermore, if $b_0 > 0$ and $a > a_0$, then \eqref{I22''} holds. Finally, if $b_0 \leq 0$, then
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi}\int_{R^-_{\delta}\cup \Omega_{-,\M + \delta} \cup \Omega_{+,\M + \delta}\cup R^+_{\delta}}\frac{e^{(a_0-a)x+b_0Z^+(x) - bY^+(x)}}{\partial_y\gamma_+(x,Y^+(x))} dx.
\end{equation}

[Thm 37 ({\cite[Theorem 10.4) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Kig12}}]
  Suppose that $(F,R)$ is boundedly compact and let $U$ be a non-empty open subset of $F$.
  Then there exists $p_U:(0,\infty)\times F\times F\to[0,\infty)$ which satisfies the following conditions:
  \begin{itemize}
    \item The function $p_U$ is continuous on $(0,\infty)\times F\times F$. Define $p^{t,x}_U(y):=p_U(t,x,y)$. Then $p^{t,x}$ lies in the domain of the Dirichlet form corresponding to $X^U$.
    \item It satisfies $p_U(t,x,y)=p_U(t,y,x)$ for any $(t,x,y)\in (0,\infty)\times F\times F$.
    \item For any Borel measurable function $u$ on $F$ and any $x\in X$, it holds that
    \begin{align*}
      E_x[u(X^U_t)]=\int_{X}p_U(t,x,y)u(y)\mu(dy).
    \end{align*}
    \item For any $t,\;s>0$ and $x,\;y\in X$, it holds that 
    \begin{align}
      p_U(t+s,x,y)=\int_{X}p_U(t,x,z)p_U(s,y,z)\mu(dz).
    \end{align}
  \end{itemize}
  Furthermore, let $A$ be a Borel subset of $X$ which satisfies $0<\mu(A)<\infty$. 
  Then
  \begin{align}
    p_U(t,x,x)\leq \frac{2\sup_{y\in A}R(x,y)}{t}+\frac{\sqrt{2}}{\mu(A)},
  \end{align}
for any $x\in X$ and any $t>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 35 (\cite{abbrescia2022emergence}*{Lemma 6.5}; Relationship between $\left\lbrace\geop{t},\geop{u},\geop{x^2},\geop{x^3}\right\rbrace$ and $\{\Lunit,X,\Yvf{2},\Yvf{3}\}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The commutation vectorfields from Def.\,\ref{D:COMVECTORFIELDS}
can be expressed as follows:
\begin{subequations} 
\begin{align}
\Lunit 
& = \geop{t} + \Lunit^A \geop{x^A},  

	\\
\muX 
& = \geop{u} + \upmu X^A \geop{x^A}, 

	\\
\Yvf{2} 
& = \left\lbrace 1 - \Speed^{-2}(X^2)^2 \right\rbrace 
		\geop{x^2}
		- \Speed^{-2} X^2 X^3 \geop{x^3}, 

		\\
\Yvf{3} 
& = \left\lbrace 1 - \Speed^{-2} (X^3)^2 \right\rbrace 
		\geop{x^3}
		- 
		\Speed^{-2} X^2 X^3 \geop{x^2}, 

\end{align}
\end{subequations}Moreover, the following identities hold:
\begin{subequations}
\begin{align}
	\geop{t} 
	& = \Lunit - \Lunit^A \Yvf{A} 
	- 
		\frac{L^2 X^2 + L^3 X^3}{(X^1)^2} X^A \Yvf{A}, 

		\\
	\geop{u} 
	& = \muX - \frac{1}{(X^1)^2} \upmu \Speed^2 X^A \Yvf{A}, 

		\\
	\geop{x^2} 
	& = 
	\left\{ \frac{(X^1)^2 + (X^2)^2}{(X^1)^2} \right\} \Yvf{2} +  \frac{X^2 X^3}{(X^1)^2} \Yvf{3},

		\\
	\geop{x^3} 
	& = 
	\left\{ \frac{(X^1)^2 + (X^3)^2}{(X^1)^2} \right\} \Yvf{3} +  \frac{X^2 X^3}{(X^1)^2} \Yvf{2}.		
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

