  \end{enumerate}

[Thm of arXiv:2506.12171, 'The multinomial dimer model'] Fix $(R,b)\subset \mathbb{R}^2$ flexible and let $h_b$ be the corresponding boundary height function. 
Let $\Lambda = \mathbb{Z}^2$ or the honeycomb lattice. The multinomial limit shape height function with boundary condition $h\mid_{\partial R}=h_b$ is a smooth function which is the envelope of $\kappa$-harmonically moving planes, where $z$ is a conformal coordinate in the Riemannian metric determined by $\sigma$ and $\kappa = \sqrt{\det \text{Hess}(\sigma)}$. Concretely,
    \begin{itemize}
        \item For $\mathbb{Z}^2$ embedded with edge vectors $(\pm 1/2, \pm 1/2)$, $\mathcal{N} = \{(s,t)\in [-1/2,1/2]^2\}$. A conformal coordinate $z = u+i v$ for $(u,v)\in[0,\pi]^2$ is given by $$(u,v) = (\arccos(2s),\arccos(2t))$$ and $\kappa(u,v) = \frac{4}{\sin(u)\sin(v)}$. 
        \item For the honeycomb lattice, $\mathcal{N} =\{(s,t): 0\leq s\leq 1, 0\leq t\leq s\}.$ A conformal coordinate $z = u+iv\in\mathbb{H}$ is given by 
        \begin{align}
            (u,v) = \bigg( \frac{s-t(1-s-t)}{(1-t)^2}, \frac{2\sqrt{st(1-s-t}}{(1-t)^2}\bigg)
        \end{align}
        and $\kappa(u,v) = \frac{(1+ \sqrt{u^2 + v^2} + \sqrt{(u-1)^2 + v^2})^2}{2 v}$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:smallt2 of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] There is an absolute constant $C > 0$ such that for every $T \in \mathbb{R}_{\ge 0}$,
    \begin{align*}
        \int_{\| \mathbf{t} \| < T} | f(\mathbf{t}) | \mathrm{d} \mathbf{t} = \int_{\| \mathbf{t} \| < T}  e^{-\frac{\widehat{\sigma}^2}{2}\|\mathbf{t}\|^2} \left| \widehat{R}_\alpha( \mathbf{X}_{\text{R}} , \mathbf{t}) \right| \mathrm{d} \mathbf{t} \le \Bigg( \frac{C|\alpha| \rho}{\sqrt{d}} \Bigg)^{\ell + 1}.
    \end{align*}

[Proposition prop:bound_gen_size_ind of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Fix some $R\geq 1$. For any $\alpha,\beta>0$, take $\underline{a}_0=\Bar{a}_0=\alpha$ and $\underline{b}_0=\Bar{b}_0=\beta$, and define $\underline{a}_i,\Bar{a}_i,\underline{b}_i,\Bar{b}_i$ inductively for $i\geq 1$ as in (equation eq:inductive_def_seq_a of the paper) and (equation eq:inductive_def_seq_b of the paper), with $m=m_n$ and $m'=m_n'$ as defined in (equation eq:def_mn_mn' of the paper). Then
    \begin{align*}
        \liminf_{n \to \infty}\CProb{\underline{a}_t\leq \xi_{l(R+t)}\leq \Bar{a}_t,\underline{b}_t\leq \Xi_{R+t}\leq \Bar{b}_t\textrm{ for all }t\geq 1}{\xi_{lR}=\alpha,\Xi_R=\beta}\geq 1-O\left(\alpha^{1-2\gamma}\right),\\ \addtocounter{equation}{1}\tag{\theequation} 
    \end{align*}
    where the constant hidden in the $O(\cdot)$ term above is universal, i.e., independent of $R, \alpha,\beta$.

