[Lemma 8 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Suppose that $\ma{M}$ is an $n\times n$ upper bidiagonal matrix with non-zero diagonal entries $d_i, 1\le i\le n$ and off-diagonal entries $-e_i, 1\le i\le n-1$. Then the entries of $\ma{M}^{-1}$ are given by
    \begin{align}
        [\ma{M}^{-1}]_{i,j}=\begin{cases}
\frac{\prod_{k=i}^{j-1} e_k}{\prod_{k=i}^{j} d_k}, \qquad  &i\le j,\\
0, \qquad &i>j.
        \end{cases}
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 (EMN conjecture) of arXiv:2608.30304, '2608.30304'] Put $M(\alpha,\beta)=\max\{1,(\alpha+\beta+1)^{1/4}\}$. Then
\begin{equation}
 F_{n,\alpha,\beta}(x)\le C_*M(\alpha,\beta)
\end{equation}
uniformly in $n$, $\alpha$, $\beta$ and $x$. Consequently
\eqref{eq:EMNconj} holds.

[Lemma lem:increase-after-shuffling of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] If ${T}$ and ${\widetildeT}$ be two plane trees such that ${T}\subseteq{\widetildeT}$, then we have
	\begin{align*}
	{\mathfrak{P}^{-1}}
		\Bigl(
			{\boldsymbol{\sigma}}_{{T}}\cdot{T},
			({\boldsymbol{\sigma}}_{{T}})_*\,{\boldsymbol{S}}_{{T}}
		\Bigr)
	\subseteq
	{\mathfrak{P}^{-1}}
		\Bigl(
			{\boldsymbol{\sigma}}_{{\widetildeT}}\cdot{\widetildeT},
			({\boldsymbol{\sigma}}_{{\widetildeT}})_*\,{\boldsymbol{S}}_{{\widetildeT}}
		\Bigr).
	\end{align*}

