[Proposition prop:Q of arXiv:2603.20078, '\bf \Large Gated Infinite Server Queues in Light Traffic'] The sequence of consecutive stage lengths $\{Y_n\}$ is a 
Markov chain with state space ${\sf X}:=[0,\infty)$ and transition kernel 
$Q(x,A)= \int_A q(x,y)dy$ for $x \in {\sf X}$, $A \in \mathcal{B}$, which
is absolutely continuous with respect to the Lebesgue measure for all $x$ with
density 

\begin{equation}  
q(x,y)= \left( \lambda xe^{\mathbf{-}\lambda x\overline{G}(y)}
+e^{-\lambda x}\right)g(y), \hspace{0.2in} y \geq 0.
\end{equation}

[Definition covariance of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] A measurable function ${\widehat B}:\widehat\Omega\times\mathbb{Z}^2\times\mathbb{Z}^2\to\mathbb{R}$ is 
\emph{shift-covariant} if for $\widehat\mathbb{P}$-almost every ${\widehat\omega}$,
\begin{align}
{\widehat B}({\widehat\omega},x+z,y+z)={\widehat B}(\widehat{T}_z{\widehat\omega},x,y)\quad\text{for all $x,y,z\in\mathbb{Z}^2$}.
\end{align}
${\widehat B}$ is $L^1(\widehat\Omega,\widehat{\mathfrak{S}},\widehat\mathbb{P})$ if
\begin{equation}\begin{aligned}
\widehat\mathbb{E}[\abs{{\widehat B}(x,y)}]<\infty\quad\text{for all $x,y\in\mathbb{Z}^2$}. 
\end{aligned}\end{equation}
When the underlying probability space is clear from context, we simply say that ${\widehat B}$ is $L^1$.

[Lemma 36 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] There exists constant $c>0$ such that for any $n$ sufficiently large, $h_*+\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}\le s \le h^*$, $(\log n)^{1+\frac23\varepsilon}\le k\le q_n(s)$ and $1 \le m \le \lfloor (\log n)^{1+\frac{\varepsilon}{2}} \rfloor$,
\begin{align}
    \p_n\!\left(
        \#\big( B_2 \cap \{u^s_i : 1 \le i \le k\} \big)
        > \frac{k}{(\log n)^{\frac\eps6}}
        \,\Big|\, X^{(r)}_{s^{\downarrow}} = m
    \right)
    \le e^{-c(\log n)^{\frac\eps4}}.
\end{align}

[Theorem thm:tsai of arXiv:2511.08479, '\Large From disordered systems to the Critical 2D Stochastic Heat Flow'] Let $Z=(Z_{s,t}(\cdot, \cdot))_{s\leq t}$ be a stochastic process taking values in
the space of locally finite non-negative measures $M_+(\mathbb{R}^2\times\mathbb{R}^2)$ on $\mathbb{R}^2\times\mathbb{R}^2$
equipped with the vague topology   such that:
\begin{itemize}
\item[(1)] for any $s<t<u$, the random measures $Z_{s,t}$, $Z_{t, u}$ and $Z_{s, u}$ satisfy a
form of Chapman-Kolmogorov property $Z_{s, u} = Z_{s, t} \, \bullet \, Z_{t,u}$;
\item[(2)] for any $s<t<u$, $Z_{s,t}$ and $Z_{t,u}$ are independent;
\item[(3)] for any $s<t<u$, $1\leq n\leq 4$, and $\phi_i,\psi_i\in L^2(\mathbb{R}^2)$ for $i=1,\ldots,4$, the mixed moments
${\ensuremath{\mathbb E}} \big[\prod_{i=1}^n Z_{s,t}(\phi_i,\psi_i) \big]$ agree with that of the SHF with parameter $\vartheta\in\mathbb{R}$.
\end{itemize}
Then $Z$ has the same law as the Critical $2d$ Stochastic Heat Flow with parameter
$\vartheta$. Furthermore, $(Z_{s,t}(\cdot, \cdot))_{s\leq t}$ admits
a version that is almost surely continuous in $s\leq t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:fun_convergence of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] Let $\mathcal T_\Phi$ denote the topology on the space $\Phi$ such that $\varphi_n \to \varphi$ if the following two conditions hold: 
\begin{enumerate}
    \item  For every $R\in\mathbb{R}$ there exists $I(R,\varphi)\subseteq\mathfrak{X}$ compact and $N_0(R,\varphi)>0$  such that\ 
    \begin{equation}
        \frac{\varphi_n(\xi)}{\mathcal P(\xi)^2}\leq R, \qquad \forall \xi\in I^c, n\geq N_0.
    \end{equation}
    \item $\text{hypo}(\varphi_n)\xrightarrow{\operatorname{PK}}\text{hypo}(\varphi)$,  as $n\rightarrow \infty$.
\end{enumerate}

[Lemma lem:cc-gaussian-flip-probabilities of arXiv:2608.06159, 'Majority Dynamics on Resampled Sparse Erd\H{o}s--R\'enyi Graphs:\\[0.5ex] Gaussian Winner '] Recall \(x_t^{\gR},x_t^{\gB}\) from
    (equation eqn:standardized-degree-difference-definitions of the paper). Fix \(c_0>0\)
    and \(M<\infty\), condition on \(\rvy_t\), and suppose that
    \begin{align}
    |\gR_t|\ge c_0N,
    \qquad
    |\gB_t|\ge c_0N,

    \end{align}
    while $x_t^{\gR}$ and $x_t^{\gB}$ in (equation eqn:standardized-degree-difference-definitions of the paper) satisfy
    \begin{align}
    |x_t^{\gR}|\le M,
    \qquad
    |x_t^{\gB}|\le M.

    \end{align}
    Then, uniformly over such configurations,
    \begin{subequations}
    \begin{align}
    p_t^{\gR}
    &=
    \Phi\left(
    x_t^{\gR}-\frac{1}{2\sqrt{v_t^{\gR}}}
    \right)
    +O\left(\frac1{\log N}\right),
    \\
    p_t^{\gB}
    &=
    \Phi\left(
    x_t^{\gB}-\frac{1}{2\sqrt{v_t^{\gB}}}
    \right)
    +O\left(\frac1{\log N}\right).

    \end{align}
    \end{subequations}
    For \(\Delta_t\ge1\), there are constants \(c,C>0\) such that
    \begin{align}
    c\frac{p\Delta_t}{\sqrt{(N-1)p(1-p)}}
    \le
    p_t^{\gR}-p_t^{\gB}
    \le
    C\frac{p\Delta_t}{\sqrt{(N-1)p(1-p)}}.

    \end{align}
    Furthermore, for every fixed \(C_0<\infty\), when
    \(0\le\Delta_t\le C_0\sqrt{N/\log N}\), we have
    \begin{align}
    p_t^{\gR}-p_t^{\gB}
    =
    \sqrt{\frac{2}{\pi}}
    \frac{p\Delta_t}{\sqrt{(N-1)p(1-p)}}
    +O\left(\frac{p\Delta_t}{\log N}\right).

    \end{align}
    All implicit constants and the constants \(c,C\) depend only on
    \(b,c_0,M\), and additionally on \(C_0\) in
    (equation eq:cc-gaussian-critical-flip-difference of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

