body:
[Definition def:equilibrium-defs of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] \enskip 

\begin{itemize}

\item A Markovian randomized stopping time pair $(\tau^*_1,\tau^*_2)=(\tau_{\Psi^{(1)}},\tau_{\Psi^{(2)}})$ is said to be a global Markovian randomized $\epsilon$-Nash equilibrium, for a fixed constant $\epsilon\geq 0$, if
\begin{align}
\begin{split}
& J(x;\tau_1,\tau^*_2) - \epsilon \leq J(x;\tau^*_1,\tau^*_2) \leq J(x;\tau_1^*,\tau_2) + \epsilon\\
& \enskip \text{for all $\tau_1 \in \mathbb{T}_1, \tau_2 \in \mathbb{T}_1$, and $x\in {\cal I}$.}
\end{split}
\end{align}
If (equation def:SE of the paper) is satisfied with $\epsilon=0$ then $(\tau^*_1,\tau^*_2)=(\tau_{\Psi^{(1)}},\tau_{\Psi^{(2)}})$ is said to be a global Markovian randomized Nash equilibrium.

\item A Markovian pure stopping time pair $(\tau^*_1,\tau^*_2)=(\tau^{D_1},\tau^{D_2})$ is said to be a global Markovian pure $\epsilon$-Nash equilibrium if it satisfies (equation def:SE of the paper). 
If it satisfies (equation def:SE of the paper) with $\epsilon=0$ then it is said to be a global Markovian pure Nash equilibrium.

\item The value of the game $V$ is defined as $V(x):=V^*(x)=V_*(x)$, whenever this equality holds for each $x\in  {\cal I}$, where 
\begin{align}
\begin{split}
V^*(x)&:=\adjustlimits \inf_{\tau_2 \in \mathbb{T}_2} \sup_{\tau_1 \in \mathbb{T}_1} J(x;\tau_1,\tau_2),\\
V_*(x)&:=\adjustlimits  \sup_{\tau_1\in \mathbb{T}_1} \inf_{\tau_2\in \mathbb{T}_2} J(x;\tau_1,\tau_2).
\end{split}
\end{align}



\end{itemize}

[Corollary 20 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Let \(Z\) be an \(\alpha\)-spectral representer satisfying
(equation 2 of the paper) and (equation 17 of the paper), and put
\(\Theta=\Theta^{[\varnothing]}\). Then \(Z\) is branch-BR stationary
if and only if
\begin{equation}
  \E*{
    \mathbf 1_{\{\Theta_a>0\}}
    \Theta_a^\alpha
    H\left(\frac{B^a\Theta}{\Theta_a}\right)
  }
  =
  \E{H(\Theta)},
  \qquad
  a\in\mathcal T,\quad H\in\mathfrak H.

\end{equation}
Under these equivalent conditions
\begin{equation}
  \mathbb P\{\Theta_u=0,\ \Theta_{uv}>0\}
  =
  \mathbb P\{Z_u=0,\ Z_{uv}>0\}
  =
  0,
  \qquad u,v\in\mathcal T.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 227 of arXiv:2601.16377, '2601.16377'] If $\theta_{g,h} = \theta > 0$ for all $g,h \in [H]$, we have
\begin{equation}

\begin{split}
\mathcal{F}(z,w) & = \frac{(\sigma(z) - \sigma(w))^2 - \frac{z - w}{2}(S'(z) - S'(w))}{4\theta(z - w)^2\sigma(z)\sigma(w)} \\
& \quad + \frac{P(z,w) + \sum_{j,i = 0}^{H - 2} c_{j,i}z^{j}w^{i}}{\theta\sigma(z)\sigma(w)}.
\end{split}
\end{equation}
Here, $P(z,w)$ is the unique symmetric polynomial of degree $2H - 2$ in both its variable such that each of its monomial contains at least $z^{H - 1}$ or $w^{H - 1}$, and
\begin{equation}

\frac{(\sigma(z) - \sigma(w))^2 - \frac{z - w}{2}(S'(z) - S'(w))}{4(z - w)^2} + P(z,w) = O(z^{H - 2}w^{H - 2})
\end{equation}
as $z,w \rightarrow \infty$. The constants $c_{j,i}$ are given in terms of the inverse of the restricted period map
\begin{equation}
\forall i \in \llbracket 0,H-2\rrbracket\qquad \sum_{j = 0}^{H - 2} c_{j,i}z^{j} = \hat{\Pi}^{-1}\Bigg[\bigg(\oint_{\gamma_h} \frac{\dd\zeta}{2\ii\pi} \frac{Q_{i}(\zeta)}{\sigma(\zeta)}\bigg)_{h = 1}^{H - 1}\Bigg],
\end{equation}
where $Q_{i}(\zeta)$ are polynomials of degree at most $2H - 2$, defined by the decomposition as $w \rightarrow \infty$
\begin{equation}

\frac{S(z) + S(w) - \frac{z - w}{2}(S'(z) - S'(w))}{4(z - w)^2} = - \sum_{i = 0}^{2H - 2} Q_{i}(z)w^{i} + O\bigg(\frac{1}{w}\bigg).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] The $r$-th moment $m_r(s)=E(X^r)$ of the $s$-Bernoulli distribution is given by
	\begin{equation}
		m_r(s) =\frac{(-1)^r }{(p-q)^{r+1}} p  \sum_{k=0}^r\left( A(r,k,s+1)  p^{r-k+s} q^{k} - A(r,k,1)  p^{r-k} q^{k+s} \right),\quad\text{ for } p\neq q,
	\end{equation}
	and
	\begin{equation}
		m_r(s) = \frac{1}{(r+1)(s+1)}\sum_{k=0}^r(-1)^k { r+1 \choose k} B_k s^{r-k+1} , \quad\text{ for } p= q,
	\end{equation}
	where the $ B_k $ are the Bernoulli numbers, with the convention $B_1=-\tfrac12$; see \cite{Sriva}.

[Lemma lem:sbmix of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $d \geqslant 2$. Consider a sequence of continuous time rate $1$ single ball chains where the $n$th chain has parameters $(d, n, \mu_n)$. Suppose that the Cheeger constant of these chains satisfies $\Phi_{\ast}^{(n)} = \Omega(1)$. Then, we have
    \begin{equation*}
        \frac{\log n}{2 \gamma_n} - O(1) \leqslant t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n}) \leqslant \frac{\log n}{2 \gamma_n} + O(\log \log n).
    \end{equation*}
    Further, if $\mu_n$ is symmetric for each $n \in \mathbb{N}$, then the condition $\Phi_{\ast}^{(n)} = \Omega(1)$ is no longer required. In fact, in this case, we have the more precise estimates
    \begin{equation*}
        \frac{\log n}{2 \gamma_n} - O\brac{\frac{1}{\gamma_n}} \leqslant t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n}) \leqslant \frac{\log n}{2 \gamma_n} + O\brac{\frac{1}{\gamma_n}}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] There are constants \(c,C>0\), independent of \(\eps\), such that if
\[
  \norm{\phi}_{C^{4,\alpha}_2}\le c,
  \qquad
  \norm{\psi}_{C^{4,\alpha}_2}\le c,
\]
then
\begin{align}
  \norm{Q_\eps(\phi)-Q_\eps(\psi)}_{C^{0,\alpha}_{\delta-4}}
  &\le
  C\left(
    \norm{\phi}_{C^{4,\alpha}_2}
    +\norm{\psi}_{C^{4,\alpha}_2}
  \right)
  \norm{\phi-\psi}_{C^{4,\alpha}_\delta},
  \\
  \norm{Q_\eps(\phi)}_{C^{0,\alpha}_{\delta-4}}
  &\le
  C\norm{\phi}_{C^{4,\alpha}_2}
  \norm{\phi}_{C^{4,\alpha}_\delta}.

\end{align}

[Theorem thm:ito_formulas of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $(\bm{\ell}_t)_{t\in[0, T]} \in \mathcal{I}^r(X)$. Then, $(\bracket{\bm{\ell}_t}{\sigX})_{t \in [0, T]}$ is an Itô process and, for all $0 \leq s \leq t \leq T$,
    \begin{equation}
        \bracket{\bm{\ell}_t}{\sigX[t]} = \bracket{\bm{\ell}_s}{\sigX[s]}  +
        \int_s^t\bracket{\dot\bm{\ell}_u}{\sigX[u]}du
        +\sum_{{\color{NavyBlue}{\mathbf{i}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{\bm{\ell}_u|_{{\color{NavyBlue}{\mathbf{i}}}}}{\sigX[u]}dX_u^i + \dfrac12\sum_{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{j}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{\bm{\ell}_u|_{{\color{NavyBlue}{\mathbf{ji}}}}}{\sigX[u]}d\bracket{X^i}{X^j}_u.
    \end{equation}    
    Similarly, if $(\bm{\ell}_t)_{t\in[0, T]} \in \mathcal{I}^l(X)$, then $(\bracket{\bm{\ell}_t}{\sigX[t]^{-1}})_{t \in {[0, T]}}$ is an Itô process and, for all $0 \leq s \leq t \leq T$,





\begin{equation}
        \bracket{\bm{\ell}_t}{\sigX[t]^{-1}} = \bracket{\bm{\ell}_s}{\sigX[s]^{-1}}  +
        \int_s^t\bracket{\dot\bm{\ell}_u}{\sigX[u]^{-1}}du
        -\sum_{{\color{NavyBlue}{\mathbf{i}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{~_{{\color{NavyBlue}{\mathbf{i}}}}|\bm{\ell}_u}{\sigX[u]^{-1}}dX_u^i + 
        \dfrac12\sum_{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{j}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{~_{{\color{NavyBlue}{\mathbf{ij}}}}|\bm{\ell}_u}{\sigX[u]^{-1}}d\bracket{X^i}{X^j}_u.
    \end{equation}

[Prop 1-integrated of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Let $-\check{L}_\mathrm{rel}$ be the generator of $(\check{R}_\alpha)_\alpha$. Then we have the following:
\begin{enumerate}
\item[\rm(1)] The linear relation  $-\check{L}_\mathrm{rel}$ is $m$-dissipative.
\item[\rm(2)] The linear relation  $-\check{L}_\mathrm{rel}$ generates  an integrated semigroup, $\check{\bf S}_t: C_0(X)\to C_0(X)$, $t\geq 0$ via the equation
\begin{equation}
\check{R}_\alpha = \alpha\int_0^\infty e^{-\alpha t} \check{\bf S}_t\,dt.

\end{equation} 
\item[\rm(3)] It holds
\begin{equation}
	\check{\bf S}_t = \int_0^t \check{\bf P}_s\,ds,\quad t\geq 0.

\end{equation}
\end{enumerate}
Here both integrals in the right hand side of 
(equation 1-integrated of the paper) and (equation integrated-smgp of the paper), respectively are
 the strong Riemann integrals.

[Defn thetaBMonGL of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] For any $N\in\mathbb{N}$ and 
$\theta\in\mathbb{R}$, we define the drifted  multiplicative Brownian motion 
$(\mathsf{Y}_N^\theta(t))_{t\ge0}$ on $\mathsf{GL}_N(\mathbb{C})$, with drift $\theta$, as the unique strong solution to the matrix-valued SDE:
\begin{align}
\mathrm{d} \mathsf{Y}_N^\theta(t) = \mathsf{Y}_N^\theta(t)\, \mathrm{d} \boldsymbol{B}_N(t) + \theta \mathsf{Y}_N^\theta(t) \, \mathrm{d} t,
\end{align}
where
$\boldsymbol{B}_N$ is a matrix Brownian motion on $\mathbb{M}_N(\mathbb{C})$, that is,
\begin{align*}
\boldsymbol{B}_N(t) &=  \boldsymbol{B}_N^{(1)}(t) + \mathrm{i} \boldsymbol{B}_N^{(2)}(t),
\end{align*}
with $\boldsymbol{B}_N^{(1)},\boldsymbol{B}_N^{(2)}$ independent matrices with independent standard real Brownian motions as entries.

[Lem principalvalue of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] There exists a constant $C>0$ uniform in $N$, such that
  \begin{align*}
   & \frac{1}{\mu_{+}(N)^{M_{1}+\ldots+M_{l}}}\cdot \prod_{j=1}^{l}\left[\left(\frac{\mathcal{D}_{1}}{N}\right)^{M_{j}}+\ldots+\left(\frac{\mathcal{D}_{N}}{N}\right)^{M_{j}}\right]G_{N}(\vec{x};\beta)\Bigg|_{\vec{x}=0}\\
    =&N(N-1)\cdots (N-l+1)\sum_{(E,\vec{q})\in \tilde{\mathcal{B}}_{\epsilon}(1,\ldots,l)\cap\mathcal{C}}w(E,\vec{q})+C\sqrt{\epsilon} +o(1).
    \end{align*}

