    \[
        \E\left[ \left|\wu_t(x)\right|^2 \right] \le q^2(t, x) + \int_0^t \sum_{y\in\Z} G^2(t-s; y-x) \E\left[ \wu^2_s(y) \right] ds.
    \]
    Therefore we can use symmetry of $G(t; x)$ and Proposition \ref{NonGronwall} and \eqref{eq:h:bound} to obtain
    \begin{align} 
    \begin{split}
        \E\left[ \left|\wu_t(x)\right|^2 \right] &\le q^2(t, x) + (q^2\star h)(t, x) \\
        &\le q^2(t, x) + \int_0^t e^s \sum_{y\in \Z} q^2(t-s, x-y)G^2(s; y) ds.
    \end{split}
    \end{align}
