[Lemma 23 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Let $F_1,F_2$ be two sets such that $F_1 \cap F_2$ is a non-empty finite set. For $i=1,2$, let $(\CE_i,\CF_i)$ be a resistance form on $F_i$, and let $(\CE,\CF)$ be the resistance form on $F_1 \cup F_2$ defined by
 \begin{align*}\begin{split}
  \CF &= \{ f : f|_{F_1} \in \CF_1,\, f|_{F_2} \in \CF_2 \} ,\\
  \CE(f,f) &= \CE_1(f|_{F_1},f|_{F_1})+\CE_2(f|_{F_2},f|_{F_2}) .
 \end{split}\end{align*}
 Then the following holds. Let $A \subseteq F_1 \cup F_2$ be a finite set containing $F_1 \cap F_2$, let $A_i = A \cap F_i$ for $i=1,2$, and let $w_A, w_{A,i}$ be the weight functions associated with $\CE|_A, \CE_i|_{A_i}$, respectively.
 Then
 \[
  w_A(x,y) =
  \begin{cases}
   w_{A,1}(x,y)+w_{A,2}(x,y) ,& x,y \in F_1 \cap F_2 ,\\
   w_{A,1}(x,y) ,& x,y \in F_1 ,\, \{x,y\} \nsubseteq F_1 \cap F_2 ,\\
   w_{A,2}(x,y) ,& x,y \in F_2 ,\, \{x,y\} \nsubseteq F_1 \cap F_2 ,\\
   0 ,& \text{otherwise.}
  \end{cases}
 \]

[Definition 30 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] \textbf{(Brownian snakes)} 
A $q$-dimensional Brownian snake is a r.v. $(H, W)\! :\!  \Omega\!  \rightarrow \! \fSigma_q(\bbR_+)$ that is measurable with respect to $\mathscr F$ and to the Borel $\sigma$-field of $\fSigma_q(\bbR_+)$, such that for all $p\ino \bbN^*$, and all real numbers 
$0\leqo s_1\leko \ldots \leko s_p$, 
\begin{equation}

\big(W_0,W_{\! s_1}, \ldots , W_{\! s_p} \big) \; \overset{\textrm{(law)}}{=} \;  F_p \big( H ; (B^{(j)}) _{0\leq j\leq p}  ;  (s_j)_{1\leq j\leq p} \big)\; , 
\end{equation}
where $B^{(0)}\eqo W_0$, where $(B^{(j)})_{1\leq j\leq p}$ are independent standard $q$-dimensional Brownian motions that are moreover independent from $W_0$ and $H$. \cq

[Lemma 1 (Uniform local and local-maximum bounds) of arXiv:2609.02257, 'Aperiodic random walks: uniform estimates, local limits and invariance principles'] There are constants \(C,c>0\), independent of \(N,L,z,R\), such that
for all sufficiently large \(N\), \(L,R\in\Z_{\ge0}\), and \(z\in\Z\),
\begin{align}
 \Pp(S_N(L)=z)
 &\le \frac{C}{\sqrt{L+1}}
 \exp\left\{-c\frac{z^2}{L+|z|+1}\right\},       \\
 \Pp\left(S_N(L)=z,
       \max_{0\le j\le L}|S_N(j)|\ge R\right)
 &\le \frac{C}{\sqrt{L+1}}
 \exp\left\{-c\frac{R^2}{L+R+1}\right\}.         
\end{align}
Moreover, for some sufficiently large \(N_0\), the uniform lattice
local central limit theorem holds:
\begin{equation}
 \lim_{L\to\infty}\sup_{N\ge N_0}\sup_{z\in\Z}
 \left|
 \sigma_N\sqrt L\,\Pp(S_N(L)=z)
 -\frac1{\sqrt{2\pi}}
  \exp\left\{-\frac{z^2}{2\sigma_N^2L}\right\}
 \right|=0.

\end{equation}

[Definition sub-matrix-block-removal of arXiv:2412.08400, '\vspace{-1.0cm} Characterization of Exponential Families of \\ Lumpable Stochastic Matrice'] Let $F \in \mathcal{F}_\kappa^{+}(\mathcal{Y}, \mathcal{E})$ and a non-degenerate surjective lumping function $\kappa \colon \mathcal{Y} \to \mathcal{X}$.
\begin{description}
    \item[Sub-matrix.] 
    For $\mathcal{T} \subset \mathcal{X}$, we write
\begin{equation*}
\begin{split}
    \mathcal{Y}|_{\mathcal{T}} \triangleq \bigcup_{x \in \mathcal{T}} \mathcal{S}_{x} , \qquad 
    \mathcal{E}|_{\mathcal{T}} \triangleq \mathcal{E} \cap \left( \bigcup_{x,x' \in \mathcal{T}} \mathcal{S}_{x} \times \mathcal{S}_{x'}\right),
\end{split}
\end{equation*}
the resulting sub-graph is  ($\mathcal{Y}|_{\mathcal{T}}, \mathcal{E}|_{\mathcal{T}}$) and the sub-matrix $F|_{\mathcal{T}} \in \mathcal{F}_\kappa^{+}(\mathcal{Y}|_{\mathcal{T}}, \mathcal{E}|_{\mathcal{T}})$ is defined such that for any $(y,y') \in \mathcal{E}|_{\mathcal{T}}$, \begin{equation*}
    F|_{\mathcal{T}}(y,y') = F(y,y').
\end{equation*}
    \item[Block removal.]
    The matrix $F$ from which the block $(x_0, x_0') \in \kappa_2(\mathcal{E})$ has been removed is defined as 
$F^{\setminus (x_0, x_0')}\in \mathcal{F}_\kappa^{+}(\mathcal{Y}, \mathcal{E} \setminus (\mathcal{S}_{x_0} \times \mathcal{S}_{x'_0}))$ where for any $(y,y') \in \mathcal{E} \setminus (\mathcal{S}_{x_0} \times \mathcal{S}_{x'_0})$,
\begin{equation*}
        F^{\setminus (x_0, x_0')}(y,y') = F(y,y').
    \end{equation*}
\end{description}

[Proposition prop:nuptcctty of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $\alpha \in [1/2,1]$,  $g$ be sufficiently small,  $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}$ and $C_{\cD}$ be sufficiently large (independently of $L$).  Then there exists $ \vec\nu_{ptc}  = (\nu^{(\km_1)}_{ptc} )_{\km_1 \in  \kA_0 \cup \kA_1 } $ such that the following hold: with initial condition \begin{align}
	\begin{cases}
		\nu^{(\km_1)}_0  = \nu_{ptc}^{(\km_1)} & (\km_1 \in \kA_0 \cup \kA_1 ) \\
		\nu^{(\km_1)}_0 = g^{(\km_2)}_0  = 0 & (\km_1 \in \kA_2 \cup \kA_3   ,  \; \km_2 \in \kB_1) \\
		g_0^{(\emptyset)} = g  , & {}
	\end{cases}

\end{align}
the bulk perturbative RG flow of infinite length exists,  and $V_j  \in \cD_{j,\varnothing} (\alpha)$ for each $j$.  Moreover,  $\vec{\nu}_{ptc}$ is a continuous function of $\vec{\textbf{a}}$ and differentiable function of $g$ satisfying $\vec{\nu}_{ptc} = O(g)$.

