[Corollary 6 (Unequal-shape asymptotic relative efficiency) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Assume the conditions of \Cref{thm:risk-hessian}. Under an unequal-shape two-component Weibull mixture, suppose the Bayes' rule has two simple decision boundaries $0<y_1<y_2$. For the $\mathrm{full}$ estimator relative to the estimator based on the completely classified sample,
\begin{equation}
\ARE_{\mathrm{full}:\mathrm{CC}}^{\mathrm{U}}
=
\frac{
\displaystyle
\sum_{j=1}^{2}
\omega_j\,
g_U(y_j)^\top
\J_{\mathrm{CC},U}^{-1}
g_U(y_j)
}{
\displaystyle
\sum_{j=1}^{2}
\omega_j\,
g_U(y_j)^\top
\J_{\mathrm{full},U}^{-1}
g_U(y_j)
}.

\end{equation}

[Prop horizontal-splitting-beta-uniform of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $C,c_1,c_2,s_0>0$ (independent of $\beta$) such that for all $\beta>\beta_0$ the following holds. If $R$ is an $\ell \times e^{ - \beta} \bar \alpha \sqrt{\ell}$ rectangle with $\sqrt{C \log \ell} \le\bar \alpha \le (1/ s)\sqrt{\ell}$, and $\Delta$ has length $s \bar \alpha^2$ for $s \ge s_0$, we have 
    \begin{align*}
        \pi^{(-,+,\Delta)}(\mathcal V^c) \le \ell^{c_1} e^{ - c_2 \bar\alpha^2}\,.
    \end{align*}

[Theorem 14 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] Let $G_{\beta}$ be the $\beta$-potential operator, that is,
\begin{align}

  G_{\beta} \mu(x)
  &:= \int_{\mathbb{R}^{d}}^{ } G_{\beta}(x,y) \mu(dy)
    := \int_{\mathbb{R}^{d}}^{ } \left( \int_0^{ \infty} e^{-\beta t} p_{t}(x,y) dt\right) \mu(dy).
\end{align}
  If $\mu \in \mathcal{K}$, then for $\beta \ge 0$, 
  \begin{align}

    \int_{\mathbb{R}^{d}}^{ } u(x)^{2} \mu(dx) \le \left\| G_{\beta} \mu \right\|_{\infty}
    \mathcal{E}_{\beta}^{\alpha}(u,u),\quad u \in \mathcal{F}^{\alpha}\
    (u \in \mathcal{F}_{e}^{\alpha}\ \text{if $\beta = 0$}),
  \end{align}
  where $\mathcal{E}_{\beta}^{\alpha}(u,u)
  = \mathcal{E}^{\alpha}(u,u) + \beta \int_{\mathbb{R}^{d}}^{ } u(x)^{2} dx$. (Proof in the paper; no proof environment follows the statement in the TeX.)
